// Banco consolidado: Guia Por Dentro da B3 (141q) + Apostila Prof. Lucas Silva (700q)
var D=[{"n":1,"tit":"I","titn":"Aspectos institucionais","cap":"I","capn":"Sistema Financeiro Nacional","stem":"Os pilares da estrutura atual do Sistema Financeiro Nacional foram criados pela:","opts":[["a","Lei nº 4.595/1964."],["b","Lei nº 6.385/1976."],["c","Lei nº 6.404/1976."],["d","Lei nº 4.728/1965."]],"ans":"a","exp":"Os pilares da estrutura atual do Sistema Financeiro Nacional foram dados pela Lei nº 4.595/1964, conhecida como a Lei da Reforma Bancária, que criou o Conselho Monetário Nacional (CMN) e o Banco Central do Brasil (Bacen), além de ter estabelecido as normas operacionais e os procedimentos aos quais as demais instituições estariam subordinadas.","pg":46,"banco":"guia"},{"n":2,"tit":"I","titn":"Aspectos institucionais","cap":"I","capn":"Sistema Financeiro Nacional","stem":"O mercado em que se concentram as operações para controle de oferta de moeda e taxas de juro de curto prazo, com o objetivo de garantir a liquidez da economia, é chamado de:","opts":[["a","mercado de crédito."],["b","mercado monetário."],["c","mercado de capitais."],["d","mercado de câmbio."]],"ans":"b","exp":"Mercado monetário é o mercado em que se concentram as operações para controle de oferta de moeda e taxas de juro de curto prazo, com o objetivo de garantir a liquidez da economia.","pg":46,"banco":"guia"},{"n":3,"tit":"I","titn":"Aspectos institucionais","cap":"I","capn":"Sistema Financeiro Nacional","stem":"O órgão responsável pela proteção da captação de poupança popular em investimentos realizados em planos de previdência complementar aberta é:","opts":[["a","o Bacen."],["b","a CVM."],["c","a Susep."],["d","a Previc."]],"ans":"c","exp":"Compete à Susep proteger a captação de poupança popular, realizada por meio de operações de seguro, previdência complementar aberta, capitalização e resseguro.","pg":46,"banco":"guia"},{"n":4,"tit":"I","titn":"Aspectos institucionais","cap":"II","capn":"Infraestrutura do mercado","stem":"O sistema de liquidação que permite que ativos sejam transferidos e liquidados por meio de registros eletrônicos chama-se:","opts":[["a","book entry."],["b","best execution."],["c","electronic shares."],["d","uncertificated shares."]],"ans":"a","exp":"O sistema de liquidação que permite que ativos sejam transferidos e liquidados por meio de registros eletrônicos, de acordo com regras preestabelecidas de compensação, chama-se book entry.","pg":68,"banco":"guia"},{"n":5,"tit":"I","titn":"Aspectos institucionais","cap":"II","capn":"Infraestrutura do mercado","stem":"O regime que busca mitigar conflitos de interesses que possam surgir na execução de ordens dos clientes pelos intermediários, assegurando que essas ordens serão executadas para proporcionar o melhor resultado possível aos clientes é chamado de:","opts":[["a","book entry."],["b","best execution."],["c","electronic shares."],["d","uncertificated shares."]],"ans":"b","exp":"A existência de um regime de best execution busca mitigar conflitos de interesses que possam surgir na execução de ordens dos clientes pelos intermediários, assegurando que essas ordens serão executadas para proporcionar o melhor resultado possível aos clientes e nas melhores condições para estes, mesmo existindo mais de um sistema de negociação e uma eventual divergência, ainda que temporária, entre os preços praticados em cada sistema.","pg":68,"banco":"guia"},{"n":6,"tit":"I","titn":"Aspectos institucionais","cap":"II","capn":"Infraestrutura do mercado","stem":"O processo pelo qual uma contraparte central se interpõe entre as contrapartes originais de contratos negociados, tornando-se o comprador de todos os vendedores e o vendedor de todos os compradores, é chamado de:","opts":[["a","desmaterialização."],["b","liquidação diferida."],["c","novação."],["d","liquidação bruta."]],"ans":"c","exp":"Uma contraparte central se interpõe entre as contrapartes originais de contratos negociados, tornando-se o comprador de todos os vendedores e o vendedor de todos os compradores, por meio do processo de novação ou por meio de um instituto legal equivalente.","pg":68,"banco":"guia"},{"n":7,"tit":"I","titn":"Aspectos institucionais","cap":"III","capn":"A B3 no mercado financeiro e de capitais","stem":"A _____ é uma infraestrutura de mercado que desempenha um papel fundamental na preservação da integridade dos ativos sob sua guarda e na proteção dos investidores em relação à propriedade desses ativos e direitos que deles se originam.","opts":[["a","câmara de compensação."],["b","central de registro."],["c","Câmara de Câmbio."],["d","central depositária."]],"ans":"d","exp":"A central depositária é uma infraestrutura de mercado que desempenha um papel fundamental na preservação da integridade dos ativos sob sua guarda e na proteção dos investidores em relação à propriedade desses ativos e direitos que deles se originam.","pg":93,"banco":"guia"},{"n":8,"tit":"I","titn":"Aspectos institucionais","cap":"III","capn":"A B3 no mercado financeiro e de capitais","stem":"O participante de negociação é aquele que atua para seus clientes por meio de um _____, que tem acesso direto ao sistema de negociação da B3.","opts":[["a","membro de compensação."],["b","participante de negociação pleno (PNP)."],["c","participante de liquidação."],["d","banco de investimento."]],"ans":"b","exp":"O participante de negociação é aquele que atua para seus clientes por meio de um participante de negociação pleno (PNP), que tem acesso direto ao sistema de negociação da B3.","pg":93,"banco":"guia"},{"n":9,"tit":"I","titn":"Aspectos institucionais","cap":"III","capn":"A B3 no mercado financeiro e de capitais","stem":"_____ é o nome do mecanismo que analisa e julga as reclamações dirigidas ao mercado para o ressarcimento de prejuízos. Ele é mantido pela B3 e administrado pela BSM, para assegurar a todos os investidores o ressarcimento de até R$ 200 mil por prejuízos, em cada ocorrência.","opts":[["a","BSM."],["b","MRP."],["c","PAD."],["d","RPB3."]],"ans":"b","exp":"O MRP, mantido pela B3 e administrado pela BSM, assegura a todos os investidores o ressarcimento de até R$ 200 mil por prejuízos, comprovadamente, causados por erros ou omissões de participantes dos mercados administrados pela B3 (corretoras e distribuidoras de títulos e valores mobiliários), seus administradores ou prepostos, em relação à intermediação de operações de bolsa com valores mobiliários (como compra e venda de ações, derivativos e fundos listados) e serviços de custódia. O ressarcimento é devido para cada ocorrência.","pg":93,"banco":"guia"},{"n":10,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"I","capn":"Mercado de renda variável","stem":"Além da distribuição de dividendos, a empresa pode remunerar seus acionistas por meio de:","opts":[["a","juros sobre o capital próprio."],["b","rendimentos fixos."],["c","rendimentos variáveis."],["d","ganho de capital."]],"ans":"a","exp":"Além da distribuição de dividendos, a empresa pode remunerar seus acionistas por meio de pagamento de juros sobre o capital próprio, com base em reservas patrimoniais de lucros retidos em exercícios anteriores.","pg":160,"banco":"guia"},{"n":11,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"I","capn":"Mercado de renda variável","stem":"O índice Ibovespa é um índice de:","opts":[["a","retorno total ponderado por pesos iguais."],["b","retorno total ponderado por capitalização de mercado."],["c","retorno total ponderado por pesos diferenciados."],["d","retorno total ponderado por liquidez."]],"ans":"d","exp":"O índice Ibovespa é um índice de retorno total ponderado por liquidez.","pg":160,"banco":"guia"},{"n":12,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"I","capn":"Mercado de renda variável","stem":"A decisão de emitir BDR Nível I Não Patrocinado (BDR NP N1) parte de uma instituição depositária estabelecida no Brasil, que solicita o registro do programa à CVM e à B3,","opts":[["a","com envolvimento da empresa estrangeira emissora do lastro dos BDRs."],["b","sem envolvimento da empresa estrangeira emissora do lastro dos BDRs."],["c","com participação das bolsas estrangeiras."],["d","com empresas sediadas em qualquer país."]],"ans":"b","exp":"A decisão de emitir BDR Nível I Não Patrocinado (BDR NP N1) parte de uma instituição depositária estabelecida no Brasil, que solicita o registro do programa à CVM e à B3, sem envolvimento da empresa estrangeira emissora do lastro dos BDRs.","pg":160,"banco":"guia"},{"n":13,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"II","capn":"Mercado de derivativos","stem":"O _____ é uma operação realizada no mercado de balcão, na qual dois agentes acertam, na data zero, a cotação pela qual liquidarão a operação de câmbio entre duas moedas na data do vencimento do contrato.","opts":[["a","contrato futuro de moedas."],["b","contrato a termo de moedas."],["c","contrato futuro de dólar."],["d","contrato a termo de mercadorias."]],"ans":"b","exp":"O contrato a termo de moedas é uma operação realizada no mercado de balcão, na qual dois agentes acertam, na data zero, a cotação pela qual liquidarão a operação de câmbio entre duas moedas na data do vencimento do contrato.","pg":244,"banco":"guia"},{"n":14,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"II","capn":"Mercado de derivativos","stem":"Os participantes do mercado de derivativos são:","opts":[["a","o hedger e o especulador."],["b","o hedger e o arbitrador."],["c","o hedger, o arbitrador e o especulador."],["d","o arbitrador e o especulador."]],"ans":"c","exp":"Os participantes do mercado de derivativos são o hedger, o arbitrador e o especulador.","pg":244,"banco":"guia"},{"n":15,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"II","capn":"Mercado de derivativos","stem":"O contrato futuro de DDI negocia o cupom cambial chamado de:","opts":[["a","cupom limpo."],["b","cupom sintético."],["c","cupom a termo."],["d","cupom sujo."]],"ans":"d","exp":"O contrato futuro de DDI negocia o cupom cambial chamado de cupom sujo.","pg":244,"banco":"guia"},{"n":16,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"III","capn":"Mercado de renda fixa","stem":"Em parceria com o Tesouro Nacional, a B3 operacionaliza o sistema _____, por meio do qual investidores (pessoa física) podem adquirir títulos públicos federais disponibilizados diretamente pelo Tesouro Nacional.","opts":[["a","Selic."],["b","Tesouro Direto."],["c","Cetip."],["d","Puma."]],"ans":"b","exp":"Em parceria com o Tesouro Nacional, a B3 operacionaliza o sistema Tesouro Direto, por meio do qual investidores (pessoa física) podem adquirir títulos públicos federais disponibilizados diretamente pelo Tesouro Nacional.","pg":277,"banco":"guia"},{"n":17,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"III","capn":"Mercado de renda fixa","stem":"Quanto _____ a duration, _____ é o período de tempo para o investidor recuperar o valor investido e _____ é a exposição ao risco.","opts":[["a","maior; maior; menor."],["b","maior; maior; maior."],["c","maior; menor; maior."],["d","maior; menor; menor."]],"ans":"b","exp":"Quanto maior a duration, maior é o período de tempo para o investidor recuperar o valor investido e maior é a exposição ao risco","pg":277,"banco":"guia"},{"n":18,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"III","capn":"Mercado de renda fixa","stem":"É um título de crédito nominativo, de livre negociação, representativo de promessa de pagamento em dinheiro emitido com base em lastro de recebíveis originados de negócios entre produtores rurais.","opts":[["a","CRI."],["b","CDB."],["c","LTN."],["d","CRA."]],"ans":"d","exp":"O Certificado de Recebíveis do Agronegócio (CRA) é um título de crédito nominativo, de livre negociação, representativo de promessa de pagamento em dinheiro emitido com base em lastro de recebíveis originados de negócios entre produtores rurais.","pg":277,"banco":"guia"},{"n":19,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"IV","capn":"Mercado de câmbio","stem":"A Câmara de Câmbio adota o modelo de pagamento contra pagamento. As operações podem ser liquidadas em:","opts":[["a","D+0 ou D+1."],["b","D+1 ou D+2."],["c","D+0, D+1 ou D+2."],["d","D+0."]],"ans":"c","exp":"A Câmara de Câmbio adota o modelo de pagamento contra pagamento. As operações podem ser liquidadas em D+0 (no mesmo dia), D+1 ou D+2, de acordo com a escolha das partes envolvidas.","pg":296,"banco":"guia"},{"n":20,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"IV","capn":"Mercado de câmbio","stem":"A plataforma eletrônica da B3 que permite a negociação de dólar pronto chama-se:","opts":[["a","Puma Trading System."],["b","Sisbex."],["c","BovespaFix."],["d","Tradenet."]],"ans":"a","exp":"A plataforma eletrônica da B3 Puma Trading System permite a negociação de dólar pronto.","pg":296,"banco":"guia"},{"n":21,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"IV","capn":"Mercado de câmbio","stem":"As taxas _____ de compra e de venda correspondem, respectivamente, às médias aritméticas das taxas de compra e de venda das consultas realizadas diariamente.","opts":[["a","PTAX."],["b","PCAM."],["c","Reuters."],["d","Taxa B3."]],"ans":"a","exp":"As taxas PTAX de compra e de venda correspondem, respectivamente, às médias aritméticas das taxas de compra e de venda das consultas realizadas diariamente.","pg":296,"banco":"guia"},{"n":22,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"V","capn":"Fundos de investimento","stem":"A menor fração do patrimônio líquido de um fundo de investimento é chamada de:","opts":[["a","valor de emissão."],["b","cota."],["c","valor financeiro."],["d","quantidade."]],"ans":"b","exp":"A cota é a fração do patrimônio líquido de um fundo de investimento utilizada como referência para a realização de aplicações e resgates.","pg":325,"banco":"guia"},{"n":23,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"V","capn":"Fundos de investimento","stem":"Fundos constituídos por prazo indeterminado, nos quais as aplicações e os resgates podem ser feitos a qualquer momento, são chamados de:","opts":[["a","fundos fechados."],["b","fundos exclusivos."],["c","fundos abertos."],["d","fundos ativos."]],"ans":"c","exp":"Fundos abertos são condomínios constituídos por prazo indeterminado, nos quais as aplicações e os resgates podem ser feitos a qualquer momento.","pg":325,"banco":"guia"},{"n":24,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"V","capn":"Fundos de investimento","stem":"O fundo de investimento em índice com cotas negociáveis em bolsa como se fossem ações é chamado de:","opts":[["a","Fundo de renda fixa."],["b","Fundo de ações."],["c","Fundo imobiliário."],["d","Exchange traded fund (ETF)."]],"ans":"d","exp":"Exchange traded fund (ETF) é um fundo de investimento em índice, com cotas negociáveis em bolsa, como se fossem ações.","pg":325,"banco":"guia"},{"n":25,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"VI","capn":"Clubes de investimento","stem":"A menor fração do patrimônio de um clube de investimento é chamada de:","opts":[["a","valor de emissão."],["b","cota."],["c","valor financeiro."],["d","quantidade."]],"ans":"b","exp":"A menor fração do patrimônio de um clube de investimento é chamada de cota.","pg":335,"banco":"guia"},{"n":26,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"VI","capn":"Clubes de investimento","stem":"A entidade responsável pelo registro dos clubes de investimento é:","opts":[["a","a B3."],["b","a CVM."],["c","o Bacen."],["d","a BSM."]],"ans":"a","exp":"A entidade responsável pelo registro dos clubes de investimento é a B3.","pg":335,"banco":"guia"},{"n":27,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"VI","capn":"Clubes de investimento","stem":"A distribuição de cotas de clube de investimento por meio de serviços públicos de comunicação é algo:","opts":[["a","permitido."],["b","vedado."],["c","permitido com ressalvas."],["d","vedado com ressalvas."]],"ans":"b","exp":"A distribuição de cotas por meio de serviços públicos de comunicação é algo vedado. Exemplos desses meios são a imprensa, o rádio, a televisão e as páginas abertas ao público na rede mundial de computadores. Também é vedado o envio de malas diretas, inclusive por correio eletrônico.","pg":335,"banco":"guia"},{"n":28,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"VII","capn":"Outros ativos e serviços","stem":"A versão brasileira das Notas Estruturadas é chamada de:","opts":[["a","COE."],["b","LIG."],["c","vendor."],["d","CDB."]],"ans":"a","exp":"A versão brasileira das Notas Estruturadas é chamada de COE – Certificado de Operações Estruturadas.","pg":353,"banco":"guia"},{"n":29,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"VII","capn":"Outros ativos e serviços","stem":"Os Certificados de Potencial Adicional de Construção (Cepacs) são valores mobiliários emitidos _____ e utilizados como meio de pagamento de contrapartida para a outorga de direito urbanístico adicional dentro do perímetro de uma operação urbana consorciada.","opts":[["a","pela União."],["b","pelas prefeituras."],["c","pelos estados."],["d","pelas empresas."]],"ans":"b","exp":"Os Certificados de Potencial Adicional de Construção (Cepacs) são valores mobiliários emitidos pelas prefeituras e utilizados como meio de pagamento de contrapartida para a outorga de direito urbanístico adicional dentro do perímetro de uma operação urbana consorciada.","pg":353,"banco":"guia"},{"n":30,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"VII","capn":"Outros ativos e serviços","stem":"O serviço que envia, em tempo real, para qualquer lugar do mundo, informações geradas pela bolsa e notícias econômicas sobre o mercado de ações e derivativos é chamado de:","opts":[["a","vendor."],["b","gestão de garantias."],["c","market data."],["d","Cepac."]],"ans":"c","exp":"O market data, da B3, é um serviço que envia, em tempo real, para qualquer lugar do mundo, informações geradas pela bolsa e notícias econômicas sobre o mercado de ações e derivativos.","pg":353,"banco":"guia"},{"n":31,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"VIII","capn":"Tributação do mercado financeiro","stem":"Nas operações de renda fixa com prazo menor que 30 dias, incide:","opts":[["a","IOF e, em seguida, IRF."],["b","IRF e, em seguida, IOF."],["c","apenas IOF."],["d","apenas IRF."]],"ans":"a","exp":"Nas operações de renda fixa com prazo menor que 30 dias, incide IOF e, em seguida, IRF.","pg":395,"banco":"guia"},{"n":32,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"VIII","capn":"Tributação do mercado financeiro","stem":"São isentos do imposto sobre a renda ou tributados à alíquota 0%, quando auferidos por pessoa física, os rendimentos auferidos por:","opts":[["a","depósitos de poupança e certificados de depósito bancário."],["b","certificados de depósito bancário e letras hipotecárias."],["c","certificados de recebíveis imobiliários e letras de crédito imobiliário."],["d","certificados de depósito bancário e letras de crédito imobiliário."]],"ans":"c","exp":"São isentos do imposto sobre a renda ou tributados à alíquota 0%, quando auferidos por pessoa física, os rendimentos auferidos por certificados de recebíveis imobiliários e letras de crédito imobiliário.","pg":395,"banco":"guia"},{"n":33,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"VIII","capn":"Tributação do mercado financeiro","stem":"No caso do Imposto de Renda, estão sujeitos a um regime especial de tributação os investidores:","opts":[["a","não residentes no Brasil que não sejam domiciliados em paraísos fiscais."],["b","não residentes no Brasil que sejam domiciliados em paraísos fiscais."],["c","não residentes no Brasil, sejam domiciliados em paraísos fiscais ou não."],["d","residentes e não residentes no Brasil."]],"ans":"a","exp":"No caso do Imposto de Renda, estão sujeitos a um regime especial de tributação os investidores não residentes no Brasil que não sejam domiciliados em paraísos fiscais.","pg":395,"banco":"guia"},{"n":34,"tit":"III","titn":"Estrutura de contas e cadastro","cap":"I","capn":"Cadastro de investidores residentes","stem":"De acordo com a regulamentação em vigor, as centrais depositárias devem manter sistema centralizado de cadastro de investidores e estruturas de contas de depósito em nome:","opts":[["a","da corretora de valores."],["b","do banco custodiante."],["c","do beneficiário final das transações."],["d","do sistema de custódia."]],"ans":"c","exp":"De acordo com a regulamentação em vigor, as centrais depositárias devem manter sistema centralizado de cadastro de investidores e estruturas de contas de depósito em nome do beneficiário final das transações ocorridas no mercado de capitais.","pg":411,"banco":"guia"},{"n":35,"tit":"III","titn":"Estrutura de contas e cadastro","cap":"I","capn":"Cadastro de investidores residentes","stem":"De acordo com a regulamentação em vigor, os investidores serão identificados:","opts":[["a","no momento em que a operação for realizada em seu nome."],["b","no momento em que a operação for realizada em nome da corretora."],["c","no momento da liquidação da operação."],["d","no momento do registro da operação na conta máster."]],"ans":"a","exp":"De acordo com a regulamentação em vigor, os investidores serão identificados no momento em que a operação for realizada em seu nome.","pg":411,"banco":"guia"},{"n":36,"tit":"III","titn":"Estrutura de contas e cadastro","cap":"I","capn":"Cadastro de investidores residentes","stem":"O repasse entre contas é feito:","opts":[["a","entre dois PNP, quando houver contrato específico entre as partes e desde que exista um vínculo de repasse entre eles."],["b","entre dois PNP ou entre um PNP e um PL, quando houver contrato específico entre as partes."],["c","entre dois PNP, desde que exista um vínculo de repasse entre eles."],["d","entre dois PNP ou entre um PNP e um PL, quando houver contrato específico entre as partes e desde que exista um vínculo de repasse entre eles."]],"ans":"d","exp":"O repasse de operações é feito entre dois PNP ou entre um PNP e um PL, quando houver contrato específico entre as partes e desde que exista um vínculo de repasse entre eles.","pg":411,"banco":"guia"},{"n":37,"tit":"III","titn":"Estrutura de contas e cadastro","cap":"II","capn":"Cadastro de investidores não residentes","stem":"A Comissão de Valores Mobiliários (CVM), o Banco Central do Brasil (Bacen), o Conselho Monetário Nacional (CMN) e a própria B3 estabelecem normas e procedimentos relativos ao cadastramento para _____, que desejam atuar no mercado financeiro do Brasil.","opts":[["a","investidores residentes e domiciliados."],["b","investidores residentes e não residentes."],["c","investidores não residentes."],["d","investidores residentes e não domiciliados."]],"ans":"b","exp":"A Comissão de Valores Mobiliários (CVM), o Banco Central do Brasil (Bacen), o Conselho Monetário Nacional (CMN) e a própria B3 estabelecem normas e procedimentos relativos ao cadastramento para investidores residentes e não residentes, que desejam atuar no mercado financeiro do Brasil.","pg":420,"banco":"guia"},{"n":38,"tit":"III","titn":"Estrutura de contas e cadastro","cap":"II","capn":"Cadastro de investidores não residentes","stem":"Em linhas gerais, a Resolução Conjunta BACEN/CVM nº 13/2024 dá acesso ao investidor não residente:","opts":[["a","aos mesmos mercados disponíveis ao investidor residente."],["b","a mercados específicos."],["c","apenas ao mercado de juros."],["d","apenas ao mercado de ações."]],"ans":"a","exp":"Em linhas gerais, a Resolução Conjunta BACEN/CVM nº 13/2024 dá acesso ao investidor não residente aos mesmos mercados disponíveis ao investidor residente, havendo a necessidade de o investidor ser registrado no Brasil e internalizar recursos, em moeda local, mediante contratação de operações de câmbio.","pg":420,"banco":"guia"},{"n":39,"tit":"III","titn":"Estrutura de contas e cadastro","cap":"II","capn":"Cadastro de investidores não residentes","stem":"O responsável por realizar o registro na CVM em nome do investidor não residente é o:","opts":[["a","responsável fiscal."],["b","representante legal."],["c","custodiante."],["d","o investidor."]],"ans":"b","exp":"O representante legal é responsável por realizar o registro na CVM.","pg":420,"banco":"guia"},{"n":40,"tit":"IV","titn":"Gestão de risco","cap":"I","capn":"Gestão de risco na Câmara","stem":"O risco de perdas em decorrência da variação do preço dos ativos e contratos em valor superior ao das garantias é chamado de:","opts":[["a","risco de mercado."],["b","risco de crédito."],["c","risco de liquidez."],["d","risco operacional."]],"ans":"a","exp":"O risco de perdas em decorrência da variação do preço dos ativos e contratos em valor superior ao das garantias é chamado de risco de mercado.","pg":457,"banco":"guia"},{"n":41,"tit":"IV","titn":"Gestão de risco","cap":"I","capn":"Gestão de risco na Câmara","stem":"A B3 assume a posição de contraparte central para fins de liquidação das obrigações resultantes de operações por ela aceitas para compensação e liquidação, exclusivamente em relação:","opts":[["a","aos participantes de negociação pleno (PNP)."],["b","aos participantes de liquidação (PL)."],["c","aos membros de compensação (MC)."],["d","aos comitentes."]],"ans":"c","exp":"A B3 assume a posição de contraparte central para fins de liquidação das obrigações resultantes de operações por ela aceitas para compensação e liquidação, exclusivamente em relação aos membros de compensação.","pg":457,"banco":"guia"},{"n":42,"tit":"IV","titn":"Gestão de risco","cap":"I","capn":"Gestão de risco na Câmara","stem":"A componente da estrutura de salvaguardas cujos recursos só podem ser usados em caso de inadimplência do participante contribuinte é chamada de:","opts":[["a","survivor pays."],["b","defaulter pays."],["c","third parties pay."],["d","modelo integrado."]],"ans":"b","exp":"A componente da estrutura de salvaguardas cujos recursos só podem ser usados em caso de inadimplência do participante contribuinte é chamada de defaulter pays.","pg":457,"banco":"guia"},{"n":43,"tit":"IV","titn":"Gestão de risco","cap":"II","capn":"Risco corporativo e controles internos","stem":"A gestão operacional está relacionada a que linha de defesa?","opts":[["a","Introdutória."],["b","Primeira linha de defesa."],["c","Segunda linha de defesa."],["d","Terceira linha de defesa."]],"ans":"b","exp":"A primeira linha de defesa corresponde à gestão operacional e está relacionada à ação do próprio funcionário que executa determinado processo ou função.","pg":484,"banco":"guia"},{"n":44,"tit":"IV","titn":"Gestão de risco","cap":"II","capn":"Risco corporativo e controles internos","stem":"Sobre a segunda linha de defesa de controles internos das instituições participantes, pode-se afirmar que:","opts":[["a","Trata-se da área que é dona, de fato, do risco daquele negócio."],["b","É desempenhada pela auditoria interna."],["c","Tem a função de averiguar se o risco chegou a se materializar."],["d","Avalia se os controles implementados estão funcionando adequadamente para prevenir o risco."]],"ans":"d","exp":"A segunda linha de defesa é desempenhada pela área de controles internos da organização. A principal função dessa área é avaliar se os controles implementados estão funcionando adequadamente para prevenir o risco. Ela não está necessariamente preocupada em averiguar se o risco chegou a se materializar alguma vez, mas sim se o mecanismo empregado para impedir que ele se materialize é eficaz.","pg":484,"banco":"guia"},{"n":45,"tit":"IV","titn":"Gestão de risco","cap":"II","capn":"Risco corporativo e controles internos","stem":"A negociação excessiva ou giro excessivo da carteira do investidor com o único objetivo de gerar maior corretagem é chamada de:","opts":[["a","churning."],["b","front running."],["c","insider trading."],["d","framing."]],"ans":"a","exp":"Churning é a negociação excessiva ou giro excessivo da carteira do investidor com o único objetivo de gerar maior corretagem.","pg":484,"banco":"guia"},{"n":46,"tit":"V","titn":"Negociação","cap":"I","capn":"Mercados organizados","stem":"Os titulares de uma opção de estilo americano:","opts":[["a","poderão exercê-la, mas não a qualquer tempo."],["b","poderão exercê-la, a qualquer tempo, a partir do pregão seguinte ao de sua aquisição, até a data de seu vencimento."],["c","poderão exercê-la somente na data de vencimento."],["d","poderão exercê-la em D+2."]],"ans":"b","exp":"Os titulares de opção de estilo americano poderão exercê-la, a qualquer tempo, a partir do pregão seguinte ao de sua aquisição, até a data de seu vencimento.","pg":503,"banco":"guia"},{"n":47,"tit":"V","titn":"Negociação","cap":"I","capn":"Mercados organizados","stem":"Os contratos futuros possuem estrutura previamente padronizada por regulamentação de bolsa, estabelecendo todas as características do produto negociado, tais como:","opts":[["a","cotação e quantidade máxima."],["b","liquidação bruta e data de vencimento."],["c","qualquer data de vencimento."],["d","cotação, data de vencimento e tipo de liquidação."]],"ans":"d","exp":"Os contratos futuros possuem estrutura previamente padronizada por regulamentação de bolsa, estabelecendo todas as características do produto negociado, tais como cotação, data de vencimento e tipo de liquidação.","pg":503,"banco":"guia"},{"n":48,"tit":"V","titn":"Negociação","cap":"I","capn":"Mercados organizados","stem":"A obrigação exigida de um lançador de uma opção de venda é que ele:","opts":[["a","empreste ao titular da opção, até uma data prefixada, um lote padrão de determinado ativo a um preço previamente estipulado."],["b","compre do titular da opção, até uma data prefixada, um lote padrão de determinado ativo a um preço previamente estipulado."],["c","vende ao titular da opção, até uma data prefixada, um lote padrão de determinado ativo a um preço previamente estipulado."],["d","Não há nenhuma obrigação."]],"ans":"b","exp":"A obrigação exigida de um lançador de uma opção de venda é que ele compre do titular da opção, até uma data prefixada, um lote padrão de determinado ativo a um preço previamente estipulado.","pg":503,"banco":"guia"},{"n":49,"tit":"V","titn":"Negociação","cap":"II","capn":"Ambiente de negociação","stem":"Compete _____, dentro de sua esfera de atuação, apurar e punir as infrações dispostas no Regulamento de Negociação da B3, nas normas que o complementam ou na legislação em vigor, aplicando, conforme o caso, as penalidades previstas em seu estatuto social, na forma de seu regulamento processual.","opts":[["a","à B3."],["b","à BSM."],["c","à CVM."],["d","ao Bacen."]],"ans":"b","exp":"Compete à BSM, dentro de sua esfera de atuação, apurar e punir as infrações dispostas no regulamento de negociação da B3, nas normas que o complementam ou na legislação em vigor, aplicando, conforme o caso, as penalidades previstas em seu estatuto social, na forma de seu regulamento processual.","pg":541,"banco":"guia"},{"n":50,"tit":"V","titn":"Negociação","cap":"II","capn":"Ambiente de negociação","stem":"O procedimento operacional que interrompe a negociação de ativos e demais valores mobiliários em momentos atípicos de mercado, em que há excessiva volatilidade, é chamado de:","opts":[["a","circuit breaker."],["b","after-hours."],["c","co-location."],["d","STP."]],"ans":"a","exp":"O circuit breaker é o procedimento operacional que interrompe a negociação de ativos e demais valores mobiliários em momentos atípicos de mercado, em que há excessiva volatilidade.","pg":541,"banco":"guia"},{"n":51,"tit":"V","titn":"Negociação","cap":"II","capn":"Ambiente de negociação","stem":"O participante cadastrado que tem suas ordens transmitidas ao ambiente de negociação por meio do registro de ofertas é chamado de:","opts":[["a","PNP."],["b","PN."],["c","comitente."],["d","formador de mercado."]],"ans":"c","exp":"O comitente é um participante cadastrado que tem suas ordens transmitidas ao ambiente de negociação por meio do registro de ofertas e suas operações próprias realizadas no ambiente de negociação, por sua conta e ordem, por intermédio e responsabilidade de um participante de negociação pleno ou participante de negociação.","pg":541,"banco":"guia"},{"n":52,"tit":"VI","titn":"Câmara de compensação e liquidação","cap":"I","capn":"Câmara B3","stem":"Que participante utiliza sua conta reservas bancárias ou conta de liquidação para efetuar ou receber os pagamentos referentes aos processos de liquidação com a câmara?","opts":[["a","O participante de liquidação."],["b","O banco liquidante."],["c","O participante de negociação."],["d","O membro de compensação."]],"ans":"b","exp":"Liquidante (ou banco liquidante) é o participante que utiliza sua conta reservas bancárias ou conta de liquidação para efetuar ou receber os pagamentos referentes aos processos de liquidação dos membros de compensação (MC) com a câmara.","pg":567,"banco":"guia"},{"n":53,"tit":"VI","titn":"Câmara de compensação e liquidação","cap":"I","capn":"Câmara B3","stem":"A Câmara B3 assume a posição de contraparte central na liquidação, exclusivamente, perante o:","opts":[["a","comitente."],["b","participante de negociação."],["c","participante de liquidação."],["d","membro de compensação."]],"ans":"d","exp":"A Câmara B3 assume a posição de contraparte central na liquidação, exclusivamente, perante o membro de compensação.","pg":567,"banco":"guia"},{"n":54,"tit":"VI","titn":"Câmara de compensação e liquidação","cap":"I","capn":"Câmara B3","stem":"O participante que não efetuar a liquidação de sua obrigação, na forma estabelecida pela câmara, em decorrência de insuficiência financeira, poderá ser declarado:","opts":[["a","insolvente."],["b","concordatário."],["c","inadimplente."],["d","devedor operacional."]],"ans":"c","exp":"O participante que não efetuar a liquidação de sua obrigação, na forma estabelecida pela câmara, em decorrência de insuficiência financeira, poderá ser declarado inadimplente.","pg":567,"banco":"guia"},{"n":55,"tit":"VI","titn":"Câmara de compensação e liquidação","cap":"II","capn":"Processos operacionais da Câmara B3","stem":"As operações de compra e de venda de um mesmo ativo, realizadas em uma mesma data de negociação, por um mesmo participante e em uma mesma conta de posição são consideradas, pela câmara,","opts":[["a","day trade."],["b","swing trade."],["c","front runner."],["d","spot."]],"ans":"a","exp":"A câmara considera day trade as operações de compra e de venda de um mesmo ativo, realizadas em uma mesma data de negociação, por um mesmo participante e em uma mesma conta de posição.","pg":599,"banco":"guia"},{"n":56,"tit":"VI","titn":"Câmara de compensação e liquidação","cap":"II","capn":"Processos operacionais da Câmara B3","stem":"As modalidades das operações registradas nos ambientes de registro podem ser realizadas","opts":[["a","com garantia e sem garantia."],["b","com garantia, sem garantia e com garantia parcial."],["c","apenas sem garantia."],["d","apenas com garantia."]],"ans":"b","exp":"As modalidades das operações registradas nos ambientes de registro podem ser realizadas com garantia, sem garantia e com garantia parcial.","pg":599,"banco":"guia"},{"n":57,"tit":"VI","titn":"Câmara de compensação e liquidação","cap":"II","capn":"Processos operacionais da Câmara B3","stem":"A modalidade de operação em que a câmara não atua como contraparte central de nenhuma das partes da operação, mas operacionaliza o processo de liquidação é chamada de:","opts":[["a","com garantia."],["b","com garantia parcial."],["c","sem garantia parcial."],["d","sem garantia com liquidação bruta."]],"ans":"d","exp":"A modalidade de operação em que a câmara não atua como contraparte central de nenhuma das partes da operação, mas operacionaliza o processo de liquidação é chamada de sem garantia com liquidação bruta.","pg":599,"banco":"guia"},{"n":58,"tit":"VII","titn":"Central depositária","cap":"I","capn":"Central depositária da B3","stem":"Os custos e encargos cobrados pela B3 estão descritos em sua política de tarifação, que é divulgada:","opts":[["a","por comunicado."],["b","por meio de ofício circular."],["c","por informe ao mercado."],["d","pelos membros de compensação."]],"ans":"b","exp":"Os custos e encargos cobrados pela B3 estão descritos em sua política de tarifação, que é divulgada por meio de ofício circular.","pg":614,"banco":"guia"},{"n":59,"tit":"VII","titn":"Central depositária","cap":"I","capn":"Central depositária da B3","stem":"Conforme estabelecido em sua _____ e demais normas relacionadas, a B3 garante a continuidade de suas atividades em caso de desastre no centro de processamento de dados principal, possuindo unidade de contingência externa, conforme a legislação em vigor.","opts":[["a","política de continuidade de negócios."],["b","política de tarifação."],["c","política de processamento de dados."],["d","política de contingência."]],"ans":"a","exp":"Conforme estabelecido em sua política de continuidade de negócios e demais normas relacionadas, a B3 garante a continuidade de suas atividades em caso de desastre no centro de processamento de dados principal, possuindo unidade de contingência externa, conforme a legislação em vigor.","pg":614,"banco":"guia"},{"n":60,"tit":"VII","titn":"Central depositária","cap":"I","capn":"Central depositária da B3","stem":"É o participante detentor de autorização de acesso para custódia perante a central depositária da B3.","opts":[["a","Sistema externo."],["b","emissor."],["c","escriturador."],["d","agente de custódia."]],"ans":"d","exp":"O agente de custódia é o participante detentor de autorização de acesso para custódia perante a central depositária da B3.","pg":614,"banco":"guia"},{"n":61,"tit":"VII","titn":"Central depositária","cap":"II","capn":"Processos operacionais da central depositária da B3","stem":"A central depositária da B3 oferece um serviço disponível em seu endereço eletrônico denominado:","opts":[["a","Serviço de Atendimento ao Investidor."],["b","Área do Investidor."],["c","Consulta de Participantes."],["d","Extrato Eletrônico."]],"ans":"b","exp":"A central depositária da B3 oferece um serviço disponível em seu endereço eletrônico denominado Área do Investidor.","pg":630,"banco":"guia"},{"n":62,"tit":"VII","titn":"Central depositária","cap":"II","capn":"Processos operacionais da central depositária da B3","stem":"As contas de depósito são identificadas e numeradas _____, sendo divididas em carteiras com características e finalidades específicas.","opts":[["a","por agente de custódia."],["b","por comitente."],["c","por agente de custódia e por comitente."],["d","por agente de custódia e por comitente e conta de ativos."]],"ans":"c","exp":"As contas de depósito são identificadas e numeradas por agente de custódia e por comitente, sendo divididas em carteiras com características e finalidades específicas.","pg":630,"banco":"guia"},{"n":63,"tit":"VII","titn":"Central depositária","cap":"II","capn":"Processos operacionais da central depositária da B3","stem":"O serviço de guarda centralizada de ativos da central depositária da B3 consiste no controle dos saldos dos ativos, bem como das respectivas movimentações de ativos, em forma:","opts":[["a","escritural, por meio de registros eletrônicos."],["b","digital, por meio de registros eletrônicos."],["c","física."],["d","de controle de títulos fungíveis."]],"ans":"a","exp":"O serviço de guarda centralizada de ativos da central depositária da B3 consiste, sobretudo, no controle dos saldos dos ativos, bem como das respectivas movimentações de ativos, em forma escritural, por meio de registros eletrônicos.","pg":630,"banco":"guia"},{"n":64,"tit":"VIII","titn":"Compliance","cap":"I","capn":"Prevenção à lavagem de dinheiro, ao financiamento do terrorismo e ao financiamento da proliferação de armas de destruição em massa","stem":"Os clientes classificados como PEP:","opts":[["a","Devem ter tratamento específico no âmbito de PLD/FTP."],["b","Deve ser tratado como os demais por força da vedação à discriminação."],["c","Devem ter seu cadastro recusado."],["d","Devem ter todas suas operações informadas ao Coaf."]],"ans":"a","exp":"Os clientes classificados como PEP devem ter tratamento específico no âmbito de PLD/FTP.","pg":644,"banco":"guia"},{"n":65,"tit":"VIII","titn":"Compliance","cap":"I","capn":"Prevenção à lavagem de dinheiro, ao financiamento do terrorismo e ao financiamento da proliferação de armas de destruição em massa","stem":"Considera-se cliente ativo aquele que:","opts":[["a","nos últimos 12 (doze) meses tenha: efetuado movimentação de sua conta-corrente ou posição de custódia, realizado operação no mercado de valores mobiliários; ou apresentado saldo e sua posição de custódia."],["b","nos últimos 18 (dezoito) meses tenha: efetuado movimentação de sua conta-corrente ou posição de custódia, realizado operação no mercado de valores mobiliários; ou apresentado saldo e sua posição de custódia."],["c","nos últimos 12 (doze) meses tenha: efetuado movimentação de sua conta-corrente."],["d","nos últimos 18 (dezoito) meses tenha: efetuado movimentação de sua conta-corrente ou posição de custódia, realizado operação de day trade."]],"ans":"a","exp":"O cliente é considerado ativo, desde que, nos últimos 12 meses, tenha efetuado movimentação de sua conta-corrente ou posição de custódia, realizado operação no mercado de valores mobiliários ou apresentado saldo e sua posição de custódia.","pg":644,"banco":"guia"},{"n":66,"tit":"VIII","titn":"Compliance","cap":"I","capn":"Prevenção à lavagem de dinheiro, ao financiamento do terrorismo e ao financiamento da proliferação de armas de destruição em massa","stem":"A política de PLD/FTP deve:","opts":[["a","ser documentada, aprovada pela alta administração e mantida atualizada, e, no caso de conglomerados financeiros, devem ser estabelecidos mecanismos de intercâmbio de informações entre as áreas de controles internos das instituições do conglomerado para o cumprimento da política."],["b","ser documentada, aprovada pela alta administração e mantida atualizada, e, no caso de conglomerados financeiros, não devem ser estabelecidos mecanismos de intercâmbio de informações entre as áreas de controles internos das instituições do conglomerado."],["c","Ser tratada como confidencial e sigilosa."],["d","Ser aprovada pelo Bacen e CVM e informada ao Coaf."]],"ans":"a","exp":"A política de PLD/FTP, deve ser documentada, aprovada pela alta administração e mantida atualizada, e, no caso de conglomerados financeiros, devem ser estabelecidos mecanismos de intercâmbio de informações entre as áreas de controles internos das instituições do conglomerado para o cumprimento da política.","pg":644,"banco":"guia"},{"n":67,"tit":"VIII","titn":"Compliance","cap":"II","capn":"Proteção de dados pessoais e privacidade","stem":"O profissional responsável pela comunicação em assuntos de proteção de dados e privacidade é chamado de:","opts":[["a","compliance officer."],["b","head de comunicação/marketing."],["c","encarregado/DPO."],["d","diretor de RH."]],"ans":"c","exp":"O encarregado/DPO é o responsável pela comunicação em assuntos de proteção de dados e privacidade.","pg":653,"banco":"guia"},{"n":68,"tit":"VIII","titn":"Compliance","cap":"II","capn":"Proteção de dados pessoais e privacidade","stem":"O direito de exclusão de dados pessoais","opts":[["a","É absoluto, deve ser atendido pela empresa sempre sem ressalvas."],["b","Pode não ser atendido se houver outros direitos ou interesses que prevaleçam sem necessidade de justificativa."],["c","Pode não ser atendido se houver outros interesses ou direitos que prevaleçam e a empresa deve fundamentar o não atendimento da exclusão."],["d","Não é um pedido possível de ser feito."]],"ans":"c","exp":"O direito de exclusão de dados pessoais pode não ser atendido se houver outros interesses ou direitos que prevaleçam e a empresa deve fundamentar o não atendimento da exclusão.","pg":653,"banco":"guia"},{"n":69,"tit":"VIII","titn":"Compliance","cap":"II","capn":"Proteção de dados pessoais e privacidade","stem":"O consentimento é:","opts":[["a","A única base legal prevista na LGPD."],["b","Irrevogável."],["c","Uma das dez bases legais previstas na LGPD."],["d","Essencial para tratamento de dados no mercado financeiro e de capitais."]],"ans":"c","exp":"O consentimento é uma das dez bases legais previstas na LGPD.","pg":653,"banco":"guia"},{"n":70,"tit":"VIII","titn":"Compliance","cap":"III","capn":"Adequação ao perfil do cliente (suitability)","stem":"Caso o investidor envie ordem de operação divergente de seu perfil, o participante deve:","opts":[["a","Recusar e não executar."],["b","Recusar e informar o Coaf e a CVM."],["c","Aceitar e executar."],["d","Aceitar alertando o investidor."]],"ans":"d","exp":"O participante deve aceitar uma ordem divergente do perfil do investidor, mas deve alertá-lo sobre isso.","pg":663,"banco":"guia"},{"n":71,"tit":"VIII","titn":"Compliance","cap":"III","capn":"Adequação ao perfil do cliente (suitability)","stem":"A pessoa natural com investimento superior a 1 milhão de reais, ao atestar essa condição nos termos exigidos pela CVM, será considerada:","opts":[["a","Investidor varejo."],["b","Investidor qualificado."],["c","Investidor Institucional."],["d","Investidor profissional."]],"ans":"b","exp":"O investidor qualificado é aquele que possui investimentos comprovados superiores a 1 milhão de reais.","pg":663,"banco":"guia"},{"n":72,"tit":"VIII","titn":"Compliance","cap":"III","capn":"Adequação ao perfil do cliente (suitability)","stem":"O objetivo de investimento do cliente:","opts":[["a","Deve ser considerado sempre para fins de suitability."],["b","Nunca deve ser considerado para fins de suitability."],["c","É o único critério de suitability."],["d","É o critério mais importante para verificação de suitability."]],"ans":"a","exp":"O objetivo de investimento do cliente sempre deverá ser considerado para fins de suitability.","pg":663,"banco":"guia"},{"n":73,"tit":"VIII","titn":"Compliance","cap":"IV","capn":"Operações ilícitas","stem":"A realização de operações de forma excessiva com o intuito de aumentar o pagamento de comissões é conhecido como:","opts":[["a","spoofing."],["b","layering."],["c","churning."],["d","OMC e Front Running."]],"ans":"c","exp":"Churning é a realização de operações de forma excessiva com o intuito de aumentar o pagamento de comissões.","pg":681,"banco":"guia"},{"n":74,"tit":"VIII","titn":"Compliance","cap":"IV","capn":"Operações ilícitas","stem":"Ordem falsa para induzir o mercado com o objetivo de realizar operação no lado oposto do livro de ofertas é elemento de:","opts":[["a","spoofing."],["b","front running e layering."],["c","churning."],["d","OMC."]],"ans":"a","exp":"A ordem falsa para induzir o mercado é chamada de spoofing.","pg":681,"banco":"guia"},{"n":75,"tit":"VIII","titn":"Compliance","cap":"IV","capn":"Operações ilícitas","stem":"No caso de spoofing, podem ser punidos por regulador e/ou autorregulador:","opts":[["a","Apenas o investidor."],["b","Apenas o participante de mercado."],["c","O investidor e participante de mercado"],["d","O investidor e o diretor responsável perante a CVM do participante."]],"ans":"c","exp":"No caso de spoofing, podem ser punidos o investidor e o participante de mercado.","pg":681,"banco":"guia"},{"n":76,"tit":"VIII","titn":"Compliance","cap":"V","capn":"Segurança cibernética e segurança da informação","stem":"As regras de segurança cibernética para o sistema de distribuição de valores mobiliários são expedidas por:","opts":[["a","Bacen."],["b","CVM."],["c","Bacen e CVM."],["d","Bacen, CVM e ANPD."]],"ans":"c","exp":"As regras de segurança cibernética são expedidas pelo Bacen e CVM.","pg":689,"banco":"guia"},{"n":77,"tit":"VIII","titn":"Compliance","cap":"V","capn":"Segurança cibernética e segurança da informação","stem":"A política de segurança da informação deve:","opts":[["a","Seguir modelo padrão do mercado expedido pelo Bacen."],["b","Seguir modelo padrão de mercado expedido pela CVM."],["c","Ser compatível com o porte, perfil e modelo de negócio da instituição."],["d","Considerar capital social, perfil de clientes e modelo de negócio da instituição."]],"ans":"c","exp":"A política da segurança da informação deve ser compatível com o porte, perfil e modelo de negócio da instituição.","pg":689,"banco":"guia"},{"n":78,"tit":"VIII","titn":"Compliance","cap":"V","capn":"Segurança cibernética e segurança da informação","stem":"Com relação à contratação de serviços de armazenamento em nuvem:","opts":[["a","O prestador pode ser livremente escolhido."],["b","O prestador deve ser homologado pelo Bacen."],["c","O prestador deve estar em país cuja autoridade de supervisão tenha convênio para troca de informações com o Bacen."],["d","O prestador deve estar em lista divulgada anualmente pelo Bacen."]],"ans":"c","exp":"Para armazenamento na nuvem, o prestador deve estar em país cuja autoridade de supervisão tenha convênio para troca de informações com o Bacen.","pg":689,"banco":"guia"},{"n":79,"tit":"VIII","titn":"Compliance","cap":"VI","capn":"Política de responsabilidade social, ambiental e climática (PRSAC)","stem":"A PRSAC deve cobrir riscos de natureza:","opts":[["a","social, ambiental e climática."],["b","socioambiental, socioeconômico e operacional."],["c","social, ambiental e demográfico."],["d","socioambiental, socioeconômico e geopolítico."]],"ans":"a","exp":"A PRSAC deve cobrir riscos de natureza social, ambiental e climática.","pg":694,"banco":"guia"},{"n":80,"tit":"VIII","titn":"Compliance","cap":"VI","capn":"Política de responsabilidade social, ambiental e climática (PRSAC)","stem":"Com relação a conglomerados prudenciais, a PRSAC:","opts":[["a","Deve ser segregada, cada instituição possui a sua."],["b","Deve ser única, ou seja, uma PRSAC para todo conglomerado."],["c","Pode ser única para conglomerado e tratar apenas o que for comum a todas as empresas do grupo."],["d","Pode ser unificada, mas deve considerar aspectos de cada instituição."]],"ans":"d","exp":"Com relação a conglomerados prudenciais, a PRSAC pode ser unificada, mas deve considerar aspectos de cada instituição.","pg":694,"banco":"guia"},{"n":81,"tit":"VIII","titn":"Compliance","cap":"VI","capn":"Política de responsabilidade social, ambiental e climática (PRSAC)","stem":"A documentação relativa a PRSAC:","opts":[["a","Deve ser arquivada por 10 anos."],["b","Deve ser mantida à disposição do Ministério do Meio Ambiente por 5 anos."],["c","Deve ser mantida à disposição do Banco Central por 5 anos."],["d","Deve ser mantida à disposição do Banco Central por 10 anos."]],"ans":"c","exp":"A documentação relativa a PRSAC deve ser mantida à disposição do Banco Central por 5 anos.","pg":694,"banco":"guia"},{"n":82,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"I","capn":"Mercado de renda variável","stem":"Segundo a Lei das S.A., qual é a participação mínima de ações ordinárias no capital social de uma companhia?","opts":[["a","25%"],["b","33%"],["c","50%"],["d","67%"]],"ans":"c","exp":"A Lei nº 6.404/1976 determina que a companhia deve ter, no mínimo, 50% do seu capital constituído de ações ordinárias; as preferenciais, em geral sem direito a voto, ficam limitadas aos demais 50%.","pg":99,"banco":"guia"},{"n":83,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"I","capn":"Mercado de renda variável","stem":"Qual característica é exclusiva do Novo Mercado em relação aos segmentos Nível 1 e Nível 2?","opts":[["a","Capital social composto apenas por ações ordinárias"],["b","Free float mínimo de 20% (ou regra alternativa)"],["c","Manutenção de ações preferenciais com tag along de 100%"],["d","Listagem sem oferta, com até sete anos para o IPO"]],"ans":"a","exp":"No Novo Mercado o capital social é composto apenas por ações ordinárias, com tag along de 100%.","pg":104,"banco":"guia"},{"n":84,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"I","capn":"Mercado de renda variável","stem":"Qual segmento de listagem permite que a empresa seja listada sem oferta e tenha até sete anos para realizar o IPO?","opts":[["a","Novo Mercado"],["b","Nível 2"],["c","Nível 1"],["d","Bovespa Mais"]],"ans":"d","exp":"O Bovespa Mais permite a listagem sem oferta: a empresa pode ser listada na B3 e tem até sete anos para realizar a oferta pública de ações (IPO).","pg":105,"banco":"guia"},{"n":85,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"I","capn":"Mercado de renda variável","stem":"A distribuição gratuita de novas ações aos acionistas, proporcional às suas participações e resultante de aumento de capital por incorporação de reservas ou lucros, é chamada de:","opts":[["a","Subscrição"],["b","Bonificação"],["c","Desdobramento"],["d","Juros sobre capital próprio"]],"ans":"b","exp":"Bonificação é a distribuição gratuita de ações aos acionistas, proporcional às parcelas que possuem, resultante de aumento de capital por incorporação de reservas ou lucros em suspenso.","pg":100,"banco":"guia"},{"n":86,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"I","capn":"Mercado de renda variável","stem":"Uma companhia decide reunir cada dez ações existentes em uma só, sem alterar o valor total do investimento do acionista. Esse evento é chamado de:","opts":[["a","Grupamento (inplit)"],["b","Desdobramento (split)"],["c","Bonificação"],["d","Subscrição"]],"ans":"a","exp":"Grupamento (inplit) consiste em reunir várias ações em uma; o desdobramento (split) faz o inverso, dividindo as ações existentes. Em ambos, o valor do investimento não se altera.","pg":101,"banco":"guia"},{"n":87,"tit":"V","titn":"Negociação","cap":"II","capn":"Ambiente de negociação","stem":"A ordem que deve ser executada somente a preço igual ou melhor do que o especificado pelo cliente é a ordem:","opts":[["a","A mercado"],["b","Administrada"],["c","Limitada"],["d","Casada"]],"ans":"c","exp":"A ordem limitada é aquela que deve ser executada somente a preço igual ou melhor do que o especificado pelo cliente.","pg":519,"banco":"guia"},{"n":88,"tit":"V","titn":"Negociação","cap":"II","capn":"Ambiente de negociação","stem":"O cliente especifica apenas a quantidade e as características do ativo, deixando a execução a critério do PNP ou do PN. Trata-se da ordem:","opts":[["a","Stop"],["b","Administrada"],["c","Limitada"],["d","Casada"]],"ans":"b","exp":"Na ordem administrada o cliente especifica somente a quantidade e as características dos ativos, ficando a execução a critério do PNP ou do PN.","pg":519,"banco":"guia"},{"n":89,"tit":"V","titn":"Negociação","cap":"II","capn":"Ambiente de negociação","stem":"A ordem cuja execução está vinculada à execução de outra ordem do cliente, podendo ser com ou sem limite de preço, é a ordem:","opts":[["a","Casada"],["b","On close"],["c","Stop"],["d","Administrada"]],"ans":"a","exp":"Ordem casada é aquela cuja execução está vinculada à execução de outra ordem do cliente, podendo ser com ou sem limite de preço.","pg":520,"banco":"guia"},{"n":90,"tit":"V","titn":"Negociação","cap":"II","capn":"Ambiente de negociação","stem":"Quando o Ibovespa cai 10% em relação ao fechamento do dia anterior, o circuit breaker interrompe a negociação por:","opts":[["a","15 minutos"],["b","30 minutos"],["c","1 hora"],["d","Prazo definido pela B3"]],"ans":"b","exp":"Pelo circuit breaker, a queda de 10% do Ibovespa interrompe a negociação por 30 minutos; a de 15%, por 1 hora; na de 20%, a B3 pode suspender a negociação por prazo que ela definir.","pg":532,"banco":"guia"},{"n":91,"tit":"V","titn":"Negociação","cap":"II","capn":"Ambiente de negociação","stem":"Reabertas as negociações após o primeiro acionamento do circuit breaker, se o Ibovespa atingir queda de 15%, a negociação é interrompida por:","opts":[["a","30 minutos"],["b","2 horas"],["c","1 hora"],["d","Até o fim do pregão"]],"ans":"c","exp":"Na queda de 15% do Ibovespa, após a reabertura, a negociação de ativos, derivativos e renda fixa privada é interrompida por 1 hora.","pg":532,"banco":"guia"},{"n":92,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"I","capn":"Mercado de renda variável","stem":"No empréstimo de ativos, a B3, como contraparte de todos os contratos registrados, só autoriza a operação mediante:","opts":[["a","Garantias depositadas previamente pela ponta tomadora"],["b","Garantias depositadas pela ponta doadora"],["c","Aval da corretora do doador"],["d","Seguro contratado pelo emissor do ativo"]],"ans":"a","exp":"A B3 é contraparte de todos os contratos de empréstimo registrados e somente autoriza as operações com as garantias da ponta tomadora previamente depositadas.","pg":151,"banco":"guia"},{"n":93,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"I","capn":"Mercado de renda variável","stem":"Durante um empréstimo de ações, a companhia emissora paga dividendos. Como o doador é compensado?","opts":[["a","Perde o direito ao provento durante o empréstimo"],["b","O tomador faz ao doador um pagamento equivalente, a título de reembolso"],["c","A companhia paga o provento diretamente ao doador"],["d","A B3 paga o provento com recursos próprios"]],"ans":"b","exp":"Como o provento é creditado a quem detém os ativos na data-base (o tomador), a bolsa obriga o tomador a fazer ao doador pagamentos equivalentes de compensação, a título de reembolso.","pg":147,"banco":"guia"},{"n":94,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"II","capn":"Mercado de derivativos","stem":"Quais são os prazos mínimo e máximo de uma operação a termo de ações na B3?","opts":[["a","1 e 360 dias corridos"],["b","16 e 999 dias corridos"],["c","30 e 720 dias corridos"],["d","16 e 360 dias úteis"]],"ans":"b","exp":"O prazo mínimo de uma operação a termo de ações é de 16 dias corridos, e o máximo, de 999 dias corridos.","pg":177,"banco":"guia"},{"n":95,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"II","capn":"Mercado de derivativos","stem":"No mercado de opções, o prêmio é:","opts":[["a","O preço pelo qual o titular pode exercer seu direito"],["b","O valor pago pelo lançador ao titular para assumir a obrigação"],["c","O valor pago pelo titular ao lançador para ter o direito de comprar ou vender o ativo-objeto"],["d","A margem de garantia exigida do titular"]],"ans":"c","exp":"Prêmio é o valor pago pelo titular ao lançador da opção para ter o direito de comprar ou de vender o ativo-objeto.","pg":187,"banco":"guia"},{"n":96,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"II","capn":"Mercado de derivativos","stem":"Considerando S o preço do ativo-objeto e K o preço de exercício, o valor intrínseco de uma opção de compra (call) é positivo quando:","opts":[["a","S > K"],["b","S < K"],["c","S = K"],["d","Sempre, independentemente de S e K"]],"ans":"a","exp":"O valor intrínseco de uma call é zero quando S ≤ K e positivo quando S > K. Na put, é positivo quando S < K.","pg":191,"banco":"guia"},{"n":97,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"II","capn":"Mercado de derivativos","stem":"As opções flexíveis da B3 se caracterizam por:","opts":[["a","Serem negociadas em bolsa, com vencimentos padronizados"],["b","Serem negociadas em balcão organizado, com regras não padronizadas definidas pelas partes"],["c","Terem sempre exercício no estilo europeu e liquidação física"],["d","Serem exclusivas de investidores não residentes"]],"ans":"b","exp":"As opções flexíveis são negociadas em ambiente de balcão organizado e têm regras e funcionalidades não padronizadas, definidas a critério das partes.","pg":240,"banco":"guia"},{"n":98,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"II","capn":"Mercado de derivativos","stem":"No vencimento, o contrato futuro de DI de um dia (DI1) tem PU de:","opts":[["a","1.000 pontos"],["b","10.000 pontos"],["c","100.000 pontos"],["d","1.000.000 de pontos"]],"ans":"c","exp":"No vencimento, o contrato futuro de DI1 tem PU de 100.000 pontos, sendo cada ponto igual a R$ 1,00 (R$ 100.000,00). A cotação é feita em taxa efetiva anual, base 252 dias úteis.","pg":215,"banco":"guia"},{"n":99,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"II","capn":"Mercado de derivativos","stem":"O contrato futuro de Ibovespa é cotado em pontos de índice e tem vencimentos:","opts":[["a","Mensais"],["b","Bimestrais, nos meses pares"],["c","Trimestrais"],["d","Bimestrais, nos meses ímpares"]],"ans":"b","exp":"O futuro de Ibovespa é cotado em pontos de índice, e os vencimentos ocorrem bimestralmente, nos meses pares.","pg":206,"banco":"guia"},{"n":100,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"II","capn":"Mercado de derivativos","stem":"Em um contrato de swap, as contrapartes:","opts":[["a","Trocam fluxos de caixa com base em prazo, valor de referência e variáveis"],["b","Trocam a propriedade dos ativos-objeto na data de início"],["c","Adquirem o direito, mas não a obrigação, de comprar um ativo"],["d","Fazem ajustes diários padronizados em bolsa"]],"ans":"a","exp":"Swap significa troca: as contrapartes trocam fluxos de caixa com base em prazo, valor de referência e variáveis.","pg":198,"banco":"guia"},{"n":101,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"III","capn":"Mercado de renda fixa","stem":"Debêntures que dão ao credor o direito de trocá-las por ações de OUTRA empresa, e não da emissora, são chamadas de:","opts":[["a","Simples"],["b","Conversíveis"],["c","Permutáveis"],["d","Incentivadas"]],"ans":"c","exp":"Debêntures permutáveis dão ao credor o direito de trocá-las por ações de outras empresas; nas conversíveis, a troca é por ações da própria emissora.","pg":266,"banco":"guia"},{"n":102,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"III","capn":"Mercado de renda fixa","stem":"A Cédula de Produto Rural (CPR), criada pela Lei nº 8.929/1994, é:","opts":[["a","Um título de crédito representativo de promessa de entrega de produtos rurais"],["b","Um título emitido por bancos com lastro em créditos do agronegócio"],["c","Um certificado emitido por securitizadora com lastro em recebíveis imobiliários"],["d","Um título público federal atrelado à inflação"]],"ans":"a","exp":"A CPR é um título de crédito representativo de promessa de entrega de produtos rurais, criado pela Lei nº 8.929/1994.","pg":267,"banco":"guia"},{"n":103,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"VIII","capn":"Tributação do mercado financeiro","stem":"Nos fundos sujeitos ao come-cotas, o recolhimento semestral do Imposto de Renda ocorre no último dia útil de quais meses?","opts":[["a","Junho e dezembro"],["b","Março e setembro"],["c","Maio e novembro"],["d","Janeiro e julho"]],"ans":"c","exp":"O come-cotas é o recolhimento semestral de IR no último dia útil de maio e de novembro; o valor devido é abatido da quantidade de cotas do investidor.","pg":372,"banco":"guia"},{"n":104,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"VIII","capn":"Tributação do mercado financeiro","stem":"Ficam isentos do IR os ganhos líquidos da pessoa física com ações no mercado à vista de bolsa quando o total das ALIENAÇÕES no mês não exceder:","opts":[["a","R$ 20.000,00"],["b","R$ 35.000,00"],["c","R$ 10.000,00"],["d","R$ 50.000,00"]],"ans":"a","exp":"São isentos os ganhos líquidos da pessoa física quando o total das alienações de ações no mercado à vista de bolsa no mês não exceder R$ 20.000,00.","pg":379,"banco":"guia"},{"n":105,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"VIII","capn":"Tributação do mercado financeiro","stem":"No day trade, quais são, respectivamente, a alíquota de IR retido na fonte e a alíquota mensal sobre os ganhos líquidos?","opts":[["a","0,005% e 15%"],["b","1% e 20%"],["c","1% e 15%"],["d","0,005% e 20%"]],"ans":"b","exp":"No day trade, a retenção na fonte é de 1% sobre o resultado positivo e o imposto mensal é de 20% sobre os ganhos líquidos.","pg":385,"banco":"guia"},{"n":106,"tit":"I","titn":"Aspectos institucionais","cap":"III","capn":"A B3 no mercado financeiro e de capitais","stem":"Quantos membros compõem o Conselho de Supervisão da BSM e qual a exigência de independência?","opts":[["a","7 membros, maioria independente"],["b","9 membros, metade independente"],["c","12 membros, todos independentes"],["d","12 membros, pelo menos dois terços independentes"]],"ans":"d","exp":"O Conselho de Supervisão da BSM tem 12 membros, sendo pelo menos dois terços independentes; ele também aprova o programa de trabalho, o orçamento e o relatório de atividades da BSM.","pg":479,"banco":"guia"},{"n":107,"tit":"I","titn":"Aspectos institucionais","cap":"I","capn":"Sistema Financeiro Nacional","stem":"Qual é a composição do Conselho Monetário Nacional (CMN)?","opts":[["a","Ministro da Fazenda, Ministro do Planejamento e Orçamento e Presidente do Banco Central"],["b","Presidente da República, Ministro da Fazenda e Presidente da CVM"],["c","Presidente do Banco Central, Presidente da CVM e Superintendente da Susep"],["d","Ministro da Fazenda, Presidente do Banco Central e Presidente da B3"]],"ans":"a","exp":"O CMN é composto pelo Ministro da Fazenda (presidente do Conselho), pelo Ministro do Planejamento e Orçamento e pelo Presidente do Banco Central do Brasil.","pg":22,"banco":"guia"},{"n":108,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"II","capn":"Mercado de derivativos","stem":"Qual é o tamanho do contrato futuro padrão de dólar comercial (DOL) na B3?","opts":[["a","US$ 10.000,00"],["b","US$ 25.000,00"],["c","US$ 50.000,00"],["d","US$ 100.000,00"]],"ans":"c","exp":"O contrato futuro padrão de dólar comercial tem tamanho de US$ 50.000,00; o minicontrato (WDO) corresponde a US$ 10.000,00.","pg":210,"banco":"guia"},{"n":109,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"II","capn":"Mercado de derivativos","stem":"O minicontrato futuro de dólar (WDO) tem tamanho de:","opts":[["a","US$ 1.000,00"],["b","US$ 5.000,00"],["c","US$ 50.000,00"],["d","US$ 10.000,00"]],"ans":"d","exp":"O minicontrato de dólar (WDO) corresponde a US$ 10.000,00, um quinto do contrato padrão de US$ 50.000,00.","pg":210,"banco":"guia"},{"n":110,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"II","capn":"Mercado de derivativos","stem":"Os contratos futuros de dólar comercial (DOL e WDO) vencem:","opts":[["a","No primeiro dia útil do mês de vencimento"],["b","No último dia útil do mês anterior ao vencimento"],["c","Na quarta-feira mais próxima do dia 15 do mês de vencimento"],["d","No dia 15 do mês de vencimento ou no dia útil seguinte"]],"ans":"a","exp":"Os contratos futuros de dólar vencem no primeiro dia útil do mês de vencimento e têm liquidação exclusivamente financeira.","pg":210,"banco":"guia"},{"n":111,"tit":"VI","titn":"Câmara de compensação e liquidação","cap":"I","capn":"Câmara B3","stem":"Na cadeia de salvaguardas da Câmara B3, qual é o PRIMEIRO recurso utilizado para cobrir perdas decorrentes de uma inadimplência?","opts":[["a","Recursos próprios da B3 dedicados à câmara"],["b","Garantias depositadas pelo comitente inadimplente"],["c","Contribuições dos membros de compensação adimplentes"],["d","Fundo de liquidação"]],"ans":"b","exp":"A cadeia de salvaguardas começa pelas garantias depositadas pelo próprio comitente inadimplente; só depois são usados os recursos dos intermediários, o fundo de liquidação e os recursos da B3.","pg":558,"banco":"guia"},{"n":112,"tit":"VI","titn":"Câmara de compensação e liquidação","cap":"I","capn":"Câmara B3","stem":"A metodologia CORE (Close-Out Risk Evaluation), adotada pela B3, é utilizada para:","opts":[["a","Calcular os tributos devidos nas operações de bolsa"],["b","Definir o horário de abertura e fechamento do pregão"],["c","Apurar as medidas de risco da atividade de contraparte central, como as margens de garantia"],["d","Classificar as companhias nos segmentos de listagem"]],"ans":"c","exp":"A metodologia CORE foi desenvolvida para apurar as medidas de risco inerentes à atividade de contraparte central da B3 em ambientes multimercados e multiativos, como o cálculo das margens de garantia.","pg":446,"banco":"guia"},{"n":113,"tit":"V","titn":"Negociação","cap":"II","capn":"Ambiente de negociação","stem":"Segundo o guia, o leilão especial de ativos tem duração mínima de:","opts":[["a","5 minutos"],["b","15 minutos"],["c","30 minutos"],["d","1 hora"]],"ans":"b","exp":"O guia estabelece que o leilão especial tem duração de, no mínimo, 15 minutos.","pg":527,"banco":"guia"},{"n":114,"tit":"V","titn":"Negociação","cap":"II","capn":"Ambiente de negociação","stem":"Os túneis de negociação da B3 são mecanismos de controle que se dividem em:","opts":[["a","Túneis de alta e túneis de baixa"],["b","Túneis de abertura e túneis de fechamento"],["c","Túneis de liquidez e túneis de volatilidade"],["d","Túneis de rejeição e túneis de leilão"]],"ans":"d","exp":"Os túneis de negociação controlam as quantidades e as oscilações de preço, destacando-se os túneis de rejeição (que impedem ofertas fora dos parâmetros) e os túneis de leilão (que submetem as ofertas a leilão), além do túnel de proteção em leilões.","pg":529,"banco":"guia"},{"n":115,"tit":"V","titn":"Negociação","cap":"II","capn":"Ambiente de negociação","stem":"O after-market é:","opts":[["a","A sessão de negociação estendida para determinados ativos e derivativos"],["b","O período de leilão que antecede a abertura do pregão"],["c","O mercado de balcão não organizado"],["d","A janela de liquidação das operações em D+2"]],"ans":"a","exp":"A sessão pode ser estendida, para determinados ativos e derivativos, por meio do after-market, que é a sessão de negociação estendida.","pg":515,"banco":"guia"},{"n":116,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"I","capn":"Mercado de renda variável","stem":"Pela Lei das S.A., em caso de alienação do controle, o tag along garante aos acionistas minoritários detentores de ações ordinárias o recebimento de, no mínimo:","opts":[["a","50% do preço pago por ação ao controlador"],["b","70% do preço pago por ação ao controlador"],["c","80% do preço pago por ação ao controlador"],["d","100% do preço pago por ação ao controlador"]],"ans":"c","exp":"A exigência legal prevê que os novos controladores façam oferta de compra (tag along) das ações ordinárias em poder do público, por preço igual ou superior a 80% do valor pago por ação do bloco de controle.","pg":129,"banco":"guia"},{"n":117,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"V","capn":"Fundos de investimento","stem":"Para ter o tratamento tributário previsto em lei, o fundo de investimento imobiliário (FII) deve distribuir aos cotistas, no mínimo:","opts":[["a","50% do lucro auferido"],["b","75% do lucro auferido"],["c","90% do lucro auferido"],["d","95% do lucro auferido"]],"ans":"d","exp":"O FII deve distribuir a seus cotistas, no mínimo, 95% do lucro auferido.","pg":317,"banco":"guia"},{"n":118,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"VIII","capn":"Tributação do mercado financeiro","stem":"Para que os rendimentos distribuídos por um FII sejam isentos de IR para a pessoa física, o fundo deve ter, no mínimo:","opts":[["a","50 cotistas"],["b","100 cotistas"],["c","500 cotistas"],["d","1.000 cotistas"]],"ans":"b","exp":"Entre as condições para a isenção dos rendimentos para a pessoa física está o fundo ter, no mínimo, 100 cotistas, além de limites de participação por cotista e por grupo familiar.","pg":376,"banco":"guia"},{"n":119,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"VIII","capn":"Tributação do mercado financeiro","stem":"Para manter a isenção dos rendimentos de um FII, o cotista pessoa física pode deter, no máximo, qual percentual das cotas emitidas?","opts":[["a","10%"],["b","5%"],["c","20%"],["d","30%"]],"ans":"a","exp":"O cotista pessoa física deve ser titular de cotas que representem até 10% das cotas emitidas pelo fundo (ou que lhe deem direito a até 10% dos rendimentos).","pg":376,"banco":"guia"},{"n":120,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"V","capn":"Fundos de investimento","stem":"O FIDC é um fundo no qual pelo menos qual parcela dos recursos é destinada à aquisição de direitos creditórios?","opts":[["a","25%"],["b","33%"],["c","50%"],["d","67%"]],"ans":"c","exp":"O FIDC é um tipo de fundo no qual pelo menos 50% dos recursos são destinados à aquisição de direitos creditórios.","pg":314,"banco":"guia"},{"n":121,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"V","capn":"Fundos de investimento","stem":"O fundo destinado à aplicação em companhias abertas, fechadas ou sociedades limitadas em fase de desenvolvimento, com participação no processo decisório, é o:","opts":[["a","FIDC"],["b","FIP"],["c","FII"],["d","ETF"]],"ans":"b","exp":"O fundo de investimento em participações (FIP) é uma comunhão de recursos destinados à aplicação em companhias abertas, fechadas ou sociedades limitadas em fase de desenvolvimento.","pg":315,"banco":"guia"},{"n":122,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"III","capn":"Mercado de renda fixa","stem":"Qual é o prazo mínimo de uma Letra Financeira (LF)?","opts":[["a","90 dias"],["b","1 ano"],["c","5 anos"],["d","2 anos"]],"ans":"d","exp":"A Letra Financeira tem prazo mínimo de dois anos, vedado o resgate antecipado, total ou parcial.","pg":262,"banco":"guia"},{"n":123,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"III","capn":"Mercado de renda fixa","stem":"Uma Letra Financeira SEM cláusula de subordinação deve ter valor nominal unitário igual ou superior a:","opts":[["a","R$ 50.000,00"],["b","R$ 300.000,00"],["c","R$ 1.000,00"],["d","R$ 150.000,00"]],"ans":"a","exp":"A LF deve ter valor nominal unitário igual ou superior a R$ 50.000,00 se não contiver cláusula de subordinação, e a R$ 300.000,00 se contiver.","pg":262,"banco":"guia"},{"n":124,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"III","capn":"Mercado de renda fixa","stem":"A Letra de Crédito do Agronegócio (LCA) é:","opts":[["a","Um título emitido pelo produtor rural com promessa de entrega de produtos"],["b","Um título emitido por securitizadora com lastro em recebíveis imobiliários"],["c","Um título de crédito nominativo, de livre negociação, usado para captar recursos para a cadeia do agronegócio"],["d","Um título público federal destinado ao financiamento agrícola"]],"ans":"c","exp":"A LCA é um título de crédito nominativo, de livre negociação, utilizado para captar recursos para participantes da cadeia do agronegócio.","pg":263,"banco":"guia"},{"n":125,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"III","capn":"Mercado de renda fixa","stem":"As notas comerciais (commercial papers) são títulos:","opts":[["a","De longo prazo, emitidos por bancos para financiar o crédito imobiliário"],["b","De curto prazo, emitidos por sociedades não financeiras para captar recursos para capital de giro"],["c","Públicos, emitidos pelo Tesouro para financiar o déficit"],["d","De renda variável, conversíveis em ações da emissora"]],"ans":"b","exp":"Notas comerciais são títulos de curto prazo emitidos por sociedades não financeiras, com o objetivo de captar recursos para capital de giro.","pg":265,"banco":"guia"},{"n":126,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"VIII","capn":"Tributação do mercado financeiro","stem":"Qual é a alíquota de IR sobre os rendimentos das debêntures incentivadas (Lei nº 12.431/2011) auferidos por pessoa física?","opts":[["a","15%"],["b","22,5%"],["c","0%"],["d","Tabela regressiva da renda fixa"]],"ans":"c","exp":"Nas debêntures incentivadas, os rendimentos auferidos por pessoa física estão sujeitos à alíquota de 0% de IR.","pg":364,"banco":"guia"},{"n":127,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"VIII","capn":"Tributação do mercado financeiro","stem":"Na tabela regressiva de IR da renda fixa, qual é a alíquota para aplicações com prazo de 181 a 360 dias?","opts":[["a","22,5%"],["b","20%"],["c","17,5%"],["d","15%"]],"ans":"b","exp":"A tabela regressiva prevê 22,5% até 180 dias, 20% de 181 a 360 dias, 17,5% de 361 a 720 dias e 15% acima de 720 dias.","pg":362,"banco":"guia"},{"n":128,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"VIII","capn":"Tributação do mercado financeiro","stem":"Um investidor resgata um CDB após 500 dias. Qual alíquota de IR se aplica ao rendimento?","opts":[["a","20%"],["b","17,5%"],["c","15%"],["d","22,5%"]],"ans":"b","exp":"Aplicações com prazo de 361 a 720 dias são tributadas a 17,5% na tabela regressiva da renda fixa.","pg":362,"banco":"guia"},{"n":129,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"VIII","capn":"Tributação do mercado financeiro","stem":"Nos resgates de renda fixa feitos em prazo inferior a 30 dias, o IOF incide sobre o rendimento com percentual que:","opts":[["a","É fixo, de 0,38%"],["b","É fixo, de 1,5% ao mês"],["c","Varia de 96% a 0%, conforme os dias decorridos desde a aplicação"],["d","Varia de 22,5% a 15%, conforme o prazo"]],"ans":"c","exp":"O IOF incide nos resgates feitos em menos de 30 dias, com percentual que varia de 96% a 0%, conforme o número de dias decorridos desde a aplicação.","pg":387,"banco":"guia"},{"n":130,"tit":"I","titn":"Aspectos institucionais","cap":"I","capn":"Sistema Financeiro Nacional","stem":"O órgão do Banco Central responsável por definir periodicamente a meta da taxa Selic é o:","opts":[["a","Conselho Monetário Nacional (CMN)"],["b","Comitê de Política Monetária (Copom)"],["c","Conselho de Recursos do Sistema Financeiro Nacional (CRSFN)"],["d","Comissão de Valores Mobiliários (CVM)"]],"ans":"b","exp":"O Copom reúne membros da diretoria do Banco Central e define periodicamente a meta da taxa Selic.","pg":231,"banco":"guia"},{"n":131,"tit":"II","titn":"Mercados de bolsa e de balcão","cap":"III","capn":"Mercado de renda fixa","stem":"No Tesouro Direto, o título Tesouro IPCA+ corresponde a qual título público?","opts":[["a","LTN"],["b","LFT"],["c","NTN-F"],["d","NTN-B"]],"ans":"d","exp":"O Tesouro IPCA+ corresponde à NTN-B, título indexado à inflação (IPCA); o Tesouro Prefixado corresponde à LTN e à NTN-F, e o Tesouro Selic à LFT.","pg":251,"banco":"guia"},{"n":132,"tit":"VIII","titn":"Compliance","cap":"I","capn":"Prevenção à lavagem de dinheiro, ao financiamento do terrorismo e ao financiamento da proliferação de armas de destruição em massa","stem":"Segundo a Resolução CVM nº 50/2021, as operações ou propostas que apresentem sérios indícios de lavagem de dinheiro ou de financiamento do terrorismo devem ser comunicadas ao Coaf em até:","opts":[["a","48 horas após a data da operação."],["b","24 horas após a conclusão da análise que caracterizou a atipicidade."],["c","5 dias úteis após a data da operação."],["d","30 dias após o encerramento do mês da operação."]],"ans":"b","exp":"A comunicação ao Coaf deve ser feita em até 24 horas contadas da conclusão da análise que caracterizou a operação ou proposta como atípica, sem dar ciência ao cliente.","pg":641,"banco":"guia"},{"n":133,"tit":"VIII","titn":"Compliance","cap":"I","capn":"Prevenção à lavagem de dinheiro, ao financiamento do terrorismo e ao financiamento da proliferação de armas de destruição em massa","stem":"Pela Resolução CVM nº 50/2021, a documentação cadastral, de monitoramento e de análise de operações relativa a PLD/FTP deve ser mantida à disposição da CVM pelo prazo mínimo de:","opts":[["a","1 ano."],["b","2 anos."],["c","5 anos."],["d","10 anos."]],"ans":"c","exp":"A documentação de cadastro, monitoramento e análise de PLD/FTP deve ser conservada por no mínimo 5 anos, à disposição da CVM.","pg":641,"banco":"guia"},{"n":134,"tit":"VIII","titn":"Compliance","cap":"II","capn":"Proteção de dados pessoais e privacidade","stem":"A Lei Geral de Proteção de Dados Pessoais (LGPD) é a:","opts":[["a","Lei nº 13.709/2018, que dispõe sobre o tratamento de dados pessoais de pessoas naturais; a ANPD foi criada pela Lei nº 13.853/2019."],["b","Lei nº 12.965/2014, que criou a ANPD e regula o tratamento de dados de pessoas jurídicas."],["c","Lei nº 9.613/1998, que trata do sigilo dos dados de clientes de instituições financeiras."],["d","Lei Complementar nº 105/2001, que instituiu as bases legais para tratamento de dados pessoais."]],"ans":"a","exp":"A LGPD é a Lei nº 13.709/2018 e trata de dados pessoais de pessoas naturais. A Lei nº 13.853/2019 alterou a LGPD e criou a Autoridade Nacional de Proteção de Dados (ANPD).","pg":646,"banco":"guia"},{"n":135,"tit":"VIII","titn":"Compliance","cap":"III","capn":"Adequação ao perfil do cliente (suitability)","stem":"De acordo com a Resolução CVM nº 30/2021, as instituições devem proceder a nova análise e classificação das categorias de produtos em intervalos não superiores a:","opts":[["a","6 meses."],["b","12 meses."],["c","36 meses."],["d","24 meses."]],"ans":"d","exp":"A Resolução CVM nº 30/2021 determina que a análise e a classificação das categorias de produtos sejam refeitas em intervalos não superiores a 24 meses.","pg":659,"banco":"guia"},{"n":136,"tit":"IV","titn":"Gestão de risco","cap":"II","capn":"Risco corporativo e controles internos","stem":"No modelo de linhas de defesa apresentado no guia, a auditoria interna corresponde à:","opts":[["a","Primeira linha de defesa."],["b","Segunda linha de defesa."],["c","Terceira linha de defesa."],["d","Quarta linha de defesa."]],"ans":"c","exp":"A auditoria interna é a terceira linha de defesa: avalia de forma independente a efetividade da gestão de riscos e dos controles. A primeira é a gestão operacional, a segunda são controles internos/riscos/compliance e a quarta, auditoria externa e reguladores.","pg":464,"banco":"guia"},{"n":137,"tit":"IV","titn":"Gestão de risco","cap":"II","capn":"Risco corporativo e controles internos","stem":"A norma que exige das instituições autorizadas pelo Banco Central a implementação de estrutura de gerenciamento de riscos (crédito, mercado, operacional e liquidez) e a indicação de diretor responsável (CRO) é a:","opts":[["a","Resolução CMN nº 4.557/2017."],["b","Resolução CVM nº 30/2021."],["c","Resolução CMN nº 4.945/2021."],["d","Resolução CVM nº 50/2021."]],"ans":"a","exp":"A Resolução CMN nº 4.557/2017 dispõe sobre a estrutura de gerenciamento de riscos e de capital e exige a indicação de diretor responsável pelo gerenciamento de riscos (CRO).","pg":470,"banco":"guia"},{"n":138,"tit":"III","titn":"Estrutura de contas e cadastro","cap":"I","capn":"Cadastro de investidores residentes","stem":"O sistema da B3 utilizado para inclusão e manutenção dos dados cadastrais de comitentes, contas, vínculos e profissionais é o:","opts":[["a","RDE."],["b","Sincad."],["c","Sisbacen."],["d","CORE."]],"ans":"b","exp":"O Sincad (Sistema Integrado de Cadastro) é a plataforma da B3 para inclusão e manutenção de dados de comitentes, contas, vínculos e profissionais.","pg":401,"banco":"guia"},{"n":139,"tit":"III","titn":"Estrutura de contas e cadastro","cap":"I","capn":"Cadastro de investidores residentes","stem":"A conta máster é uma estrutura de conta:","opts":[["a","de depósito definitiva, na qual os ativos do comitente ficam custodiados."],["b","exclusiva de investidores não residentes, aberta pelo representante legal."],["c","transitória, que agrupa ordens de comitentes com vínculo comum para posterior alocação aos beneficiários finais."],["d","de garantia, utilizada para depósito de margem junto à Câmara B3."]],"ans":"c","exp":"A conta máster é transitória: agrupa ordens de comitentes que possuem vínculo comum, e as operações são depois alocadas às contas dos beneficiários finais.","pg":404,"banco":"guia"},{"n":140,"tit":"VII","titn":"Central depositária","cap":"I","capn":"Central depositária da B3","stem":"Em relação aos ativos mantidos sob guarda na central depositária da B3, é correto afirmar que:","opts":[["a","integram o patrimônio da B3 até a liquidação das operações."],["b","podem ser usados pela B3 para cobrir perdas de qualquer participante."],["c","pertencem ao agente de custódia enquanto estiverem depositados."],["d","não integram o patrimônio da B3 e permanecem em nome dos comitentes."]],"ans":"d","exp":"Os ativos depositados na central depositária não integram o patrimônio da B3: ficam segregados e mantidos em nome dos respectivos comitentes (titulares).","pg":604,"banco":"guia"},{"n":141,"tit":"VII","titn":"Central depositária","cap":"II","capn":"Processos operacionais da central depositária da B3","stem":"O controle de saldos que registra, além da quantidade, as datas e os custos de aquisição dos ativos, permitindo a apuração tributária, é chamado de controle:","opts":[["a","analítico."],["b","sintético."],["c","fungível."],["d","consolidado."]],"ans":"a","exp":"No controle analítico são registradas as datas e os custos de aquisição, o que permite a apuração tributária. O controle sintético registra apenas a quantidade consolidada.","pg":619,"banco":"guia"},{"n":142,"banco":"lucas","mod":1,"tit":"I","titn":"Sistema Financeiro Nacional e Participantes do Mercado","cap":"1","capn":"Questão 1 (cód. 9516)","stem":"Entende-se o Sistema Financeiro Nacional (SFN) como um conjunto de instrumentos, mecanismos e instituições que: I. Asseguram a canalização da poupança para investimento. II. Possuem recursos financeiros superavitários para os que necessitam de recursos. III. Articulam estratégias de grupos deficitários em prol dos superavitários. IV. Asseguram a unificação das moedas e o equilíbrio da balança comercial. Quais das afirmativas acima estão corretas?","opts":[["a","Apenas I"],["b","Apena I e II"],["c","Apenas II e III"],["d","Apenas III e IV"]],"ans":"b","exp":"Tema: função do Sistema Financeiro Nacional. O SFN canaliza a poupança para investimento e faz a intermediação entre superavitários (quem tem recursos sobrando) e deficitários (quem precisa de recursos). Os itens I e II estão corretos. O item III inverte a lógica, porque o SFN articula estratégias dos superavitários em favor dos deficitários, e não o contrário. O item IV descreve funções de outros órgãos, como a política cambial e monetária. A alternativa B é a correta. Atenção ao erro de digitação na alternativa \"Apena I e II\", que tem o mesmo conteúdo da correta.","id":"9516"},{"n":143,"banco":"lucas","mod":1,"tit":"I","titn":"Sistema Financeiro Nacional e Participantes do Mercado","cap":"2","capn":"Questão 2 (cód. 9517)","stem":"O Sistema Financeiro Nacional (SFN), está fragmentado em seis grandes mercados, dentre eles: I. Mercado Monetário e Mercado de Crédito. II. Mercado Monetário e Mercado Consumidor. III. Mercado Concorrente e Mercado de Capitais. IV. Mercados de Derivativos e Mercados de Capitais. V. Mercados de Câmbio e Mercados de Seguro e Previdência. Está correto o que se afirma em:","opts":[["a","I e II"],["b","II, III e IV"],["c","III e V"],["d","I, IV e V"]],"ans":"d","exp":"Tema: mercados do SFN. A apostila organiza o sistema em mercados como monetário, crédito, câmbio, capitais, derivativos e seguros/previdência. Analisando os itens: I (monetário e crédito) corretos; IV (derivativos e capitais) corretos; V (câmbio e seguros/previdência) corretos. Os itens II (consumidor) e III (concorrente) não são mercados do sistema. Por isso a alternativa D (I, IV e V) é a correta.","id":"9517"},{"n":144,"banco":"lucas","mod":1,"tit":"I","titn":"Sistema Financeiro Nacional e Participantes do Mercado","cap":"3","capn":"Questão 3 (cód. 9518)","stem":"É no mercado monetário que se concentram as operações para controle da oferta da moeda e taxa de juros de curto prazo, com o objetivo de garantir a liquidez da economia. Sendo que, o Bacen, Banco Central do Brasil, atua nesse mercado através da prática de:","opts":[["a","Normatização da concorrência."],["b","Controle de câmbio."],["c","Política monetária."],["d","Fiscalização da Previdência."]],"ans":"c","exp":"Tema: mercado monetário e política monetária. O mercado monetário concentra as operações de controle da oferta de moeda e dos juros de curto prazo, e o Bacen atua nele por meio da política monetária. A alternativa C é a correta. A normatização da concorrência (A) não é função do Bacen, o controle de câmbio (B) é apenas parte do papel do Bacen e não define o mercado monetário, e a fiscalização da previdência (D) é da Previc ou da Susep.","id":"9518"},{"n":145,"banco":"lucas","mod":1,"tit":"I","titn":"Sistema Financeiro Nacional e Participantes do Mercado","cap":"4","capn":"Questão 4 (cód. 9519)","stem":"Qual o mercado onde instituições financeiras e não financeiras prestam serviço de intermediação de recursos para agentes que necessitam de recursos para consumo ou capital de giro?","opts":[["a","Mercado Fornecedor."],["b","Mercado de Capitais"],["c","Mercado de Derivativos."],["d","Mercado de crédito."]],"ans":"d","exp":"Tema: mercado de crédito. É onde instituições financeiras e não financeiras intermedeiam recursos para agentes que precisam de financiamento para consumo ou capital de giro. A alternativa D é a correta. Mercado de capitais (B) e de derivativos (C) são outros mercados do SFN, e o \"mercado fornecedor\" (A) não existe como categoria.","id":"9519"},{"n":146,"banco":"lucas","mod":1,"tit":"I","titn":"Sistema Financeiro Nacional e Participantes do Mercado","cap":"5","capn":"Questão 5 (cód. 9520)","stem":"Acerca do Mercado de Câmbio, um dos grandes mercados do Sistema Financeiro Nacional (SFN), analise as afirmações abaixo e assinale V para verdadeiro e F para falso: ( ) Trata-se de um Mercado onde são negociadas trocas de moedas estrangeiras por reais. ( ) Negocia os títulos da dívida pública Federal, Estadual e Municipal. ( ) É nele que se coíbe abusos, fraudes e práticas ilegais em operações que envolvam títulos ou valores mobiliários negociados a partir de moeda estrangeira. ( ) Tem o Bacen como órgão responsável por administrar, fiscalizar e controlar as taxas de câmbio. Qual a ordem correta?","opts":[["a","V, F, F, V."],["b","F, V, F, V."],["c","V, F, V, F."],["d","F, F, V, V."]],"ans":"a","exp":"Tema: mercado de câmbio. Analisando:\n\n( ) Verdadeiro. O mercado de câmbio negocia trocas de moedas estrangeiras por reais.\n\n( ) Falso. Negociação de títulos da dívida pública é do mercado de títulos públicos e de renda fixa, e não do câmbio.\n\n( ) Falso. Coibir abusos, fraudes e práticas ilegais em valores mobiliários é função da CVM, no mercado de capitais, e não do câmbio.\n\n( ) Verdadeiro. O Bacen administra, fiscaliza e controla as taxas de câmbio.\n\nA sequência correta é V, F, F, V, que corresponde à alternativa A.","id":"9520"},{"n":147,"banco":"lucas","mod":1,"tit":"I","titn":"Sistema Financeiro Nacional e Participantes do Mercado","cap":"6","capn":"Questão 6 (cód. 9521)","stem":"O Mercado de Capitais busca, principalmente, canalizar recursos dos agentes econômicos para a capitalização das empresas de capital aberto, por meio de operações com títulos e valores mobiliários em mercados de bolsa e balcão. Sendo assim, suas operações são realizadas nos:","opts":[["a","Mercado Cambial."],["b","Mercado de Mutualização e Mercado de Balcão."],["c","Mercado Interbancário."],["d","Mercado Primário e Mercado Secundário."]],"ans":"d","exp":"Tema: mercado de capitais. Ele canaliza recursos para a capitalização de empresas de capital aberto, por meio de títulos e valores mobiliários negociados em bolsa e balcão. Essas operações se dão no mercado primário, quando a empresa emite os títulos e os vende pela primeira vez, e no mercado secundário, quando os investidores negociam entre si. A alternativa D é a correta. As demais alternativas trazem mercados ou termos que não se aplicam, como mercado cambial e interbancário.","id":"9521"},{"n":148,"banco":"lucas","mod":1,"tit":"I","titn":"Sistema Financeiro Nacional e Participantes do Mercado","cap":"7","capn":"Questão 7 (cód. 9522)","stem":"Qual o principal órgão responsável por controlar, normatizar e fiscalizar o Mercado de Capitais?","opts":[["a","Banco Central"],["b","Comissão de Valores Mobiliários (CVM)"],["c","Conselho Nacional de Seguros Privados (CNSP)"],["d","Conselho de Controle de Atividades Financeiras (COAF)"]],"ans":"b","exp":"Tema: órgão responsável pelo mercado de capitais. A Comissão de Valores Mobiliários controla, normatiza e fiscaliza o mercado de valores mobiliários. A alternativa B é a correta. O Banco Central (A) regula o sistema bancário e o câmbio, o CNSP (C) regula seguros, e o COAF (D) combate a lavagem de dinheiro.","id":"9522"},{"n":149,"banco":"lucas","mod":1,"tit":"I","titn":"Sistema Financeiro Nacional e Participantes do Mercado","cap":"8","capn":"Questão 8 (cód. 9523)","stem":"Sobre o Mercado Derivativo, assinale o que for correto: I. Sua existência e a formação de preço estão vinculados ao grau de risco e as diferentes expectativas quanto ao comportamento passado dos preços de um outro produto/ mercado. II. Sua principal função é oferecer aos agentes econômicos mecanismos de proteção contra o risco de variação de preços de determinado ativo ou mercadoria. III. Um produto/mercado é derivativo quando sua existência e formação de preço estão vinculados ao grau de risco e as diferentes expectativas quanto ao futuro comportamento dos preços de um outro produto/ mercado. IV. Derivativos são contratos que derivam a maior parte de seu valor de um ativo subjacente, taxa de referência ou índice. O ativo subjacente deve ser exclusivamente abstrato, tais como as tomadas de decisões políticas. Quais estão corretas?","opts":[["a","Apenas I e II."],["b","Apenas II e III."],["c","Apenas III e IV."],["d","Apenas IV e V."]],"ans":"b","exp":"Tema: mercado derivativo. Analisando:\n\nI. Errado. A existência e a formação de preço do derivativo dependem das expectativas quanto ao comportamento futuro, e não do passado.\n\nII. Correto. O derivativo serve principalmente para proteção contra variação de preços.\n\nIII. Correto. Um produto é derivativo quando seu preço depende do futuro de outro produto ou mercado.\n\nIV. Errado. O ativo subjacente pode ser concreto ou abstrato, como ações, moedas, juros e índices. A afirmação de que deve ser exclusivamente abstrato está errada.\n\nA alternativa B (II e III) é a correta.","id":"9523"},{"n":150,"banco":"lucas","mod":1,"tit":"I","titn":"Sistema Financeiro Nacional e Participantes do Mercado","cap":"9","capn":"Questão 9 (cód. 9524)","stem":"Acerca do Conselho Monetário Nacional (CMN) assinale o que for correto: I. É o órgão normativo responsável pela fixação das diretrizes das políticas monetárias, creditícia e cambial do país. II. Tem como objetivo estimular investimentos no mercado acionário. III. Sua função é coibir abusos, fraudes e práticas ilegais em operações que envolvam títulos ou valores mobiliários. IV. Objetiva divulgar estudos de análise econômica conjuntural para guiar os participantes dos mercados de derivativos. Quais estão corretas?","opts":[["a","Apenas I e II."],["b","Apenas III e IV."],["c","Apenas I, II e III."],["d","Apenas II, III e IV."]],"ans":"c","exp":"Tema: funções do CMN. O CMN é o órgão normativo que fixa diretrizes das políticas monetária, creditícia e cambial, por isso o item I está correto. Os itens II (estimular o mercado acionário), III (coibir abusos com valores mobiliários) e IV (divulgar estudos para derivativos) não são funções do CMN, e pertencem à CVM ou a outros órgãos.\n\nA alternativa correta, pela análise, seria apenas o I. Essa alternativa não aparece entre as opções, e o gabarito indica C (I, II e III), que contém dois itens que não são funções do CMN. Esta é uma divergência de chave a conferir no material original.","id":"9524"},{"n":151,"banco":"lucas","mod":1,"tit":"I","titn":"Sistema Financeiro Nacional e Participantes do Mercado","cap":"10","capn":"Questão 10 (cód. 9525)","stem":"Os principais órgãos supervisores do SFN subordinam-se ao Conselho Monetário Nacional (CMN). Dentre eles, o Banco Central do Brasil e a Comissão de Valores Mobiliários. Mas, o que compete à Comissão e Valores Mobiliários?","opts":[["a","Inspecionar as companhias abertas dada prioridade às que não apresentem lucro em balanço ou às que deixem de pagar o dividendo mínimo obrigatório."],["b","Estabelecer as diretrizes da política cambial."],["c","Fixar taxas e emolumentos."],["d","O funcionamento de um mercado de balcão."]],"ans":"a","exp":"Tema: competência da CVM. A CVM inspeciona as companhias abertas, dando prioridade às que não apresentam lucro ou não pagam o dividendo mínimo obrigatório. A alternativa A é a correta.\n\nA política cambial (B) é função do CMN e do Bacen. Fixar taxas e emolumentos (C) não é competência da CVM como regra geral. Operar o mercado de balcão (D) é atribuição da B3 e de suas regras, e não da CVM.","id":"9525"},{"n":152,"banco":"lucas","mod":1,"tit":"I","titn":"Sistema Financeiro Nacional e Participantes do Mercado","cap":"11","capn":"Questão 11 (cód. 9526)","stem":"A Comissão de Valores Mobiliários é uma entidade autárquica, vinculada ao governo através do Ministério da Fazenda. Entre seus objetivos, está a proteção dos titulares contra a emissão fraudolenta, manipulação de preços e outros atos ilegais. Qual a penalidade a CVM pode aplicar àqueles que desrespeitem a norma?","opts":[["a","Prestação de serviço comunitário"],["b","Cancelamento do Cadastro de Pessoa Física (CPF)"],["c","Multa"],["d","Bloqueio do Cadastro Nacional de Pessoa Jurídica (CNPJ)"]],"ans":"c","exp":"Tema: penalidades da CVM. A CVM pode aplicar sanções administrativas, sendo a principal delas a multa. A alternativa C é a correta. CPF e CNPJ não são cancelados ou bloqueados como sanção, e a prestação de serviço comunitário não é penalidade prevista para o mercado de valores mobiliários.","id":"9526"},{"n":153,"banco":"lucas","mod":1,"tit":"I","titn":"Sistema Financeiro Nacional e Participantes do Mercado","cap":"12","capn":"Questão 12 (cód. 9527)","stem":"O Conselho Nacional de Previdência Complementar (CNPC) é o órgão que regula o regime de previdência complementar operado pelas entidades fechadas de previdência complementar. Sendo, necessariamente, presidido por:","opts":[["a","Representante da Secretaria Política"],["b","Representante do Ministério da Fazenda"],["c","Representante do Banco Central"],["d","Representante da Coaf"]],"ans":"b","exp":"Tema: presidência do CNPC. O Conselho Nacional de Previdência Complementar, que regula as entidades fechadas de previdência, é presidido por um representante do Ministério da Fazenda. A alternativa B é a correta. A Secretaria Política (A), o Bacen (C) e o Coaf (D) não presidem o conselho.","id":"9527"},{"n":154,"banco":"lucas","mod":1,"tit":"I","titn":"Sistema Financeiro Nacional e Participantes do Mercado","cap":"13","capn":"Questão 13 (cód. 9528)","stem":"Acerca do Conselho de Recursos do Sistema Financeiro Nacional (CRSFN), considere V para verdadeiro e F para falso: Trata-se de uma Entidade Supervisora Julga em última instância administrativa, as sanções aplicadas pelo Conselho de Controle de Atividades Financeiras (Coaf), exceto no caso de lavagem de dinheiro. Trata-se de um Órgão Normativo. Tem por finalidade julgar, em última instância administrativa, os recursos contra as sanções aplicadas pelo Banco Central do Brasil (BCB) e Comissão de Valores Mobiliários (CVM). Qual a ordem correta?","opts":[["a","V, F, F, V."],["b","F, V, V, F."],["c","V, V, F, F."],["d","F, F, V, V."]],"ans":"d","exp":"Tema: CRSFN. Analisando os itens (pela ordem do enunciado):\n\nItem 1: o CRSFN é um órgão de recurso administrativo, e não uma entidade supervisora. Falso.\n\nItem 2: o CRSFN não é órgão normativo. Falso.\n\nItem 3: o CRSFN julga, em última instância administrativa, os recursos contra as sanções do Bacen e da CVM. Verdadeiro.\n\nItem 4: a afirmação sobre julgar sanções do Coaf não corresponde à sua competência principal. Esta análise depende da redação completa.\n\nPela chave, a alternativa D (F, F, V, V) é a correta.","id":"9528"},{"n":155,"banco":"lucas","mod":1,"tit":"I","titn":"Sistema Financeiro Nacional e Participantes do Mercado","cap":"14","capn":"Questão 14 (cód. 9529)","stem":"Sobre a estrutura do Sistema Financeiro Nacional, analise as asserções abaixo: I. O Conselho Monetário Nacional, dentro do SFN, possui função fiscalizadora. II. A CMN apenas fiscaliza, enquanto o Bacen executa a supervisão. A respeito dessas asserções, assinale a opção correta.","opts":[["a","As asserções I e II são proposições verdadeiras, e a II é uma justificativa correta da I."],["b","A asserção I é uma proposição verdadeira, e a II é uma proposição falsa."],["c","A asserção I é uma proposição falsa, e a II é uma proposição verdadeira."],["d","As asserções I e II são proposições falsas."]],"ans":"d","exp":"Tema: estrutura do SFN. A asserção I é falsa: o CMN é normativo, e não tem função fiscalizadora. A asserção II também é falsa: o CMN não fiscaliza, e a supervisão é feita pelo Bacen e pela CVM, que são órgãos executores. Por isso a alternativa D (ambas falsas) é a correta.","id":"9529"},{"n":156,"banco":"lucas","mod":1,"tit":"I","titn":"Sistema Financeiro Nacional e Participantes do Mercado","cap":"15","capn":"Questão 15 (cód. 9531)","stem":"Quem é responsável por conduzir a Política Monetária dentro do SFN?","opts":[["a","Bolsa de Valores"],["b","Bacen"],["c","Administradoras de Cartão de Crédito"],["d","Conselho Monetário Nacional"]],"ans":"b","exp":"Tema: condução da política monetária. A política monetária é conduzida pelo Bacen, por meio do Copom e de seus instrumentos, como a taxa Selic e os depósitos compulsórios. A alternativa B é a correta. O CMN (D) fixa diretrizes, mas não conduz a política no dia a dia. A Bolsa (A) e as administradoras de cartão (C) não têm essa função.","id":"9531"},{"n":157,"banco":"lucas","mod":1,"tit":"I","titn":"Sistema Financeiro Nacional e Participantes do Mercado","cap":"16","capn":"Questão 16 (cód. 9532)","stem":"Dentre as Entidades Supervisoras, quem é responsável pelo controle e fiscalização do mercado de seguro, previdência privada aberta e capitalização?","opts":[["a","Bacen"],["b","CVM"],["c","PREVIC"],["d","SUSEP"]],"ans":"d","exp":"Tema: supervisão de seguros, previdência aberta e capitalização. Esse mercado é regulado pelo CNSP e supervisionado pela Susep. A alternativa D é a correta. O Bacen (A) regula bancos, a CVM (B) regula o mercado de valores mobiliários, e a Previc (C) supervisiona a previdência fechada, com fundos de pensão.","id":"9532"},{"n":158,"banco":"lucas","mod":1,"tit":"I","titn":"Sistema Financeiro Nacional e Participantes do Mercado","cap":"17","capn":"Questão 17 (cód. 9533)","stem":"Qual a principal função das instituições que atuam como operadoras do Sistema Financeiro?","opts":[["a","Realizar a transferência de recursos entre os agentes econômicos."],["b","Desenvolver atividade similar àquelas realizadas pelos órgãos normativos."],["c","Fiscalizar as seguradoras e corretoras de seguro."],["d","Regular o investido em crédito financiado e investimento."]],"ans":"a","exp":"Tema: função das instituições operadoras do SFN. Elas realizam a transferência de recursos entre os agentes econômicos, por meio de captação, aplicação e intermediação. A alternativa A é a correta. As demais descrevem funções de órgãos normativos ou de fiscalização, que não são o papel das operadoras.","id":"9533"},{"n":159,"banco":"lucas","mod":1,"tit":"I","titn":"Sistema Financeiro Nacional e Participantes do Mercado","cap":"18","capn":"Questão 18 (cód. 9534)","stem":"Sobre os Bancos Comerciais, assinale o que for correto: I. Tratam-se de instituições financeiras reguladas e fiscalizadas pelo CVM. II. São instituições financeiras reguladas e fiscalizadas pelo BACEN. III. Diz-se de instituições financeiras exclusivamente privadas. IV. Podem ser consideradas a base do sistema monetário. Quais estão corretas?","opts":[["a","Apenas I e II"],["b","Apenas II e III"],["c","Apenas III e IV"],["d","Apenas II e IV."]],"ans":"d","exp":"Tema: bancos comerciais. Analisando:\n\nI. Errado. Os bancos comerciais são reguladas e fiscalizadas pelo Bacen, e não pela CVM.\n\nII. Correto. Eles são reguladas e fiscalizados pelo Bacen.\n\nIII. Errado. Os bancos comerciais podem ser públicos ou privados, então \"exclusivamente privadas\" não procede.\n\nIV. Correto. Os bancos comerciais são a base do sistema monetário, pela capacidade de criar moeda escritural.\n\nA alternativa D (II e IV) é a correta.","id":"9534"},{"n":160,"banco":"lucas","mod":1,"tit":"I","titn":"Sistema Financeiro Nacional e Participantes do Mercado","cap":"19","capn":"Questão 19 (cód. 9535)","stem":"A função dos Bancos Comerciais é proporcionar o suprimento de recursos para financiar a indústria, o comércio, as empresas e as pessoas físicas em que prazo?","opts":[["a","Curto prazo"],["b","Médio prazo"],["c","Longo prazo"],["d","Curto e médio prazo"]],"ans":"d","exp":"Tema: prazo de atuação dos bancos comerciais. Eles suprem recursos de curto e médio prazo para indústria, comércio, empresas e pessoas físicas. A alternativa D é a correta. O longo prazo (C) é característica dos bancos de investimento e de desenvolvimento.","id":"9535"},{"n":161,"banco":"lucas","mod":1,"tit":"I","titn":"Sistema Financeiro Nacional e Participantes do Mercado","cap":"20","capn":"Questão 20 (cód. 9536)","stem":"Sobre as Caixas Econômicas, analise as asserções a seguir: I. Caixas econômicas são empresas públicas que exercem atividades totalmente divergentes daquelas exercidas pelo Banco Comercial. II. O único ponto de congruência entre Caixas Econômicas e Bancos Comerciais é o foco na concessão de empréstimos e financiamentos de programas e projetos nas áreas de assistência social, saúde, educação, trabalho e esporte. A respeito dessas asserções, assinale a opção correta.","opts":[["a","As asserções I e II são proposições verdadeiras, e a II é uma justificativa correta da I."],["b","A asserção I é uma proposição verdadeira, e a II é uma proposição falsa."],["c","A asserção I é uma proposição falsa, e a II é uma proposição verdadeira."],["d","As asserções I e II são proposições falsas."]],"ans":"d","exp":"Tema: caixas econômicas. Analisando:\n\nI. Errado. Caixas econômicas são empresas públicas que, em parte, atuam de forma semelhante aos bancos comerciais, com depósitos, crédito e serviços. Dizer que são totalmente divergentes é um exagero.\n\nII. Errado. Há mais de um ponto de convergência com os bancos comerciais, como os serviços bancários e a captação de depósitos.\n\nComo as duas afirmações são falsas, a alternativa D é a correta.","id":"9536"},{"n":162,"banco":"lucas","mod":1,"tit":"I","titn":"Sistema Financeiro Nacional e Participantes do Mercado","cap":"21","capn":"Questão 21 (cód. 9537)","stem":"As Cooperativas de crédito são definidas como instituições financeiras formadas pela associação de pessoas para prestar serviços financeiros exclusivamente aos seus associados. Sobre as Cooperativas de crédito, assinale o que for correto: I. Os cooperados são usuários da cooperativa que usufruem dos produtos, enquanto os donos fazem a gestão. II. Como os cooperados são donos e usuários da cooperativa eles têm igual poder de voto. III. Nas cooperativas de crédito, os usuários encontram os principais serviços de banco. IV. Os bancos cooperativos não estão subordinados à legislação e regulamentação aplicáveis aos bancos comerciais, apenas àquelas aplicáveis aos bancos múltiplos em geral.","opts":[["a","Apenas I e II."],["b","Apenas II e III."],["c","Apenas III e IV."],["d","Apenas I e IV."]],"ans":"b","exp":"Tema: cooperativas de crédito. Analisando:\n\nI. Errado. Os cooperados são ao mesmo tempo donos e usuários, e a gestão é feita pelos próprios cooperados eleitos. A afirmação de que um grupo usufrui e outro gere não descreve a cooperativa.\n\nII. Correto. Cada cooperado tem um voto, independentemente do capital investido, o que dá igual poder de voto.\n\nIII. Correto. Nas cooperativas, os usuários encontram os principais serviços de banco.\n\nIV. Errado. Os bancos cooperativos seguem a legislação aplicável aos bancos comerciais e múltiplos, e não só aos múltiplos.\n\nA alternativa B (II e III) é a correta.","id":"9537"},{"n":163,"banco":"lucas","mod":1,"tit":"I","titn":"Sistema Financeiro Nacional e Participantes do Mercado","cap":"22","capn":"Questão 22 (cód. 9538)","stem":"Bancos de Investimentos são instituições financeiras privadas especializadas em operações de participação societária de caráter temporário, de financiamento da atividade produtiva para suprimento de capital fixo e de giro, e de administração de recursos de terceiros. Sobre o tema, analise as afirmações abaixo: I. Entre as principais operações de um Banco de Investimento está a administração de fundos de investimentos. II. Assim como os bancos comerciais, os bancos de investimento recebem depósito. III. São instituições financeiras reguladas e fiscalizadas pelo CMN. IV. A função dos bancos de investimentos é dilatar o prazo das operações de empréstimos e financiamentos, fortalecendo o processo de capitalização das empresas na compra de equipamentos e na subscrição de ações e debênture. Quais estão corretas","opts":[["a","Apenas I, IV."],["b","Apenas II e III."],["c","Apenas III e IV."],["d","Apenas I, II e III."]],"ans":"a","exp":"Tema: bancos de investimento. Analisando:\n\nI. Correto. A administração de fundos de investimento é uma das principais operações do banco de investimento.\n\nII. Errado. O banco de investimento capta por depósito a prazo, e não recebe depósito à vista, que é privilégio dos bancos comerciais. A comparação do item está incorreta.\n\nIII. Errado. Os bancos de investimento são regulados e fiscalizados pelo Bacen, e não pelo CMN.\n\nIV. Correto. Um dos papéis do banco de investimento é alongar o prazo das operações, fortalecendo a capitalização das empresas.\n\nA alternativa A (I e IV) é a correta.","id":"9538"},{"n":164,"banco":"lucas","mod":1,"tit":"I","titn":"Sistema Financeiro Nacional e Participantes do Mercado","cap":"23","capn":"Questão 23 (cód. 9539)","stem":"Os Bancos Múltiplos são instituições financeiras, privadas ou públicas, que captam depósitos à vista e realizam operações ativas, passivas e acessórias das diversas instituições financeiras, por intermédio de algumas carteiras. O banco múltiplo deve ser constituído com, no mínimo, duas carteiras, sendo obrigatoriamente, uma delas:","opts":[["a","Comercial ou de Crédito imobiliário."],["b","Comercial ou de Desenvolvimento."],["c","Comercial ou de Investimentos."],["d","De investimento e de Crédito financeiro."]],"ans":"c","exp":"Tema: banco múltiplo. Ele é constituído com pelo menos duas carteiras, e uma delas precisa ser obrigatoriamente a comercial ou a de investimento. A alternativa C é a correta. A carteira de desenvolvimento (B) e a de crédito imobiliário (A) não são obrigatórias nesse sentido. A alternativa D inventa uma carteira de crédito financeiro que não existe.","id":"9539"},{"n":165,"banco":"lucas","mod":1,"tit":"I","titn":"Sistema Financeiro Nacional e Participantes do Mercado","cap":"24","capn":"Questão 24 (cód. 9540)","stem":"O Mercado de Capitais pode ser definido como um sistema de distribuição de valores mobiliários que tem o propósito de viabilizar a capitalização das empresas e dar liquidez aos títulos emitidos por elas. No contexto do mercado de capitais, verifique as assertivas apresentadas a seguir e assinale a alternativa correta: I. O Mercado de Capitais também oferece alternativas rentáveis e totalmente seguras de investimento, não envolvendo riscos de qualquer natureza. II. Os participantes do Mercado de Capitais podem ser divididos em dois grupos: os que normatizam e os que operacionalizam. III. Bolsas de valores, emissores, e sociedades corretoras, por exemplo, fazem parte do Mercado de Capitais.","opts":[["a","Apenas as assertivas I e II estão corretas."],["b","Apenas as assertivas I e III estão corretas."],["c","Apenas as assertivas II e III estão corretas."],["d","Apenas a assertiva III está correta."]],"ans":"c","exp":"Tema: participantes do mercado de capitais. Analisando: I. Errado. Não existe investimento totalmente seguro, pois todo investimento envolve algum risco. II. Correto. Os participantes podem ser divididos entre os que normatizam e os que operacionalizam. III. Correto. Bolsas de valores, emissores e sociedades corretoras fazem parte do mercado de capitais. A alternativa C (II e III) é a correta.","id":"9540"},{"n":166,"banco":"lucas","mod":1,"tit":"I","titn":"Sistema Financeiro Nacional e Participantes do Mercado","cap":"25","capn":"Questão 25 (cód. 9541)","stem":"Pode-se dizer que a principal função do Sistema Financeiro Nacional é viabilizar a intermediação entre poupança e investimento, possibilitando ao setor produtivo maior eficiência. Quanto à sua composição, o Sistema Financeiro Nacional pode ser subdividido em entidades , e . Partindo do exposto, assinale a alternativa com as três subdivisões do Sistema Nacional Financeiro, preenchendo corretamente as lacunas:","opts":[["a","Normativas, burocráticas e técnicas."],["b","Normativas, supervisoras e operacionais."],["c","Supervisoras, operacionais e estratégicas."],["d","Supervisoras, executoras, dirigentes."]],"ans":"b","exp":"Tema: subdivisões do SFN. O sistema se divide em entidades normativas, supervisoras e operacionais. A alternativa B é a correta. As demais alternativas trazem termos que não são as categorias do SFN.","id":"9541"},{"n":167,"banco":"lucas","mod":1,"tit":"I","titn":"Sistema Financeiro Nacional e Participantes do Mercado","cap":"26","capn":"Questão 26 (cód. 9542)","stem":"De maneira geral, o Subsistema Normativo é o responsável pelo funcionamento do mercado financeiro e de suas instituições. Sua composição se dá através de instituições tais quais: Conselho Monetário Nacional – CMN; Banco Central – BACEN; Comissão de Valores Mobiliários – CVM entre outras. Neste contexto, verifique as assertivas apresentadas a seguir e assinale a alternativa correta: I. O Conselho Monetário Nacional – CMN é o órgão supremo do Sistema Financeiro Nacional cuja finalidade é fixar diretrizes para as políticas monetária, creditícia e cambial do país. II. O Banco Central – BACEN tem como principal competência regular e supervisionar o Sistema Financeiro Nacional, bem como controlar o fluxo de capitais. Não é, por exemplo, uma atribuição do BACEN a emissão de papel moeda, pois esta é uma atribuição do CMN. III. A Comissão de Valores Mobiliários – CVM tem como principal objetivo disciplinar, fiscalizar e promover a expansão, o desenvolvimento e o funcionamento eficiente do mercado de valores mobiliários, sob orientação do CMN.","opts":[["a","Apenas as assertivas I e II estão corretas."],["b","Apenas as assertivas I e III estão corretas."],["c","Apenas as assertivas II e III estão corretas."],["d","As assertivas I, II e III estão corretas."]],"ans":"b","exp":"Tema: subsistema normativo. Analisando:\n\nI. Correto. O CMN é o órgão máximo do SFN e fixa diretrizes das políticas monetária, creditícia e cambial.\n\nII. Errado. A emissão de papel-moeda é atribuição do Bacen, que executa o meio circulante, e não do CMN. O item inverte a competência. Além disso, o Bacen não tem a principal competência de regular o SFN, que é do CMN.\n\nIII. Correto. A CVM disciplina e fiscaliza o mercado de valores mobiliários, com orientação do CMN.\n\nPor isso a alternativa correta seria a B (I e III). O gabarito indica B, que é coerente com essa análise.","id":"9542"},{"n":168,"banco":"lucas","mod":1,"tit":"I","titn":"Sistema Financeiro Nacional e Participantes do Mercado","cap":"27","capn":"Questão 27 (cód. 9543)","stem":"O Banco Nacional de Desenvolvimento Econômico (BNDES) é uma empresa pública federal, com personalidade jurídica e de direito privado e patrimônio próprio, vinculado ao Ministério da Economia e que tem como principal objetivo:","opts":[["a","Intermediação entre depositantes e tomadores de crédito. Atuar tanto na prestação de serviços tais como conta corrente; depósitos diversos; pagamento de cheques; transferências; ordens de pagamento; etc."],["b","Apoiar empreendimentos que contribuam para o desenvolvimento do país, através de financiamento de longo prazo e investimentos em todos os segmentos da economia brasileira."],["c","Realizar empréstimos de capital fixo ou de giro e captar recursos por meio de depósitos a prazo e interfinanceiros."],["d","Realizar compra e venda de moeda estrangeira."]],"ans":"b","exp":"Tema: BNDES. É uma empresa pública federal, vinculada ao Ministério da Economia, que apoia empreendimentos de desenvolvimento do país, por meio de financiamento de longo prazo em todos os setores da economia. A alternativa B é a correta. As outras alternativas descrevem funções de bancos comerciais ou de outras instituições.","id":"9543"},{"n":169,"banco":"lucas","mod":1,"tit":"I","titn":"Sistema Financeiro Nacional e Participantes do Mercado","cap":"28","capn":"Questão 28 (cód. 9501)","stem":"Entre as atribuições da Comissão de Valores Mobiliários (CVM), pode se afirmar que:","opts":[["a","É responsável por fiscalizar e inspecionar as companhias abertas"],["b","Executar a política cambial"],["c","É responsável por regular os limites mínimos de emolumentos e comissões do mercado"],["d","Realiza autorização de funcionamento para instituições financeiras"]],"ans":"a","exp":"Tema: atribuições da CVM. A CVM fiscaliza e inspeciona as companhias abertas, como competência específica. A alternativa A é a correta. A política cambial (B) é do CMN e do Bacen, a fixação de emolumentos (C) não é regra geral da CVM, e a autorização de instituições financeiras (D) é do Bacen.","id":"9501"},{"n":170,"banco":"lucas","mod":1,"tit":"I","titn":"Sistema Financeiro Nacional e Participantes do Mercado","cap":"29","capn":"Questão 29 (cód. 9502)","stem":"Uma entidade fechada de previdência privada é classificada, de acordo com a CVM, como:","opts":[["a","Sociedade seguradora"],["b","Investidor não residente"],["c","Instituição financeira"],["d","Investidor qualificado"]],"ans":"d","exp":"Tema: classificação de entidade fechada de previdência pela CVM. A apostila lista as entidades abertas e fechadas de previdência complementar entre os investidores profissionais. Por isso a classificação correta seria profissional, e nenhuma alternativa traz essa categoria. A alternativa D (investidor qualificado) é a mais próxima das opções, mas não corresponde ao texto desta edição. Vale conferir a categoria no material original.","id":"9502"},{"n":171,"banco":"lucas","mod":1,"tit":"I","titn":"Sistema Financeiro Nacional e Participantes do Mercado","cap":"30","capn":"Questão 30 (cód. 9503)","stem":"Julgue as afirmativas abaixo e assinale a alternativa incorreta sobre a CVM:","opts":[["a","Negociação e intermediação no mercado de valores mobiliários são fiscalizadas pela CVM"],["b","São atribuições da CVM: fiscalizar e inspecionar empresas de capital aberto, especialmente as que não apresentem lucro em seu balanço ou não paguem o dividendo mínimo obrigatório"],["c","Realiza fiscalização às instituições financeiras que emitam títulos públicos federais e debêntures"],["d","Emissão e distribuição de valores mobiliários são fiscalizados pela CVM"]],"ans":"c","exp":"Tema: CVM, com a alternativa incorreta. Analisando:\n\nA) Correta. Negociação e intermediação de valores mobiliários são fiscalizadas pela CVM.\n\nB) Correta. A CVM fiscaliza as companhias abertas, com prioridade às que não lucram ou não pagam o dividendo.\n\nC) Incorreta. Quem fiscaliza as instituições financeiras que emitem títulos públicos federais é o Bacen, e não a CVM.\n\nD) Correta. A emissão e a distribuição de valores mobiliários são fiscalizadas pela CVM.\n\nA alternativa C é a incorreta, e é a resposta da questão.","id":"9503"},{"n":172,"banco":"lucas","mod":1,"tit":"I","titn":"Sistema Financeiro Nacional e Participantes do Mercado","cap":"31","capn":"Questão 31 (cód. 9504)","stem":"Refere – se a uma competência da SU- SEP:","opts":[["a","Realizar treinamentos aos profissionais do mercado de seguros"],["b","Criar normas e diretrizes para o mercado de seguro e cosseguro"],["c","Atuar na comercialização de apólice de seguros"],["d","Realizar a autorização de funcionamento de instituições seguradoras"]],"ans":"d","exp":"Tema: competência da Susep. A Susep autoriza o funcionamento das instituições seguradoras. A alternativa D é a correta. Treinamentos (A), normas de seguro (B), e comercialização de apólices (C) não são competências da Susep: as normas são do CNSP e a comercialização é feita pelas seguradoras e corretoras.","id":"9504"},{"n":173,"banco":"lucas","mod":1,"tit":"I","titn":"Sistema Financeiro Nacional e Participantes do Mercado","cap":"32","capn":"Questão 32 (cód. 9505)","stem":"Antecedente ao início de negociações no Brasil, os investidores não residentes tem por obrigação:","opts":[["a","Constituir um ou mais representantes"],["b","Registrar – se junto à ANBIMA"],["c","Caso o representante for PF ou PJ não financeira, o investidor deve nomear instituição autorizada a funcionar pela CVM, do qual será corresponsável pelo cumprimento das obrigações"],["d","Registrar – se junto ao Banco Central do Brasil"]],"ans":"a","exp":"Tema: obrigações do investidor não residente antes de negociar no Brasil. Ele deve constituir um ou mais representantes, como o legal, o fiscal e o custodiante. A alternativa A é a correta. Registro na ANBIMA (B) e no Bacen (D) não são as obrigações principais descritas. A alternativa C mistura a nomeação com a autorização pela CVM, o que não corresponde à regra apresentada na apostila.","id":"9505"},{"n":174,"banco":"lucas","mod":1,"tit":"I","titn":"Sistema Financeiro Nacional e Participantes do Mercado","cap":"33","capn":"Questão 33 (cód. 9506)","stem":"Uma das atribuições das sociedades de crédito, financiamento e investimento é de financiar:","opts":[["a","Bens de consumo duráveis por meio do crédito direto ao consumidor (CDC)"],["b","Bens de consumo e produção por meio do lançamento de eurobonds"],["c","Bens duráveis e ativos mobiliários por meio do lançamento de debêntures"],["d","O comércio e a indústria de modo geral"]],"ans":"a","exp":"Tema: sociedades de crédito, financiamento e investimento (financeiras). Elas financiam o consumo de bens duráveis por meio do crédito direto ao consumidor (CDC). A alternativa A é a correta. Eurobonds (B) e debêntures (C) são instrumentos de captação de empresas, e não a atribuição das financeiras. A alternativa D (comércio e indústria em geral) é função mais ampla dos bancos comerciais.","id":"9506"},{"n":175,"banco":"lucas","mod":1,"tit":"I","titn":"Sistema Financeiro Nacional e Participantes do Mercado","cap":"34","capn":"Questão 34 (cód. 9507)","stem":"Dentre as atribuições do Banco Central do Brasil (BACEN), assinale a alternativa que descreve uma de suas funções:","opts":[["a","Fiscalizar e disciplinar as operações com valores mobiliários"],["b","É uma autarquia federal que gerencia o sistema financeiro"],["c","É uma autarquia federal que realiza a fiscalização no mercado aberto de títulos"],["d","É um banco privado que realiza o gerenciamento do sistema financeiro"]],"ans":"b","exp":"Tema: função do Bacen. O Banco Central é uma autarquia federal que gerencia o sistema financeiro, por meio de normas, fiscalização e execução de políticas. A alternativa B é a correta. As demais atribuem ao Bacen funções de valores mobiliários (A), de mercado aberto (C) ou o descrevem como banco privado (D), o que não é verdadeiro.","id":"9507"},{"n":176,"banco":"lucas","mod":1,"tit":"I","titn":"Sistema Financeiro Nacional e Participantes do Mercado","cap":"35","capn":"Questão 35 (cód. 9508)","stem":"As metas de inflação são determinadas, originalmente, pelo:","opts":[["a","Comissão de Valores Mobiliários"],["b","Banco Central do Brasil"],["c","Comitê de Política Monetária"],["d","Conselho Monetário Nacional"]],"ans":"d","exp":"Tema: metas de inflação. Quem determina originalmente as metas de inflação é o Conselho Monetário Nacional, que fixa as diretrizes da política monetária. O Copom executa a política e o Bacen a implementa. A alternativa D é a correta.","id":"9508"},{"n":177,"banco":"lucas","mod":1,"tit":"I","titn":"Sistema Financeiro Nacional e Participantes do Mercado","cap":"36","capn":"Questão 36 (cód. 9509)","stem":"Assinale a alternativa que caracteriza um investidor não residente:","opts":[["a","Qualquer investidor que possua recursos aplicados no exterior"],["b","Investidor que não possui residência fixa no Brasil"],["c","Pessoa física, jurídica ou fundo de investimento com sede no exterior e investimento no Brasil"],["d","Pessoa física, jurídica ou fundo de investimento com sede no Brasil e investimento no exterior"]],"ans":"c","exp":"Tema: investidor não residente. É a pessoa física, jurídica ou fundo de investimento com residência, sede ou domicílio no exterior, que investe no Brasil. A alternativa C reproduz essa definição, e é a correta. A alternativa A confunde com quem aplica no exterior, e a B usa um critério de residência fixa que não é o definido.","id":"9509"},{"n":178,"banco":"lucas","mod":1,"tit":"I","titn":"Sistema Financeiro Nacional e Participantes do Mercado","cap":"37","capn":"Questão 37 (cód. 9510)","stem":"A principal função das corretoras de valores mobiliários é:","opts":[["a","Promover de forma eficiente a distribuição de títulos"],["b","Fomentar de forma eficiente a aproximação entre compradores e vendedores de títulos e valores mobiliários"],["c","Fomentar de forma eficiente, a aproximação de empresas emissoras de títulos, valores mobiliários e mercadorias"],["d","Promover de forma eficiente o pregão da bolsa de valores (B3), por meio da apregoação de leilão em recinto próprio"]],"ans":"b","exp":"Tema: função das corretoras de valores mobiliários. Elas aproximam compradores e vendedores de títulos e valores mobiliários, dando eficiência à negociação. A alternativa B é a correta. A distribuição de títulos (A) é função de outras instituições, e as alternativas C e D descrevem atividades de emissão ou do pregão, que não são o papel principal da corretora.","id":"9510"},{"n":179,"banco":"lucas","mod":1,"tit":"I","titn":"Sistema Financeiro Nacional e Participantes do Mercado","cap":"38","capn":"Questão 38 (cód. 9511)","stem":"Sobre as corretoras de valores mobiliários, assinale a alternativa correta:","opts":[["a","São instituições financeiras reguladas e fiscalizadas pelo BACEN"],["b","São instituições financeiras reguladas e fiscalizadas pela CVM"],["c","São instituições financeiras reguladas e fiscalizadas pelo BACEN e CVM"],["d","São instituições não financeiras reguladas e fiscalizadas pelo BACEN e CVM"]],"ans":"c","exp":"Tema: supervisão das corretoras. As corretoras são instituições financeiras reguladas e fiscalizadas pelo Bacen e pela CVM, em supervisão conjunta. A alternativa C é a correta. Supervisionar apenas por um dos órgãos (A e B) fica incompleto, e a alternativa D classifica erroneamente como não financeiras.","id":"9511"},{"n":180,"banco":"lucas","mod":1,"tit":"I","titn":"Sistema Financeiro Nacional e Participantes do Mercado","cap":"39","capn":"Questão 39 (cód. 9512)","stem":"Assinale a alternativa que contém um órgão de caráter regulamentar do Sistema Financeiro Nacional","opts":[["a","CVM"],["b","PREVIC"],["c","CMN"],["d","BACEN"]],"ans":"c","exp":"Tema: órgão de caráter regulamentar. O CMN é o órgão normativo, ou regulamentar, do SFN. A alternativa C é a correta. CVM, Previc e Bacen são órgãos executores ou supervisores, e não são normativos.","id":"9512"},{"n":181,"banco":"lucas","mod":1,"tit":"I","titn":"Sistema Financeiro Nacional e Participantes do Mercado","cap":"40","capn":"Questão 40 (cód. 9513)","stem":"É competência exclusivamente do BA- CEN:","opts":[["a","Emissão de títulos públicos"],["b","Fiscalização as instituições financeiras"],["c","Aprovação de orçamentos monetários de moeda e crédito"],["d","Fixar diretrizes e normas da política cambial"]],"ans":"b","exp":"Tema: competência exclusiva do Bacen. Fiscalizar as instituições financeiras é competência do Bacen, que a exerce com exclusividade no segmento bancário. A alternativa B é a correta. A emissão de títulos públicos (A) é do Tesouro Nacional. A aprovação dos orçamentos monetários (C) e a fixação das diretrizes cambiais (D) são do CMN.","id":"9513"},{"n":182,"banco":"lucas","mod":1,"tit":"I","titn":"Sistema Financeiro Nacional e Participantes do Mercado","cap":"41","capn":"Questão 41 (cód. 9514)","stem":"O Conselho Monetário Nacional (CMN) tem como função:","opts":[["a","Execução da política cambial"],["b","Regulação dos índices de inflação para evitar desequilíbrios"],["c","Fiscalização do mercado de capitais"],["d","Fiscalização do mercado de crédito"]],"ans":"b","exp":"Tema: função do CMN. O CMN regula o sistema e define as políticas monetária, creditícia e cambial. A alternativa B aparece como regulação de índices de inflação para evitar desequilíbrios, o que tem relação com a política monetária do CMN. A execução da política cambial (A) é do Bacen, e a fiscalização de mercado de capitais (C) e de crédito (D) são de outros órgãos. Essa é a alternativa mais próxima da função do CMN, mas o enunciado é impreciso. Vale conferir o texto da questão no material original.","id":"9514"},{"n":183,"banco":"lucas","mod":1,"tit":"I","titn":"Sistema Financeiro Nacional e Participantes do Mercado","cap":"42","capn":"Questão 42 (cód. 9515)","stem":"Em relação ao registro de operações de clientes, as instituições financeiras têm a obrigação de mantê – los:","opts":[["a","Inteiramente, realizando a identificação destes clientes por, no mínimo, 05 anos"],["b","Inteiramente, realizando a identificação destes clientes por, no mínimo, 10 anos"],["c","Inteiramente, não realizando a identificação destes clientes por, no mínimo, 05 anos"],["d","Inteiramente, realizando a identificação destes clientes por, no máximo, 10 anos"]],"ans":"b","exp":"Tema: prazo de guarda do registro de operações dos clientes. A regra apresentada na apostila é de manter o registro por no mínimo cinco anos. A alternativa A é a que corresponde a essa regra.\n\nO gabarito indica B, que fixa o prazo de dez anos. Essa é uma divergência com o texto da apostila, que indica cinco anos (página 18 da apostila). Vale conferir a regra específica antes de considerar a questão resolvida.","id":"9515"},{"n":184,"banco":"lucas","mod":1,"tit":"I","titn":"Sistema Financeiro Nacional e Participantes do Mercado","cap":"43","capn":"Questão 43 (cód. 9544)","stem":"No mercado financeiro, os órgãos são segmentados em órgãos normativos, órgãos executores e instituições participantes do mercado, sujeitas a regulação das entidades. A alternativa que cita órgãos executores é:","opts":[["a","Banco Central do Brasil (BACEN), Comissão de Valores Mobiliários (CVM), Superintendência Nacional de Previdência Complementar (Previc) e Conselho Monetário Nacional (CMN)."],["b","Banco Central do Brasil (BACEN), Superintendência de Seguros Privados (SUSEP), Comissão de Valores Mobiliários (CVM) e Superintendência Nacional de Previdência Complementar (Previc)."],["c","Conselho Nacional de Seguros Privados (CNSP), COAF, Banco Central do Brasil (BA- CEN) e Ministério da Economia."],["d","Ministério da Economia, Comissão de Valores Mobiliários (CVM), Conselho Nacional de Seguros Privados (CNSP)."]],"ans":"b","exp":"Tema: órgãos executores do SFN. Os executores são os órgãos que fiscalizam e supervisionam o sistema: Bacen, Susep, CVM e Previc. A alternativa B é a correta. A alternativa A inclui o CMN, que é normativo. A alternativa C inclui o CNSP, que é normativo, e a D inclui o Ministério, que não é executor do sistema.","id":"9544"},{"n":185,"banco":"lucas","mod":1,"tit":"I","titn":"Sistema Financeiro Nacional e Participantes do Mercado","cap":"44","capn":"Questão 44 (cód. 199544073)","stem":"Responsável pela emissão dos títulos públicos federais:","opts":[["a","BACEN"],["b","CMN"],["c","CVM"],["d","Tesouro Nacional"]],"ans":"d","exp":"Tema: emissão de títulos públicos federais. É competência do Tesouro Nacional, que emite e administra a dívida pública da União. A alternativa D é a correta. O Bacen (A) executa a política monetária e o sistema de pagamentos, e não emite títulos da União. O CMN (B) é normativo e a CVM (C) regula o mercado de valores mobiliários.","id":"199544073"},{"n":186,"banco":"lucas","mod":1,"tit":"I","titn":"Sistema Financeiro Nacional e Participantes do Mercado","cap":"45","capn":"Questão 45 (cód. 199544074)","stem":"É o órgão responsável pela administração da dívida pública mobiliária e contratual, interna e externa, da União:","opts":[["a","Tesouro Nacional"],["b","Bacen"],["c","CMN"],["d","CVM"]],"ans":"a","exp":"Tema: administração da dívida pública da União. Quem administra a dívida mobiliária e contratual, interna e externa, é o Tesouro Nacional. A alternativa A é a correta, pela regra da dívida pública. O Bacen (B) executa a política monetária, o CMN (C) é normativo e a CVM (D) regula o mercado de valores mobiliários.","id":"199544074"},{"n":187,"banco":"lucas","mod":1,"tit":"I","titn":"Sistema Financeiro Nacional e Participantes do Mercado","cap":"46","capn":"Questão 46 (cód. 199544075)","stem":"Se um sistema de compensação e liquidação (clearings) for considerado sistemicamente importante pelo Banco Central do Brasil:","opts":[["a","deverá assumir posição de contraparte central das operações e contar com mecanismos e salvaguardas que lhes permitam assegurar a liquidação das operações nele compensadas e liquidadas."],["b","deve exigir dos participantes que depositem margens de garantia suficientemente elevadas para dar segurança aos participantes, sem, contudo, serem contrapartes centrais."],["c","não precisa assumir posição de contraparte central das operações, porque isso demandaria excesso de garantias e tornaria as clearings inviáveis economicamente."],["d","deve deixar que os participantes estabeleçam entre si as garantias que julgarem necessário sem estabelecimento de níveis mínimos ou máximos."]],"ans":"a","exp":"Tema: clearings sistemicamente importantes. Quando o Bacen considera o sistema sistemicamente importante, a câmara deve assumir a posição de contraparte central e manter mecanismos e salvaguardas que assegurem a liquidação das operações. A alternativa A é a correta. As demais afastam a contraparte central ou deixam as garantias sem regra mínima, o que contraria a regulação.","id":"199544075"},{"n":188,"banco":"lucas","mod":1,"tit":"I","titn":"Sistema Financeiro Nacional e Participantes do Mercado","cap":"47","capn":"Questão 47 (cód. 199544076)","stem":"O Banco Central do Brasil – BA- CEN é uma autarquia do governo federal e tem como função:","opts":[["a","Emitir papel moeda, após autorização do CMN"],["b","Autorizar o funcionamento de instituição financeira estrangeira"],["c","Coordenar a política monetária"],["d","Realizar operações de redesconto"]],"ans":"d","exp":"Tema: funções do Bacen. O Banco Central pode realizar operações de redesconto, que são empréstimos de assistência à liquidez às instituições financeiras. A alternativa D é a correta. Emissão de papel-moeda (A) é do Bacen com autorização do CMN, a autorização de instituições estrangeiras (B) é outra atribuição, e a coordenação da política monetária (C) é função do CMN e do Copom, e não exclusivamente do Bacen.","id":"199544076"},{"n":189,"banco":"lucas","mod":1,"tit":"I","titn":"Sistema Financeiro Nacional e Participantes do Mercado","cap":"48","capn":"Questão 48 (cód. 199544077)","stem":"O Conselho Monetário Nacional - CMN, tem como função:","opts":[["a","Exercer a fiscalização das instituições financeiras"],["b","Conceder autorização para abertura de bancos estrangeiros no Brasil"],["c","Realizar operações de redesconto junto às instituições financeiras"],["d","Definir as diretrizes e normas referentes ao câmbio"]],"ans":"d","exp":"Tema: função do CMN. O CMN define as diretrizes e normas referentes ao câmbio e às demais políticas. A alternativa D é a correta. A fiscalização das instituições (A) é do Bacen, a autorização de bancos estrangeiros (B) também é do Bacen, e o redesconto (C) é função do Bacen.","id":"199544077"},{"n":190,"banco":"lucas","mod":1,"tit":"I","titn":"Sistema Financeiro Nacional e Participantes do Mercado","cap":"49","capn":"Questão 49 (cód. 199544078)","stem":"É uma função da Comissão de Valores Mobiliários – CVM:","opts":[["a","Fiscalizar as instituições financeiras do ramo bancário"],["b","Determina as diretrizes do mercado de câmbio"],["c","Limitar os valores máximos de comissão que podem ser cobrados pelas instituições que participam do mercado de distribuição de valores mobiliários"],["d","Estimular os investimentos em caderneta de poupança"]],"ans":"c","exp":"Tema: função da CVM. A CVM limita os valores máximos de comissão cobrados pelas instituições do mercado de distribuição de valores mobiliários. A alternativa C é a correta. A fiscalização de instituições bancárias (A) é do Bacen, a diretriz do câmbio (B) é do CMN, e o estímulo à poupança (D) não é função da CVM, que apenas estimula a aplicação em valores mobiliários.","id":"199544078"},{"n":191,"banco":"lucas","mod":1,"tit":"I","titn":"Sistema Financeiro Nacional e Participantes do Mercado","cap":"50","capn":"Questão 50 (cód. 199544079)","stem":"É uma definição correta sobre o Sistema de Pagamentos Brasileiro - SPB:","opts":[["a","Sistema criado para transferir fundos entre bancos de um mesmo conglomerado"],["b","Sistema criado para realização de DOC’s para valores superiores a R$ 5 mil"],["c","É a transferência de fundos próprio e de terceiros realizados entre bancos em tempo real, com o objetivo de reduzir o risco sistêmico"],["d","Sistema criado para gerenciar o risco de crédito das instituições ao custodiar todos os CDB’s emitidos por essas instituições"]],"ans":"c","exp":"Tema: definição do SPB. O Sistema de Pagamentos Brasileiro é o conjunto de entidades, sistemas e mecanismos de processamento e liquidação de transferências de fundos, moeda estrangeira, ativos financeiros e valores mobiliários. A alternativa C tem parte da definição, e é a correta pela chave, embora a alternativa A da questão 55 traga a definição completa. O SPB existe para reduzir o risco sistêmico, o que é coerente com a alternativa C.","id":"199544079"},{"n":192,"banco":"lucas","mod":1,"tit":"I","titn":"Sistema Financeiro Nacional e Participantes do Mercado","cap":"51","capn":"Questão 51 (cód. 199544080)","stem":"É uma função do Banco Central do Brasil – BACEN:","opts":[["a","Atuar, através do Comitê de Política Monetária - COPOM, para definir a taxa meta de inflação"],["b","Realizar, através de operações de redesconto bancário, empréstimos de assistência à liquidez para as instituições financeiras"],["c","Estimular a formação de poupança e direcionamento da mesma para o mercado de valores mobiliários"],["d","Fiscalizar as instituições financeiras e não financeiras que atuam na gestão de recursos de terceiros"]],"ans":"b","exp":"Tema: função do Bacen. O Banco Central realiza operações de redesconto, que são empréstimos de assistência à liquidez para as instituições financeiras. A alternativa B é a correta. O Copom (A) é órgão do Bacen e não define a meta de inflação, que é do CMN. O estímulo à poupança (C) é função da CVM, e a fiscalização de não financeiras (D) não é a regra.","id":"199544080"},{"n":193,"banco":"lucas","mod":1,"tit":"I","titn":"Sistema Financeiro Nacional e Participantes do Mercado","cap":"52","capn":"Questão 52 (cód. 199544081)","stem":"É a entidade responsável pelas diretrizes das operações de seguro, capitalização e previdência","opts":[["a","SUSEP"],["b","CNSP"],["c","CMN"],["d","CVM"]],"ans":"b","exp":"Tema: diretrizes das operações de seguro, capitalização e previdência. Essa competência é do CNSP, o Conselho Nacional de Seguros Privados, que regula esses mercados. A alternativa B é a correta. A Susep (A) é a supervisora, e não define as diretrizes. O CMN (C) e a CVM (D) regulam outros mercados.","id":"199544081"},{"n":194,"banco":"lucas","mod":1,"tit":"I","titn":"Sistema Financeiro Nacional e Participantes do Mercado","cap":"53","capn":"Questão 53 (cód. 199544082)","stem":"Depósito compulsório é um dos instrumentos de política monetária. A quem compete receber os mesmos:","opts":[["a","COPOM"],["b","BACEN"],["c","CMN"],["d","Instituição Financeira onde o cliente possua a conta"]],"ans":"b","exp":"Tema: depósito compulsório. Os recursos dos depósitos compulsórios são recebidos pelo Banco Central, que os usa como instrumento de política monetária. A alternativa B é a correta. O Copom (A) decide a taxa de juros, o CMN (C) fixa diretrizes e a instituição financeira (D) apenas recolhe o valor ao Bacen.","id":"199544082"},{"n":195,"banco":"lucas","mod":1,"tit":"I","titn":"Sistema Financeiro Nacional e Participantes do Mercado","cap":"54","capn":"Questão 54 (cód. 199544083)","stem":"Tipo de Sociedade que a Comissão de Valores Mobiliários – CVM, fiscaliza:","opts":[["a","Sociedades de Economia Mista que sejam de propriedade privada"],["b","Sociedades Anônimas que possuem ações negociadas em Bolsa de Valores e Mercado de Balcão"],["c","Sociedades Anônimas que possuem ações negociadas em Bolsa de Valores e Mercado Primário"],["d","Sociedades Limitadas que possuem ações negociadas em Bolsa de Valores"]],"ans":"b","exp":"Tema: sociedades fiscalizadas pela CVM. São as sociedades anônimas com ações negociadas em bolsa e no mercado de balcão. A alternativa B é a correta. Sociedades de economia mista privadas (A), mercado primário (C) e sociedades limitadas (D) não são o alvo da fiscalização na forma descrita, já que as limitadas não negociam ações em bolsa.","id":"199544083"},{"n":196,"banco":"lucas","mod":1,"tit":"I","titn":"Sistema Financeiro Nacional e Participantes do Mercado","cap":"55","capn":"Questão 55 (cód. 199544084)","stem":"O Sistema de Pagamentos Brasileiro (SPB) é o conjunto de:","opts":[["a","entidades, sistemas e mecanismos relacionados com o processamento e a liquidação de operações de transferência de fundos, de operações com moeda estrangeira ou com ativo financeiros e valores mobiliários."],["b","instituições financeiras, cooperativas de crédito e centrais depositárias de ações e de títulos de dívida corporativa."],["c","sistemas eletrônicos disponibilizados pelo governo brasileiro para transferência de fundos e pagamentos de tributos"],["d","sistemas e mecanismos que possuem relação com a liquidação de câmbio entre as instituições financeiras"]],"ans":"a","exp":"Tema: definição do SPB. O SPB é o conjunto de entidades, sistemas e mecanismos de processamento e liquidação de transferências de fundos, operações com moeda estrangeira e com ativos financeiros e valores mobiliários. A alternativa A é a correta, pela definição da apostila.","id":"199544084"},{"n":197,"banco":"lucas","mod":1,"tit":"I","titn":"Sistema Financeiro Nacional e Participantes do Mercado","cap":"56","capn":"Questão 56 (cód. 199544085)","stem":"É a entidade responsável pelas diretrizes das operações dos “Fundos de Pensão”:","opts":[["a","CNSP"],["b","CNPC"],["c","CMN"],["d","PREVIC"]],"ans":"b","exp":"Tema: diretrizes dos fundos de pensão. A entidade responsável pelas diretrizes das entidades fechadas de previdência é o CNPC, o Conselho Nacional de Previdência Complementar. A alternativa B é a correta. A Previc (D) fiscaliza e supervisiona essas entidades, mas não define as diretrizes. O CNSP (A) cuida de seguros, e o CMN (C) é o órgão normativo maior do SFN.","id":"199544085"},{"n":198,"banco":"lucas","mod":1,"tit":"I","titn":"Sistema Financeiro Nacional e Participantes do Mercado","cap":"57","capn":"Questão 57 (cód. 199544086)","stem":"Órgão máximo do Sistema Financeiro Nacional:","opts":[["a","CNSP"],["b","Bacen"],["c","CMN"],["d","Tesouro Nacional"]],"ans":"c","exp":"Tema: órgão máximo do SFN. É o CMN, o Conselho Monetário Nacional, que fixa as diretrizes do sistema. A alternativa C é a correta. O CNSP (A) é órgão de seguros, o Bacen (B) é executor e o Tesouro (D) administra a dívida pública.","id":"199544086"},{"n":199,"banco":"lucas","mod":1,"tit":"I","titn":"Sistema Financeiro Nacional e Participantes do Mercado","cap":"58","capn":"Questão 58 (cód. 199544087)","stem":"Os sistemas que integram o Sistema de Pagamentos Brasileiro (SPB) NÃO incluem o Sistema:","opts":[["a","de Registro, de compensação, de liquidação e custódia da Cetip S.A.."],["b","de Cadastramento Unificado de Fornecedores (SICAF)."],["c","de Transferência de Reservas (STR)."],["d","Especial de Liquidação e de Custódia (Selic)."]],"ans":"b","exp":"Tema: sistemas integrantes do SPB. Integram o SPB o Selic, o STR e os sistemas de registro, compensação e liquidação da Cetip. O SICAF (Cadastramento Unificado de Fornecedores) é um sistema de compras do governo, sem relação com o SPB. A alternativa B é a correta, porque é o sistema que não faz parte do SPB.","id":"199544087"},{"n":200,"banco":"lucas","mod":1,"tit":"I","titn":"Sistema Financeiro Nacional e Participantes do Mercado","cap":"59","capn":"Questão 59 (cód. 199544088)","stem":"Para se constituir uma cooperativa de crédito é necessário se obter autorização de qual órgão:","opts":[["a","CVM"],["b","CMN"],["c","Susep"],["d","BACEN"]],"ans":"d","exp":"Tema: autorização para cooperativa de crédito. A autorização para constituir uma cooperativa de crédito é concedida pelo Bacen, que regula e fiscaliza essas instituições. A alternativa D é a correta. CVM (A) e Susep (C) não autorizam cooperativas de crédito. O CMN (B) é normativo e não concede autorizações individuais.","id":"199544088"},{"n":201,"banco":"lucas","mod":1,"tit":"I","titn":"Sistema Financeiro Nacional e Participantes do Mercado","cap":"60","capn":"Questão 60 (cód. 199544089)","stem":"Um Banco Múltiplo privado para ser constituído pode ter a carteira comercial e qual mais:","opts":[["a","Crédito e Financiamento Imobiliário"],["b","Câmbio e Crédito"],["c","Câmbio e Financiamento Imobiliário"],["d","Crédito e Desenvolvimento (privado)"]],"ans":"a","exp":"Tema: carteiras de um banco múltiplo privado. O banco múltiplo pode ter a carteira comercial e também as de crédito imobiliário, de crédito, financiamento e investimento, entre outras. Pela chave, a alternativa A (crédito e financiamento imobiliário) é a que completa a regra da questão. A alternativa D inclui desenvolvimento privado, que não é a carteira típica do banco privado.","id":"199544089"},{"n":202,"banco":"lucas","mod":1,"tit":"I","titn":"Sistema Financeiro Nacional e Participantes do Mercado","cap":"61","capn":"Questão 61 (cód. 199544090)","stem":"As Sociedades de Crédito, Financiamento e Investimento, mais conhecidas como financeiras, são instituições e tem como principal característica, para aquisição de bens, serviços e .","opts":[["a","bancárias / financiar a atividade produtiva / capital social."],["b","bancárias / conceder financiamento / capital fixo."],["c","não bancárias / conceder empréstimos / capital social."],["d","não bancárias / conceder crédito / capital de giro."]],"ans":"d","exp":"Tema: sociedades de crédito, financiamento e investimento (financeiras). Elas são instituições não bancárias, que concedem crédito e financiamento para a aquisição de bens e serviços, com capital de giro e não capital fixo. A alternativa D é a correta, porque é a combinação de não bancárias, conceder crédito e capital de giro. As demais misturam características de bancos ou usam termos que não se aplicam às financeiras.","id":"199544090"},{"n":203,"banco":"lucas","mod":1,"tit":"I","titn":"Sistema Financeiro Nacional e Participantes do Mercado","cap":"62","capn":"Questão 62 (cód. 199544091)","stem":"\"Analise as atribuições abaixo: I. Conceder financiamento imobiliário II. Realizar intermediação de operações na bolsa de valores III. Administrar Fundos de Investimentos Refere (m) se a atividade (s) de uma SCTVM:\"","opts":[["a","Somente II"],["b","I e II"],["c","II e III"],["d","Todas as alternativas"]],"ans":"c","exp":"Tema: SCTVM (sociedade corretora de títulos e valores mobiliários). Analisando:\n\nI. Errado. Conceder financiamento imobiliário não é atividade da SCTVM, e sim de instituições de crédito imobiliário.\n\nII. Correto. A SCTVM realiza intermediação de operações na bolsa de valores.\n\nIII. Correto. A SCTVM pode administrar fundos de investimento.\n\nA alternativa C (II e III) é a correta.","id":"199544091"},{"n":204,"banco":"lucas","mod":1,"tit":"I","titn":"Sistema Financeiro Nacional e Participantes do Mercado","cap":"63","capn":"Questão 63 (cód. 199544092)","stem":"Um Banco Múltiplo é constituído com a carteira Comercial e a de Crédito, Financiamento e Investimento. Esse banco está autorizado a:","opts":[["a","Captar por depósito à vista e também administrar fundos de investimentos"],["b","Conceder crédito para médio prazo, porém não pode captar pode depósito à vista"],["c","Captar por depósito à vista e também conceder crédito para aquisição de bens"],["d","Captar por depósito à vista e conceder crédito imobiliário"]],"ans":"c","exp":"Tema: banco múltiplo com carteira comercial e de crédito, financiamento e investimento. Ele pode captar por depósito à vista, por ser banco comercial, e conceder crédito para a aquisição de bens, pela carteira de crédito, financiamento e investimento. A alternativa C é a correta. A alternativa A (administrar fundos) não é a primeira opção de carteira comercial. A alternativa B proíbe a captação à vista, o que é falso, e a alternativa D inclui crédito imobiliário, que não está nessa carteira.","id":"199544092"},{"n":205,"banco":"lucas","mod":1,"tit":"I","titn":"Sistema Financeiro Nacional e Participantes do Mercado","cap":"64","capn":"Questão 64 (cód. 199544093)","stem":"Uma empresa decide abrir seu capital no mercado. Essa operação será coordenada por um (a):","opts":[["a","Banco de Investimento"],["b","Banco Comercial"],["c","Banco Múltiplo, com carteira comercial"],["d","Comissão de Valores Mobiliários – CVM"]],"ans":"a","exp":"Tema: coordenação de abertura de capital (IPO). A operação é coordenada pelo banco de investimento, que atua com subscrição e distribuição de valores mobiliários. A alternativa A é a correta. O banco comercial (B) não coordena IPO, e o banco múltiplo (C) só faz isso se tiver carteira de investimento. A CVM (D) regula, e não coordena a operação.","id":"199544093"},{"n":206,"banco":"lucas","mod":1,"tit":"I","titn":"Sistema Financeiro Nacional e Participantes do Mercado","cap":"65","capn":"Questão 65 (cód. 199544094)","stem":"São funções de uma SCTVM, exceto:","opts":[["a","Administrar planos de capitalização"],["b","Administrar clubes de investimentos"],["c","Administrar fundos de investimentos"],["d","Realizar operações de câmbio"]],"ans":"a","exp":"Tema: funções da SCTVM, com a alternativa que não é função. A SCTVM pode administrar clubes e fundos de investimento e realizar operações de câmbio. Ela não administra planos de capitalização, que são do mercado de seguros e previdência, supervisionado pela Susep. A alternativa A é a exceção, e é a correta.","id":"199544094"},{"n":207,"banco":"lucas","mod":1,"tit":"I","titn":"Sistema Financeiro Nacional e Participantes do Mercado","cap":"66","capn":"Questão 66 (cód. 199544095)","stem":"Sobre o Banco Nacional de Desenvolvimento – BNDES, assinale a alternativa correta:","opts":[["a","É um banco de desenvolvimento do governo federal"],["b","É uma sociedade de economia mista com ações em bolsa"],["c","É o principal fomentador do mercado imobiliário no Brasil"],["d","É o instrumento que o governo usa para fomentar o desenvolvimento de setores estratégicos"]],"ans":"d","exp":"Tema: BNDES. O instrumento que o governo usa para fomentar setores estratégicos é o BNDES, que financia projetos de longo prazo em áreas estratégicas. A alternativa D é a correta. A alternativa A apenas descreve a natureza do banco de forma imprecisa, e as alternativas B e C estão erradas: o BNDES é empresa pública, não sociedade de economia mista com ações em bolsa, e o principal fomentador do mercado imobiliário não é o BNDES.","id":"199544095"},{"n":208,"banco":"lucas","mod":1,"tit":"I","titn":"Sistema Financeiro Nacional e Participantes do Mercado","cap":"67","capn":"Questão 67 (cód. 199544096)","stem":"Instituição Financeira autorizada a captar através de depósito à vista:","opts":[["a","Banco Comercial"],["b","Banco Múltiplo"],["c","Banco de Desenvolvimento"],["d","Financeiras"]],"ans":"a","exp":"Tema: instituição autorizada a captar por depósito à vista. Somente o banco comercial e o banco múltiplo com carteira comercial podem captar por depósito à vista. A alternativa A é a correta. O banco múltiplo (B) pode captar à vista só se tiver carteira comercial, e não é a resposta mais direta. Os bancos de desenvolvimento (C) e as financeiras (D) não captam por depósito à vista.","id":"199544096"},{"n":209,"banco":"lucas","mod":1,"tit":"I","titn":"Sistema Financeiro Nacional e Participantes do Mercado","cap":"68","capn":"Questão 68 (cód. 199544097)","stem":"É uma carteira que deve estar presente em um Banco Múltiplo, obrigatoriamente:","opts":[["a","Comercial"],["b","Crédito e Financiamento"],["c","Crédito Imobiliário"],["d","Desenvolvimento"]],"ans":"a","exp":"Tema: carteira obrigatória do banco múltiplo. A carteira comercial é a que deve estar presente obrigatoriamente, junto com outra. A alternativa A é a correta. As demais carteiras são facultativas, o que explica por que não podem ser obrigatórias.","id":"199544097"},{"n":210,"banco":"lucas","mod":1,"tit":"I","titn":"Sistema Financeiro Nacional e Participantes do Mercado","cap":"69","capn":"Questão 69 (cód. 199544098)","stem":"Os Bancos de Investimentos são instituições muito importantes na estrutura do sistema financeiro nacional. Sobre essas instituições, assinale a alternativa correta:","opts":[["a","Realizam operações de emissão de valores mobiliários, assessoram operações de fusões e aquisições e ofertam crédito de curto e médio prazo, como cheque especial, por exemplo."],["b","Realizam operações de emissão de valores mobiliários, assessoram operações de fusões e aquisições e realizam operações com dólar turismo"],["c","Fiscalizam o mercado de distribuição de valores mobiliários"],["d","Assessoram empresas em operações de fusões e aquisições, emissões de valores mobiliários e ofertas públicas, além de fornecer crédito para médio e longo prazo"]],"ans":"d","exp":"Tema: bancos de investimento. Eles assessoram operações de fusões e aquisições, emissões de valores mobiliários e ofertas públicas, e fornecem crédito de médio e longo prazo. A alternativa D é a correta.\n\nA alternativa A atribui crédito de curto prazo e cheque especial, que são do banco comercial. A alternativa B menciona dólar turismo, operação de câmbio, não típica do banco de investimento. A alternativa C atribui a fiscalização à instituição, que é da CVM.","id":"199544098"},{"n":211,"banco":"lucas","mod":1,"tit":"I","titn":"Sistema Financeiro Nacional e Participantes do Mercado","cap":"70","capn":"Questão 70 (cód. 199544099)","stem":"Banco Comercial é aquele que:","opts":[["a","Pode captar por depósito a prazo e conceder crédito imobiliário"],["b","Possui pelo menos 2 carteiras e pode captar por depósito à vista"],["c","Pode administrar fundos de investimentos"],["d","Pode captar por depósito a prazo e também depósito à vista"]],"ans":"d","exp":"Tema: banco comercial. Ele pode captar por depósito à vista e a prazo, e conceder crédito de curto e médio prazo. A alternativa D é a correta. A captação a prazo e à vista é característica do banco comercial, o que confirma a resposta. As demais alternativas atribuem a ele crédito imobiliário, administração de fundos ou múltiplas carteiras, que não são o perfil do banco comercial.","id":"199544099"},{"n":212,"banco":"lucas","mod":1,"tit":"I","titn":"Sistema Financeiro Nacional e Participantes do Mercado","cap":"71","capn":"Questão 71 (cód. 199544100)","stem":"Número mínimo de cooperados que devem estar presentes em uma Cooperativa de Crédito:","opts":[["a","30"],["b","3"],["c","20"],["d","50"]],"ans":"c","exp":"Tema: número mínimo de cooperados. A cooperativa de crédito precisa de no mínimo 20 cooperados para ser constituída. A alternativa C é a correta.","id":"199544100"},{"n":213,"banco":"lucas","mod":1,"tit":"I","titn":"Sistema Financeiro Nacional e Participantes do Mercado","cap":"72","capn":"Questão 72 (cód. 199544101)","stem":"\"Analise as instituições abaixo: I. CEF II. Banco Múltiplo com Carteira de Crédito Imobiliário III. Banco Comercial Pode (m) conceder crédito imobiliário:\"","opts":[["a","Somente a I"],["b","I e II"],["c","I, II e III"],["d","II e III"]],"ans":"b","exp":"Tema: crédito imobiliário por instituições. Analisando:\n\nI. Correto. A Caixa Econômica Federal pode conceder crédito imobiliário, conforme sua atuação no setor.\n\nII. Correto. O banco múltiplo com carteira de crédito imobiliário pode conceder esse crédito.\n\nIII. Errado. O banco comercial, em regra, não pode conceder crédito imobiliário. Essa carteira faz parte do banco múltiplo, e não do banco comercial.\n\nA alternativa B (I e II) é a correta.","id":"199544101"},{"n":214,"banco":"lucas","mod":2,"tit":"II","titn":"Infraestrutura do Mercado & B3","cap":"1","capn":"Questão 1 (cód. 9667)","stem":"A respeito da Bolsa de Valores (B3), analise as afirmativas abaixo: I. Também atua como sistema de liquidação bruta em tempo real II. Atua na compensação bilateral de obrigações de seus participantes e efetua a liquidação pelo resultado líquido III. Sua estrutura de compensação e liquidação corresponde aos sistemas de liquidação (SSS) e a uma contraparte central (CCP) Está correto o que se afirma em:","opts":[["a","I e II"],["b","I e III"],["c","II e III"],["d","Todas as alternativas"]],"ans":"b","exp":"Tema: a B3 como bolsa, câmara e liquidação. Analisando:\n\nI. Correto em parte. A B3 atua como sistema de liquidação bruta em tempo real em certos segmentos, como o CETIP UTVM, citado na questão 45. O texto desta edição confirma isso.\n\nII. Errado. A B3 não faz compensação bilateral de obrigações; a compensação é multilateral, com o resultado líquido de cada participante.\n\nIII. Correto. A estrutura de compensação e liquidação da B3 corresponde a um sistema de liquidação (SSS) e a uma contraparte central (CCP), que são conceitos da abordagem internacional.\n\nA alternativa B (I e III) é a correta.","id":"9667"},{"n":215,"banco":"lucas","mod":2,"tit":"II","titn":"Infraestrutura do Mercado & B3","cap":"2","capn":"Questão 2 (cód. 9668)","stem":"A contraparte central, segundo abordagem internacional: I. Pode atuar para mutualizar alguns riscos por meio da constituição de fundos de falhas II. É possível a redução de riscos aos quais estão expostos os participantes pela imposição aos mesmos de mecanismos de controles III. Atua como contraparte central dos participantes de mercado apenas por meio do processo de novação Está correto o que se afirma em:","opts":[["a","I e II"],["b","I e III"],["c","II e III"],["d","Todas as alternativas"]],"ans":"a","exp":"Tema: contraparte central na abordagem internacional. Analisando:\n\nI. Correto. A CCP pode mutualizar riscos por meio de fundos de falhas, que são alimentados pelos participantes.\n\nII. Correto. Ela reduz os riscos dos participantes ao impor mecanismos de controle e de garantia.\n\nIII. Errado. A CCP não atua apenas por novação. A novação é um dos mecanismos, mas há também instituto legal equivalente, como lembra a teoria desta edição. A palavra \"apenas\" torna o item falso.\n\nA alternativa A (I e II) é a correta.","id":"9668"},{"n":216,"banco":"lucas","mod":2,"tit":"II","titn":"Infraestrutura do Mercado & B3","cap":"3","capn":"Questão 3 (cód. 9669)","stem":"Possui função de permitir a transferência e liquidação de ativos através de registros eletrônicos de acordo com regras pré estabelecidas de compensação:","opts":[["a","Bolsa de valores"],["b","Contraparte central"],["c","Central depositária"],["d","Sistema de liquidação"]],"ans":"d","exp":"Tema: função de transferir e liquidar ativos por registros eletrônicos. Essa é a definição de sistema de liquidação (SSS): permite a transferência e liquidação de ativos por registros eletrônicos, de acordo com regras preestabelecidas de compensação. A alternativa D é a correta.\n\nBolsa (A) é o ambiente de negociação, a contraparte central (B) garante a liquidação, e a central depositária (C) guarda os ativos. Cada uma tem papel próprio, e a função do enunciado é a de liquidar por registro.","id":"9669"},{"n":217,"banco":"lucas","mod":2,"tit":"II","titn":"Infraestrutura do Mercado & B3","cap":"4","capn":"Questão 4 (cód. 9670)","stem":"A respeito do Sistema de Pagamentos Brasileiro (SPB), analise as afirmativas abaixo: I. Uma de suas características é o uso obrigatório de contrapartes centrais para liquidação de obrigações resultantes de compensação multilateral II. Possui como característica a certeza da liquidação proporcionada pela contraparte central com base em mecanismos de gerenciamento de riscos e salvaguardas constituídas para tratamento de casos de insolvência de instituições III. Irrevogabilidade e finalidade das liquidações são características do SPB Está correto o que se afirma em:","opts":[["a","I e II"],["b","I e III"],["c","II e III"],["d","Todas as alternativas"]],"ans":"d","exp":"Tema: características do SPB. A chave indica D, com todos os itens corretos, mas há uma inconsistência interna entre questões desta mesma apostila. A questão 11 afirma que o uso de contrapartes centrais em sistemas sistemicamente importantes é facultativo, e a chave dela considera esse item falso. Já o item I desta questão (uso obrigatório de contrapartes centrais) só seria verdadeiro se o uso fosse obrigatório, o que contradiz a questão 11.\n\nOs itens II (certeza da liquidação com mecanismos de gerenciamento de risco) e III (irrevogabilidade e finalidade) são características do SPB. Por isso, pela teoria, a resposta mais coerente seria a C (II e III), e não a D. Vale conferir a regra de uso das contrapartes centrais no SPB antes de considerar a questão resolvida.","id":"9670"},{"n":218,"banco":"lucas","mod":2,"tit":"II","titn":"Infraestrutura do Mercado & B3","cap":"5","capn":"Questão 5 (cód. 9671)","stem":"A que se refere o documento Principles for Financial Market Infrastructures (PFMI)? I. Ao conjunto de princípios a serem observados pelas organizações que compõem a infraestrutura dos mercados financeiros. II. Ao conjunto de princípios e recomendações para a base legal necessária a dar suporte às operações das entidades; a sua governança; à administração dos riscos de crédito, de liquidez, de custódia, de transferência de valores e operacionais por elas incorridos. III. Às contrapartes centrais, os sistemas de liquidação, os sistemas de registro de títulos e valores mobiliários, e as centrais depositárias de ativos. Quais estão corretas?","opts":[["a","Apenas I."],["b","Apenas II e III."],["c","Apenas I e III."],["d","Todas estão corretas."]],"ans":"d","exp":"Tema: o documento PFMI (Principles for Financial Market Infrastructures). Ele é um conjunto de princípios aplicáveis às infraestruturas dos mercados financeiros, incluindo base legal, governança, administração de riscos de crédito, liquidez, custódia, transferência de valores e riscos operacionais. Também abrange as contrapartes centrais, os sistemas de liquidação, os registros de títulos e as centrais depositárias. Os três itens estão corretos, e a alternativa D é a correta.","id":"9671"},{"n":219,"banco":"lucas","mod":2,"tit":"II","titn":"Infraestrutura do Mercado & B3","cap":"6","capn":"Questão 6 (cód. 9672)","stem":"Assinale a alternativa que contém as características correspondentes ao conceito de Bolsa (Exchange): I. Entidade que mantém ambientes ou sistemas de negociação eletrônica. II. Mercados de bolsa são aqueles que funcionam regularmente como sistemas centralizados de negociação, evitando as negociações multilaterais. III. O Mercado de bolsa possibilita o encontro e a interação de ofertas de compra e de venda ou permitem a execução de negócios, sujeitos ou não à interferência de outras pessoas autorizadas a operar no mercado. Quais estão corretas?","opts":[["a","Apenas I."],["b","Apenas I e II."],["c","Apenas II e III."],["d","Apenas I e III."]],"ans":"d","exp":"Tema: conceito de bolsa. Analisando:\n\nI. Correto. A bolsa é a entidade que mantém ambientes ou sistemas de negociação eletrônica.\n\nII. Errado. Mercados de bolsa funcionam como sistemas centralizados de negociação, mas multilaterais. Dizer que \"evitam as negociações multilaterais\" contradiz a definição.\n\nIII. Correto. A bolsa possibilita o encontro e a interação de ofertas, e a execução de negócios, com ou sem interferência de outras pessoas autorizadas.\n\nA alternativa D (I e III) é a correta.","id":"9672"},{"n":220,"banco":"lucas","mod":2,"tit":"II","titn":"Infraestrutura do Mercado & B3","cap":"7","capn":"Questão 7 (cód. 9673)","stem":"Como se dá o funcionamento das negociações na Bolsa (Exchange)?","opts":[["a","Instituições previamente habilitadas podem negociar ativos financeiros e mercadorias exclusivamente em nome próprio."],["b","Não é necessária habilitação prévia por parte das instituições para poder haver negociações."],["c","As negociações realizadas na bolsa, são realizadas por pelas instituições previamente habilitadas, e podem ser em nome próprio ou para clientes."],["d","Instituições que desejam negociar ativos financeiros e mercadorias em nome de clientes não precisam de habilitação, enquanto, aquelas que querem negociar em seu nome, precisam de habilitação prévia."]],"ans":"c","exp":"Tema: funcionamento das negociações na bolsa. Apenas instituições previamente habilitadas podem negociar na bolsa, e elas podem fazê-lo em nome próprio ou para clientes. A alternativa C reproduz essa regra.\n\nA alternativa A limita a negociação ao nome próprio, o que não é a regra. A alternativa B dispensa a habilitação, o que é falso. A alternativa D cria uma distinção inexistente entre negociar para clientes e em nome próprio quanto à habilitação.","id":"9673"},{"n":221,"banco":"lucas","mod":2,"tit":"II","titn":"Infraestrutura do Mercado & B3","cap":"8","capn":"Questão 8 (cód. 9674)","stem":"Uma entidade de registro (Trade Repository – TR) mantém um sistema centralizado para registro de transações. Com base na centralização, no armazenamento e na disseminação de informações sobre transações registradas para os reguladores e para o público em geral. Sendo sua função: I. Prestar serviços adicionais de compensação e liquidação. II. Promover a transparência e a estabilidade financeira III. Identificar situações de abuso no mercado e realizar a prevenção contra elas. Quais estão corretas?","opts":[["a","Apenas I e II"],["b","Apenas II e III"],["c","Apenas III"],["d","Todas estão corretas"]],"ans":"b","exp":"Tema: entidade de registro (trade repository). Ela centraliza, armazena e divulga informações sobre transações para reguladores e público, e promove transparência e estabilidade financeira. Analisando:\n\nI. Errado. A entidade de registro não presta serviços de compensação e liquidação, que são funções da câmara.\n\nII. Correto. A transparência e a estabilidade são o objetivo da entidade de registro.\n\nIII. Correto. Ao registrar e divulgar as transações, ela permite identificar situações de abuso e apoiar a prevenção.\n\nA alternativa B (II e III) é a correta.","id":"9674"},{"n":222,"banco":"lucas","mod":2,"tit":"II","titn":"Infraestrutura do Mercado & B3","cap":"9","capn":"Questão 9 (cód. 9675)","stem":"A compensação é um acordo de contrabalanceamento de posições ou obrigações por contrapartes de negócios, cujo resultado é:","opts":[["a","Apuração de saldos envolvendo mais de duas partes"],["b","Apuração exclusiva da obrigação líquido dos participantes"],["c","Apuração apenas dos direitos brutos dos participantes"],["d","Múltiplo resultado líquido entre os membros de compensação e a câmara"]],"ans":"a","exp":"Tema: definição de compensação. A compensação é o acordo de contrabalanceamento de posições ou obrigações entre contrapartes, e o resultado é a apuração de saldos envolvendo mais de duas partes. Por isso a alternativa A é a correta.\n\nA alternativa B (apenas a obrigação líquida) é apenas uma parte do resultado. A alternativa C (apenas direitos brutos) está errada, porque a compensação trabalha com saldos líquidos. A alternativa D (múltiplo resultado) contraria a ideia de um saldo líquido por participante.","id":"9675"},{"n":223,"banco":"lucas","mod":2,"tit":"II","titn":"Infraestrutura do Mercado & B3","cap":"10","capn":"Questão 10 (cód. 967636)","stem":"Principal foco do Sistema de Pagamentos Brasileiro (SPB)?","opts":[["a","Promover a transparência e combater as operações fraudulentas."],["b","Evitar que os agentes participantes do mercado de capitais tenham perdas em suas operações."],["c","Gerenciamento de riscos na compensação e na liquidação das transações financeiras realizadas no SFN."],["d","Identificar como foi o desempenho do mercado em termo de volume financeiro"]],"ans":"c","exp":"Tema: foco do SPB. O Sistema de Pagamentos Brasileiro existe para gerenciar os riscos na compensação e na liquidação das transações financeiras do SFN. A alternativa C é a correta.\n\nA alternativa A (transparência e combate a fraudes) é objetivo de outros sistemas, como a entidade de registro. A alternativa B (evitar perdas dos agentes) não é o foco do SPB. A alternativa D (medir volume) não é função do sistema de pagamentos.","id":"967636"},{"n":224,"banco":"lucas","mod":2,"tit":"II","titn":"Infraestrutura do Mercado & B3","cap":"11","capn":"Questão 11 (cód. 9677)","stem":"São características do Sistema de Pagamentos Brasileiro (SPB): I. Certeza da liquidação dada pela contraparte central com base em mecanismos de gerenciamento de riscos e salvaguardas constituídas para tratamento de casos de insolvência de participantes do sistema. II. Irrevogabilidade e finalidade das liquidações. III. Uso facultativo de contrapartes centrais para a liquidação de obrigações resultantes de compensação multilateral em sistemas sistemicamente importantes. Quais estão corretas?","opts":[["a","Apenas I e II"],["b","Apenas II e III"],["c","Apenas III"],["d","Todas estão corretas"]],"ans":"a","exp":"Tema: características do SPB. Analisando:\n\nI. Correto. A certeza da liquidação vem da contraparte central, com mecanismos de risco e salvaguardas para casos de insolvência.\n\nII. Correto. As liquidações são irrevogáveis e finais.\n\nIII. Errado. O uso de contrapartes centrais é obrigatório para sistemas importantes, e não facultativo.\n\nA alternativa A (I e II) é a correta. Vale comparar com a questão 4, cuja chave diverge deste ponto.","id":"9677"},{"n":225,"banco":"lucas","mod":2,"tit":"II","titn":"Infraestrutura do Mercado & B3","cap":"12","capn":"Questão 12 (cód. 9678)","stem":"Sistema que faz liquidação bruta em tempo real (LBTR), ou seja, que processa e liquida transação por transação. Pertencente e operado pelo Banco Central do Brasil, funciona com base em transferência de fundos, que permite aos titulares das contas realizarem as liquidações interbancárias efetuadas nos mercados monetário, cambial e de capitais.","opts":[["a","CMN"],["b","Selic"],["c","STR"],["d","SPB"]],"ans":"c","exp":"Tema: sistema de liquidação bruta em tempo real (LBTR) do Banco Central. É o STR, Sistema de Transferência de Reservas, que processa transação por transação e pertence ao Bacen. A alternativa C é a correta.\n\nO Selic (B) é o sistema de liquidação e custódia de títulos públicos, não de transferências de fundos. O CMN (A) é órgão normativo, e o SPB (D) é o conjunto do sistema, e não um dos seus componentes.","id":"9678"},{"n":226,"banco":"lucas","mod":2,"tit":"II","titn":"Infraestrutura do Mercado & B3","cap":"13","capn":"Questão 13 (cód. 9679)","stem":"Sobre as Câmaras de Compensação e Liquidação, assinale o que for correto: I. Possuem contas de liquidação diretamente no Bacen e devem, obrigatoriamente, liquida, por meio dessas contas, os resultados financeiros da compensação multilateral das obrigações de seus participantes. II. Dentro do SFN são operadores, as Câmaras de Compensação e Liquidação e o Bacen são operadores. III. As transferências dos recursos, realizadas pelas instituições financeiras para liquidação de suas operações para as câmaras de compensação e liquidação, são processadas de forma irrevogável e final. Quais estão corretas?","opts":[["a","Apenas II."],["b","Apenas I e III."],["c","Apenas I."],["d","Apenas II e III."]],"ans":"b","exp":"Tema: câmaras de compensação e liquidação. Analisando:\n\nI. Correto. As câmaras têm contas de liquidação no Bacen, e por meio delas liquidam os resultados multilaterais.\n\nII. Errado. A câmara é participante do SFN, mas o termo \"operadores\" não define o papel. O Bacen é o regulador, e não o operador das câmaras.\n\nIII. Correto. As transferências para as câmaras são processadas de forma irrevogável e final.\n\nA alternativa B (I e III) é a correta.","id":"9679"},{"n":227,"banco":"lucas","mod":2,"tit":"II","titn":"Infraestrutura do Mercado & B3","cap":"14","capn":"Questão 14 (cód. 9680)","stem":"Sobre os mecanismos de mitigação de risco analise as asserções a seguir: I. No Brasil, as câmaras de compensação e liquidação sistemicamente importantes devem, obrigatoriamente, possuir modelos de gerenciamento de risco capazes de mensurar com grande confiabilidade o risco do sistema a cada instante. II. O Bacen não possui acesso às informações de liquidação de todos os participantes do mercado, mas pode visualizar as contas de liquidação das câmaras e o fluxo de mensagens referentes às liquidações diárias de operações das instituições financeiras. A respeito dessas asserções, assinale a opção correta.","opts":[["a","As asserções I e II são proposições verdadeiras, e a II é uma justificativa correta da I."],["b","A asserção I é uma proposição verdadeira, e a II é uma proposição falsa."],["c","A asserção I é uma proposição falsa, e a II é uma proposição verdadeira."],["d","As asserções I e II são proposições falsas."]],"ans":"b","exp":"Tema: mitigação de risco nas câmaras. A asserção I afirma que as câmaras sistemicamente importantes precisam de modelos de gerenciamento de risco capazes de medir o risco do sistema a cada instante. A asserção II afirma que o Bacen não tem acesso às informações de liquidação de todos os participantes, mas pode visualizar as contas das câmaras e o fluxo de mensagens.\n\nA chave indica que a I é verdadeira e a II é falsa. Mas a questão 60 do mesmo módulo considera a mesma afirmação sobre o acesso do Bacen como verdadeira. Por isso há uma inconsistência entre as duas questões. Pela teoria, a II parece verdadeira, e a alternativa A não se sustenta, porque a II não justifica a I. Vale conferir a redação original antes de considerar esta questão resolvida.","id":"9680"},{"n":228,"banco":"lucas","mod":2,"tit":"II","titn":"Infraestrutura do Mercado & B3","cap":"15","capn":"Questão 15 (cód. 9681)","stem":"A B3 é uma das principais empresas de infraestrutura de mercado financeiro no mundo, e seu nome faz referência à:","opts":[["a","Brainly , Branding e Banking"],["b","Brasil, Bolsa e Balcão"],["c","Bovespa, Bolsa Livre e Balcão"],["d","Brasil, Bovespa e Bolsa de Mercadorias e Futuros"]],"ans":"b","exp":"Tema: origem do nome B3. O nome vem de Brasil, Bolsa e Balcão, que resume as três frentes da empresa após a fusão. A alternativa B é a correta. As demais misturam nomes de empresas ou invenções, como \"Brainly\", que não têm relação com a sigla.","id":"9681"},{"n":229,"banco":"lucas","mod":2,"tit":"II","titn":"Infraestrutura do Mercado & B3","cap":"16","capn":"Questão 16 (cód. 9682)","stem":"Sobre a CIP (Câmara Interbancária de Pagamentos) assinale o que for verdadeiro: I. Processa a emissão, o resgate, o pagamento dos juros e a custódia dos títulos emitidos pelo Tesouro Nacional e pelo Bacen. II. É uma associação civil com fins lucrativos que integra o Sistema de Pagamentos Brasileiro (SPB), provendo infraestrutura aos movimentos do mercado financeiro. III. Administra o SITRAF – Sistema de Transferência de Fundos, atuando como sistema de liquidação de fundos no âmbito do SPB. IV. É responsável pela compensação e liquidação de instrumentos de pagamentos tais como TEDs e DOCs.","opts":[["a","Apenas I e II."],["b","Apenas II e III."],["c","Apenas III e IV."],["d","Apenas II, III e IV."]],"ans":"c","exp":"Tema: Câmara Interbancária de Pagamentos (CIP). Analisando:\n\nI. Errado. A emissão, o resgate, o pagamento de juros e a custódia dos títulos do Tesouro são feitos pelo Selic, e não pela CIP.\n\nII. Correto. A CIP é uma associação civil sem fins lucrativos que integra o SPB.\n\nIII. Correto. A CIP administra o SITRAF, que é o sistema de transferência de fundos.\n\nIV. Correto. A CIP compensa e liquida TEDs e DOCs.\n\nPelos itens II, III e IV, a alternativa correta seria a D. A chave indica C (III e IV), que exclui o II, o que contradiz a afirmação de que a CIP é associação sem fins lucrativos. A questão 61 do mesmo módulo considera o item II correto. Por isso a chave desta questão parece divergente. Vale conferir a natureza jurídica da CIP no material original.","id":"9682"},{"n":230,"banco":"lucas","mod":2,"tit":"II","titn":"Infraestrutura do Mercado & B3","cap":"17","capn":"Questão 17 (cód. 9683)","stem":"são as regras, para viabilizar transferências de recursos, aportes, saques e tudo o mais que puder ser definido como pagamento. Assinale alternativa que preenche corretamente a lacuna acima:","opts":[["a","COMPEs"],["b","Câmaras Interbancária de Pagamentos"],["c","Sistemas Especiais de Liquidação"],["d","Arranjos de Pagamento"]],"ans":"d","exp":"Tema: arranjos de pagamento. São as regras que viabilizam transferências de recursos, aportes, saques e outros pagamentos. Essa é a definição de arranjo de pagamento, e a alternativa D é a correta.\n\nCOMPEs (A) são as câmaras de compensação de cheques. Câmaras Interbancárias (B) são as entidades de processamento. Sistemas Especiais de Liquidação (C) são sistemas do Bacen, como o Selic. Nenhum deles é o conjunto de regras do enunciado.","id":"9683"},{"n":231,"banco":"lucas","mod":2,"tit":"II","titn":"Infraestrutura do Mercado & B3","cap":"18","capn":"Questão 18 (cód. 9684)","stem":"A História da B3 inicia-se a partir da fundação da Bolsa Livre, considerada como o embrião da BOVESPA. Mas em que ano a Bolsa Livre foi fundada?","opts":[["a","1929"],["b","1952"],["c","1970"],["d","1890"]],"ans":"d","exp":"Tema: história da B3. A Bolsa Livre, considerada o embrião da Bovespa, foi fundada em 1890. A alternativa D é a correta. Os demais anos (1929, 1952 e 1970) são de outros marcos históricos, como a Bolsa Oficial de Valores de São Paulo, que surgiu em 1935, e não da Bolsa Livre.","id":"9684"},{"n":232,"banco":"lucas","mod":2,"tit":"II","titn":"Infraestrutura do Mercado & B3","cap":"19","capn":"Questão 19 (cód. 9685)","stem":"foi criada em 30 de março de 2017, após o Conselho Administrativo de Defesa Econômica (Cade) aprovar a fusão da BMFBOVES- PA S.A. com a CETIP S.A., o que geriu uma nova empresa. Assinale a alternativa que preenche corretamente a lacuna:","opts":[["a","B3"],["b","CETIP"],["c","IBOVESPA"],["d","Bolsa Brasil"]],"ans":"a","exp":"Tema: criação da B3 em 2017. A B3 foi criada em 30 de março de 2017, após a aprovação do Cade para a fusão da BM&FBOVESPA com a CETIP. A alternativa A é a correta.\n\nCETIP (B) e Bolsa Brasil (D) são empresas que se fundiram, e o IBOVESPA (C) é um índice, e não a empresa.","id":"9685"},{"n":233,"banco":"lucas","mod":2,"tit":"II","titn":"Infraestrutura do Mercado & B3","cap":"20","capn":"Questão 20 (cód. 9686)","stem":"Sobre a B3 S.A., considere V para verdadeiro e F para falso: ( ) Com a fusão da BMFBOVESPA S.A. com a CETIP S.A., o mercado de bolsa e balcão é organizado, mas a infraestrutura do sistema financeiro brasileiro só é consolidada em uma única instituição no ano seguinte, com a compra do Bolsa Brasil. ( ) A B3 reúne os mercados de renda variável, renda fixa privada, derivativos financeiros, commodities, títulos de dívida bancária, e outros, nos segmentos de bolsa e balcão, oferecendo aos participantes de mercado e seus clientes uma solução completa de negociação, registro e pós-negociação. ( ) A B3 compreende um conjunto de empresas controladas que compõem sua estrutura corporativa. Entre elas, a Banco B3 S.A., B3 Social e BLK Sistemas Financeiros. Qual a ordem correta?","opts":[["a","F, V, V."],["b","V, F, V."],["c","F, F, V."],["d","V, V, F."]],"ans":"a","exp":"Tema: a B3 S.A. Analisando:\n\n( ) Falso. A fusão não consolidou a infraestrutura com a compra da \"Bolsa Brasil\" no ano seguinte. Essa afirmação mistura fatos e não está na teoria.\n\n( ) Verdadeiro. A B3 reúne renda variável, renda fixa privada, derivativos, commodities e outros, nos segmentos de bolsa e balcão, com negociação, registro e pós-negociação.\n\n( ) Verdadeiro. A B3 é um conjunto de empresas controladas, como o Banco B3, a B3 Social e a BLK.\n\nA ordem F, V, V corresponde à alternativa A, que é a correta.","id":"9686"},{"n":234,"banco":"lucas","mod":2,"tit":"II","titn":"Infraestrutura do Mercado & B3","cap":"21","capn":"Questão 21 (cód. 9687)","stem":"São Segmentos da B3:","opts":[["a","Balcão B3, NDF e Mercado a Termo."],["b","Registro de companhias abertas (S.A), Listado B3, e NTN-F."],["c","Listado B3, Balcão B3 e Estrutura para Financiamento."],["d","SWAP, Mercado a Termo e Clearing."]],"ans":"c","exp":"Tema: segmentos da B3. Os três segmentos são o Listado B3, o Balcão B3 e a Estrutura para Financiamento. A alternativa C é a correta.\n\nAs demais misturam produtos, instrumentos ou conceitos, como NDF, swap e NTN-F, que não são segmentos da B3.","id":"9687"},{"n":235,"banco":"lucas","mod":2,"tit":"II","titn":"Infraestrutura do Mercado & B3","cap":"22","capn":"Questão 22 (cód. 9688)","stem":"Segmento da B3 que a torna líder nas atividades de registro, depósito, negociação e liquidação de instrumentos financeiros de renda fixa e derivativos de balcão, funcionando como uma solução única e integrada para estes mercados:","opts":[["a","Derivativos"],["b","Listado B3"],["c","Balcão B3"],["d","Estrutura para Financiamento"]],"ans":"c","exp":"Tema: segmento Balcão B3. Ele é o segmento de registro, depósito, negociação e liquidação de renda fixa e de derivativos de balcão, com solução integrada. A alternativa C é a correta.\n\nDerivativos (A) e Listado B3 (B) não atendem à descrição de renda fixa de balcão, e a Estrutura para Financiamento (D) é outro segmento, voltado a garantias e financiamentos.","id":"9688"},{"n":236,"banco":"lucas","mod":2,"tit":"II","titn":"Infraestrutura do Mercado & B3","cap":"23","capn":"Questão 23 (cód. 9689)","stem":"Sobre os participantes da B3 analise as asserções abaixo: I. O participante de negociação (PN) é a instituição autorizada pela B3 a acessar diretamente os sistemas de negociação administrados pela B3 para a realização de negócios para carteira própria e para seus clientes. II. Os participantes autorizados da B3 são as instituições (corretoras, distribuidoras de valores mobiliários e bancos) que mantêm vínculos formais com a bolsa, a câmara de compensação e liquidação, e a central depositária para o desempenho das atividades de negociação e/ou liquidação e/ou custódia, nos diversos segmentos de mercado. A respeito dessas asserções, assinale a opção correta.","opts":[["a","As asserções I e II são proposições verdadeiras, e a II é uma justificativa correta da I."],["b","A asserção I é uma proposição verdadeira, e a II é uma proposição falsa."],["c","A asserção I é uma proposição falsa, e a II é uma proposição verdadeira."],["d","As asserções I e II são proposições falsas."]],"ans":"c","exp":"Tema: participantes da B3. Analisando:\n\nI. Errado. Quem acessa diretamente os sistemas da B3 é o PNP (Participante de Negociação Pleno), e não o PN, que atua para clientes por meio de um PNP.\n\nII. Correto. Os participantes autorizados são as instituições que mantêm vínculos formais com a bolsa, a câmara e a central depositária.\n\nA alternativa C (I falsa e II verdadeira) é a correta.","id":"9689"},{"n":237,"banco":"lucas","mod":2,"tit":"II","titn":"Infraestrutura do Mercado & B3","cap":"24","capn":"Questão 24 (cód. 9690)","stem":"Quais os critérios que a B3 utiliza para autorizar determinado segmento de mercado? I. Grupo de Mercados, isso é, descrição dos segmentos nos quais as instituições estarão autorizadas a operar. II. Elegibilidade, que trata a determinação de quais tipos de instituições podem ser autorizadas a atuar em diversos segmentos de mercado, nos termos da regulação em vigor. III. Capacitação Financeira e Operacional, que consiste em uma série de exigências, determinadas pela B3, dentro da esfera da autorregulação dos mercados, que têm natureza prudencial e visam contribuir para a preservação do bom funcionamento e da integridade dos mercados. Quais estão corretas?","opts":[["a","Apenas I e II."],["b","Apenas II e III."],["c","Apenas I e III."],["d","Todas estão corretas."]],"ans":"d","exp":"Tema: critérios de autorização de segmentos. A B3 usa três critérios: grupo de mercados, em que se descrevem os segmentos de atuação; elegibilidade, que define quais tipos de instituição podem atuar; e capacitação financeira e operacional, com exigências de natureza prudencial. Todos os itens estão corretos, e a alternativa D é a correta.","id":"9690"},{"n":238,"banco":"lucas","mod":2,"tit":"II","titn":"Infraestrutura do Mercado & B3","cap":"25","capn":"Questão 25 (cód. 9691)","stem":"Sobre o acesso ao Sistemas de Negociação Eletrônica, assinale o que for correto: I. PUMA Trading System é a plataforma eletrônica de negociação multiativos desenvolvida pela B3 em conjunto com o CME Group. II. É possível ter acesso pela plataforma o GTS (Global Trading System) e Sisbex (usado para títulos públicos). III. Uma das formas de acesso à plataforma é pelo encaminhamento de ordens dadas pelos investidores, seus clientes ao PNP, por meio de um terminal de negociação próprio ou fornecido pelo B3. IV. Outra forma de acesso à plataforma é através do DMA (Direct Market Access) que isenta o acesso de autorização e controle do PN ou PNP.","opts":[["a","Apenas I e II."],["b","Apenas III e IV."],["c","Apenas I e III."],["d","Apenas II e IV."]],"ans":"c","exp":"Tema: acesso aos sistemas de negociação eletrônica. Analisando:\n\nI. Duvidoso. O PUMA é o sistema multiativos da B3, mas a teoria desta edição não confirma a parceria com o CME Group citada no item.\n\nII. Correto. A teoria lista o GTS e o Sisbex entre os sistemas de negociação eletrônica.\n\nIII. Correto. O investidor encaminha ordens ao PNP, por terminal próprio ou fornecido pela B3.\n\nIV. Errado. O DMA não isenta de controle. Ele exige o controle de risco pré-negociação, e o acesso continua sob responsabilidade do PN ou PNP.\n\nA chave indica C (I e III), mas pela análise o item II também seria correto e o I é duvidoso. Pelo texto, nenhuma alternativa combina II e III, então o enunciado parece ter um problema de redação. Vale conferir o material original.","id":"9691"},{"n":239,"banco":"lucas","mod":2,"tit":"II","titn":"Infraestrutura do Mercado & B3","cap":"26","capn":"Questão 26 (cód. 9692)","stem":"São as Câmaras de Compensação e Liquidação na B3 (clearings):","opts":[["a","Clearing de CBLC e Banco BM&F."],["b","Clearing de Ações e Renda Fixa, Câmbio, Ativos e Derivativos."],["c","Clearing de Câmbio, derivativos e IPN."],["d","Clearing de Banco BM&F, dívida corporativa e mutualização."]],"ans":"b","exp":"Tema: câmaras de compensação e liquidação da B3 (clearings). A clearing única reúne as antigas câmaras de ações e renda fixa, câmbio, ativos e derivativos. A alternativa B é a correta.\n\nAs demais alternativas trazem nomes que não correspondem às clearings, como \"Banco BM&F\" e \"IPN\", que não são as câmaras da B3.","id":"9692"},{"n":240,"banco":"lucas","mod":2,"tit":"II","titn":"Infraestrutura do Mercado & B3","cap":"27","capn":"Questão 27 (cód. 9693)","stem":"Acerca da Clearing B3, analise as asserções a seguir e a relação entre elas: I. Os dois maiores segmentos de mercado da B3 usufruem de uma estrutura única e integrada, que conta com regras uniformes de acesso, uma estrutura única de salvaguardas, um único netting multilateral e uma única janela de liquidação. II. A B3 decidiu que a implantação da Câmara integrada se daria por meio da transferência progressiva das atividades das quatro câmaras existentes para a nova estrutura, a Câmara B3 ou Clearing Única. A respeito dessas asserções, assinale a opção correta.","opts":[["a","As asserções I e II são proposições verdadeiras, e a II é uma justificativa correta da I."],["b","A asserção I é uma proposição verdadeira, e a II é uma proposição falsa."],["c","A asserção I é uma proposição falsa, e a II é uma proposição verdadeira."],["d","As asserções I e II são proposições falsas."]],"ans":"a","exp":"Tema: estrutura integrada da clearing única. A asserção I afirma que os dois maiores segmentos usam uma estrutura única, com regras e salvaguardas comuns, um único netting e uma única janela de liquidação. A asserção II afirma que a implantação foi feita de forma progressiva, transferindo as atividades das quatro câmaras para a Câmara B3.\n\nAs duas afirmações são verdadeiras. Mas a II descreve como a estrutura foi implantada, e não a razão da estrutura única descrita na I. Por isso a II não justifica a I. A chave indica A, que trata a II como justificativa, e isso não se sustenta pela redação. Vale conferir a redação original.","id":"9693"},{"n":241,"banco":"lucas","mod":2,"tit":"II","titn":"Infraestrutura do Mercado & B3","cap":"28","capn":"Questão 28 (cód. 9694)","stem":"Empresa criada em 2007, integrante do grupo B3 e constituída para realizar, com autonomia administrativa e orçamentária, as atividades de supervisão dos mercados administrados pela B3:","opts":[["a","CBLC"],["b","BSM"],["c","ETF"],["d","CEPEA"]],"ans":"b","exp":"Tema: BSM Supervisão de Mercados. Ela foi criada em 2007, faz parte do grupo B3 e tem autonomia administrativa e orçamentária para supervisionar os mercados. A alternativa B é a correta.\n\nCBLC (A) é a câmara de liquidação e custódia, ETF (C) é um tipo de fundo, e o CEPEA (D) é um centro de estudos de agronegócio. Nenhum deles é a supervisora.","id":"9694"},{"n":242,"banco":"lucas","mod":2,"tit":"II","titn":"Infraestrutura do Mercado & B3","cap":"29","capn":"Questão 29 (cód. 9695)","stem":"Estão entre as principais frentes de atuação da BSM: I. O monitoramento de boa parte das ofertas e negócios realizados nos mercados da B3 para identificação de indícios de irregularidades; II. Fiscalização e supervisão dos participantes da B3 e da própria B3. III. Identificação das condições anormais de negociação ou comportamentos que possam colocar em risco a regularidade de funcionamento, a transparência e credibilidade do mercado IV. Instauração e condução de processos administrativos disciplinares para apurar infrações às normas e, se for o caso, penalizar quem cometer irregularidades. Quais estão corretas?","opts":[["a","Apenas I e II."],["b","Apenas III e IV."],["c","Apenas I, II e III."],["d","Apenas II, III e IV."]],"ans":"d","exp":"Tema: frentes de atuação da BSM. Analisando:\n\nI. Correto. A BSM monitora ofertas e negócios para identificar indícios de irregularidades.\n\nII. Correto. A BSM fiscaliza e supervisiona os participantes e a própria B3.\n\nIII. Correto. A BSM identifica condições anormais de negociação que coloquem em risco a regularidade e a credibilidade do mercado.\n\nIV. Correto. A BSM instaura e conduz processos administrativos disciplinares e aplica penalidades.\n\nTodos os quatro itens são atribuições da BSM, o que daria a alternativa com todos eles. A chave indica D (II, III e IV), que exclui o I, mas a teoria confirma o monitoramento do item I. Por isso há uma divergência de chave a conferir.","id":"9695"},{"n":243,"banco":"lucas","mod":2,"tit":"II","titn":"Infraestrutura do Mercado & B3","cap":"30","capn":"Questão 30 (cód. 9696)","stem":"Sobre o market data, é possível afirmar que:","opts":[["a","Serviço da B3 que envia, em tempo real e para qualquer lugar do mundo, informações geradas pela bolsa e notícias econômicas sobre o mercado de ações e derivativos."],["b","Serviço da B3 que envia, em tempo real, para as instituições participantes, informações geradas pela bolsa e notícias econômicas sobre o mercado de ações e derivativos."],["c","Consolida os dados dos mercados atendidos pela B3 e os organiza em forma de dashboards, possibilitando a consulta de informações relevantes para negócios de forma mais ágil e inteligente."],["d","Otimiza a retaguarda das instituições financeiras participantes do mercado com base em informatização e atividades operacionais para controle."]],"ans":"a","exp":"Tema: market data. É o serviço da B3 que envia, em tempo real, às instituições participantes, informações geradas pela bolsa e notícias econômicas sobre ações e derivativos. A alternativa A diz \"para qualquer lugar do mundo\", que ultrapassa o público das instituições participantes. Por isso a alternativa B é a que descreve o serviço corretamente, mas a chave indica A. Esta é uma divergência de redação a conferir.","id":"9696"},{"n":244,"banco":"lucas","mod":2,"tit":"II","titn":"Infraestrutura do Mercado & B3","cap":"31","capn":"Questão 31 (cód. 9697)","stem":"São informações geradas pelo market data:","opts":[["a","Cotações de ações negociadas, índices e renda fixa corporativa de instituições habilitadas pela B3 para acessar o mercado de capitais."],["b","Cotações de ações negociadas, índices, renda fixa corporativa, notícias sobre o mercado de bolsa, informações de derivativos, câmbio e notícias sobre os mercados derivativos e futuros."],["c","Cotações de ações negociadas, índices, renda fixa corporativa, notícias sobre o mercado de bolsa e informações de derivativos exclusivamente a investidores pessoa física."],["d","Cotações de ações negociadas, índices, renda fixa corporativa, notícias sobre o mercado de bolsa, informações sobre derivativos, câmbio de empresas listadas para consolidação de balanço anual perante a CVM."]],"ans":"b","exp":"Tema: conteúdo do market data. O market data reúne cotações de ações negociadas, índices, renda fixa corporativa, notícias sobre o mercado de bolsa e informações de derivativos e câmbio. A alternativa B traz exatamente esse conjunto. As demais restringem o público ou incluem itens que não fazem parte do market data, como balanços anuais, que são obrigações de companhias e não de dados de mercado.","id":"9697"},{"n":245,"banco":"lucas","mod":2,"tit":"II","titn":"Infraestrutura do Mercado & B3","cap":"32","capn":"Questão 32 (cód. 9698)","stem":"Dentre os sistemas presentes no mercado de capitais e disponibilizados pela B3, o iBalcão refere – se a um sistema:","opts":[["a","Administrado pela CVM e disponibilizado pela B3 para controle de ofertas públicas no mercado de capitais."],["b","Administrado pela B3 para registro de operações realizadas no mercado de balcão com derivativos e títulos de renda fixa específico para o segmento listado B3."],["c","Utilizado para controle das operações de câmbio pronto no mercado de balcão e bolsa, com fiscalização da B3 e do BACEN."],["d","Disponibilizado as instituições financeiras participantes para cotação em tempo real de ativos e contratos negociados."]],"ans":"b","exp":"Tema: iBalcão. É um sistema administrado pela B3 para registro de operações do mercado de balcão, com derivativos e títulos de renda fixa. A alternativa B é a correta.\n\nA alternativa A atribui o sistema à CVM, o que não corresponde. A alternativa C fala em câmbio pronto em bolsa, e a alternativa D descreve um sistema de cotação, e não o registro do balcão. A teoria desta edição não detalha o iBalcão, então essa resposta depende de conhecimento complementar.","id":"9698"},{"n":246,"banco":"lucas","mod":2,"tit":"II","titn":"Infraestrutura do Mercado & B3","cap":"33","capn":"Questão 33 (cód. 9699)","stem":"Sobre o iBalcão, pode – se afirmar que:","opts":[["a","Sistema que reúne todas as informações sobre registro, acesso, monitoramento, regulamentação, regras operacionais, custos e estatísticas."],["b","Consolida os dados dos mercados atendidos pela B3 e os organiza em forma de dashboards, possibilitando a consulta de informações relevantes para negócios de forma mais fácil, ágil e inteligente."],["c","Otimiza a retaguarda das instituições financeiras participantes do mercado com base em informatização e atividades operacionais para controle."],["d","Refere – se ao sistema de negociação eletrônica de ativos, do qual permite a inserção de ordens de compra e venda."]],"ans":"a","exp":"Tema: iBalcão, como sistema de informações. A alternativa A descreve um sistema que reúne informações sobre registro, acesso, monitoramento, regulamentação, regras operacionais, custos e estatísticas do balcão. A alternativa A é a correta, de acordo com a chave. A teoria desta edição não detalha o iBalcão, então vale conferir a descrição oficial do sistema.","id":"9699"},{"n":247,"banco":"lucas","mod":2,"tit":"II","titn":"Infraestrutura do Mercado & B3","cap":"34","capn":"Questão 34 (cód. 9700)","stem":"Sobre o DATAWISE, pode – se afirmar que:","opts":[["a","Consolida os dados dos mercados atendidos pela B3 e os organiza em forma de dashboards, possibilitando a consulta de informações relevantes para negócios de forma mais fácil, ágil e inteligente."],["b","Refere – se ao sistema de consolidação de contas e cadastros de investidores pessoas físicas e institucionais na bolsa de valores."],["c","Otimiza a retaguarda das instituições participantes do mercado com base em informatização e atividades operacionais para controle."],["d","Possibilita o envio de ordens de compra e venda de ativos para o sistema PUMA."]],"ans":"a","exp":"Tema: DATAWISE. É o sistema que consolida dados dos mercados da B3 e os organiza em dashboards, facilitando a consulta de informações para negócios. A alternativa A é a correta. As demais descrevem cadastro de investidores, retaguarda e envio de ordens, que são funções de outros sistemas. A teoria desta edição não detalha o DATAWISE.","id":"9700"},{"n":248,"banco":"lucas","mod":2,"tit":"II","titn":"Infraestrutura do Mercado & B3","cap":"35","capn":"Questão 35 (cód. 9701)","stem":"O SINACOR é característico por ser um sistema que:","opts":[["a","Permite a inserção de ordens de compra e venda de investidores pessoa física."],["b","Otimiza a retaguarda das instituições participantes do mercado com base em informatização e atividades operacionais para controle."],["c","Atua como contraparte central das operações em bolsas de valores."],["d","Permite a negociação de ativos fora do ambiente de bolsa de valores."]],"ans":"b","exp":"Tema: SINACOR. É um sistema de otimização da retaguarda das corretoras, com informatização e atividades operacionais de controle. A alternativa B é a correta.\n\nA alternativa A (inserção de ordens de pessoa física) descreve o ambiente de negociação. A alternativa C (contraparte central) é função da câmara. A alternativa D (negociação fora da bolsa) não é o papel do SINACOR.","id":"9701"},{"n":249,"banco":"lucas","mod":2,"tit":"II","titn":"Infraestrutura do Mercado & B3","cap":"36","capn":"Questão 36 (cód. 9702)","stem":"Sobre o SINACOR, pode – se afirmar que:","opts":[["a","Atua como contraparte central das operações em bolsas de valores."],["b","Informatiza e integra as corretoras com objetivo de maior lucratividade para o mercado de capitais."],["c","É oferecido exclusivamente a corretoras com alta classificação de crédito para atuar no mercado de câmbio em bolsa de valores."],["d","É oferecido aos participantes que possuem acesso ao ambiente de negociação e pós negociação, de acordo com seu perfil de relacionamento e conformidade com regulamentos e normas da B3 nas câmaras."]],"ans":"d","exp":"Tema: SINACOR, pelo acesso aos ambientes. Ele é oferecido aos participantes que têm acesso ao ambiente de negociação e pós-negociação, de acordo com seu perfil de relacionamento e a conformidade com as regras da B3. A alternativa D é a correta.\n\nA alternativa A (contraparte central) é função da câmara. A alternativa B fala em maior lucratividade, o que não é o objetivo declarado. A alternativa C restringe o sistema a corretoras de alto crédito, o que não é a regra.","id":"9702"},{"n":250,"banco":"lucas","mod":2,"tit":"II","titn":"Infraestrutura do Mercado & B3","cap":"37","capn":"Questão 37 (cód. 9703)","stem":"O mercado de capitais conta com sistema e mecanismos para melhor funcionamento e apoio aos agentes do mercado, entre eles o Sistema Integrado de Administração de Corretoras. Sobre sua atuação e características, pode – se afirmar que:","opts":[["a","Está presente na maioria das corretoras e é responsável por otimizar a atuação dos agentes do mercado, facilitando suas atividades de controle e operacionais."],["b","Está presente em todas as corretoras, sendo o responsável pelo recebimento das ordens e repasse ao pit de negociação para efetivação."],["c","Atua no registro e controle de operações de câmbio via mercado de balcão e mercado de bolsa de valores."],["d","É oferecido aos participantes que possuem acesso ao ambiente de negociação e pós negociação de acordo com regimentos definidos pelo BACEN."]],"ans":"a","exp":"Tema: Sistema Integrado de Administração de Corretoras. Ele está presente na maioria das corretoras e otimiza a atuação dos agentes, facilitando as atividades de controle e operacionais. A alternativa A é a correta.\n\nA alternativa B (presença em todas as corretoras e recebimento de ordens) não é a função do sistema. A alternativa C (câmbio) não é o foco. A alternativa D atribui a regra ao BACEN, e não à B3.","id":"9703"},{"n":251,"banco":"lucas","mod":2,"tit":"II","titn":"Infraestrutura do Mercado & B3","cap":"38","capn":"Questão 38 (cód. 9704)","stem":"Denomina – se apregoação por oferta:","opts":[["a","Aquela em que o operador interessado em comprar ou vender os ativos demonstra sua intenção especificando ativo, lote e preço, obrigatoriamente."],["b","Aquela em que o investidor deseja inserir oferta restrita ao valor de negociação do momento da operação."],["c","Aquela em que o operador interessado em comprar ou vender ativos realiza o lucro em oferta vendedora de ações."],["d","Aquela em que o investidor insere ofertas fora do ambiente de negociação de bolsa de valores, via SINACOR."]],"ans":"a","exp":"Tema: apregoação por oferta. É a forma em que o operador interessado em comprar ou vender demonstra sua intenção, especificando o ativo, o lote e o preço. A alternativa A é a correta.\n\nA alternativa B (oferta restrita ao valor do momento) não descreve a apregoação. A alternativa C (lucro em oferta vendedora) não define o termo. A alternativa D (oferta fora da bolsa via SINACOR) não é o conceito.","id":"9704"},{"n":252,"banco":"lucas","mod":2,"tit":"II","titn":"Infraestrutura do Mercado & B3","cap":"39","capn":"Questão 39 (cód. 9642)","stem":"No que tange ao conceito de “melhor execução da ordem”, analise as afirmativas abaixo: I. Na existência de mais de um sistema de negociação, o conceito não se aplica II. É responsável por conter conflitos de interesses que venham a surgir na intermediação de ordens de clientes III. É apresentado na Instrução CVM nº 505 É correto o que se afirma em:","opts":[["a","I e II"],["b","I e III"],["c","II e III"],["d","Todas as alternativas"]],"ans":"c","exp":"Tema: melhor execução de ordem. Analisando:\n\nI. Errado. O conceito se aplica mesmo quando há mais de um sistema de negociação, porque a divergência de preços entre sistemas não elimina o dever de executar no melhor resultado possível.\n\nII. Correto. A melhor execução serve para conter conflitos de interesse na intermediação de ordens de clientes.\n\nIII. Correto. O conceito é apresentado na Instrução CVM 505.\n\nA alternativa C (II e III) é a correta.","id":"9642"},{"n":253,"banco":"lucas","mod":2,"tit":"II","titn":"Infraestrutura do Mercado & B3","cap":"40","capn":"Questão 40 (cód. 9643)","stem":"Sobre o sistema de liquidação, visto a abordagem internacional, analise as afirmativas abaixo: I. O DvP, mecanismo do qual os ativos são entregues somente mediante pagamento, não está presente II. É permitido a transferência de ativos livres de pagamento. III. Compensação e liquidação são serviços que também podem ser prestados É correto o que se afirma em:","opts":[["a","I e II"],["b","I e III"],["c","II e III"],["d","Todas as alternativas"]],"ans":"c","exp":"Tema: sistema de liquidação na abordagem internacional. Analisando:\n\nI. Errado. O DvP (entrega contra pagamento) é um mecanismo presente na liquidação, justamente para que o ativo só seja entregue mediante pagamento.\n\nII. Correto. É permitido transferir ativos livres de pagamento, que são operações sem contrapartida financeira.\n\nIII. Correto. Compensação e liquidação são serviços que podem ser prestados por diferentes entidades.\n\nA alternativa C (II e III) é a correta.","id":"9643"},{"n":254,"banco":"lucas","mod":2,"tit":"II","titn":"Infraestrutura do Mercado & B3","cap":"41","capn":"Questão 41 (cód. 9644)","stem":"Faz parte das responsabilidades da BSM Supervisão de Mercados: I. Coordenar e implantar processos administrativos para apuração de infrações, além de penalizar quem cometer irregularidades II. Realizar supervisão e fiscalização sob a B3 e seus participantes III. Detectar condições incomuns de negociação ou condutas que possam colocar em risco a estabilidade de funcionamento, a transparência e confiabilidade do mercado É correto que se afirma em:","opts":[["a","I e II"],["b","I e III"],["c","II e III"],["d","Todas as alternativas"]],"ans":"d","exp":"Tema: responsabilidades da BSM. A BSM coordena processos administrativos para apurar infrações e penalizar quem as cometer, realiza supervisão e fiscalização da B3 e de seus participantes, e detecta condições incomuns de negociação que possam colocar em risco a estabilidade e a confiabilidade do mercado. Os três itens procedem, e a alternativa D é a correta.","id":"9644"},{"n":255,"banco":"lucas","mod":2,"tit":"II","titn":"Infraestrutura do Mercado & B3","cap":"42","capn":"Questão 42 (cód. 9645)","stem":"Sobre o conceito de \"compensação multilateral\": I. É possível ser entendida como o levantamento de saldos abrangendo mais de duas partes II. Refere – se a um acordo de contrabalanceamento de posições ou obrigações por contrapartes de negócios do qual resulta na apuração de saldos que diminui um alto número de posições ou obrigações individuais a um número menor. III. É possível significar o processo de cálculo das obrigações bilaterais dos participantes do mercado, geralmente em bases líquidas, para a permuta de títulos e dinheiro. É correto o que se afirma em:","opts":[["a","I e II"],["b","I e III"],["c","II e III"],["d","Todas as alternativas"]],"ans":"d","exp":"Tema: compensação multilateral. Analisando:\n\nI. Correto. A compensação envolve o levantamento de saldos entre mais de duas partes.\n\nII. Correto. É um acordo de contrabalanceamento que reduz um grande número de posições individuais a um número menor.\n\nIII. Errado para a compensação multilateral. O item descreve o cálculo de obrigações bilaterais em bases líquidas, o que é a compensação bilateral, e não a multilateral.\n\nA chave indica D (todas corretas), que considera o item III certo. Pela definição de compensação multilateral, esse item está incorreto, então a resposta mais coerente seria a A (I e II). Vale conferir a redação original.","id":"9645"},{"n":256,"banco":"lucas","mod":2,"tit":"II","titn":"Infraestrutura do Mercado & B3","cap":"43","capn":"Questão 43 (cód. 9646)","stem":"Sobre a entidade de registro, visto a abordagem internacional, analise as afirmativas abaixo: I. Uma de suas funções é proporcionar informação que ampare a diminuição do risco, a eficiência operacional e a contenção de custos. II. O mercado de derivativos de balcão não é afetado pela entidade de registro. III. Assegura um sistema descentralizado para registro de transações. É correto o que se afirma em:","opts":[["a","I"],["b","I e II"],["c","II e III"],["d","Todas as alternativas"]],"ans":"a","exp":"Tema: entidade de registro na abordagem internacional. Analisando:\n\nI. Correto. A entidade de registro fornece informação que apoia a redução de risco, a eficiência operacional e a contenção de custos.\n\nII. Errado. O mercado de derivativos de balcão é diretamente afetado pela entidade de registro, que o registra e divulga.\n\nIII. Errado. A entidade de registro assegura um sistema centralizado, e não descentralizado, como diz o item.\n\nA alternativa A (apenas I) é a correta.","id":"9646"},{"n":257,"banco":"lucas","mod":2,"tit":"II","titn":"Infraestrutura do Mercado & B3","cap":"44","capn":"Questão 44 (cód. 9647)","stem":"Pertence ao Banco Central do Brasil e funciona com base em ordens de crédito, do qual é designado como o sistema de transferência de fundos com liquidação bruta em tempo real (LBTR).","opts":[["a","CETIP"],["b","STR"],["c","SITRAF"],["d","SELIC"]],"ans":"a","exp":"Tema: sistema de transferência de fundos com liquidação bruta em tempo real, pertencente ao Banco Central. Essa é a descrição do STR, o Sistema de Transferência de Reservas, que processa ordens de crédito em LBTR. A alternativa B é a correta.\n\nA chave indica A (CETIP), mas a CETIP é uma entidade de registro e liquidação de títulos privados, e não pertence ao Banco Central. Pela teoria desta edição, a descrição do enunciado corresponde ao STR, o que confirma a questão 12. Por isso a chave parece divergente. Vale conferir o material original.","id":"9647"},{"n":258,"banco":"lucas","mod":2,"tit":"II","titn":"Infraestrutura do Mercado & B3","cap":"45","capn":"Questão 45 (cód. 9648)","stem":"A respeito da Bolsa de Valores, a B3, analise as afirmativas abaixo: I. Através de sua câmara de compensação e liquidação, te atuação como contraparte central na liquidação das operações. II. Também atua como um sistema de liquidação bruta em tempo real, nas operações registradas no segmento CETIP UTVM, permite, em alguns casos, a compensação bilateral entre participantes. III. Atua como central depositária de títulos e valores mobiliários de renda variável, essencialmente ações, renda fixa corporativa, debêntures e cotas de fundos, além de títulos públicos estaduais e municipais, títulos representativos de dívida bancária e ouro. Está correto o que se afirma em:","opts":[["a","I e II"],["b","I e III"],["c","II e III"],["d","Todas as alternativas"]],"ans":"d","exp":"Tema: atuação da B3 como contraparte, liquidação e depositária. Analisando:\n\nI. Correto. Pela câmara de compensação e liquidação, a B3 atua como contraparte central.\n\nII. Correto. A B3 atua como sistema de liquidação bruta em tempo real no segmento CETIP UTVM, e em alguns casos permite compensação bilateral.\n\nIII. Correto. A B3 atua como central depositária de renda variável, renda fixa corporativa, debêntures, cotas de fundos, títulos públicos estaduais e municipais, dívida bancária e ouro.\n\nA alternativa D (todas) é a correta.","id":"9648"},{"n":259,"banco":"lucas","mod":2,"tit":"II","titn":"Infraestrutura do Mercado & B3","cap":"46","capn":"Questão 46 (cód. 9649)","stem":"É responsável por manter ambientes e sistemas de negociação eletrônica de ativos do qual instituições habilitadas podem negociar valores mobiliários, títulos e derivativos para clientes ou em nome próprio.","opts":[["a","Central depositária"],["b","Bolsa de valores"],["c","Contraparte central"],["d","Sistema de liquidação"]],"ans":"b","exp":"Tema: bolsa de valores. A bolsa mantém ambientes e sistemas de negociação eletrônica, nos quais instituições habilitadas negociam valores mobiliários, títulos e derivativos para clientes ou em nome próprio. A alternativa B é a correta.\n\nA central depositária (A) guarda os ativos, a contraparte central (C) garante a liquidação e o sistema de liquidação (D) processa a transferência. Nenhuma delas mantém o ambiente de negociação.","id":"9649"},{"n":260,"banco":"lucas","mod":2,"tit":"II","titn":"Infraestrutura do Mercado & B3","cap":"47","capn":"Questão 47 (cód. 9650)","stem":"Dentre as auditorias da BSM Supervisão de Mercados, esta é responsável por garantir o funcionamento adequado das ferramentas de acesso direto ao mercado, importante para que participantes possuam sistemas de controle de risco pré negociação, além de auditar tais ferramentas de controle por meio de uma auditoria:","opts":[["a","Indireta"],["b","DMA"],["c","Operacional"],["d","Pré operacional"]],"ans":"b","exp":"Tema: auditoria de acesso direto ao mercado. A BSM audita as ferramentas de acesso direto (DMA), para verificar se os controles de risco pré-negociação estão funcionando. A alternativa B (DMA) é a correta, porque é a auditoria voltada ao acesso direto.\n\nAs outras opções (indireta, operacional e pré-operacional) não são as auditorias descritas no enunciado.","id":"9650"},{"n":261,"banco":"lucas","mod":2,"tit":"II","titn":"Infraestrutura do Mercado & B3","cap":"48","capn":"Questão 48 (cód. 9651)","stem":"As instituições e órgãos presentes no Sistema Financeiro Nacional são responsáveis por:","opts":[["a","Regular apenas o processo de IPO de títulos e sua distribuição."],["b","Realizar captação de recursos financeiros, distribuição e movimentar valores, assim como regular este processo."],["c","Realizar transferência de valores apenas entre investidores internos e externos."],["d","Realizar distribuição e movimentar valores e títulos mobiliários."]],"ans":"b","exp":"Tema: funções das instituições do SFN. Elas captam recursos, distribuem e movimentam valores, e também são reguladas nesse processo. A alternativa B reúne essas funções, e é a correta.\n\nA alternativa A limita a regulação ao IPO, o que é restrito demais. A alternativa C limita a transferência a investidores internos e externos, sem o restante das funções. A alternativa D limita a função à distribuição de títulos, deixando de lado a captação.","id":"9651"},{"n":262,"banco":"lucas","mod":2,"tit":"II","titn":"Infraestrutura do Mercado & B3","cap":"49","capn":"Questão 49 (cód. 9652)","stem":"Possui atribuição de assegurar a integridade dos ativos custodiados em seu ambiente, atuando na prevenção para que ativos não sejam criados de forma acidental ou fraudulenta, extintos ou que tenham suas características alteradas.","opts":[["a","Contraparte central"],["b","Bolsa de valores"],["c","Central depositária"],["d","Sistema de liquidação"]],"ans":"c","exp":"Tema: integridade dos ativos custodiados. Quem assegura que os ativos não sejam criados, extintos ou alterados de forma indevida é a central depositária. A alternativa C é a correta.\n\nA contraparte central (A) garante a liquidação, a bolsa (B) negocia e o sistema de liquidação (D) transfere os ativos. A integridade dos ativos custodiados é função da central depositária, conforme a teoria desta edição.","id":"9652"},{"n":263,"banco":"lucas","mod":2,"tit":"II","titn":"Infraestrutura do Mercado & B3","cap":"50","capn":"Questão 50 (cód. 9653)","stem":"A respeito do Sistema de Liquidação e Custódia (SELIC): I. É responsável por ser a contraparte central na liquidação de operações; II. Atua como custodiante dos títulos do Tesouro Nacional; III. Atua no registro de operações compromissadas e definitivas do mercado de balcão. Está correto o que se afirma em:","opts":[["a","I e II"],["b","I e III"],["c","II e III"],["d","Todas as alternativas"]],"ans":"c","exp":"Tema: SELIC. Analisando:\n\nI. Errado. O Selic não é contraparte central. Sua função é liquidação bruta e custódia de títulos públicos, sem ser contraparte.\n\nII. Correto. O Selic atua como custodiante dos títulos do Tesouro Nacional.\n\nIII. Correto. O Selic registra operações compromissadas e definitivas do mercado de balcão.\n\nA alternativa C (II e III) é a correta.","id":"9653"},{"n":264,"banco":"lucas","mod":2,"tit":"II","titn":"Infraestrutura do Mercado & B3","cap":"51","capn":"Questão 51 (cód. 9654)","stem":"Entre os principais componentes do mercado financeiro, a central depositária, segundo a abordagem internacional: I. É possível manter ativos depositados de forma física (imobilizados) ou desmaterializado, mediante registro eletrônico II. É possível manter estrutura de contas direta em nome do beneficiário final III. Realiza serviços de guarda centralizada e de tratamento de eventos incidentes sobre os ativos Está correto o que se afirma em:","opts":[["a","I e II"],["b","I e III"],["c","II e III"],["d","Todas as alternativas"]],"ans":"d","exp":"Tema: central depositária na abordagem internacional. Analisando:\n\nI. Correto. Os ativos podem ser mantidos fisicamente ou desmaterializados, por registro eletrônico.\n\nII. Correto. A central pode manter estrutura de contas direta em nome do beneficiário final.\n\nIII. Correto. A central presta guarda centralizada e trata eventos incidentes sobre os ativos.\n\nA alternativa D (todas) é a correta.","id":"9654"},{"n":265,"banco":"lucas","mod":2,"tit":"II","titn":"Infraestrutura do Mercado & B3","cap":"52","capn":"Questão 52 (cód. 9655)","stem":"Tem função de atuar como comprador de todos os vendedores, além de vendedor de todos os compradores:","opts":[["a","Sistema de liquidação"],["b","Bolsa de valores"],["c","A central depositária"],["d","A contraparte central"]],"ans":"d","exp":"Tema: contraparte central. Ela atua como comprador de todos os vendedores e vendedor de todos os compradores, por meio da novação ou de instituto equivalente. A alternativa D é a correta.\n\nO sistema de liquidação (A) processa a transferência de ativos, a bolsa (B) negocia, e a central depositária (C) guarda os ativos. Nenhuma delas assume a posição de contraparte de todos.","id":"9655"},{"n":266,"banco":"lucas","mod":2,"tit":"II","titn":"Infraestrutura do Mercado & B3","cap":"53","capn":"Questão 53 (cód. 9656)","stem":"Entre os principais componentes do mercado financeiro, a bolsa de valores, segundo a abordagem internacional: I. Realiza a listagem dos emissores do qual os ativos são negociados no mercado secundário II. É responsável por assegurar elevado nível de transparência no mercado pré e pós negociação, além de promover a boa formação de preços III. É responsável por manter sistemas de negociação eletrônica do qual instituições habilitadas podem negociar títulos, derivativos e valores mobiliários exclusivamente para terceiros.","opts":[["a","I e II"],["b","I e III"],["c","II e III"],["d","Todas as alternativas"]],"ans":"d","exp":"Tema: função da bolsa de valores na abordagem internacional. Analisando:\n\nI. Correto. A bolsa realiza a listagem dos emissores, cujos ativos são negociados no mercado secundário.\n\nII. Correto. A bolsa assegura transparência no pré e pós-negociação, e promove a boa formação de preços.\n\nIII. Errado. A bolsa mantém sistemas de negociação para instituições habilitadas negociarem para clientes e também em nome próprio. O termo \"exclusivamente para terceiros\" torna o item falso.\n\nA chave indica D (todas corretas), mas o item III está incorreto. A alternativa correta seria A (I e II). Vale conferir o material original.","id":"9656"},{"n":267,"banco":"lucas","mod":2,"tit":"II","titn":"Infraestrutura do Mercado & B3","cap":"54","capn":"Questão 54 (cód. 9657)","stem":"A respeito da B3 e do Tesouro Direto: I. A instituição financeira que decidir aderir ao Tesouro Direto deve estar habilitada como Agente de Custódia da B3 II. Se um investidor possui ações e títulos depositados na B3, este pode utilizar a mesma conta de depósito para seus títulos públicos III. A estrutura integrada de liquidação e depositária que a B3 utiliza nos mercados em que opera também é estendida aos títulos do Tesouro Direto Está correto o que se afirma em:","opts":[["a","I e II"],["b","I e III"],["c","II e III"],["d","Todas as alternativas"]],"ans":"d","exp":"Tema: B3 e Tesouro Direto. Analisando:\n\nI. Correto. A instituição que adere ao Tesouro Direto precisa estar habilitada como agente de custódia da B3.\n\nII. Correto. O investidor pode usar a mesma conta de depósito para ações e títulos públicos, porque a estrutura é integrada.\n\nIII. Correto. A estrutura integrada de liquidação e depositária se estende aos títulos do Tesouro Direto.\n\nA alternativa D (todas) é a correta.","id":"9657"},{"n":268,"banco":"lucas","mod":2,"tit":"II","titn":"Infraestrutura do Mercado & B3","cap":"55","capn":"Questão 55 (cód. 9658)","stem":"A respeito da B3, analise as afirmativas abaixo: I. Se trata da única entidade de mercado de bolsa e balcão organizado que possui aprovação da CVM de acordo com a ICVM nº 461 no Brasil II. É responsável por manter sistemas eletrônicos de negociação diferentes para renda variável, renda fixa corporativa, derivativos e commodities III. É responsável por atuar como entidade de registro de ordens e operações realizadas em mercado de balcão para o mercado de derivativos, câmbio e renda fixa corporativa e bancária. Está correto o que se afirma em:","opts":[["a","I e II"],["b","I e III"],["c","II e III"],["d","Todas as alternativas"]],"ans":"b","exp":"Tema: a B3 e sua atuação. Analisando:\n\nI. Correto. A B3 é a única entidade de bolsa e balcão organizado aprovada pela CVM, conforme a ICVM 461.\n\nII. Errado. A B3 mantém um sistema eletrônico de negociação integrado, e não sistemas diferentes para cada segmento, como afirma o item.\n\nIII. Correto. A B3 atua como entidade de registro de ordens e operações de balcão para derivativos, câmbio e renda fixa corporativa e bancária.\n\nA alternativa B (I e III) é a correta.","id":"9658"},{"n":269,"banco":"lucas","mod":2,"tit":"II","titn":"Infraestrutura do Mercado & B3","cap":"56","capn":"Questão 56 (cód. 9659)","stem":"É correspondente à diretriz responsável por estabelecer que pagamentos e transferências de recursos ocorridos na liquidação têm caráter final, do qual não pode ser estornado após processamento","opts":[["a","Finalidade e irrevogabilidade"],["b","Liquidação diferida"],["c","Novação"],["d","Certeza de liquidação"]],"ans":"a","exp":"Tema: finalidade e irrevogabilidade. É a diretriz que determina que os pagamentos e transferências feitos na liquidação têm caráter final, e não podem ser estornados depois de processados. A alternativa A é a correta.\n\nLiquidação diferida (B) é outra forma de liquidação, e novação (C) é o processo de substituição das contrapartes. A certeza de liquidação (D) é a garantia de que a liquidação ocorrerá, mas não é a irrevogabilidade.","id":"9659"},{"n":270,"banco":"lucas","mod":2,"tit":"II","titn":"Infraestrutura do Mercado & B3","cap":"57","capn":"Questão 57 (cód. 9660)","stem":"Plataforma do qual intermediários registram ofertas correspondentes às ordens dos clientes e tais ofertas são casadas, fechando a operação em linha com critérios de melhor preço e cronológico:","opts":[["a","O sistema de negociação direcionado por ordens"],["b","A liquidação bruta em tempo real"],["c","A compensação multilateral"],["d","O acesso direto ao mercado"]],"ans":"a","exp":"Tema: sistema de negociação direcionado por ordens (order driven). É a plataforma em que os intermediários registram ofertas correspondentes às ordens dos clientes, e as ofertas são casadas por preço e ordem cronológica. A alternativa A é a correta.\n\nLiquidação bruta em tempo real (B) é um sistema de liquidação, compensação multilateral (C) é um método de cálculo de saldos e acesso direto (D) é um canal de acesso para o cliente final.","id":"9660"},{"n":271,"banco":"lucas","mod":2,"tit":"II","titn":"Infraestrutura do Mercado & B3","cap":"58","capn":"Questão 58 (cód. 9661)","stem":"A respeito da Compe, analise as afirmativas abaixo: I. São feitas duas sessões de compensação a cada dia útil, do qual apura – se, em cada sessão, um resultado multilateral único para cada participante com âmbito nacional II. Realiza a liquidação das obrigações interbancárias com cheques de valor menor que 250 mil reais III. Seus executantes são o Banco do Brasil e a Caixa Econômica Federal Está correto o que se afirma em:","opts":[["a","I e II"],["b","I e III"],["c","II e III"],["d","Todas as alternativas"]],"ans":"a","exp":"Tema: Compe, a compensação de cheques. Analisando:\n\nI. Correto. A Compe tem duas sessões por dia útil, e em cada uma apura um resultado multilateral único por participante, com âmbito nacional.\n\nII. Duvidoso. A teoria desta edição não traz o limite de R$ 250 mil citado no item, então não consigo confirmar.\n\nIII. Errado. Os executantes da Compe não são o Banco do Brasil e a Caixa Econômica Federal, e a teoria não atribui essa função a eles.\n\nA chave indica A (I e II), mas pelos dados que tenho, o item III é o que parece errado e o II não está confirmado. Vale conferir a regulamentação da Compe antes de usar a questão.","id":"9661"},{"n":272,"banco":"lucas","mod":2,"tit":"II","titn":"Infraestrutura do Mercado & B3","cap":"59","capn":"Questão 59 (cód. 9662)","stem":"É correspondente à situação do qual ativos de guarda centralizada são representados unicamente por um registro eletrônico na central depositária:","opts":[["a","Desmaterialização"],["b","Liquidação diferida"],["c","Compensação multilateral"],["d","Liquidação bruta em tempo real"]],"ans":"a","exp":"Tema: desmaterialização. Quando os ativos existem apenas como registro eletrônico na central depositária, sem certificado físico, ocorre a desmaterialização. A alternativa A é a correta.\n\nLiquidação diferida (B) é a forma de liquidação em momento posterior, compensação multilateral (C) é o cálculo de saldos e liquidação bruta em tempo real (D) é a transferência de cada operação individualmente.","id":"9662"},{"n":273,"banco":"lucas","mod":2,"tit":"II","titn":"Infraestrutura do Mercado & B3","cap":"60","capn":"Questão 60 (cód. 9663)","stem":"A respeito dos mecanismos de inibição de risco e estruturas de salvaguardas das câmaras de compensação e liquidação, analise as afirmativas abaixo: ( ) Câmaras de compensação e liquidação devem obrigatoriamente possuir modelos de gerenciamento de riscos no Brasil ( ) O Banco Central pode ter acesso a visualização das contas de liquidação das câmaras e o fluxo de mensagens referentes às liquidações diárias de operações das instituições financeiras, porém não possui acesso às informações de liquidação de todos os participantes do mercado ( ) Mesmo com inadimplência do maior devedor líquido de um sistema, as câmaras devem constituir uma estrutura de salvaguardas que assegure a continuidade das liquidações Julgue os itens acima em verdadeiro (V) ou falso (F)","opts":[["a","V - V - F"],["b","V - V - V"],["c","V - F – V"],["d","F – F – V"]],"ans":"c","exp":"Tema: mecanismos de inibição de risco nas câmaras. Analisando cada item:\n\n( ) Verdadeiro. As câmaras devem possuir modelos de gerenciamento de risco no Brasil.\n\n( ) Verdadeiro. O Bacen pode visualizar as contas de liquidação das câmaras e o fluxo de mensagens, mas não tem acesso às informações de liquidação de todos os participantes. A mesma afirmação aparece na asserção II da questão 14, e lá a chave a considera verdadeira.\n\n( ) Verdadeiro. Mesmo com a inadimplência do maior devedor líquido, a câmara deve manter salvaguardas que assegurem a continuidade das liquidações.\n\nA sequência correta pela análise é V, V, V, que corresponde à alternativa B. O gabarito indica C (V, F, V), que considera o segundo item falso. Essa é uma divergência de chave, que é a mesma discussão da questão 14. Vale conferir o material original antes de considerar a questão resolvida.","id":"9663"},{"n":274,"banco":"lucas","mod":2,"tit":"II","titn":"Infraestrutura do Mercado & B3","cap":"61","capn":"Questão 61 (cód. 9664)","stem":"A respeito da Câmara Interbancária de Pagamentos (CIP), analise as afirmativas abaixo: I. Realiza o processamento da emissão, resgate, pagamento de juros e custódia dos títulos emitidos pelo Tesouro Nacional e Banco Central II. É responsável pela administração do Sistema de Transferência de Fundos (SITRAF), do qual atua como sistema de liquidação de fundos do SPB III. Atua na compensação e liquidação de TEDs e DOCs","opts":[["a","I e II"],["b","I e III"],["c","II e III"],["d","Todas as alternativas"]],"ans":"c","exp":"Tema: Câmara Interbancária de Pagamentos (CIP). Analisando:\n\nI. Errado. A custódia e a emissão de títulos do Tesouro são feitas pelo Selic, e não pela CIP.\n\nII. Correto. A CIP administra o SITRAF e atua como sistema de liquidação de fundos do SPB.\n\nIII. Correto. A CIP atua na compensação e liquidação de TEDs e DOCs.\n\nA alternativa C (II e III) é a correta. Esta resposta é coerente com a análise dos itens, mas diverge da chave da questão 16 sobre a natureza jurídica da CIP.","id":"9664"},{"n":275,"banco":"lucas","mod":2,"tit":"II","titn":"Infraestrutura do Mercado & B3","cap":"62","capn":"Questão 62 (cód. 9665)","stem":"Definido como um canal que conecta o cliente final ao ambiente de negociação da B3 para comercialização de ativos com autorização por sua corretora:","opts":[["a","O sistema de negociação direcionado por ordens"],["b","O acesso direto ao mercado"],["c","A liquidação bruta em tempo real"],["d","A compensação multilateral"]],"ans":"b","exp":"Tema: acesso direto ao mercado (DMA). É o canal que conecta o cliente final ao ambiente de negociação da B3, com autorização da corretora para comercializar os ativos. A alternativa B é a correta.\n\nO sistema direcionado por ordens (A) é a plataforma de casamento de ofertas, liquidação bruta (C) é o sistema de transferência e compensação multilateral (D) é o cálculo de saldos. Nenhuma delas é o canal de acesso do cliente.","id":"9665"},{"n":276,"banco":"lucas","mod":2,"tit":"II","titn":"Infraestrutura do Mercado & B3","cap":"63","capn":"Questão 63 (cód. 9666)","stem":"A respeito das possibilidades do Sistema de Transferência de Reserva (STR), analise as afirmativas a seguir: I. Concessão de crédito em tempo real (intradia) através de operações compromissadas abrangendo títulos públicos federais registrados e liquidados no Selic II. Até que haja suficiência de fundos na conta da instituição remetente, atua na manutenção de ordens de pagamento em pendência III. Realiza o agendamento de ordens de pagamento para até trinta dias da data de emissão da ordem Está correto o que se afirma em:","opts":[["a","I e II"],["b","I e III"],["c","II e III"],["d","Todas as alternativas"]],"ans":"a","exp":"Tema: STR, Sistema de Transferência de Reservas. Analisando:\n\nI. Correto. O STR permite concessão de crédito intradia por operações compromissadas com títulos públicos federais registrados e liquidados no Selic.\n\nII. Correto. Enquanto a instituição remetente não tem fundos suficientes, as ordens de pagamento ficam pendentes.\n\nIII. Errado. O STR não agenda ordens por até trinta dias, o que está fora do seu funcionamento.\n\nA alternativa A (I e II) é a correta.","id":"9666"},{"n":277,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"1","capn":"Questão 1 (cód. 199543168)","stem":"O Certificado de Operações Estruturadas - COE é um instrumento moderno de investimentos que combina aplicações de renda fixa e variável. Para uma pessoa física que realiza aplicações em COE, como será a tributação do Imposto de Renda:","opts":[["a","Alíquota fixa de 15%"],["b","Tabela regressiva de 22,5% até 15%, conforme o prazo"],["c","Alíquota fixa de 20%"],["d","Alíquota regressiva de 35% até 10%, conforme o prazo"]],"ans":"b","exp":"Tema: tributação de COE para pessoa física. O COE é um título de renda fixa com componente de renda variável, e o IR segue a tabela regressiva de renda fixa: 22,5% para prazos de até 180 dias, caindo até 15% em prazos acima de 720 dias. A alternativa B é a correta. As alíquotas fixas de 15% (A) e 20% (C) e a tabela de 35% a 10% (D) não correspondem à regra do COE.","id":"199543168"},{"n":278,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"2","capn":"Questão 2 (cód. 199543169)","stem":"Seu cliente teve perdas em operações do tipo day trade com ações. Nesse caso, a compensação desse prejuízo para calcular o imposto de renda pode ser feito?","opts":[["a","Sim, desde que com operações somente realizadas com day trade"],["b","Sim, podendo ser compensada com operações day trade e também operações não day trade"],["c","Não podem ser compensadas"],["d","Sim, podem ser compensadas com qualquer ganho no mercado financeiro"]],"ans":"a","exp":"Tema: compensação de prejuízo em day trade. O prejuízo de day trade só pode ser compensado com ganhos de day trade, e o prejuízo de operações comuns só com ganhos comuns. A alternativa A é a correta. As alternativas B e D permitem compensação cruzada, o que não é permitido, e a C nega qualquer compensação, o que também está errado.","id":"199543169"},{"n":279,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"3","capn":"Questão 3 (cód. 199543170)","stem":"Sobre os BDR’s, assinale a alternativa correta:","opts":[["a","É um recibo de ação brasileiro, lastreado em empresa do Brasil e negociado nos Estados Unidos"],["b","É uma ação brasileira de uma companhia que está fora do Brasil"],["c","É um título negociado no Brasil, cotado em dólares e lastreado em ação de uma empresa não brasileira"],["d","É um título negociado no Brasil, cotado em reais e lastreado em ação de uma empresa não brasileira"]],"ans":"d","exp":"Tema: BDR. É um título negociado no Brasil, cotado em reais, que representa ações de empresas estrangeiras depositadas no país. A alternativa D é a correta. A alternativa A inverte o local de negociação e o lastro, e a B fala em ação brasileira, o que não é o BDR. A alternativa C fala em cotação em dólar, o que é característica de outros recibos, como o ADR.","id":"199543170"},{"n":280,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"4","capn":"Questão 4 (cód. 199543171)","stem":"Segmento de listagem de Governança Corporativa que exige emissão de somente ações ordinárias:","opts":[["a","Nível 2"],["b","Novo Mercado"],["c","Nível 1"],["d","Tradicional"]],"ans":"b","exp":"Tema: segmentos de governança da B3. O Novo Mercado é o segmento que exige emissão apenas de ações ordinárias (ON). A alternativa B é a correta. Os níveis 1 e 2 permitem ações preferenciais, e o segmento tradicional não exige práticas de governança.","id":"199543171"},{"n":281,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"5","capn":"Questão 5 (cód. 199543172)","stem":"Uma diferença entre o mercado a termo e o mercado futuro é que:","opts":[["a","No mercado a termo há ajuste diário"],["b","No mercado futuro existe ajuste diário"],["c","No mercado a termo os contratos são padronizados"],["d","No mercado futuro existe a opção de exercer o direito"]],"ans":"b","exp":"Tema: diferença entre mercado futuro e a termo. O mercado futuro tem ajuste diário, que é o acerto diário das posições pela variação do preço. O mercado a termo não tem ajuste diário, e o pagamento é feito apenas no vencimento. A alternativa B é a correta. A alternativa A inverte a regra, e a alternativa C descreve o futuro, que é padronizado. A alternativa D atribui ao futuro uma opção de exercício, o que é característica de opções.","id":"199543172"},{"n":282,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"6","capn":"Questão 6 (cód. 199543173)","stem":"Qual a perda máxima de um titular de PUT?","opts":[["a","Ilimitada"],["b","O preço de exercício"],["c","O valor do prêmio"],["d","O beta da ação"]],"ans":"c","exp":"Tema: perda máxima do titular de uma put. Quem compra a put paga o prêmio, e no pior caso perde apenas esse valor, se a opção não for exercida. A alternativa C é a correta. A perda não é ilimitada (A), não é o preço de exercício (B), e o beta (D) é medida de risco de ação, e não limite de perda de opção.","id":"199543173"},{"n":283,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"7","capn":"Questão 7 (cód. 199543174)","stem":"Seu cliente possui uma dívida em dólar para pagar em 1 ano. Para se proteger da oscilação da moeda estrangeira, você o aconselha a:","opts":[["a","Comprar uma PUT de dólar"],["b","Vender uma CALL de dólar"],["c","Comprar dólar a termo"],["d","Vender dólar futuro"]],"ans":"c","exp":"Tema: hedge de dívida em dólar. O cliente deve comprar dólar a termo, travando hoje o preço de compra da moeda para pagar a dívida daqui a um ano. A alternativa C é a correta. Comprar put de dólar (A) protege contra queda, o que não é o interesse do devedor, e vender call (B) ou vender dólar futuro (D) expõe o cliente a alta da moeda.","id":"199543174"},{"n":284,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"8","capn":"Questão 8 (cód. 199543175)","stem":"É um benefício dos títulos conhecidos como TIPS:","opts":[["a","Não possuir risco de reinvestimento"],["b","Ser negociado com deságio sobre o valor de face"],["c","Ser atualizado pela inflação"],["d","Ser considerado ativo livre de risco brasileiro"]],"ans":"c","exp":"Tema: TIPS. O título americano TIPS tem o principal corrigido pela inflação, por isso é a alternativa C. Os demais benefícios não são característicos dos TIPS: o risco de reinvestimento (A) existe no cupom, o deságio (B) é uma forma de negociação, e a condição de ativo livre de risco brasileiro (D) não se aplica a um título americano.","id":"199543175"},{"n":285,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"9","capn":"Questão 9 (cód. 199543121)","stem":"O gráfico abaixo representa qual posição no mercado de ações:","opts":[["a","Titular de uma Call"],["b","Lançador de uma Call"],["c","Titular de uma Put"],["d","Lançador de uma Put"]],"ans":"b","exp":"Tema: posição no gráfico de opção (lançador de call). O gráfico depende de um desenho que não aparece no texto extraído. A chave indica B, lançador de uma call. Vale conferir o gráfico original, porque a identificação depende da inclinação e do ponto de corte da linha.","id":"199543121"},{"n":286,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"10","capn":"Questão 10 (cód. 1995420213001)","stem":"O mercado de derivativos é onde são negociados contratos que se referem a um ativo principal. Em opções, um investidor irá exercer um direito de compra (call) quando:","opts":[["a","O valor de mercado da ação estiver superior ao preço de exercício"],["b","O valor de mercado da ação estiver superior ao preço de exercício mais o valor do prêmio"],["c","O valor de mercado da ação estiver inferior ao preço de exercício"],["d","O valor de mercado da ação estiver inferior ao preço de exercício mais o valor do prêmio"]],"ans":"c","exp":"Tema: exercício de uma call. O titular de uma call exerce o direito de compra quando o preço de mercado do ativo está acima do preço de exercício. Se o mercado estiver abaixo, a opção não é exercida. A alternativa A é a correta pela regra.\n\nA chave indica C (mercado inferior ao preço de exercício), que descreve justamente o caso em que o titular não exerce. Essa é uma divergência de chave. Vale conferir o material original.","id":"1995420213001"},{"n":287,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"11","capn":"Questão 11 (cód. 1995420213004)","stem":"O Fundo Garantidor de Crédito – FGC é uma instituição privada e tem como objetivo de contribuir para a confiança das pessoas no Sistema Financeiro Nacional. Nesse sentido, quando um banco sofre liquidação e alguns clientes possuem conta corrente conjunta conforme abaixo, qual será o valor que cada um dos clientes irá receber: Conta Titulares Valor em Conta 1 Bernardo e Júlio R$ 100.000 2 Bernardo e Luís R$ 250.000 3 Bernardo e Luís e João R$ 750.000","opts":[["a","Bernardo: R$ 258 mil; Júlio: R$ 50 mil; Luís: R$ 208 mil; João: R$ 83 mil"],["b","Bernardo: R$ 250 mil; Júlio: R$ 100 mil; Luís: R$ 208 mil; João: R$ 83 mil"],["c","Bernardo: R$ 250 mil; Júlio: R$ 50 mil; Luís: R$ 208 mil; João: R$ 83 mil"],["d","Bernardo: R$ 433 mil; Júlio: R$ 50 mil; Luís: R$ 208 mil; João: R$ 83 mil"]],"ans":"c","exp":"Tema: FGC e contas conjuntas. O FGC cobre até R$ 250 mil por titular, por instituição, e na conta conjunta o valor é dividido igualmente entre os titulares. Pela divisão das três contas, Bernardo teria R$ 425 mil, Luís R$ 375 mil e Júlio R$ 50 mil, e João R$ 250 mil. Como cada titular só pode receber até o limite, Bernardo e Luís são limitados a R$ 250 mil, e o excedente é redistribuído conforme as regras do FGC.\n\nA alternativa C é a chave, e a distribuição final depende dessa regra de redistribuição, que não está detalhada no texto desta edição. Recomendo conferir a regra do FGC antes de usar o valor.","id":"1995420213004"},{"n":288,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"12","capn":"Questão 12 (cód. 1995420213016)","stem":"Um jovem investidor realizou uma aplicação de R$ 50 mil em um COE atrelado ao SP 500 com 3 opções de cenário conforme abaixo: Cenário 1 - Queda do SP 500: Valor Nominal Protegido (VNP) Cenário 2 – Variação do SP 500 Entre 0 e 10%: 100% Variação SP 500 Cenário 3 – Variação do SP 500 Acima de 10% a Qualquer Momento: Alta limitada em 10% Prazo de Aplicação: 2,2 anos P Abertura: 4200 Pontos P Fechamento: 4700 Pontos Qual será o resgate líquido:","opts":[["a","R$ 50.000"],["b","R$ 55.000"],["c","R$ 54.250"],["d","R$ 54.500"]],"ans":"d","exp":"Tema: COE atrelado ao S&P 500 com cenários. A variação do índice é de 4.200 para 4.700 pontos, ou seja, 11,9%. No cenário 3, a alta fica limitada a 10%, então o ganho sobre os R$ 50.000 é de R$ 5.000, e o resgate bruto seria de R$ 55.000. A alternativa B é o cálculo direto. A chave indica D (R$ 54.500), o que implicaria um desconto de R$ 500 que o enunciado não justifica. Vale conferir a redação original, porque a diferença não está explicada no texto.","id":"1995420213016"},{"n":289,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"13","capn":"Questão 13 (cód. 1995420213020)","stem":"Um determinado investidor faz 2 aplicações no Mercado de Capitais, ambas pelo prazo de 152 dias úteis (220 dias corridos) nos seguintes produtos: 1 – NDF no valor de 55.000 2 – Contrato de Swap (Atrelado a renda variável) no valor de 55.000 Qual será a alíquota do Imposto de Renda de ambos, respectivamente:","opts":[["a","15% e 15%"],["b","22,50% e 15%"],["c","20% e 20%"],["d","15% e 20%"]],"ans":"a","exp":"Tema: IR em NDF e swap. Operações de derivativos de renda fixa e variável com prazo de 220 dias corridos seguem a tabela regressiva, com alíquota de 15% para prazo acima de 180 dias. A alternativa A (15% e 15%) é a correta. Alíquotas de 22,5% (B) e 20% (C e D) correspondem a prazos menores que o aplicável.","id":"1995420213020"},{"n":290,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"14","capn":"Questão 14 (cód. 1995420213025)","stem":"Sr. Estagiário é residente no Brasil, porém, como tem conhecimento sobre investimentos, gosta de realizar operações nos Estados Unidos. Em uma delas, comprou 5.000 ações de uma empresa americana, nos EUA por U$ 20,00 cada. Na data da compra das ações a cotação do Dólar era de R$ 4,00. Após 8 meses ele decide então vender essas ações e as mesmas estão cotadas por U$ 15,00, e o dólar estava cotado a R$ 6,00. Esse valor não foi repatriado para o Brasil. Pergunta-se então qual será o I.R devido por Sr. Estagiário aqui no Brasil:","opts":[["a","15%"],["b","27,50%"],["c","Isento, pois, não trouxe o valor para o Brasil"],["d","Isento, pois, não teve lucro na operação"]],"ans":"d","exp":"Tema: tributação de operações no exterior feitas por residente no Brasil. O investidor vendeu as ações com lucro, em reais: a compra custou 5.000 × US$ 20 × R$ 4 = R$ 400.000, e a venda rendeu 5.000 × US$ 15 × R$ 6 = R$ 450.000. Há ganho de R$ 50.000, que é tributável no Brasil, mesmo sem repatriação.\n\nA alternativa D (isento por não ter lucro) contraria a conta, porque houve lucro em reais. A chave indica D, o que é uma divergência a conferir com a regra específica de ganhos no exterior.","id":"1995420213025"},{"n":291,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"15","capn":"Questão 15 (cód. 1995420213026)","stem":"Analise as afirmações abaixo sobre opções: I. Em uma opção de venda, o lançador tem sempre a obrigação de comprar II. Em uma opção de venda, o titular tem sempre o direito de vender III. Em uma opção de compra, o titular tem sempre o direito de comprar Está correto o que se afirma em:","opts":[["a","I e II"],["b","I e III"],["c","II e III"],["d","I, II e III"]],"ans":"c","exp":"Tema: opções de compra e de venda. Analisando:\n\nI. Correto. Na put, o lançador se obriga a comprar o ativo se o titular exercer.\n\nII. Correto. Na put, o titular tem o direito de vender o ativo ao preço de exercício.\n\nIII. Correto. Na call, o titular tem o direito de comprar.\n\nO item I contém a palavra \"sempre\", que o torna questionável, porque a obrigação só existe se o titular exercer. A chave indica C (II e III), que exclui o I por esse motivo. Vale conferir o enunciado original.","id":"1995420213026"},{"n":292,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"16","capn":"Questão 16 (cód. 1995420213031)","stem":"Em relação à diferença entre Mercado Futuro e Mercado a Termo no Brasil, analise as afirmações abaixo: I. Mercado Futuro não possui ajuste diário II. Mercado a Termo não possui ajuste diário III. Mercado Futuro não possui risco de contraparte IV. Mercado Futuro possui contratos padronizados Está correto o que se afirma em:","opts":[["a","I e III"],["b","III e IV"],["c","II e III"],["d","II, III e IV"]],"ans":"d","exp":"Tema: diferenças entre mercado futuro e a termo no Brasil. Analisando:\n\nI. Errado. O mercado futuro tem ajuste diário.\n\nII. Correto. O mercado a termo não tem ajuste diário.\n\nIII. Errado. O mercado futuro tem garantia da câmara da B3, que reduz o risco de contraparte, mas não o elimina totalmente. Afirmar que não há risco de contraparte está errado.\n\nIV. Correto. O futuro tem contratos padronizados.\n\nA combinação que corresponde à análise é II e IV, que não aparece entre as alternativas. A chave indica D (II, III e IV), que inclui o item III, errado. Esta é uma divergência de chave. Vale conferir o material original.","id":"1995420213031"},{"n":293,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"17","capn":"Questão 17 (cód. 1995420213038)","stem":"Sobre os IMA’s, assinale a alternativa incorreta: I. IMA-S = Selic II. IMA-B = IPCA III. IDkA = IGP-M IV. IRF-M = Prefixado","opts":[["a","I"],["b","II"],["c","III"],["d","IV"]],"ans":"c","exp":"Tema: índices IMA. O IMA-S acompanha títulos pós-fixados atrelados à Selic (I, correto). O IMA-B acompanha títulos atrelados ao IPCA (II, correto). O IRF-M acompanha prefixados (IV, correto). O IDkA é indexado ao IPCA, e não ao IGP-M, o que torna o item III incorreto. A alternativa C é a incorreta, e é a resposta da questão.","id":"1995420213038"},{"n":294,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"18","capn":"Questão 18 (cód. 1995420213040)","stem":"O gráfico abaixo descreve qual tipo de operações no mercado de derivativos financeiros","opts":[["a","Short Strangle"],["b","Butterfly"],["c","Long Strangle"],["d","Financiamento"]],"ans":"c","exp":"Tema: operação com derivativos representada no gráfico (Long Strangle). O gráfico não aparece no texto extraído, então a identificação depende da imagem original. A chave indica C (Long Strangle), que é a compra de uma call e de uma put com preços de exercício diferentes e fora do dinheiro. Vale conferir o gráfico original para confirmar.","id":"1995420213040"},{"n":295,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"19","capn":"Questão 19 (cód. 1995420213041)","stem":"É o responsável pelo recolhimento do IRRF nos investimentos realizados através do Tesouro Direto:","opts":[["a","Tesouro Nacional"],["b","Próprio Investidor"],["c","Instituição Emissora"],["d","Agente de Custódia"]],"ans":"d","exp":"Tema: responsável pela retenção do IR no Tesouro Direto. Pela chave, o responsável pelo recolhimento é o agente de custódia, que retém o imposto na fonte. A alternativa D é a correta. O Tesouro Nacional (A) emite os títulos, o próprio investidor (B) só recolhe quando a retenção não ocorre, e a instituição emissora (C) não é a responsável pela retenção no Tesouro Direto.","id":"1995420213041"},{"n":296,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"20","capn":"Questão 20 (cód. 1995420213044)","stem":"Sobre o Índice de Governança Corporativa – IGC, analise as afirmações abaixo: I. São ações com práticas de Governança Corporativa diferenciadas II. Considera empresas do nível 1, 2 e Novo Mercado III. É um índice que considera somente ativos negociados em Mercado de Balcão Está correto o que se afirma em:","opts":[["a","I e II"],["b","I e III"],["c","II e III"],["d","I, II e III"]],"ans":"a","exp":"Tema: Índice de Governança Corporativa (IGC). Analisando:\n\nI. Correto. O IGC reúne ações de empresas com práticas diferenciadas de governança.\n\nII. Correto. O índice considera empresas dos níveis 1 e 2 e do Novo Mercado.\n\nIII. Errado. O IGC considera ativos negociados na bolsa, e não apenas no mercado de balcão.\n\nA alternativa A (I e II) é a correta.","id":"1995420213044"},{"n":297,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"21","capn":"Questão 21 (cód. 1995420213045)","stem":"Um determinado investidor comprou um título hoje, com preço de mercado de 5% de taxa de juros pelo prazo de 2 anos. Para esse mesmo período, o mercado estava estimando uma projeção de juros de 6%. Nesse caso, o investidor comprará esse título com:","opts":[["a","Ágio"],["b","Deságio"],["c","Ao Par"],["d","Não é possível negociar um título com taxa diferente da projeção do mercado"]],"ans":"b","exp":"Tema: ágio e deságio. O título é comprado com taxa de 5%, enquanto o mercado projeta 6%. Quando a taxa do título é menor que a taxa de mercado, ele é negociado com deságio, e o preço fica abaixo do valor de face para compensar. A alternativa B é a correta. O ágio (A) ocorre quando a taxa do título é maior que a do mercado, e o título ao par (C) quando as taxas são iguais.","id":"1995420213045"},{"n":298,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"22","capn":"Questão 22 (cód. 1995420213046)","stem":"Em uma distribuição de COE para investidores não profissionais, a entrega do Documento de Informações Essenciais (DIE) e a assinatura do termo de adesão, são, respectivamente:","opts":[["a","Obrigatório e Obrigatória"],["b","Obrigatório e Opcional"],["c","Opcional e Obrigatório"],["d","Opcional e Opcional"]],"ans":"a","exp":"Tema: distribuição de COE para investidores não profissionais. O Documento de Informações Essenciais (DIE) é obrigatório, e a assinatura do termo de adesão também é obrigatória. A alternativa A é a correta, conforme a regra de distribuição de COE. As demais tornam uma das exigências opcional, o que não é a regra.","id":"1995420213046"},{"n":299,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"23","capn":"Questão 23 (cód. 1995420213047)","stem":"Sr. Alberto é um investidor de 63 anos de idade e possui perfil arrojado. O mesmo possui uma esposa e 3 filhos. Em Março de 2019 Sr. João decide então comprar um lote de 1000 ações com o preço de R$ 20,00 cada ação. Decide então vender conforme descrito abaixo: 01/05/2020 – 400 ações a R$ 25,00 03/06/2020 – 400 ações a R$ 28,00 05/07/2020 – 200 ações a R$ 30,00 Desconsiderando taxas e despesas, qual foi o total de imposto retido na fonte das 3 operações:","opts":[["a","R$ 0,00"],["b","R$ 1,36"],["c","R$ 20,00"],["d","R$ 4,74"]],"ans":"a","exp":"Tema: IR retido na fonte em vendas de ações e isenção mensal. Na venda de ações, a regra de isenção é de até R$ 20.000 de vendas no mês. Em maio, as vendas foram de 400 × R$ 25 = R$ 10.000. Em junho, 400 × R$ 28 = R$ 11.200. Em julho, 200 × R$ 30 = R$ 6.000. Em nenhum mês as vendas ultrapassaram R$ 20.000, então não há IR retido na fonte, e a alternativa A (R$ 0,00) é a correta.","id":"1995420213047"},{"n":300,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"24","capn":"Questão 24 (cód. 1995420213048)","stem":"Um dos conceitos fundamentais do mercado de opções é o Modelo de Black Scholes. Sobre esse modelo, analise as afirmações abaixo: I. A precificação pode ser feita para opções americanas ou europeias II. Existe correlação entre o ativo principal e a opção III. A taxa livre de risco é constante e conhecida Está (ão) correta (s):","opts":[["a","I e III"],["b","II e III"],["c","Apenas I"],["d","I, II e III"]],"ans":"b","exp":"Tema: modelo de Black-Scholes. Analisando:\n\nI. Errado. O modelo foi desenvolvido para opções europeias, e não serve diretamente para opções americanas, que podem ser exercidas antes do vencimento.\n\nII. Correto. Há correlação entre o preço do ativo principal e o valor da opção.\n\nIII. Correto. O modelo supõe uma taxa livre de risco constante e conhecida.\n\nA alternativa B (II e III) é a correta.","id":"1995420213048"},{"n":301,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"25","capn":"Questão 25 (cód. 1995420213050)","stem":"O Mercado de Capitais possui muitas opções de ativos para que o investidor monte a sua carteira. Ao optar por comprar ações, o comprador pode optar pela análise técnica (grafista), que se baseia em gráficos ou na análise fundamentalista. Na análise gráfica, descreva o que representa a trava de alta e de baixa, respectivamente:","opts":[["a","Suporte e Resistência"],["b","Índice de Força Relativa e Suporte"],["c","Índice de Força Relativa e Resistência"],["d","Resistência e Suporte"]],"ans":"d","exp":"Tema: análise gráfica, travas de alta e de baixa. Na análise técnica, o suporte é o nível de preço em que a demanda tende a segurar a queda, e a resistência é o nível em que a oferta tende a limitar a alta. A alternativa D é a correta. As alternativas A, B e C misturam indicadores de força relativa e conceitos que não definem as travas.","id":"1995420213050"},{"n":302,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"26","capn":"Questão 26 (cód. 1995420213062)","stem":"Um determinado investidor comprou ações na Bolsa de Valores pelo valor de R$ 100.000. Após alguns dias, vende essas ações pelo valor de R$ 130.000. Qual será o I.R na fonte e o imposto de renda total dessa operação (desconsidere custos de transações):","opts":[["a","R$ 1,50 e R$ 4.500"],["b","R$ 6,50 e R$ 4.500"],["c","R$ 300 e R$ 6.000"],["d","R$ 6,50 e R$ 4.506,50"]],"ans":"b","exp":"Tema: IR de operação de compra e venda de ações com lucro. O ganho é de R$ 30.000 (R$ 130.000 − R$ 100.000). O IRRF na fonte é de 0,005% sobre o valor de venda: 0,00005 × 130.000 = R$ 6,50. O IR total, de 15% sobre o ganho, é de 0,15 × 30.000 = R$ 4.500. A alternativa B é a correta, pois o IRRF retido de R$ 6,50 faz parte do imposto total de R$ 4.500.","id":"1995420213062"},{"n":303,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"27","capn":"Questão 27 (cód. 1995420213063)","stem":"São títulos negociados no mercado norte-americano que implicam risco de reinvestimento no recebimento de cupons","opts":[["a","T-Notes e T-Bills"],["b","T-Bills e T-Bonds"],["c","T-Bills e TIPS"],["d","T-Notes e T-Bonds"]],"ans":"d","exp":"Tema: títulos americanos com risco de reinvestimento. Os T-Notes e os T-Bonds pagam cupons periódicos, e por isso expõem o investidor ao risco de reinvestimento desses cupons. Os T-Bills são zero cupom e não têm esse risco. A alternativa D é a correta.","id":"1995420213063"},{"n":304,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"28","capn":"Questão 28 (cód. 1995420213065)","stem":"O gráfico abaixo representa qual posição no mercado de ações:","opts":[["a","Titular de uma Call"],["b","Lançador de uma Call"],["c","Titular de uma Put"],["d","Lançador de uma Put"]],"ans":"b","exp":"Tema: posição no gráfico de opção (lançador de call). O gráfico não aparece no texto extraído. A chave indica B, lançador de uma call, que é a mesma resposta da questão 9. Vale conferir o gráfico original, porque a identificação depende da inclinação e do ponto de corte da linha.","id":"1995420213065"},{"n":305,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"29","capn":"Questão 29 (cód. 1995420213074)","stem":"Nas operações a termo no mercado de ações, uma operação de financiamento é caracterizada como aquela em que o investidor","opts":[["a","obtém recursos de um empréstimo e compra ações, simultaneamente, para entrega em uma data futura."],["b","compra à vista um lote de ações e o vende, simultaneamente, para entrega em uma data futura."],["c","paga um prêmio ao titular das ações para obter o direito de comprá-las em uma data futura."],["d","vende à vista um lote de ações e o recompra para entrega em uma data futura."]],"ans":"d","exp":"Tema: operação de financiamento no mercado a termo de ações. O investidor vende as ações à vista e se compromete a recomprá-las em data futura. Ele recebe dinheiro hoje e paga depois, o que caracteriza o financiamento. A alternativa D é a correta. A alternativa A descreve um empréstimo, e não a operação a termo. As alternativas B e C descrevem compra à vista e pagamento de prêmio, que não são financiamento.","id":"1995420213074"},{"n":306,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"30","capn":"Questão 30 (cód. 1995420213075)","stem":"Um mercado de capitais é considerado eficiente quando os","opts":[["a","Padrões de preços históricos dos ativos sinalizam tendências para o comportamento futuro."],["b","Ativos negociados são considerados investimentos com valor presente líquido positivo."],["c","Retornos esperados dos ativos são iguais aos retornos efetivamente realizados."],["d","Preços atuais dos ativos negociados refletem todas as informações disponíveis."]],"ans":"d","exp":"Tema: mercado eficiente. Um mercado é eficiente quando os preços atuais refletem todas as informações disponíveis. A alternativa D é a correta. Padrões históricos sinalizando tendências (A) é a crença da análise técnica, que a hipótese de eficiência rejeita. O VPL positivo (B) e a igualdade entre retorno esperado e realizado (C) não definem a eficiência.","id":"1995420213075"},{"n":307,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"31","capn":"Questão 31 (cód. 1995420213053)","stem":"Seu cliente Pessoa Física possui ações de empresas aqui no Brasil e também no exterior. Em relação à tributação (Imposto de Renda) dos dividendos desses ativos, no exterior e no Brasil, respectivamente:","opts":[["a","Isento e Até 22,5%"],["b","Isento e Isento"],["c","Até 27,5% e Isento"],["d","15% e 15%"]],"ans":"c","exp":"Tema: IR sobre dividendos de ações brasileiras e estrangeiras. Os dividendos de empresas brasileiras para pessoa física são isentos. Os dividendos recebidos do exterior podem ter tributação de até 27,5%. A alternativa C é a correta, conforme a chave. A alternativa A (isento e até 22,5%) inverte a alíquota de exterior, e as demais não correspondem ao tratamento dos dividendos.","id":"1995420213053"},{"n":308,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"32","capn":"Questão 32 (cód. 1995420213054)","stem":"Seu cliente possui um fundo indexado ao IMA-S. Ele o questiona sobre a variação em que tipo de ativo irá afetar mais esse fundo:","opts":[["a","Ibovespa"],["b","IGP-M"],["c","CDI"],["d","Selic"]],"ans":"d","exp":"Tema: fator de risco de fundo indexado ao IMA-S. O IMA-S acompanha títulos pós-fixados atrelados à Selic, então o fator que mais afeta o fundo é a própria Selic. A alternativa D é a correta. Ibovespa (A) é de renda variável, IGP-M (B) e CDI (C) não são o índice de referência do IMA-S.","id":"1995420213054"},{"n":309,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"33","capn":"Questão 33 (cód. 1995420213057)","stem":"Seu cliente investidor gosta muito de colocar recursos em títulos públicos federais. Ao negociar uma LFT no Tesouro Direto, o mesmo comprou esse título com deságio. Na prática, isso quer dizer que:","opts":[["a","Ele terá um rendimento inferior à Taxa Selic"],["b","Ele terá um rendimento igual à Taxa Selic"],["c","Ele terá um rendimento atrelado ao CDI"],["d","Ele terá um rendimento superior à Taxa Selic"]],"ans":"d","exp":"Tema: LFT comprada com deságio. A LFT é um título pós-fixado atrelado à Selic. Quando é comprada com deságio, o preço pago fica abaixo do valor de face, e o investidor recebe a Selic mais o ganho desse deságio até o vencimento. Por isso, o rendimento fica acima da Selic. A alternativa D é a correta.","id":"1995420213057"},{"n":310,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"34","capn":"Questão 34 (cód. 1995420213060)","stem":"Uma ação está cotada no mercado a R$ 18,00. Um investidor estima um lucro por ação igual a R$ 2,00 no atual exercício. Nesse caso, P/L estimado indica que","opts":[["a","O lucro deverá se elevar, anualmente, em 11,00%."],["b","A taxa de retorno da ação será de 1,80% a.a."],["c","O capital investido será recuperado em nove anos."],["d","O retorno esperado da ação será de 11,11% para um período de nove anos."]],"ans":"c","exp":"Tema: índice P/L. O P/L é o preço da ação dividido pelo lucro por ação: R$ 18,00 / R$ 2,00 = 9. Isso significa que o investidor recupera o capital em nove anos, se o lucro se mantiver. A alternativa C é a correta. As demais alternativas inventam taxas de crescimento ou de retorno que não decorrem do cálculo.","id":"1995420213060"},{"n":311,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"35","capn":"Questão 35 (cód. 1995420213061)","stem":"Um determinado investidor o procura muito preocupado com a alta da inflação. Ele deseja então montar uma carteira que o proteja dessa oscilação. Você deveria indicar produtos atrelados à:","opts":[["a","Índice Bovespa"],["b","Taxa Referencial - TR"],["c","IPCA"],["d","Cotação do Dólar"]],"ans":"c","exp":"Tema: proteção contra inflação. O IPCA é o índice oficial de inflação, e os produtos atrelados a ele protegem o investidor da alta de preços. A alternativa C é a correta. Ibovespa (A) e dólar (D) são ativos de renda variável e câmbio, e a TR (B) é um índice que não acompanha a inflação de forma direta.","id":"1995420213061"},{"n":312,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"36","capn":"Questão 36 (cód. 1995420213081)","stem":"Um investimento em empresas do tipo “Small Caps”, possui, principalmente, qual tipo de risco:","opts":[["a","Crédito e Mercado"],["b","Apenas de Mercado"],["c","Liquidez e Mercado"],["d","Crédito e Liquidez"]],"ans":"c","exp":"Tema: riscos de investimentos em small caps. As small caps têm pouca negociação, o que gera risco de liquidez, e oscilam conforme o mercado, o que gera risco de mercado. A alternativa C é a correta.","id":"1995420213081"},{"n":313,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"37","capn":"Questão 37 (cód. 1995420213082)","stem":"É função do Market Maker:","opts":[["a","Aumentar liquidez dos ativos e reduzir movimentos artificiais"],["b","Garantir o risco de crédito dos ativos para dar mais segurança ao mercado"],["c","Realizar a venda de ativos exclusivamente para fundos de investimentos"],["d","Atuar como contraparte para operações de altíssimo risco"]],"ans":"a","exp":"Tema: função do formador de mercado (market maker). Ele se compromete a manter ofertas de compra e venda de um ativo, aumentando a liquidez e reduzindo movimentos artificiais. A alternativa A é a correta. As alternativas B e D atribuem ao market maker funções de garantia de crédito ou contraparte de risco elevado, o que não corresponde ao papel. A alternativa C limita a venda a fundos, o que não é a regra.","id":"1995420213082"},{"n":314,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"38","capn":"Questão 38 (cód. 1995420213085)","stem":"Germano quer ter uma renda mensal vitalícia de R$ 10 mil quando se aposentar. Receberá do INSS uma renda de R$ 2 mil. Utilizando os dados abaixo: -Taxa de Juros: 1% -Alíquota de I.R: 15% -Desconsiderar inflação Qual o montante que Germano precisa acumular para garantir essa renda, aproximadamente:","opts":[["a","R$ 941 mil"],["b","R$ 1.150 mm"],["c","R$ 1.250 mm"],["d","R$ 830 mil"]],"ans":"a","exp":"Tema: valor presente de uma renda vitalícia. Germano precisa de R$ 10.000 de renda mensal, e o INSS paga R$ 2.000, então precisa complementar R$ 8.000 líquidos. Com alíquota de 15% sobre o rendimento, o rendimento líquido efetivo é de 1% × 0,85 = 0,85% ao mês. O capital necessário é de 8.000 / 0,0085 = R$ 941.176, o que corresponde à alternativa A.","id":"1995420213085"},{"n":315,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"39","capn":"Questão 39 (cód. 1995420213087)","stem":"Um gestor de um fundo de ações comprou 2.000 “Call’s” de uma ação conforme abaixo: - Prêmio: R$ 1,30 - Preço Exercício: R$ 20,00 - Preço de Mercado na Data do Exercício: R$ 25 - A Call estava <i>At The Money </i>no seu lançamento Qual o resultado líquido dessa operação (desconsiderar tributos e demais custos)","opts":[["a","R$ 2.300"],["b","R$ 7.400"],["c","R$ 9.200"],["d","R$ 5.700"]],"ans":"b","exp":"Tema: resultado de uma call comprada. O gestor comprou 2.000 calls com prêmio de R$ 1,30 e preço de exercício de R$ 20. No vencimento, o preço do ativo é R$ 25, então o ganho bruto é de (25 − 20) × 2.000 = R$ 10.000. Descontado o prêmio de 2.000 × R$ 1,30 = R$ 2.600, o resultado líquido é de R$ 7.400. A alternativa B é a correta.","id":"1995420213087"},{"n":316,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"40","capn":"Questão 40 (cód. 1995420213088)","stem":"Analise as afirmações abaixo: I. Debêntures Incentivadas contam com garantia do FGC II. Debêntures Incentivadas possuem isenção fiscal para pessoa física III. LCI possui lastro em financiamento imobiliário, garantido por alienação fiduciária ou hipoteca Está correto o que se afirma em:","opts":[["a","I e III"],["b","Nenhum"],["c","II e III"],["d","I, II e III"]],"ans":"c","exp":"Tema: debêntures incentivadas, FGC e LCI. Analisando:\n\nI. Errado. Debêntures não contam com garantia do FGC, que cobre apenas instituições financeiras.\n\nII. Correto. As debêntures incentivadas são isentas de IR para pessoa física.\n\nIII. Correto. A LCI tem lastro em financiamentos imobiliários, com garantia de alienação fiduciária ou hipoteca.\n\nA alternativa C (II e III) é a correta.","id":"1995420213088"},{"n":317,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"41","capn":"Questão 41 (cód. 1995420213094)","stem":"Quais dos títulos do Tesouro Norte Americano que, respectivamente, não emitem cupom e oferecem proteção em um cenário de incerteza inflacionária:","opts":[["a","T-Bill e TIPS"],["b","T-Bond’s e T-Bill"],["c","TIPS e T-Bill"],["d","T-Notes e TIPS"]],"ans":"a","exp":"Tema: títulos americanos sem cupom e com proteção contra inflação. O T-Bill é zero cupom, ou seja, não paga cupom. O TIPS protege contra a inflação, porque o principal é corrigido. A alternativa A é a chave. Vale notar que o TIPS paga cupom semestral, e por isso a formulação do enunciado é imprecisa para essa característica. Recomendo conferir a redação original.","id":"1995420213094"},{"n":318,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"42","capn":"Questão 42 (cód. 1995420213096)","stem":"Títulos Públicos são instrumentos de captação dos governos para equilibrar as contas públicas e servem como ativos de investimentos para os poupadores. Nos Estados Unidos, são títulos públicos que implicam em risco de reinvestimento, exceto","opts":[["a","T- Notes"],["b","T-Bond"],["c","TIPS"],["d","T-Bill"]],"ans":"d","exp":"Tema: títulos americanos com risco de reinvestimento. O risco de reinvestimento existe nos títulos com cupom periódico. O T-Bill é zero cupom, sem cupom para reinvestir, e por isso não tem esse risco. A alternativa D é a exceção, e é a correta.","id":"1995420213096"},{"n":319,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"43","capn":"Questão 43 (cód. 1995420213101)","stem":"Títulos Públicos são instrumentos de captação dos governos para equilibrar as contas públicas e servem como ativos de investimentos para os poupadores. Nos Estados Unidos, um dos títulos emitidos pelo governo é o Treasury Inflation Protected Securities – TIPS, com relação a esse título analise as afirmações abaixo: I. A Taxa de Cupom pode variar de acordo com o tempo II. Em caso de deflação, o principal do título cai III. O título possui atualização anual Está correto o que se afirma em:","opts":[["a","I e II"],["b","I, II e III"],["c","II e III"],["d","Apenas II"]],"ans":"d","exp":"Tema: características do TIPS. Analisando:\n\nI. Errado. A taxa de cupom é fixa sobre o principal corrigido. O que varia é o valor do principal, e não a taxa.\n\nII. Correto. Em caso de deflação, o principal pode cair, embora a norma preserve o valor nominal original em alguns casos.\n\nIII. Errado. O TIPS tem cupom semestral, e não anual.\n\nA alternativa D (apenas II) é a correta.","id":"1995420213101"},{"n":320,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"44","capn":"Questão 44 (cód. 1995420223001)","stem":"Sobre o índice de Sustentabilidade Empresarial (ISE B3), analise as afirmações abaixo: I. Contempla as 200 ações com maior negociabilidade e práticas sustentáveis II. Contempla empresas com as melhores práticas de ESG (Sustentáveis) III. A metodologia de inclusão no índice é através de pesquisa/questionário enviado para as companhias Está correto o que se afirma em:","opts":[["a","I e III"],["b","II e III"],["c","Apenas II"],["d","I, II e III"]],"ans":"d","exp":"Tema: Índice de Sustentabilidade Empresarial (ISE B3). Analisando:\n\nI. Duvidoso. O ISE reúne empresas com práticas sustentáveis, mas o número de 200 ações com maior negociabilidade não é a regra do índice, que tem composição própria.\n\nII. Correto. O índice inclui empresas com as melhores práticas de ESG.\n\nIII. Correto. A inclusão é feita por questionário enviado às companhias.\n\nA chave indica D (I, II e III), que aceita o item I. Pelo texto disponível, o item I não está confirmado. Vale conferir a metodologia do índice.","id":"1995420223001"},{"n":321,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"45","capn":"Questão 45 (cód. 1995420223003)","stem":"É função do Market Maker:","opts":[["a","Aumentar liquidez dos ativos e reduzir movimentos artificiais"],["b","Garantir o risco de crédito dos ativos para dar mais segurança ao mercado"],["c","Realizar a venda de ativos exclusivamente para fundos de investimentos"],["d","Atuar como contraparte para operações de altíssimo risco"]],"ans":"a","exp":"Tema: função do market maker. A mesma do item 37: aumentar a liquidez dos ativos e reduzir movimentos artificiais. A alternativa A é a correta.","id":"1995420223003"},{"n":322,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"46","capn":"Questão 46 (cód. 1995420223004)","stem":"Cintia fez uma aplicação em Certificado de Operações Estruturadas – COE atrelado à renda variável no exterior (SP500). Ela gostaria de saber qual será a tributação (Imposto de Renda) que incidirá no seu resgate:","opts":[["a","22,5% sempre"],["b","15% sempre"],["c","De 22,5% a 15%, conforme prazo de permanência"],["d","De 35% até 10%, conforme prazo de permanência"]],"ans":"c","exp":"Tema: IR sobre COE atrelado a índice americano. O COE tem tributação de renda fixa, com alíquota regressiva de 22,5% para prazos curtos até 15% para prazos longos, conforme a permanência. A alternativa C é a correta. As alíquotas fixas (A e B) não se aplicam, e a tabela de 35% a 10% (D) não é a regra do COE.","id":"1995420223004"},{"n":323,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"47","capn":"Questão 47 (cód. 1995420223011)","stem":"Uma empresa decide captar recursos através de uma operação de <i>Initial Public Offering – IPO. </i>Esse tipo de operação é o que permite a empresa passar a ser negociada em através do que conhece como . Complete as lacunas:","opts":[["a","Bolsa de Valores | Mercado Secundário"],["b","Mercado Secundário | Mercado Primário"],["c","Bolsa de Valores | Mercado de Balcão"],["d","Bolsa de Valores | Mercado Primário"]],"ans":"d","exp":"Tema: IPO. A operação de abertura de capital é feita no mercado primário, e permite que a empresa passe a ser negociada na bolsa de valores, no mercado secundário. A chave indica D: a empresa é negociada na bolsa, e o IPO é uma operação do mercado primário. A alternativa D é a correta.","id":"1995420223011"},{"n":324,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"48","capn":"Questão 48 (cód. 1995420223019)","stem":"Um título prefixado com o prazo de 2 anos está sendo negociado nesse momento com taxa de 4% ao ano. Nesse caso, o seu valor de negociação será:","opts":[["a","Acima de R$ 1.000"],["b","Não é possível determinar"],["c","Exatamente R$ 1.000"],["d","Inferior a R$ 1.000"]],"ans":"d","exp":"Tema: título prefixado negociado com taxa de 4% ao ano. O preço de um título prefixado sem cupom é calculado como o valor de face descontado pela taxa de negociação. Com prazo de dois anos e taxa de 4%, o preço é de 1.000 / 1,04² ≈ R$ 924, que está abaixo de R$ 1.000. A alternativa D é a correta.","id":"1995420223019"},{"n":325,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"49","capn":"Questão 49 (cód. 1995420223021)","stem":"Nos títulos de Renda Fixa existe a incidência de Imposto de Renda. Sobre esse tributo, para essa modalidade de investimento, analise as afirmações abaixo: I. O fato gerador é o resgate ou o pagamento de juros periódicos (cupons) II. A base de cálculo é o valor positivo entre o valor de venda e de compra III. O IOF é cobrado após a incidência do I.R Está correto o que se afirma em:","opts":[["a","I e II"],["b","I e III"],["c","II e III"],["d","Apenas II"]],"ans":"a","exp":"Tema: IR em títulos de renda fixa. Analisando:\n\nI. Correto. O fato gerador é o resgate ou o pagamento de cupons periódicos.\n\nII. Correto. A base de cálculo é o ganho positivo entre o valor de venda e o de compra.\n\nIII. Errado. O IOF é cobrado antes do IR, e não depois, na ordem de tributação da renda fixa.\n\nA alternativa A (I e II) é a correta.","id":"1995420223021"},{"n":326,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"50","capn":"Questão 50 (cód. 1995420223023)","stem":"Em um processo de abertura de capital (underwriting) do tipo “Melhores Esforços” o risco de não colocação dos títulos é do (a):","opts":[["a","Instituição Financeira"],["b","Investidor"],["c","Emissor dos Títulos"],["d","Compartilhado"]],"ans":"c","exp":"Tema: underwriting, modalidade melhores esforços. Nesse modelo, a instituição coordenadora se compromete apenas a fazer o melhor esforço para colocar os títulos, sem garantir a colocação. O risco de não colocação, portanto, fica com o emissor. A alternativa C é a correta. Na modalidade firme, o risco seria da instituição financeira.","id":"1995420223023"},{"n":327,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"51","capn":"Questão 51 (cód. 1995420223033)","stem":"Em um cenário de queda dos ativos, em qual gráfico o titular irá exercer a sua opção:","opts":[["a","I e II"],["b","I, II e III"],["c","Apenas I"],["d","Apenas II"]],"ans":"d","exp":"Tema: exercício de uma put em queda do ativo. O gráfico não aparece no texto extraído. A chave indica D (apenas II), que descreve o gráfico em que a put é exercida com queda do ativo. Vale conferir o gráfico original, porque a identificação depende da posição das linhas em relação ao preço de exercício.","id":"1995420223033"},{"n":328,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"52","capn":"Questão 52 (cód. 1995420223034)","stem":"Analise os gráficos abaixo: Nos pontos de preços 1 e 2, que indicam o preço do ativo na data do exercício (PE), um titular iria exercer em qual das situações:","opts":[["a","Em Ambas"],["b","Somente na segunda"],["c","Somente na primeira"],["d","Em nenhuma"]],"ans":"c","exp":"Tema: exercício de opção conforme o preço do ativo no vencimento. Os gráficos e os pontos de preço não aparecem no texto extraído. A chave indica C (somente na primeira). A decisão depende de comparar o preço de exercício com o preço do ativo em cada ponto, e recomendo conferir o gráfico original.","id":"1995420223034"},{"n":329,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"53","capn":"Questão 53 (cód. 1995420223035)","stem":"Um determinado investidor possui em sua T-Notes com juros de 5%. Nesse momento o mercado está com juros de 4%, para o mesmo prazo. Pode-se dizer que esse título será negociado:","opts":[["a","Com ágio"],["b","Com deságio"],["c","Ao par"],["d","Com desconto"]],"ans":"a","exp":"Tema: título com cupom acima da taxa de mercado. O T-Note paga 5%, e o mercado negocia taxa de 4% para o mesmo prazo. Como o título paga mais do que o mercado, ele é negociado com ágio, ou seja, acima do valor de face. A alternativa A é a correta.","id":"1995420223035"},{"n":330,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"54","capn":"Questão 54 (cód. 1995420223024)","stem":"Um investidor possui um direito de subscrição. Essa posição assemelha-se a um (a)","opts":[["a","Comprar de uma put"],["b","Compra de uma call"],["c","Venda de uma call"],["d","Venda de uma put"]],"ans":"b","exp":"Tema: direito de subscrição. Ele dá ao acionista o direito de comprar novas ações a um preço definido, o que é equivalente a uma opção de compra, ou call. A alternativa B é a correta. A put (A e D) dá o direito de vender, e a venda de call (C) é a posição do lançador.","id":"1995420223024"},{"n":331,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"55","capn":"Questão 55 (cód. 1995420223037)","stem":"Um título prefixado está sendo negociado com deságio de R$ 90,00 e paga cupom anual de R$ 50. Qual Current Yield desse título:","opts":[["a","5,50%"],["b","10%"],["c","Não é possível determinar"],["d","7,25%"]],"ans":"a","exp":"Tema: current yield (rendimento corrente). É o cupom anual dividido pelo preço de compra. O título tem valor de face de R$ 1.000 e foi comprado com deságio de R$ 90, então o preço é de R$ 910. O current yield é 50 / 910 = 5,49%, que corresponde à alternativa A (5,50%).","id":"1995420223037"},{"n":332,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"56","capn":"Questão 56 (cód. 1995420223038)","stem":"Cristiano compra em 06/12 BDR’s da Apple da Microsoft por R$ 10,00. Vende essas BDR’s em 10/12 pelo valor de R$ 15,00. Nesse caso, com relação à tributação:","opts":[["a","Deve pagar 20%"],["b","Deve pagar 15%"],["c","É isento"],["d","Deve pagar 27,5%"]],"ans":"b","exp":"Tema: tributação de BDR. A venda de BDR com lucro é tributada a 15% sobre o ganho, como ocorre com as ações e os demais ativos de renda variável. A alternativa B é a correta. A tributação de 20% (A), a isenção (C) e a de 27,5% (D) não correspondem à regra.","id":"1995420223038"},{"n":333,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"57","capn":"Questão 57 (cód. 1995420223039)","stem":"Uma empresa deseja emitir títulos na bolsa da Alemanha. Essa empresa deveria optar por:","opts":[["a","ADR"],["b","BDR"],["c","GDR"],["d","Debêntures"]],"ans":"c","exp":"Tema: recibo para emissão na Europa. Os recibos depositários globais (GDR) são usados para negociar títulos em bolsas fora dos Estados Unidos, como a da Alemanha. O ADR (A) é para os Estados Unidos, e o BDR (B) é para títulos estrangeiros negociados no Brasil. Debêntures (D) são títulos de dívida. A alternativa C é a correta.","id":"1995420223039"},{"n":334,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"58","capn":"Questão 58 (cód. 1995420223040)","stem":"Analise as afirmativas abaixo, para investidores pessoas físicas: I. Debêntures incentivadas têm isenção de I.R e também FGC II. Fundo de Investimento em Debênture Incentivada tem isenção de I.R e não conta com proteção do FGC III. LCA tem isenção de Imposto de Renda e garantia limitada do FGC Está correto o que se afirma em:","opts":[["a","I e II"],["b","I e III"],["c","II e III"],["d","I, II e III"]],"ans":"c","exp":"Tema: debêntures incentivadas, fundos e LCA. Analisando:\n\nI. Errado. Debêntures incentivadas têm isenção de IR, mas não têm garantia do FGC.\n\nII. Correto. O fundo de debêntures incentivadas tem isenção de IR para pessoa física, e não conta com o FGC.\n\nIII. Correto. A LCA tem isenção de IR para pessoa física e garantia limitada do FGC.\n\nA alternativa C (II e III) é a correta.","id":"1995420223040"},{"n":335,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"59","capn":"Questão 59 (cód. 1995420223042)","stem":"Sobre o índice de Sustentabilidade Empresarial (ISE B3), analise as afirmações abaixo: I. Contempla as 200 ações com maior negociabilidade e práticas sustentáveis II. Contempla empresas com as melhores práticas de ESG (Sustentáveis) III. A metodologia de inclusão no índice é através de pesquisa/questionário enviado para as companhias Está correto o que se afirma em:","opts":[["a","I e III"],["b","II e III"],["c","I e III"],["d","I, II e III"]],"ans":"d","exp":"Tema: ISE B3. A análise é a mesma da questão 44: os itens II e III procedem, e o item I não está confirmado pelo texto disponível. A chave indica D, mas a mesma ressalva vale aqui. Vale conferir a metodologia do índice.","id":"1995420223042"},{"n":336,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"60","capn":"Questão 60 (cód. 1995420223046)","stem":"O gráfico abaixo descreve qual tipo de operações no mercado de derivativos financeiros:","opts":[["a","Short Strangle"],["b","Butterfly"],["c","Long Strangle"],["d","Financiamento"]],"ans":"c","exp":"Tema: operação de derivativo representada no gráfico (Long Strangle). O gráfico não aparece no texto extraído. A chave indica C, Long Strangle, a mesma resposta da questão 18. Vale conferir o gráfico original.","id":"1995420223046"},{"n":337,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"61","capn":"Questão 61 (cód. 1995420223047)","stem":"Júlio realizou a compra de Petrobrás a termo pelo prazo de 60 dias e com o valor de R$ 40,00. Se ele desejar fechar essa posição (deixar de estar comprado a termo) o que ele deverá fazer:","opts":[["a","Não há como desfazer a operação antes do seu prazo final"],["b","Júlio precisa realizar uma venda a termo de Petrobrás, zerando assim a posição"],["c","Júlio pode realizar a quitação do contrato antecipadamente e irá pagar um valor proporcional ao período que ficou na operação"],["d","Júlio pode realizar a quitação do contrato antecipadamente, porém, irá pagar o mesmo valor que iria pagar no seu vencimento"]],"ans":"d","exp":"Tema: liquidação antecipada de termo. Ao quitar um contrato a termo antes do vencimento, o investidor paga o valor que pagaria no vencimento, descontado pelo ajuste de forma que o resultado seja o mesmo. A alternativa D é a correta. Não há como desfazer a operação (A) nem o valor proporcional ao período (C), porque o termo é pactuado pelo preço final.","id":"1995420223047"},{"n":338,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"62","capn":"Questão 62 (cód. 1995420223048)","stem":"Germano é um investidor pessoa física e ao consultar os títulos disponíveis para compra no Tesouro Direto chegou as seguintes informações (considerando um mesmo prazo): -LTN: 14,5% -NTN-B: 8% Considerando esses dados, qual é a inflação projetada para o período:","opts":[["a","6,02%"],["b","7,25%"],["c","5,87%"],["d","6,80%"]],"ans":"a","exp":"Tema: inflação projetada a partir de LTN e NTN-B. A taxa prefixada da LTN é de 14,5%, e a taxa real da NTN-B é de 8%. A inflação implícita é dada por (1,145 / 1,08) − 1 = 6,02%. A alternativa A é a correta.","id":"1995420223048"},{"n":339,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"63","capn":"Questão 63 (cód. 1995420223053)","stem":"Títulos Públicos são instrumentos de captação dos governos para equilibrar as contas públicas e servem como ativos de investimentos para os poupadores. Nos Estados Unidos, são títulos públicos que implicam em risco de reinvestimento, exceto","opts":[["a","T- Notes"],["b","T-Bond"],["c","TIPS"],["d","T-Bill"]],"ans":"d","exp":"Tema: títulos americanos com risco de reinvestimento. Igual à questão 42: o T-Bill é zero cupom e não tem risco de reinvestimento. A alternativa D é a correta.","id":"1995420223053"},{"n":340,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"64","capn":"Questão 64 (cód. 1995420223057)","stem":"Um determinado investidor decidiu fazer hedge, para se proteger da queda da moeda, com contratos futuros de dólar. Quando ele iniciou a operação o contrato estava cotado a 5.297. E quando ele fechou a operação, o contrato estava a 5.397. Ele fez a operação com 10 contratos. Considerando que cada contrato tenha equivalência de 1 U$, como ficará o fluxo financeiro para esse investidor:","opts":[["a","Receberá 1.000"],["b","Receberá 100.000"],["c","Pagará 100.000"],["d","Pagará 1.000"]],"ans":"d","exp":"Tema: hedge com contratos futuros de dólar. O investidor se protege da queda do dólar vendendo contratos futuros. Ele vendeu a 5.297 e fechou a 5.397, então houve alta de 100 pontos contra a posição. Com 10 contratos e cada contrato equivalente a US$ 1, a perda é de 100 × 10 = R$ 1.000, que ele paga. A alternativa D é a correta.","id":"1995420223057"},{"n":341,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"65","capn":"Questão 65 (cód. 1995420223058)","stem":"Seu cliente é importador de produtos para serem vendidos aqui no Brasil. Ele o procura para ajudar a montar estratégias de proteção (hege) para a alta do dólar. São operações possíveis para esse tipo de proteção: I. Comprar put de dólar II. Fazer NDF de dólar III. Comprar call de dólar Está correto o que se afirma em:","opts":[["a","I e II"],["b","II e III"],["c","Apenas I"],["d","I, II e III"]],"ans":"b","exp":"Tema: hedge de importador contra a alta do dólar. O importador precisa comprar dólar no futuro, então se protege com NDF de dólar, que trava a compra, e com a compra de call de dólar, que limita o preço máximo. A comprar put de dólar (I) protegeria contra queda. Por isso a alternativa B (II e III) é a correta.","id":"1995420223058"},{"n":342,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"66","capn":"Questão 66 (cód. 1995420223060)","stem":"Certificado de Operações Estruturadas – COE são títulos recentes no mercado financeiro. Analise as afirmações abaixo sobre esses títulos: I. Possuem tributação que varia de 22,50% até 15% II. Possuem garantia pelo FGC III. Todos são emitidos com Valor Nominal Protegido (VNP) Está correto o que se afirma em:","opts":[["a","I e II"],["b","Apenas I"],["c","Apenas III"],["d","I, II e III"]],"ans":"b","exp":"Tema: características dos COE. Analisando:\n\nI. Correto. A tributação do COE varia de 22,5% até 15%, conforme o prazo.\n\nII. Errado. O COE não tem garantia do FGC.\n\nIII. Errado. Nem todos os COE são emitidos com valor nominal protegido.\n\nA alternativa B (apenas I) é a correta.","id":"1995420223060"},{"n":343,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"67","capn":"Questão 67 (cód. 1995420223062)","stem":"O Fundo Garantidor de Crédito – FGC é uma instituição privada e tem como objetivo de contribuir para a confiança das pessoas no Sistema Financeiro Nacional. Nesse sentido, quando um banco sofre liquidação e alguns clientes possuem conta corrente conjunta conforme abaixo, qual será o valor que cada um dos clientes irá receber:","opts":[["a","Bernardo: R$ 258 mil; Júlio: R$ 50 mil; Luís: R$ 208 mil; João: R$ 83 mil"],["b","Bernardo: R$ 250 mil; Júlio: R$ 100 mil; Luís: R$ 208 mil; João: R$ 83 mil"],["c","Bernardo: R$ 250 mil; Júlio: R$ 50 mil; Luís: R$ 208 mil; João: R$ 83 mil"],["d","Bernardo: R$ 433 mil; Júlio: R$ 50 mil; Luís: R$ 208 mil; João: R$ 83 mil"]],"ans":"c","exp":"Tema: FGC e conta conjunta. É a mesma questão 11, com a mesma regra de divisão entre os titulares e de limite de R$ 250 mil. A chave indica C. Vale a mesma ressalva: a redistribuição depende da regra do FGC, que não está detalhada aqui.","id":"1995420223062"},{"n":344,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"68","capn":"Questão 68 (cód. 1995420223063)","stem":"Analise as funções abaixo sobre o modelo de precificação de opções Black & Scholes: I. Pode ser utilizado para precificação de qualquer tipo de opção II. Todos os investidores possuem a mesma taxa livre de risco III. O prêmio da opção sofre alterações até o seu vencimento Está correto o que se afirma em:","opts":[["a","I e II"],["b","I e III"],["c","Apenas II"],["d","I, II e III"]],"ans":"c","exp":"Tema: modelo de Black-Scholes. Analisando:\n\nI. Errado. O modelo foi feito para opções europeias, e não serve para qualquer tipo de opção.\n\nII. Correto. O modelo supõe uma taxa livre de risco única para todos os investidores.\n\nIII. Errado. O prêmio muda ao longo da vida da opção, e o modelo calcula esse valor em cada momento. Por isso a afirmação de que o prêmio não muda até o vencimento está errada.\n\nA alternativa C (apenas II) é a correta.","id":"1995420223063"},{"n":345,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"69","capn":"Questão 69 (cód. 1995420223064)","stem":"Os Índices de Mercado Anbima – IMA são índices referência para investimentos em renda fixa. Os índices são formados pelos títulos que compõem a Dívida Pública Interna Brasileira – DPIB. Analise as afirmações abaixo sobre esses índices: I. O IMA-Geral é formado por todos os títulos públicos e privados que compõem a dívida pública II. O IMA-B é formado por títulos públicos e privados indexados ao IPCA III. O IMA-S é formado por títulos ´públicos pós fixados atrelados à Selic Está correto o que se afirma em:","opts":[["a","I e II"],["b","I e III"],["c","Apenas III"],["d","I, II e III"]],"ans":"c","exp":"Tema: índices IMA. Analisando:\n\nI. Errado. O IMA-Geral é formado apenas por títulos públicos da dívida pública interna, e não por títulos privados.\n\nII. Errado. O IMA-B é formado apenas por títulos públicos atrelados ao IPCA, e não por títulos privados.\n\nIII. Correto. O IMA-S é formado por títulos públicos pós-fixados atrelados à Selic.\n\nA alternativa C (apenas III) é a correta.","id":"1995420223064"},{"n":346,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"70","capn":"Questão 70 (cód. 1995420223075)","stem":"Dionatan possui uma carteira de investimentos focado na aposentadoria. Entre os títulos dessa carteira, ele possui um título renda fixa zero cupom, com vencimento em 20/12/2023 e valor nominal de R$ 1.000. Esse título está com taxa de juros prefixado de 12% a.a. Pode-se afirmar que: I. O valor de face do título é inferior a R$ 1.000 II. O PU do título é inferior a R$ 1.000 III. O título não oscila de valor. Está correto o que se afirma em:","opts":[["a","I e III"],["b","II e III"],["c","Apenas II"],["d","I, II e III"]],"ans":"c","exp":"Tema: título zero cupom prefixado a 12% ao ano com valor de face de R$ 1.000. Analisando:\n\nI. Errado. O valor de face é de R$ 1.000, como indicado no enunciado. O preço de negociação é que fica abaixo disso.\n\nII. Correto. O PU, que é o preço unitário, fica abaixo de R$ 1.000, porque o título é negociado com desconto em relação ao valor de face.\n\nIII. Errado. O título oscila de valor conforme a taxa de mercado varia, então não é correto dizer que não oscila.\n\nA alternativa C (apenas II) é a correta.","id":"1995420223075"},{"n":347,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"71","capn":"Questão 71 (cód. 1995420223077)","stem":"Um Certificado de Operações Estruturadas – COE foi emitido pelo Banco SharkBank com as seguintes características: - Atrelado ao índice de ações (renda variável) dos Estados Unidos - Prazo de 4 anos - Janela de resgate semestral - Emissão do tipo Valor Nominal Protegido (VNP). Júlio é um investidor conservador e decidiu fazer a aplicação nesse COE. Ficou por 8 meses e teve lucro. Nesse caso, qual será o I.R devido por Júlio e quem fará o recolhimento?","opts":[["a","20%; Próprio Júlio"],["b","20%; SharkBank"],["c","15%; SharkBank"],["d","15%; Próprio Júlio"]],"ans":"b","exp":"Tema: IR de COE com prazo de oito meses e recolhimento. Oito meses equivalem a cerca de 240 dias, e na tabela regressiva de renda fixa essa faixa (181 a 360 dias) tem alíquota de 20%. O recolhimento na fonte é feito pela instituição emissora, o SharkBank. A alternativa B é a correta. A alternativa A atribui o recolhimento ao próprio investidor, o que não é o caso de COE distribuído por banco.","id":"1995420223077"},{"n":348,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"72","capn":"Questão 72 (cód. 1995420223079)","stem":"Bruna possui uma carteira de investimentos focado na aposentadoria. Entre os títulos dessa carteira, ele possui uma Letra de Crédito do Agronegócio – LCA. Ela o questiona com relação ao prazo mínimo desse tipo de título. Você explica que: I. Em geral, o prazo mínimo é de 90 dias II. Quando estiver atrelado à índice de preço, o prazo é de 12 meses III. O prazo máximo é de 12 meses Está correto o que se afirma em:","opts":[["a","I e II"],["b","II e III"],["c","Apenas II"],["d","I, II e III"]],"ans":"a","exp":"Tema: prazo da LCA. Analisando:\n\nI. Correto. Em geral, o prazo mínimo da LCA é de 90 dias.\n\nII. Correto. Quando a LCA é atrelada a índice de preço, o prazo mínimo passa a ser de 12 meses.\n\nIII. Errado. A LCA não tem prazo máximo de 12 meses. Esse limite não existe como regra.\n\nA alternativa A (I e II) é a correta.","id":"1995420223079"},{"n":349,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"73","capn":"Questão 73 (cód. 1995420223081)","stem":"”Poupança em 2022 renderá 80% do CDI”. Jornal Shark, 2022. A poupança, aplicação mais popular do nosso país, é sempre tema de jornais e revistas. Com relação ao formato de rendimento dos juros desse produto de investimento, assinale a alternativa correta:","opts":[["a","Se dá pelo saldo médio das aplicações no período"],["b","Se dá pelo maior saldo das aplicações no período"],["c","É sempre 0,5% ao mês para pessoa física"],["d","Se dá pelo menor saldo das aplicações do período"]],"ans":"d","exp":"Tema: formato de rendimento da poupança. Pela regra, o rendimento dos juros da poupança é calculado sobre o menor saldo do período, e não sobre a média ou o maior saldo. A alternativa D é a correta. As alternativas A e B adotam critérios de saldo que não correspondem ao cálculo da poupança, e a alternativa C (0,5% ao mês) é a remuneração base, mas não o formato de cálculo.","id":"1995420223081"},{"n":350,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"74","capn":"Questão 74 (cód. 1995420223088)","stem":"Affonso é um jovem programador muito preocupado em garantir estabilidade financeira para o futuro da sua família. Ele procura um consultor de investimentos com 2 opções para alocar seus recursos: I. Título prefixado (500 dias úteis): 9% ao ano II. NTN-B (500 dias úteis): 12% ao período Qual a inflação necessária (projetada) para que a escolha dos 2 títulos seja indiferente para Affonso?","opts":[["a","7,25%"],["b","8,85%"],["c","12,25%"],["d","5,94%"]],"ans":"d","exp":"Tema: inflação de equilíbrio entre um prefixado e uma NTN-B. O prefixado de 9% ao ano por 500 dias úteis, que equivalem a 500/252 = 1,984 anos, acumula (1,09)^1,984 − 1 ≈ 18,65%. A NTN-B paga 12% ao período, e para igualar o resultado a inflação projetada precisa ser de (1,1865 / 1,12) − 1 ≈ 5,94%. A alternativa D é a correta.","id":"1995420223088"},{"n":351,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"75","capn":"Questão 75 (cód. 1995420223089)","stem":"Cláudia possui em sua carteira um título com valor de face de R$ 1 mil. O mesmo paga cupom anual de R$ 60 e foi comprado com deságio de R$ 43. Qual o Current Yield desse título:","opts":[["a","12,53%"],["b","6,26%"],["c","10,75%"],["d","5,94%"]],"ans":"b","exp":"Tema: current yield (rendimento corrente). O título tem valor de face de R$ 1.000, cupom anual de R$ 60 e preço de R$ 1.000 − R$ 43 = R$ 957. O current yield é 60 / 957 = 6,27%, que corresponde à alternativa B (6,26%) com arredondamento. A alternativa B é a correta. A diferença de 0,01 vem do arredondamento.","id":"1995420223089"},{"n":352,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"76","capn":"Questão 76 (cód. 1995420223091)","stem":"Germano é um rapaz de meia idade que está buscando construir uma carteira de investimentos com o mínimo risco possível. Recebeu um valor de rescisão do seu trabalho anterior e deseja um título de renda fixa, sem risco de crédito e atrelado à taxa de juros. Ele deveria optar por:","opts":[["a","CDB de banco de primeira linha"],["b","NTN-B"],["c","NTN-F"],["d","LFT"]],"ans":"d","exp":"Tema: título de renda fixa sem risco de crédito e atrelado à taxa de juros. A LFT é um título público pós-fixado atrelado à Selic, sem risco de crédito, porque é emitido pelo Tesouro. A alternativa D é a correta. A NTN-B (B) é atrelada à inflação, a NTN-F (C) é prefixada, e o CDB (A) tem risco de crédito do banco emissor.","id":"1995420223091"},{"n":353,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"77","capn":"Questão 77 (cód. 1995420223092)","stem":"Dr. João é um médico radiologista e possui uma clínica em Porto Alegre. Decidiu então comprar um equipamento de ultrassonografia, importado. Dr. João decidiu financiar essa aquisição, atrelado ao dólar. Dr. João procura um especialista de investimentos, Bernardo, para usar um derivativo para fazer hedge. Bernardo deveria indicar:","opts":[["a","Comprar Put de Dólar"],["b","Vender Call de Dólar"],["c","Fazer NDF de Dólar"],["d","Vender Put de Dólar"]],"ans":"c","exp":"Tema: hedge de importação com dívida atrelada ao dólar. O comprador do equipamento importado precisa de proteção contra a alta do dólar, e a ferramenta adequada é o NDF de dólar, que trava a taxa de compra da moeda. A alternativa C é a correta. Comprar put (A) protege contra a queda, e vender call (B) ou put (D) expõe o investidor à alta da moeda.","id":"1995420223092"},{"n":354,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"78","capn":"Questão 78 (cód. 1995420223093)","stem":"O mercado de derivativos desenvolvido auxilia um país e seus investidores para adoção de estratégias visando redução de risco. Com relação à diferença entre NDF (Non Deliverable Forward) e Mercado Futuro, assinale a alternativa correta:","opts":[["a","NDF possui ajuste diário e Mercado Futuro não"],["b","Mercado Futuro é tributado com Renda Fixa e NDF como Renda Variável"],["c","NDF é um contrato não padronizado e o Mercado Futuro é padronizado"],["d","NDF é compra de dólar no mercado à vista"]],"ans":"c","exp":"Tema: NDF e mercado futuro. O NDF é um contrato de câmbio não padronizado, negociado em balcão, com prazo e valor livres. O mercado futuro é padronizado e negociado em bolsa. A alternativa C é a correta. O NDF não tem ajuste diário na mesma forma (A), a tributação não é a diferença entre renda fixa e variável (B), e o NDF não é compra de dólar à vista (D).","id":"1995420223093"},{"n":355,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"79","capn":"Questão 79 (cód. 1995420223097)","stem":"O Estagiário comprou títulos públicos dos Estados Unidos para a sua carteira. Entre esses títulos, adquiriu TIPS (Treasury Inflation Protected Securities). Ele faz 3 afirmações sobre esse título: I. São ajustadas pelo CPI (Consumer Price Index) dos EUA II. O prazo mais curto é de cinco anos e o mais longo é de 30 anos III. Podem pagar um valor abaixo do principal caso haja deflação Está correto o que se afirma em:","opts":[["a","I e II"],["b","I e III"],["c","Apenas II"],["d","I, II e III"]],"ans":"a","exp":"Tema: TIPS. Analisando:\n\nI. Correto. O principal do TIPS é ajustado pelo CPI dos Estados Unidos.\n\nII. Correto. Os TIPS têm prazos de 5, 10 e 30 anos, então o mais curto é de cinco anos e o mais longo de 30.\n\nIII. Errado. O TIPS não paga valor abaixo do principal original, mesmo em deflação. Há uma proteção que impede o principal de ficar abaixo do valor nominal inicial.\n\nA alternativa A (I e II) é a correta.","id":"1995420223097"},{"n":356,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"80","capn":"Questão 80 (cód. 1995420223098)","stem":"A companhia energética “Shark Energy” emitiu em 2021 Debêntures pagando taxa de 8% a.a. Na emissão a empresa foi classificada por uma agência de risco (“Shark Auditores”) que concedeu rating AA para a companhia. Decide então, fazer uma nova emissão em 2022 e contrata novamente a agência de risco que classifica a empresa agora como A. Considerando que trata-se do mesmo emissor, é de se esperar que a rentabilidade agora:","opts":[["a","Seja menor que em 2021"],["b","Seja igual a 2021"],["c","Não é possível determinar"],["d","Seja maior que em 2021"]],"ans":"d","exp":"Tema: rentabilidade de debêntures após queda de rating. A mesma empresa emitiu em 2021 com rating AA e em 2022 com rating A. Um rating menor significa maior risco de crédito, e o investidor exige mais retorno para compensar, então a rentabilidade deve ser maior do que em 2021. A alternativa D é a correta.","id":"1995420223098"},{"n":357,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"81","capn":"Questão 81 (cód. 1995420223101)","stem":"Bernardo comprou no dia 20/05/2022 300 ações da Empresa Shark (TUBA10) pelo preço de R$ 48,00 cada uma. Após ter realizado a compra dessas ações, é anunciado que a empresa seria vendida, ainda no mesmo dia e as ações se valorizam muito, indo para R$ 67,00. Bernardo decide então vender sua posição. Qual será o IRRF.","opts":[["a","R$ 57,00"],["b","R$ 201,00"],["c","R$ 1,00"],["d","Zero"]],"ans":"a","exp":"Tema: IRRF em day trade. Bernardo comprou 300 ações a R$ 48 e vendeu a R$ 67 no mesmo dia. O lucro é de (67 − 48) × 300 = R$ 5.700. Em day trade, o IRRF na fonte é de 1% sobre o lucro, e não sobre o valor de venda: 1% × 5.700 = R$ 57,00. A alternativa A é a correta. A alternativa B (R$ 201) usa 1% sobre o valor de venda, o que é o cálculo errado para day trade.","id":"1995420223101"},{"n":358,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"82","capn":"Questão 82 (cód. 1995420223102)","stem":"Eduardo é um investidor do Mercado de Capitais faz mais de 15 anos. Depois de tantos anos, começou a montar operações estruturadas com Derivativos. No dia de hoje ele decide montar uma operação conhecida como , que consiste na compra de 1 PUT e também 1 Call de um mesmo ativo. Complete a lacuna:","opts":[["a","Box de 4 pontas"],["b","Short Strangle"],["c","Long&Short"],["d","Long Strangle"]],"ans":"d","exp":"Tema: operação com compra de put e call de mesmo ativo. Quando se compra uma put e uma call de um mesmo ativo com preços de exercício diferentes, a estratégia é o long strangle. A alternativa D é a correta. O box (A) combina travas de alta e de baixa, o short strangle (B) é a venda das duas opções, e a alternativa C não é uma estratégia com esse nome.","id":"1995420223102"},{"n":359,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"83","capn":"Questão 83 (cód. 1995420223109)","stem":"Bernardo possui uma empresa exportadora de café e é correntista do “Shark Bank”. O seu gerente, Paulo, conhecedor da atividade econômica de Bernardo, apresenta então algumas opções de posicionamento no mercado de derivativos para que Bernardo tenha um “Hedge” da sua operação. Entre as opções apresentadas estão: I. Fazer um Swap com posição ativa em CDI e passiva em dólar II. Comprar PUT’s de dólar III. Comprar Call de dólar São alternativas que servem para esse objetivo de Bernardo:","opts":[["a","I e II"],["b","II e III"],["c","I, II e III"],["d","Apenas II"]],"ans":"a","exp":"Tema: hedge de exportadora de café. A empresa recebe em dólar, então precisa se proteger contra a queda da moeda. Comprar put de dólar (II) garante um preço mínimo de venda, o que é adequado. O swap com ponta ativa em CDI e passiva em dólar (I) também troca a exposição cambial, e por isso serve ao objetivo. Comprar call de dólar (III) protegeria a empresa contra a alta, o que não é o interesse de quem recebe em dólar. A alternativa A (I e II) é a correta.","id":"1995420223109"},{"n":360,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"84","capn":"Questão 84 (cód. 1995420223112)","stem":"“Tag Along é um mecanismo de proteção a acionistas minoritários de uma companhia, que garante a eles o direito de deixaram uma sociedade, caso o controle da companhia seja adquirido por um investidor que até então não fazia parte da mesma.” Com relação à essa definição analise as afirmações abaixo: I. No nível 2 o Tag Along é de 100% para todas as ações II. No Novo Mercado o Tag Along é de 100% para “ON” e “PN” III. No nível 1 o Tag Along é de 80% para as ações “ON” Está correto o que se afirma em:","opts":[["a","I e III"],["b","II e III"],["c","I e II"],["d","Apenas II"]],"ans":"a","exp":"Tema: Tag Along nos segmentos de listagem. Analisando:\n\nI. Correto. No Nível 2, o Tag Along é de 100% para todas as ações, ON e PN.\n\nII. Errado. No Novo Mercado, o Tag Along é de 100% apenas para as ações ON, e não para ON e PN.\n\nIII. Correto. No Nível 1, o Tag Along é de 80% para as ações ON.\n\nA alternativa A (I e III) é a correta.","id":"1995420223112"},{"n":361,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"85","capn":"Questão 85 (cód. 1995420223115)","stem":"Tipo de investimento que não possui risco de crédito e está atrelado a índice de preços:","opts":[["a","NTN-F"],["b","CDB-DI"],["c","LFT"],["d","NTN-B"]],"ans":"d","exp":"Tema: título sem risco de crédito atrelado a índice de preços. A NTN-B é um título público indexado ao IPCA, sem risco de crédito, porque é emitido pelo Tesouro. A alternativa D é a correta. A NTN-F (A) é prefixada, o CDB-DI (B) tem risco do banco, e a LFT (C) é atrelada à Selic.","id":"1995420223115"},{"n":362,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"86","capn":"Questão 86 (cód. 9756)","stem":"Sobre paridade de put e call europeia, pode – se afirmar que:","opts":[["a","O valor de uma call europeia pode ser deduzido do valor de uma put europeia tendo ambas os mesmos preços de exercício e datas de vencimentos."],["b","O valor de uma call europeia pode ser deduzido do valor de uma put europeia tendo ambas os mesmos preços de exercício."],["c","O valor de call europeia pode ser deduzido do valor de uma put europeia tendo ambas as mesmas datas de vencimento."],["d","O valor de uma call europeia pode se deduzido do valor de uma put americana tendo ambas os mesmos preços de exercício e datas de vencimento iguais."]],"ans":"a","exp":"Tema: paridade put-call europeia. Pela paridade, o valor da call europeia pode ser deduzido do valor da put europeia, desde que ambas tenham o mesmo preço de exercício e a mesma data de vencimento. A alternativa A é a correta, porque inclui as duas condições. As alternativas B e C omitem uma das condições, e a D usa uma put americana, que não cabe na paridade.","id":"9756"},{"n":363,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"87","capn":"Questão 87 (cód. 9757)","stem":"O clube de investimento é uma alternativa para acessar o mercado de ações de forma diversificada e sob estrutura de condomínio de recursos. Sobre esta estrutura, é correto afirmar que:","opts":[["a","Clubes podem ser constituídos com prazo de duração determinado ou indeterminado."],["b","Serão fiscalizados pela corretora que o constitui e pela CVM."],["c","O gestor irá definir a quantidade máxima de cotas que um cotista poderá adquirir."],["d","O investimento deve ser realizado pelo mínimo de 90 dias."]],"ans":"a","exp":"Tema: prazo de clubes de investimento. Os clubes podem ser constituídos com prazo de duração determinado ou indeterminado, conforme o regulamento. A alternativa A é a correta. Os clubes não são fiscalizados pela corretora que os constitui (B), o gestor não limita a quantidade de cotas por cotista (C) e não há prazo mínimo de 90 dias (D).","id":"9757"},{"n":364,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"88","capn":"Questão 88 (cód. 9759)","stem":"Um CDB com rentabilidade de 99% do CDI para vencimento em 30 dias é um exemplo de título:","opts":[["a","Prefixado."],["b","Pós fixado."],["c","Híbrido."],["d","Sem liquidez."]],"ans":"b","exp":"Tema: CDB com rentabilidade de 99% do CDI. O rendimento depende do CDI, que varia ao longo do tempo, então o título é pós-fixado. A alternativa B é a correta. Prefixado (A) teria taxa fixa, e híbrido (C) combina duas formas, o que não se aplica.","id":"9759"},{"n":365,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"89","capn":"Questão 89 (cód. 9760)","stem":"Sobre o vencimento de contratos futuros de Ibovespa, os vencimentos ocorrem:","opts":[["a","Mensalmente."],["b","Bimestralmente."],["c","Semestralmente."],["d","Anualmente."]],"ans":"b","exp":"Tema: vencimentos do contrato futuro de Ibovespa. Os vencimentos ocorrem bimestralmente, em meses pares. A alternativa B é a correta.","id":"9760"},{"n":366,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"90","capn":"Questão 90 (cód. 9764)","stem":"Sobre o convenience yield, é correto afirmar que:","opts":[["a","Será maior quanto maior a escassez de uma commoditie."],["b","Será menor quanto maior a escassez de uma commoditie."],["c","É responsável por avaliar o índice Beta de um ativo agropecuário."],["d","Nos ativos agropecuários, o convenience yield é responsável por mensurar a negociabilidade do ativo frente ao seu índice futuro."]],"ans":"a","exp":"Tema: convenience yield. É o benefício de manter o estoque físico de uma commodity, e tende a ser maior quando a commodity é mais escassa, porque o detentor do ativo ganha vantagem em ter o produto disponível. A alternativa A é a correta. As alternativas B, C e D invertem a relação ou atribuem ao convenience yield funções que não são suas.","id":"9764"},{"n":367,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"91","capn":"Questão 91 (cód. 9765)","stem":"“A respeito do convenience yield do mercado futuro de commodities, pode – se afirmar que este será quanto a escassez de uma commoditie.” Complete as lacunas:","opts":[["a","Menor / Maior"],["b","Maior / Menor"],["c","Maior / Maior"],["d","Menor / Igual"]],"ans":"c","exp":"Tema: relação entre convenience yield e escassez no mercado futuro. A chave indica C (maior/maior), que descreve a tendência de o convenience yield aumentar quando a escassez aumenta. A alternativa C é a correta pela chave. A análise confirma a mesma direção da questão 90.","id":"9765"},{"n":368,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"92","capn":"Questão 92 (cód. 199544102)","stem":"Com relação ao risco operacional, assinale a alternativa correta:","opts":[["a","É o risco de perdas (diretas ou indiretas) determinadas por erros humanos, falhas nos sistemas de informações e computadores"],["b","É o risco de perdas (diretas ou indiretas) determinadas por oscilações nos valores dos ativos presentes na carteira de uma instituição financeira"],["c","Com o objetivo de reduzir o risco operacional, é indicado que as instituições financeiras mantenham sempre a tecnologia atual sem melhorias de processos"],["d","É o risco de perdas (diretas ou indiretas) determinadas por oscilações de valores de dívidas lastreadas em moeda estrangeira"]],"ans":"a","exp":"Tema: risco operacional. É o risco de perdas diretas ou indiretas causadas por erros humanos, falhas em sistemas de informação e computadores, processos e eventos externos. A alternativa A é a correta. A alternativa B descreve risco de mercado, a D descreve risco cambial de dívidas, e a C defende não atualizar a tecnologia, o que aumenta o risco.","id":"199544102"},{"n":369,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"93","capn":"Questão 93 (cód. 1995440103)","stem":"Com relação a risco:","opts":[["a","O risco de mercado pode ser reduzido com operações de hedge, já o risco de liquidez é aquele decorrente da variação ligado à moeda estrangeira"],["b","Risco de crédito é a possibilidade de perdas decorrentes por falta de pagamento dos emissores de títulos, já o risco operacional é decorrente das oscilações dos valores dos títulos que estão na carteira de investimentos"],["c","O risco Sistemático pode ser reduzido através da diversificação"],["d","O Value At Risk define a perda máxima potencial de uma carteira, com um determinado nível de confiança"]],"ans":"d","exp":"Tema: conceitos de risco. A alternativa D é a correta: o Value at Risk (VaR) mede a perda máxima potencial de uma carteira, com um nível de confiança definido. As demais trocam os conceitos: hedge reduz risco de mercado, mas não é o que define o risco de liquidez (A); o risco de crédito é a falta de pagamento (B), e o risco sistemático é reduzido pela diversificação só em parte, o que não é a regra da alternativa C.","id":"1995440103"},{"n":370,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"94","capn":"Questão 94 (cód. 199544104)","stem":"Um investidor que deseja reduzir o seu risco de oscilação de taxa de juros de uma carteira de renda fixa pós fixado, poderia:","opts":[["a","Vender contratos futuros de índice DI"],["b","Fazer um contrato de SWAP com ponta ativa em Juros-DI e ponta passiva em Pré-Fixado"],["c","Comprar contratos futuros de índice DI"],["d","Vender contratos futuros de Ibovespa"]],"ans":"a","exp":"Tema: proteção contra oscilação de juros em carteira pós-fixada. A chave indica A (vender contratos futuros de DI). Um investidor com renda fixa pós-fixada tem exposição ao CDI, e o contrato futuro de DI permite ajustar essa exposição. Essa resposta depende da leitura do que é a exposição do portfólio. A posição de hedge correta para carteira pós-fixada costuma ser discutida, e recomendo conferir a apostila original para este caso.","id":"199544104"},{"n":371,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"95","capn":"Questão 95 (cód. 199544105)","stem":"Com relação ao Value At Risk - VAR, assinale a alternativa correta:","opts":[["a","Significa a perda máxima que um investidor pode ter, com um determinado nível de confiança"],["b","Significa o retorno máximo que um investidor pode ter"],["c","Significa a média histórica de oscilação de um ativo"],["d","Significa o quanto um investidor terá de retorno a partir de um determinado valor investido"]],"ans":"a","exp":"Tema: Value at Risk (VaR). É a perda máxima que o investidor pode ter, em determinado período, com um nível de confiança estabelecido. A alternativa A é a correta. As demais definem retorno máximo, média de oscilação ou retorno sobre o investimento, que não são o conceito do VaR.","id":"199544105"},{"n":372,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"96","capn":"Questão 96 (cód. 199544106)","stem":"Seu cliente fez uma aplicação em CDB e o banco sofreu liquidação. Que tipo de risco será observado, principalmente:","opts":[["a","Legal, que é coberto pelo FGC até o limite de R$ 250 mil"],["b","De liquidez, que é coberto pelo FGC até o limite de R$ 250 mil"],["c","De mercado, que é coberto pelo FGC até o limite de R$ 250 mil"],["d","De crédito, que é coberto pelo FGC até o limite de R$ 250 mil."]],"ans":"d","exp":"Tema: risco de crédito em CDB com liquidação do banco. O risco envolvido é o de crédito, porque o emissor não consegue pagar. O FGC cobre até R$ 250 mil por titular e por instituição. A alternativa D é a correta.","id":"199544106"},{"n":373,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"97","capn":"Questão 97 (cód. 199544107)","stem":"O risco de liquidez presente em um título refere-se a:","opts":[["a","Impossibilidade de se comercializar um ativo por seu preço justo"],["b","Oscilações naturais no preço do ativo"],["c","Não pagamento das obrigações por parte do emissor do ativo"],["d","Excesso de recursos em um determinado mercado"]],"ans":"a","exp":"Tema: risco de liquidez. É a impossibilidade de vender um ativo pelo seu preço justo, por falta de compradores ou de demanda. A alternativa A é a correta. As alternativas B e C descrevem risco de mercado e risco de crédito, e a D não é uma definição de risco.","id":"199544107"},{"n":374,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"98","capn":"Questão 98 (cód. 199544108)","stem":"\"Seu cliente possui 4 produtos prefixados na carteira conforme prazos abaixo: Produto Prazo (Dias) I 70 II 120 III 250 IV 350 Qual dos 4 ativos é o que mais seria afetado em uma alteração da taxa de juros:\"","opts":[["a","I"],["b","II"],["c","III"],["d","IV"]],"ans":"d","exp":"Tema: sensibilidade a variações de juros em prefixados. Quanto maior o prazo, maior a sensibilidade do preço a uma mudança na taxa de juros. O produto IV, com 350 dias, é o de maior prazo entre os quatro, e por isso seria o mais afetado. A alternativa D é a correta.","id":"199544108"},{"n":375,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"99","capn":"Questão 99 (cód. 199544109)","stem":"O risco de mercado em um fundo de investimento pode ser entendido como:","opts":[["a","Variação do valor das cotas desse fundo"],["b","Soma dos aportes realizados nesse fundo"],["c","Soma dos resgates realizados nesse fundo"],["d","Diferença entre aportes e resgates realizados nesse fundo"]],"ans":"a","exp":"Tema: risco de mercado em fundo de investimento. Ele se traduz na variação do valor das cotas, que sobe ou cai conforme os ativos da carteira oscilam. A alternativa A é a correta. Aportes, resgates e a diferença entre eles (B, C e D) são movimentações de cotistas, e não riscos de mercado.","id":"199544109"},{"n":376,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"100","capn":"Questão 100 (cód. 199544110)","stem":"Um ativo com maior risco de crédito é aquele que tem:","opts":[["a","Maior prazo"],["b","Maior chance de inadimplência"],["c","Menor juros"],["d","Menor liquidez"]],"ans":"b","exp":"Tema: risco de crédito. Um ativo tem mais risco de crédito quando tem maior chance de inadimplência do emissor. A alternativa B é a correta. Prazo (A), juros mais baixos (C) e liquidez (D) não definem o risco de crédito.","id":"199544110"},{"n":377,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"101","capn":"Questão 101 (cód. 199544111)","stem":"Dois ativos (A e B) de mesmo emissor possuem prazo de 1 e 10 anos, respectivamente. O título B terá:","opts":[["a","Maior risco e menor rentabilidade que o ativo A"],["b","Maior risco e maior rentabilidade que o ativo A"],["c","Menor risco e maior rentabilidade que o ativo A"],["d","Menor risco e menor rentabilidade que o ativo A"]],"ans":"b","exp":"Tema: prazo, risco e rentabilidade. Para o mesmo emissor, o título de prazo maior (10 anos) tem mais risco e, por isso, paga maior rentabilidade do que o de prazo menor (1 ano). A alternativa B é a correta. As demais alternativas invertem essa relação.","id":"199544111"},{"n":378,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"102","capn":"Questão 102 (cód. 199544112)","stem":"Tipo de risco que pode ser reduzido com a diversificação:","opts":[["a","Sistemático"],["b","Não Sistemático"],["c","Não Específico"],["d","De Conjuntura"]],"ans":"b","exp":"Tema: diversificação e tipos de risco. A diversificação reduz o risco não sistemático, que é específico de empresas ou setores. O risco sistemático, de mercado, não é eliminado pela diversificação. A alternativa B é a correta.","id":"199544112"},{"n":379,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"103","capn":"Questão 103 (cód. 199544113)","stem":"Risco de Liquidez pode ser definido como:","opts":[["a","Possibilidade de o emissor de um título não honrar com o seu compromisso de pagar o mesmo"],["b","Possibilidade de não ser possível comercializar um ativo pelo seu preço justo, por falta de demanda no mercado"],["c","Possibilidade de oscilação de preço de um ativo por condições naturais do mercado"],["d","A possibilidade do rating de crédito do emissor se confirmar no prazo do título"]],"ans":"b","exp":"Tema: risco de liquidez. É a possibilidade de não conseguir vender um ativo pelo seu preço justo, por falta de demanda no mercado. A alternativa B é a correta. As demais descrevem risco de crédito, risco de mercado e risco de rating, que não são a definição de liquidez.","id":"199544113"},{"n":380,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"104","capn":"Questão 104 (cód. 199544114)","stem":"Quanto maior for o número de interessados em comprar um determinado ativo, maior será a sua:","opts":[["a","Liquidez"],["b","Possibilidade de perdas"],["c","Oscilação"],["d","Correlação"]],"ans":"a","exp":"Tema: liquidez de um ativo. Quanto mais interessados em comprar, mais fácil é vender o ativo, o que aumenta a liquidez. A alternativa A é a correta. Possibilidade de perdas (B), oscilação (C) e correlação (D) não são consequências diretas do número de compradores.","id":"199544114"},{"n":381,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"105","capn":"Questão 105 (cód. 199544115)","stem":"Quando se tem dificuldade em comercializar um ativo pelo seu preço justo, por falta de compradores, que tipo de risco se caracteriza, principalmente:","opts":[["a","Mercado"],["b","Liquidez"],["c","Crédito"],["d","Operacional"]],"ans":"b","exp":"Tema: dificuldade de vender pelo preço justo por falta de compradores. É o risco de liquidez. A alternativa B é a correta. As demais descrevem risco de mercado, de crédito e operacional.","id":"199544115"},{"n":382,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"106","capn":"Questão 106 (cód. 199544116)","stem":"Com relação ao Risco de Mercado, assinale a alternativa correta:","opts":[["a","Refere-se as oscilações dos ativos presentes em uma carteira por condições naturais"],["b","Refere-se à possiblidade de não pagamento de um título por parte do emissor"],["c","Refere-se à impossibilidade de se vender um ativo por seu preço justo por falta de compradores"],["d","Pode ser reduzido a zero com a diversificação"]],"ans":"a","exp":"Tema: risco de mercado. É a oscilação dos preços dos ativos da carteira, por condições naturais do mercado. A alternativa A é a correta. As alternativas B e C descrevem risco de crédito e risco de liquidez, e a D afirma que o risco de mercado pode ser zerado com diversificação, o que não é verdadeiro, porque ele é sistemático.","id":"199544116"},{"n":383,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"107","capn":"Questão 107 (cód. 199544118)","stem":"\"Dois investimentos estão disponíveis para aplicação conforme abaixo: Título: A Rating: AAA Título: B Rating: BBB O título A em relação ao título B:\"","opts":[["a","É mais arriscado e por isso deve apresentar rentabilidade maior"],["b","É mais arriscado e por isso deve apresentar rentabilidade menor"],["c","É menos arriscado e por isso deve apresentar rentabilidade maior"],["d","É menos arriscado e por isso deve apresentar rentabilidade menor"]],"ans":"d","exp":"Tema: rating e rentabilidade. O título A tem rating AAA, que indica menor risco de crédito do que o BBB do título B. Pelo princípio de que menor risco implica menor rentabilidade, o título A deve pagar rentabilidade menor. A alternativa D é a correta.","id":"199544118"},{"n":384,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"108","capn":"Questão 108 (cód. 199544119)","stem":"Um determinado investidor comprou uma ação no valor de R$ 20,00. No momento de vender, entre as várias ofertas de compra, a melhor foi de R$ 13,00. Qual foi o risco presente, principalmente:","opts":[["a","Mercado"],["b","Crédito"],["c","Liquidez"],["d","Legal"]],"ans":"a","exp":"Tema: diferença entre preço de compra e a melhor oferta de venda. Quando há várias ofertas de compra, o que se perde é o preço, e não a possibilidade de vender. O risco presente é o de mercado, porque o preço do ativo variou. A alternativa A é a correta. A liquidez (C) só aparece quando há uma única oferta, como no item 109.","id":"199544119"},{"n":385,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"109","capn":"Questão 109 (cód. 199544120)","stem":"Um determinado investidor comprou uma ação no valor de R$ 20,00. No momento de vender, recebeu uma única oferta de compra no valor de R$ 13,00. Qual foi o risco presente, principalmente:","opts":[["a","Mercado"],["b","Crédito"],["c","Liquidez"],["d","Legal"]],"ans":"c","exp":"Tema: uma única oferta de compra. Quando só existe uma oferta, a dificuldade de vender ao preço desejado decorre da falta de compradores, o que caracteriza o risco de liquidez. A alternativa C é a correta. A diferença para a questão 108 é que lá há várias ofertas, e o problema é o preço.","id":"199544120"},{"n":386,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"110","capn":"Questão 110 (cód. 199544121)","stem":"São riscos presentes nas aplicações:","opts":[["a","Ações: Mercado, Crédito e Liquidez. CDB: Mercado, Crédito e Liquidez"],["b","Ações: Mercado e Liquidez. CDB: Mercado e Crédito"],["c","Ações: Mercado, Crédito e Liquidez. CDB: Mercado e Liquidez"],["d","Ações: Mercado e Liquidez. CDB: Mercado, Crédito e Liquidez"]],"ans":"d","exp":"Tema: riscos de ações e de CDB. Ações têm risco de mercado e de liquidez. CDB tem risco de mercado, de crédito e de liquidez. A alternativa D é a correta, porque é a única com essa combinação.","id":"199544121"},{"n":387,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"111","capn":"Questão 111 (cód. 199544122)","stem":"Se compararmos uma aplicação em um título privado (LCI, CDB) em relação a uma aplicação em título público, o título privado deveria ter uma rentabilidade maior, em função da (o):","opts":[["a","Maior possibilidade de ter lucros"],["b","Maior risco de crédito presente no título privado"],["c","Maior risco de crédito presente no título público"],["d","Menor risco de crédito presente no título privado"]],"ans":"b","exp":"Tema: rentabilidade de título privado em relação a título público. O título privado paga mais porque tem maior risco de crédito, já que o emissor privado pode não honrar a dívida, diferentemente do Tesouro. A alternativa B é a correta. A alternativa C está errada, porque o título público tem risco de crédito praticamente nulo.","id":"199544122"},{"n":388,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"112","capn":"Questão 112 (cód. 199544123)","stem":"Seu cliente está montando uma carteira 100% composta com ações. Nesse caso, você explica para ele que essa carteira possui os seguintes riscos, com exceção de:","opts":[["a","Liquidez"],["b","Mercado"],["c","Crédito"],["d","Sistemático"]],"ans":"c","exp":"Tema: riscos de uma carteira de ações. Uma carteira só de ações tem risco de liquidez, de mercado e sistemático, que é um tipo de risco de mercado. O risco de crédito não se aplica, porque as ações não são títulos de dívida de um emissor que possa deixar de pagar. A alternativa C é a exceção, e é a correta.","id":"199544123"},{"n":389,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"113","capn":"Questão 113 (cód. 199544124)","stem":"Sobre o Risco de Mercado, assinale a alternativa correta:","opts":[["a","É impossível fazer com que o mesmo seja igual a zero"],["b","Não está presente nos títulos prefixados"],["c","É menor nos títulos com prazos maiores"],["d","É coberto pelo FGC"]],"ans":"a","exp":"Tema: risco de mercado. Ele não pode ser reduzido a zero, porque é sistemático e atinge o mercado como um todo. A alternativa A é a correta. Títulos prefixados também têm risco de mercado (B), o risco de mercado é maior nos prazos longos (C), e não é coberto pelo FGC (D).","id":"199544124"},{"n":390,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"114","capn":"Questão 114 (cód. 199544125)","stem":"Um determinado investidor possui uma carteira de investimentos com Duration = 900 dias. Deseja diminuir a mesma. Para tanto, deverá:","opts":[["a","Comprar ativos com mais risco"],["b","Comprar ativos com prazo maior que 900 dias"],["c","Comprar ativos com prazo inferior a 900 dias"],["d","Comprar ativos mais defensivos"]],"ans":"c","exp":"Tema: duration e redução de sensibilidade. A duration mede a sensibilidade do preço às variações de juros. Para reduzi-la, o investidor compra ativos com prazo inferior à duration atual, de 900 dias. A alternativa C é a correta. Comprar prazos maiores (B) aumentaria a sensibilidade, e comprar ativos com mais risco (A) ou mais defensivos (D) não se relaciona à duration.","id":"199544125"},{"n":391,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"115","capn":"Questão 115 (cód. 199544126)","stem":"Um investidor comprou uma debênture com cláusula de repactuação anual. Na emissão, havia sido classificada por uma agência de rating como AAA. Na primeira repactuação teve o seu rating alterado para AA. Nesse caso, é de se esperar que:","opts":[["a","Ocorra a cobrança de Imposto de Renda do investidor"],["b","O título sofra uma redução na taxa de juros nessa repactuação"],["c","Não ocorra alteração alguma com a taxa de juros"],["d","O título sofra um aumento na taxa de juros nessa repactuação"]],"ans":"d","exp":"Tema: repactuação de debêntures com queda de rating. Quando o rating cai de AAA para AA, o risco de crédito aumenta, e na repactuação o investidor passa a exigir taxa maior. A alternativa D é a correta. A alternativa B (redução de juros) é o contrário do esperado.","id":"199544126"},{"n":392,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"116","capn":"Questão 116 (cód. 199544127)","stem":"Ao realizar um aporte em um fundo de ações do tipo Small Caps, quais os principais riscos presentes:","opts":[["a","Operacional e Crédito"],["b","Operacional e Liquidez"],["c","Mercado e Crédito"],["d","Mercado e Liquidez"]],"ans":"d","exp":"Tema: riscos de fundo de small caps. Small caps têm risco de mercado, porque oscilam com o mercado, e risco de liquidez, porque têm pouca negociação. A alternativa D é a correta.","id":"199544127"},{"n":393,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"117","capn":"Questão 117 (cód. 199544128)","stem":"Com relação aos segmentos de listagem da B3, analise as afirmações abaixo: I. O nível 2 exige free float de 25% (sem carência) e permite a existência de ações PN II. O Novo Mercado exige free float de 25% e não permite a existência de ações PN III. O Bovespa Mais exige free float de 25% e permite a existência de ações PN Está (ão) correto (s):","opts":[["a","I e II"],["b","I e III"],["c","II e III"],["d","I, II e III"]],"ans":"a","exp":"Tema: segmentos de listagem da B3. Analisando:\n\nI. Correto. O Nível 2 exige free float de 25%, sem carência, e permite ações PN.\n\nII. Correto. O Novo Mercado exige free float de 25% e não permite ações PN.\n\nIII. Errado para a chave. O Bovespa Mais tem regras próprias de free float, e a chave o considera incorreto nesse item.\n\nA alternativa A (I e II) é a correta. Vale conferir a regra do Bovespa Mais no material original, porque a análise do item III depende dela.","id":"199544128"},{"n":394,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"118","capn":"Questão 118 (cód. 199544129)","stem":"As ações Preferenciais (PN) adquirem direito a voto quando:","opts":[["a","A companhia distribui dividendos"],["b","A companhia aumenta o seu capital"],["c","A companhia fica sem distribuir dividendos por três (03) anos seguidos"],["d","A companhia deixa de ter ações negociadas no mercado"]],"ans":"c","exp":"Tema: direito de voto das ações preferenciais. As ações PN adquirem direito de voto quando a companhia fica sem distribuir dividendos por três exercícios seguidos. A alternativa C é a correta. A distribuição de dividendos (A), o aumento de capital (B) e o fechamento do capital (D) não dão esse direito.","id":"199544129"},{"n":395,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"119","capn":"Questão 119 (cód. 199544130)","stem":"Tipo de ADR que não é necessário registro na SEC:","opts":[["a","Nível 1"],["b","Nível 2"],["c","Nível 3"],["d","Nível 144-A"]],"ans":"d","exp":"Tema: ADR nível 144A. Esse tipo de ADR é negociado apenas entre investidores institucionais qualificados e não exige registro na SEC. A alternativa D é a correta. Os ADRs nível 1, 2 e 3 precisam de registro na SEC, em graus diferentes.","id":"199544130"},{"n":396,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"120","capn":"Questão 120 (cód. 199544131)","stem":"Quando uma ação é emitida sem cautela, significa que esse título é:","opts":[["a","Nominativo"],["b","Escritural"],["c","Preferencial"],["d","Endossável"]],"ans":"b","exp":"Tema: ação emitida sem cautela. A ação sem cautela é escritural, ou seja, existe apenas como registro eletrônico na instituição escrituradora. A alternativa B é a correta. Nominativa (A) e preferencial (C) são outras classificações, e endossável (D) se refere a títulos ao portador ou à ordem.","id":"199544131"},{"n":397,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"121","capn":"Questão 121 (cód. 199544132)","stem":"A operação por conta margem, oferecida por uma corretora, pode ser definida como:","opts":[["a","Uma compra com compromisso de venda futura"],["b","Uma compra financiada pela corretora"],["c","Uma forma de diminuir o risco da carteira de ações"],["d","Não é considerado uma forma de alavancagem"]],"ans":"b","exp":"Tema: operação por conta margem. É a compra financiada pela corretora, em que o investidor usa parte de crédito para comprar ações e deixa os títulos como garantia. A alternativa B é a correta. A conta margem é uma forma de alavancagem, e não de diminuir o risco, o que descarta as alternativas C e D.","id":"199544132"},{"n":398,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"122","capn":"Questão 122 (cód. 199544133)","stem":"São segmentos de listagem exclusiva para o mercado de balcão organizado:","opts":[["a","Nível 2 e Novo Mercado"],["b","Nível 1 e Nível 2"],["c","Nível 1 e Bovespa Mais"],["d","Bovespa Mais e Bovespa Mais 2"]],"ans":"d","exp":"Tema: segmentos de listagem exclusivos do mercado de balcão organizado. São o Bovespa Mais e o Bovespa Mais 2. A alternativa D é a correta. Os níveis 1 e 2 e o Novo Mercado são segmentos da bolsa, e o Bovespa Mais é o único dos citados que é exclusivo do balcão organizado.","id":"199544133"},{"n":399,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"123","capn":"Questão 123 (cód. 199544134)","stem":"É uma das características das ações Preferenciais (PN):","opts":[["a","Dar maior proteção ao acionista minoritário"],["b","Ter sempre uma cotação inferior com relação às ações ON"],["c","Ter direito a participação nas decisões da companhia"],["d","Ter preferência no recebimento dos dividendos"]],"ans":"d","exp":"Tema: características das ações PN. A principal vantagem das PN é a preferência no recebimento de dividendos. A alternativa D é a correta. As PN não dão proteção maior ao minoritário (A), não têm cotação sempre inferior às ON (B) e não têm direito de participar das decisões (C), que é próprio das ON.","id":"199544134"},{"n":400,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"124","capn":"Questão 124 (cód. 199544135)","stem":"Com relação ao mercado secundário, assinale a alternativa correta:","opts":[["a","É onde ocorre a liquidez dos títulos e os recursos vão somente para os investidores"],["b","É onde as empresas utilizam para captar recursos"],["c","É onde ocorre a liquidez dos títulos e os recursos vão parte para os investidores e parte para a empresa emissora do título"],["d","As empresas emissoras utilizam esse mercado para realizar as ofertas públicas e captar recursos"]],"ans":"a","exp":"Tema: mercado secundário. É o mercado em que ocorre a liquidez dos títulos, e os recursos vão apenas para os investidores que compram e vendem entre si, e não para a empresa emissora. A alternativa A é a correta. A alternativa C erra ao dizer que parte do dinheiro vai para a emissora, e as alternativas B e D descrevem o mercado primário.","id":"199544135"},{"n":401,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"125","capn":"Questão 125 (cód. 199544136)","stem":"Uma S.A com ações na bolsa, é uma empresa:","opts":[["a","Fechada"],["b","Financeira"],["c","Limitada"],["d","Listada"]],"ans":"d","exp":"Tema: S.A. com ações na bolsa. Uma S.A. com ações negociadas em bolsa é chamada de empresa listada. A alternativa D é a correta. Fechada (A) é a companhia sem ações negociadas, e as demais classificações não se aplicam.","id":"199544136"},{"n":402,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"126","capn":"Questão 126 (cód. 199544137)","stem":"Principais ativos emitidos por uma S.A","opts":[["a","Títulos de Curto Prazo e Debêntures"],["b","Títulos de Longo Prazo e Debêntures"],["c","Ações, Commercial Paper e Debêntures"],["d","Títulos de Curto Prazo e Ações"]],"ans":"c","exp":"Tema: principais títulos emitidos por S.A. As S.A. emitem ações, commercial papers e debêntures. A alternativa C é a correta. Títulos de curto e longo prazo (A, B e D) são classificações genéricas, e não os títulos emitidos pela companhia.","id":"199544137"},{"n":403,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"127","capn":"Questão 127 (cód. 199544138)","stem":"Qualquer pode requerer o fechamento do seu capital através de uma , operação na qual irá as suas ações e o dinheiro irá para os . Preenche corretamente as lacunas:","opts":[["a","S.A | OPA | Comprar | Acionistas"],["b","Instituição Financeira | OPA | Comprar | Acionistas"],["c","S.A | IPO | Vender | Acionistas"],["d","Instituição Financeira | IPO | Vender | Investidores"]],"ans":"a","exp":"Tema: fechamento de capital. Qualquer acionista pode requerer o fechamento do capital, por meio de uma oferta pública de aquisição de ações (OPA), na qual a companhia compra as ações, e o dinheiro vai para os acionistas que venderam. A alternativa A é a correta. A alternativa C fala em IPO, que é abertura de capital, e as demais trocam o agente ou a operação.","id":"199544138"},{"n":404,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"128","capn":"Questão 128 (cód. 199544139)","stem":"Os agentes underwriters são:","opts":[["a","Instituições financeiras ou não financeiras especializadas em coordenar processos de emissões de valores mobiliários"],["b","Instituições não financeiras especializadas em coordenar processos de emissões de valores mobiliários"],["c","Instituições financeiras especializadas em coordenar processos de emissões de títulos e valores mobiliários"],["d","Instituições financeiras que emitem ações e valores mobiliários no mercado primário"]],"ans":"c","exp":"Tema: underwriters. São instituições financeiras especializadas em coordenar processos de emissão de títulos e valores mobiliários. A alternativa C é a correta. A alternativa A inclui não financeiras, o que não é a regra, e a alternativa D trata da emissão em si, e não do papel do underwriter.","id":"199544139"},{"n":405,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"129","capn":"Questão 129 (cód. 199544140)","stem":"Sobre o processo conhecido como BookBuilding no mercado de capitais:","opts":[["a","A empresa emissora define o preço de emissão do título sempre no teto (preço máximo) do bookbuilding"],["b","É um processo de consulta de intenção de compra e é sigiloso, onde somente a empresa emissora tem acesso aos dados"],["c","Pode ser realizado somente com ativos de renda variável"],["d","É utilizado para conhecer as expectativas dos investidores em relação ao ativo que será emitido"]],"ans":"d","exp":"Tema: bookbuilding. É o processo de consulta de intenções de compra, em que se coleta a demanda e o preço que os investidores estão dispostos a pagar, para definir o preço da emissão. A alternativa D é a correta. A alternativa B erra ao dizer que o processo é sigiloso e restrito à emissora, e a alternativa C limita o processo à renda variável, o que também não é verdadeiro.","id":"199544140"},{"n":406,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"130","capn":"Questão 130 (cód. 199544141)","stem":"Com relação à custódia fungível, assinale a alternativa correta:","opts":[["a","É aquela onde os títulos recebidos serão exatamente os mesmos que foram depositados"],["b","É aquela onde os títulos recebidos podem não ser exatamente os mesmos que foram depositados"],["c","Tipo de custódia que é utilizado somente nos Estados Unidos"],["d","É aquela onde os títulos recebidos serão de outra companhia emissora"]],"ans":"b","exp":"Tema: custódia fungível. Na custódia fungível, os títulos recebidos podem não ser exatamente os mesmos que foram depositados, desde que tenham as mesmas características. A alternativa B é a correta. A alternativa A descreve a custódia não fungível, e as alternativas C e D não correspondem ao conceito.","id":"199544141"},{"n":407,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"131","capn":"Questão 131 (cód. 199544142)","stem":"São ambientes de negociação do mercado secundário:","opts":[["a","Bolsa de Valores e Mercado Primário"],["b","Mercado Primário e Mercado Secundário"],["c","Mercado de Balcão e Mercado Primário"],["d","Bolsa de Valores e Mercado de Balcão Organizado"]],"ans":"d","exp":"Tema: ambientes do mercado secundário. Os ambientes de negociação do mercado secundário são a bolsa de valores e o mercado de balcão organizado. A alternativa D é a correta. O mercado primário (A, B e C) é o da emissão, e não da negociação entre investidores.","id":"199544142"},{"n":408,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"132","capn":"Questão 132 (cód. 199544143)","stem":"Em um tipo de sistema de liquidação “Book Entry”:","opts":[["a","Ocorre a transferência e liquidação dos ativos somente por meio de registro eletrônico"],["b","Ocorre a transferência e liquidação dos ativos por meio físico ou eletrônico"],["c","Ocorre a transferência e liquidação dos ativos somente por meio físico"],["d","É uma forma antiga de transferência e liquidação onde os dois participantes do negócio precisam estar fisicamente no local"]],"ans":"a","exp":"Tema: sistema de liquidação book entry. Nele, a transferência e a liquidação dos ativos ocorrem somente por registro eletrônico, sem movimentação física. A alternativa A é a correta. As demais descrevem transferência física, que é a forma antiga, em que a entrega do certificado é feita em mãos.","id":"199544143"},{"n":409,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"133","capn":"Questão 133 (cód. 199544144)","stem":"Ordem discricionária é aquela que:","opts":[["a","Estabelece um limite ao preço de negociação"],["b","Envolve obrigatoriamente uma operação de compra e outra de venda"],["c","Não possui qualquer limitação quanto a preço"],["d","É gerada por administradores de carteira ou representantes de mais de um investidor"]],"ans":"d","exp":"Tema: ordem discricionária. É a ordem dada por um administrador de carteira ou por quem representa mais de um investidor, em que cabe ao ordenante escolher as condições e, depois, os comitentes. A alternativa D é a correta. As alternativas A e C descrevem outras ordens, como a limitada e a de mercado, e a B descreve a ordem casada.","id":"199544144"},{"n":410,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"134","capn":"Questão 134 (cód. 199544145)","stem":"Assinale a alternativa correta sobre Debêntures:","opts":[["a","Dão direito a participação nas decisões da companhia emissora"],["b","São títulos de médio/longo prazo emitidos por Sociedades Anônimas abertas ou fechadas e representam uma dívida da companhia emissora e estão cobertos pelo FGC"],["c","São títulos de médio/longo prazo emitidos por Sociedades Anônimas abertas ou fechadas e representam uma dívida da companhia emissora"],["d","São títulos de curto/médio prazo emitidos por Sociedades Anônimas abertas ou fechadas e representam uma dívida da companhia emissora"]],"ans":"c","exp":"Tema: debêntures. São títulos de médio e longo prazo, emitidos por sociedades anônimas abertas ou fechadas, que representam dívida da companhia. A alternativa C é a correta. A alternativa A confere direito de voto, que não é característica da debênture. A alternativa B adiciona cobertura do FGC, que não se aplica às debêntures.","id":"199544145"},{"n":411,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"135","capn":"Questão 135 (cód. 199544146)","stem":"Sobre as operações Ex-Pit, é correto afirmar:","opts":[["a","Não possibilitam a precificação de posições a termo por meio de preços futuros"],["b","Reduzem a liquidez do mercado a termo"],["c","São submetidas à interferência do mercado"],["d","Constituem negócios realizados fora do pit de negociação ou pregão, de uma bolsa"]],"ans":"d","exp":"Tema: operações ex-pit. São negócios realizados fora do pit de negociação ou do pregão de uma bolsa. A alternativa D é a correta. As demais alternativas trazem características que não definem o ex-pit, como interferência de mercado (C), que é o contrário do que ocorre.","id":"199544146"},{"n":412,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"136","capn":"Questão 136 (cód. 199544147)","stem":"Um “commercial paper” é um título, emitido por sociedade financeira ou não financeira:","opts":[["a","negociável, representativo de uma dívida de curto prazo."],["b","não negociável, representativo de uma dívida de curto prazo."],["c","não negociável, representativo de uma dívida de longo prazo."],["d","negociável, representativo de uma dívida de longo prazo."]],"ans":"a","exp":"Tema: commercial paper. É um título negociável, de curto prazo, emitido por sociedades financeiras ou não financeiras para captar recursos rapidamente. A alternativa A é a correta.","id":"199544147"},{"n":413,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"137","capn":"Questão 137 (cód. 199544148)","stem":"As debêntures são classificadas quanto a classe/tipo:","opts":[["a","simples, não permutáveis e não conversíveis."],["b","simples, conversíveis em ações ou permutáveis."],["c","simples, permutáveis e diferenciadas."],["d","simples, não conversíveis ou de crédito."]],"ans":"b","exp":"Tema: classificação das debêntures. Quanto à classe e ao tipo, as debêntures são simples, conversíveis em ações ou permutáveis. A alternativa B é a correta. As demais misturam classificações que não existem, como debêntures diferenciadas ou de crédito.","id":"199544148"},{"n":414,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"138","capn":"Questão 138 (cód. 199544149)","stem":"Trata-se de uma informação que deve constar, obrigatoriamente, na escritura de uma debênture:","opts":[["a","A informação de intervenção de um Agente Fiduciário"],["b","A classificação de risco concedida por uma agência de Rating de Crédito"],["c","Direitos iguais para os detentores de todas as debêntures, independente da série que pertencer"],["d","Informação de que o Agente Fiduciário irá honrar o risco de não pagamento por parte do emissor da debênture"]],"ans":"a","exp":"Tema: informação obrigatória na escritura de debênture. A presença de um agente fiduciário, que representa os debenturistas, é exigida na escritura. A alternativa A é a correta. As demais exigências ou garantias citadas (rating e garantia de pagamento pelo agente) não são obrigatórias na escritura, e o agente não honra o risco de crédito.","id":"199544149"},{"n":415,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"139","capn":"Questão 139 (cód. 199544150)","stem":"Uma S.A não financeira está necessitando de recursos para capital de giro. Uma opção para captar recursos de forma rápida, seria:","opts":[["a","Ações"],["b","CDB"],["c","Notas Promissórias"],["d","LCI"]],"ans":"c","exp":"Tema: captação rápida de recursos para capital de giro. A nota promissória (commercial paper) é o instrumento de captação de curto prazo mais rápido para empresas não financeiras. A alternativa C é a correta. Ações (A) levam tempo para emissão e diluem o controle, CDB (B) é de instituição financeira, e LCI (D) é de financiamento imobiliário.","id":"199544150"},{"n":416,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"140","capn":"Questão 140 (cód. 199544151)","stem":"Uma debênture conversível é aquela que:","opts":[["a","Pode ser convertida em dinheiro a qualquer momento"],["b","Pode ser recomprada pelo emissor"],["c","Pode ser convertida em ações na data do seu resgate"],["d","Pode ser convertida em ações a qualquer momento"]],"ans":"c","exp":"Tema: debênture conversível. Ela pode ser convertida em ações nas datas e condições definidas na escritura, e não em qualquer momento. A chave indica C (conversão na data do resgate), que é uma das possibilidades previstas. A alternativa D (conversão a qualquer momento) não é a regra habitual. Vale conferir a escritura de emissão, porque as datas de conversão são definidas caso a caso.","id":"199544151"},{"n":417,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"141","capn":"Questão 141 (cód. 199544152)","stem":"Responsável pelo recolhimento do Imposto de Renda no mercado de ações:","opts":[["a","Próprio investidor"],["b","Bolsa de valores"],["c","Corretora de valores"],["d","Administrador"]],"ans":"a","exp":"Tema: responsável pelo IR em operações de ações. Nas vendas de ações, o investidor pessoa física apura e paga o imposto por DARF, quando o ganho ultrapassa a isenção. A alternativa A é a correta. A corretora retém apenas o IRRF na fonte, de 0,005% sobre a venda. A bolsa (B) e o administrador (D) não são responsáveis por esse recolhimento, e a alternativa C tem papel de retenção, não de recolhimento final.","id":"199544152"},{"n":418,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"142","capn":"Questão 142 (cód. 199544153)","stem":"Quando um cliente faz uma operação com lucro, no mercado de ações, não day trade, acima de R$ 20 mil, essa operação será tributada com qual alíquota de I.R:","opts":[["a","20%"],["b","15%"],["c","Dependo do prazo Isento"]],"ans":"b","exp":"Tema: IR em ações não day trade com lucro acima de R$ 20 mil no mês. Nessa situação, o ganho é tributado a 15%, e a isenção de R$ 20 mil não se aplica, porque as vendas superaram esse valor. A alternativa B é a correta. A alíquota de 20% (A) é para day trade em alguns casos, e a alternativa C (dependo do prazo) não se aplica a ações.","id":"199544153"},{"n":419,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"143","capn":"Questão 143 (cód. 199544154)","stem":"Sobre debêntures, assinale a alternativa correta:","opts":[["a","Dá direito a voto para os detentores nas assembleias da empresa"],["b","Possui participação nos lucros da companhia emissora"],["c","Em nenhuma hipótese pode ser convertida em ações"],["d","Pode ter sua rentabilidade repactuada, se essa cláusula estiver na escritura"]],"ans":"d","exp":"Tema: debêntures e repactuação. A repactuação é uma cláusula que permite rever a taxa e está prevista na escritura da emissão. A alternativa D é a correta. Debêntures não dão direito a voto (A) e não participam dos lucros como ações (B), e a conversão em ações depende da modalidade (C), não sendo impossível em todos os casos.","id":"199544154"},{"n":420,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"144","capn":"Questão 144 (cód. 199544155)","stem":"O dividendo é a divisão do lucro de uma companhia. E é um direito do qual o acionista:","opts":[["a","Pode ser privado através de assembleia"],["b","Pode ser privado através de determinação do presidente da companhia"],["c","Pode ser privado através do estatuto da companhia"],["d","Não pode ser privado"]],"ans":"d","exp":"Tema: direito ao dividendo. O dividendo é um direito essencial do acionista, e ele não pode ser privado por assembleia, presidente ou estatuto, porque isso violaria o direito de participar dos lucros. A alternativa D é a correta.","id":"199544155"},{"n":421,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"145","capn":"Questão 145 (cód. 199544156)","stem":"\"Um determinado investidor fez uma aplicação em debêntures pelo prazo de 181 dias e obteve lucro de R$ 421 mil. Com relação à tributação, analise os itens abaixo: I. A Instituição Emissora irá reter o valor do imposto devido II. A alíquota do imposto de renda é de 15% III. A base de cálculo para cobrança do I.R é o rendimento da operação. Está (ão) correto (s):","opts":[["a","I e II"],["b","I e III"],["c","Apenas I"],["d","Apenas III"]],"ans":"b","exp":"Tema: IR sobre debêntures aplicadas por 181 dias. Analisando:\n\nI. Correto. A instituição emissora ou financeira que faz a custódia retém o IR na fonte.\n\nII. Errado. Para aplicações de 181 a 360 dias, a alíquota regressiva é de 20%, e não de 15%. A alíquota de 15% vale só acima de 720 dias.\n\nIII. Correto. A base de cálculo é o rendimento da operação, ou seja, o ganho sobre o valor aplicado.\n\nA chave indica B (I e III), que é coerente com a análise.","id":"199544156"},{"n":422,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"146","capn":"Questão 146 (cód. 199544)","stem":"São ações que dão direito a voto nas assembleias da companhia:","opts":[["a","Ordinárias"],["b","Preferenciais"],["c","Subordinadas"],["d","De fruição"]],"ans":"a","exp":"Tema: ações com direito de voto. As ações ordinárias (ON) dão direito a voto nas assembleias. A alternativa A é a correta. As preferenciais (B) não votam, salvo nas situações previstas na lei, e as subordinadas (C) e de fruição (D) não são as classes que dão voto.","id":"199544"},{"n":423,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"147","capn":"Questão 147 (cód. 199544158)","stem":"Sobre o Juros Sobre Capital Próprio – JSCP, assinale a alternativa correta:","opts":[["a","São isentos de Imposto de Renda e se originam em lucros retidos"],["b","Se originam de lucros retidos e possuem I.R conforme tabela regressiva do I.R"],["c","São os lucros da companhia sendo distribuídos e são isentos de I.R"],["d","Se originam de lucros retidos e possuem I.R com alíquota única de 15%"]],"ans":"d","exp":"Tema: juros sobre capital próprio (JSCP). O JSCP é uma forma de remunerar o capital próprio, com incidência de IR na fonte de 15%, alíquota única. A alternativa D é a correta. O JSCP não é isento (A e C), e a tabela regressiva (B) não se aplica a ele.","id":"199544158"},{"n":424,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"148","capn":"Questão 148 (cód. 199544159)","stem":"Com relação ao Mercado Primário, assinale a alternativa correta:","opts":[["a","É onde são emitidos títulos pela primeira vez e os recursos captados vão para os acionistas"],["b","É onde são emitidos títulos pela primeira vez e os recursos captados vão para a empresa emissora"],["c","É onde são comercializados títulos já existentes e os recursos captados vão para a empresa"],["d","É onde são comercializados títulos já existentes e os recursos captados vão para os atuais acionistas"]],"ans":"b","exp":"Tema: mercado primário. É onde os títulos são emitidos pela primeira vez, e os recursos captados vão para a empresa emissora. A alternativa B é a correta. A alternativa A leva os recursos aos acionistas, o que não é a regra, e as alternativas C e D descrevem o mercado secundário.","id":"199544159"},{"n":425,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"149","capn":"Questão 149 (cód. 199544160)","stem":"Responsável pelo recolhimento do I.R na fonte nas operações com ações:","opts":[["a","Próprio investidor"],["b","Bolsa de valores"],["c","Corretora de Valores"],["d","Administrador do fundo"]],"ans":"c","exp":"Tema: responsável pelo recolhimento do IR na fonte em ações. A corretora de valores retém o IRRF na fonte nas operações com ações. A alternativa C é a correta. O investidor (A) declara e paga o imposto restante, e a bolsa (B) e o administrador (D) não fazem essa retenção nas operações diretas.","id":"199544160"},{"n":426,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"150","capn":"Questão 150 (cód. 199544161)","stem":"Nas operações com ações do tipo Day Trade, qual é a alíquota do Imposto de Renda total e na fonte, respectivamente:","opts":[["a","20% e 0,005%"],["b","15% e 0,005%"],["c","15% e 1%"],["d","20% e 1%"]],"ans":"d","exp":"Tema: alíquotas de day trade. Nas operações de day trade com ações, o IR total é de 20% sobre o lucro, e o IRRF na fonte é de 1% sobre o lucro. A alternativa D é a correta. A alternativa A (0,005%) é a alíquota de IRRF das operações comuns, e a alternativa C tem 15%, que é a alíquota de operações não day trade.","id":"199544161"},{"n":427,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"151","capn":"Questão 151 (cód. 199544162)","stem":"Uma empresa do setor de construção de rodovias quer captar recursos através de dívida e deseja um longo prazo para ficar com os recursos, deveria optar por:","opts":[["a","Debêntures"],["b","Ações"],["c","Notas Promissórias"],["d","CDB"]],"ans":"a","exp":"Tema: captação de longo prazo por dívida. As debêntures são títulos de dívida de médio e longo prazo, emitidos por companhias para captar recursos, e por isso são a opção indicada para a construtora. A alternativa A é a correta. Ações (B) são capital, não dívida, e as notas promissórias (C) e o CDB (D) são de curto prazo ou de instituições financeiras.","id":"199544162"},{"n":428,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"152","capn":"Questão 152 (cód. 199544163)","stem":"Ganho de Capital é quando:","opts":[["a","Um investidor recebe dividendos no seu investimento"],["b","Um investidor recebe juros sobre capital próprio no seu investimento"],["c","Um investidor vende uma ação por um valor superior ao que comprou"],["d","Um investidor vende uma ação por um valor inferior ao que comprou"]],"ans":"c","exp":"Tema: ganho de capital. É o lucro obtido quando o investidor vende um ativo por valor superior ao preço de compra. A alternativa C é a correta. Dividendos (A) e JSCP (B) são formas de remuneração, e a venda abaixo do custo (D) é perda de capital.","id":"199544163"},{"n":429,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"153","capn":"Questão 153 (cód. 199544164)","stem":"Período de uma oferta pública em que se coleta as intenções de aquisição de um determinado título e também o preço que esses interessados estão dispostos a pagar:","opts":[["a","Front Runner"],["b","Chinese Wall"],["c","Bookbuilding"],["d","Churning"]],"ans":"c","exp":"Tema: bookbuilding. É o processo de coleta de intenções de compra e dos preços que os interessados estão dispostos a pagar, em uma oferta pública. A alternativa C é a correta. Front runner (A) é operar antes de uma ordem de cliente, chinese wall (B) é segregação de atividades, e churning (D) é giro excessivo da carteira.","id":"199544164"},{"n":430,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"154","capn":"Questão 154 (cód. 199544165)","stem":"Um investidor pessoa física fez a compra de 800 ações de uma empresa pelo valor total de R$ 30.000. Alguns dias depois ele vende metade da posição comprada pelo valor de R$ 23.000. Nesse caso, qual será o I.R retido na fonte e o valor a ser pago via DARF (Considere R$ 100 de corretagem na venda):","opts":[["a","R$ 1,20 e R$ 1.200,00"],["b","R$ 0,39 e R$ 1.200,00"],["c","R$ 0,40 e R$ 1183,60"],["d","R$ 1,15 e R$ 1.183,85"]],"ans":"d","exp":"Tema: IR retido e IR devido em venda parcial de ações. O investidor comprou 800 ações por R$ 30.000, ou seja, R$ 37,50 cada. Vendeu 400 por R$ 23.000, cujo custo é de 400 × R$ 37,50 = R$ 15.000. O ganho bruto é de R$ 8.000, e com a corretagem de R$ 100 a base fica em R$ 7.900. O IRRF retido na fonte é de 0,005% da venda: 0,00005 × 23.000 = R$ 1,15. O IR devido, a 15%, é de 0,15 × 7.900 = R$ 1.185, e descontado o IRRF, o DARF é de R$ 1.185 − R$ 1,15 = R$ 1.183,85. A alternativa D é a correta.","id":"199544165"},{"n":431,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"155","capn":"Questão 155 (cód. 199544166)","stem":"Em uma emissão de debêntures ou notas promissórias, é função de uma agência classificadora de risco:","opts":[["a","Garantir que os pagamentos serão realizados pelo emissor"],["b","Conceder uma nota de crédito, que significa a possibilidade de o emissor não honrar com o seu compromisso"],["c","Ser o representante do emissor na oferta pública"],["d","Ser o representante dos investidores em uma oferta pública"]],"ans":"b","exp":"Tema: função da agência de classificação de risco. Ela atribui uma nota de crédito, que indica a probabilidade de o emissor cumprir suas obrigações, mas não garante o pagamento. A alternativa B é a correta. A agência não garante nem representa emissor ou investidores, o que descarta as alternativas A, C e D.","id":"199544166"},{"n":432,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"156","capn":"Questão 156 (cód. 199544167)","stem":"A ação Preferencial (PN) possui preferência no recebimento de dividendos de uma companhia. Essa ação, pode adquirir o direito a voto no caso de:","opts":[["a","A companhia der prejuízo em um determinado exercício"],["b","Ser uma ação conversível"],["c","A companhia ficar 3 exercícios seguidos sem distribuir dividendos"],["d","A companhia fechar seu capital"]],"ans":"c","exp":"Tema: direito de voto das preferenciais. A PN passa a ter direito de voto quando a companhia fica três exercícios seguidos sem pagar dividendos. A alternativa C é a correta. Prejuízo (A), conversibilidade (B) e fechamento de capital (D) não dão esse direito.","id":"199544167"},{"n":433,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"157","capn":"Questão 157 (cód. 199544168)","stem":"Em uma Bonificação de Ações:","opts":[["a","O acionista tem o direito de comprar um número de ações"],["b","O acionista recebe sem custo um número de ações"],["c","A empresa está captando novos recursos"],["d","O acionista continua com o mesmo número de ações"]],"ans":"b","exp":"Tema: bonificação de ações. Na bonificação, o acionista recebe, sem custo, novas ações proporcionais às que já possui. A alternativa B é a correta. O direito de comprar (A) é da subscrição, e a bonificação não capta recursos (C) nem mantém a quantidade de ações (D).","id":"199544168"},{"n":434,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"158","capn":"Questão 158 (cód. 199544170)","stem":"Quanto ao prazo máximo de emissão das Notas Promissórias – Commercial Papers, assinale a alternativa correta:","opts":[["a","180 dias (S.A Fechada) e 360 dias (S.A Aberta)"],["b","360 dias (S.A Fechada e Aberta)"],["c","180 dias (S.A Fechada e Aberta)"],["d","180 dias (S.A Aberta) e 360 dias (S.A Fechada)"]],"ans":"b","exp":"Tema: prazo máximo das notas promissórias (commercial papers). O prazo máximo é de 360 dias, tanto para S.A. aberta quanto para S.A. fechada. A alternativa B é a correta. As demais alternativas trazem prazo de 180 dias, que não é o limite.","id":"199544170"},{"n":435,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"159","capn":"Questão 159 (cód. 199544171)","stem":"Segmento de listagem que conta com 100% de Tag Along para ações Ordinárias e Preferenciais:","opts":[["a","Nível 2"],["b","Novo Mercado"],["c","Nível 1"],["d","Tradicional"]],"ans":"a","exp":"Tema: segmento com 100% de Tag Along para ON e PN. O Nível 2 exige que todas as ações, ON e PN, tenham Tag Along de 100%. A alternativa A é a correta. O Novo Mercado (B) exige 100% apenas para ON, e o Nível 1 (C) tem 80% para ON.","id":"199544171"},{"n":436,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"160","capn":"Questão 160 (cód. 199544172)","stem":"Um American Depositary Receipt - ADR:","opts":[["a","É uma ação negociada nos Estados Unidos, cotada em dólares de uma empresa não americana"],["b","É um título negociado nos Estados Unidos, cotado em dólares e lastreado em ações de uma empresa não americana"],["c","É um título negociado nos Estados Unidos, cotado em reais e lastreado em ações de uma empresa não americana"],["d","É um título negociado no Brasil, cotado em reais e lastreado em ações de uma empresa americana"]],"ans":"b","exp":"Tema: ADR. É um título negociado nos Estados Unidos, cotado em dólares, lastreado em ações de empresas não americanas. A alternativa B é a correta. A alternativa A descreve uma ação, e não o recibo, e as alternativas C e D trocam a moeda ou o local de negociação.","id":"199544172"},{"n":437,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"161","capn":"Questão 161 (cód. 199544173)","stem":"Seu cliente teve perdas em operações do tipo day trade com ações. Nesse caso, a compensação desse prejuízo para calcular o imposto de renda pode ser feito?","opts":[["a","Sim, desde que com operações somente realizadas com day trade"],["b","Sim, podendo ser compensada com operações day trade e também operações não day trade"],["c","Não podem ser compensadas"],["d","Sim, podem ser compensadas com qualquer ganho no mercado financeiro"]],"ans":"a","exp":"Tema: compensação de prejuízo em day trade. O prejuízo de day trade só pode ser compensado com ganhos de day trade. A alternativa A é a correta. Ver a questão 2, que trata do mesmo conceito.","id":"199544173"},{"n":438,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"162","capn":"Questão 162 (cód. 199544174)","stem":"Sobre os BDR’s, assinale a alternativa correta:","opts":[["a","É um recibo de ação brasileiro, lastreado em empresa do Brasil e negociado nos Estados Unidos"],["b","É uma ação brasileira de uma companhia que está fora do Brasil"],["c","É um título negociado no Brasil, cotado em dólares e lastreado em ação de uma empresa não brasileira"],["d","É um título negociado no Brasil, cotado em reais e lastreado em ação de uma empresa não brasileira"]],"ans":"d","exp":"Tema: BDR. É um título negociado no Brasil, cotado em reais e lastreado em ações de empresas estrangeiras. A alternativa D é a correta. Ver a questão 3, com o mesmo conceito.","id":"199544174"},{"n":439,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"163","capn":"Questão 163 (cód. 199544175)","stem":"Segmento de listagem de Governança Corporativa que exige emissão de somente ações ordinárias:","opts":[["a","Nível 2"],["b","Novo Mercado"],["c","Nível 1"],["d","Tradicional"]],"ans":"b","exp":"Tema: segmento de governança que exige somente ações ON. É o Novo Mercado. A alternativa B é a correta. Ver a questão 4.","id":"199544175"},{"n":440,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"164","capn":"Questão 164 (cód. 199544176)","stem":"Ordem limitada é aquela que:","opts":[["a","Especifica somente ativo e quantidade e a execução fica a critério da corretora"],["b","É executada somente a preço igual ou melhor ao especificado pelo cliente"],["c","Realizada por um administrador de carteira em nome de vários clientes"],["d","Especifica o preço do ativo a partir do qual a ordem deve ser executada"]],"ans":"b","exp":"Tema: ordem limitada. É aquela executada somente a preço igual ou melhor que o especificado pelo cliente. A alternativa B é a correta. A alternativa A descreve a ordem administrada, a C a ordem discricionária, e a D a ordem stop.","id":"199544176"},{"n":441,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"165","capn":"Questão 165 (cód. 199544177)","stem":"Ordem casada é aquela que:","opts":[["a","Especifica somente ativo e quantidade e a execução fica a critério da corretora"],["b","É executada no momento do envio da mesma"],["c","Realizada por um administrador de carteira em nome de vários clientes"],["d","Está vinculada à execução de uma outra ordem"]],"ans":"d","exp":"Tema: ordem casada. É a ordem vinculada à execução de outra ordem do cliente. A alternativa D é a correta. A alternativa A descreve a administrada, a B a de mercado e a C a discricionária.","id":"199544177"},{"n":442,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"166","capn":"Questão 166 (cód. 199544178)","stem":"A apregoação por leilão:","opts":[["a","É realizada com destaque das demais, sendo obrigatório mencionar ativo, lote e preço"],["b","É aquela onde é permitida a interferência do vendedor e comprador a melhor preço"],["c","É realizada com destaque das demais, sendo permitida a interferência para melhor preço do comprador"],["d","É aquela que se demonstra o interesse em comprar ou vender um ativo, inserindo a oferta no sistema"]],"ans":"a","exp":"Tema: apregoação por leilão. A chave indica A, que descreve a apregoação com destaque das demais e a obrigação de informar ativo, lote e preço. Essa definição se aproxima da apregoação por oferta, que é a forma mais específica, e a alternativa B é a que descreve o leilão comum. A definição do enunciado é imprecisa para a categoria de leilão. Vale conferir o material original.","id":"199544178"},{"n":443,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"167","capn":"Questão 167 (cód. 199544179)","stem":"A apregoação por leilão comum:","opts":[["a","É realizada com destaque das demais, sendo obrigatório mencionar ativo, lote e preço"],["b","É realizada com destaque das demais, sendo permitida a interferência para melhor preço do comprador"],["c","É aquela onde é permitida a interferência do vendedor e comprador a melhor preço"],["d","É aquela onde o operador se propõe a comprar e vender um mesmo ativo para diversos clientes"]],"ans":"c","exp":"Tema: leilão comum. É aquele em que é permitida a interferência de compradores e vendedores para melhor preço. A alternativa C é a correta. A alternativa B restringe a interferência ao comprador, o que não é a regra, e as alternativas A e D descrevem outras formas de apregoação.","id":"199544179"},{"n":444,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"168","capn":"Questão 168 (cód. 199544180)","stem":"Sobre a oferta a mercado, assinale a alternativa correta:","opts":[["a","É executada por preço igual ou melhor que o especificado pelo cliente"],["b","É disparada a partir de um gatilho"],["c","É executada ao melhor limite do preço oposto no mercado"],["d","É executada no preço de abertura"]],"ans":"c","exp":"Tema: ordem a mercado. É executada ao melhor limite de preço oposto no mercado no momento do registro. A alternativa C é a correta. A alternativa A descreve a ordem limitada, a B a ordem stop e a D a ordem ao preço de abertura.","id":"199544180"},{"n":445,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"169","capn":"Questão 169 (cód. 199544181)","stem":"\"Analise as afirmações abaixo sobre a operação com aluguel de ações: I. O direito a voto fica com o tomador do aluguel II. Quem paga o aluguel é o doador III. Os proventos ficam com o tomador Está (ão) correto (s) o que se afirma em:","opts":[["a","I e III"],["b","I e II"],["c","II e III"],["d","Apenas I"]],"ans":"d","exp":"Tema: aluguel de ações. Analisando:\n\nI. Correto. O direito de voto fica com o tomador do aluguel, que tem a posse das ações.\n\nII. Errado. Quem paga o aluguel é o tomador, e não o doador.\n\nIII. Errado. Os proventos são pagos ao doador, que é o dono das ações, e não ficam com o tomador.\n\nA alternativa D (apenas I) é a correta.","id":"199544181"},{"n":446,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"170","capn":"Questão 170 (cód. 199544229)","stem":"Em uma operação de securitização de recebíveis, uma Sociedade de Propósito Específico (SPE):","opts":[["a","capta recursos por meio da emissão de cotasparte, com o objetivo de adquirir direitos creditórios e outros ativos."],["b","segrega o risco de crédito dos originadores de recebíveis o que aumento o risco para os compradores de ativos emitidos pela SPE."],["c","vende recebíveis com o objetivo de captar recursos para a compra de debêntures."],["d","capta recurso, por meio da emissão de títulos de crédito, visando adquirir direitos creditórios."]],"ans":"d","exp":"Tema: SPE na securitização de recebíveis. A SPE é a sociedade que capta recursos por meio da emissão de títulos de crédito, para adquirir direitos creditórios. A alternativa D é a correta. A alternativa A fala em emissão de cotas, o que é típico de fundos, e as alternativas B e C descrevem efeitos ou operações diferentes.","id":"199544229"},{"n":447,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"171","capn":"Questão 171 (cód. 199544230)","stem":"Em um processo de securitização, os créditos devem estar no balanço da:","opts":[["a","Empresa originária dos créditos"],["b","Sociedade de Propósito Específico (SPE)"],["c","Pool de investidores"],["d","Devedores do título de crédito"]],"ans":"b","exp":"Tema: onde ficam os créditos na securitização. Os créditos são transferidos ao patrimônio da SPE, que os detém no balanço, e o risco de crédito fica segregado. A alternativa B é a correta. A empresa originária (A) já não é a dona dos créditos após a cessão.","id":"199544230"},{"n":448,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"172","capn":"Questão 172 (cód. 199544231)","stem":"Título lastreado em recebíveis imobiliários e com isenção de imposto de renda para pessoa física:","opts":[["a","CRA"],["b","CRI"],["c","CDB"],["d","Poupança"]],"ans":"b","exp":"Tema: título lastreado em recebíveis imobiliários com isenção de IR para pessoa física. É o CRI, o Certificado de Recebíveis Imobiliários, que tem a isenção. A alternativa B é a correta. O CRA (A) é do agronegócio. O CDB (C) é tributado, e a poupança (D) é outro produto.","id":"199544231"},{"n":449,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"173","capn":"Questão 173 (cód. 199544232)","stem":"Em um processo de securitização de recebíveis o pagamento do fluxo financeiro originário é pago para o (a):","opts":[["a","Investidor"],["b","Securitizadora"],["c","Emissor da Dívida"],["d","Devedor"]],"ans":"b","exp":"Tema: destino do fluxo de pagamento na securitização. O fluxo financeiro dos recebíveis é pago à securitizadora, que o repassa aos investidores. A alternativa B é a correta.","id":"199544232"},{"n":450,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"174","capn":"Questão 174 (cód. 199544233)","stem":"Instituição financeira responsável pela emissão de Certificado de Recebíveis Imobiliários:","opts":[["a","Banco Múltiplo"],["b","Securitizadora"],["c","Banco de Investimento"],["d","S.A não financeira"]],"ans":"b","exp":"Tema: emissor de CRI. A securitizadora é a instituição que emite o Certificado de Recebíveis Imobiliários. A alternativa B é a correta.","id":"199544233"},{"n":451,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"175","capn":"Questão 175 (cód. 199544234)","stem":"Para um investidor pessoa física que busca vantagem fiscal e título lastreado em recebíveis, você deveria indicar:","opts":[["a","FIDC"],["b","CRI"],["c","Poupança"],["d","Fundo de Ações"]],"ans":"b","exp":"Tema: investidor pessoa física que busca vantagem fiscal com recebíveis. O CRI tem isenção de IR para pessoa física, e por isso é a indicação adequada. A alternativa B é a correta. O FIDC (A) não é isento, a poupança (C) é outro produto e o fundo de ações (D) não é lastreado em recebíveis.","id":"199544234"},{"n":452,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"176","capn":"Questão 176 (cód. 199544235)","stem":"A qualidade de cotista caracteriza-se pelo(a):","opts":[["a","Pelo cadastramento do cotista no Clube"],["b","Inscrição do nome do titular no registro de cotistas do clube"],["c","Pelo envio da documentação do cotista para o clube"],["d","Pelo aporte financeiro no clube"]],"ans":"b","exp":"Tema: qualidade de cotista em clube. Ela se caracteriza pela inscrição do nome do titular no registro de cotistas do clube. A alternativa B é a correta. O cadastro ou o envio de documentos (A e C) são etapas, e o aporte (D) não define a condição de cotista.","id":"199544235"},{"n":453,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"177","capn":"Questão 177 (cód. 199544237)","stem":"O montante que exceder 67% do patrimônio líquido do Clube de Investimento pode ser aplicado em outros valores mobiliários de emissão de companhias abertas, sendo vedado o lançamento de:","opts":[["a","cotas de Fundos de Investimento Referenciado"],["b","compra de opções"],["c","opções a descoberto"],["d","títulos de responsabilidade de instituição financeira"]],"ans":"c","exp":"Tema: vedações do clube de investimento. O clube pode aplicar o excedente de 67% em outros valores mobiliários, mas não pode lançar opções a descoberto. A alternativa C é a correta. Compra de opções (B) é permitida, e as cotas de fundos e os títulos de instituições financeiras (A e D) também não são vedados.","id":"199544237"},{"n":454,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"178","capn":"Questão 178 (cód. 199544238)","stem":"Em situação de atraso no pagamento do resgate das cotas de um Clube de Investimento, é devida multa por dia de atraso igual a:","opts":[["a","0,1% do valor da carteira, a ser paga pelo administrador do Clube."],["b","0,1% do valor da carteira, a ser paga por cada cotista."],["c","0,5% do valor de resgate, a ser paga por cada cotista."],["d","0,5% do valor de resgate, a ser paga pelo administrador do Clube."]],"ans":"d","exp":"Tema: multa por atraso no pagamento de resgate de clube. A multa é de 0,5% por dia sobre o valor do resgate, e é paga pelo administrador do clube. A alternativa D é a correta.","id":"199544238"},{"n":455,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"179","capn":"Questão 179 (cód. 199544239)","stem":"Número máximo de participantes de um Clube de Ações:","opts":[["a","50"],["b","150"],["c","3"],["d","30"]],"ans":"a","exp":"Tema: número máximo de participantes de clube de ações. O limite é de 50 cotistas. A alternativa A é a correta.","id":"199544239"},{"n":456,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"180","capn":"Questão 180 (cód. 199544240)","stem":"Percentual máximo do total do Clube de Investimento que um único cotista pode deter:","opts":[["a","30%"],["b","67%"],["c","25%"],["d","40%"]],"ans":"d","exp":"Tema: participação máxima de um cotista em clube. Um único cotista não pode deter mais de 40% do total do clube. A alternativa D é a correta.","id":"199544240"},{"n":457,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"181","capn":"Questão 181 (cód. 199544241)","stem":"Percentual mínimo da carteira de um Clube que deve ser direcionado para a compra de ações:","opts":[["a","67,00%"],["b","95,00%"],["c","80,00%"],["d","50,00%"]],"ans":"a","exp":"Tema: percentual mínimo de ações na carteira do clube. Pelo menos 67% do patrimônio deve ser aplicado em ações. A alternativa A é a correta, e é o mesmo percentual exigido dos fundos de ações.","id":"199544241"},{"n":458,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"182","capn":"Questão 182 (cód. 199544242)","stem":"São instituições que podem administrar um clube de investimento: I. Corretoras de Valores II. Bancos de Investimentos III. Bancos Múltiplos Está (ão) correto (s) o que se afirma em:","opts":[["a","I e III"],["b","II e III"],["c","Apenas I"],["d","I e II"]],"ans":"d","exp":"Tema: quem pode administrar um clube de investimento. Podem administrar as corretoras de valores e os bancos de investimento. A alternativa D é a correta. Os bancos múltiplos (III) não são administradores de clubes pela regra apresentada.","id":"199544242"},{"n":459,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"183","capn":"Questão 183 (cód. 199544256)","stem":"Com relação à Letra Hipotecária, título de dívida, emitido por instituições financeiras autorizadas a conceder créditos hipotecários, assinale a alternativa correta:","opts":[["a","Conta com garantia integral do FGC"],["b","Pessoa Física possui isenção de Imposto de Renda"],["c","Não pode ser emitido pela CEF"],["d","É emitido lastreado em empréstimos pessoais"]],"ans":"b","exp":"Tema: Letra Hipotecária e a tributação para pessoa física. A LH é um título de dívida emitido por instituições autorizadas a conceder crédito hipotecário. A chave indica B (pessoa física com isenção de IR), o que é coerente com a questão 229 desta mesma apostila. A isenção depende da norma específica do título, e o texto desta edição não detalha essa regra. Vale conferir a legislação da LH no material original, porque o comentário anterior apontava uma divergência que não consigo confirmar.","id":"199544256"},{"n":460,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"184","capn":"Questão 184 (cód. 199544257)","stem":"A Letra de Crédito Imobiliário, título de renda fixa, lastreado por créditos imobiliários garantidos por hipoteca ou alienação fiduciária de coisa imóvel, que confere aos seus tomadores direito de crédito pelo valor nominal, juros e, se for o caso, atualização monetária nelas estipulados. Esse título pode ser emitido por:","opts":[["a","Corretoras de Valores"],["b","Bancos Múltiplos que concedam crédito imobiliário"],["c","Qualquer banco múltiplo"],["d","Sociedades de arrendamento mercantil"]],"ans":"b","exp":"Tema: emissores da LCI. A LCI pode ser emitida por bancos múltiplos que concedam crédito imobiliário. A alternativa B é a correta. As corretoras (A), os bancos múltiplos sem essa carteira (C) e as empresas de arrendamento (D) não emitem LCI nessa condição.","id":"199544257"},{"n":461,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"185","capn":"Questão 185 (cód. 199544258)","stem":"A Letra Financeira é um título de emissão das instituições financeiras e tem como característica","opts":[["a","Aproveitar o spread bancário entre o curto e o longo prazo"],["b","Ser de renda fixa e de longo prazo, com o objetivo de alongar o perfil de captação das IF’s, melhorando a relação entre ativo e passivo das instituições"],["c","Beneficiar o investidor com um menor imposto de renda"],["d","Atrair o capital externo com preferência pelo longo prazo"]],"ans":"b","exp":"Tema: Letra Financeira. É um título de renda fixa de longo prazo, emitido pelas instituições financeiras para alongar o perfil de captação e melhorar a relação entre ativo e passivo. A alternativa B é a correta. As demais descrevem spread de curto prazo, benefício fiscal indevido ou captação de capital externo, que não são as características da LF.","id":"199544258"},{"n":462,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"186","capn":"Questão 186 (cód. 199544259)","stem":"Calcule o preço unitário de uma LTN com 110 dias úteis até o seu resgate, considerando os seguintes prazos e vencimentos (DU: Taxa) do DI-Futuro no momento da operação, (110;14,08). Considerando um prêmio de 12 pontos base para a LTN, o resultado desse cálculo é:","opts":[["a","944,120861"],["b","943,687686"],["c","946,04191"],["d","945,45056"]],"ans":"b","exp":"Tema: preço unitário de LTN. A LTN é descontada pela taxa do DI-Futuro somada ao prêmio de 12 pontos-base, que dá 14,08% + 0,12% = 14,20% ao ano. Com 110 dias úteis, o PU é 1.000 / (1,142)^(110/252) ≈ R$ 943,69. A alternativa B é a correta.","id":"199544259"},{"n":463,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"187","capn":"Questão 187 (cód. 199544260)","stem":"Em um determinado momento, uma NTN-B Principal está sendo negociada com 430 dias úteis para o seu vencimento e indicava uma taxa de 7,6% ao ano. A cotação desse título para compra é de:","opts":[["a","85,66"],["b","88,25"],["c","87,48"],["d","88,6"]],"ans":"b","exp":"Tema: cotação de NTN-B Principal. A cotação depende do valor de referência da NTN-B e da taxa de compra, descontada pelos dias úteis até o vencimento. A chave indica B (R$ 88,25). O cálculo depende do valor nominal atualizado no período, que o texto não traz. Recomendo conferir o cálculo original.","id":"199544260"},{"n":464,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"188","capn":"Questão 188 (cód. 199544261)","stem":"Com relação ao PU de uma LTN, assinale a alternativa correta:","opts":[["a","Possui o seu valor atualizado diariamente pela taxa de juros do mercado"],["b","Possui o seu valor atualizado pelo índice de preços oficial do país"],["c","É sempre R$ 1000 (mil reais) e a rentabilidade é calculada a partir dessa referência"],["d","É calculado a partir do deságio do seu valor nominal no vencimento"]],"ans":"d","exp":"Tema: PU da LTN. A LTN é um título zero cupom, e o PU é calculado pelo desconto do valor nominal no vencimento. Por isso o PU é determinado pelo deságio sobre o valor nominal. A alternativa D é a correta. A alternativa A atualiza pelo mercado, e a B pelo índice de preços, o que se aplica a outros títulos.","id":"199544261"},{"n":465,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"189","capn":"Questão 189 (cód. 199544262)","stem":"Segundo o Decreto 3.859 de 2001, são características de uma LTN:","opts":[["a","Valor nominal com múltiplo de R$ 1.000 (mil reais) e rendimento definido pelo deságio sobre o valor nominal"],["b","Valor nominal com múltiplo de R$ 100 (cem reais) e rendimento definido pelo deságio sobre o valor nominal"],["c","Valor nominal na data base de R$ 1.000 (mil reais) e rendimento ajustável de acordo com a taxa média praticada no mercado"],["d","Valor nominal na data base de R$ 100 (cem reais) e rendimento ajustável de acordo com a taxa média praticada no mercado"]],"ans":"a","exp":"Tema: características da LTN, segundo o Decreto 3.859/2001. A LTN tem valor nominal com múltiplo de R$ 1.000, e o rendimento é definido pelo deságio sobre o valor nominal. A alternativa A é a correta. A alternativa B usa múltiplo de R$ 100, que não é a regra, e as alternativas C e D atribuem rendimento ajustável, o que é característica de outro título. Atenção: a apostila apresenta a alternativa B com rótulo repetido.","id":"199544262"},{"n":466,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"190","capn":"Questão 190 (cód. 199544263)","stem":"As Letras de Câmbio são instrumentos de captação emitidos por sociedades de crédito, financiamento e investimento (Financeiras), com base numa transação comercial. Como características de resgate, as Letras de Câmbio, que normalmente ultrapassam sessenta dias de prazo:","opts":[["a","não possuem liquidez diária e o investidor só poderá resgatar o montante no vencimento."],["b","possuem liquidez diária e o investidor pode resgatar o montante antes do vencimento."],["c","possuem liquidez diária a partir de 15 dias, quando o investidor poderá resgatar o montante."],["d","não possuem liquidez diária, mas o investidor poderá resgatar o montante antes do vencimento."]],"ans":"a","exp":"Tema: liquidez da letra de câmbio. As letras de câmbio prazo acima de 60 dias não têm liquidez diária, e o investidor só resgata no vencimento. A alternativa A é a correta.","id":"199544263"},{"n":467,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"191","capn":"Questão 191 (cód. 199544264)","stem":"Suponha que um investidor precifique uma NTN – B, título público pós-fixados, indexado à inflação. No mesmo dia, a expectativa de inflação caiu e a taxa de renda fixa se manteve constante. Caso o investidor não mude o preço do título, a taxa de juros real estimada no cálculo ficará:","opts":[["a","maior que a projetada pelas novas expectativas de inflação e taxa de renda fixa."],["b","igual à nova expectativa de inflação."],["c","menor que a projetada pelas novas expectativas de inflação e taxa de renda fixa."],["d","constante pois a taxa de renda fixa não se alterou."]],"ans":"c","exp":"Tema: taxa real de uma NTN-B com queda da expectativa de inflação. Se a expectativa de inflação cai e o preço é mantido, a taxa real estimada no cálculo fica menor que a projetada pelas novas expectativas. A alternativa C é a correta. A taxa real muda porque a inflação projetada muda, e o título continua com o mesmo preço.","id":"199544264"},{"n":468,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"192","capn":"Questão 192 (cód. 199544265)","stem":"Investimentos imobiliários com aplicação em títulos de renda fixa emitidos por instituições financeiras autorizadas a operar com carteiras de créditos imobiliários são aplicações em:","opts":[["a","certificados de recebíveis mobiliários"],["b","letras de crédito imobiliário"],["c","letras de Câmbio imobiliário"],["d","letras do Tesouro Nacional"]],"ans":"b","exp":"Tema: aplicação imobiliária em títulos de renda fixa de instituições autorizadas a operar com crédito imobiliário. A aplicação é em letras de crédito imobiliário (LCI). A alternativa B é a correta. Ver a questão 183 e a observação de extração da questão 192, que trata da numeração das alternativas.","id":"199544265"},{"n":469,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"193","capn":"Questão 193 (cód. 199544266)","stem":"Um cliente do Banco XYZ pediu cotação para a compra de um lote de 50.000 LTNs, vencimento em 245 du no mercado secundário, com liquidação em “D0”. A mesa de clientes do banco consegue uma oferta de compra com prêmio de 9 pontos. O mercado futuro de DI-1Dia está projetando taxas de juros de 12,60% a.a.. O cliente mantém os títulos em carteira até o resgate. Considere o valor da taxa média do CDI-Over no período até o resgate igual a 12,65% a.a. O resultado financeiro líquido dessa aplicação em relação a variação do CDI-Over é:","opts":[["a","21.559,10"],["b","38.806,56"],["c","32.562,24"],["d","17.254,88"]],"ans":"d","exp":"Tema: resultado financeiro de LTN negociada com prêmio. O cálculo depende da taxa de compra com prêmio, da variação do CDI-Over até o resgate e do número de títulos. A chave indica D (R$ 17.254,88). O cálculo completo exige encadear o PU da LTN com o prêmio e a diferença de taxa, que não estão todos explicitados no enunciado. Recomendo conferir a resolução original.","id":"199544266"},{"n":470,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"194","capn":"Questão 194 (cód. 199544267)","stem":"O valor presente de um fluxo financeiro representa o preço de um ativo de renda fixa. O preço de negociação do ativo, para um mesmo prazo é:","opts":[["a","reduzido quando ocorre uma queda na taxa de juros. Observa-se uma desvalorização no preço de mercado do título."],["b","não se altera quando ocorre uma queda na taxa de juros. Observa-se um equilíbrio no preço de mercado do título."],["c","elevado quando ocorre uma queda na taxa de juros. Observa-se uma valorização no preço de mercado do título."],["d","não se altera quando ocorre uma alta na taxa de juros. Observa-se um equilibro no preço de mercado do título."]],"ans":"c","exp":"Tema: relação entre juros e preço de títulos de renda fixa. Quando a taxa de juros cai, o valor presente do fluxo aumenta, e por isso o preço do título sobe, com valorização. A alternativa C é a correta. As demais descrevem o efeito oposto ou afirmam que o preço não se altera, o que não é verdadeiro.","id":"199544267"},{"n":471,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"195","capn":"Questão 195 (cód. 199544268)","stem":"A expectativa de alterações na taxa de juros dos agentes financeiros tem influência direta sobre os preços dos títulos de renda fixa do Tesouro (LTN). Os agentes econômicos estimam, através do mercado de derivativos, a taxa de juros esperada para os meses futuros e a partir destas projeções os títulos têm os seus preços determinados. Suponha que um agente efetuou a compra de uma LTN, em um terminado dia, a taxa de juros de 15,00% a.a. Suponha agora, uma estimativa de elevação da taxa de juros e 20 dias depois, a taxa de juros deste título aumente para 18,5% a.a. O efeito desta alteração na rentabilidade (obtida ao longo dos 20 dias) da LTN, caso o agente efetue a venda este título é:","opts":[["a","manutenção no valor da taxa de venda (18,50%)."],["b","diminuir a níveis menores que a sua taxa de compra (15,00%)."],["c","aumentar a níveis maiores que a sua taxa de venda (18,50%)."],["d","manutenção no valor da taxa de compra (15,00%)."]],"ans":"b","exp":"Tema: efeito de alta de juros sobre um título comprado a 15%. Se a taxa sobe para 18,5%, o preço do título cai, e quem vende antes do vencimento tem rentabilidade menor do que a taxa de compra. A alternativa B é a correta. A alternativa A descreve a taxa de venda como se fosse a rentabilidade, e as alternativas C e D não consideram a queda de preço.","id":"199544268"},{"n":472,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"196","capn":"Questão 196 (cód. 199544269)","stem":"Sobre o Certificado de Depósito Bancário - CDB:","opts":[["a","Possui garantia limitada do Fundo Garantidor de Crédito - FGC"],["b","Tem prazo máximo de 720 dias"],["c","Possui tributação diferenciada se for prefixado ou pós fixado"],["d","Possui isenção de I.R para aplicações até R$ 20 mil"]],"ans":"a","exp":"Tema: CDB e FGC. O CDB tem garantia limitada do FGC, de até R$ 250 mil por titular e por instituição. A alternativa A é a correta. Prazo máximo de 720 dias (B), tributação diferenciada conforme prefixado ou pós-fixado (C) e isenção até R$ 20 mil (D) não são regras do CDB.","id":"199544269"},{"n":473,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"197","capn":"Questão 197 (cód. 199544270)","stem":"Seu cliente ao operar no Tesouro Direto deseja aplicar em um título que seja corrigido pela inflação e que não tenha risco de reinvestimento. Nesse caso, deverá escolher:","opts":[["a","Tesouro IPCA + com Juros Semestrais (NTN- -B)"],["b","Tesouro Selic (LFT)"],["c","Tesouro Prefixado (LTN)"],["d","Tesouro IPCA + (NTN-B Principal)"]],"ans":"d","exp":"Tema: Tesouro Direto para inflação sem risco de reinvestimento. O título que paga apenas o principal corrigido, sem cupons, é o Tesouro IPCA+ (NTN-B Principal). A alternativa D é a correta. O IPCA+ com juros semestrais (A) paga cupons, o que gera risco de reinvestimento, e a LFT (B) e a LTN (C) não são corrigidas pela inflação.","id":"199544270"},{"n":474,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"198","capn":"Questão 198 (cód. 199544271)","stem":"Seu cliente comprou um lote de LTN com vencimento para 2021. O risco de liquidez presente nessa aplicação está na possibilidade de:","opts":[["a","Alteração do valor do título em face das mudanças da taxa de juros"],["b","Impossibilidade de vender o ativo antes de 2021 pelo seu preço justo, por falta de compradores no mercado"],["c","Não pagamento por parte do emissor do título do compromisso"],["d","Falta de cobertura do FGC para o título"]],"ans":"b","exp":"Tema: risco de liquidez de uma LTN. A LTN pode não ser negociada antes do vencimento pelo preço justo, por falta de compradores. A alternativa B é a correta. As demais descrevem risco de mercado (A), risco de crédito (C) e a falta de cobertura do FGC, que não é o risco de liquidez.","id":"199544271"},{"n":475,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"199","capn":"Questão 199 (cód. 199544272)","stem":"Seu cliente compra um Título Tesouro IPCA + Com Juros Semestrais 2045. Com relação à tributação do Imposto de Renda:","opts":[["a","Ocorrerá somente no vencimento do título."],["b","Ocorrerá no pagamento dos juros semestrais e também no vencimento do título, conforme tabela regressiva"],["c","Ocorrerá no pagamento dos juros semestrais e também no vencimento do título, conforme tabela progressiva"],["d","Ocorrerá somente no pagamento dos juros semestrais"]],"ans":"b","exp":"Tema: IR sobre NTN-B com juros semestrais. O IR incide sobre os juros pagos semestralmente e também sobre o rendimento total no vencimento, conforme a tabela regressiva. A alternativa B é a correta. As alternativas A e D tratam apenas um dos eventos, e a C usa a tabela progressiva, que não se aplica.","id":"199544272"},{"n":476,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"200","capn":"Questão 200 (cód. 199544273)","stem":"Seu cliente pessoa física deseja um produto com vantagem tributária e garantido pelo FGC. Você deveria indicar:","opts":[["a","CDB"],["b","LCI"],["c","Ações"],["d","Debêntures Incentivadas"]],"ans":"b","exp":"Tema: produto com vantagem tributária e garantia do FGC. A LCI é isenta de IR para pessoa física e tem garantia do FGC. A alternativa B é a correta. O CDB (A) tem garantia do FGC, mas é tributado. Ações (C) e debêntures incentivadas (D) não têm garantia do FGC.","id":"199544273"},{"n":477,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"201","capn":"Questão 201 (cód. 199544274)","stem":"Com relação ao imposto de renda (I.R) em uma aplicação de Certificado de Depósito Bancário - CDB:","opts":[["a","Ocorre nos últimos dias úteis de Maio e Novembro"],["b","Incide com a tabela regressiva do I.R sobre o valor total resgatado pelo cliente"],["c","Incide com a tabela regressiva do I.R sobre o valor total do rendimento do cliente"],["d","Incide com a tabela progressiva do I.R sobre o valor total do rendimento do cliente"]],"ans":"c","exp":"Tema: IR sobre CDB. A tabela regressiva incide sobre o rendimento do cliente, e não sobre o valor total resgatado. A alternativa C é a correta. A alternativa A (últimos dias de maio e novembro) é o come-cotas de fundos, e as alternativas B e D erram a base ou a tabela.","id":"199544274"},{"n":478,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"202","capn":"Questão 202 (cód. 199544275)","stem":"Título Público do tipo zero cupom e negociado com deságio sobre o valor de face:","opts":[["a","LTN"],["b","LFN"],["c","NTN-B"],["d","NTN-F"]],"ans":"a","exp":"Tema: título público zero cupom negociado com deságio. A LTN é zero cupom, e o rendimento vem do deságio sobre o valor nominal. A alternativa A é a correta.","id":"199544275"},{"n":479,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"203","capn":"Questão 203 (cód. 199544276)","stem":"Seu cliente deseja um investimento que conte com proteção contra a inflação. Você deveria indicar:","opts":[["a","Letra Financeira do Tesouro – LFT"],["b","Letra de Crédito Imobiliário – LCI"],["c","Nota do Tesouro Nacional – Série B – NTN-B"],["d","Nota do Tesouro Nacional – Série F – NTN-F"]],"ans":"c","exp":"Tema: proteção contra a inflação. A NTN-B é o título público indexado ao IPCA, e por isso protege contra a inflação. A alternativa C é a correta. A LFT (A) é pós-fixada pela Selic, a LCI (B) é um título de crédito imobiliário, e a NTN-F (D) é prefixada.","id":"199544276"},{"n":480,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"204","capn":"Questão 204 (cód. 199544277)","stem":"Um investimento de R$ 10 mil em uma Letra de Câmbio por 150 dias corridos com rentabilidade de 5% a.p terá qual valor de resgate líquido.","opts":[["a","R$ 10.500,80"],["b","R$ 10.387,50"],["c","R$ 10.667,90"],["d","R$ 10.880,99"]],"ans":"b","exp":"Tema: resgate líquido de letra de câmbio. O investidor aplicou R$ 10.000 por 150 dias, com rentabilidade de 5% no período. O valor bruto é de R$ 10.500, e o rendimento de R$ 500. Para prazo de até 180 dias, a alíquota de IR é de 22,5%: 0,225 × 500 = R$ 112,50. O resgate líquido é de R$ 10.500 − R$ 112,50 = R$ 10.387,50. A alternativa B é a correta.","id":"199544277"},{"n":481,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"205","capn":"Questão 205 (cód. 199544278)","stem":"Um determinado cliente fez uma aplicação em um CDB pelo prazo de 200 dias. Qual será a tributação no resgate:","opts":[["a","IOF e IR (20%)"],["b","IOF e IR (22,50%)"],["c","Somente IR (22,50%)"],["d","Somente IR (20%)"]],"ans":"d","exp":"Tema: tributação de CDB no resgate. Para prazo de 200 dias, a alíquota regressiva é de 20%, e como o resgate é após 30 dias, não há IOF. A alternativa D é a correta. A alternativa A inclui IOF, que não incide após 30 dias, e as alternativas B e C usam alíquota de 22,5%, válida apenas para prazos de até 180 dias.","id":"199544278"},{"n":482,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"206","capn":"Questão 206 (cód. 199544279)","stem":"Se um cliente investir em Letra Financeira do Tesouro – LFT, terá sua rentabilidade:","opts":[["a","Creditada semestralmente atualizada pela Taxa Selic"],["b","Creditada semestralmente atualizada pela Taxa CDI"],["c","Creditada no vencimento do título, atualizada pela Taxa Selic"],["d","Creditada no vencimento do título, atualizada pela Taxa CDI"]],"ans":"c","exp":"Tema: rentabilidade da LFT. A LFT paga a rentabilidade apenas no vencimento, atualizada pela taxa Selic. A alternativa C é a correta. A LFT não paga cupom semestral (A e B), e a referência é a Selic, e não o CDI (D).","id":"199544279"},{"n":483,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"207","capn":"Questão 207 (cód. 199544280)","stem":"Responsável pelo recolhimento do Imposto de Renda que incide sobre as aplicações em Certificado de Depósito Bancário – CDB:","opts":[["a","Instituição que emitiu o certificado"],["b","Próprio investidor"],["c","Bolsa de Valores"],["d","Bacen"]],"ans":"a","exp":"Tema: responsável pelo IR sobre CDB. A instituição que emitiu o certificado é a responsável pela retenção do IR. A alternativa A é a correta.","id":"199544280"},{"n":484,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"208","capn":"Questão 208 (cód. 199544281)","stem":"Um investidor pessoa física fez uma aplicação em LCI e resgatou 80 dias depois com rentabilidade acima de R$ 50 mil. Nesse caso:","opts":[["a","Deverá pagar I.R com alíquota de 22,50%"],["b","Deverá pagar I.R com alíquota de 15%"],["c","Estará isento do I.R"],["d","Deverá pagar I.R com alíquota de 17,50%"]],"ans":"c","exp":"Tema: IR sobre LCI para pessoa física. A LCI é isenta de IR para pessoa física, independentemente do rendimento ou do prazo. A alternativa C é a correta. O rendimento de R$ 50 mil não altera a isenção.","id":"199544281"},{"n":485,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"209","capn":"Questão 209 (cód. 199544282)","stem":"Com relação à Letra de Crédito Imobiliário – LCI, assinale a alternativa correta:","opts":[["a","Podem ser emitidas por qualquer banco"],["b","São lastreadas em financiamento imobiliário"],["c","Não possuem garantia do FGC"],["d","São emitidas por empresas que realizam construções de imóveis"]],"ans":"b","exp":"Tema: características da LCI. A LCI é lastreada em créditos imobiliários, como financiamentos garantidos por hipoteca ou alienação fiduciária. A alternativa B é a correta. A LCI tem garantia do FGC (C), não pode ser emitida por qualquer banco (A) e não é emitida por construtoras (D).","id":"199544282"},{"n":486,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"210","capn":"Questão 210 (cód. 199544283)","stem":"Um determinado investidor acredita na elevação da taxa de juros para os próximos anos. Com isso, deveria investir em:","opts":[["a","LFT"],["b","LTN"],["c","NTN-B"],["d","Ações"]],"ans":"a","exp":"Tema: investimento para quem espera alta de juros. A LFT é pós-fixada, e seu rendimento acompanha a Selic. Se os juros sobem, a LFT rende mais, e por isso é a indicação adequada. A alternativa A é a correta. LTN e NTN-B (B e C) são prefixada e indexada à inflação, e as ações (D) não são investimento de juros.","id":"199544283"},{"n":487,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"211","capn":"Questão 211 (cód. 199544284)","stem":"Seu cliente deseja montar uma carteira somente com títulos públicos e todos com rentabilidade pós fixadas. Você deveria indicar qual carteira:","opts":[["a","60% LFT e 40% LTN"],["b","60% LFT e 40% CDB pós fixado"],["c","60% LFT e 40% NTN-B"],["d","100% LFT"]],"ans":"d","exp":"Tema: carteira só com títulos públicos pós-fixados. A LFT é o único título público pós-fixado, atrelado à Selic, e por isso uma carteira 100% LFT atende ao enunciado. A alternativa D é a correta. As demais misturam títulos prefixados (LTN) ou indexados à inflação (NTN-B), ou incluem o CDB, que é privado.","id":"199544284"},{"n":488,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"212","capn":"Questão 212 (cód. 199544285)","stem":"Você é gerente de um cliente que deseja um produto de investimento com rentabilidade real. Você deveria indicar:","opts":[["a","LFT"],["b","CDB Prefixado"],["c","NTN-B"],["d","LTN"]],"ans":"c","exp":"Tema: produto com rentabilidade real. A rentabilidade real é a que fica acima da inflação, e o título que a entrega é a NTN-B, indexada ao IPCA com taxa real fixa. A alternativa C é a correta. LFT (A) é pós-fixada nominal, o CDB prefixado (B) e a LTN (D) são nominais.","id":"199544285"},{"n":489,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"213","capn":"Questão 213 (cód. 199544287)","stem":"Uma Letra Financeira do Tesouro – LFT tem a sua remuneração:","opts":[["a","Pós fixada, atrelada à Taxa Selic Meta"],["b","Pós fixada, atrelada à Taxa Selic Over"],["c","Prefixada, atrelada à Taxa Selic Over"],["d","Atrelada à inflação"]],"ans":"b","exp":"Tema: remuneração da LFT. A LFT é pós-fixada e acompanha a taxa Selic Over, que é a taxa média diária de financiamento no mercado. A alternativa B é a correta. A Selic Meta (A) é a taxa definida pelo Copom, e não a remuneração diária do título.","id":"199544287"},{"n":490,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"214","capn":"Questão 214 (cód. 199544289)","stem":"Com relação às garantias do Mercado Futuro, assinale a alternativa correta:","opts":[["a","É sempre igual ou maior do que o valor total que está se operando"],["b","É obrigatória e não é permitido fiança bancária"],["c","Deve sempre ser depositada antes do início das operações no mercado futuro"],["d","Mesmo em situações de prejuízo, o investidor sempre irá resgatar o valor total deixado em garantia"]],"ans":"c","exp":"Tema: garantias no mercado futuro. As garantias devem ser depositadas antes do início das operações no mercado futuro. A alternativa C é a correta. A garantia não precisa ser sempre maior que o valor operado (A), a fiança bancária é permitida em alguns casos (B), e o investidor não recupera garantia em caso de prejuízo (D).","id":"199544289"},{"n":491,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"215","capn":"Questão 215 (cód. 199544290)","stem":"Com relação ao Mercado a Termo, assinale a alternativa correta:","opts":[["a","É um acordo de compra e venda de um certo ativo para ser entregue em uma data futura a um preço previamente estabelecido"],["b","É um acordo de compra e venda de um certo ativo que conta com garantias por parte da bolsa e possui contratos padronizados"],["c","É um tipo de contrato muito usado pelos agricultores do Brasil para proteção de preços"],["d","Conta com mecanismo de proteção para redução do risco de crédito chamado de Ajuste Diário"]],"ans":"a","exp":"Tema: mercado a termo. É um acordo de compra e venda de um ativo, para entrega em data futura, a preço previamente estabelecido. A alternativa A é a correta. O mercado a termo não tem garantia da bolsa e não é padronizado (B), o ajuste diário não é do termo (D), e a alternativa C restringe o uso ao agro, o que não é o conceito.","id":"199544290"},{"n":492,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"216","capn":"Questão 216 (cód. 199544291)","stem":"Um gestor de um fundo de ações deseja utilizar o Mercado Futuro para fazer Head, nesse caso:","opts":[["a","Ele deveria comprar contratos futuros do Ibovespa, desconsiderando o beta médio da carteira"],["b","Ele deveria vender contratos futuros, utilizando o beta médio da carteira de ações"],["c","O número de contratos vendidos não irá se alterar, a não ser que ocorra alteração na carteira de ações"],["d","Ele deveria comprar contratos futuros, considerando o beta médio da carteira de ações"]],"ans":"b","exp":"Tema: hedge de carteira de ações com futuros de Ibovespa. Para proteger a carteira de uma queda, o gestor vende contratos futuros, dimensionados pelo beta médio da carteira em relação ao índice. A alternativa B é a correta. Comprar futuros (A e D) aumentaria a exposição à queda, e a alternativa C ignora o ajuste necessário pelo beta.","id":"199544291"},{"n":493,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"217","capn":"Questão 217 (cód. 199544292)","stem":"Sobre as especificações de contratos derivativos, é correto afirmar:","opts":[["a","Em contratos a termo são definidos os dias de vencimento (padronizados), as unidades de negociação, o ativo-objeto e as margens de garantia"],["b","Em contratos de swap são definidos os prazos de vigência, as unidades de negociação e as margens de garantia"],["c","Em contratos de opções de compra, são definidos os dias de vencimento (padronizados), o tipo da opção, o ativo-objeto e os ajustes diários"],["d","Em contratos futuros são especificados as unidades de negociação, os dias de vencimento (padronizados), o ativo-objeto e os ajustes diários."]],"ans":"d","exp":"Tema: especificações de contratos futuros. Os contratos futuros são padronizados e têm definidos as unidades de negociação, os dias de vencimento, o ativo-objeto e os ajustes diários. A alternativa D é a correta. As demais alternativas atribuem a contratos a termo ou swap características que não lhes pertencem, como vencimento padronizado no termo (A).","id":"199544292"},{"n":494,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"218","capn":"Questão 218 (cód. 199544293)","stem":"Considerando que há países com mercados derivativos mais ou menos desenvolvidos, como também operações e contabilizações de derivativos, é correto afirmar:","opts":[["a","Um país que não dispõe de mercados derivativos evita problemas de especulação excessiva e tende a ter um desempenho econômico melhor"],["b","Os exportadores que têm receita em dólar e compram put de dólar são especuladores"],["c","Um país não deveria eliminar a existência de mercados derivativos porque isto reduziria drasticamente as chances das empresas eliminarem seus riscos"],["d","Os reguladores não devem estabelecer normas de contabilização de derivativos porque a padronização não é importante para a evidenciação de riscos nos balanços"]],"ans":"c","exp":"Tema: papel dos mercados derivativos em um país. Os derivativos permitem que empresas eliminem ou reduzam riscos. Por isso, um país não deveria eliminar os mercados derivativos, porque isso reduziria as chances de hedge. A alternativa C é a correta. As demais tratam os derivativos como causa de problemas, o que não é a visão correta.","id":"199544293"},{"n":495,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"219","capn":"Questão 219 (cód. 199544294)","stem":"Conforme o regulamento operacional da BM&F em relação à liquidação dos derivativos:","opts":[["a","Os prêmios das opções será liquidado em D+3"],["b","Os ajustes diários do mercado a termo ocorrem em D+1"],["c","Os ajustes diários do mercado futuro ocorrem em D+0"],["d","Os ajustes diários do mercado futuro ocorrem em D+1"]],"ans":"d","exp":"Tema: liquidação dos ajustes diários no mercado futuro. Os ajustes diários são liquidados em D+1, no dia útil seguinte. A alternativa D é a correta.","id":"199544294"},{"n":496,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"220","capn":"Questão 220 (cód. 199544295)","stem":"Sobre os Mercados Futuros, assinale a alternativa correta:","opts":[["a","Quando um investidor estiver comprado em futuros, porém de forma coberta com o ativo, não terá débitos de ajuste diário no caso de variação negativa"],["b","Trata-se de um mercado onde envolve basicamente um compromisso de compra ou venda de determinado ativo em data futura, que conta com contratos não padronizados"],["c","Tipo de mercado onde ocorre o pagamento de prêmio na abertura do contrato e que se tem expectativa de alta ou baixa de um determinado ativo, contando ainda com contratos padrões"],["d","É obrigatório o depósito de margem de garantia e também de recursos suficientes para honrar os ajustes diários"]],"ans":"d","exp":"Tema: exigências do mercado futuro. É obrigatório depositar margem de garantia e também manter recursos suficientes para honrar os ajustes diários. A alternativa D é a correta. As demais afirmações são falsas ou se referem a outros contratos.","id":"199544295"},{"n":497,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"221","capn":"Questão 221 (cód. 199544296)","stem":"Sobre os Swaps, assinale a alternativa correta:","opts":[["a","É um tipo de derivativo que possui contratos padronizados"],["b","São contratos entre duas partes visando uma troca de fluxo de caixa futuro, permitindo assim um hedge para 2 variáveis"],["c","Os valores recebidos nesse tipo de contrato são sempre superiores ao valor principal a que se refere o contrato"],["d","São contratos que contam com a garantia da B3"]],"ans":"b","exp":"Tema: swaps. Os swaps são contratos entre duas partes para troca de fluxos de caixa futuros, permitindo hedge de duas variáveis. A alternativa B é a correta. Swaps não são padronizados (A), e não há garantia da B3 nesse tipo de contrato (D).","id":"199544296"},{"n":498,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"222","capn":"Questão 222 (cód. 9741)","stem":"O IBOVESPA é considerado um índice de mercado:","opts":[["a","Sem ponderação, com distribuição igual de pesos dos ativos"],["b","Ponderado pela capitalização de mercado dos ativos que o compõe"],["c","Ponderado pela liquidez dos ativos que o compõe"],["d","Ponderado aleatoriamente pelos pesos dos ativos que o compõe"]],"ans":"c","exp":"Tema: ponderação do Ibovespa. O Ibovespa é um índice de mercado ponderado pela liquidez dos ativos que o compõem, o que faz com que os papéis mais negociados tenham maior peso. A alternativa C é a correta. A distribuição igual de pesos (A) e a ponderação pela capitalização (B) não correspondem ao critério atual, e a ponderação aleatória (D) não é um critério de índice.","id":"9741"},{"n":499,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"223","capn":"Questão 223 (cód. 9742)","stem":"Sobre os Brazilian Depositary Receipts (BDRs), analise as afirmativas abaixo: I. A depositária dos ativos tem a função de obter registro dos BDRs na B3 e coordenar a distribuição de direitos no mercado (dividendos, bonificações, subscrições, etc) II. A emissão de BDRs deve ser realizada por instituição financeira autorizada e habilitada pelo BACEN e CVM a operar III. É função do emissor dos BDRs a estruturação e lançamento no mercado, obtenção de registros e obtenção de registros da companhia a CVM Está correto o que se afirma em:","opts":[["a","I e II"],["b","I e III"],["c","II e III"],["d","Todas as alternativas"]],"ans":"a","exp":"Tema: BDRs. Analisando:\n\nI. Correto. A depositária é responsável pelo registro dos BDRs na B3 e pela distribuição dos direitos, como dividendos e bonificações.\n\nII. Correto. A emissão deve ser feita por instituição autorizada e habilitada pelo Bacen e pela CVM.\n\nIII. Errado. A estruturação e o lançamento são funções do emissor, mas a obtenção do registro da companhia junto à CVM não é função do emissor do BDR, e sim da companhia. O item está mal formulado.\n\nA alternativa A (I e II) é a correta.","id":"9742"},{"n":500,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"224","capn":"Questão 224 (cód. 9743)","stem":"O direito de subscrição emitido por uma ação de companhia listada, se assemelha a uma:","opts":[["a","Compra de call"],["b","Compra de put"],["c","Venda de call"],["d","Venda de put"]],"ans":"a","exp":"Tema: direito de subscrição e opções. O direito de subscrição dá ao acionista o direito de comprar ações novas a preço definido, o que se assemelha à compra de uma call. A alternativa A é a correta. Put (B e D) dá direito de venda, e a venda de call (C) é a posição do lançador.","id":"9743"},{"n":501,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"225","capn":"Questão 225 (cód. 9744)","stem":"É obrigação da pessoa física que opera em bolsa de valores a apresentação anual, junto a declaração do IR, o (a):","opts":[["a","Demonstrativo de ganho de capital"],["b","Relação de operações realizadas"],["c","Relação de corretoras as quais operou"],["d","Resumo de apuração de ganhos em renda variável"]],"ans":"d","exp":"Tema: documento anual da pessoa física que opera em bolsa. Ela deve apresentar, junto à declaração do IR, o resumo de apuração de ganhos em renda variável. A alternativa D é a correta. Demonstrativo de ganho de capital (A) e relação de operações (B) são elementos de controle, mas o documento anual exigido é o resumo.","id":"9744"},{"n":502,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"226","capn":"Questão 226 (cód. 9745)","stem":"O preço de ajuste de Y (vencimento em agosto XZ) foi de R$ 110,00 em D0. O preço de ajuste do dia anterior (D-1) foi de R$ 105,00. Como será feito o ajuste deste dia para investidores que mantinham posições ao final de D-1 e mantiveram no mercado no dia seguinte:","opts":[["a","Compradores pagam R$ 5,00 e vendedores recebem R$ 5,00 em D+1"],["b","Compradores recebem R$ 5,00 e vendedores pagam R$ 5,00 em D+1"],["c","Compradores pagam R$ 5,00 e vendedores recebem R$ 5,00 em D+0"],["d","Compradores recebem R$ 5,00 e vendedores pagam R$ 5,00 em D+0"]],"ans":"b","exp":"Tema: ajuste diário de um contrato futuro. O preço de ajuste subiu de R$ 105 para R$ 110, uma variação de R$ 5. Compradores recebem R$ 5 e vendedores pagam R$ 5, em D+1, como ocorre no ajuste diário do futuro. A alternativa B é a correta.","id":"9745"},{"n":503,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"227","capn":"Questão 227 (cód. 9746)","stem":"Não há necessidade de pagar IR na fonte as operações de contratos futuros realizadas na B3 sob titularidade de:","opts":[["a","Bancos, corretoras e distribuidoras"],["b","Indústrias"],["c","Empresas comerciais"],["d","Pessoa física"]],"ans":"a","exp":"Tema: IR nas operações de futuros na B3. A isenção de retenção na fonte vale para bancos, corretoras e distribuidoras, que operam com contratos futuros. A alternativa A é a correta, conforme a regra apresentada na apostila.","id":"9746"},{"n":504,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"228","capn":"Questão 228 (cód. 9747)","stem":"As alternativas para realização de hedge, sem desembolso inicial de caixa, para uma empresa que possui passivo em dólar, é:","opts":[["a","Swap, opções e termo"],["b","Swap, opções e futuro"],["c","Swap, futuros e termo"],["d","Futuro, termo e opções"]],"ans":"c","exp":"Tema: hedge de passivo em dólar sem desembolso inicial. O swap, o contrato futuro e o termo não exigem desembolso inicial de caixa, ao contrário da opção, que exige pagamento de prêmio. A alternativa C é a correta. Opções (A, B e D) têm desembolso de prêmio, por isso não entram.","id":"9747"},{"n":505,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"229","capn":"Questão 229 (cód. 9748)","stem":"Para um investidor pessoa física que tenha interesse em rendimento isento de IR na fonte na composição de sua carteira de investimentos, pode – se recomendar a aplicação em:","opts":[["a","Letra Hipotecária"],["b","Letra de Câmbio"],["c","Recibo de Depósito Bancário"],["d","Fundos de Direitos Creditórios"]],"ans":"a","exp":"Tema: aplicação isenta de IR na fonte. A letra hipotecária é um dos títulos isentos apontados pela chave. A alternativa A é a correta, conforme a chave desta questão. A análise da isenção depende da norma específica desse título, como já comentado na questão 183.","id":"9748"},{"n":506,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"230","capn":"Questão 230 (cód. 9749)","stem":"Sobre o pagamento de cupom em títulos públicos federais do Tesouro Direto, o imposto de renda:","opts":[["a","É recolhido pelo cliente por meio do carnê leão no recebimento"],["b","É recolhido pelo cliente por meio da DARF no vencimento do título"],["c","É recolhido pelo próprio tesouro direto"],["d","É recolhido pela corretora que atuou como agente de custódia"]],"ans":"d","exp":"Tema: IR sobre cupom de títulos públicos no Tesouro Direto. O imposto é retido na fonte pela corretora que atua como agente de custódia. A alternativa D é a correta, coerente com a questão 19.","id":"9749"},{"n":507,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"231","capn":"Questão 231 (cód. 9750)","stem":"Rendimentos auferidos em LCI para o investidor pessoa física estão:","opts":[["a","Isentos"],["b","Sujeitos à tabela decrescente de IR conforme o prazo do investimento"],["c","Sujeitos a alíquota de 10% independente do prazo do investimento"],["d","Sujeitos a alíquota de 15% independente do prazo do investimento"]],"ans":"a","exp":"Tema: tributação da LCI para pessoa física. Os rendimentos da LCI são isentos de IR para pessoa física. A alternativa A é a correta. As alternativas B, C e D aplicam tabelas e alíquotas que não se aplicam à LCI.","id":"9750"},{"n":508,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"232","capn":"Questão 232 (cód. 9751)","stem":"A respeito do mercado de câmbio: I. As operações de câmbio no mercado interbancário só podem ser realizadas entre as instituições bancárias, com intermediação da mesa de câmbio do banco central. II. A operação de câmbio no mercado secundário envolve a movimentação de moeda estrangeira entre uma instituição autorizada a operar no mercado de câmbio para o de outra, igualmente autorizada, não havendo fluxo de entrada ou saída de moeda estrangeira no país; III. A operação de câmbio de mercado primário implica no recebimento ou a entrega de moeda estrangeira por parte de clientes no País, correspondente a fluxo de entrada ou de saída da moeda estrangeira; Está correto o que se afirma em:","opts":[["a","I e II"],["b","I e III"],["c","II e III"],["d","Todas as alternativas"]],"ans":"c","exp":"Tema: mercado de câmbio. Analisando:\n\nI. Errado. No mercado interbancário, as operações não ficam restritas aos bancos com intermediação da mesa do Bacen, como o item afirma.\n\nII. Correto. No mercado secundário, há movimentação de moeda entre instituições autorizadas, sem entrada ou saída de moeda do país.\n\nIII. Correto. No mercado primário, há recebimento ou entrega de moeda por clientes, o que representa fluxo de entrada ou saída.\n\nA alternativa C (II e III) é a correta.","id":"9751"},{"n":509,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"233","capn":"Questão 233 (cód. 9752)","stem":"Conforme o manual de procedimentos da Câmara de Câmbio da B3, a característica abaixo refere – se a qual participante: \"Instituição habilitada pela B3, que pode, exclusivamente, praticar operações de câmbio em sistemas eletrônicos vinculados à câmara, por conta e ordem de um ou mais agentes, sendo que não pode, em qualquer hipótese, praticar Operações de Câmbio em nome próprio ou sem a devida autorização do agente para o qual presta serviço\"","opts":[["a","Participante"],["b","Correspondente"],["c","Liquidante"],["d","Intermediador"]],"ans":"d","exp":"Tema: participante da câmara de câmbio da B3. A descrição é a de um intermediador, que atua por conta e ordem de agentes, em sistemas eletrônicos vinculados à câmara, sem operar em nome próprio. A alternativa D é a chave. A distinção com o correspondente (B) depende do manual da câmara, que não está detalhado no texto desta edição, então vale conferir o manual.","id":"9752"},{"n":510,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"234","capn":"Questão 234 (cód. 9753)","stem":"”Valor máximo em moeda estrangeira para a soma dos valores negociados nas operações de câmbio intermediadas no câmbio pronto eletrônico ou em outros sistemas de negociação.” A definição acima refere – se ao:","opts":[["a","Limite comercial para transferências de custódia entre corretoras"],["b","Limite operacional para ordem de ações"],["c","Limite operacional de negociação da Câmara de Câmbio da B3"],["d","Limite operacional de negociação da Câmara de Liquidação da B3"]],"ans":"c","exp":"Tema: limite operacional da câmara de câmbio. É o valor máximo, em moeda estrangeira, para a soma das operações negociadas no câmbio pronto eletrônico. A alternativa C é a correta. As demais se referem a ações ou à câmara de liquidação, que não definem esse limite.","id":"9753"},{"n":511,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"235","capn":"Questão 235 (cód. 9754)","stem":"Sobre ofertas tomadoras e doadores, analise as afirmativas abaixo: I. Cada oferta tomadora irá requerer a identificação do investidor final, uma vez que o empréstimo ficará catalogado em seu nome II. O tomador poderá utilizar uma carteira de cobertura como destino dos ativos, o que possibilita ao detentor segregar a posição, do qual não irá sensibilizar o portfólio para margens de garantia III. É de responsabilidade do doador indicar qual das contas de custódia o tomador irá destinar os ativos","opts":[["a","I e II"],["b","I e III"],["c","II e III"],["d","Todas as alternativas"]],"ans":"a","exp":"Tema: ofertas tomadoras e doadoras de empréstimo de ativos. Analisando:\n\nI. Correto. A oferta tomadora exige a identificação do investidor final, pois o empréstimo fica registrado em seu nome.\n\nII. Correto. O tomador pode usar uma carteira de cobertura, o que segrega a posição e não sensibiliza as margens.\n\nIII. Errado. Quem indica para qual conta de custódia os ativos vão é o tomador, e não o doador.\n\nA alternativa A (I e II) é a correta.","id":"9754"},{"n":512,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"236","capn":"Questão 236 (cód. 9755)","stem":"A parcela de lucros que é paga aos acionistas, estabelecida em estatuto, é conhecida como:","opts":[["a","Dividendos"],["b","Juros Sob Capital Próprio"],["c","Direito de Subscrição"],["d","Bonificação"]],"ans":"a","exp":"Tema: parcela de lucros paga aos acionistas. Essa parcela é o dividendo, previsto no estatuto e distribuído aos acionistas. A alternativa A é a correta. Juros sobre capital próprio (B) são remuneração tributada de forma diferente, direito de subscrição (C) é direito de compra de ações novas, e bonificação (D) é a entrega gratuita de novas ações.","id":"9755"},{"n":513,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"237","capn":"Questão 237 (cód. 199544297)","stem":"Um agricultor irá realizar a colheita em 4 meses e possui custo de R$ 1.000 por tonelada. Deseja fazer hedge em relação ao preço e o mercado possui as seguintes informações: Preço à vista: R$ 1.050 Preço a termo (4 meses): R$ 1.100 Opções para 4 meses: Call PE: R$ 1.100 Prêmio: R$ 50 Put PE: R$ 1.100 Prêmio: R$ 40 Qual das opções o agricultor deveria optar:","opts":[["a","Se acredita em baixa volatilidade: Comprar Put"],["b","Se acredita em baixa volatilidade: Vender Call"],["c","Vender PUT não é operação de hedge nessa situação"],["d","Comprar a termo"]],"ans":"c","exp":"Tema: hedge de preço de colheita. O agricultor teme a queda do preço da soja, então precisa de proteção de venda. Vender puts não protege, porque aumenta sua exposição à queda. Por isso a alternativa C é a correta. Comprar put (A) e vender a termo são formas de proteção, e comprar a termo (D) não protege a venda futura.","id":"199544297"},{"n":514,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"238","capn":"Questão 238 (cód. 199544298)","stem":"Um exportador vendeu ao exterior, produtos por U$ 100 milhões, a serem recebidos no prazo de 120 dias. O exportador teve diversos custos de produção que somam R$ 260 milhões e que precisam ser financiados até o recebimento das exportações. Admitindo que a taxa de juro no mercado interno esteja em 7% no período e que o dólar à vista esteja em R$ 3,15. Considere também que o mercado de swaps Dólar x Taxa Prefixada, esteja com a taxa de Variação do Dólar x 21% a.a e que existam 84 dias úteis no período. Como o exportador deveria efetuar o hedge utilizando swap Dólar x Taxa Prefixada?","opts":[["a","Dólar deveria constar na variável passiva do swap e o lucro obtido seria de R$ 58,16 milhões"],["b","Dólar deveria constar na variável ativa do swap e o lucro obtido seria de R$ 58,46 milhões"],["c","Dólar deveria constar na variável passiva do swap e o lucro obtido seria de R$ 57,46 milhões"],["d","Dólar deveria constar na variável ativa do swap e o lucro obtido seria de R$ 57,16 milhões"]],"ans":"c","exp":"Tema: hedge de exportador com swap dólar x taxa pré. O exportador recebe em dólar, então precisa de proteção contra a queda da moeda. No swap, o dólar entra na variável passiva, e o lucro indicado pela chave é de R$ 57,46 milhões. O cálculo depende das taxas de juros e dos dias úteis do período, e o texto desta edição não permite refazer a conta com segurança. Recomendo conferir a resolução original.","id":"199544298"},{"n":515,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"239","capn":"Questão 239 (cód. 199544300)","stem":"Em relação às operações a futuro negociados na BMF/BOVESPA, é correto afirmar que:","opts":[["a","são contratos intercambiáveis que possibilitam o encerramento de posições antecipadamente."],["b","são contratos intransferíveis cujas liquidações podem ser antecipadas por vontade do comprador."],["c","os contratos futuros de dólar podem ser liquidados por diferença ou fisicamente."],["d","os ajustes diários negativos podem ser cumpridos mediante fiança bancária de banco de primeira linha."]],"ans":"a","exp":"Tema: contratos futuros na B3. Os contratos futuros são intercambiáveis, e isso permite encerrar a posição antecipadamente, comprando ou vendendo o contrato de volta. A alternativa A é a correta. As alternativas B e D atribuem características erradas (intransferibilidade e fiança), e a alternativa C limita a liquidação ao dólar, sem considerar que os contratos podem ser liquidados por diferença.","id":"199544300"},{"n":516,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"240","capn":"Questão 240 (cód. 199544301)","stem":"No que se refere à tributação em derivativos, é correto afirmar que:","opts":[["a","não se pode compensar as perdas e ganhos obtidos em mercados a termo com mercados à vista para fins de cálculo do imposto."],["b","no mercado de opções, os ganhos (exceto nas operações day-trade) são tributados com alíquota de imposto de renda na fonte de 0,005% (cinco milésimos por cento)."],["c","no mercado a termo a tributação é menor quando há a liquidação física dos contratos, comparativamente aos liquidados por diferença."],["d","não se pode compensar as perdas e ganhos obtidos em opções de compra com opções de venda para fins de cálculo do imposto."]],"ans":"b","exp":"Tema: tributação em derivativos. No mercado de opções, os ganhos fora do day trade são tributados com IRRF na fonte de 0,005%, o que corresponde à alternativa B. As demais afirmações afirmam que não se pode compensar ganhos e perdas, o que é contrário à regra, ou atribuem tratamento de prazo que não é o caso.","id":"199544301"},{"n":517,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"241","capn":"Questão 241 (cód. 199544302)","stem":"Um exportador vendeu ao exterior, produtos por US$ 100 milhões, a serem recebidos no prazo de 120 dias. O exportador teve diversos custos de produção que somam R$ 260 milhões e que precisam ser financiados até o recebimento das exportações. Admitindo que a taxa de juro no mercado interno esteja em 8% no período, que o dólar à vista esteja em R$ 3,15 e no mercado a termo para 120 dias, a R$ 3,30. Se o mercado estivesse negociando uma serie de put com vencimento em 120 dias, PE = R$ 3,28 e prêmio de R$ 0,09, com o objetivo de hedge o exportador deveria: Observação: PVv :tx do dólar no vencimento","opts":[["a","vender puts; o lucro seria maior em relação ao hedge no mercado a termo se PVV < R$ 3,397."],["b","comprar puts; o lucro seria maior em relação ao hedge no mercado a termo se PVV > R$ 3,397."],["c","comprar puts; o lucro seria maior em relação ao hedge no mercado a termo se PVV > R$ 3,377."],["d","vender puts; o lucro seria maior em relação ao hedge no mercado a termo se PVV < R$ 3,390."]],"ans":"b","exp":"Tema: hedge de exportador com put de dólar. O exportador recebe dólar e se protege da queda comprando put de dólar, que garante um preço mínimo de venda. Por isso a alternativa B é a correta. O ponto de equilíbrio com o hedge a termo depende do preço de exercício, do prêmio e da taxa a termo, e a chave indica R$ 3,397. Recomendo conferir o cálculo original, porque o enunciado não traz todos os dados para refazer a conta.","id":"199544302"},{"n":518,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"242","capn":"Questão 242 (cód. 199544303)","stem":"Um determinado investidor comprou uma ação no mercado à vista e quer se proteger da queda desse ativo. Para fazer hedge dessa posição, você deveria indicar:","opts":[["a","Comprar uma call"],["b","Vender uma call"],["c","Comprar uma put"],["d","Vender uma put"]],"ans":"c","exp":"Tema: hedge de ação à vista contra queda. Para se proteger da queda, o investidor compra uma put, que dá o direito de vender a ação ao preço de exercício. A alternativa C é a correta. Vender call (B) ou comprar call (A) não protegem contra a queda, e vender put (D) aumenta a exposição.","id":"199544303"},{"n":519,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"243","capn":"Questão 243 (cód. 199544304)","stem":"Um determinado investidor faz o lançamento de uma PUT descoberta conforme dados abaixo: PUT Prêmio: 1,20 Preço Exercício: R$ 20,00 Preço de Mercado no Vencimento: R$ 25,00 Nessa situação, qual será o resultado financeiro dessa operação para esse lançador:","opts":[["a","#ERROR!"],["b","– R$ 3,80"],["c","#ERROR!"],["d","– R$ 1,20"]],"ans":"c","exp":"Tema: resultado do lançador de put descoberta. O lançador recebe o prêmio de R$ 1,20. Como o preço de mercado (R$ 25) está acima do preço de exercício (R$ 20), a put não é exercida, e o lançador fica com o prêmio. O resultado é de +R$ 1,20.\n\nO enunciado traz a alternativa C como \"#ERROR!\", que é um erro de digitação, e o resultado correto (+R$ 1,20) não aparece entre as opções. A alternativa B (−R$ 3,80) e a D (−R$ 1,20) têm os valores errados ou o sinal invertido. A chave indica C, que não tem conteúdo. Recomendo conferir o material original.","id":"199544304"},{"n":520,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"244","capn":"Questão 244 (cód. 199544305)","stem":"Um determinado investidor faz o compra de uma CALL conforme dados abaixo: CALL Prêmio: 2,50 Preço Exercício: R$ 40,00 Preço de Mercado no Vencimento: R$ 50,00 Nessa situação, qual será o resultado financeiro dessa operação para esse titular:","opts":[["a","#ERROR!"],["b","– R$ 7,50"],["c","#ERROR!"],["d","– R$ 2,50"]],"ans":"a","exp":"Tema: resultado do titular de call. O titular paga prêmio de R$ 2,50 e exerce com o preço do ativo a R$ 50, acima do exercício de R$ 40. O ganho é de (50 − 40) − 2,50 = +R$ 7,50. A alternativa B traz −R$ 7,50, com o sinal invertido, e a alternativa A é \"#ERROR!\", erro de digitação. A chave indica A, mas o resultado correto seria +R$ 7,50, que não aparece com o sinal certo. Vale conferir o material original.","id":"199544305"},{"n":521,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"245","capn":"Questão 245 (cód. 199544306)","stem":"Um determinado cliente leu em uma revista que a inflação nos próximos anos será muito alta. Porém, ele está posicionado em um investimento com taxa prefixada e o mesmo não pode ser desmontado agora. Você sugere então que ele faça uma operação de Swap, com o seguinte posicionamento:","opts":[["a","Ativo em Taxa Pré e Passivo em IPCA"],["b","Ativo em IPCA e Passivo em Taxa Pré"],["c","Ativo em IPCA e Passivo em Taxa Pós"],["d","Ativo em Taxa Pós e Passivo em IPCA"]],"ans":"b","exp":"Tema: swap para se proteger de inflação com taxa prefixada. O cliente tem ativo prefixado e teme alta da inflação. Para se proteger, ele deve ficar com ativo indexado ao IPCA e passivo em taxa prefixada, assim recebe a inflação. A alternativa B é a correta.","id":"199544306"},{"n":522,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"246","capn":"Questão 246 (cód. 199544307)","stem":"Um determinado investidor faz uma aplicação no mercado futuro do Ibovespa quando estava em 80 mil pontos. A operação é encerrada com o Ibovespa futuro em 100 mil pontos. O valor investido foi de R$ 200 mil. Qual será o retorno líquido dessa operação (desconsiderar custo de corretagem):","opts":[["a","R$ 42,5 mil"],["b","R$ 50 mil"],["c","R$ 40 mil"],["d","R$ 30 mil"]],"ans":"a","exp":"Tema: resultado de uma posição comprada em Ibovespa futuro. A operação foi aberta a 80 mil pontos e encerrada a 100 mil, com ganho de 20 mil pontos, equivalente a 25% sobre o valor investido de R$ 200 mil, o que resulta em R$ 50 mil. A chave indica A (R$ 42,5 mil), que é diferente desse cálculo. A diferença depende da regra de conversão do contrato, que o enunciado não especifica. Recomendo conferir a resolução original.","id":"199544307"},{"n":523,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"247","capn":"Questão 247 (cód. 199544310)","stem":"Seu cliente exporta máquinas para o exterior. Vende uma máquina por U$ 100 mil e receberá esse valor em 40 dias. Para se proteger (hedge) da oscilação da moeda estrangeira, qual alternativa você indica:","opts":[["a","Comprar uma Call de Dólar"],["b","Vender uma Call de Dólar"],["c","Comprar uma Put de Dólar"],["d","Vender uma Put de Dólar"]],"ans":"c","exp":"Tema: hedge de exportador. O exportador recebe dólar em 40 dias, e precisa se proteger da queda da moeda. A alternativa C é a correta: comprar put de dólar garante um preço mínimo de venda. Comprar call (A) protege contra alta, o que não é o interesse do exportador, e vender call ou put (B e D) aumenta a exposição ao risco.","id":"199544310"},{"n":524,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"248","capn":"Questão 248 (cód. 199544311)","stem":"Para o lançador, uma opção de compra, se exercida, representa:","opts":[["a","Uma obrigação de vender"],["b","Um direito de comprar"],["c","Uma obrigação de comprar"],["d","Um direito de vender"]],"ans":"a","exp":"Tema: posição do lançador de call. O lançador tem a obrigação de vender o ativo ao titular, caso ele exerça a opção. A alternativa A é a correta. O direito de comprar (B) é do titular, e a obrigação de comprar (C) pertence ao lançador de put.","id":"199544311"},{"n":525,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"249","capn":"Questão 249 (cód. 199544312)","stem":"Uma diferença entre o mercado a termo e o mercado futuro é que:","opts":[["a","No mercado a termo há ajuste diário"],["b","No mercado futuro existe ajuste diário"],["c","No mercado a termo os contratos são padronizados"],["d","No mercado futuro existe a opção de exercer o direito"]],"ans":"b","exp":"Tema: diferença entre mercado a termo e mercado futuro. O mercado futuro tem ajuste diário, que o mercado a termo não tem. A alternativa B é a correta. Ver a questão 5, que trata do mesmo tema.","id":"199544312"},{"n":526,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"250","capn":"Questão 250 (cód. 199544313)","stem":"Seu cliente possui uma dívida em dólar para pagar em 1 ano. Para se proteger da oscilação da moeda estrangeira, você o aconselha a:","opts":[["a","Comprar uma PUT de dólar"],["b","Vender uma CALL de dólar"],["c","Comprar dólar a termo"],["d","Vender dólar futuro"]],"ans":"c","exp":"Tema: hedge de dívida em dólar em um ano. O devedor deve comprar dólar a termo, travando o preço da moeda. A alternativa C é a correta. Ver a questão 7, que trata do mesmo caso.","id":"199544313"},{"n":527,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"251","capn":"Questão 251 (cód. 199544314)","stem":"Um titular de uma Call:","opts":[["a","Tem a obrigação de comprar um ativo objeto"],["b","Tem a obrigação de vender um ativo objeto"],["c","Tem o direito de comprar um ativo objeto"],["d","Tem o direito de vender um ativo objeto"]],"ans":"c","exp":"Tema: direito do titular de call. O titular tem o direito de comprar o ativo objeto, mas não a obrigação. A alternativa C é a correta. As alternativas A e B atribuem obrigações ao titular, e a alternativa D descreve a put.","id":"199544314"},{"n":528,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"252","capn":"Questão 252 (cód. 199544308)","stem":"O gráfico abaixo representa qual posição no mercado de ações:","opts":[["a","Titular de uma Call"],["b","Lançador de uma Call"],["c","Titular de uma Put"],["d","Lançador de uma Put"]],"ans":"b","exp":"Tema: posição no gráfico (lançador de call). O gráfico não aparece no texto extraído. A chave indica B. Vale conferir o gráfico original, porque a identificação depende da inclinação e do ponto de corte da linha, como nas questões 9 e 28.","id":"199544308"},{"n":529,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"253","capn":"Questão 253 (cód. 199544202010)","stem":"Ações nominativas sem suas respectivas cautelas são denominadas.","opts":[["a","Nominativas não endossáveis."],["b","Escriturais"],["c","De gozo ou fruição."],["d","Nominativas endossáveis."]],"ans":"b","exp":"Tema: ações nominativas sem cautela. Quando a ação é nominativa e não tem cautela física, ela é escritural, existindo apenas como registro eletrônico. A alternativa B é a correta.","id":"199544202010"},{"n":530,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"254","capn":"Questão 254 (cód. 199544202011)","stem":"As carteiras teóricas dos índices amplos da B3 são formadas por ativos de companhias listadas na B3. Esses ativos são:","opts":[["a","Ações e units"],["b","Ações e BDR."],["c","Ações e bônus de subscrição"],["d","Ações e debentures"]],"ans":"a","exp":"Tema: composição dos índices amplos da B3. As carteiras teóricas são formadas por ações e units de companhias listadas. A alternativa A é a correta. BDRs (B), bônus de subscrição (C) e debêntures (D) não compõem os índices amplos.","id":"199544202011"},{"n":531,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"255","capn":"Questão 255 (cód. 199544202012)","stem":"A Câmara de Ações da B3 liquida operações realizadas por meio do sistema Bovespa Fix onde são negociados os :","opts":[["a","Títulos privados de renda fixa."],["b","Títulos lastreados em moedas."],["c","Títulos de renda variável."],["d","Títulos lastreados em ouro."]],"ans":"a","exp":"Tema: Bovespa Fix. O sistema liquida operações com títulos privados de renda fixa. A alternativa A é a correta. Os demais tipos de títulos não são o objeto do Bovespa Fix.","id":"199544202012"},{"n":532,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"256","capn":"Questão 256 (cód. 199544202013)","stem":"Para a realização de operações de repasse:","opts":[["a","Os intermediários e os operadores especiais envolvidos não podem repassar operações especulativas."],["b","Os intermediários e os operadores especiais envolvidos deverão estar vinculados por contrato específico, estabelecendo os direitos e deveres de cada parte."],["c","Os intermediários e os operadores especiais envolvidos não precisam requerer à BM&F/BOVESPA a constituição de vínculos em seus sistemas."],["d","Os intermediários e os operadores especiais envolvidos deverão confirmar as operações em seus sistemas, sem a necessidade de contrato específico prévio"]],"ans":"b","exp":"Tema: operações de repasse. Os intermediários e os operadores envolvidos devem estar vinculados por contrato específico, que define os direitos e deveres de cada parte. A alternativa B é a correta. As demais afirmam que não há necessidade de contrato ou de vínculo, o que é contrário à regra.","id":"199544202013"},{"n":533,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"257","capn":"Questão 257 (cód. 199544202014)","stem":"Uma das formas das empresas captarem recursos no mercado de capitais, é negociar os títulos representativos de seu capital. O primeiro passo para isso, é contratar um ou mais intermediários financeiros, que irão atuar como líderes da distribuição, organizando a operação e solicitando o registro da mesma, como companhia aberta, junto a . Vencida essa longa etapa, a empresa deve, emitir títulos representativos do seu capital, e através dos intermediários, fazer uma , que acontece no mercado .","opts":[["a","B3 / OPA (Oferta Pública de Ações) / secundário."],["b","CVM / OPA (Oferta Pública de Ações) / secundário"],["c","B3 / IPO (Oferta Pública Inicial) / primário"],["d","CVM / IPO (Oferta Pública Inicial) / primário"]],"ans":"d","exp":"Tema: captação via mercado de capitais. Os intermediários atuam como líderes da distribuição, e o registro de companhia aberta é feito junto à CVM. Depois, a empresa faz a oferta pública inicial (IPO), que acontece no mercado primário. A alternativa D é a correta.","id":"199544202014"},{"n":534,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"258","capn":"Questão 258 (cód. 199544202015)","stem":"Celebrar contrato com instituição diferente daquela com a qual o AAI, sua firma individual ou a sociedade de que faz parte já mantiver contrato, é uma das vedações aos AAI. Porém, para a atividade de , é ressalvada a possibilidade de celebração de contrato com mais de uma instituição.","opts":[["a","Distribuição de subscrição de ações."],["b","Distribuição de valores mobiliários no mercado futuro."],["c","Distribuição de cotas de fundos de investimentos."],["d","Distribuição de cotas de clubes de investimentos."]],"ans":"c","exp":"Tema: vedações aos AAI. Um AAI não pode celebrar contrato com instituição diferente daquela com a qual já tem vínculo, mas a distribuição de cotas de fundos de investimento é a exceção que permite contratos com mais de uma instituição. A alternativa C é a correta.","id":"199544202015"},{"n":535,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"259","capn":"Questão 259 (cód. 199544202016)","stem":"A diferença básica entre um bônus de subscrição e o direito de subscrição é:","opts":[["a","O bônus tem prazo de validade e o direito de subscrição não tem."],["b","O direito de subscrição é dado/vendido pela Cia emissora a qualquer investidor e o bônus não."],["c","O direito é apenas do acionista da Cia emissora, o bônus não."],["d","Ambos, o direito de subscrição e o bônus de subscrição, não tem prazo de validade."]],"ans":"c","exp":"Tema: diferença entre bônus de subscrição e direito de subscrição. O direito de subscrição é restrito ao acionista da companhia emissora e tem prazo de validade. O bônus de subscrição é um título negociável, que pode ser emitido e vendido a qualquer investidor. A alternativa C é a correta, conforme a chave.","id":"199544202016"},{"n":536,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"260","capn":"Questão 260 (cód. 199544202026)","stem":"O montante que exceder 67% do patrimônio líquido do Clube de Investimento pode ser aplicado em outros valores mobiliários de emissão de companhias abertas, sendo vedado o lançamento de:","opts":[["a","Cotas de Fundos de Investimento Referenciado."],["b","Compra de opções."],["c","Opções a descoberto."],["d","Títulos de responsabilidade de instituição financeira."]],"ans":"c","exp":"Tema: vedações de clube de investimento. O clube não pode lançar opções a descoberto. A alternativa C é a correta. Ver a questão 177, que trata do mesmo tema.","id":"199544202026"},{"n":537,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"261","capn":"Questão 261 (cód. 199544202027)","stem":"As demonstrações contábeis dos Clubes de Investimentos devem obedecer à normas contábeis da (o):","opts":[["a","Conselho Regional de Contabilidade"],["b","BACEN"],["c","CVM"],["d","CMN"]],"ans":"c","exp":"Tema: normas contábeis dos clubes de investimento. As demonstrações dos clubes seguem as normas da CVM. A alternativa C é a correta. Ver a questão 46.","id":"199544202027"},{"n":538,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"262","capn":"Questão 262 (cód. 199544202031)","stem":"As Letras Financeiras são títulos de renda fixa, emitidos por instituições financeiras, que consistem em promessa de pagamento. Emitida com prazo superior a 2 anos, a LF visa:","opts":[["a","Aproveitar o spread bancário entre o curto e o longo prazo"],["b","Alongar a forma de captação das IF’s, melhorando o gerenciamento entre ativo e passivo"],["c","Beneficiar o investidor com menor imposto de renda"],["d","Atrair o capital externo com preferência pelo longo prazo"]],"ans":"b","exp":"Tema: finalidade da Letra Financeira com prazo acima de dois anos. A LF serve para alongar o perfil de captação das instituições, melhorando a relação entre ativos e passivos. A alternativa B é a correta.","id":"199544202031"},{"n":539,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"263","capn":"Questão 263 (cód. 199544202032)","stem":"As Letras Imobiliárias são títulos de renda fixa, geralmente emitidos com longo prazo, garantidos pelo FGC, e as principais características são:","opts":[["a","Emitidos por bancos de investimentos, destinados a captação de recursos de construtores e adquirentes de imóveis"],["b","Emitidos por bancos comerciais, destinados a captação de recursos para capital de giro de empresas em geral"],["c","Emitidos por Sociedades de Crédito Imobiliário, destinados a captação de recursos para o financiamento de construtores e adquirentes de imóveis"],["d","Emitidos por sociedades corretoras, destinados para financiar o mercado imobiliário"]],"ans":"c","exp":"Tema: Letras Imobiliárias. São títulos de renda fixa, de longo prazo, emitidos por sociedades de crédito imobiliário para captar recursos destinados ao financiamento de construtores e adquirentes de imóveis. A alternativa C é a correta. Os demais emissores (A, B e D) não são os descritos.","id":"199544202032"},{"n":540,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"264","capn":"Questão 264 (cód. 199544202033)","stem":"O Decreto nº 9.292 de 23 de fevereiro de 2018 que estabelece as características dos Títulos da Dívida Pública Mobiliária Federal interna, no art. 2º, define a LFT, que terá valor nominal:","opts":[["a","Múltiplo de R$ 1.000,00 rendimento definido pelo deságio sobre o valor nominal e pagamento de juros semestrais."],["b","Múltiplo de R$ 1.000,00, rendimento definido pelo deságio sobre o valor nominal sem pagamento de juros."],["c","Múltiplo de R$ 1.000,00, na data-base, atualização do valor nominal pela taxa média ajustada dos financiamentos diários apurados no Sistema Especial de Liquidação e de Custódia – SELIC."],["d","Múltiplo de R$ 1.000,00, na data-base, atualização do valor nominal pela variação da cotação de venda do dólar americano e pagamento de juros semestrais."]],"ans":"c","exp":"Tema: características da LFT segundo o Decreto 9.292/2018. A LFT tem valor nominal múltiplo de R$ 1.000, atualizado na data-base pela taxa média ajustada dos financiamentos diários apurados no Selic. A alternativa C é a correta. As alternativas A e B descrevem título prefixado ou com juros semestrais, que não são características da LFT, e a D atualiza pelo dólar, o que não se aplica.","id":"199544202033"},{"n":541,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"265","capn":"Questão 265 (cód. 199544202034)","stem":"Conforme o decreto 9.292/18, as NTN-B terão como característica:","opts":[["a","Valor nominal na data base múltiplo de R$ 1.000 e atualização do valor nominal pela variação do IPCA"],["b","Valor nominal na data base múltiplo de R$ 1.000 e atualização do valor nominal pela variação do IGP-M"],["c","Valor nominal na data base múltiplo de R$ 1.000 e rentabilidade prefixada"],["d","Valor nominal na data base múltiplo de R$ 1.000 e atualização do valor nominal pela variação da taxa básica de juros"]],"ans":"a","exp":"Tema: características da NTN-B segundo o Decreto 9.292/2018. A NTN-B tem valor nominal na data-base múltiplo de R$ 1.000 e atualização pela variação do IPCA. A alternativa A é a correta. As demais atualizam pelo IGP-M, pela taxa básica de juros ou são prefixadas, o que não é a NTN-B.","id":"199544202034"},{"n":542,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"266","capn":"Questão 266 (cód. 199544202035)","stem":"Nos mercados agrícolas ou pecuários, em muitos casos há sazonalidade nos preços devido às épocas de safra ou entressafra. A respeito dos preços futuros praticados em tais mercados é correto afirmar:","opts":[["a","Os preços futuros de equilíbrio devem ser maiores do que os seus equivalentes no mercado a termo, em razão da maior liquidez"],["b","Os preços futuros de equilíbrio devem ser crescentes em função do prazo."],["c","Os preços futuros de equilíbrio para diferentes vencimentos podem apresentar reduções ou aumentos, mantendo-se, entretanto, superiores aos preços à vista."],["d","Os preços futuros de equilíbrio para diferentes vencimentos podem apresentar reduções ou aumentos, podendo, inclusive, ser inferiores aos preços à vista"]],"ans":"d","exp":"Tema: preços futuros em mercados agrícolas com sazonalidade. Os preços futuros de equilíbrio podem subir ou cair entre vencimentos, e podem ficar abaixo do preço à vista em alguns casos. A alternativa D é a correta. A alternativa A diz que o futuro é maior por liquidez, o que não é a regra, e a alternativa B exige alta sempre, o que não acontece em safras.","id":"199544202035"},{"n":543,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"267","capn":"Questão 267 (cód. 199544202036)","stem":"Quanto aos preços dos derivativos, é correto afirmar que:","opts":[["a","Os preços dos mercados futuros tendem a ser inferiores aos dos mercados a termo devido aos ajustes diários."],["b","Os mercados futuros de Depósito Interfinanceiro são predominantemente especulativos devido à liquidação exclusivamente financeira, sem que ocorra entrega de títulos."],["c","Preços futuros e preços à vista estão estreitamente relacionados, devido à possibilidade da montagem de arbitragens envolvendo operações à vista e a futuro."],["d","O modelo de precificação de opções de Black&Scholes é bastante utilizado e permite a precificação de calls e puts do tipo americano."]],"ans":"c","exp":"Tema: relação entre preços futuros e à vista. Os preços futuros e à vista estão estreitamente relacionados, porque a arbitragem entre as duas operações mantém os preços alinhados. A alternativa C é a correta. Black-Scholes (D) não se aplica a opções americanas, e os futuros não têm ajuste que os torne inferiores ao termo (A).","id":"199544202036"},{"n":544,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"268","capn":"Questão 268 (cód. 199544202037)","stem":"Os produtores e compradores de soja podem efetuar as seguintes operações de hedge no mercado:","opts":[["a","Produtores: venda de puts de soja ou implementação de swap de soja se o preço estiver na variável passiva do swap."],["b","Compradores: compra de puts de soja ou implementação de swap de soja se o preço estiver na variável ativa do swap."],["c","Produtores: compra de puts de soja ou venda de soja a termo."],["d","Compradores: compra de soja no mercado futuro de soja ou compra de puts de soja."]],"ans":"c","exp":"Tema: hedge de produtores e compradores de soja. O produtor se protege da queda comprando put ou vendendo a termo. A alternativa C é a correta. Vender put (A) aumenta a exposição do produtor, e as demais alternativas invertem o papel de produtor e comprador.","id":"199544202037"},{"n":545,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"269","capn":"Questão 269 (cód. 199544202038)","stem":"Em relação às operações a futuro, é correto afirmar que:","opts":[["a","Os contratos são negociados para determinados prazos e não para determinadas datas de vencimento."],["b","Os vendedores descobertos estão sujeitos a ajustes diários negativos, mas não aos positivos."],["c","Há mercados futuros com volumes de negociação bastante elevados e tanto podem ser utilizados com objetivos de hedge como de especulação."],["d","O mercado futuro de Depósito Interfinanceiro destina-se principalmente à especulação, devido à não existência da liquidação física."]],"ans":"c","exp":"Tema: mercados futuros. Há mercados futuros com volume de negociação muito alto, usados tanto para hedge quanto para especulação. A alternativa C é a correta. Os contratos são negociados para datas de vencimento padronizadas, e não apenas para prazos (A).","id":"199544202038"},{"n":546,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"270","capn":"Questão 270 (cód. 199544202039)","stem":"Sobre os benefícios dos derivativos para os agentes econômicos em geral e para empresas em particular, é correto afirmar que:","opts":[["a","A não implementação de hedge pela maior parte das empresas faz com que elas oscilem entre situações de grandes lucros ou grandes prejuízos, o que é bom para administradores prudentes."],["b","A implementação de hedges por parte da maioria das empresas tende a gerar confirmação de suas margens de lucro esperadas, reduzindo as chances de quebras e contribuído para o aumento da produção e do emprego."],["c","A implementação de hedges por parte da maioria das empresas tende a engessar o mercado e retirar as possibilidades de grandes lucros, o que prejudica a renda e o emprego."],["d","A não implementação de hedge pela maior parte das empresas faz com que elas mantenham o risco de mercado o que é fundamental para o dinamismo e o aumento da produção e do emprego."]],"ans":"b","exp":"Tema: benefícios dos derivativos para empresas. Quando a maioria das empresas faz hedge, as margens de lucro ficam mais previsíveis, o que reduz quebras e contribui para produção e emprego. A alternativa B é a correta. As demais alternativas afirmam que o hedge engessa o mercado ou que a falta de proteção é benéfica, o que não corresponde à teoria.","id":"199544202039"},{"n":547,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"271","capn":"Questão 271 (cód. 199544202040)","stem":"As negociações de um determinado ativo negociado no mercado futuro de ações, serão suspensas, sempre que as negociações com esses mesmos ativos forem suspensas no mercado:","opts":[["a","Derivativos."],["b","À termo."],["c","À vista"],["d","De opções."]],"ans":"c","exp":"Tema: suspensão de futuro de ações. A negociação de um futuro de ações é suspensa quando a negociação do ativo à vista é suspensa. A alternativa C é a correta.","id":"199544202040"},{"n":548,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"272","capn":"Questão 272 (cód. 199544202041)","stem":"Tipo de direito de compra que pode ser exercido por seu titular a qualquer momento até a data limite (data de exercício). Trata-se de uma:","opts":[["a","Put americana"],["b","Call americana"],["c","Put europeia"],["d","Call europeia"]],"ans":"b","exp":"Tema: tipos de opção de compra. A call americana pode ser exercida a qualquer momento até o vencimento. A alternativa B é a correta. A call europeia (D) só pode ser exercida na data de vencimento, e a put (A e C) é a opção de venda.","id":"199544202041"},{"n":549,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"273","capn":"Questão 273 (cód. 199543088)","stem":"Um determinado investidor comprou uma ação no mercado à vista e quer se proteger da queda desse ativo. Para fazer hedge dessa posição, você deveria indicar:","opts":[["a","Comprar uma call"],["b","Vender uma call"],["c","Comprar uma put"],["d","Vender uma put"]],"ans":"c","exp":"Tema: hedge de ação à vista contra queda. Igual à questão 242: comprar put protege contra queda. A alternativa C é a correta.","id":"199543088"},{"n":550,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"274","capn":"Questão 274 (cód. 199543089)","stem":"Uma debênture emitida pela Petrobrás com valor de face de R$ 1.000 está sendo negociada com deságio de 12%. A mesma paga cupom semestral com taxa de 10% a.a. O prazo é de 2 anos. Qual o YTM desse título:","opts":[["a","8,54% a.s"],["b","8,54% a.a"],["c","8,67% a.s"],["d","8,67% a.a"]],"ans":"a","exp":"Tema: YTM de debênture com deságio de 12%. O título tem valor de face de R$ 1.000, negociado a R$ 880, com cupom semestral de 5% (10% ao ano dividido por dois) e prazo de dois anos, ou quatro semestres. A taxa que iguala o valor presente a R$ 880 é de cerca de 8,67% ao semestre. Pelas contas, a alternativa C (8,67% a.s.) é a correta.\n\nA chave indica A (8,54% a.s.), que dá um valor presente de cerca de R$ 884, acima do preço de R$ 880. Essa é uma divergência de chave. Vale conferir o material original.","id":"199543089"},{"n":551,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"275","capn":"Questão 275 (cód. 199543092)","stem":"Tipo de opção que pode ser exercida a qualquer momento até a data de vencimento:","opts":[["a","Europeia"],["b","Brasileira"],["c","Americana"],["d","Opção de compra"]],"ans":"c","exp":"Tema: opção que pode ser exercida a qualquer momento até o vencimento. É a opção americana. A alternativa C é a correta. A europeia (A) só pode ser exercida no vencimento, e a brasileira (B) não é um tipo de opção.","id":"199543092"},{"n":552,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"276","capn":"Questão 276 (cód. 199543093)","stem":"Trata-se de uma informação que deve constar, obrigatoriamente, na escritura de uma debênture:","opts":[["a","A informação de intervenção de um Agente Fiduciário"],["b","A classificação de risco concedida por uma agência de Rating de Crédito"],["c","Direitos iguais para os detentores de todas as debêntures, independente da série que pertencer"],["d","Informação de que o Agente Fiduciário irá honrar o risco de não pagamento por parte do emissor da debênture"]],"ans":"a","exp":"Tema: informação obrigatória na escritura de debênture. A presença do agente fiduciário, que representa os debenturistas, é exigida na escritura. A alternativa A é a correta. Ver a questão 138.","id":"199543093"},{"n":553,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"277","capn":"Questão 277 (cód. 199543094)","stem":"Uma S.A não financeira está necessitando de recursos para capital de giro. Uma opção para captar recursos de forma rápida, seria:","opts":[["a","Ações"],["b","CDB"],["c","Notas Promissórias"],["d","LCI"]],"ans":"c","exp":"Tema: captação rápida para capital de giro. A nota promissória é o instrumento de curto prazo mais rápido para empresas não financeiras. A alternativa C é a correta. Ver a questão 139.","id":"199543094"},{"n":554,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"278","capn":"Questão 278 (cód. 199543096)","stem":"Uma debênture conversível é aquela que:","opts":[["a","Pode ser convertida em dinheiro a qualquer momento"],["b","Pode ser recomprada pelo emissor"],["c","Pode ser convertida em ações na data do seu resgate"],["d","Pode ser convertida em ações a qualquer momento"]],"ans":"c","exp":"Tema: debênture conversível. Ela pode ser convertida em ações nas datas e condições definidas na escritura. A alternativa C é a chave. Ver a questão 140, com a mesma ressalva sobre a escritura.","id":"199543096"},{"n":555,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"279","capn":"Questão 279 (cód. 199543097)","stem":"Sobre o Certificado de Depósito Bancário - CDB:","opts":[["a","Possui garantia limitada do Fundo Garantidor de Crédito - FGC"],["b","Tem prazo máximo de 720 dias"],["c","Possui tributação diferenciada se for prefixado ou pós fixado"],["d","Possui isenção de I.R para aplicações até R$ 20 mil"]],"ans":"a","exp":"Tema: CDB e FGC. O CDB tem garantia limitada do FGC, de até R$ 250 mil por titular e por instituição. A alternativa A é a correta. Ver a questão 196.","id":"199543097"},{"n":556,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"280","capn":"Questão 280 (cód. 199543098)","stem":"Seu cliente ao operar no Tesouro Direto deseja aplicar em um título que seja corrigido pela inflação e que não tenha risco de reinvestimento. Nesse caso, deverá escolher:","opts":[["a","Tesouro IPCA + com Juros Semestrais (NTN-B)"],["b","Tesouro Selic (LFT)"],["c","Tesouro Prefixado (LTN)"],["d","Tesouro IPCA + (NTN-B Principal)"]],"ans":"d","exp":"Tema: Tesouro Direto para inflação sem risco de reinvestimento. O título é o Tesouro IPCA+ (NTN-B Principal), que paga apenas o principal corrigido, sem cupons. A alternativa D é a correta. Ver a questão 197.","id":"199543098"},{"n":557,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"281","capn":"Questão 281 (cód. 199543100)","stem":"Título emitido pelo governo americano que é atualizado pela inflação:","opts":[["a","T-Bond"],["b","T-Bill"],["c","TIPS"],["d","T-Note"]],"ans":"c","exp":"Tema: título público americano atualizado pela inflação. O TIPS (Treasury Inflation-Protected Securities) tem o principal corrigido pelo CPI dos Estados Unidos. A alternativa C é a correta. T-Bond, T-Bill e T-Note são títulos nominais, sem correção pela inflação.","id":"199543100"},{"n":558,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"282","capn":"Questão 282 (cód. 199543101)","stem":"Seu cliente comprou um lote de LTN com vencimento para 2021. O risco de liquidez presente nessa aplicação está na possibilidade de:","opts":[["a","Alteração do valor do título em face das mudanças da taxa de juros"],["b","Impossibilidade de vender o ativo antes de 2021 pelo seu preço justo, por falta de compradores no mercado"],["c","Não pagamento por parte do emissor do título do compromisso"],["d","Falta de cobertura do FGC para o título"]],"ans":"b","exp":"Tema: risco de liquidez de uma LTN. O risco está na impossibilidade de vender o título antes do vencimento pelo preço justo, por falta de compradores. A alternativa B é a correta. As demais descrevem risco de mercado (A), risco de crédito (C) e a ausência de cobertura do FGC, que não é o risco de liquidez.","id":"199543101"},{"n":559,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"283","capn":"Questão 283 (cód. 199543102)","stem":"Sobre a remuneração da poupança:","opts":[["a","Se dá pela média do valor mantido durante o período"],["b","Se dá pelo menor saldo durante um período"],["c","Se dá pelo maior saldo durante um período"],["d","Se dá pela soma dos saldos de um determinado período"]],"ans":"b","exp":"Tema: remuneração da poupança. Os juros da poupança são calculados sobre o menor saldo do período, e não sobre a média ou o maior saldo. A alternativa B é a correta. Ver a questão 73, que trata do mesmo conceito.","id":"199543102"},{"n":560,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"284","capn":"Questão 284 (cód. 199543103)","stem":"Um cliente foi até o banco para saber mais informações sobre a nova poupança. O gerente o informa que: I. A rentabilidade é de 0,5% a.m + T.R independente da meta da Taxa Selic II. É isento de Imposto de Renda para Pessoa Física, para aplicações de qualquer valor III. Possui cobertura do Fundo Garantidor de Crédito - FGC Está (ão) correto (s):","opts":[["a","I e II"],["b","I e III"],["c","II e III"],["d","I, II e III"]],"ans":"c","exp":"Tema: regras da poupança. Analisando:\n\nI. Errado. A rentabilidade de 0,5% ao mês mais TR só vale quando a Selic está acima de 8,5% ao ano. Quando está abaixo, a regra muda, e o item não é verdadeiro sem essa condição.\n\nII. Correto. A poupança é isenta de IR para pessoa física, independentemente do valor.\n\nIII. Correto. A poupança tem cobertura do FGC.\n\nA alternativa C (II e III) é a correta.","id":"199543103"},{"n":561,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"285","capn":"Questão 285 (cód. 199543104)","stem":"Responsável pelo recolhimento do Imposto de Renda no mercado de ações:","opts":[["a","Próprio investidor"],["b","Bolsa de valores"],["c","Corretora de valores"],["d","Administrador"]],"ans":"a","exp":"Tema: responsável pelo IR nas operações com ações. O investidor é o responsável pelo recolhimento do IR devido, por DARF, quando o ganho ultrapassa a isenção. A alternativa A é a correta. Ver a questão 141.","id":"199543104"},{"n":562,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"286","capn":"Questão 286 (cód. 199543105)","stem":"Quando um cliente faz uma operação com lucro, no mercado de ações, não day trade, acima de R$ 20 mil, essa operação será tributada com qual alíquota de I.R:","opts":[["a","20%"],["b","15%"],["c","Dependo do prazo"],["d","Isento"]],"ans":"b","exp":"Tema: IR em ações não day trade com lucro acima de R$ 20 mil no mês. A alíquota é de 15%, porque as vendas superaram o limite de isenção. A alternativa B é a correta. Ver a questão 142.","id":"199543105"},{"n":563,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"287","capn":"Questão 287 (cód. 199543106)","stem":"Seu cliente compra um Título Tesouro IPCA + Com Juros Semestrais 2045. Com relação à tributação do Imposto de Renda:","opts":[["a","Ocorrerá somente no vencimento do título."],["b","Ocorrerá no pagamento dos juros semestrais e também no vencimento do título, conforme tabela regressiva."],["c","Ocorrerá no pagamento dos juros semestrais e também no vencimento do título, conforme tabela progressiva."],["d","Ocorrerá somente no pagamento dos juros semestrais."]],"ans":"b","exp":"Tema: IR sobre NTN-B com juros semestrais. O IR incide sobre os juros pagos semestralmente e também sobre o rendimento no vencimento, conforme a tabela regressiva. A alternativa B é a correta. Ver a questão 199.","id":"199543106"},{"n":564,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"288","capn":"Questão 288 (cód. 199543107)","stem":"Seu cliente pessoa física deseja um produto com vantagem tributária e garantido pelo FGC. Você deveria indicar:","opts":[["a","CDB"],["b","LCI"],["c","Ações"],["d","Debêntures Incentivadas"]],"ans":"b","exp":"Tema: produto com vantagem tributária e garantia do FGC. A LCI é isenta de IR para pessoa física e tem garantia do FGC. A alternativa B é a correta. Ver a questão 200.","id":"199543107"},{"n":565,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"289","capn":"Questão 289 (cód. 199543108)","stem":"Com relação ao imposto de renda (I.R) em uma aplicação de Certificado de Depósito Bancário - CDB:","opts":[["a","Ocorre nos últimos dias úteis de Maio e Novembro"],["b","Incide com a tabela regressiva do I.R sobre o valor total resgatado pelo cliente"],["c","Incide com a tabela regressiva do I.R sobre o valor total do rendimento do cliente"],["d","Incide com a tabela progressiva do I.R sobre o valor total do rendimento do cliente"]],"ans":"c","exp":"Tema: IR sobre CDB. A tabela regressiva incide sobre o rendimento do cliente, e não sobre o valor total resgatado. A alternativa C é a correta. Ver a questão 201.","id":"199543108"},{"n":566,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"290","capn":"Questão 290 (cód. 199543109)","stem":"Um determinado investidor faz o lançamento de uma PUT descoberta conforme dados abaixo: PUT Prêmio: 1,20 Preço Exercício: R$ 20,00 Preço de Mercado no Vencimento: R$ 25,00 Nessa situação, qual será o resultado financeiro dessa operação para esse lançador:","opts":[["a","#ERROR!"],["b","– R$ 3,80"],["c","#ERROR!"],["d","– R$ 1,20"]],"ans":"c","exp":"Tema: resultado do lançador de put descoberta. O lançador recebe o prêmio de R$ 1,20. Como o preço de mercado (R$ 25) está acima do preço de exercício (R$ 20), a put não é exercida, e o resultado é de +R$ 1,20.\n\nA alternativa C está como \"#ERROR!\", um erro de digitação, e o resultado correto não aparece entre as opções. A chave indica C, sem conteúdo. Esta questão repete a questão 243. Vale conferir o material original.","id":"199543109"},{"n":567,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"291","capn":"Questão 291 (cód. 199543110)","stem":"Um determinado investidor faz o compra de uma CALL conforme dados abaixo: CALL Prêmio: 2,50 Preço Exercício: R$ 40,00 Preço de Mercado no Vencimento: R$ 50,00 Nessa situação, qual será o resultado financeiro dessa operação para esse lançador:","opts":[["a","#ERROR!"],["b","– R$ 7,50"],["c","#ERROR!"],["d","– R$ 2,50"]],"ans":"b","exp":"Tema: resultado do lançador de call. O lançador recebe o prêmio de R$ 2,50 e, como o preço de mercado (R$ 50) está acima do preço de exercício (R$ 40), é obrigado a vender a R$ 40. O resultado é de 2,50 − (50 − 40) = −R$ 7,50. A alternativa B é a correta.\n\nEsta questão é a versão para o lançador da questão 244, que pergunta pelo titular. Para o titular, o resultado seria +R$ 7,50, e não −R$ 7,50, o que mostra que a questão 244 tem a chave divergente.","id":"199543110"},{"n":568,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"292","capn":"Questão 292 (cód. 199543111)","stem":"Sobre debêntures, assinale a alternativa correta:","opts":[["a","Dá direito a voto para os detentores nas assembleias da empresa"],["b","Possui participação nos lucros da companhia emissora"],["c","Em nenhuma hipótese pode ser convertida em ações"],["d","Pode ter sua rentabilidade repactuada, se essa cláusula estiver na escritura"]],"ans":"d","exp":"Tema: repactuação de debêntures. A rentabilidade pode ser repactuada quando a cláusula estiver prevista na escritura de emissão. A alternativa D é a correta. Ver a questão 143.","id":"199543111"},{"n":569,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"293","capn":"Questão 293 (cód. 199543112)","stem":"Para um investidor que deseja proteção do Fundo Garantidor de Crédito e também economia fiscal, você deveria recomendar:","opts":[["a","Debêntures Incentivadas"],["b","CDB"],["c","LCI"],["d","CRI"]],"ans":"c","exp":"Tema: proteção do FGC com economia fiscal. A LCI tem garantia do FGC e é isenta de IR para pessoa física. A alternativa C é a correta. CDB (B) tem garantia, mas é tributado, e as debêntures incentivadas (A) e o CRI (D) não têm garantia do FGC.","id":"199543112"},{"n":570,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"294","capn":"Questão 294 (cód. 199543113)","stem":"O dividendo é a divisão do lucro de uma companhia. E é um direito do qual o acionista:","opts":[["a","Pode ser privado através de assembleia"],["b","Pode ser privado através de determinação do presidente da companhia"],["c","Pode ser privado através do estatuto da companhia"],["d","Não pode ser privado"]],"ans":"d","exp":"Tema: direito ao dividendo. O dividendo é um direito do acionista e não pode ser suprimido por assembleia, presidente ou estatuto. A alternativa D é a correta. Ver a questão 144.","id":"199543113"},{"n":571,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"295","capn":"Questão 295 (cód. 199543114)","stem":"Um determinado cliente leu em uma revista que a inflação nos próximos anos será muito alta. Porém, ele está posicionado em um investimento com taxa prefixada e o mesmo não pode ser desmontado agora. Você sugere então que ele faça uma operação de Swap, com o seguinte posicionamento:","opts":[["a","Ativo em Taxa Pré e Passivo em IPCA"],["b","Ativo em IPCA e Passivo em Taxa Pré"],["c","Ativo em IPCA e Passivo em Taxa Pós"],["d","Ativo em Taxa Pós e Passivo em IPCA"]],"ans":"b","exp":"Tema: swap para se proteger de inflação com ativo prefixado. O cliente deve ficar com ativo indexado ao IPCA e passivo em taxa prefixada, para receber a inflação. A alternativa B é a correta. Ver a questão 245.","id":"199543114"},{"n":572,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"296","capn":"Questão 296 (cód. 199543115)","stem":"Um determinado investidor fez uma aplicação em debêntures pelo prazo de 181 dias e obteve lucro de R$ 421 mil. Com relação à tributação, analise os itens abaixo: I. A Instituição Emissora irá reter o valor do imposto devido II. A alíquota do imposto de renda é de 15% III. A base de cálculo para cobrança do I.R é o rendimento da operação. Está (ão) correto (s):","opts":[["a","I e II"],["b","I e III"],["c","Apenas I"],["d","Apenas III"]],"ans":"b","exp":"Tema: IR sobre debêntures aplicadas por 181 dias. Analisando:\n\nI. Correto. A instituição retém o IR na fonte.\n\nII. Errado. Para 181 a 360 dias, a alíquota é de 20%, e não de 15%.\n\nIII. Correto. A base de cálculo é o rendimento da operação.\n\nA alternativa B (I e III) é a correta. Ver a questão 145.","id":"199543115"},{"n":573,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"297","capn":"Questão 297 (cód. 199543116)","stem":"Um determinado investidor faz uma aplicação no mercado futuro do Ibovespa quando estava em 80 mil pontos. A operação é encerrada com o Ibovespa futuro em 100 mil pontos. O valor investido foi de R$ 200 mil. Qual será o retorno líquido dessa operação (desconsiderar custo de corretagem):","opts":[["a","R$ 42,5 mil"],["b","R$ 50 mil"],["c","R$ 40 mil"],["d","R$ 30 mil"]],"ans":"a","exp":"Tema: resultado de uma posição comprada em Ibovespa futuro. Ver a questão 246. A análise é a mesma: o ganho de 20 mil pontos sobre o investimento de R$ 200 mil resulta em R$ 50 mil, e a chave indica R$ 42,5 mil. A diferença depende da regra de conversão do contrato, que o enunciado não especifica. Recomendo conferir a resolução original.","id":"199543116"},{"n":574,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"298","capn":"Questão 298 (cód. 199543117)","stem":"Título Público do tipo zero cupom e negociado com deságio sobre o valor de face:","opts":[["a","LTN"],["b","LFN"],["c","NTN-B"],["d","NTN-F"]],"ans":"a","exp":"Tema: título público zero cupom negociado com deságio. A LTN é o título zero cupom, cujo rendimento vem do deságio sobre o valor nominal. A alternativa A é a correta. Ver a questão 202.","id":"199543117"},{"n":575,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"299","capn":"Questão 299 (cód. 199543118)","stem":"Seu cliente deseja um investimento que conte com proteção contra a inflação. Você deveria indicar:","opts":[["a","Letra Financeira do Tesouro – LFT"],["b","Letra de Crédito Imobiliário – LCI"],["c","Nota do Tesouro Nacional – Série B – NTN-B"],["d","Nota do Tesouro Nacional – Série F – NTN-F"]],"ans":"c","exp":"Tema: proteção contra inflação. A NTN-B é o título público indexado ao IPCA. A alternativa C é a correta. Ver a questão 203.","id":"199543118"},{"n":576,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"300","capn":"Questão 300 (cód. 199543119)","stem":"Um investimento de R$ 10 mil em uma Letra de Câmbio por 150 dias corridos com rentabilidade de 5% a.p terá qual valor de resgate líquido.","opts":[["a","R$ 10.500,80"],["b","R$ 10.387,50"],["c","R$ 10.667,90"],["d","R$ 10.880,99"]],"ans":"b","exp":"Tema: resgate líquido de letra de câmbio em 150 dias. Ver a questão 204. Com R$ 10.000 aplicados a 5% no período, o rendimento bruto é de R$ 500, e o IR de 22,5% sobre esse rendimento é de R$ 112,50. O resgate líquido é de R$ 10.387,50, que é a alternativa B.","id":"199543119"},{"n":577,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"301","capn":"Questão 301 (cód. 199543120)","stem":"São ações que dão direito a voto nas assembleias da companhia:","opts":[["a","Ordinárias"],["b","Preferenciais"],["c","Subordinadas"],["d","De fruição"]],"ans":"a","exp":"Tema: ações com direito de voto. As ações ordinárias (ON) dão direito a voto nas assembleias. A alternativa A é a correta. Ver a questão 146.","id":"199543120"},{"n":578,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"302","capn":"Questão 302 (cód. 199543122)","stem":"Sobre o Juros Sobre Capital Próprio – JSCP, assinale a alternativa correta:","opts":[["a","São isentos de Imposto de Renda e se originam em lucros retidos"],["b","Se originam de lucros retidos e possuem I.R conforme tabela regressiva do I.R"],["c","São os lucros da companhia sendo distribuídos e são isentos de I.R"],["d","Se originam de lucros retidos e possuem I.R com alíquota única de 15%"]],"ans":"d","exp":"Tema: JSCP. O JSCP se origina de lucros e tem IR de alíquota única de 15%. A alternativa D é a correta. Ver a questão 147.","id":"199543122"},{"n":579,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"303","capn":"Questão 303 (cód. 199543123)","stem":"Com relação ao Mercado Primário, assinale a alternativa correta:","opts":[["a","É onde são emitidos títulos pela primeira vez e os recursos captados vão para os acionistas"],["b","É onde são emitidos títulos pela primeira vez e os recursos captados vão para a empresa emissora"],["c","É onde são comercializados títulos já existentes e os recursos captados vão para a empresa"],["d","É onde são comercializados títulos já existentes e os recursos captados vão para os atuais acionistas"]],"ans":"b","exp":"Tema: mercado primário. É onde os títulos são emitidos pela primeira vez, e os recursos vão para a empresa emissora. A alternativa B é a correta. Ver a questão 148.","id":"199543123"},{"n":580,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"304","capn":"Questão 304 (cód. 199543124)","stem":"Número máximo de participantes de um Clube de Ações:","opts":[["a","50"],["b","150"],["c","3"],["d","30"]],"ans":"a","exp":"Tema: número máximo de participantes de clube de ações. O limite é de 50 cotistas. A alternativa A é a correta. Ver a questão 179.","id":"199543124"},{"n":581,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"305","capn":"Questão 305 (cód. 199543125)","stem":"Um determinado cliente fez uma aplicação em um CDB pelo prazo de 200 dias. Qual será a tributação no resgate:","opts":[["a","IOF e IR (20%)"],["b","IOF e IR (22,50%)"],["c","Somente IR (22,50%)"],["d","Somente IR (20%)"]],"ans":"d","exp":"Tema: tributação de CDB no resgate após 200 dias. A alíquota regressiva de 20% se aplica à faixa de 181 a 360 dias, e como o resgate é após 30 dias, não há IOF. A alternativa D é a correta. Ver a questão 205.","id":"199543125"},{"n":582,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"306","capn":"Questão 306 (cód. 199543126)","stem":"Se um cliente investir em Letra Financeira do Tesouro – LFT, terá sua rentabilidade:","opts":[["a","Creditada semestralmente atualizada pela Taxa Selic"],["b","Creditada semestralmente atualizada pela Taxa CDI"],["c","Creditada no vencimento do título, atualizada pela Taxa Selic"],["d","Creditada no vencimento do título, atualizada pela Taxa CDI"]],"ans":"c","exp":"Tema: rentabilidade da LFT. A LFT paga no vencimento, atualizada pela Selic. A alternativa C é a correta. Ver a questão 206.","id":"199543126"},{"n":583,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"307","capn":"Questão 307 (cód. 199543127)","stem":"Uma aplicação realizada em caderneta de poupança, em 2015, por uma pessoa física, terá a sua rentabilidade:","opts":[["a","Creditada mensalmente com taxa de 0,5% ao mês"],["b","Creditada diariamente com taxa de 0,5% ao mês"],["c","Atrelada a Taxa Selic, se essa estiver abaixo de 9% ao ano"],["d","Atrelada a Taxa Selic, se essa estiver abaixo de 8,5% ao ano"]],"ans":"d","exp":"Tema: poupança em 2015. Quando a Selic está abaixo de 8,5% ao ano, a poupança passa a render pela Selic, mais TR. A alternativa D é a correta, conforme a regra da época.","id":"199543127"},{"n":584,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"308","capn":"Questão 308 (cód. 199543128)","stem":"Os Títulos Públicos Federais são emitidos por qual órgão:","opts":[["a","BACEN"],["b","Tesouro Nacional"],["c","Banco do Brasil"],["d","CMN"]],"ans":"b","exp":"Tema: emissor dos títulos públicos federais. Os títulos são emitidos pelo Tesouro Nacional, que administra a dívida pública da União. A alternativa B é a correta. Ver a questão 44.","id":"199543128"},{"n":585,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"309","capn":"Questão 309 (cód. 199543129)","stem":"Responsável pelo recolhimento do Imposto de Renda que incide sobre as aplicações em Certificado de Depósito Bancário – CDB:","opts":[["a","Instituição que emitiu o certificado"],["b","Próprio investidor"],["c","Bolsa de Valores"],["d","Bacen"]],"ans":"a","exp":"Tema: responsável pelo IR sobre CDB. A instituição que emitiu o certificado retém o imposto. A alternativa A é a correta. Ver a questão 207.","id":"199543129"},{"n":586,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"310","capn":"Questão 310 (cód. 199543130)","stem":"O Governo Federal emite títulos públicos para financiar a sua dívida através do Tesouro Nacional. Uma das formas de comercialização desses títulos é através do Tesouro Direto, que possui como característica:","opts":[["a","Títulos que podem ser comprados sem nenhum limite de valor"],["b","Liquidez diária para os títulos através do programa de recompra do Tesouro Nacional"],["c","Garantia do Fundo Garantidor de Crédito - FGC para os títulos emitidos"],["d","Oferta de títulos privados para a realização de investimentos"]],"ans":"b","exp":"Tema: liquidez dos títulos públicos. O Tesouro Direto oferece liquidez diária, por meio do programa de recompra do Tesouro Nacional, que permite ao investidor vender o título antes do vencimento. A alternativa B é a correta. As demais alternativas afirmam que o título é ilíquido, o que não é a regra desse programa.","id":"199543130"},{"n":587,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"311","capn":"Questão 311 (cód. 199543131)","stem":"São títulos que possuem garantia do FGC:","opts":[["a","CDB, LCI e LCA"],["b","CDB, LCI e Ações"],["c","CDB, LCI e Debêntures"],["d","LCI, LCA e Ações"]],"ans":"a","exp":"Tema: títulos com garantia do FGC. CDB, LCI e LCA têm garantia do FGC, dentro dos limites. A alternativa A é a correta. Debêntures e títulos públicos não têm essa garantia.","id":"199543131"},{"n":588,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"312","capn":"Questão 312 (cód. 199543132)","stem":"Um investidor pessoa física fez uma aplicação em LCI e resgatou 80 dias depois com rentabilidade acima de R$ 50 mil. Nesse caso:","opts":[["a","Deverá pagar I.R com alíquota de 22,50%"],["b","Deverá pagar I.R com alíquota de 15%"],["c","Estará isento do I.R"],["d","Deverá pagar I.R com alíquota de 17,50%"]],"ans":"c","exp":"Tema: IR sobre LCI para pessoa física. A LCI é isenta de IR para pessoa física, independentemente do rendimento e do prazo. A alternativa C é a correta. Ver a questão 208.","id":"199543132"},{"n":589,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"313","capn":"Questão 313 (cód. 199543133)","stem":"Com relação à Letra de Crédito Imobiliário – LCI, assinale a alternativa correta:","opts":[["a","Podem ser emitidas por qualquer banco"],["b","São lastreadas em financiamento imobiliário"],["c","Não possuem garantia do FGC"],["d","São emitidas por empresas que realizam construções de imóveis"]],"ans":"b","exp":"Tema: características da LCI. A LCI é lastreada em financiamentos imobiliários. A alternativa B é a correta. Ver a questão 209.","id":"199543133"},{"n":590,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"314","capn":"Questão 314 (cód. 199543134)","stem":"Responsável pelo recolhimento do I.R na fonte nas operações com ações:","opts":[["a","Próprio investidor"],["b","Bolsa de valores"],["c","Corretora de Valores"],["d","Administrador do fundo"]],"ans":"c","exp":"Tema: responsável pelo IR na fonte em ações. A corretora de valores retém o IRRF na fonte. A alternativa C é a correta. Ver a questão 149.","id":"199543134"},{"n":591,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"315","capn":"Questão 315 (cód. 199543135)","stem":"Nas operações com ações do tipo Day Trade, qual é a alíquota do Imposto de Renda total e na fonte, respectivamente:","opts":[["a","20% e 0,005%"],["b","15% e 0,005%"],["c","15% e 1%"],["d","20% e 1%"]],"ans":"d","exp":"Tema: alíquotas de day trade. O IR total é de 20% sobre o lucro, e o IRRF na fonte é de 1% sobre o lucro. A alternativa D é a correta. Ver a questão 150.","id":"199543135"},{"n":592,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"316","capn":"Questão 316 (cód. 199543136)","stem":"Um determinado investidor acredita na elevação da taxa de juros para os próximos anos. Com isso, deveria investir em:","opts":[["a","LFT"],["b","LTN"],["c","NTN-B"],["d","Ações"]],"ans":"a","exp":"Tema: investimento para quem espera alta de juros. A LFT é pós-fixada e acompanha a Selic, então rende mais quando os juros sobem. A alternativa A é a correta. Ver a questão 210.","id":"199543136"},{"n":593,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"317","capn":"Questão 317 (cód. 199543138)","stem":"Seu cliente deseja montar uma carteira somente com títulos públicos e todos com rentabilidade pós fixadas. Você deveria indicar qual carteira:","opts":[["a","60% LFT e 40% LTN"],["b","60% LFT e 40% CDB pós fixado"],["c","60% LFT e 40% NTN-B"],["d","100% LFT"]],"ans":"d","exp":"Tema: carteira só com títulos públicos pós-fixados. A carteira 100% LFT atende ao enunciado. A alternativa D é a correta. Ver a questão 211.","id":"199543138"},{"n":594,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"318","capn":"Questão 318 (cód. 199543139)","stem":"O IOF é um imposto cobrado com alíquota regressiva que incide a partir do primeiro dia de aplicação até o:","opts":[["a","30°"],["b","29°"],["c","180°"],["d","19°"]],"ans":"b","exp":"Tema: IOF regressivo. O IOF incide de forma regressiva até o 29º dia de aplicação, quando a alíquota chega a zero. A alternativa B é a correta, conforme a regra apresentada na questão 17 e na apostila.","id":"199543139"},{"n":595,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"319","capn":"Questão 319 (cód. 199543140)","stem":"Uma empresa do setor de construção de rodovias quer captar recursos através de dívida e deseja um longo prazo para ficar com os recursos, deveria optar por:","opts":[["a","Debêntures"],["b","Ações"],["c","Notas Promissórias"],["d","CDB"]],"ans":"a","exp":"Tema: captação de longo prazo por dívida para construtora de rodovias. As debêntures são títulos de dívida de médio e longo prazo, emitidos por companhias para captar recursos. A alternativa A é a correta. Ver a questão 151.","id":"199543140"},{"n":596,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"320","capn":"Questão 320 (cód. 199543141)","stem":"Ganho de Capital é quando:","opts":[["a","Um investidor recebe dividendos no seu investimento"],["b","Um investidor recebe juros sobre capital próprio no seu investimento"],["c","Um investidor vende uma ação por um valor superior ao que comprou"],["d","Um investidor vende uma ação por um valor inferior ao que comprou"]],"ans":"c","exp":"Tema: ganho de capital. É o lucro obtido quando o investidor vende um ativo por valor superior ao que pagou. A alternativa C é a correta. Ver a questão 152.","id":"199543141"},{"n":597,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"321","capn":"Questão 321 (cód. 199543142)","stem":"Segundo a instrução da Comissão de Valores Mobiliários - CVM de número 400/2003, um título pode ser ofertado ao público em que momento:","opts":[["a","Somente depois do registro da oferta na CVM"],["b","Somente depois da publicação do prospecto"],["c","Antes do registro da oferta na CVM"],["d","Somente depois da apresentação de todas as informações nas principais capitais do país"]],"ans":"a","exp":"Tema: oferta pública de títulos segundo a ICVM 400. Um título só pode ser ofertado ao público depois do registro da oferta na CVM. A alternativa A é a correta.","id":"199543142"},{"n":598,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"322","capn":"Questão 322 (cód. 199543143)","stem":"Um investimento em Letra de Crédito do Agronegócio – LCA:","opts":[["a","Possui isenção de I.R para pessoa física e cobertura do FGC com valor ilimitado"],["b","Possui isenção de I.R para pessoa física e cobertura limitada do FGC"],["c","Possui isenção de I.R para pessoa física e não possui cobertura do FGC"],["d","Não possui isenção de I.R, porém conta com cobertura do FGC"]],"ans":"b","exp":"Tema: LCA. A LCA tem isenção de IR para pessoa física e cobertura limitada do FGC. A alternativa B é a correta. Ver a questão 58 e a questão 72.","id":"199543143"},{"n":599,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"323","capn":"Questão 323 (cód. 199543144)","stem":"Percentual máximo do total do Clube de Investimento que um único cotista pode deter:","opts":[["a","30%"],["b","67%"],["c","25%"],["d","40%"]],"ans":"d","exp":"Tema: participação máxima de um cotista em clube. Nenhum cotista pode deter mais de 40% do total do clube. A alternativa D é a correta. Ver a questão 180.","id":"199543144"},{"n":600,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"324","capn":"Questão 324 (cód. 199543145)","stem":"Período de uma oferta pública em que se coleta as intenções de aquisição de um determinado título e também o preço que esses interessados estão dispostos a pagar:","opts":[["a","Front Runner"],["b","Chinese Wall"],["c","Bookbuilding"],["d","Churning"]],"ans":"c","exp":"Tema: bookbuilding. É o período em que se coletam as intenções de aquisição de um título e o preço que os interessados estão dispostos a pagar. A alternativa C é a correta. Ver a questão 153.","id":"199543145"},{"n":601,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"325","capn":"Questão 325 (cód. 199543146)","stem":"Você é gerente de um cliente que deseja um produto de investimento com rentabilidade real. Você deveria indicar:","opts":[["a","LFT"],["b","CDB Prefixado"],["c","NTN-B"],["d","LTN"]],"ans":"c","exp":"Tema: produto com rentabilidade real. A NTN-B é o título com rentabilidade acima da inflação. A alternativa C é a correta. Ver a questão 212.","id":"199543146"},{"n":602,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"326","capn":"Questão 326 (cód. 199543147)","stem":"O Certificado de Depósito Bancário – CDB é:","opts":[["a","Título representativo de depósito a prazo emitido por empresas de qualquer setor"],["b","Título representativo de depósito a prazo emitido por bancos comerciais e de investimentos"],["c","Título representativo de depósito a prazo emitido somente por bancos comerciais"],["d","Título representativo de depósito a prazo emitido somente por banco de investimento"]],"ans":"b","exp":"Tema: CDB. É um título representativo de depósito a prazo, emitido por bancos comerciais e de investimento. A alternativa B é a correta.","id":"199543147"},{"n":603,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"327","capn":"Questão 327 (cód. 199543148)","stem":"Um investidor pessoa física fez a compra de 800 ações de uma empresa pelo valor total de R$ 30.000. Alguns dias depois ele vende metade da posição comprada pelo valor de R$ 23.000. Nesse caso, qual será o I.R retido na fonte e o valor a ser pago via DARF (Considere R$ 100 de corretagem na venda):","opts":[["a","R$ 1,20 e R$ 1.200,00"],["b","R$ 0,39 e R$ 1.200,00"],["c","R$ 0,40 e R$ 1183,60"],["d","R$ 1,15 e R$ 1.183,85"]],"ans":"d","exp":"Tema: IR retido e DARF na venda parcial de ações. O resultado é o mesmo da questão 154: IRRF de R$ 1,15 e DARF de R$ 1.183,85. A alternativa D é a correta.","id":"199543148"},{"n":604,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"328","capn":"Questão 328 (cód. 199543149)","stem":"Em uma oferta pública destinada exclusivamente para Investidores Qualificados, quem poderia participar: I. Colaboradores do banco líder da oferta pública II. Companhias Seguradoras III. Entidades Fechadas de Previdência Complementar Está (ão) correto (s):","opts":[["a","Apenas I"],["b","I e II"],["c","I e III"],["d","II e III"]],"ans":"d","exp":"Tema: oferta pública restrita a investidores qualificados. Podem participar os colaboradores do banco líder e os investidores qualificados, desde que atendam às condições da oferta. Analisando os itens do enunciado, a alternativa D (II e III) é a chave. O texto desta edição não detalha as condições do item I, então a análise do item I depende da norma da oferta. Recomendo conferir o enunciado completo.","id":"199543149"},{"n":605,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"329","capn":"Questão 329 (cód. 199543150)","stem":"Em uma emissão de debêntures ou notas promissórias, é função de uma agência classificadora de risco:","opts":[["a","Garantir que os pagamentos serão realizados pelo emissor"],["b","Conceder uma nota de crédito, que significa a possibilidade de o emissor não honrar com o seu compromisso"],["c","Ser o representante do emissor na oferta pública"],["d","Ser o representante dos investidores em uma oferta pública"]],"ans":"b","exp":"Tema: função da agência classificadora de risco. Ela atribui uma nota de crédito, que indica a probabilidade de o emissor não honrar a dívida. A alternativa B é a correta. Ver a questão 155.","id":"199543150"},{"n":606,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"330","capn":"Questão 330 (cód. 199543151)","stem":"Uma Letra Financeira do Tesouro – LFT tem a sua remuneração:","opts":[["a","Pós fixada, atrelada à Taxa Selic Meta"],["b","Pós fixada, atrelada à Taxa Selic Over"],["c","Prefixada, atrelada à Taxa Selic Over"],["d","Atrelada à inflação"]],"ans":"b","exp":"Tema: remuneração da LFT. A LFT é pós-fixada, atrelada à Selic Over. A alternativa B é a correta. Ver a questão 213.","id":"199543151"},{"n":607,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"331","capn":"Questão 331 (cód. 199543152)","stem":"Seu cliente fez um as seguintes movimentações em poupança: 03/01 – Depósito R$ 10 mil 01/02 – Saque R$ 9 mil No dia 03/02, qual será a base de cálculo para o crédito dos juros:","opts":[["a","R$ 1 mil"],["b","R$ 10 mil"],["c","R$ 9 mil"],["d","R$ 19 mil"]],"ans":"a","exp":"Tema: base de cálculo da poupança em uma movimentação. O cliente depositou R$ 10 mil em 3 de janeiro e sacou R$ 9 mil em 1 de fevereiro, deixando R$ 1 mil. Entre os dias 3 de janeiro e 3 de fevereiro, o menor saldo do período é de R$ 1 mil, que é a base de cálculo. A alternativa A é a correta.","id":"199543152"},{"n":608,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"332","capn":"Questão 332 (cód. 199543153)","stem":"São produtos de investimentos com cobertura do FGC, exceto:","opts":[["a","Poupança"],["b","LCI"],["c","CDB"],["d","Debêntures Incentivadas"]],"ans":"d","exp":"Tema: produtos com cobertura do FGC. Debêntures incentivadas não têm cobertura do FGC, e são a exceção. A alternativa D é a correta. CDB, LCI e LCA têm cobertura.","id":"199543153"},{"n":609,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"333","capn":"Questão 333 (cód. 199543154)","stem":"São produtos isentos de Imposto de Renda para investidor pessoa física, exceto:","opts":[["a","Debêntures Incentivadas"],["b","LFT"],["c","Poupança"],["d","LCI"]],"ans":"b","exp":"Tema: produtos isentos de IR para pessoa física. A LFT não é isenta de IR, e é tributada conforme a tabela regressiva. A alternativa B é a correta, por ser a exceção. LCI, LCA e poupança são isentas.","id":"199543154"},{"n":610,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"334","capn":"Questão 334 (cód. 199543155)","stem":"A ação Preferencial (PN) possui preferência no recebimento de dividendos de uma companhia. Essa ação, pode adquirir o direito a voto no caso de:","opts":[["a","A companhia der prejuízo em um determinado exercício"],["b","Ser uma ação conversível"],["c","A companhia ficar 3 exercícios seguidos sem distribuir dividendos"],["d","A companhia fechar seu capital"]],"ans":"c","exp":"Tema: direito de voto das preferenciais. A PN passa a votar quando a companhia fica três exercícios seguidos sem distribuir dividendos. A alternativa C é a correta. Ver a questão 156.","id":"199543155"},{"n":611,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"335","capn":"Questão 335 (cód. 199543156)","stem":"Em uma Bonificação de Ações:","opts":[["a","O acionista tem o direito de comprar um número de ações"],["b","O acionista recebe sem custo um número de ações"],["c","A empresa está captando novos recursos"],["d","O acionista continua com o mesmo número de ações"]],"ans":"b","exp":"Tema: bonificação de ações. O acionista recebe, sem custo, novas ações proporcionais às que já possui. A alternativa B é a correta. Ver a questão 157.","id":"199543156"},{"n":612,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"336","capn":"Questão 336 (cód. 199543157)","stem":"A liquidação no mercado secundário ocorre em:","opts":[["a","D+3 (física) e D+3 (financeira)"],["b","D+2 (física) e D+3 (financeira)"],["c","D+2 (física) e D+2 (financeira)"],["d","D+4 (física) e D+3 (financeira)"]],"ans":"c","exp":"Tema: liquidação no mercado secundário de ações. A liquidação física e a financeira ocorrem em D+2. A alternativa C é a correta, conforme a regra do mercado à vista de renda variável.","id":"199543157"},{"n":613,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"337","capn":"Questão 337 (cód. 199543159)","stem":"Seu cliente exporta máquinas para o exterior. Vende uma máquina por U$ 100 mil e receberá esse valor em 40 dias. Para se proteger (hedge) da oscilação da moeda estrangeira, qual alternativa você indica:","opts":[["a","Comprar uma Call de Dólar"],["b","Vender uma Call de Dólar"],["c","Comprar uma Put de Dólar"],["d","Vender uma Put de Dólar"]],"ans":"c","exp":"Tema: hedge de exportador de máquinas com recebimento em dólar. Para se proteger da queda do dólar, o exportador compra put de dólar, que garante um preço mínimo de venda. A alternativa C é a correta. Ver a questão 247.","id":"199543159"},{"n":614,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"338","capn":"Questão 338 (cód. 199543160)","stem":"Quem pode emitir um Certificado de Recebíveis Imobiliários:","opts":[["a","Banco de Investimento"],["b","Banco Múltiplo"],["c","Sociedade de Crédito Imobiliário"],["d","Sociedade Securitizadora"]],"ans":"d","exp":"Tema: emissor do CRI. Quem pode emitir o Certificado de Recebíveis Imobiliários é a sociedade securitizadora. A alternativa D é a correta. Ver as questões 174 e 175.","id":"199543160"},{"n":615,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"339","capn":"Questão 339 (cód. 199543161)","stem":"Quanto ao prazo máximo de emissão das Notas Promissórias – Commercial Papers, assinale a alternativa correta:","opts":[["a","180 dias (S.A Fechada) e 360 dias (S.A Aberta)"],["b","360 dias (S.A Fechada e Aberta)"],["c","180 dias (S.A Fechada e Aberta)"],["d","180 dias (S.A Aberta) e 360 dias (S.A Fechada)"]],"ans":"b","exp":"Tema: prazo máximo de emissão de notas promissórias. O prazo máximo é de 360 dias, para S.A. fechada e aberta. A alternativa B é a correta. Ver a questão 158.","id":"199543161"},{"n":616,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"340","capn":"Questão 340 (cód. 199543162)","stem":"Seu cliente gostaria de uma aplicação que contasse com garantia do FGC, porém acima da garantia. Você deveria indicar para ele:","opts":[["a","Títulos Públicos Federais"],["b","DPGE"],["c","Debêntures Incentivadas"],["d","CDB de banco de primeira linha"]],"ans":"b","exp":"Tema: aplicação com garantia do FGC e acima da garantia. O DPGE (Depósito a Prazo com Garantia Especial) é um título bancário com garantia especial do FGC, que cobre valores acima do limite do CDB comum. A alternativa B é a correta.","id":"199543162"},{"n":617,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"341","capn":"Questão 341 (cód. 199543163)","stem":"No mercado atualmente existem 2 títulos com as taxas para o mesmo prazo: LTN: 9,25% NTN-B: 6,75% Qual a inflação projetada para o período:","opts":[["a","4,50%"],["b","3,25%"],["c","2,50%"],["d","2,34%"]],"ans":"d","exp":"Tema: inflação projetada a partir de LTN e NTN-B. A taxa prefixada da LTN é de 9,25%, e a taxa real da NTN-B é de 6,75%. A inflação implícita é dada por (1,0925 / 1,0675) − 1 ≈ 2,34%. A alternativa D é a correta.","id":"199543163"},{"n":618,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"342","capn":"Questão 342 (cód. 199543164)","stem":"Segmento de listagem que conta com 100% de Tag Along para ações Ordinárias e Preferenciais:","opts":[["a","Nível 2"],["b","Novo Mercado"],["c","Nível 1"],["d","Tradicional"]],"ans":"a","exp":"Tema: segmento com 100% de Tag Along para ON e PN. O Nível 2 exige Tag Along de 100% para todas as ações. A alternativa A é a correta. Ver a questão 159.","id":"199543164"},{"n":619,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"343","capn":"Questão 343 (cód. 199543165)","stem":"Para o analista técnico, na hora de definir qual ação irá comprar:","opts":[["a","É importante entender o cenário macroeconômico e projeções"],["b","É necessário analisar o balanço e as demonstrações financeiras da empresa"],["c","As informações de volume de compra e preço são desprezadas"],["d","Irá considerar o preço da ação, a partir do histórico do mesmo, para definir ponto de entrada e saída da operação"]],"ans":"d","exp":"Tema: análise técnica. O analista técnico considera o histórico de preços da ação para definir os pontos de entrada e saída da operação. A alternativa D é a correta.","id":"199543165"},{"n":620,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"344","capn":"Questão 344 (cód. 199543166)","stem":"Um American Depositary Receipt - ADR:","opts":[["a","É uma ação negociada nos Estados Unidos, cotada em dólares de uma empresa não americana"],["b","É um título negociado nos Estados Unidos, cotado em dólares e lastreado em ações de uma empresa não americana"],["c","É um título negociado nos Estados Unidos, cotado em reais e lastreado em ações de uma empresa não americana"],["d","É um título negociado no Brasil, cotado em reais e lastreado em ações de uma empresa americana"]],"ans":"b","exp":"Tema: ADR. É um título negociado nos Estados Unidos, cotado em dólares, lastreado em ações de empresas não americanas. A alternativa B é a correta. Ver a questão 160.","id":"199543166"},{"n":621,"banco":"lucas","mod":3,"tit":"III","titn":"Instrumentos de Renda Fixa, Renda Variável e Derivativos","cap":"345","capn":"Questão 345 (cód. 199543167)","stem":"Para o lançador, uma opção de compra, se exercida, representa:","opts":[["a","Uma obrigação de vender"],["b","Um direito de comprar"],["c","Uma obrigação de comprar"],["d","Um direito de vender"]],"ans":"a","exp":"Tema: posição do lançador de call. Se o titular exercer, o lançador tem a obrigação de vender o ativo ao preço de exercício. A alternativa A é a correta. Ver a questão 248.","id":"199543167"},{"n":622,"banco":"lucas","mod":4,"tit":"IV","titn":"Fundos de Investimentos","cap":"1","capn":"Questão 1 (cód. 199544182)","stem":"São taxas que podem ser cobradas dos cotistas de um fundo de investimento, conforme a instrução CVM 555/14:","opts":[["a","Entrada, Saída e Carregamento"],["b","Entrada, Saída, Administração e Performance"],["c","Administração e Performance, somente"],["d","Entrada, Saída e Performance"]],"ans":"b","exp":"Tema: taxas que podem ser cobradas dos cotistas. Pelas regras da CVM, o fundo pode cobrar taxa de administração e taxa de performance. As taxas de ingresso e de saída, que aparecem nas alternativas A, B e D, não estão no conjunto de taxas admitidas pela instrução, e por isso a combinação correta é apenas administração e performance.\n\nO gabarito indica B, que inclui entrada e saída. Pela regra que eu conheço da ICVM 555, a cobrança de ingresso e saída é vedada, então a B conflita com a norma. A resposta mais coerente seria a C. Como a apostila desta edição não detalha essa vedação nas páginas de teoria, vale conferir a redação atual da ICVM 555 antes de considerar a questão resolvida.","id":"199544182"},{"n":623,"banco":"lucas","mod":4,"tit":"IV","titn":"Fundos de Investimentos","cap":"2","capn":"Questão 2 (cód. 199544184)","stem":"Pessoa Jurídica que tem por obrigação legal investir parte do seu patrimônio no mercado financeiro:","opts":[["a","Banco Múltiplo"],["b","Banco Comercial"],["c","Investidor Institucional"],["d","Investidor Profissional"]],"ans":"c","exp":"Tema: investidores institucionais. São pessoas jurídicas que, por obrigação legal ou regulatória, precisam investir parte do patrimônio no mercado financeiro, como seguradoras, entidades de previdência e instituições financeiras. A alternativa C é a correta.\n\nBanco múltiplo (A) e banco comercial (B) são instituições financeiras, e não categorias de investidor. Investidor profissional (D) é uma classificação da CVM baseada no volume de investimentos e na declaração escrita, e não tem a obrigação legal de investir.","id":"199544184"},{"n":624,"banco":"lucas","mod":4,"tit":"IV","titn":"Fundos de Investimentos","cap":"3","capn":"Questão 3 (cód. 199544185)","stem":"Quem pode fazer a gestão dos ativos da carteira de um fundo de investimentos:","opts":[["a","Gestor"],["b","Custodiante"],["c","Auditor Externo"],["d","Cotista"]],"ans":"a","exp":"Tema: quem gere os ativos da carteira. O gestor é o responsável pela gestão da carteira, ou seja, pela compra e venda dos ativos de acordo com a política de investimentos. A alternativa A é a correta.\n\nO custodiante (B) guarda os ativos, mas não os escolhe. O auditor externo (C) audita as contas. O cotista (D) é o investidor, que não gere a carteira do fundo.","id":"199544185"},{"n":625,"banco":"lucas","mod":4,"tit":"IV","titn":"Fundos de Investimentos","cap":"4","capn":"Questão 4 (cód. 199544186)","stem":"A taxa de Administração de um fundo de investimento é cobrada:","opts":[["a","Sobre o valor total da aplicação de cada cotista, dependendo do resultado auferido"],["b","Sobre o valor total da aplicação de cada cotista, independente do resultado auferido"],["c","Com base no desempenho global da carteira, em relação a um índice de mercado"],["d","Com base no desempenho mensal da carteira, em relação a um índice de mercado"]],"ans":"b","exp":"Tema: cobrança da taxa de administração. Ela incide sobre o patrimônio do fundo e é cobrada independentemente do resultado. Por isso a alternativa B é a correta, pois descreve a cobrança fixa sobre o valor aplicado, sem depender do desempenho.\n\nA alternativa A condiciona a cobrança ao resultado, e isso é característica da taxa de performance. As alternativas C e D também associam a taxa ao desempenho em relação a um índice, o que é a lógica da performance e não da administração.","id":"199544186"},{"n":626,"banco":"lucas","mod":4,"tit":"IV","titn":"Fundos de Investimentos","cap":"5","capn":"Questão 5 (cód. 199544187)","stem":"Um Fundo está alavancado em 150% do seu patrimônio. Em um determinado dia todos os ativos desse fundo tiveram desvalorização de 10%. Com isso, a cota teve queda de:","opts":[["a","10%"],["b","25%"],["c","20%"],["d","15%"]],"ans":"b","exp":"Tema: efeito da alavancagem sobre a cota. Um fundo alavancado em 150% do patrimônio tem ativos equivalentes a 1,5 vez o PL. Se os ativos caem 10%, a perda sobre o PL é de 10% × 1,5 = 15%, e a cota cai 15%. A alternativa D é o resultado desse cálculo.\n\nO gabarito indica B (25%). Ele só seria válido se a alavancagem fosse de 250% do PL, o que não é o enunciado. Por isso há uma divergência de cálculo entre a chave e a regra. Vale conferir a redação original da questão.","id":"199544187"},{"n":627,"banco":"lucas","mod":4,"tit":"IV","titn":"Fundos de Investimentos","cap":"6","capn":"Questão 6 (cód. 199544188)","stem":"Calcule a cota de um fundo em D+1 com as características abaixo: P.L em D+0: R$ 2.000.000 Valorização dos Ativos em D+1: R$ 10.000 Despesa com Corretagem: R$ 300 Despesa com Auditoria: R$ 800 Taxa de Administração: 1% a.a Cotas emitidas: 200.000 Qual o valor da cota em D+1:","opts":[["a","R$ 10,0440103"],["b","R$ 10,1920103"],["c","R$ 13,2511495"],["d","R$ 11,0756998"]],"ans":"a","exp":"Tema: cálculo da cota em D+1. A cota é o patrimônio líquido dividido pelo número de cotas. O PL em D+1 é o PL inicial somado à valorização dos ativos, descontadas as despesas do dia. A taxa de administração de 1% a.a. é apropriada diariamente, sobre o PL, em base de 252 dias úteis, o que dá cerca de R$ 79,37 por dia.\n\nPL = 2.000.000 + 10.000 − 300 − 800 − 79,37 = 2.008.820,63. Cota = 2.008.820,63 / 200.000 = R$ 10,0441. A alternativa A (R$ 10,0440103) bate com esse cálculo, o que confirma o gabarito. A conta exata depende da base de dias úteis usada, mas o padrão de 252 dias é o que a questão supõe.","id":"199544188"},{"n":628,"banco":"lucas","mod":4,"tit":"IV","titn":"Fundos de Investimentos","cap":"7","capn":"Questão 7 (cód. 199544189)","stem":"Com relação ao Fundo Multimercado, assinale a alternativa correta:","opts":[["a","Deve investir no mínimo 50% em crédito privado"],["b","Deve investir no mínimo 67% em ações"],["c","Investe em vários fatores de risco, sem o compromisso de alocação mínima em nenhum desses mercados"],["d","Investe em vários fatores de risco, porém, com concentração mínima em renda fixa, para reduzir o risco"]],"ans":"c","exp":"Tema: fundo multimercado. Ele investe em vários fatores de risco, como juros, câmbio, ações e commodities, sem percentual mínimo de alocação em nenhum deles. A alternativa C é a correta.\n\nAs alternativas A (50% em crédito privado) e B (67% em ações) são percentuais mínimos de outras classificações: crédito privado e ações. A alternativa D cria uma concentração mínima em renda fixa que não existe no multimercado.","id":"199544189"},{"n":629,"banco":"lucas","mod":4,"tit":"IV","titn":"Fundos de Investimentos","cap":"8","capn":"Questão 8 (cód. 199544190)","stem":"Um determinado investidor que busque proteção contra a variação cambial, deveria investir em:","opts":[["a","CDB"],["b","CDI"],["c","Fundo Cambial"],["d","LCI"]],"ans":"c","exp":"Tema: proteção contra variação cambial. O fundo cambial investe em variação de moeda estrangeira e de cupom cambial, com pelo menos 80% do patrimônio nesses ativos. Por isso é o instrumento adequado para quem quer proteção cambial. A alternativa C é a correta.\n\nCDB (A) e LCI (D) são renda fixa em reais, e não expõem o investidor à variação do dólar. O CDI (B) é uma taxa de referência de juros, e não um investimento.","id":"199544190"},{"n":630,"banco":"lucas","mod":4,"tit":"IV","titn":"Fundos de Investimentos","cap":"9","capn":"Questão 9 (cód. 199544191)","stem":"Os fundos classificados como “Cambiais” devem ter como principal fator de risco de sua carteira a variação:","opts":[["a","do cupom cambial e da variação da moeda americana"],["b","da taxa de juros medida pelo dólar ou do índice de preços internacional"],["c","de preços de moeda estrangeira ou da taxa de juros cambial"],["d","de preços de moeda estrangeira ou do cupom cambial"]],"ans":"d","exp":"Tema: fator de risco principal dos fundos cambiais. O fundo cambial tem como fator de risco a variação de preços de moeda estrangeira ou do cupom cambial. A alternativa D traz exatamente esses dois fatores. A alternativa A fala em cupom cambial e dólar, mas o dólar é o preço da moeda, então a ordem não corresponde. A alternativa B mistura taxa de juros com índice internacional. A alternativa C fala em taxa de juros cambial, que não é o fator definido.","id":"199544191"},{"n":631,"banco":"lucas","mod":4,"tit":"IV","titn":"Fundos de Investimentos","cap":"10","capn":"Questão 10 (cód. 199544192)","stem":"Em um fundo de renda fixa onde ocorre um alto volume de resgates, o gestor deve:","opts":[["a","Comprar títulos com alta rentabilidade para cobrir esses resgates"],["b","Comprar ativos no mercado financeiro de acordo com a política do fundo, respeitando o limite de risco e rentabilidade"],["c","Vender ativos para honrar os resgates"],["d","Fechar o fundo para novos aportes"]],"ans":"c","exp":"Tema: gestão de resgates em fundo de renda fixa. O gestor deve vender ativos para honrar os resgates, de acordo com a política do fundo. A alternativa C é a correta. Comprar títulos para cobrir resgates (A) não faz sentido, porque o fundo precisa de caixa, e não de mais ativos. A alternativa B é genérica demais e não diz o que fazer com o resgate. O fechamento para novos aportes (D) não é a reação prevista.","id":"199544192"},{"n":632,"banco":"lucas","mod":4,"tit":"IV","titn":"Fundos de Investimentos","cap":"11","capn":"Questão 11 (cód. 199544193)","stem":"Em janeiro de um determinado ano, Sr. Luís fez um aporte de R$ 50 mil em um fundo de Renda Fixa Longo Prazo com o valor de cota em R$ 10,00. No último dia útil de maio, segundo a Marcação a Mercado realizada pelo fundo essa cota estava no valor de R$ 12,00, ocorrendo então a antecipação do Imposto de Renda. Nesse caso, com quantas cotas ficará o Sr. Luís:","opts":[["a","5.000"],["b","4.875"],["c","5.625"],["d","4.900"]],"ans":"b","exp":"Tema: come-cotas e cálculo de cotas após a tributação. Sr. Luís aplicou R$ 50.000 à cota de R$ 10, obtendo 5.000 cotas. Em maio, a cota está em R$ 12, então o rendimento é de R$ 2 por cota, ou R$ 10.000 no total. Com alíquota de 15% (fundo de longo prazo), o IR é de R$ 1.500, que são cobrados por meio da redução de cotas: 1.500 / 12 = 125 cotas. Sobram 5.000 − 125 = 4.875 cotas. A alternativa B é a correta.","id":"199544193"},{"n":633,"banco":"lucas","mod":4,"tit":"IV","titn":"Fundos de Investimentos","cap":"12","capn":"Questão 12 (cód. 199544194)","stem":"Um cotista de um Fundo de Renda Fixa aberto, irá pagar Imposto de Renda em um eventual resgate e também nos meses de:","opts":[["a","Maio e Novembro, com alíquotas de 20% (Longo Prazo) e 15% (Curto Prazo)"],["b","Maio e Novembro, com alíquotas de 20% (Curto Prazo) e 15% (Longo Prazo)"],["c","Janeiro e Junh"],["d","Janeiro e Dezembro"]],"ans":"b","exp":"Tema: come-cotas em fundos de renda fixa. O IR é cobrado semestralmente, em maio e em novembro, além do IR cobrado no resgate. As alíquotas antecipadas são de 20% para fundos de curto prazo e de 15% para fundos de longo prazo. A alternativa B traz exatamente essa combinação. A alternativa A troca as alíquotas.\n\nA alternativa C está cortada no PDF (\"Janeiro e Junh\"), e a D fala em janeiro e dezembro, que não são os meses do come-cotas. Por isso a B é a resposta correta.","id":"199544194"},{"n":634,"banco":"lucas","mod":4,"tit":"IV","titn":"Fundos de Investimentos","cap":"13","capn":"Questão 13 (cód. 199544195)","stem":"Responsável pelo recolhimento do Imposto de Renda nos Fundos de ações:","opts":[["a","Próprio Cotista através de DARF"],["b","Gestor do fundo"],["c","Administrador do fundo"],["d","Custodiante do fundo"]],"ans":"c","exp":"Tema: responsável pelo IR em fundos de ações. Nos fundos de ações, o IR é recolhido pelo administrador, e não pelo cotista por DARF, porque não há come-cotas. A alternativa C é a correta. O gestor (B) escolhe os ativos, e o custodiante (D) guarda os ativos, mas nenhum deles é o responsável pelo recolhimento. Vale observar que o cotista (A) só recolhe por conta própria em outras situações.","id":"199544195"},{"n":635,"banco":"lucas","mod":4,"tit":"IV","titn":"Fundos de Investimentos","cap":"14","capn":"Questão 14 (cód. 199544196)","stem":"Um cliente fez um aporte em um Fundo de Ações de um determinado banco. Ele o questiona sobre a tributação desse fundo. Você explica que:","opts":[["a","Não possui IOF e o I.R é cobrado somente no resgate à alíquota única de 15%."],["b","Não possui IOF e o I.R é cobrado somente no resgate à alíquota única de 20%."],["c","Não possui IOF e o I.R é cobrado de forma antecipada semestralmente (come-cotas) e também no resgate, com alíquota variando de 15% a 20%."],["d","Possui IOF para resgates até 29 dias e o I.R é cobrado de forma antecipada semestralmente (come-cotas) e também no resgate, com alíquota única de 15%."]],"ans":"a","exp":"Tema: tributação de fundos de ações. Fundos de ações não pagam IOF e não têm come-cotas. O IR incide apenas no resgate, à alíquota única de 15%. A alternativa A descreve exatamente isso.\n\nAs alternativas B (20%) e C (come-cotas com alíquota variável) erram a alíquota e o regime. A alternativa D inclui IOF para resgates até 29 dias, o que não se aplica a fundos de ações, porque o IOF se restringe aos fundos de renda fixa.","id":"199544196"},{"n":636,"banco":"lucas","mod":4,"tit":"IV","titn":"Fundos de Investimentos","cap":"15","capn":"Questão 15 (cód. 199544197)","stem":"Quando um fundo realiza a cotização em D+1 e a liquidação em D+4, significa que:","opts":[["a","O valor da cota será conhecido no dia útil seguinte e valor será creditado no quarto dia útil"],["b","O valor da cota será conhecido no dia útil anterior e o valor da cota será creditado no quarto dia útil"],["c","O valor da cota será conhecido no segundo dia útil e o valor da cota será creditado no quarto dia útil"],["d","O valor da cota será conhecido no segundo dia útil e o valor da cota será creditado no mesmo dia"]],"ans":"a","exp":"Tema: prazos de cotização e liquidação. Cotização em D+1 significa que o valor da cota é conhecido no dia útil seguinte ao pedido. A liquidação em D+4 significa que o valor é creditado no quarto dia útil. A alternativa A é a correta.\n\nA alternativa B inverte a lógica e fala em cota conhecida no dia útil anterior, o que não é o caso. As alternativas C e D fixam a cotização no segundo dia útil, o que não corresponde ao D+1.","id":"199544197"},{"n":637,"banco":"lucas","mod":4,"tit":"IV","titn":"Fundos de Investimentos","cap":"16","capn":"Questão 16 (cód. 199544198)","stem":"Metodologia utilizada para a cobrança da Taxa de Performance:","opts":[["a","Linha D’agua"],["b","Chinese Wall"],["c","Day Trade"],["d","Taxa Over"]],"ans":"a","exp":"Tema: metodologia de cobrança da taxa de performance. A linha d'água é o método que cobra a performance sobre o rendimento acima de um índice de referência, apurando-o a cada período e reajustando a provisão. A alternativa A é a correta.\n\nChinese wall (B) é a segregação de atividades, day trade (C) é a compra e venda no mesmo dia, e taxa over (D) é a taxa de juros de um financiamento diário. Nenhuma delas é metodologia de performance.","id":"199544198"},{"n":638,"banco":"lucas","mod":4,"tit":"IV","titn":"Fundos de Investimentos","cap":"17","capn":"Questão 17 (cód. 199544199)","stem":"Com relação à cobrança de IOF nos fundos de investimentos, é correto afirmar:","opts":[["a","É uma alíquota regressiva que incide até o 29° dia de aplicação e é cobrado nos fundos de Renda Fixa e Ações"],["b","É uma alíquota regressiva que incide até o 30° dia de aplicação e é cobrado nos fundos de Renda Fixa e Ações"],["c","É uma alíquota regressiva que incide até o 30° dia de aplicação e é cobrado nos fundos de Renda Fixa"],["d","É uma alíquota regressiva que incide até o 29° dia de aplicação e é cobrado nos fundos de Renda Fixa"]],"ans":"d","exp":"Tema: IOF em fundos de investimento. O IOF é regressivo, incide sobre resgates feitos até o 29º dia de aplicação, e é cobrado apenas nos fundos de renda fixa. A alternativa D traz exatamente essas características.\n\nA alternativa A inclui fundos de ações, onde o IOF não incide. As alternativas B e C erram o prazo ao colocar o 30º dia. Vale fixar: IOF é de 29 dias e só em renda fixa.","id":"199544199"},{"n":639,"banco":"lucas","mod":4,"tit":"IV","titn":"Fundos de Investimentos","cap":"18","capn":"Questão 18 (cód. 199544200)","stem":"Tipo de Fundo de Investimento com ativos ligados à variação da taxa de juros doméstica ou índice de inflação:","opts":[["a","Renda Fixa"],["b","Multimercado"],["c","Referenciado"],["d","Ações"]],"ans":"a","exp":"Tema: fundos de renda fixa. A classificação de renda fixa abrange fundos que compram ativos ligados à variação da taxa de juros doméstica ou de índice de preços, com percentual mínimo de 80%. A alternativa A é a correta.\n\nMultimercado (B) não tem percentual mínimo de alocação. Referenciado (C) acompanha um índice de referência, o que é diferente. Ações (D) investe em ações, BDRs e bônus de subscrição.","id":"199544200"},{"n":640,"banco":"lucas","mod":4,"tit":"IV","titn":"Fundos de Investimentos","cap":"19","capn":"Questão 19 (cód. 199544201)","stem":"Responsável pelo registro do fundo na CVM:","opts":[["a","Custodiante"],["b","Administrador"],["c","Distribuidor"],["d","Gestor"]],"ans":"b","exp":"Tema: responsável pelo registro do fundo na CVM. O administrador é o responsável legal pelo fundo, responde perante a CVM e é quem contrata os demais prestadores. Por isso é o responsável pelo registro. A alternativa B é a correta.\n\nO custodiante (A) guarda os ativos, o distribuidor (C) comercializa as cotas e o gestor (D) cuida da carteira. Nenhum deles é responsável pelo registro perante a CVM.","id":"199544201"},{"n":641,"banco":"lucas","mod":4,"tit":"IV","titn":"Fundos de Investimentos","cap":"20","capn":"Questão 20 (cód. 199544202)","stem":"Os ativos que um Fundo de Investimentos de Renda Fixa investe são considerados de propriedade do:","opts":[["a","Administrador"],["b","Cotista"],["c","Gestor"],["d","Custodiante"]],"ans":"b","exp":"Tema: propriedade dos ativos do fundo. Os ativos pertencem ao fundo, que é um condomínio, e na prática o patrimônio é dos cotistas, na proporção de suas cotas. O administrador, o gestor e o custodiante exercem funções sobre esses ativos, mas não são donos deles. A alternativa B é a correta.\n\nA alternativa A (administrador) é o responsável legal, mas não o proprietário. As alternativas C e D são prestadores de serviço.","id":"199544202"},{"n":642,"banco":"lucas","mod":4,"tit":"IV","titn":"Fundos de Investimentos","cap":"21","capn":"Questão 21 (cód. 199544203)","stem":"Em um determinado fundo aberto, no D+0 haviam 5.000 cotas. No D+1 haviam 4.800 cotas. Isso ocorreu por qual motivo:","opts":[["a","Desvalorização dos ativos presentes na carteira do fundo"],["b","Valorização dos ativos presentes na carteira do fundo"],["c","Um número maior de resgates do que aportes"],["d","Um número maior de aportes do que de resgates"]],"ans":"c","exp":"Tema: variação do número de cotas em um fundo aberto. O número de cotas cai quando há mais resgates do que aportes, porque cada resgate cancela cotas. Desvalorização ou valorização dos ativos mudam o valor da cota, e não o número de cotas. A alternativa C é a correta.","id":"199544203"},{"n":643,"banco":"lucas","mod":4,"tit":"IV","titn":"Fundos de Investimentos","cap":"22","capn":"Questão 22 (cód. 199544204)","stem":"O Come-Cotas é um sistema de antecipação do imposto devido, que ocorre semestralmente. Quando o mesmo ocorre, o cotista observa uma:","opts":[["a","Redução no seu número de cotas, sem alterar o valor da mesma"],["b","Redução no seu número de cotas, alterando o valor da mesma"],["c","Redução no valor da cota"],["d","Aumento no seu número de cotas, sem alterar o valor da mesma"]],"ans":"a","exp":"Tema: efeito do come-cotas sobre o cotista. No come-cotas, o IR é antecipado por meio da redução do número de cotas. O valor de cada cota não se altera pela antecipação do imposto, porque o fundo apenas cancela cotas para pagar o tributo. A alternativa A é a correta.\n\nAs alternativas B e C alteram o valor da cota, o que não acontece. A alternativa D aumenta o número de cotas, o que é o oposto do que o come-cotas faz.","id":"199544204"},{"n":644,"banco":"lucas","mod":4,"tit":"IV","titn":"Fundos de Investimentos","cap":"23","capn":"Questão 23 (cód. 199544205)","stem":"Responsável pela escolha dos ativos que irão ser adquiridos para a carteira do fundo, de acordo com a Política de Investimentos:","opts":[["a","Administrador"],["b","Custodiante"],["c","Distribuidor"],["d","Gestor"]],"ans":"d","exp":"Tema: gestor de carteira. Ele escolhe os ativos que compõem a carteira, de acordo com a política de investimentos do fundo. A alternativa D é a correta.\n\nO administrador (A) é o responsável legal, o custodiante (B) guarda os ativos e o distribuidor (C) comercializa as cotas. Nenhum deles escolhe os ativos.","id":"199544205"},{"n":645,"banco":"lucas","mod":4,"tit":"IV","titn":"Fundos de Investimentos","cap":"24","capn":"Questão 24 (cód. 199544206)","stem":"Fundo fechado é aquele que:","opts":[["a","Permite resgate somente na data de liquidação do fundo"],["b","Permite resgate somente depois de um determinado período de carência"],["c","É exclusivo para Investidores Qualificados"],["d","Permite resgate somente com variações positivas"]],"ans":"a","exp":"Tema: fundo fechado. Nos fundos fechados, o cotista só pode resgatar as cotas na liquidação do fundo. Eles podem ter negociação no mercado secundário, como os FIIs. A alternativa A é a correta.\n\nA alternativa B descreve a carência, que é característica dos fundos abertos. A alternativa C atribui a restrição a qualificados, o que não define o fundo fechado. A alternativa D (resgate apenas com variação positiva) não existe como regra.","id":"199544206"},{"n":646,"banco":"lucas","mod":4,"tit":"IV","titn":"Fundos de Investimentos","cap":"25","capn":"Questão 25 (cód. 199544207)","stem":"É característica de um Fundo com Gestão Ativa:","opts":[["a","Ter estratégias de investimentos que visem replicar um determinado benchmark"],["b","Ter estratégias de investimentos que visem rentabilidade superior à de um determinado benchmark"],["c","Ter estratégias de investimentos mais defensivas"],["d","Ter estratégias de investimentos voltadas para Hedge da posição"]],"ans":"b","exp":"Tema: gestão ativa. O fundo de gestão ativa busca superar um benchmark, e não apenas replicá-lo. O gestor escolhe ativos com esse objetivo. A alternativa B é a correta.\n\nA alternativa A descreve a gestão passiva, que replica o índice. A alternativa C fala em estratégias mais defensivas, que não definem a gestão ativa. A alternativa D descreve o hedge, que é outro objetivo.","id":"199544207"},{"n":647,"banco":"lucas","mod":4,"tit":"IV","titn":"Fundos de Investimentos","cap":"26","capn":"Questão 26 (cód. 199544208)","stem":"Sobre Fundo Alavancado, assinale a alternativa correta:","opts":[["a","Existe menores chances de ocorrer perdas"],["b","São fundos considerados mais defensivos"],["c","São indicados para investidores mais conservadores"],["d","Existe a possiblidade de ter perdas superiores ao Patrimônio Líquido do fundo"]],"ans":"d","exp":"Tema: fundo alavancado. Ao usar derivativos ou empréstimos para ampliar a exposição, o fundo pode perder mais do que o próprio patrimônio líquido. Por isso a alternativa D é a correta. A alavancagem aumenta o risco, e não o reduz, o que descarta as alternativas A e B. Também não é indicado para investidores conservadores (C).","id":"199544208"},{"n":648,"banco":"lucas","mod":4,"tit":"IV","titn":"Fundos de Investimentos","cap":"27","capn":"Questão 27 (cód. 199544209)","stem":"A taxa de Administração em um Fundo de Investimento:","opts":[["a","É cobrada sempre que o fundo possui rentabilidade superior a um determinado benchmark"],["b","É cobrada anualmente e incide sobre o Patrimônio Líquido do fundo"],["c","É cobrada diariamente e incide sobre o Patrimônio Líquido do fundo"],["d","É cobrada diariamente e incide sobre a rentabilidade do fundo"]],"ans":"c","exp":"Tema: cobrança da taxa de administração. Ela é apropriada diariamente sobre o patrimônio líquido do fundo, e paga mensalmente. A alternativa C é a correta. A taxa não depende de rentabilidade (A), e não incide sobre a rentabilidade (D), porque a base é o PL. A cobrança anual (B) também está errada, porque é apropriada diariamente.","id":"199544209"},{"n":649,"banco":"lucas","mod":4,"tit":"IV","titn":"Fundos de Investimentos","cap":"28","capn":"Questão 28 (cód. 199544210)","stem":"Um Fundo de Ações deve aplicar:","opts":[["a","No máximo 67% do seu patrimônio em ações"],["b","No mínimo 80% do seu patrimônio em ações"],["c","No máximo 80% do seu patrimônio em ações"],["d","No mínimo 67% do seu patrimônio em ações"]],"ans":"d","exp":"Tema: percentual mínimo em ações. O fundo de ações deve aplicar no mínimo 67% do patrimônio em ações, BDRs e bônus de subscrição. A alternativa D é a correta, porque o percentual é mínimo e não máximo. As alternativas A e C falam em máximo, o que não é a regra. A alternativa B usa 80%, que é o percentual de outros fundos.","id":"199544210"},{"n":650,"banco":"lucas","mod":4,"tit":"IV","titn":"Fundos de Investimentos","cap":"29","capn":"Questão 29 (cód. 199544211)","stem":"Um Fundo Cambial deve investir, no mínimo, qual percentual do seu patrimônio em ativos ligados à variação de moeda estrangeira:","opts":[["a","67%"],["b","95%"],["c","80%"],["d","100%"]],"ans":"c","exp":"Tema: percentual mínimo em fundo cambial. O fundo cambial deve aplicar no mínimo 80% do patrimônio em ativos ligados à variação de moeda estrangeira ou ao cupom cambial. A alternativa C é a correta.\n\n67% (A) é o mínimo de fundos de ações, e 95% (B) é o mínimo de renda fixa simples. A alternativa D (100%) não é exigida.","id":"199544211"},{"n":651,"banco":"lucas","mod":4,"tit":"IV","titn":"Fundos de Investimentos","cap":"30","capn":"Questão 30 (cód. 199544212)","stem":"Tipo de Fundo de Investimento que dispensa o Termo de Adesão e também o API:","opts":[["a","Fundo de Renda Fixa"],["b","Fundo de Renda Fixa Simples"],["c","Fundo Cambial"],["d","Fundo Referenciado"]],"ans":"b","exp":"Tema: fundo de renda fixa simples. Ele é o único que não exige termo de adesão nem o API (Anexo de Informações Essenciais), por ser composto por títulos públicos federais ou ativos privados de mesmo risco. A alternativa B é a correta. Os demais fundos de renda fixa e o cambial, o referenciado seguem as exigências gerais de documentação.","id":"199544212"},{"n":652,"banco":"lucas","mod":4,"tit":"IV","titn":"Fundos de Investimentos","cap":"31","capn":"Questão 31 (cód. 199544213)","stem":"Conforme a classificação CVM, um fundo de Curto Prazo:","opts":[["a","Deve ter prazo médio da carteira de até 60 dias e prazo máximo de cada ativo de até 375 dias"],["b","Deve ter prazo médio da carteira de até 365 dias e prazo máximo de cada ativo de até 375 dias"],["c","Deve ter prazo médio da carteira de até 60 dias e prazo máximo de cada ativo de até 365 dias"],["d","Deve ter prazo médio da carteira de até 365 dias e prazo máximo de cada ativo de até 365 dias"]],"ans":"a","exp":"Tema: fundo de curto prazo, pela CVM. O prazo médio da carteira deve ser de até 60 dias, e o prazo máximo de cada ativo é de 375 dias. A alternativa A reúne esses dois critérios.\n\nAs alternativas B e D usam 365 dias como prazo médio, que é o critério tributário, e não o da classificação CVM. A alternativa C usa 365 dias para o prazo máximo, que não é o limite da CVM.","id":"199544213"},{"n":653,"banco":"lucas","mod":4,"tit":"IV","titn":"Fundos de Investimentos","cap":"32","capn":"Questão 32 (cód. 199544214)","stem":"Para ser um Fundo de Curto Prazo, conforme a Receita Federal, o mesmo deve ter:","opts":[["a","Prazo médio da carteira de até 60 dias"],["b","Prazo médio da carteira de até 365 dias"],["c","Prazo médio da carteira de até 375 dias"],["d","Prazo médio da carteira de até 180 dias"]],"ans":"b","exp":"Tema: fundo de curto prazo para fins tributários. Para a Receita Federal, o fundo é de curto prazo quando o prazo médio da carteira é de até 365 dias. A alternativa B é a correta.\n\nEsse critério é diferente do da CVM, que é de 60 dias para o prazo médio. Por isso a questão diferencia os dois conceitos. Vale fixar a diferença: 60 dias na CVM e 365 dias na Receita.","id":"199544214"},{"n":654,"banco":"lucas","mod":4,"tit":"IV","titn":"Fundos de Investimentos","cap":"33","capn":"Questão 33 (cód. 199544215)","stem":"Alíquota do Come-Cotas para um Fundo Renda Fixa Curto Prazo:","opts":[["a","15%"],["b","17,50%"],["c","22,50%"],["d","20%"]],"ans":"d","exp":"Tema: alíquota do come-cotas em fundo de curto prazo. O come-cotas de fundos de curto prazo tem alíquota de 20%, aplicada sobre o rendimento do período, enquanto os fundos de longo prazo têm 15%. A alternativa D é a correta.","id":"199544215"},{"n":655,"banco":"lucas","mod":4,"tit":"IV","titn":"Fundos de Investimentos","cap":"34","capn":"Questão 34 (cód. 199544216)","stem":"Seu cliente faz um resgate antes de 30 dias em um Fundo Renda Fixa Longo Prazo. Nesse caso, sobre a tributação:","opts":[["a","Incidirá I.R e depois IOF"],["b","Incidirá somente IOF"],["c","Incidirá IOF e depois I.R"],["d","Incidirá somente I.R"]],"ans":"c","exp":"Tema: tributação de resgate antes de 30 dias em fundo de renda fixa de longo prazo. Nos fundos de renda fixa, o IOF incide sobre os rendimentos resgatados em até 29 dias, e o IR incide depois. A ordem de cobrança é IOF primeiro e IR depois, por isso a alternativa C é a correta.\n\nA alternativa A inverte a ordem e a alternativa D ignora o IOF, que incide nesse caso. A alternativa B deixa de fora o IR.","id":"199544216"},{"n":656,"banco":"lucas","mod":4,"tit":"IV","titn":"Fundos de Investimentos","cap":"35","capn":"Questão 35 (cód. 199544217)","stem":"Sobre a taxa de administração em um fundo de investimento:","opts":[["a","É uma taxa cobrada sempre que o fundo possui rentabilidade acima de um determinado benchmarking"],["b","É devolvida ao cotista após um determinado período"],["c","É um dos fatores que afeta o valor da cota"],["d","É cobrado sobre a rentabilidade"]],"ans":"c","exp":"Tema: natureza da taxa de administração. Ela é um dos fatores que afetam o valor da cota, porque é descontada do patrimônio do fundo diariamente. A alternativa C é a correta.\n\nA alternativa A condiciona a taxa ao benchmark, o que é da performance. A alternativa B diz que ela é devolvida, o que não é regra. A alternativa D fala em cobrança sobre a rentabilidade, e a base da administração é o patrimônio.","id":"199544217"},{"n":657,"banco":"lucas","mod":4,"tit":"IV","titn":"Fundos de Investimentos","cap":"36","capn":"Questão 36 (cód. 199544218)","stem":"Sobre o limite de concentração em fundos de investimentos, para ativos de um mesmo emissor presentes na carteira, esse limite para emissores financeiros e não financeiros é de, respectivamente:","opts":[["a","10% e 10%"],["b","20% e 20%"],["c","10% e 20%"],["d","20% e 10%"]],"ans":"d","exp":"Tema: limite de concentração por emissor. Esta é uma regra de detalhe da CVM 555, e a apostila desta edição não traz os percentuais nas páginas de teoria, então não consigo confirmar a resposta com o texto que tenho.\n\nO gabarito indica D (20% para financeiros e 10% para não financeiros). Pela regra que eu conheço, a divisão é esta, mas recomendo conferir a redação atual da instrução antes de usar.","id":"199544218"},{"n":658,"banco":"lucas","mod":4,"tit":"IV","titn":"Fundos de Investimentos","cap":"37","capn":"Questão 37 (cód. 199544219)","stem":"Um determinado fundo de investimento possui a sua composição de carteira conforme abaixo: I - 75% em ativos de Renda Variável II - 25% em ativos de Renda Fixa III - Até 40% em derivativos futuros da Bolsa de Valores Esse fundo:","opts":[["a","Deve ser indicado para um investidor que busca baixo risco"],["b","Deve ser indicado para um investidor que busca um fundo de renda fixa"],["c","Tem possibilidade de ter perdas superiores ao seu patrimônio líquido"],["d","É um fundo de Renda Fixa Simples"]],"ans":"c","exp":"Tema: risco de um fundo com derivativos. O fundo tem 75% em renda variável, 25% em renda fixa e até 40% em derivativos futuros. Essa exposição tem alavancagem, porque os derivativos amplificam o resultado, e por isso o fundo pode ter perdas superiores ao PL. A alternativa C é a correta.\n\nA alternativa A (baixo risco) e a B (renda fixa) não correspondem à composição, que é de maior risco. A alternativa D (renda fixa simples) exige 95% em títulos públicos ou equivalentes, o que não se aplica.","id":"199544219"},{"n":659,"banco":"lucas","mod":4,"tit":"IV","titn":"Fundos de Investimentos","cap":"38","capn":"Questão 38 (cód. 199544220)","stem":"Sobre fundos, assinale a alternativa correta:","opts":[["a","Fundo de Renda Fixa não pode comprar ativos no exterior"],["b","Fundo fechado permite resgate a qualquer momento"],["c","Fundo exclusivo é aquele que investe em um determinado setor, como energia elétrica"],["d","Um fundo de ações pode comprar cotas de outros fundos"]],"ans":"d","exp":"Tema: regras gerais de fundos. Analisando cada alternativa:\n\nA) Errada: fundo de renda fixa pode comprar ativos no exterior, desde que observe os limites da classificação.\nB) Errada: fundo fechado não permite resgate a qualquer momento, só na liquidação, salvo casos específicos.\nC) Errada: fundo exclusivo é o destinado a um único cotista, e não ao setor de atuação.\nD) Correta: fundo de ações pode investir em cotas de outros fundos, observados os limites.\n\nA alternativa D é a correta.","id":"199544220"},{"n":660,"banco":"lucas","mod":4,"tit":"IV","titn":"Fundos de Investimentos","cap":"39","capn":"Questão 39 (cód. 199544221)","stem":"Um Fundo de Investimento em Cotas de FIDC (FICFIDC) deve investir, no mínimo:","opts":[["a","95% do seu patrimônio em cotas de FIDC"],["b","80% do seu patrimônio em cotas de FIDC"],["c","95% do seu patrimônio em direitos creditórios"],["d","80% do seu patrimônio em direitos creditórios"]],"ans":"a","exp":"Tema: fundo de investimento em cotas de FIDC (FICFIDC). A regra é que ele invista no mínimo 95% do patrimônio em cotas de FIDC. A alternativa A é a correta. O percentual de 80% (B) é de outros fundos, e a menção a direitos creditórios (C e D) não corresponde ao FICFIDC, que investe em cotas de FIDC, e não diretamente em direitos.","id":"199544221"},{"n":661,"banco":"lucas","mod":4,"tit":"IV","titn":"Fundos de Investimentos","cap":"40","capn":"Questão 40 (cód. 199544222)","stem":"Um Fundo de Investimentos em Participações - FIP de empresas emergentes, deve investir em:","opts":[["a","No mínimo 80% em títulos do governo"],["b","Títulos de empresas emergentes e trata-se de um fundo aberto"],["c","No mínimo 67% em ações"],["d","Títulos que permitam influenciar nas decisões das empresas"]],"ans":"d","exp":"Tema: FIP e a participação no processo decisório. O FIP investe em empresas com o objetivo de participar do processo decisório, principalmente pela indicação de membros para o conselho de administração. Por isso a alternativa D é a correta. Títulos do governo (A) não são o objeto do FIP, a alternativa B fala em fundo aberto, o que não é o caso, e a alternativa C (67% em ações) não é a exigência do FIP, que é de 90% em ações e títulos conversíveis.","id":"199544222"},{"n":662,"banco":"lucas","mod":4,"tit":"IV","titn":"Fundos de Investimentos","cap":"41","capn":"Questão 41 (cód. 199544223)","stem":"Com relação aos Exchange Traded Funds (ETF’s), as negociações desses ativos na bolsa de valores se dá pelo seguinte lote padrão:","opts":[["a","No mínimo 100 cotas"],["b","10 cotas"],["c","100 cotas"],["d","1 cota"]],"ans":"d","exp":"Tema: lote padrão de negociação dos ETFs em bolsa. A apostila desta edição indica que o lote padrão do ETF é de 10 cotas, e o exemplo dado é o BOVA11. A alternativa B é a que corresponde ao texto.\n\nO gabarito indica D (1 cota). Essa divergência é direta: a teoria aponta 10 cotas. Recomendo conferir o material original antes de considerar a questão resolvida.","id":"199544223"},{"n":663,"banco":"lucas","mod":4,"tit":"IV","titn":"Fundos de Investimentos","cap":"42","capn":"Questão 42 (cód. 199544224)","stem":"Os rendimentos e ganhos de capital auferidos pelos FIIs (Fundos de Investimentos Imobiliários), cujas cotas sejam negociadas em bolsa de valores, sujeitam-se à incidência do IR na fonte à alíquota de:","opts":[["a","20% para pessoa jurídica e isento para pessoa física."],["b","22,5% para pessoa jurídica e isento para pessoa física."],["c","25% para pessoa jurídica e para pessoa física."],["d","15% para pessoa jurídica e para pessoa física."]],"ans":"a","exp":"Tema: tributação de FII negociado em bolsa. Os rendimentos de FII negociado em bolsa são isentos para pessoa física, e para pessoa jurídica incidem a 20%. A alternativa A é a correta, de acordo com a regra do FII.\n\nAs alternativas B, C e D aplicam alíquotas que não correspondem à regra para FII.","id":"199544224"},{"n":664,"banco":"lucas","mod":4,"tit":"IV","titn":"Fundos de Investimentos","cap":"43","capn":"Questão 43 (cód. 199544225)","stem":"Seu cliente pessoa física possui cotas de Fundo de Investimento Imobiliário e comercializa as cotas desse fundo com ganho. Nesse caso o I.R será de:","opts":[["a","20%"],["b","15%"],["c","Depende do prazo de permanência"],["d","Isento"]],"ans":"a","exp":"Tema: ganho de capital na venda de cotas de FII por pessoa física. O ganho de capital na venda de cotas de FII é tributado a 20%, enquanto os rendimentos distribuídos são isentos. Essa alíquota não depende do prazo. A alternativa A é a correta.\n\nA alternativa B (15%) é a alíquota de outros fundos. A alternativa C (depende do prazo) não se aplica aos FIIs. A alternativa D (isento) vale apenas para os rendimentos, e não para o ganho de capital.","id":"199544225"},{"n":665,"banco":"lucas","mod":4,"tit":"IV","titn":"Fundos de Investimentos","cap":"44","capn":"Questão 44 (cód. 199544226)","stem":"Percentual mínimo do Patrimônio Líquido da carteira que um FIDC deve comprar em direitos creditórios:","opts":[["a","67%"],["b","80%"],["c","50%"],["d","95%"]],"ans":"c","exp":"Tema: percentual mínimo de direitos creditórios no FIDC. O FIDC deve aplicar no mínimo 50% do patrimônio líquido em direitos creditórios. A alternativa C é a correta, pela regra da apostila, que indica o mínimo de 50%.\n\nAs demais alternativas trazem percentuais de outros tipos de fundo, como 67% (ações) e 80% ou 95% (renda fixa e fundos em cotas).","id":"199544226"},{"n":666,"banco":"lucas","mod":4,"tit":"IV","titn":"Fundos de Investimentos","cap":"45","capn":"Questão 45 (cód. 199544227)","stem":"Seu cliente possui cotas de um Fundo de Investimento Imobiliário. Com relação à distribuição dos resultados do fundo, qual I.R será cobrado:","opts":[["a","É isento"],["b","20%"],["c","15%"],["d","Depende do prazo"]],"ans":"a","exp":"Tema: IR sobre a distribuição de rendimentos do FII para pessoa física. Os rendimentos distribuídos aos cotistas pessoa física são isentos, desde que o fundo cumpra as condições, como cotas negociadas em bolsa, ao menos 50 cotistas e nenhum cotista com 10% ou mais das cotas. A alternativa A é a correta.\n\nAs alternativas B, C e D aplicam alíquotas ou prazos que não se aplicam à distribuição de FII.","id":"199544227"},{"n":667,"banco":"lucas","mod":4,"tit":"IV","titn":"Fundos de Investimentos","cap":"46","capn":"Questão 46 (cód. 199544236)","stem":"As contas, informações periódicas de natureza contábil e demonstrações financeiras do Clube devem obedecer à norma específica da (o):","opts":[["a","CVM"],["b","Conselho Regional de Contabilidade"],["c","BACEN"],["d","CMN"]],"ans":"a","exp":"Tema: normas contábeis do clube de investimento. As contas, informações periódicas e demonstrações financeiras do clube devem seguir norma específica da CVM. A alternativa A é a correta.\n\nO Conselho Regional de Contabilidade (B) fiscaliza a profissão contábil, mas não edita a norma do clube. O BACEN (C) e o CMN (D) regulam instituições financeiras e não os clubes.","id":"199544236"},{"n":668,"banco":"lucas","mod":4,"tit":"IV","titn":"Fundos de Investimentos","cap":"47","capn":"Questão 47 (cód. 199544202017)","stem":"Sobre as operações ex-pit, é correto afirmar que:","opts":[["a","Reduzem a liquidez do mercado a termo e ampliam a liquidez do mercado futuro."],["b","Não possibilitam a precificação de posições a termo por meio de preços a futuro."],["c","São submetidas à interferência do mercado."],["d","Constituem negócios realizados fora do pit de negociação ou pregão, de uma bolsa."]],"ans":"d","exp":"Tema: operações ex-pit. A definição é de negócios realizados fora do pit de negociação ou pregão de uma bolsa, sem interferência do mercado. A alternativa D é a correta.\n\nA alternativa A atribui à operação efeitos sobre liquidez que não são definição. A alternativa B afirma que o ex-pit não permite precificar posições a termo, o que é falso, porque o ex-pit é justamente usado para precificar. A alternativa C diz que há interferência do mercado, o que é o contrário da característica do ex-pit.","id":"199544202017"},{"n":669,"banco":"lucas","mod":4,"tit":"IV","titn":"Fundos de Investimentos","cap":"48","capn":"Questão 48 (cód. 199544202018)","stem":"São considerados investidores profissionais pessoas físicas ou jurídicas que atestem por escrito essa condição de investidor e que possuam investimentos financeiros em valor superior a:","opts":[["a","U$ 10.000.000,00"],["b","R$ 10.000.000,00"],["c","R$ 1.000.000,00"],["d","U$ 500.000,00"]],"ans":"b","exp":"Tema: investidor profissional. São profissionais as pessoas físicas ou jurídicas com investimentos financeiros superiores a R$ 10 milhões, que atestem essa condição por escrito. A alternativa B é a correta, pela moeda brasileira.\n\nDólar (A e D) não é o critério, que é em reais. A alternativa C fixa R$ 1 milhão, que é o limite do investidor qualificado, e não do profissional.","id":"199544202018"},{"n":670,"banco":"lucas","mod":4,"tit":"IV","titn":"Fundos de Investimentos","cap":"49","capn":"Questão 49 (cód. 199544202019)","stem":"Os fundos classificados como “Dívida Externa” deverão aplicar, no mínimo de seu(sua) em títulos representativos da dívida externa de responsabilidade da União, sendo permitida a aplicação dos recursos remanescentes em operações de derivativos, no Brasil, exclusivamente para fins de proteção de sua carteira (hedge) ou mantê-los em conta de depósito à vista em nome do fundo, observando, no conjunto, o limite de do Patrimônio Líquido respectivo.","opts":[["a","80% patrimônio líquido, 10%"],["b","80% carteira, 20%"],["c","90% carteira, 10%"],["d","90% patrimônio líquido, 10%"]],"ans":"a","exp":"Tema: composição do fundo de dívida externa. O fundo deve aplicar no mínimo 80% do patrimônio em títulos da dívida externa da União, e o restante pode ir para derivativos de hedge ou para conta de depósito, observando no conjunto o limite de 10% do PL. A alternativa A reúne esses percentuais.\n\nO enunciado usa \"patrimônio líquido\" no mínimo de 80%, e a chave A bate com essa regra. A alternativa B (80% da carteira) difere da regra por usar carteira em vez de PL. As alternativas C e D trazem 90%, que não é o mínimo.","id":"199544202019"},{"n":671,"banco":"lucas","mod":4,"tit":"IV","titn":"Fundos de Investimentos","cap":"50","capn":"Questão 50 (cód. 199544202020)","stem":"Um fundo de investimentos pode ser constituído sob a forma de condomínio fechado em que os cotistas podem solicitar o resgate de suas cotas:","opts":[["a","De acordo com as regras estabelecidas em seu regulamento."],["b","Após o primeiro ano de criação do fundo."],["c","Ao término do prazo de duração do fundo."],["d","Se houver concordância de no mínimo dois terços dos cotistas."]],"ans":"c","exp":"Tema: resgate em fundo fechado constituído como condomínio. Os cotistas só podem solicitar resgate ao término do prazo de duração do fundo, quando o fundo é liquidado. A alternativa C é a correta. A alternativa A (regras do regulamento) é genérica demais, a B (após um ano) não é regra geral, e a D (dois terços dos cotistas) não é o mecanismo de resgate.","id":"199544202020"},{"n":672,"banco":"lucas","mod":4,"tit":"IV","titn":"Fundos de Investimentos","cap":"51","capn":"Questão 51 (cód. 199544202021)","stem":"Um fundo de investimento, registrado na CVM, que aplica seus recursos, exclusivamente, em títulos indexados a índices de preços, e com prazo médio da carteira inferior a 60 dias, é um fundo classificado como e deve ter o sufixo .","opts":[["a","Curto Prazo / Ações."],["b","Renda Variável / Cambial."],["c","Multimercado / Simples."],["d","Renda Fixa / Curto Prazo."]],"ans":"d","exp":"Tema: classificação de fundo que aplica em títulos indexados a índices de preços com prazo médio inferior a 60 dias. Pela classificação CVM, esse fundo é de renda fixa, na categoria de curto prazo. A alternativa D (renda fixa, curto prazo) é a correta.\n\nA classificação de ações (A), multimercado (C) e renda variável com cambial (B) não se aplicam ao perfil descrito.","id":"199544202021"},{"n":673,"banco":"lucas","mod":4,"tit":"IV","titn":"Fundos de Investimentos","cap":"52","capn":"Questão 52 (cód. 199544202022)","stem":"Sobre os Exchange Traded Funds – ETF, assinale a alternativa correta:","opts":[["a","É um fundo negociado em bolsa de valores, atrelado a um determinado índice"],["b","É um fundo fechado, negociado em bolsa de valores e com valor mínimo de investimento inicial de R$ 25.000"],["c","É um fundo negociado em bolsa de valores, atrelado ao mercado imobiliário"],["d","É um fundo negociado em mercado de balcão, com negociação restrita"]],"ans":"a","exp":"Tema: ETF. O Exchange Traded Fund é um fundo negociado em bolsa de valores que replica um índice de referência. A alternativa A é a correta.\n\nA alternativa B descreve um fundo fechado com investimento mínimo de R$ 25.000, o que não é a definição de ETF. A alternativa C atrela o ETF ao mercado imobiliário, o que é o caso do FII. A alternativa D diz que o ETF é negociado em balcão, o que é o contrário: ele é negociado em bolsa.","id":"199544202022"},{"n":674,"banco":"lucas","mod":4,"tit":"IV","titn":"Fundos de Investimentos","cap":"53","capn":"Questão 53 (cód. 199544202023)","stem":"Conforme a instrução CVM para ofertas públicas dos Fundos de Investimentos em Participações – FIP, analise as afirmações abaixo: I. A oferta pública de distribuição de cotas de FIP depende de registro na CVM II. Não se pode realizar uma nova oferta pública sem ter sido totalmente subscrita as cotas de uma oferta anterior (ou cancelado o saldo remanescente) III. Não se qualifica como “Oferta Pública” quando as cotas são emitidas para os cotistas atuais do fundo Está (ão) correta (s):","opts":[["a","I e III"],["b","II e III"],["c","Apenas I"],["d","Todas as afirmações"]],"ans":"d","exp":"Tema: oferta pública de cotas de FIP, pela instrução da CVM. Analisando:\n\nI. Correto. A oferta pública de FIP depende de registro na CVM.\n\nII. Correto. Não se pode iniciar nova oferta sem que a anterior esteja totalmente subscrita, ou sem que o saldo remanescente tenha sido cancelado.\n\nIII. Correto. Quando as cotas são emitidas para os cotistas atuais, a operação não se qualifica como oferta pública.\n\nA alternativa D (todas) é a correta.","id":"199544202023"},{"n":675,"banco":"lucas","mod":4,"tit":"IV","titn":"Fundos de Investimentos","cap":"54","capn":"Questão 54 (cód. 199544202025)","stem":"A ICVM 356/01 define um Fundo e Investimento em Direitos Creditórios (FIDC) como uma comunhão de recursos que destina uma parcela do respectivo patrimônio líquido (PL) para a aplicação em .","opts":[["a","Menor que 50% / cotas de fundo de investimento em cotas de fundo de investimento."],["b","De 95% / créditos creditórios."],["c","Maior que 50% / direitos creditórios."],["d","De 95% / cotas de fundo de investimento em cotas de fundo de investimento."]],"ans":"c","exp":"Tema: definição de FIDC pela ICVM 356. O FIDC é uma comunhão de recursos que aplica parcela do patrimônio líquido em direitos creditórios, com mínimo de 50% do PL. A alternativa C é a correta, com a expressão \"maior que 50%\". A regra usa o mínimo de 50%, e a alternativa C reproduz essa ideia de forma próxima.\n\nAs alternativas A e D usam cotas de fundos, o que não é o foco do FIDC, e a alternativa B usa 95%, que é de outro tipo de fundo.","id":"199544202025"},{"n":676,"banco":"lucas","mod":4,"tit":"IV","titn":"Fundos de Investimentos","cap":"55","capn":"Questão 55 (cód. 9951)","stem":"A respeito da Instrução CVM 578 que aborda sobre ofertas públicas dos Fundos de Investimentos em Participações (FIP), analise as alternativas abaixo: I. Para distribuição de cotas via oferta pública de um FIP necessita de registro na CVM II. Não é permitido a realização de uma nova oferta pública caso as cotas da oferta anterior não tenham sido totalmente subscritas ou com o saldo remanescente cancelado III. Caso as cotas tenham sido emitidas para os atuais cotistas do fundo, não se qualificam como oferta pública Está correto o que se afirma em:","opts":[["a","I e II"],["b","I e III"],["c","II e III"],["d","Todas as alternativas"]],"ans":"d","exp":"Tema: oferta pública de FIP pela Instrução CVM 578. Os três itens procedem: a oferta pública exige registro na CVM, não pode haver nova oferta antes de subscrita a anterior ou cancelado o saldo, e a emissão aos cotistas atuais não é oferta pública. A alternativa D é a correta. Esta questão repete o conteúdo da 53, com a mesma regra.","id":"9951"},{"n":677,"banco":"lucas","mod":4,"tit":"IV","titn":"Fundos de Investimentos","cap":"56","capn":"Questão 56 (cód. 9952)","stem":"A alíquota da antecipação semestral de imposto de renda de um fundo de longo prazo é:","opts":[["a","22,50%"],["b","20%"],["c","17,50%"],["d","15%"]],"ans":"d","exp":"Tema: alíquota do come-cotas em fundo de longo prazo. A antecipação semestral é de 15% em fundos de longo prazo, e 20% em fundos de curto prazo. A alternativa D é a correta.\n\nAs alíquotas de 22,5% (A) e 17,5% (C) são faixas do IR no resgate em outros casos, e a alíquota de 20% (B) é a do curto prazo.","id":"9952"},{"n":678,"banco":"lucas","mod":4,"tit":"IV","titn":"Fundos de Investimentos","cap":"57","capn":"Questão 57 (cód. 9953)","stem":"“Fundo com no mínimo 95% do patrimônio líquido em títulos públicos federais, títulos de renda fixa emitidos por instituição financeira com rating igual ou maior que o governo”. Tal definição, de acordo com a CVM 555, refere – se a um:","opts":[["a","Fundo de investimento renda fixa referenciado"],["b","Fundo de investimento renda fixa simples"],["c","Fundo de investimento curto prazo"],["d","Fundo de investimento em cotas"]],"ans":"b","exp":"Tema: fundo de renda fixa simples, pela CVM 555. A definição é de um fundo com pelo menos 95% do PL em títulos públicos federais e em títulos de renda fixa de instituições financeiras com rating igual ou maior que o do governo. Esse é o conceito de renda fixa simples. A alternativa B é a correta.\n\nO referenciado (A) acompanha um índice de referência, o curto prazo (C) tem prazo médio de 60 dias, e o de cotas (D) investe em outros fundos.","id":"9953"},{"n":679,"banco":"lucas","mod":4,"tit":"IV","titn":"Fundos de Investimentos","cap":"58","capn":"Questão 58 (cód. 9954)","stem":"A respeito da tributação de fundos imobiliários, é correto afirmar que:","opts":[["a","Perdas registradas na alienação de cotas poderão ser compensadas com ganhos futuros de fundos da mesma espécie, com negociação realizada em bolsa de valores"],["b","O próprio contribuinte deverá recolher o IR via DARF"],["c","Todos os cotistas, pessoa física ou jurídica, são isentos de IR sobre os rendimentos"],["d","A alíquota de IR de fundos imobiliários é regressiva"]],"ans":"a","exp":"Tema: tributação de fundos imobiliários. Perdas registradas na alienação de cotas de FII negociados em bolsa podem ser compensadas com ganhos futuros de fundos da mesma espécie, também negociados em bolsa. A alternativa A é a correta.\n\nA alternativa B está errada, porque o IR é retido na fonte, e não recolhido via DARF pelo cotista. A alternativa C está errada, porque a isenção dos rendimentos vale apenas para pessoa física. A alternativa D está errada, porque a alíquota de FII não é regressiva.","id":"9954"},{"n":680,"banco":"lucas","mod":4,"tit":"IV","titn":"Fundos de Investimentos","cap":"59","capn":"Questão 59 (cód. 9955)","stem":"O chinese wall é definido como:","opts":[["a","Marcação de títulos pelo valor atual que está sendo negociado no mercado"],["b","Operação de derivativo caracterizada pela troca de indicadores de rentabilidade"],["c","Segregação da administração de recursos próprios e de terceiros"],["d","Operação realizada no mesmo dia em ambiente de bolsa de valores"]],"ans":"c","exp":"Tema: chinese wall. É a segregação das atividades de administração de recursos próprios e de terceiros, para evitar conflito de interesses e troca de informações. A alternativa C é a correta.\n\nA marcação pelo valor atual (A) é a marcação a mercado. A troca de indicadores (B) é o swap. A operação no mesmo dia (D) é o day trade.","id":"9955"},{"n":681,"banco":"lucas","mod":4,"tit":"IV","titn":"Fundos de Investimentos","cap":"60","capn":"Questão 60 (cód. 9956)","stem":"Sobre um fundo de ações, pode – se afirmar que:","opts":[["a","Não haverá IOF no resgate"],["b","Há isenção de IR para investidor pessoa física até o limite de R$ 20.000,00"],["c","A tributação ocorre no último dia útil de maio e novembro e no resgate"],["d","A alíquota de IR sobre o resgate será decrescente de 22,5% a 15%"]],"ans":"a","exp":"Tema: tributação de fundo de ações. Fundos de ações não pagam IOF no resgate, por isso a alternativa A é a correta. A isenção de IR para pessoa física até R$ 20.000 (B) não é regra. A tributação semestral (C) não existe nos fundos de ações, que têm IR apenas no resgate. A alíquota de 22,5% a 15% (D) é a faixa do come-cotas de outros fundos, e não se aplica aos fundos de ações.","id":"9956"},{"n":682,"banco":"lucas","mod":4,"tit":"IV","titn":"Fundos de Investimentos","cap":"61","capn":"Questão 61 (cód. 9957)","stem":"Sobre o come cotas, assinale a afirmativa correta","opts":[["a","Todos os fundos de investimento possuem IR, cobrados nos meses de maio e novembro"],["b","Fundos cambiais não possuem IR semestral, havendo tributação apenas no resgate"],["c","Fundos de investimento de renda fixa curto prazo possuem IR semestral menor que fundos de renda fixa longo prazo"],["d","Fundos de investimento de curto prazo possuem alíquota de IR semestral de 20% sobre ganhos auferidos no período"]],"ans":"d","exp":"Tema: come-cotas. Analisando as alternativas:\n\nA) Errada: nem todos os fundos têm come-cotas, como os de ações e os cambiais.\nB) Duvidosa: a afirmativa depende do enquadramento tributário do fundo cambial, que não está detalhado na teoria desta edição. Não é a resposta indicada.\nC) Errada: o curto prazo tem alíquota semestral de 20%, maior que o longo prazo, que é de 15%.\nD) Correta: o curto prazo tem alíquota semestral de 20% sobre os ganhos do período.\n\nA alternativa D é a correta.","id":"9957"},{"n":683,"banco":"lucas","mod":4,"tit":"IV","titn":"Fundos de Investimentos","cap":"62","capn":"Questão 62 (cód. 9958)","stem":"Se um determinado grupo de investidores desejar estruturar um grupo para investimento em ações, o instrumento legal apropriado seria um:","opts":[["a","Agremiação de investidores"],["b","Clube de investimento"],["c","Cooperativa de investidores"],["d","Assembleia de investimento"]],"ans":"b","exp":"Tema: instrumento legal para investir em grupo. O clube de investimento é o instrumento legal adequado para um grupo de investidores que deseja investir em conjunto, principalmente em ações. A alternativa B é a correta.\n\nAgremiação (A), cooperativa (C) e assembleia (D) não são instrumentos de investimento regulados pela CVM.","id":"9958"},{"n":684,"banco":"lucas","mod":4,"tit":"IV","titn":"Fundos de Investimentos","cap":"63","capn":"Questão 63 (cód. 9959)","stem":"Fundos de investimento definidos como fundos em índice de mercado caracterizam-se principalmente por:","opts":[["a","Cumprir pelo menos 50%, de seu PL investido em valores mobiliários ou outros ativos de renda variável autorizados pela CVM, na proporção em que estes compõem o índice de referência"],["b","Cumprir pelo menos 5%, de seu PL investido em valores mobiliários ou outros ativos de renda variável autorizados pela CVM, na proporção em que estes compõem o índice de referência"],["c","Cumprir pelo menos 95%, de seu PL investido em valores mobiliários ou outros ativos de renda variável autorizados pela CVM, na proporção em que estes compõem o índice de referência"],["d","Cumprir pelo menos 80%, de seu PL investido em valores mobiliários ou outros ativos de renda variável autorizados pela CVM, na proporção em que estes compõem o índice de referência"]],"ans":"c","exp":"Tema: fundo de índice de mercado. Pela CVM, ele deve cumprir pelo menos 95% do PL em valores mobiliários ou ativos de renda variável, na proporção em que estes compõem o índice de referência. A alternativa C é a correta.\n\nAs alternativas A (50%), B (5%) e D (80%) usam percentuais que não correspondem à regra.","id":"9959"},{"n":685,"banco":"lucas","mod":4,"tit":"IV","titn":"Fundos de Investimentos","cap":"64","capn":"Questão 64 (cód. 9960)","stem":"Sobre clubes de investimentos, assinale a alternativa incorreta:","opts":[["a","É facultativo ao administrador a alteração do estatuto do clube de investimento, independente de aprovação em assembleia geral, adequar o regulamento as alterações de reguladores ou reduzir taxas de administração ou performance"],["b","Desde que aprovado em regulamento, um cotista poderá deter mais de 40% das cotas de um clube de investimento"],["c","A contratação de um auditor independente para o clube de investimentos é facultativa, desde que expressa em regulamento"],["d","As cotas de um clube de investimento não podem ser cessadas ou transferidas, salvo por decisão judicial, execução de garantia ou sucessão universal"]],"ans":"b","exp":"Tema: clubes de investimento, com a pergunta invertida (alternativa incorreta). Analisando:\n\nA) Correta. O administrador pode alterar o estatuto sem assembleia nos casos previstos, como adequar regulamento a reguladores ou reduzir taxas.\n\nB) Incorreta pela chave. A afirmação de que o regulamento autoriza um cotista a ter mais de 40% das cotas é o ponto que a questão aponta como errado. O limite de concentração de cotas por cotista é uma regra específica, que precisa ser conferida na instrução.\n\nC) Correta. A contratação de auditor independente para o clube é facultativa, desde que expressa em regulamento.\n\nD) Correta. As cotas não podem ser cedidas ou transferidas, salvo em hipóteses específicas, como decisão judicial ou sucessão universal.\n\nA alternativa B é a apontada como incorreta. Vale conferir a regra do limite por cotista na instrução, porque a teoria desta edição não a detalha.","id":"9960"},{"n":686,"banco":"lucas","mod":4,"tit":"IV","titn":"Fundos de Investimentos","cap":"65","capn":"Questão 65 (cód. 9961)","stem":"Entre as diferenças de fundos de investimento fechado e fundos abertos, é possível afirmar:","opts":[["a","O fundo fechado é destinado apenas a investidores qualificados"],["b","Fundo aberto e fechado permitem resgate de cotas a qualquer momento, desde que observado o prazo de carência, se houver"],["c","Fundos abertos permitem resgate de cotas apenas no encerramento do fundo"],["d","Fundos fechados permitem o resgate de cotas apenas no encerramento do fundo"]],"ans":"d","exp":"Tema: fundos abertos e fechados. No fundo aberto, o cotista pode resgatar a qualquer momento, observado o prazo de carência, se houver. No fundo fechado, o resgate só ocorre na liquidação do fundo. A alternativa D é a correta, pois descreve o caso do fundo fechado.\n\nA alternativa A restringe o fundo fechado a qualificados, o que não é a regra geral. A alternativa B afirma que ambos permitem resgate a qualquer momento, o que é falso para o fechado. A alternativa C inverte o regime do aberto.","id":"9961"},{"n":687,"banco":"lucas","mod":4,"tit":"IV","titn":"Fundos de Investimentos","cap":"66","capn":"Questão 66 (cód. 9962)","stem":"Fundos de investimentos estão sujeitas a diversas taxas. Dentre as alternativas abaixo, a que não pode ser uma taxa de um fundo de investimento é:","opts":[["a","Taxa de ingresso"],["b","Taxa de custódia"],["c","Taxa de administração"],["d","Taxa de performance"]],"ans":"b","exp":"Tema: taxas de fundos. A taxa de ingresso é uma taxa de entrada, a taxa de administração é a remuneração do administrador, e a taxa de performance é a remuneração por desempenho. A taxa de custódia é um encargo do fundo, pago pelo patrimônio, mas não é considerada uma das taxas típicas do fundo na classificação da CVM.\n\nO gabarito indica B, que é a alternativa que não pode ser taxa do fundo. A taxa de ingresso é vedada pela regra atual, como comentado na questão 1, então a leitura pode ser diferente. Vale conferir a regra da ICVM 555.","id":"9962"},{"n":688,"banco":"lucas","mod":4,"tit":"IV","titn":"Fundos de Investimentos","cap":"67","capn":"Questão 67 (cód. 9963)","stem":"O objetivo da marcação dos títulos presentes na carteira de um fundo de investimento pelo preço de mercado diário, tem por objetivo:","opts":[["a","Beneficiar o investidor que realiza novos aportes"],["b","Beneficiar o investidor que realiza solicitações de resgates"],["c","Evitar transferência de riqueza entre investidores cotistas"],["d","Evitar que o administrador obtenha lucro com os recursos"]],"ans":"c","exp":"Tema: marcação a mercado. Marcar os títulos pelo preço de mercado diariamente evita transferência de riqueza entre cotistas, porque quem entra ou sai do fundo não ganha ou perde à custa dos demais. A alternativa C é a correta.\n\nAs alternativas A e B beneficiariam um grupo específico de cotistas, o que é o problema que a marcação resolve. A alternativa D não é a finalidade da marcação.","id":"9963"},{"n":689,"banco":"lucas","mod":4,"tit":"IV","titn":"Fundos de Investimentos","cap":"68","capn":"Questão 68 (cód. 9964)","stem":"O banco de investimento “LS Bank” possui em seu portfólio alguns fundos de investimento com as determinadas alocações: Fundo X: 75% de ações e 25% de títulos públicos federais; Fundo Y: 35% de ações e 65% de títulos públicos federais; Fundo Z: 55% de ações e 45% de títulos públicos federais; Fundo W: 65% de ações e 35% de títulos públicos federais. Dentre os fundos acima, o que se enquadra na regra de fundos de ações são:","opts":[["a","Y e Z"],["b","X e Y"],["c","Z e W"],["d","Apenas X"]],"ans":"d","exp":"Tema: enquadramento de fundo de ações (mínimo de 67% em ações). Analisando cada fundo:\n\nFundo X: 75% em ações, enquadrado.\nFundo Y: 35% em ações, não enquadrado.\nFundo Z: 55% em ações, não enquadrado.\nFundo W: 65% em ações, não enquadrado, porque o mínimo é de 67%.\n\nApenas o Fundo X se enquadra na regra de fundos de ações. A alternativa D é a correta.","id":"9964"},{"n":690,"banco":"lucas","mod":4,"tit":"IV","titn":"Fundos de Investimentos","cap":"69","capn":"Questão 69 (cód. 9965)","stem":"Ao contrário da marcação a mercado dos títulos, a marcação na curva do papel existente nos fundos de investimento irá provocar:","opts":[["a","Aumento do rendimento, pois os títulos serão contabilizados pelo valor de mercado"],["b","Igualdade e equidade entre os cotistas do fundo, do qual não importa o momento de aplicação ou resgate"],["c","Distorção na rentabilidade a ser apurada, podendo ocorrer a distribuição de renda entre os cotistas"],["d","Diferença no patrimônio líquido do fundo, que seria ajustada no balanço social"]],"ans":"c","exp":"Tema: marcação na curva versus marcação a mercado. Na marcação na curva, os títulos são contabilizados pela taxa contratada, e não pelo preço de mercado. Isso gera distorção na rentabilidade apurada, porque quem entra ou sai em momentos diferentes pode ser beneficiado ou prejudicado, com transferência de renda entre cotistas. A alternativa C é a correta.\n\nA alternativa A (aumento do rendimento) não é o efeito. A alternativa B descreve o efeito da marcação a mercado, e não da curva. A alternativa D cita um ajuste em balanço social, que não existe nesse contexto.","id":"9965"},{"n":691,"banco":"lucas","mod":5,"tit":"V","titn":"Estrutura de Contas e Cadastro","cap":"1","capn":"Questão 1 (cód. 10102)","stem":"Sobre o cadastro de Investidores na B3, assinale o que for correto: I. A CVM, o Bacen, o CMN e a própria B3 estabelecem normas e procedimentos relativos ao cadastramento de investidores residentes que desejam atuar no mercado financeiro do Brasil. Já os investidores não residentes estão sujeitos à outra normatização. II. Os investidores devem ser identificados nas infraestruturas de mercado que utilizarão (sistemas de negociação, câmaras e depositárias). Sendo que, na B3, a identificação dos investidores é feita por meio da indicação de sua conta. III. A Central de Cadastro de Participantes é responsável por atividades de manutenção e suporte ao cadastro de investidores.","opts":[["a","Apenas I e II."],["b","Apenas II e III."],["c","Apenas III."],["d","Todas estão corretas."]],"ans":"b","exp":"Tema: cadastro de investidores na B3 e quem cadastra o quê. Analisando cada item:\n\nI. Correto. CVM, Bacen, CMN e a B3 estabelecem as normas de cadastro dos investidores residentes. Os não residentes seguem outra normatização, a Resolução CMN 4.373/2014 e a regulamentação da CVM sobre INRs.\n\nII. Correto. Os investidores precisam ser identificados nas infraestruturas que vão usar (sistemas de negociação, câmaras e depositárias). Na B3, a identificação se faz pela conta.\n\nIII. Correto. A Central de Cadastro de Participantes cuida da habilitação e manutenção de participantes, representantes e profissionais, além do suporte ao cadastro de investidores.\n\nOs três itens estão corretos, então a resposta é a alternativa D, mas o gabarito indica B. Esta é uma divergência a conferir: pelo texto da apostila, todos os itens procedem, e a alternativa D seria a correta. Vale checar com o material original antes de considerar a questão resolvida.","id":"10102"},{"n":692,"banco":"lucas","mod":5,"tit":"V","titn":"Estrutura de Contas e Cadastro","cap":"2","capn":"Questão 2 (cód. 10103)","stem":"Analise as asserções abaixo acerca do cadastro de Investidores na B3: A estrutura de contas criada a partir do cadastramento dos investidores é peça fundamental ao funcionamento ordenado do mercado. E por 3eio dessas contas que são realizadas as transações, registradas as posições, liquidadas as operações e guardados os ativos em nome dos titulares. Essa estrutura dá mais segurança ao mercado e aos investidores, pois garante a identificação dos direitos de propriedade de cada investidor em caso de insolvência ou falência de uma instituição intermediaria. A respeito dessas asserções, assinale a opção correta.","opts":[["a","As asserções I e II são proposições verdadeiras, e a II é uma justificativa correta da I."],["b","A asserção I é uma proposição verdadeira, e a II é uma proposição falsa."],["c","A asserção I é uma proposição falsa, e a II é uma proposição verdadeira."],["d","As asserções I e II são proposições falsas."]],"ans":"a","exp":"Tema: a estrutura de contas e a segurança do investidor. A asserção I é verdadeira: a estrutura de contas é peça fundamental, porque é nas contas que se registram as posições, se liquidam as operações e se guardam os ativos em nome dos titulares. A asserção II também é verdadeira: a segregação das contas em nome do investidor final garante a identificação dos direitos de propriedade em caso de insolvência ou falência de um intermediário. A II explica a I, porque é justamente a estrutura de contas individualizadas que dá segurança ao mercado. Alternativa A.","id":"10103"},{"n":693,"banco":"lucas","mod":5,"tit":"V","titn":"Estrutura de Contas e Cadastro","cap":"3","capn":"Questão 3 (cód. 10104)","stem":"No Know Your Costumer (KYC) e Suitability deve-se: I. Antes de começar a operar para um cliente, o participante deve empreender todos os esforços possíveis para conhecer seu cliente, seu perfil, sua capacidade financeira e, como consequência, quais operações lhe são mais apropriadas e quais escapam totalmente do seu perfil. II. O participante deve conhecer seu cliente e poder, assim, verificar se os documentos e dados apresentados são condizentes com sua realidade e se fazem sentido com o perfil e natureza do cliente III. O participante tem a responsabilidade de deixar claro os riscos de cada operação, para o cliente, e tomar a decisão de investimento por ele.","opts":[["a","Apenas I está correta."],["b","Apenas I e II estão corretas."],["c","Apenas II e III estão corretas."],["d","Todas estão corretas."]],"ans":"b","exp":"Tema: KYC (conheça seu cliente) e suitability (adequação de perfil). O item I descreve o dever de conhecer o cliente antes de operar, e está correto. O item II descreve a verificação de que os documentos e dados são condizentes com a realidade do cliente, também correto. O item III é o que está errado: o participante deve informar os riscos, mas quem toma a decisão de investimento é o próprio cliente, e não o intermediário. Por isso a alternativa B (apenas I e II) é a correta.","id":"10104"},{"n":694,"banco":"lucas","mod":5,"tit":"V","titn":"Estrutura de Contas e Cadastro","cap":"4","capn":"Questão 4 (cód. 10105)","stem":"Qual é a primeira etapa a ser cumprida para habilitar um investidor a atuar nos mercados da B3?","opts":[["a","Cadastramento"],["b","Investimento"],["c","Especulação"],["d","Financiamento"]],"ans":"a","exp":"Tema: a etapa inicial para atuar nos mercados da B3. Antes de investir, especular ou financiar, o investidor precisa ser cadastrado. O cadastro é o pré-requisito da habilitação: sem ele não há conta, e sem conta não há operação. A alternativa A é a correta. Investimento, especulação e financiamento são finalidades ou modalidades de operação, que só fazem sentido depois do cadastro.","id":"10105"},{"n":695,"banco":"lucas","mod":5,"tit":"V","titn":"Estrutura de Contas e Cadastro","cap":"5","capn":"Questão 5 (cód. 10106)","stem":"De quem é a responsabilidade pela veracidade das informações fornecidas, e da sua manutenção periódica no processo de cadastro do investidor?","opts":[["a","Do próprio investidor"],["b","Bacen"],["c","Da instituição que efetuou o cadastro"],["d","Da empresa ao qual o investidor trabalha"]],"ans":"c","exp":"Tema: responsabilidade pela informação cadastral. A instituição que efetuou o cadastro é a responsável pela veracidade das informações e pela manutenção periódica. Ela precisa manter o cadastro atualizado e coerente com as operações, e responde pela autenticidade dos dados. A alternativa C é a correta. O investidor fornece os dados, mas quem responde pelo processo é o intermediário. O Bacen (B) não executa esse papel no cadastro, e a empresa em que o investidor trabalha (D) não tem nenhuma relação com a responsabilidade.","id":"10106"},{"n":696,"banco":"lucas","mod":5,"tit":"V","titn":"Estrutura de Contas e Cadastro","cap":"6","capn":"Questão 6 (cód. 10107)","stem":"No modelo de estrutura de contas da Câmara B3, é possível ao participante manter uma única conta para seu cliente em todos os mercados que atue, permitindo a harmonização das regras e a consolidação de informações. Sobre o tema é correto afirmar que:","opts":[["a","Por fazer parte da estrutura do modelo de contas, é obrigatório ao participante a unificação de contas."],["b","A unificação das contas não é obrigatória, cabendo ao participante e ao cliente definir o nível de consolidação que mais lhes convier."],["c","Desde 2019 a unificação de contas é compulsória, sendo passível a aplicação de multa conforme a normatização elaborada pela CVM."],["d","É facultativo a unificação de contas, desde que o cliente apresente a documentação necessária que justifique sua escolha."]],"ans":"b","exp":"Tema: unificação de contas na Câmara B3. O modelo permite manter uma única conta para o cliente em todos os mercados, o que facilita a harmonização das regras e a consolidação de informações. Essa unificação não é obrigatória: cabe ao participante e ao cliente definir o nível de consolidação que mais convier. A alternativa B é a correta.\n\nA alternativa A afirma que a unificação é obrigatória, o que não está no modelo. A C fala em obrigatoriedade desde 2019 e multa pela CVM, afirmações sem base no material. A D diz que a unificação depende de documentação que justifique a escolha, o que também não corresponde ao texto.","id":"10107"},{"n":697,"banco":"lucas","mod":5,"tit":"V","titn":"Estrutura de Contas e Cadastro","cap":"7","capn":"Questão 7 (cód. 10108)","stem":"Tendo como contexto o cadastro de investidores residentes, qual o número de contas um investidor pode ter?","opts":[["a","Apenas uma conta"],["b","A abertura de contas é ilimitada para todos os investidores"],["c","A B3 delimita a abertura de três contas por investidor"],["d","Mais de uma conta, dependendo de seu perfil de atuação"]],"ans":"d","exp":"Tema: número de contas do investidor residente. A regra é que o investidor pode ter mais de uma conta, dependendo do seu perfil de atuação. A alternativa D é a correta. A alternativa A (uma só conta) confunde com a possibilidade de consolidação, que é facultativa. A B (abertura ilimitada) e a C (limite de três contas) não correspondem ao que o material apresenta. A regra é flexível e depende do perfil do investidor.","id":"10108"},{"n":698,"banco":"lucas","mod":5,"tit":"V","titn":"Estrutura de Contas e Cadastro","cap":"8","capn":"Questão 8 (cód. 10109)","stem":"Conta mantida na central depositária, individualizada ou não por comitente, para fins de guarda e controle da movimentação de ativos submetidos às atividades de depósito centralizado, bem como de guarda e movimentação de recursos financeiros e ativos depositados para assegurar a certeza da liquidação de operações (garantia). O texto se refere à:","opts":[["a","Conta de Depósito"],["b","Conta de Liquidação"],["c","Conta Máster"],["d","Conta Brokerage"]],"ans":"a","exp":"Tema: tipos de conta na B3. A conta de depósito fica na central depositária, individualizada ou não por comitente, e serve para guardar e controlar os ativos submetidos ao depósito centralizado, além de garantir a liquidação das operações. A alternativa A é a correta.\n\nA conta de liquidação (B) não é a conta de depósito, que é o nome específico do descrito. A conta máster (C) é a que agrupa contas de investidores vinculados. A conta brokerage (D) é usada pelo grande investidor que quer operar com mais de um participante, com possibilidade de anonimato. A palavra-chave do enunciado é \"central depositária\", que aponta para a conta de depósito.","id":"10109"},{"n":699,"banco":"lucas","mod":5,"tit":"V","titn":"Estrutura de Contas e Cadastro","cap":"9","capn":"Questão 9 (cód. 10110)","stem":"Associe corretamente as informações sobre Perfil da Conta: 1. Investidor não residente (Resolução nº 2687) 2. Cadastro Simplificado (RCVM nº 35) 3. High Frequency Trader (HFT) Perfil incluído no nível do titular da conta, para investidor não residente, que indica que o participante possui a documentação simplificada do investidor. Perfil incluído no nível de entidade e conta para gerar tarifas diferenciadas e decrescentes em função do volume de negociações realizado pelos comitentes no mercado de derivativos. Perfil incluído no nível da conta, durante o cadastro de conta, que restringe a conta automaticamente às negociações relacionadas aos mercados agropecuários.","opts":[["a","1, 3, 2002."],["b","2, 3, 2001."],["c","3, 1, 2002."],["d","1, 2, 2003."]],"ans":"b","exp":"Tema: perfis de conta. Os três itens do enunciado precisam ser associados aos perfis corretos:\n\n1. Investidor não residente: o perfil no nível do titular indica que o participante tem a documentação simplificada. Pelo texto, isso se refere ao cadastro simplificado, que é o número 2.\n2. Tarifas diferenciadas e decrescentes conforme o volume de negociação no mercado de derivativos: esse é o perfil de High Frequency Trader, o número 3.\n3. Conta restrita a negociações agropecuárias, definida no cadastro: esse é o perfil do investidor não residente, o número 1.\n\nA sequência correta seria 2, 3, 1. A alternativa B traz \"2, 3, 2001\", e o ano é um ruído no texto da prova. O enunciado original da questão tem um erro de digitação nos números, então a leitura dos dois primeiros números leva à alternativa B. Vale conferir o material original antes de usar.","id":"10110"},{"n":700,"banco":"lucas","mod":5,"tit":"V","titn":"Estrutura de Contas e Cadastro","cap":"10","capn":"Questão 10 (cód. 10111)","stem":"Segundo a CVM, pessoas físicas ou jurídicas, fundos ou outras entidades de investimento coletivo, com residência, sede ou domicílio no exterior e que investem no Brasil, são chamados de:","opts":[["a","Investidores"],["b","Investidores estrangeiros (IEs)"],["c","Investidores não residentes (INRs)"],["d","Investidores do exterior (IEX)"]],"ans":"c","exp":"Tema: definição de investidor não residente (INR), segundo a CVM. São INRs as pessoas físicas ou jurídicas, fundos ou outras entidades de investimento coletivo, com residência, sede ou domicílio no exterior, que investem no Brasil. A alternativa C é a correta.\n\nA alternativa A (investidores) é genérica demais. As alternativas B (IEs) e D (IEX) são siglas que não aparecem na definição regulatória. A sigla que vale para a prova é INR.","id":"10111"},{"n":701,"banco":"lucas","mod":5,"tit":"V","titn":"Estrutura de Contas e Cadastro","cap":"11","capn":"Questão 11 (cód. 10112)","stem":"Conforme as regras gerais para Investidores não residentes: I. O investidor não residente possui o mesmo acesso aos mercados disponíveis que dispõe o investidor residente. II. Diferentemente do investidor residente, o investidor estrangeiro não precisa contratar instituição para atuar como representante legal, representante fiscal e custodiante. III. Para ter acesso aos mercados disponíveis, o investidor não residente deve ser registrado no Brasil e internalizar recursos, em moeda local, mediante contratação de operações de câmbio.","opts":[["a","Apenas I e III."],["b","Apenas II."],["c","Apenas I e II."],["d","Apenas II e III."]],"ans":"a","exp":"Tema: regras gerais para o investidor não residente. Analisando cada item:\n\nI. Correto. O INR tem o mesmo acesso aos mercados que o residente, desde que atenda as condições do registro e da internalização dos recursos.\n\nII. Errado. Ao contrário do que o item diz, o INR precisa contratar instituições para atuar como representante legal, representante fiscal e custodiante. Essa exigência existe justamente porque ele não tem residência no Brasil.\n\nIII. Correto. Para acessar os mercados, o INR precisa estar registrado no Brasil (na CVM) e internalizar os recursos em moeda local, por meio de operações de câmbio.\n\nA combinação correta é I e III, alternativa A.","id":"10112"},{"n":702,"banco":"lucas","mod":5,"tit":"V","titn":"Estrutura de Contas e Cadastro","cap":"12","capn":"Questão 12 (cód. 10113)","stem":"O é o responsável por manter atualizados os documentos, controlar todos os ativos do investidor estrangeiro em contas segregadas e fornecer, a qualquer momento, informações solicitadas pelas autoridades ou pelo investidor. Assinale a alternativa que preenche corretamente a lacuna:","opts":[["a","Representante Legal"],["b","Representante Fiscal"],["c","Custodiante"],["d","Investidor residente"]],"ans":"c","exp":"Tema: as funções dos três representantes do investidor não residente. A função descrita no enunciado é a do custodiante: manter os documentos atualizados, controlar os ativos em contas segregadas e fornecer informações a qualquer momento, às autoridades ou ao investidor. A alternativa C é a correta.\n\nO representante legal (A) é quem responde perante a CVM e as autoridades pelos registros, e o representante fiscal (B) cuida dos temas tributáveis. A alternativa D não é uma função de representação, porque o próprio investidor não é quem executa esse papel no caso do INR.","id":"10113"},{"n":703,"banco":"lucas","mod":5,"tit":"V","titn":"Estrutura de Contas e Cadastro","cap":"13","capn":"Questão 13 (cód. 10114)","stem":"São pré-requisitos para o cadastro simplificado de investidores não residentes: I. A intermediária estrangeira deverá assumir, perante um intermediário estrangeiro, a obrigação de apresentar, sempre que for solicitado, todas as informações exigidas pelas instruções da CVM que dispõem sobre o cadastramento de investidores em âmbito do mercado de valores mobiliários devidamente atualizadas, como outras informações exigidas por órgãos públicos brasileiros com poderes de fiscalização. II. Investidores não residentes devem ser clientes de instituições intermediárias estrangeiras, perante a qual estejam devidamente cadastrados na forma da legislação aplicável no país de origem destas. III. O país que a intermediária estrangeira estiver sediada não deve ser considerado de alto risco no que diz respeito a matéria de lavagem de dinheiro e financiamento ao terrorismo, e não deve ser classificado como cooperante por organismos internacionais em relação ao combate de ilícitos dessa natureza.","opts":[["a","Apenas I e II."],["b","Apenas II e III."],["c","Apenas I e III."],["d","Todas estão corretas."]],"ans":"b","exp":"Tema: pré-requisitos do cadastro simplificado de INR. Os itens:\n\nI. Errado. A intermediária estrangeira deve assumir a obrigação perante o intermediário local, e não perante um intermediário estrangeiro. Esse é o ponto que torna o item falso.\n\nII. Correto. O investidor não residente precisa ser cliente de uma intermediária estrangeira em que esteja cadastrado conforme a legislação do país de origem.\n\nIII. Correto. O país da intermediária não pode ser de alto risco para lavagem de dinheiro e financiamento do terrorismo, nem estar classificado como não cooperante.\n\nA alternativa correta é B (apenas II e III). O item I é a pegadinha: basta trocar \"estrangeiro\" por \"local\" para ele ficar certo.","id":"10114"},{"n":704,"banco":"lucas","mod":5,"tit":"V","titn":"Estrutura de Contas e Cadastro","cap":"14","capn":"Questão 14 (cód. 10115)","stem":"São exigência em relação aos intermediários locais no processo de cadastro de investidores não residentes:","opts":[["a","Confiabilidade, Informações cadastrais e Compliance cadastral"],["b","Obrigação de informar a CVM, Confiabilidade e Signatário IOSCO"],["c","Rescisão de contrato, Signatário IOSCO e Informações cadastrais"],["d","Constituição de mandatário no Brasil, Compliance cadastral e Sujeição às normas no Brasil"]],"ans":"a","exp":"Tema: exigências para o intermediário local. O material lista como exigências: confiabilidade (critérios para avaliar a instituição estrangeira), informações cadastrais prontamente disponíveis e compliance cadastral (boas práticas de identificação de clientes). A alternativa A reúne essas três exigências, e por isso é a correta.\n\nAs demais misturam exigências do intermediário local com as do estrangeiro. Signatário IOSCO (B, C) é uma condição sobre o país da instituição estrangeira. Rescisão de contrato (C) é consequência do descumprimento, e não exigência prévia. A constituição de mandatário no Brasil (D) é cláusula contratual, não o rol de exigências ao intermediário local.","id":"10115"},{"n":705,"banco":"lucas","mod":5,"tit":"V","titn":"Estrutura de Contas e Cadastro","cap":"15","capn":"Questão 15 (cód. 10116)","stem":"Segundo a resolução CMN nº 4.373/2014, o investidor não residente está dispensado do registro requerido na CVM caso negocie, exclusivamente:","opts":[["a","Ações."],["b","Contratos agropecuários."],["c","Opções."],["d","Ouro."]],"ans":"b","exp":"Tema: dispensa do registro na CVM para o INR. Segundo a Resolução CMN 4.373/2014, o INR só fica dispensado do registro na CVM se negociar exclusivamente contratos agropecuários. A alternativa B é a correta.\n\nAções (A), opções (C) e ouro (D) são ativos negociados nos mercados de capitais ou no mercado de ouro, e para negociá-los o INR precisa do registro. A pegadinha é que o agro é o único caso de dispensa.","id":"10116"},{"n":706,"banco":"lucas","mod":5,"tit":"V","titn":"Estrutura de Contas e Cadastro","cap":"16","capn":"Questão 16 (cód. 10117)","stem":"O responsável por manter os dados atualizados e controlar os ativos do investidor não residente é:","opts":[["a","Representante legal."],["b","Representante fiscal."],["c","B3."],["d","Custodiante."]],"ans":"d","exp":"Tema: quem mantém os dados atualizados e controla os ativos. Essa é a função do custodiante: manter os documentos atualizados, controlar os ativos do investidor não residente em contas segregadas e fornecer informações quando solicitado. A alternativa D é a correta.\n\nO representante legal (A) é quem responde perante a CVM pelo registro. O representante fiscal (B) cuida dos temas tributários. A B3 (C) é a infraestrutura de mercado, não um representante do investidor. Atenção: a questão 12 do mesmo módulo cobra o mesmo conceito, com o nome de custodiante.","id":"10117"},{"n":707,"banco":"lucas","mod":5,"tit":"V","titn":"Estrutura de Contas e Cadastro","cap":"17","capn":"Questão 17 (cód. 10118)","stem":"O responsável pelos assuntos tributáveis e fiscais em nome do investidor não residente perante as autoridades brasileiras, é:","opts":[["a","Representante legal"],["b","Representante fiscal"],["c","B3"],["d","Custodiante"]],"ans":"b","exp":"Tema: representante fiscal. Ele é o responsável pelos assuntos tributáveis e fiscais em nome do investidor não residente, perante as autoridades brasileiras. A alternativa B é a correta.\n\nO representante legal (A) responde pelo registro e pela representação perante a CVM, não pela parte tributária. A B3 (C) é uma infraestrutura de mercado e não presta esse serviço. O custodiante (D) guarda os ativos e mantém os documentos, sem responder pelos tributos.","id":"10118"},{"n":708,"banco":"lucas","mod":5,"tit":"V","titn":"Estrutura de Contas e Cadastro","cap":"18","capn":"Questão 18 (cód. 10119)","stem":"O responsável por apresentar todas as informações de registro para as autoridades, para o investidor não residente, é:","opts":[["a","Representante legal."],["b","Representante fiscal."],["c","B3."],["d","Custodiante."]],"ans":"a","exp":"Tema: representante legal. Ele é o responsável por apresentar todas as informações de registro às autoridades em nome do investidor não residente. A alternativa A é a correta.\n\nA distinção a fixar é: legal (registro e informações às autoridades), fiscal (tributos) e custodiante (documentos e ativos). O representante fiscal (B) cuida dos tributos, e o custodiante (D) controla os ativos. A B3 (C) não é representante.","id":"10119"},{"n":709,"banco":"lucas","mod":5,"tit":"V","titn":"Estrutura de Contas e Cadastro","cap":"19","capn":"Questão 19 (cód. 10091)","stem":"A nomenclatura da conta mantida junto à central depositária, individual ou não pelo comitente, para fins de guarda e controle da movimentação de ativos que estão submetidos à atividades de depósitos centralizados, como de guarda e movimentação de recursos e ativos que estejam depositados para assegurar a garantia, é:","opts":[["a","Conta admincom"],["b","Conta máster"],["c","Conta de depósito"],["d","Conta intermediária"]],"ans":"c","exp":"Tema: conta de depósito. É a conta mantida junto à central depositária, individual ou não por comitente, usada para guardar e controlar a movimentação de ativos do depósito centralizado e para garantir a liquidação das operações. A alternativa C é a correta.\n\nA conta admincom (A) recebe ordens administradas. A conta máster (B) agrupa contas de investidores vinculados. A conta intermediária (D) intermedia operações em nome de outro participante. A palavra-chave do enunciado é \"central depositária\" e \"garantia\", que definem a conta de depósito.","id":"10091"},{"n":710,"banco":"lucas","mod":5,"tit":"V","titn":"Estrutura de Contas e Cadastro","cap":"20","capn":"Questão 20 (cód. 10092)","stem":"A nomenclatura da conta mantida na câmara da B3 com uso do participante de negociação pleno, como conta de intermediação de operações em nome de um participante, sendo ainda necessária a posterior distribuição para contas normais, é:","opts":[["a","Conta intermediária"],["b","Conta máster"],["c","Conta brokerage"],["d","Conta captura"]],"ans":"a","exp":"Tema: conta intermediária. Ela é mantida na câmara da B3 e usada pelo participante de negociação pleno para intermediar operações em nome de outro participante, que ainda precisa distribuir as operações para as contas normais. A alternativa A é a correta.\n\nA conta máster (B) vincula contas de investidores com vínculos em comum. A conta brokerage (C) permite que o investidor use mais de um participante. A conta captura (D) não é a conta de intermediação. A ideia central é o passo posterior de distribuição para as contas normais, que caracteriza a conta intermediária.","id":"10092"},{"n":711,"banco":"lucas","mod":5,"tit":"V","titn":"Estrutura de Contas e Cadastro","cap":"21","capn":"Questão 21 (cód. 10093)","stem":"Segundo a resolução do CMN nº 4.373, para investir no Brasil, o investidor estrangeiro necessita contratar uma instituição para se responsabilizar pela atualização dos documentos e controle dos ativos de um investidor em contas segregadas, e ainda fornecer informações que venham a ser solicitadas. Tal instituição é denominada como:","opts":[["a","Representante fiscal"],["b","Representante legal"],["c","Representante normativo"],["d","Custodiante"]],"ans":"d","exp":"Tema: custodiante do INR. O enunciado descreve a atualização dos documentos, o controle dos ativos em contas segregadas e o fornecimento de informações, que são as funções do custodiante. A alternativa D é a correta.\n\nO representante fiscal (A) cuida dos tributos e o legal (B) do registro. O representante normativo (C) não existe nessa classificação, é uma alternativa inventada para confundir.","id":"10093"},{"n":712,"banco":"lucas","mod":5,"tit":"V","titn":"Estrutura de Contas e Cadastro","cap":"22","capn":"Questão 22 (cód. 10094)","stem":"“Função de identificar clientes do participante de negociação e do participante de negociação pleno, por meio do qual o participante de negociação irá operar”. Tal definição refere – se ao tipo de vínculo:","opts":[["a","Conta e ordem"],["b","Custodiante"],["c","Consolidação de margem"],["d","Exercício de opções"]],"ans":"a","exp":"Tema: vínculo de conta e ordem. O vínculo permite que o participante de negociação pleno identifique os clientes do participante de negociação, por meio do qual o participante de negociação irá operar. Esse é o vínculo por conta e ordem, que liga o participante de negociação (PN) ao participante de negociação pleno (PNP). A alternativa A é a correta.\n\nA custódia (B) é outro tipo de vínculo, para os ativos. A consolidação de margem (C) centraliza a chamada de margem. O exercício de opções (D) liga o participante de liquidação a um participante de negociação para as opções.","id":"10094"},{"n":713,"banco":"lucas","mod":5,"tit":"V","titn":"Estrutura de Contas e Cadastro","cap":"23","capn":"Questão 23 (cód. 10095)","stem":"Refere – se a conta mantida na câmara utilizada apenas para possibilitar a identificação de ofertas originárias de ordens administradas concorrentes, do qual serão aquelas que especificam apenas a quantidade e a característica dos ativos a serem negociados, ficando a execução a critério do participante de negociação pleno:","opts":[["a","Admincom"],["b","Erro"],["c","Restrição"],["d","Captura"]],"ans":"a","exp":"Tema: conta admincom. Ela é mantida na câmara e serve para identificar as ofertas originárias de ordens administradas. Essas ordens especificam apenas a quantidade e a característica dos ativos, e a execução fica a critério do participante de negociação pleno. A alternativa A é a correta.\n\nA conta de erro (B) é criada pela B3 para operações não alocadas ou com erro operacional. A restrição (C) e a captura (D) são outras contas, com funções diferentes.","id":"10095"},{"n":714,"banco":"lucas","mod":5,"tit":"V","titn":"Estrutura de Contas e Cadastro","cap":"24","capn":"Questão 24 (cód. 10096)","stem":"Refere – se a conta que irá possuir contas de investidores vinculados, do qual irá agrupar investidores que possuam vínculos em comum, como gestão comum ou representação por um mesmo intermediário internacional que seja autorizado a realizar tais atividades:","opts":[["a","Conta de depósito"],["b","Conta máster"],["c","Conta admincom"],["d","Conta intermediária"]],"ans":"b","exp":"Tema: conta máster. Ela agrupa contas de investidores vinculados, que têm vínculos em comum, como gestão comum ou representação por um mesmo intermediário internacional autorizado. A alternativa B é a correta.\n\nA conta de depósito (A) é a conta de guarda de ativos. A admincom (C) recebe ordens administradas. A intermediária (D) intermedia operações. A chave é o agrupamento de contas vinculadas, que é o papel da conta máster.","id":"10096"},{"n":715,"banco":"lucas","mod":5,"tit":"V","titn":"Estrutura de Contas e Cadastro","cap":"25","capn":"Questão 25 (cód. 10097)","stem":"Refere – se a conta mantida na câmara da B3 utilizada para possibilitar o vínculo de repasse entre dois participantes (negociação pleno e liquidação), sem a necessidade de identificação do beneficiário final no participante origem:","opts":[["a","Conta restrição"],["b","Conta captura"],["c","Conta brokerage"],["d","Conta intermediária"]],"ans":"c","exp":"Tema: conta brokerage. Ela é usada pelo grande investidor que quer operar com mais de um participante, com possibilidade de anonimato. Mantida na câmara, possibilita o repasse entre dois participantes (negociação pleno e liquidação), sem que o beneficiário final precise ser identificado no participante de origem. A alternativa C é a correta.\n\nA conta intermediária (D) também participa de operações entre participantes, mas com o objetivo de distribuição posterior para contas normais, o que não é o caso descrito. A restrição (A) e a captura (B) têm outras finalidades.","id":"10097"},{"n":716,"banco":"lucas","mod":5,"tit":"V","titn":"Estrutura de Contas e Cadastro","cap":"26","capn":"Questão 26 (cód. 10098)","stem":"Vínculo existente em contas que possui a função de vincular uma conta normal cadastrada sob um participante de negociação ou participante de liquidação a outra conta normal, de mesma titularidade, cadastrada sob um mesmo participante. Tal definição refere – se ao tipo de vínculo:","opts":[["a","Consolidação de margem"],["b","Custodiante"],["c","Exercício das opções"],["d","Por conta e ordem"]],"ans":"a","exp":"Tema: consolidação de margem. Esse vínculo liga contas normais da mesma titularidade, cadastradas sob um mesmo participante, para centralizar a chamada de margem de garantia. A alternativa A é a correta.\n\nPor conta e ordem (D) liga participantes diferentes (PN e PNP). O custodiante (B) é o vínculo para a custódia dos ativos, e o exercício de opções (C) liga o participante de liquidação a um participante de negociação. Atenção ao detalhe da questão: \"mesma titularidade\" e \"mesmo participante\" caracterizam a consolidação, e não o vínculo por conta e ordem.","id":"10098"},{"n":717,"banco":"lucas","mod":5,"tit":"V","titn":"Estrutura de Contas e Cadastro","cap":"27","capn":"Questão 27 (cód. 10099)","stem":"Sobre o cadastro simplificado de investidores não residentes, analise as afirmativas abaixo: I. Investidores não residentes devem ser clientes de instituições intermediárias estrangeiras, perante a qual estejam devidamente cadastrados na forma da legislação aplicável no país de origem destas II. A intermediária estrangeira deverá assumir, perante um intermediário local, a obrigação de apresentar todas as informações exigidas pelas instruções da CVM que dispõem sobre o cadastramento de investidores em âmbito do mercado de valores mobiliários devidamente atualizadas, como outras informações exigidas por órgãos públicos III. O país que a intermediária estrangeira estiver sediada não deve ser considerado de alto risco no que diz respeito a matéria de lavagem de dinheiro e financiamento ao terrorismo, e não deve ser classificado como não cooperante por organismos internacionais em relação ao combate de ilícitos dessa natureza. Está correto o que se afirma em:","opts":[["a","I"],["b","II"],["c","III"],["d","Todas as alternativas"]],"ans":"d","exp":"Tema: cadastro simplificado de INR, com as três afirmativas.\n\nI. Correto. Os INRs precisam ser clientes de intermediárias estrangeiras, em que estejam cadastrados conforme a legislação do país de origem.\n\nII. Correto no sentido exigido pela CVM. A intermediária estrangeira assume, perante o intermediário local, a obrigação de apresentar as informações cadastrais e as demais exigidas por órgãos públicos.\n\nIII. Correto. O país da intermediária não pode ser de alto risco nem ser classificado como não cooperante.\n\nComo todas as afirmativas estão corretas, a alternativa D é a resposta. Observação: a formulação do item II no PDF menciona \"perante um intermediário local\", e essa é a forma correta. Se o enunciado trouxesse \"estrangeiro\" no lugar de \"local\", o item seria falso.","id":"10099"},{"n":718,"banco":"lucas","mod":5,"tit":"V","titn":"Estrutura de Contas e Cadastro","cap":"28","capn":"Questão 28 (cód. 10100)","stem":"Segundo a resolução do CMN nº 4.373, para investir no Brasil, o investidor estrangeiro necessita contratar uma instituição para se responsabilizar pelos assuntos tributáveis e fiscais em nome do investidor, perante a autoridade brasileira. Tal instituição é denominada como:","opts":[["a","Representante fiscal"],["b","Representante legal"],["c","Representante normativo"],["d","Custodiante"]],"ans":"a","exp":"Tema: representante fiscal, pela Resolução CMN 4.373. O representante fiscal responde pelos assuntos tributáveis e fiscais em nome do investidor, perante a autoridade brasileira. A alternativa A é a correta.\n\nO representante legal (B) responde pelo registro e pelas informações cadastrais. O normativo (C) não é uma figura da regulamentação. O custodiante (D) controla os ativos.","id":"10100"},{"n":719,"banco":"lucas","mod":5,"tit":"V","titn":"Estrutura de Contas e Cadastro","cap":"29","capn":"Questão 29 (cód. 10101)","stem":"Refere – se a conta transitória criada automaticamente pela bolsa de valores, sob titularidade do participante de negociação pleno, utilizada para recebimento de operações que não tenham uma conta especificada no ambiente de negociação.","opts":[["a","Conta restrição"],["b","Conta captura"],["c","Conta brokerage"],["d","Conta intermediária"]],"ans":"b","exp":"Tema: conta captura. É a conta transitória criada automaticamente pela bolsa, sob titularidade do participante de negociação pleno, usada para receber operações que não tenham conta especificada no ambiente de negociação. A alternativa B é a correta.\n\nA conta restrição (A) tem outra finalidade, e a brokerage (C) permite operar com vários participantes. A intermediária (D) intermedia operações em nome de outro participante, e não recebe operações sem conta definida. A palavra-chave é \"transitória\" e \"sem conta especificada\", que caracterizam a captura.","id":"10101"},{"n":720,"banco":"lucas","mod":6,"tit":"VI","titn":"Risco Corporativo e Controles Internos","cap":"1","capn":"Questão 1 (cód. 10131)","stem":"Refere – se a prática ilegal de posicionamento no mercado por participante antes dos clientes, objetivando vantagens:","opts":[["a","Churning"],["b","Front running"],["c","Front trading"],["d","Insider trading"]],"ans":"b","exp":"Tema: práticas abusivas de intermediação. A questão pede a prática em que o participante negocia antes dos clientes, aproveitando a informação de uma ordem que ainda vai ser executada. Essa conduta é o front running (ou \"operar na frente\"). A alternativa B está correta.\n\nPor que as outras não servem: o churning (A) é o giro excessivo da carteira para gerar corretagem, e não tem relação com a ordem de execução. O insider trading (D) é negociar com informação relevante ainda não divulgada, e não depende de ordens de clientes. Front trading (C) é tratado por muitos autores como sinônimo do front running; na prova, a resposta esperada é a forma mais comum, \"front running\", que é a alternativa B.","id":"10131"},{"n":721,"banco":"lucas","mod":6,"tit":"VI","titn":"Risco Corporativo e Controles Internos","cap":"2","capn":"Questão 2 (cód. 10132)","stem":"O risco de crédito é caracterizado por:","opts":[["a","Pela impossibilidade de pagamento apenas total do devedor"],["b","Pela impossibilidade de pagamento parcial ou total do devedor"],["c","Pela impossibilidade de default por parte do devedor do crédito"],["d","Pela impossibilidade de não honrar com os créditos por parte do devedor"]],"ans":"b","exp":"Tema: risco de crédito. Ele existe quando o devedor não paga, total ou parcialmente, o que foi pactuado. Por isso a alternativa B é a correta, pois abrange tanto o não pagamento parcial quanto o total.\n\nA alternativa A fala apenas em pagamento total, o que deixa de fora o atraso ou pagamento parcial. A C usa \"default\" de forma confusa, porque o default já é o próprio evento de crédito, não uma forma de caracterizar o risco. A D inverte a lógica: fala em \"não honrar\" e \"créditos\", mas a definição precisa mencionar a incapacidade de pagar a obrigação, parcial ou totalmente.","id":"10132"},{"n":722,"banco":"lucas","mod":6,"tit":"VI","titn":"Risco Corporativo e Controles Internos","cap":"3","capn":"Questão 3 (cód. 10133)","stem":"Caracteriza – se pela negociação excessiva ou giro em excesso da carteira de um investidor com objetivo de gerar maior corretagem:","opts":[["a","Churning"],["b","Front running"],["c","Front trading"],["d","Insider trading"]],"ans":"a","exp":"Tema: práticas abusivas. O churning é o giro excessivo da carteira de um cliente, com o objetivo de gerar corretagem para o intermediário, e não para o cliente. A alternativa A é a correta.\n\nO front running (B) é operar à frente de uma ordem do cliente. O front trading (C) tem características parecidas, mas é o termo usado para a mesma família de condutas. O insider trading (D) depende de informação privilegiada, o que não é a descrição dada no enunciado. O que define o churning é o volume de negociações sem justificativa para o cliente.","id":"10133"},{"n":723,"banco":"lucas","mod":6,"tit":"VI","titn":"Risco Corporativo e Controles Internos","cap":"4","capn":"Questão 4 (cód. 10134)","stem":"Caracteriza – se pela possibilidade de ser realizada uma estratégia mal sucedida ou ineficaz que não atinja os objetivos pretendidos:","opts":[["a","Risco de iliquidez"],["b","Risco operacional"],["c","Risco de principal"],["d","Risco estratégico"]],"ans":"d","exp":"Tema: tipos de risco corporativo. O risco estratégico é a possibilidade de implementar uma estratégia malsucedida ou ineficaz, que não alcança os objetivos pretendidos. A alternativa D é a correta.\n\nA alternativa A (risco de iliquidez) se refere à dificuldade de vender um ativo sem perda significativa. O B (risco operacional) é falha de processos, pessoas, sistemas ou eventos externos. O C (risco de principal) não faz parte da classificação do COSO ou da Resolução 4.557 apresentada na apostila. A lógica de decisão é: o problema está na escolha da estratégia, então é risco estratégico.","id":"10134"},{"n":724,"banco":"lucas","mod":6,"tit":"VI","titn":"Risco Corporativo e Controles Internos","cap":"5","capn":"Questão 5 (cód. 10135)","stem":"“A característica de liquidez em investimentos refere – se a quando os ativos são convertidos facilmente pelo em .” Complete as lacunas:","opts":[["a","Preço de mercado / valores mobiliários"],["b","Preço justo / dinheiro"],["c","Preço de mercado / ações"],["d","Preço justo / valores mobiliários"]],"ans":"b","exp":"Tema: liquidez. Um ativo tem boa liquidez quando pode ser convertido em dinheiro com facilidade e a um preço justo, sem que a operação altere de forma relevante o preço de mercado. A alternativa B traz \"preço justo / dinheiro\", que é a formulação correta.\n\nA alternativa A usa \"preço de mercado\", que tem o problema de ser o preço observado no momento, e não o preço justo. A C e a D trocam o \"dinheiro\" por ações ou valores mobiliários, o que não está na definição: liquidez é a conversão em caixa, qualquer que seja o ativo. Note também que a sentença usa \"preço justo\" e \"dinheiro\", que são os termos mais comuns nas provas sobre esse conceito.","id":"10135"},{"n":725,"banco":"lucas","mod":6,"tit":"VI","titn":"Risco Corporativo e Controles Internos","cap":"6","capn":"Questão 6 (cód. 10136)","stem":"Caracteriza o risco sistemático:","opts":[["a","O risco ligado a um setor específico"],["b","O risco ligado ao mercado como um todo"],["c","O risco que pode ser eliminado pela diversificação"],["d","O risco de um setor específico que pode ser mitigado"]],"ans":"b","exp":"Tema: diferença entre risco sistemático e não sistemático. O risco sistemático (também chamado de risco de mercado) atinge o mercado como um todo: juros, inflação, câmbio, crises políticas. Ele não pode ser eliminado pela diversificação, porque afeta todos os ativos ao mesmo tempo. A alternativa B é a correta.\n\nA alternativa A descreve um risco setorial, que é não sistemático. A C descreve justamente o contrário: o risco que a diversificação elimina é o não sistemático, e não o sistemático. A D também mistura setor com mitigação, e não define o risco sistemático.","id":"10136"},{"n":726,"banco":"lucas","mod":6,"tit":"VI","titn":"Risco Corporativo e Controles Internos","cap":"7","capn":"Questão 7 (cód. 10137)","stem":"A possibilidade de emissão de relatórios (sejam eles financeiros, fiscais, regulatórios, sustentabilidade ou estatutários) inexatos, expondo a instituição de penalidades refere – se ao:","opts":[["a","Risco legal"],["b","Risco financeiro"],["c","Risco de crédito"],["d","Risco de principal"]],"ans":"b","exp":"Tema: risco financeiro. Ele aparece quando a instituição emite relatórios financeiros, gerenciais, regulatórios, fiscais, estatutários ou de sustentabilidade incompletos, inexatos ou fora do prazo, sujeitando-se a multas e sanções. A alternativa B é a correta.\n\nO risco legal (A) está ligado à inadequação de contratos e ao descumprimento de normas em si, e não à qualidade da informação emitida. O risco de crédito (C) trata da inadimplência do tomador. O risco de principal (D) não é uma categoria apresentada no material.","id":"10137"},{"n":727,"banco":"lucas","mod":6,"tit":"VI","titn":"Risco Corporativo e Controles Internos","cap":"8","capn":"Questão 8 (cód. 10138)","stem":"Refere – se a negociação utilizando o conhecimento de informações relevantes e privilegiadas que não tenham sido publicadas com objetivo de obter lucro ou vantagem no mercado:","opts":[["a","Churning"],["b","Front running"],["c","Front trading"],["d","Insider trading"]],"ans":"d","exp":"Tema: insider trading. É a negociação com base em informação relevante e privilegiada que ainda não foi publicada, com o objetivo de obter lucro ou vantagem. A alternativa D é a correta.\n\nNa prova, a diferença importante é que o insider trading depende da posse de uma informação que o mercado não conhece. O front running (B) depende da informação da ordem de um cliente, e não de um fato relevante da empresa. O churning (A) é giro excessivo, e o front trading (C) é tratado como sinônimo do front running. Por isso, a palavra-chave \"informação privilegiada\" direciona para a alternativa D.","id":"10138"},{"n":728,"banco":"lucas","mod":6,"tit":"VI","titn":"Risco Corporativo e Controles Internos","cap":"9","capn":"Questão 9 (cód. 10139)","stem":"Refere – se ao risco de oscilação de preços de ativos no mercado:","opts":[["a","Risco de mercado"],["b","Risco de liquidez e câmbio"],["c","Risco de liquidez e rentabilidade"],["d","Risco de mercado e liquidez"]],"ans":"a","exp":"Tema: risco de mercado. Ele é a possibilidade de perdas por oscilação dos preços de ativos no mercado, como juros, câmbio, ações e commodities. A alternativa A é a correta.\n\nAs alternativas B, C e D misturam o risco de mercado com o risco de liquidez. O risco de liquidez não é oscilação de preço, e sim a dificuldade de vender ou de honrar obrigações. Os termos \"câmbio\" e \"rentabilidade\" não são categorias de risco no enunciado. A regra é: se o enunciado fala em oscilação de preços, a resposta é risco de mercado.","id":"10139"},{"n":729,"banco":"lucas","mod":6,"tit":"VI","titn":"Risco Corporativo e Controles Internos","cap":"10","capn":"Questão 10 (cód. 10140)","stem":"No modelo de gestão de risco, a gestão operacional está relacionada a fase:","opts":[["a","Introdutória"],["b","Terceira linha de defesa"],["c","Segunda linha de defesa"],["d","Primeira linha de defesa"]],"ans":"d","exp":"Tema: as três linhas de defesa. A primeira linha é a gestão operacional, quem executa a ação e é o \"dono do risco\" da função. A alternativa D é a correta.\n\nA segunda linha é a área de governança e controles internos, que fornece políticas e processos e monitora a primeira linha. A terceira linha é a auditoria interna, que avalia todo o sistema de forma independente. A alternativa \"introdutória\" (A) não é uma linha do modelo. Por isso, a gestão operacional está associada à primeira linha de defesa.","id":"10140"},{"n":730,"banco":"lucas","mod":6,"tit":"VI","titn":"Risco Corporativo e Controles Internos","cap":"11","capn":"Questão 11 (cód. 10141)","stem":"Sobre o Modelo das Três Linhas de Defesa considere V para verdadeiro e F para falso: ( ) É uma forma simples de promover a eficácia do gerenciamento de riscos e controle, na medida em que esclarece as responsabilidades essenciais. ( ) O modelo é aplicável apenas à organizações de grande porte e alta complexidade. ( ) Preconiza que o desenvolvimento e a implementação de atividades de controles internos são responsabilidades de todos os integrantes da organização, desde o funcionário que está envolvido diretamente na operação até o mais alto executivo. Qual a ordem correta?","opts":[["a","F, V, V."],["b","V, V, F."],["c","F, F, V."],["d","V, F, V."]],"ans":"d","exp":"Tema: Modelo das Três Linhas de Defesa e suas características gerais. Vamos analisar cada afirmativa.\n\n(V) O modelo é uma forma simples e eficaz de gerenciar riscos, porque esclarece papéis e responsabilidades de cada agente, por camadas.\n\n(F) A apostila afirma que o modelo é aplicável a qualquer organização, independentemente do tamanho e da complexidade. Por isso a afirmativa que restringe o modelo a grandes organizações é falsa.\n\n(V) O controle interno é responsabilidade de todos, do funcionário que executa a operação ao executivo mais alto.\n\nA sequência é V, F, V, que corresponde à alternativa D.","id":"10141"},{"n":731,"banco":"lucas","mod":6,"tit":"VI","titn":"Risco Corporativo e Controles Internos","cap":"12","capn":"Questão 12 (cód. 10142)","stem":"No gerenciamento de riscos corporativos e controles internos, utiliza-se o modelo de Três Linhas de Defesa. A Primeira, Segunda e Terceira linha são, respectivamente:","opts":[["a","Funcionários e Gerentes da Linha de Frente; Grupos de Gestão de Riscos e Compliance; Auditoria Externa."],["b","Gestão operacional; Governança/controles internos; Auditoria interna."],["c","Funcionários e Gerentes da Linha de Frente; Auditoria Interna e Grupos de Gestão de Riscos e Compliance."],["d","Gestão operacional; Governança/controles externos; Auditoria externa."]],"ans":"b","exp":"Tema: funções de cada linha de defesa. A primeira linha é a gestão operacional, a segunda é a governança e os controles internos (com gestão de riscos e compliance), e a terceira é a auditoria interna. A alternativa B é a correta.\n\nNa alternativa A, a auditoria externa não é a terceira linha: a apostila fala em auditoria interna, que reporta ao conselho e tem independência. A C troca a ordem da segunda e da terceira linhas. A D troca \"interna\" por \"externa\" e fala em controles externos, o que não corresponde ao modelo. Vale fixar a ordem: operação, controles, auditoria.","id":"10142"},{"n":732,"banco":"lucas","mod":6,"tit":"VI","titn":"Risco Corporativo e Controles Internos","cap":"13","capn":"Questão 13 (cód. 10143)","stem":"Sobre o Modelo das Três Linhas de Defesa, assinale o que for correto: I. A primeira linha está relacionada à ação do próprio funcionário que executa determinado processo ou função. E por ser a área diretamente envolvida no processo, é a que tem o maior nível de independência em relação às atividades de controle. II. A função da segunda linha é avaliar se os controles implementados estão funcionando adequadamente para prevenir o risco. III. Cabe a terceira linha a verificação dos procedimentos de cadastro, tais como know your customer e suitability, empregados pelo participante. Esses procedimentos visam, entre outras coisas, prevenir a lavagem de dinheiro. IV. A terceira linha monitora permanentemente as atividades, identifica as falhas nos controles internos, faz recomendações de aprimoramentos e acompanha a sua implementação.","opts":[["a","Apenas I e II"],["b","Apenas II e III"],["c","Apenas II e IV"],["d","Apenas III e IV"]],"ans":"c","exp":"Tema: atribuições de cada linha. A alternativa C (apenas II e IV) é a correta, segundo o gabarito. Vamos analisar cada item.\n\nI. Errado. A primeira linha é a que está mais diretamente envolvida no processo, então tem o menor grau de independência em relação às atividades de controle, e não o maior.\n\nII. Correto segundo o gabarito, mas com uma ressalva. A apostila atribui à auditoria interna (terceira linha) a função de avaliar se os controles estão funcionando, independentemente da ocorrência do risco. A segunda linha, pela apostila, fornece a política e monitora a implementação na primeira linha. Por isso, este item é o mais ambíguo da questão, e vale notar essa diferença para a prova.\n\nIII. Errado segundo o gabarito. A apostila trata KYC e suitability como procedimentos de cobrar, verificar e avaliar dentro das linhas de controle, e não como função própria da terceira linha. Vale fixar que a checagem de cadastro é controle de processo, e a auditoria só a avalia depois.\n\nIV. Correto. A terceira linha avalia a qualidade dos processos, identifica falhas nos controles internos, faz recomendações de melhoria e acompanha a implementação.","id":"10143"},{"n":733,"banco":"lucas","mod":6,"tit":"VI","titn":"Risco Corporativo e Controles Internos","cap":"14","capn":"Questão 14 (cód. 10144)","stem":"Criado em 1985 com a finalidade de assessorar a Comissão Nacional sobre Relatórios Financeiros Fraudulentos, foi encarregado de estudar fatores que pudessem levar à geração de relatórios fraudulentos e elaborar recomendações para empresas abertas e seus auditores, instituições educacionais, para a SEC e outros reguladores. A quem o texto se refere?","opts":[["a","OICV (Organização Internacional das Comissões de Valores)"],["b","COSO (Committee of Sponsoring Organizations of the Treadway Commission)"],["c","CRSFN – Conselho de Recursos do Sistema Financeiro Nacional"],["d","FRA (Forward Rate Agreement)"]],"ans":"b","exp":"Tema: origem e objetivos do COSO. O COSO (Committee of Sponsoring Organizations of the Treadway Commission) foi criado em 1985 para estudar os fatores que levam à emissão de relatórios financeiros fraudulentos e para elaborar recomendações a empresas abertas, auditores, instituições de ensino, SEC e outros reguladores. A alternativa B é a correta.\n\nA OICV (A) é a organização internacional das comissões de valores mobiliários, e não tem essa origem. O CRSFN (C) é o órgão de recursos do Sistema Financeiro Nacional, com função recursal. O FRA (D) é um instrumento derivativo (contrato a termo de taxa de juros), sem relação com controles internos. A pista decisiva é o nome da comissão, que é o próprio COSO.","id":"10144"},{"n":734,"banco":"lucas","mod":6,"tit":"VI","titn":"Risco Corporativo e Controles Internos","cap":"15","capn":"Questão 15 (cód. 10145)","stem":"O arcabouço do COSO descreve três categorias de objetivos (representados na ilustração pelos números 1, 2, 3) e cinco componentes essenciais de um sistema eficaz de controle interno e é usualmente sistematizado por meio do chamado cubo do COSO, ilustrado a seguir. São categorias de objetivo COSO:","opts":[["a","Operações, Monitoramento e Controle"],["b","Avaliação, Comunicação e Controle"],["c","Operações, Comunicação e Conformidade"],["d","Avaliação, Monitoramento e Conformidade."]],"ans":"c","exp":"Tema: as três categorias de objetivo do cubo do COSO. Elas são: operações (eficácia e eficiência, segurança dos ativos), comunicação ou reporting (confiabilidade dos relatórios contábeis e financeiros) e conformidade ou compliance (cumprimento das leis e normas). A alternativa C é a correta.\n\nAs alternativas A, B e D trazem monitoramento, avaliação e controle, que são componentes ou outras palavras do arcabouço, e não categorias de objetivo. Monitoramento é um dos cinco componentes essenciais do COSO, ao lado de ambiente de controle, atividades de controle e informação e comunicação. Vale distinguir objetivos (o que se quer) de componentes (como se alcança).","id":"10145"},{"n":735,"banco":"lucas","mod":6,"tit":"VI","titn":"Risco Corporativo e Controles Internos","cap":"16","capn":"Questão 16 (cód. 10146)","stem":"Componente de risco coorporativo que oferece possibilidade de ocorrência de perdas resultantes de falha, deficiência ou inadequação de processos internos, pessoas e sistemas, ou de eventos externos. Inclui o risco legal associado à inadequação ou deficiência dos contratos firmados pela instituição, bem como as sanções sofridas em razão do descumprimento dos dispositivos legais e de indenizações por danos de terceiros decorrentes de atividades desenvolvidas pela instituição. A que risco o trecho faz referência?","opts":[["a","Risco de Mercado"],["b","Risco de Crédito"],["c","Risco de Liquidez"],["d","Risco Operacional"]],"ans":"d","exp":"Tema: risco operacional, conforme a Resolução 4.557/2017. O enunciado fala em perdas por falha, deficiência ou inadequação de processos internos, pessoas e sistemas, ou por eventos externos, e menciona o risco legal ligado a contratos e sanções. Esse é o conceito de risco operacional. A alternativa D é a correta.\n\nO risco de mercado (A) decorre da flutuação de preços de posições. O risco de crédito (B) é o não pagamento do tomador. O risco de liquidez (C) é a dificuldade de vender um ativo por seu preço justo. A chave é a palavra \"processos\" e \"pessoas e sistemas\", que caracterizam o risco operacional.","id":"10146"},{"n":736,"banco":"lucas","mod":6,"tit":"VI","titn":"Risco Corporativo e Controles Internos","cap":"17","capn":"Questão 17 (cód. 10147)","stem":"É o risco ligado aos danos à reputação da instituição diante das partes interessadas, acarretando impactos no valor da marca.","opts":[["a","Risco de Imagem"],["b","Risco Financeiro"],["c","Risco Regulamentar"],["d","Risco Estratégico"]],"ans":"a","exp":"Tema: risco de imagem. É o risco de danos à reputação da instituição diante das partes interessadas, com impactos no valor da marca. A alternativa A é a correta.\n\nO risco financeiro (B) trata de informações contábeis e financeiras inexatas. O risco regulamentar (C) é a mudança nas normas e a pressão sobre o negócio. O risco estratégico (D) é a escolha de uma estratégia malsucedida. A expressão \"reputação\" e \"valor da marca\" são as palavras-chave para o risco de imagem.","id":"10147"},{"n":737,"banco":"lucas","mod":6,"tit":"VI","titn":"Risco Corporativo e Controles Internos","cap":"18","capn":"Questão 18 (cód. 10148)","stem":"A Resolução nº 4.557/2017 define normas para operações incluídas na carteira de negociação e demais posições. Mas em que consiste a Carteira de Negociação? I. Todas as operações com instrumentos financeiros e mercadorias, inclusive derivativos, detidas com intenção de negociação ou destinadas a hedge de outros elementos da carteira de negociação, e que não estejam sujeitas à limitação de sua negociabilidade. II. Na determinação de que as instituições financeiras e demais instituições autorizadas a funcionar pelo Bacen implementem controles internos voltados às atividades por elas desenvolvidas. III. Na indicação de diretor responsável peal estrutura de gerenciamento de capital.","opts":[["a","Apenas I está correta"],["b","Apenas I e II estão corretas"],["c","Apenas II e III estão corretas"],["d","Apenas III está correta"]],"ans":"a","exp":"Tema: carteira de negociação, segundo a Resolução 4.557/2017. A carteira de negociação reúne as operações com instrumentos financeiros e mercadorias, inclusive derivativos, detidas com intenção de negociação ou para hedge de outras posições da própria carteira, e que não estejam sujeitas a limitação de negociabilidade. Por isso a afirmativa I está correta.\n\nA II é falsa para esse conceito: ela descreve a determinação de controles internos das instituições em geral, que é a base da Resolução 2.554/1998, e não a carteira de negociação. A III também está errada, porque o diretor responsável pela estrutura de gerenciamento de capital não é o conceito de carteira. A alternativa A é a correta.","id":"10148"},{"n":738,"banco":"lucas","mod":6,"tit":"VI","titn":"Risco Corporativo e Controles Internos","cap":"19","capn":"Questão 19 (cód. 10149)","stem":"São deveres da auditoria interna no processo de gerenciamento de riscos corporativos e controles internos: I. Promover a avaliação independente das atividades desenvolvidas pelas áreas da instituição II. Impedir que a administração possa aferir a adequação dos controles internos, III. Colaborar para que a administração realize o cálculo de efetividade do gerenciamento dos riscos e dos processos de governança, da adequação dos controles que suportam a emissão das informações financeiras e o cumprimento das normas e regulamentos (compliance).","opts":[["a","Apenas I."],["b","Apenas II."],["c","Apenas I e III."],["d","Apenas II e III."]],"ans":"c","exp":"Tema: funções da auditoria interna no gerenciamento de riscos. Ela deve promover a avaliação independente das atividades, avaliar a adequação dos controles internos e colaborar com a administração na efetividade do gerenciamento de riscos, dos processos de governança e na aderência às normas (compliance). A alternativa C é a correta.\n\nA afirmativa II é falsa porque a auditoria não deve impedir a administração de avaliar os controles, e sim facilitar essa avaliação. Por isso as alternativas com II (B e D) ficam descartadas. A III, na sua formulação mais precisa, descreve o que a auditoria interna faz para apoiar a administração, de modo que a combinação I e III é a correta.","id":"10149"},{"n":739,"banco":"lucas","mod":6,"tit":"VI","titn":"Risco Corporativo e Controles Internos","cap":"20","capn":"Questão 20 (cód. 10150)","stem":"Analise as asserções abaixo: I. A auditoria interna tem a intenção de agregar valor e melhorar as operações das organizações, contribuindo na realização de seus objetivos a partir da aplicação de uma abordagem sistemática para avaliar e melhorar a eficácia dos processos de gerenciamento de riscos, controle e governança. II. Uma vez testado o sistema de controle interno, temos a clareza de seu bom funcionamento, o que permite retirar o monitoramento contínuo e uma aceleração dos processos. A respeito dessas asserções, assinale a opção correta.","opts":[["a","As asserções I e II são proposições verdadeiras, e a II é uma justificativa correta da I."],["b","A asserção I é uma proposição verdadeira, e a II é uma proposição falsa."],["c","A asserção I é uma proposição falsa, e a II é uma proposição verdadeira."],["d","As asserções I e II são proposições falsas."]],"ans":"b","exp":"Tema: auditoria interna e o monitoramento contínuo. A asserção I está correta: a auditoria interna busca agregar valor e melhorar as operações, por meio de uma abordagem sistemática para avaliar e melhorar a eficácia dos processos de gerenciamento de riscos, controle e governança.\n\nA asserção II é falsa: testar o sistema de controle interno não permite retirar o monitoramento contínuo. A avaliação de controles é periódica, mas o monitoramento é permanente, porque os riscos mudam. A alternativa B (I verdadeira e II falsa) é a correta.\n\nAtenção: a alternativa A ficaria certa apenas se a II fosse verdadeira e justificasse a I, o que não acontece.","id":"10150"},{"n":740,"banco":"lucas","mod":6,"tit":"VI","titn":"Risco Corporativo e Controles Internos","cap":"21","capn":"Questão 21 (cód. 10151)","stem":"Associada aos controles internos da organização, a atividade de Compliance (ou conformidade) é fundamental no gerenciamento de riscos. Mas qual seu objetivo?","opts":[["a","Assegurar o atendimento às leis, regulamentações, normas e aos regulamentos que regem determinada atividade ou processo."],["b","Realizar um controle interno, operacional, realizado pela própria instituição investigada."],["c","Elaborar relatórios que expressem ações a serem implementadas para a correção tempestiva das deficiências da empresa."],["d","Identificar falhas na execução, no cumprimento de prazos e no gerenciamento das atividades na instituição."]],"ans":"a","exp":"Tema: objetivo da atividade de compliance. Compliance (conformidade) tem como objetivo assegurar o atendimento às leis, às regulamentações, às normas e aos regulamentos que regem a atividade. A alternativa A é a correta.\n\nA alternativa B confunde compliance com um controle operacional. A C descreve um relatório de plano de ação, que é uma atribuição da auditoria ou de controles internos. A D descreve o papel da auditoria na identificação de falhas de execução. O foco do compliance é a aderência a normas, e não a eficiência operacional.","id":"10151"},{"n":741,"banco":"lucas","mod":6,"tit":"VI","titn":"Risco Corporativo e Controles Internos","cap":"22","capn":"Questão 22 (cód. 10152)","stem":"O risco microeconômico, em relação ao risco total, refere – se ao:","opts":[["a","Risco não diversificável."],["b","Risco sistemático."],["c","Risco diversificável."],["d","Risco de crédito."]],"ans":"c","exp":"Tema: risco microeconômico e risco total. O risco total de um ativo se divide em sistemático (não diversificável, de mercado) e não sistemático (diversificável, específico de uma empresa ou setor). O risco microeconômico é o risco específico de uma empresa ou setor, ou seja, o diversificável. A alternativa C é a correta.\n\nA alternativa A (não diversificável) descreve o risco sistemático, que atinge o mercado como um todo. A alternativa B é a mesma ideia de A, com outro nome. O risco de crédito (D) é um tipo de risco específico, mas não é a classificação pedida, que é a divisão entre sistemático e não sistemático.","id":"10152"},{"n":742,"banco":"lucas","mod":7,"tit":"VII","titn":"Negociação","cap":"1","capn":"Questão 1 (cód. 10201)","stem":"Considera-se mercado organizado de valores mobiliários (conforme CVM nº 461/2007): I. Apenas o espaço físico destinado à negociação, que atuam por conta própria ou de terceiros. II. Exclusivamente o sistema eletrônico destinado ao registro de operações com valores mobiliários por um conjunto determinado de pessoas autorizadas a operar III. O espaço físico ou o sistema eletrônico destinado à negociação ou ao registro de operações com valores mobiliários por um conjunto determinado de pessoas autorizadas a operar, que atuam por conta própria ou de terceiros. IV. As bolsas de valores, de mercadorias e de futuros, e os mercados de balcão organizado.","opts":[["a","Apenas I e IV"],["b","Apenas II e IV"],["c","Apenas III e IV"],["d","Apenas III"]],"ans":"c","exp":"Tema: definição de mercado organizado de valores mobiliários, pela ICVM 461/2007. A definição é o espaço físico ou o sistema eletrônico destinado à negociação ou ao registro de operações com valores mobiliários, por um conjunto determinado de pessoas autorizadas a operar, que atuam por conta própria ou de terceiros. Por isso o item III está correto.\n\nO item I está incompleto, porque fala só do espaço físico, e a norma admite também o sistema eletrônico. O item II restringe a definição ao registro, deixando de fora a negociação. O item IV lista tipos de entidade, e não a definição. A alternativa C (III e IV) é a indicada pelo gabarito, mas, pelo texto da própria apostila, o item IV também não é a definição em si. A leitura mais precisa é que apenas o III traz a definição, e a resposta mais coerente seria a D. Vale conferir a redação original da questão.","id":"10201"},{"n":743,"banco":"lucas","mod":7,"tit":"VII","titn":"Negociação","cap":"2","capn":"Questão 2 (cód. 10202)","stem":"Quais mercados possuem operações compreendidas pelo mercado organizado na B3, Segmento Listado B3? I. Mercado de bolsa II. Mercado de balcão organizado III. Mercado de câmbio","opts":[["a","Apenas I."],["b","Apenas II e III."],["c","Apenas I e III."],["d","I, II e III."]],"ans":"d","exp":"Tema: abrangência do mercado organizado na B3. Pela apostila, o mercado organizado reúne as operações realizadas no mercado de bolsa, no mercado de balcão organizado e no mercado de câmbio, todas estruturadas em sistemas centralizados e multilaterais de negociação. Por isso os três itens estão corretos, e a alternativa D é a resposta.\n\nA alternativa A (só bolsa) deixaria de fora o balcão organizado e o câmbio. As alternativas B e C também excluem algum dos três. A chave para a prova é lembrar que o mercado organizado não se limita à bolsa.","id":"10202"},{"n":744,"banco":"lucas","mod":7,"tit":"VII","titn":"Negociação","cap":"3","capn":"Questão 3 (cód. 10203)","stem":"São mercados ligados ao mercado de balcão organizado (Segmento Listado B3):","opts":[["a","Mercado à Vista de Renda Variável; Mercado de Derivativos; Mercado a Termo"],["b","Mercado à Vista de Renda Variável; Mercado à Vista de Renda Fixa Privada; Operações Ex-Pit"],["c","Mercado à Vista de Renda Fixa Privada; Mercado à Vista de Ouro; Estratégias"],["d","Operações Ex-Pit; Mercado de Dólar Pronto"]],"ans":"b","exp":"Tema: mercados ligados ao balcão organizado (Segmento Listado). O balcão organizado é o ambiente fora da bolsa, com negociação de contratos não padronizados, como swap, NDF e opções flexíveis, e com operações ex-pit. A alternativa B reúne mercado à vista de renda variável, mercado à vista de renda fixa privada e operações ex-pit, que são os ambientes ligados ao balcão na apostila. A alternativa A traz derivativos de bolsa e termo, que são da bolsa. A alternativa C inclui ouro e estratégias, que pertencem a outros ambientes. A alternativa D inclui dólar pronto, que é ambiente de câmbio.","id":"10203"},{"n":745,"banco":"lucas","mod":7,"tit":"VII","titn":"Negociação","cap":"4","capn":"Questão 4 (cód. 10204)","stem":"São considerados mercados de bolsa aqueles mercados que: I. Funcionam essencialmente como sistemas centralizados de negociação. II. Propiciam o encontro e a interação de ofertas de compra e de venda de valores mobiliários; III. Admite a execução de negócios, sujeitos ou não à interferência de outras pessoas autorizadas a operar no mercado, tendo como contraparte formador de mercado que assuma a obrigação de colocar ofertas firmes de compra e de venda.","opts":[["a","Apenas I e II."],["b","Apenas II e III."],["c","Apenas II."],["d","Todas estão corretas."]],"ans":"b","exp":"Tema: características do mercado de bolsa. A apostila define a bolsa como sistema centralizado e multilateral de negociação, que possibilita o encontro e a interação de ofertas de compra e venda, e que permite a execução de negócios tendo como contraparte um formador de mercado com obrigação de inserir ofertas firmes.\n\nPela leitura do texto, os três itens procedem: o I (sistema centralizado), o II (encontro de ofertas) e o III (execução com formador de mercado). Por isso a resposta, segundo a teoria, seria a alternativa D. O gabarito indica B, que exclui o item I. Esta é uma divergência entre a chave e o texto da apostila. Recomendo conferir antes de considerar a questão resolvida.","id":"10204"},{"n":746,"banco":"lucas","mod":7,"tit":"VII","titn":"Negociação","cap":"5","capn":"Questão 5 (cód. 10205)","stem":"Nesse mercado são realizadas operações de compra e venda de ações e demais ativos admitidos à negociação, sendo o prazo de liquidação física e financeira (D+2) fixado nos regulamentos e procedimentos operacionais da Câmara da B3.","opts":[["a","A que mercado o texto faz referência?"],["b","Mercado à Vista de Renda Fixa Privada"],["c","Mercado à Vista de Ativos de Renda Variável"],["d","Mercado a Termo"]],"ans":"c","exp":"Tema: mercado à vista de renda variável. É onde se realizam as compras e vendas de ações e demais ativos admitidos à negociação, com liquidação física e financeira em D+2, fixada pelos regulamentos da câmara. A alternativa C é a correta.\n\nRenda fixa privada (B) tem regras próprias de leilão e de túneis, e não é o mercado descrito. Mercado a termo (D) tem prazo fixado pelas partes, e não o D+2 do regulamento da câmara.","id":"10205"},{"n":747,"banco":"lucas","mod":7,"tit":"VII","titn":"Negociação","cap":"6","capn":"Questão 6 (cód. 10206)","stem":"Define-se Bônus de subscrição por:","opts":[["a","Títulos negociáveis emitidos por sociedades por ações, que conferem aos seus titulares, nas condições constantes do certificado, o direito de subscrever ações do capital social da companhia, dentro dos limites estatutários."],["b","Título emitido por qualquer companhia de capital aberto, que confere a seu titular, nas condições constantes do certificado, direito de comprar ações da companhia"],["c","Título emitido por sociedade anônima, que confere a seu titular, nas condições constantes do certificado, direito de vender ações para a companhia"],["d","Título emitido por uma companhia aberta, de capital autorizado, que confere a seu titular, nas condições por ele determinadas de vender ações"]],"ans":"a","exp":"Tema: bônus de subscrição. São títulos negociáveis emitidos por sociedades por ações, que dão aos titulares, nas condições do certificado, o direito de subscrever ações do capital social dentro dos limites estatutários. Esse direito protege o acionista contra a diluição e permite a negociação no mercado secundário. A alternativa A é a correta.\n\nAs demais alternativas trocam o direito de subscrever (ou seja, comprar ações novas emitidas pela companhia) por direito de comprar ações já existentes, de vender ações à companhia ou de vender ações por condições fixadas pelo titular. Isso não corresponde ao bônus de subscrição.","id":"10206"},{"n":748,"banco":"lucas","mod":7,"tit":"VII","titn":"Negociação","cap":"7","capn":"Questão 7 (cód. 10207)","stem":"Com relação ao Recibo de Carteira Selecionada de Ações (RCSA), considere V para verdadeiro e F para falso: ( ) RCSA é o recibo representativo de um conjunto preestabelecido de ações cujas quantidades ainda não foram estabelecidas no ato de sua constituição. ( ) As ações que compõem a Carteira Selecionada de Ações deverão estar, obrigatoriamente, custodiadas na Câmara da B3 em que cada recibo representará parcela de uma determinada Carteira Selecionada de Ações. ( ) A Carteira Selecionada de Ações poderá ser constituída por instituições e investidores interessados em participar de sua constituição, observadas, para tal fim, as normas fixadas pela B3.","opts":[["a","F, V, V,"],["b","V, F, F"],["c","F, V, V"],["d","V, F, F"]],"ans":"a","exp":"Tema: Recibo de Carteira Selecionada de Ações (RCSA). A apostila desta edição não traz a definição do RCSA nas páginas de teoria do Módulo 7, então a análise abaixo depende de conhecimento complementar, e não do texto que tenho disponível.\n\nO primeiro item, em princípio, descreve um recibo de carteira preestabelecida; o segundo fala de custódia das ações e de cada recibo representar parcela da carteira; o terceiro diz que a carteira pode ser constituída por instituições e investidores, observadas as normas da B3. A chave indica F, V, V. Como o texto da apostila não cobre esse ativo, não consigo confirmar as três afirmativas com segurança. Vale verificar a regulamentação específica do RCSA.","id":"10207"},{"n":749,"banco":"lucas","mod":7,"tit":"VII","titn":"Negociação","cap":"8","capn":"Questão 8 (cód. 10208)","stem":"Em qual forma o ouro é negociado como produto financeiro no Brasil conforme B3?","opts":[["a","Pepita"],["b","Lingotes de ouro fino"],["c","Barra de 500 gramas"],["d","Toda forma é aceita pela B3"]],"ans":"b","exp":"Tema: formas de negociação do ouro como ativo financeiro na B3. O ouro é negociado em forma de lingotes de ouro fino, em contratos padrão e fracionário. O lote padrão é de um lingote de 250 g, e há lotes fracionários de 10 g e de 0,225 g, com teor de pureza de 999 partes por 1.000. A alternativa B é a correta.\n\nPepita (A) não é a forma negociada, e barras de 500 gramas (C) não correspondem ao lote padrão. A alternativa D (qualquer forma) não procede, porque a B3 define a forma específica de negociação.","id":"10208"},{"n":750,"banco":"lucas","mod":7,"tit":"VII","titn":"Negociação","cap":"9","capn":"Questão 9 (cód. 10209)","stem":"Mercado onde são realizadas operações com contratos futuros e de opções padronizados admitidos à negociação pela B3, com prazo de liquidação definido no regulamento e no manual da câmara de compensação e liquidação da B3.","opts":[["a","Mercado à Vista de Ouro Ativo Financeiro"],["b","Mercado à Vista de Renda Fixa Privada"],["c","Mercado à Vista de Renda Variável"],["d","Mercado de derivativos de bolsa (ou derivativos listados)"]],"ans":"d","exp":"Tema: mercado de derivativos de bolsa (ou listados). É o mercado em que se negociam contratos futuros e de opções padronizados, admitidos à negociação pela B3, com prazo de liquidação definido nos regulamentos. A alternativa D é a correta.\n\nOuro ativo financeiro (A), renda fixa privada (B) e renda variável (C) são mercados à vista, em que a liquidação ocorre em prazo curto e não são contratos padronizados de derivativos. A pista do enunciado é a palavra \"padronizados\", que aponta para derivativos.","id":"10209"},{"n":751,"banco":"lucas","mod":7,"tit":"VII","titn":"Negociação","cap":"10","capn":"Questão 10 (cód. 10210)","stem":"Na B3, os contratos futuros (no Mercado de Derivativos de Bolsa) são separados em duas categorias: I. Contratos financeiros, referente a juros, moedas, índices etc. II. Contratos financeiros, referente a ouro, café, boi, energia etc. III. Contratos de commodities referente a juros, moedas, índices etc. IV. Contratos de commodities referente a ouro, café, boi, energia etc. Quais estão corretas?","opts":[["a","I e II"],["b","I e IV"],["c","II e III"],["d","II e IV"]],"ans":"b","exp":"Tema: categorias dos contratos futuros na B3. Os contratos são separados em financeiros (juros, moedas, índices) e de commodities (ouro, café, boi, energia). Assim, os itens I e IV estão corretos: juros e moedas são financeiros, e ouro e café são commodities. A alternativa B (I e IV) é a correta.\n\nOs itens II e III estão invertidos. Atenção: a questão exige a correspondência certa, não apenas a memorização dos exemplos.","id":"10210"},{"n":752,"banco":"lucas","mod":7,"tit":"VII","titn":"Negociação","cap":"11","capn":"Questão 11 (cód. 10211)","stem":"Estabeleça a correta relação entre as operações estruturadas e suas características: 1. Operação Estruturada de Rolagem 2. Operação Estruturada de Volatilidade 3. Forward Rate Agreement (FRC) Combina a negociação de dois contratos futuros de cupom cambial, com naturezas opostas, de forma a expor o investidor a um cupom cambial a termo, ou seja, com início em uma data futura. Possibilita que os investidores se protejam contra variações indesejadas de preço, limitando suas perdas em condições adversas de mercado. Mecanismo para negociar, em uma única operação, contrato de opções e de futuros em quantidades que representem um portfólio delta- -neutro.","opts":[["a","1, 2, 2003"],["b","2, 1, 2003"],["c","3, 1, 2002"],["d","1, 3, 2002"]],"ans":"c","exp":"Tema: operações estruturadas da B3. Cada operação tem uma característica própria:\n\n- Operação Estruturada de Rolagem: permite proteger-se contra variações indesejadas de preço, limitando perdas em condições adversas.\n- Operação Estruturada de Volatilidade: negocia, em uma só operação, opções e futuros em quantidades que representam um portfólio delta-neutro.\n- Forward Rate Agreement (FRC): combina dois futuros de cupom cambial de naturezas opostas, expondo o investidor a um cupom cambial a termo com início futuro.\n\nPela descrição, a associação correta é Rolagem com a proteção, Volatilidade com o delta-neutro e FRC com o cupom cambial. O enunciado apresenta os números das opções de forma confusa (os anos dos itens são ruído de digitação), e a alternativa C indicada pelo gabarito traz \"3, 1, 2002\". Para ler essa resposta, é preciso aplicar a associação de conteúdo, e não só os números. Vale conferir a numeração no material original.","id":"10211"},{"n":753,"banco":"lucas","mod":7,"tit":"VII","titn":"Negociação","cap":"12","capn":"Questão 12 (cód. 10212)","stem":"Sobre a característica da oferta no mercado de opções sobre, assinale o que for correto:","opts":[["a","O titular da opção de compra é obrigado a exercer a compra até o vencimento"],["b","O titular de uma opção de compra tem o direito de comprar certa quantia de ações, a um determinado preço de exercício fixado, até determinada data;"],["c","O lançador de opção de compra é obrigado a exercer a compra até o vencimento"],["d","O lançador de opção de compra tem o direito de comprar certa quantidade de ações, a um preço fixado até determinada data;"]],"ans":"b","exp":"Tema: direitos e obrigações em opções de compra. O titular de uma opção de compra (call) tem o direito de comprar uma quantidade de ativo, a um preço de exercício fixado, até determinada data. O lançador (quem vende a opção) tem a obrigação de vender se o titular exercer. A alternativa B é a correta.\n\nA alternativa A e a C dão ao titular uma obrigação que ele não tem, e atribuem ao lançador a obrigação de comprar, o que não é o caso de uma call. A alternativa D inverte a posição do lançador: quem tem o direito de comprar é o titular, e não o lançador. Vale fixar que o titular tem direito e o lançador tem dever.","id":"10212"},{"n":754,"banco":"lucas","mod":7,"tit":"VII","titn":"Negociação","cap":"13","capn":"Questão 13 (cód. 10213)","stem":"Na operação a termo o prazo de liquidação física e financeira da compra e venda de ativos é:","opts":[["a","Previamente fixado pelas partes"],["b","Padronizado para todo contrato"],["c","Liquidado na data de contratação"],["d","Liquidado 5 dias após o contrato"]],"ans":"a","exp":"Tema: mercado a termo. A característica central é que o prazo de liquidação física e financeira é previamente fixado pelas partes. Isso difere do mercado à vista (D+2, fixado pela câmara) e dos contratos padronizados. A alternativa A é a correta.\n\nA alternativa B descreve o termo comum com prazo padronizado, o que não é regra geral do termo. A C (liquidação na data da contratação) é a característica do mercado à vista de câmbio pronto em alguns casos. A D (5 dias após o contrato) não corresponde a nenhuma regra da apostila.","id":"10213"},{"n":755,"banco":"lucas","mod":7,"tit":"VII","titn":"Negociação","cap":"14","capn":"Questão 14 (cód. 10214)","stem":"Acerca dos elementos de uma operação em mercado a termo, assinale o que for correto: I. As operações com ações possuem prazo de vencimento fixado pelas partes, observados o mínimo de 16 dias e o máximo de 999 dias. II. Liquidação em data futura, preço oscilando segundo forças de mercado e fácil intercambialidade de posição III. Liquidação na data da contratação, preço oscilando segundo forças de mercado e dificuldade de reversão da posição assumida IV. Liquidação em data futura, preço predeterminado e dificuldade em reversão da posição assumida","opts":[["a","Apenas I e II"],["b","Apenas II e III"],["c","Apenas III e IV"],["d","Apenas I e IV"]],"ans":"d","exp":"Tema: elementos da operação a termo. Analisando:\n\nI. Correto. Para ações, o vencimento é fixado pelas partes, entre o mínimo de 16 dias e o máximo de 999 dias.\n\nII. Errado. No termo, a liquidação é futura e o preço é predeterminado na contratação, não oscila livremente. Além disso, a posição é de difícil reversão, e não de fácil intercambialidade.\n\nIII. Errado. A liquidação não é na contratação, e sim em data futura.\n\nIV. Correto. A liquidação é futura, o preço é predeterminado e a reversão da posição é difícil.\n\nA alternativa D (I e IV) é a correta.","id":"10214"},{"n":756,"banco":"lucas","mod":7,"tit":"VII","titn":"Negociação","cap":"15","capn":"Questão 15 (cód. 10215)","stem":"Sobre as operações ex-pit, considere V para verdadeiro e F para falso: ( ) Não possibilitam a precificação de posições a termo por meio de preços futuros ( ) As operações ex-pit não são submetidas à interferência de mercado ( ) Constituem negócios realizados fora do pit de negociação ou pregão de uma bolsa ( ) Constituem negócios realizados fora do pit de negociação ou pregão de uma bolsa","opts":[["a","F, V, V, F"],["b","V, F, F, V"],["c","F, V, F, V"],["d","V, F, V, F"]],"ans":"a","exp":"Tema: operações ex-pit. São negócios realizados fora do pit de negociação ou pregão da bolsa, sem interferência do mercado, e por isso não se submetem à formação de preço dos leilões. Analisando os itens:\n\n( ) Não possibilitam a precificação a termo por preços futuros. Falso, porque o ex-pit é usado justamente para negócios cujo preço é definido entre as partes.\n( ) Não são submetidas à interferência de mercado. Verdadeiro, pela teoria do módulo.\n( ) São negócios fora do pit ou pregão. Verdadeiro, é a definição.\n( ) São negócios fora do pit ou pregão. Repete o item anterior, e por isso deveria ter o mesmo valor.\n\nO gabarito indica F, V, V, F. O terceiro e o quarto itens são idênticos, mas o gabarito atribui valores diferentes a eles. Há uma inconsistência na chave. Vale conferir com o material original.","id":"10215"},{"n":757,"banco":"lucas","mod":7,"tit":"VII","titn":"Negociação","cap":"16","capn":"Questão 16 (cód. 10216)","stem":"Sobre os participantes da B3 assinale o que for correto: I. São classificados como participantes autorizados e participantes cadastrados II. Estão desautorizados a criar condições artificiais de demanda, oferta ou preço de ativos ou derivativos III. São incentivados a inserir ofertas no sistema de negociação visando ao posterior cancelamento ou à modificação de tais ofertas, com o objetivo de evitar o seu fechamento","opts":[["a","Apenas I"],["b","Apenas I e II"],["c","Apenas II e III"],["d","Todas estão corretas"]],"ans":"b","exp":"Tema: participantes da B3 e suas vedações. Analisando:\n\nI. Correto. Os participantes classificam-se em autorizados (PN, PNP, PL) e cadastrados (comitentes, formadores de mercado etc.).\n\nII. Correto. É vedado criar condições artificiais de demanda, oferta ou preço.\n\nIII. Errado. A apostila lista como vedação inserir ofertas com o objetivo de modificar ou cancelar, evitando que se concretizem. Ou seja, é proibido, e não incentivado.\n\nA alternativa B (I e II) é a correta.","id":"10216"},{"n":758,"banco":"lucas","mod":7,"tit":"VII","titn":"Negociação","cap":"17","capn":"Questão 17 (cód. 10217)","stem":"Participante cadastrado que atua, na condição de comitente, com o intuito de fomentar a liquidez de determinado ativo ou derivativo, observado o disposto nos regulamentos da B3 e na regulamentação em vigor:","opts":[["a","Participante de Negociação Pleno"],["b","Formador de Mercado"],["c","Comitente"],["d","Assessor Bancário Responsável"]],"ans":"b","exp":"Tema: formador de mercado. É o participante cadastrado que atua como comitente para fomentar a liquidez de um ativo, comprometendo-se a manter ofertas de compra e venda, de forma autônoma ou contratada pelo emissor. Deve ter quantidade mínima, spread máximo e percentual de atuação definidos, e está sujeito à fiscalização da B3. A alternativa B é a correta.\n\nO participante de negociação pleno (A) é autorizado e intermedia operações, sem o papel específico de fomentar liquidez. O comitente (C) é quem dá a ordem. O assessor bancário (D) não é a figura descrita.","id":"10217"},{"n":759,"banco":"lucas","mod":7,"tit":"VII","titn":"Negociação","cap":"18","capn":"Questão 18 (cód. 10218)","stem":"Sobre a Atuação do Formador de Mercado, analise as asserções a seguir: I. O formador de mercado não pode exercer sua atividade de forma a criar, direta ou indiretamente, condições artificiais de demanda, oferta ou preço dos ativos e/ou derivativos objetos de sua atuação ou incorrer em práticas não equitativas. II. Ele deve exercer sua atividade com estrita observância à regulamentação aplicável e manter elevados padrões éticos de conduta em sua atuação e nas demais atividades associadas aos mercados administrados pela B3. A respeito dessas asserções, assinale a opção correta.","opts":[["a","As asserções I e II são proposições verdadeiras, e a II é uma justificativa correta da I."],["b","A asserção I é uma proposição verdadeira, e a II é uma proposição falsa."],["c","A asserção I é uma proposição falsa, e a II é uma proposição verdadeira."],["d","As asserções I e II são proposições falsas."]],"ans":"a","exp":"Tema: atuação do formador de mercado. A asserção I é verdadeira: ele não pode criar condições artificiais de demanda, oferta ou preço, nem praticar operações não equitativas. A asserção II também é verdadeira: deve observar a regulamentação e manter padrões éticos elevados. Mas a II não justifica a I. Uma afirmação sobre ética não explica por que o formador não pode manipular preços. As duas são corretas, e são afirmações independentes.\n\nPor isso a alternativa A, que diz que a II justifica a I, é a resposta indicada pelo gabarito, mas o raciocínio da justificativa não se sustenta. A alternativa correta, pela análise, seria a que diz apenas que as duas são verdadeiras, sem relação de justificativa. Vale conferir a redação original.","id":"10218"},{"n":760,"banco":"lucas","mod":7,"tit":"VII","titn":"Negociação","cap":"19","capn":"Questão 19 (cód. 10219)","stem":"A responsabilidade principal do Membro de Compensação (MC) é: I. Liquidar, perante a câmara, as obrigações decorrentes das operações atribuídas ao membro de compensação (MC) e aos demais participantes que utilizam os seus serviços de compensação e liquidação II. Efetuar o depósito de garantias exigidas pela câmara, inclusive aquelas destinadas à constituição do fundo de liquidação, responsabilizando-se por sua autenticidade e legitimidade. III. Utilizar prática não equitativa que resulte, direta ou indiretamente, efetiva ou potencialmente, um tratamento para qualquer das partes de uma operação que a coloque em indevida posição de desequilíbrio ou desvantagem em face dos demais participantes da operação.","opts":[["a","Apenas I"],["b","Apenas I e II"],["c","Apenas II e III"],["d","Todas estão corretas"]],"ans":"b","exp":"Tema: responsabilidades do Membro de Compensação (MC). Analisando:\n\nI. Correto. O MC liquida perante a câmara as obrigações das operações atribuídas a ele e aos participantes que usam seus serviços.\n\nII. Correto. Cabe ao MC depositar as garantias exigidas pela câmara, inclusive as do fundo de liquidação.\n\nIII. Errado. A prática não equitativa é uma vedação aplicável aos participantes em geral, e não uma responsabilidade específica do MC. Além disso, o texto da prova descreve um conceito de conduta, e não uma atribuição.\n\nA alternativa B (I e II) é a correta.","id":"10219"},{"n":761,"banco":"lucas","mod":7,"tit":"VII","titn":"Negociação","cap":"20","capn":"Questão 20 (cód. 10220)","stem":"Entre os participantes autorizados e os participantes cadastrados da B3 que atuam na câmara, quem é o Participante de Negociação Pleno (PNP)?","opts":[["a","É o participante detentor de autorização de acesso para a intermediação de operações de comitentes e para a realização de operações próprias."],["b","É o participante detentor de autorização de acesso para custódia na central depositária da B3."],["c","É o participante detentor de autorização de acesso para liquidação financeira diretamente perante a câmara."],["d","É o participante detentor de autorização de acesso para negociação."]],"ans":"d","exp":"Tema: Participante de Negociação Pleno (PNP). Ele é o participante autorizado a intermediar operações de comitentes e a realizar operações próprias, com acesso ao ambiente de negociação. A chave indica a alternativa D, que fala em autorização para negociação. A questão tem uma formulação ampla, e a alternativa A é a que melhor descreve o PNP na sua função de intermediar comitentes e operar por conta própria. A distinção a fixar é: PNP é autorizado a negociar e intermediar; o PN só negocia, sem poder de liquidar perante a câmara; o PL liquida. Vale verificar a redação da questão, porque a alternativa A é a mais precisa, e a chave aponta outra.","id":"10220"},{"n":762,"banco":"lucas","mod":7,"tit":"VII","titn":"Negociação","cap":"21","capn":"Questão 21 (cód. 10221)","stem":"Considere V para verdadeiro e F para falso acerca da Compensação Multilateral: ( ) Consiste na apuração dos direitos e da obrigação líquido dos participantes ( ) É o procedimento destinado à apuração da soma dos resultados devedores e credores de cada participante em relação aos demais ( ) Esse procedimento gera um único resultado líquido entre os membros de compensação e a câmara","opts":[["a","V, F, V"],["b","F, F, V"],["c","V, V, V"],["d","F, V, F"]],"ans":"c","exp":"Tema: compensação multilateral. Ela apura os direitos e obrigações líquidos dos participantes, somando os resultados devedores e credores de cada um em relação aos demais. Ao final, gera um único resultado líquido entre cada membro de compensação e a câmara. Os três itens são verdadeiros, e a alternativa C é a correta.\n\nPara o primeiro item, a apuração é de direitos e obrigações líquidos. Para o segundo, a soma de devedores e credores. Para o terceiro, o resultado único líquido entre o MC e a câmara. A alternativa B (F, F, V) e as demais descartam itens que estão certos.","id":"10221"},{"n":763,"banco":"lucas","mod":7,"tit":"VII","titn":"Negociação","cap":"22","capn":"Questão 22 (cód. 10222)","stem":"São mecanismos de proteção e contenção de riscos da câmara, exceto:","opts":[["a","A utilização, no processo de liquidação, de mecanismo de entrega contra pagamento, destinado à mitigação do risco de principal."],["b","O cálculo e o depósito de garantias pelos membros de compensação, participantes de negociação plenos, participantes de liquidação, participantes de negociação e comitentes."],["c","O compartilhamento de mesma conexão por mais de um participante de negociação pleno ou um participante de negociação, ou seja, o fluxo de ofertas deve ser segregado para cada participante."],["d","\\N"]],"ans":"d","exp":"Tema: mecanismos de proteção e contenção de riscos da câmara, com a pergunta \"exceto\". Os mecanismos são: entrega contra pagamento para mitigar o risco de principal (item A, correto), cálculo e depósito de garantias (item B, correto), e o fundo de liquidação, os limites e as garantias. O compartilhamento de uma mesma conexão por mais de um participante (item C) é vedado pela apostila, e não é mecanismo de proteção.\n\nA alternativa D aparece no PDF como \"\\N\", um erro de digitação, sem texto. O gabarito marca D, que não tem conteúdo. Pelo raciocínio, a resposta correta é a C, porque é a única que não é mecanismo de proteção. Vale conferir a alternativa D no material original.","id":"10222"},{"n":764,"banco":"lucas","mod":7,"tit":"VII","titn":"Negociação","cap":"23","capn":"Questão 23 (cód. 10224)","stem":"Com relação aos períodos de negociação da bolsa de valores (B3), a alternativa que apresenta a ordem correta é:","opts":[["a","Pré abertura – Negociação – Cancelamento de ofertas – Call de fechamento – After market."],["b","Pré abertura – Negociação – Call de fechamento – After market."],["c","Pré abertura – Fase aberta – Negociação – Cancelamento de ofertas – Call de fechamento."],["d","Pré abertura – Cancelamento de ofertas – Negociação – Fechamento – After market."]],"ans":"b","exp":"Tema: fases da sessão de negociação na B3. A ordem pela apostila é: pré-abertura (registro de ofertas, sem operações), fase aberta (livre negociação), cancelamento de ofertas (sem novas ofertas), pré-fechamento (sem alterações) e call de fechamento (fixing final). Depois, a fase fechada.\n\nO gabarito indica a alternativa B, que traz \"after market\", termo que não aparece na teoria desta edição, e omite a fase de cancelamento. A alternativa C é a mais próxima da ordem da apostila, porque traz pré-abertura, fase aberta, cancelamento e call de fechamento, embora inclua \"negociação\" entre a fase aberta e o cancelamento. Por esse motivo, a resposta da chave não corresponde ao texto. Vale conferir o material original.","id":"10224"},{"n":765,"banco":"lucas","mod":7,"tit":"VII","titn":"Negociação","cap":"24","capn":"Questão 24 (cód. 10225)","stem":"Em caso de estado de sítio ou situações de emergência e calamidade pública, em relação as obrigações dos participantes do mercado de capitais: I. Estão dispensados das obrigações até o problema for resolvido II. Estão dispensados das obrigações, exceto os participantes pertencentes a cadeia de responsabilidades III. Não estarão dispensados de suas obrigações Julgue os itens como verdadeiro (V) ou falso (F).","opts":[["a","F – V. F"],["b","V. F – V"],["c","V. V. F"],["d","F – F – V"]],"ans":"d","exp":"Tema: obrigações dos participantes do mercado de capitais em caso de estado de sítio, emergência ou calamidade. A apostila trata dos planos de continuidade de negócios, que atendem casos de decretação de estado de defesa, estado de sítio ou calamidade pública, e prevê que a B3 mantém a continuidade de suas atividades. Ela não diz que os participantes ficam dispensados das obrigações. Por isso a afirmativa I (dispensa até a solução do problema) parece falsa, e a III (não dispensados) parece verdadeira.\n\nA chave indica F – F – V, e a leitura pela teoria confere com a III verdadeira e a I falsa. O item II, que fala em dispensa exceto a cadeia de responsabilidades, não está claro no texto da apostila, então não consigo confirmá-lo com segurança. Vale conferir a regra específica.","id":"10225"},{"n":766,"banco":"lucas","mod":7,"tit":"VII","titn":"Negociação","cap":"25","capn":"Questão 25 (cód. 10226)","stem":"Com relação ao dealers do mercado de câmbio, pode – se afirmar que:","opts":[["a","São sociedades corretoras de títulos e valores mobiliários e sociedades de crédito, financiamento e investimento."],["b","Instituições financeiras autorizadas a operar no mercado de câmbio para controlar sua cotação, caracterizada pela flutuação suja."],["c","São bancos escolhidos para atuar no mercado de câmbio, inserindo ofertas próprias e das demais instituições participantes do mercado."],["d","Instituições autorizadas pela B3 para acessar sua câmara de câmbio e realizar operações sem fiscalização do BACEN."]],"ans":"c","exp":"Tema: dealers do mercado de câmbio. São bancos escolhidos para atuar no mercado de câmbio, que inserem ofertas próprias e das demais instituições participantes. A alternativa C é a correta.\n\nA alternativa A descreve corretoras e sociedades de crédito, o que não é a definição de dealer. A alternativa B fala em \"flutuação suja\", um termo do controle cambial, e não define o dealer. A alternativa D diz que atuam sem fiscalização do Bacen, o que contraria o texto: o mercado de câmbio é fiscalizado pelo Bacen.","id":"10226"},{"n":767,"banco":"lucas","mod":7,"tit":"VII","titn":"Negociação","cap":"26","capn":"Questão 26 (cód. 10227)","stem":"Sobre o imposto de renda sobre pessoas físicas (IRPF) em operações de câmbio é possível afirmar que:","opts":[["a","O IRPF incide sobre o ganho de capital auferido na alienação de moeda estrangeira em 15%, e o recolhimento é de responsabilidade do próprio investidor beneficiário dos valores."],["b","O IRPF incide sobre o valor da venda auferido na alienação de moeda estrangeira sob tabela regressiva de IR."],["c","O IRPF incide sobre o valor da venda auferido na alienação de moeda estrangeira sob tabela progressiva de 15%."],["d","O IRPF incide sobre o ganho de capital auferido na alienação de moeda estrangeira em 15%, e o recolhimento é de responsabilidade da instituição financeira que intermediou a operação."]],"ans":"a","exp":"Tema: IRPF em operações de câmbio. A apostila desta edição não detalha a tributação de câmbio para pessoa física no trecho de teoria do módulo, então esta análise depende de conhecimento complementar.\n\nA chave indica que o IR incide sobre o ganho de capital na alienação de moeda estrangeira, à alíquota de 15%, com recolhimento pelo próprio investidor. Essa alternativa conflita com a D, que atribui o recolhimento à instituição intermediária. Como a questão 28 do mesmo módulo indica que o responsável pelo recolhimento de IR em câmbio para pessoa física é a própria pessoa física, a chave é coerente com ela. Mesmo assim, recomendo conferir a regra específica, porque a teoria desta edição não resolve a dúvida.","id":"10227"},{"n":768,"banco":"lucas","mod":7,"tit":"VII","titn":"Negociação","cap":"27","capn":"Questão 27 (cód. 10228)","stem":"Sobre o imposto de renda sobre pessoas jurídicas (IRPF) em operações de câmbio é possível afirmar que:","opts":[["a","O IRPJ incide sobre o ganho de capital auferido na alienação de moeda estrangeira em 15%, e o recolhimento é de responsabilidade da própria empresa beneficiária dos valores."],["b","O IRPJ incide sobre o valor de venda auferido na alienação de moeda estrangeira sob alíquota de 32% de presunção de lucro."],["c","O IRPJ incide sobre o ganho de capital auferido na alienação de moeda estrangeira e devem ser incluídos, assim como as variações cambiais dos direitos e obrigações, na base de cálculo do IR e ser pago pelo conselho fiscal da companhia."],["d","O IRPJ incide sobre o ganho de capital auferido na alienação de moeda estrangeira e devem ser incluídos, assim como as variações cambiais dos direitos e obrigações, na base de cálculo do IR e da contribuição social sobre o lucro líquido (CSLL)."]],"ans":"d","exp":"Tema: IRPJ em operações de câmbio. Para pessoa jurídica, o ganho de capital na alienação de moeda estrangeira entra na base de cálculo do IRPJ, assim como as variações cambiais de direitos e obrigações. Também entra na base da contribuição social sobre o lucro líquido (CSLL). A alternativa D é a correta.\n\nA alternativa A fala em alíquota de 15%, o que é regra da pessoa física. A B usa alíquota de presunção de 32%, que é a base para a receita da presunção, e não uma alíquota sobre o câmbio. A C diz que o conselho fiscal recolhe o imposto, o que não é a regra.","id":"10228"},{"n":769,"banco":"lucas","mod":7,"tit":"VII","titn":"Negociação","cap":"28","capn":"Questão 28 (cód. 10229)","stem":"O responsável pelo recolhimento de imposto de renda em operações de câmbio realizadas por pessoas físicas, do qual apura – se ganho de capital, é:","opts":[["a","Instituição financeira intermediadora"],["b","Pessoa física"],["c","B3"],["d","Clearing de câmbio da B3"]],"ans":"b","exp":"Tema: responsável pelo recolhimento de IR em câmbio para pessoa física com ganho de capital. Pela chave, a resposta é a própria pessoa física. Esse entendimento é coerente com a questão 26. A instituição financeira intermediadora (A) é a alternativa tentadora, porque aparece em outras questões do módulo, mas o enunciado trata do recolhimento pelo próprio beneficiário. A B3 e a clearing de câmbio (C e D) não são responsáveis pelo IR de pessoa física.\n\nRecomendo conferir a regra específica, porque a teoria desta edição não resolve a questão de forma completa.","id":"10229"},{"n":770,"banco":"lucas","mod":7,"tit":"VII","titn":"Negociação","cap":"29","capn":"Questão 29 (cód. 10230)","stem":"Sobre operações de câmbio, é correto afirmar que:","opts":[["a","O IRPF será de 22,5% até 15% para operações em que haja ganho de capital para pessoa física."],["b","O responsável pelo recolhimento de IRPF em operações de câmbio que apura – se ganho de capital é a instituição financeiras."],["c","Operações em que haja ganho de capital para pessoa jurídica não deverá ser recolhido IRPJ."],["d","Alienação abaixo R$ 5.000,00 no ano-calendário está isenta de IR."]],"ans":"d","exp":"Tema: síntese de regras de câmbio para pessoas físicas e jurídicas. Analisando:\n\nA) Errada: a alíquota de 15% é a regra, não uma faixa de 22,5% até 15%.\nB) Errada: o recolhimento de IR em câmbio de pessoa física cabe, pela questão 28, à própria pessoa física, não à instituição.\nC) Errada: o ganho de capital de pessoa jurídica é tributado pelo IRPJ.\nD) Correta pela chave: a alienação abaixo de R$ 5.000,00 no ano-calendário é isenta de IR.\n\nA alternativa D é a resposta. A teoria desta edição não detalha o limite de isenção, então esse valor precisa ser conferido na regra específica.","id":"10230"},{"n":771,"banco":"lucas","mod":7,"tit":"VII","titn":"Negociação","cap":"30","capn":"Questão 30 (cód. 10231)","stem":"Sobre IOF em operações de câmbio é correto afirmar que:","opts":[["a","A base de cálculo do IOF para operações de câmbio incide sobre o valor de alienação a alíquota de 15%."],["b","Operações de câmbio estão sujeitas a IOF sob tabela regressiva até o 29º dia do contrato."],["c","A base de cálculo do IOF para operações de câmbio incide sobre o montante em moeda nacional (recebido, entregue ou posto à disposição)."],["d","Operações de câmbio estão sujeitas a IOF progressivo a depender do valor da operação."]],"ans":"c","exp":"Tema: IOF em operações de câmbio. A base de cálculo do IOF de câmbio é o montante em moeda nacional recebido, entregue ou posto à disposição. A alternativa C é a correta.\n\nA alternativa A fala em alíquota de 15% sobre a alienação, o que mistura IR e IOF. A B e a D falam em tabela regressiva e progressiva, sistemas que não são o do IOF de câmbio: a alíquota depende da operação e do prazo, mas não é uma tabela progressiva de valor.","id":"10231"},{"n":772,"banco":"lucas","mod":7,"tit":"VII","titn":"Negociação","cap":"31","capn":"Questão 31 (cód. 10232)","stem":"Sobre operações ex pit, é correto afirmar que:","opts":[["a","São operações não submetidas à interferência de mercado."],["b","São operações realizadas dentro do ambiente de negociação da B3, sob fiscalização e atuação das clearings e central depositária."],["c","São operações de arbitragem no mercado realizadas fora do ambiente de negociação realizada por investidores institucionais."],["d","São operações acordadas entre as partes, sem interferência do mercado, exclusivamente para contratos agrícolas."]],"ans":"a","exp":"Tema: operações ex-pit. São operações acordadas entre as partes, fora do pregão ou ambiente de negociação, e não sofrem interferência do mercado. A alternativa A é a correta, pela teoria desta edição.\n\nA alternativa B descreve justamente o contrário, porque a operação ex-pit está fora do ambiente de negociação. A C fala em arbitragem por investidores institucionais, o que é uma restrição não prevista. A D limita a operação a contratos agrícolas, quando a apostila mostra que o uso agro é apenas um exemplo.","id":"10232"},{"n":773,"banco":"lucas","mod":7,"tit":"VII","titn":"Negociação","cap":"32","capn":"Questão 32 (cód. 10233)","stem":"Sobre os especuladores, arbitradores e hedgers do mercado de capitais, pode – se afirmar que:","opts":[["a","O hedger busca ganhar com as oscilações momentâneas de curto prazo do mercado."],["b","Especuladores buscam empresas sólidas para investimento de longo prazo observando seus fundamentos para carregar a posição."],["c","Arbitradores buscam obter ganhos com base em distorções de preços nos mercados."],["d","O hedger busca se proteger contra alta de preços, exclusivamente."]],"ans":"c","exp":"Tema: diferença entre hedgers, especuladores e arbitradores. O hedger usa derivativos para se proteger contra oscilações de preço, mas não se limita a proteger-se contra alta. Ele pode se proteger contra qualquer movimento. O arbitrador ganha com distorções de preço entre mercados. A alternativa C é a correta.\n\nA alternativa A descreve o especulador, que busca ganhos com oscilações de curto prazo. A alternativa B descreve o investidor de longo prazo, e não o especulador. A alternativa D restringe o hedger à alta de preços, o que é incorreto, porque ele se protege nos dois sentidos.","id":"10233"},{"n":774,"banco":"lucas","mod":7,"tit":"VII","titn":"Negociação","cap":"33","capn":"Questão 33 (cód. 10234)","stem":"Sobre o hedger, pode-se afirmar que:","opts":[["a","Seu objetivo é proteger – se contra a oscilação de preços, garantindo o preço de compra ou venda de determinada mercadoria em data futura."],["b","Seu objetivo é proteger – se contra a oscilação de preços, obtendo lucro com derivativos e alavancando sua posição para data futura predeterminada."],["c","Seu objetivo é especular posições visando obtenção de lucro de curto prazo em distorções de preços nos mercados."],["d","Seu objetivo é superar o índice Ibovespa com eficiência em aproveitar movimentos de curto e longo prazo no mercado."]],"ans":"a","exp":"Tema: hedger. Seu objetivo é proteger-se contra a oscilação de preços, garantindo o preço de compra ou venda de uma mercadoria em data futura. A alternativa A é a correta.\n\nA alternativa B mistura proteção com lucro e alavancagem, o que descreve especulação. A C é a definição do especulador. A D fala em superar o Ibovespa, objetivo de gestão de carteira, e não de hedge.","id":"10234"},{"n":775,"banco":"lucas","mod":7,"tit":"VII","titn":"Negociação","cap":"34","capn":"Questão 34 (cód. 10235)","stem":"Sobre o arbitrador, pode – se afirmar que:","opts":[["a","Seu objetivo é obter lucro no longo prazo com carteira de ações de empresas blue chips que distribuam dividendos."],["b","Seu objetivo é lucro, sem assumir riscos, buscando distorções de preços entre mercados e tirar proveito dessa diferença ou da expectativa futura dessa diferença."],["c","Seu objetivo é especular posições visando obtenção de lucro de curto prazo em distorções nos mercados."],["d","Seu objetivo é proteger – se contra a oscilação de preços, garantindo o preço de compra ou venda de determinada mercadoria em data futura."]],"ans":"b","exp":"Tema: arbitrador. Seu objetivo é obter lucro sem assumir risco, explorando distorções de preço entre mercados, ou a expectativa futura dessa diferença. A alternativa B é a correta.\n\nA alternativa A descreve um investidor de longo prazo em blue chips. A C descreve o especulador de curto prazo. A D descreve o hedger.","id":"10235"},{"n":776,"banco":"lucas","mod":7,"tit":"VII","titn":"Negociação","cap":"35","capn":"Questão 35 (cód. 10236)","stem":"Sobre o especulador, pode – se afirmar que:","opts":[["a","Seu objetivo é lucro, sem assumir riscos, buscando distorções de preços entre mercados e tirar proveito dessa diferença ou da expectativa futura dessa diferença."],["b","Seu objetivo é proteger – se contra a oscilação de preços, garantindo o preço de compra ou venda de determinada mercadoria em data futura."],["c","Sua atuação consiste na compra e venda de contratos futuros apenas para ganhar o diferencial entre o preço de compra e venda, sem interesse real pelo ativo."],["d","Sua atuação consiste na compra e venda de ações com objetivo de obtenção de lucro no longo prazo com carrego do ativo – objeto ."]],"ans":"c","exp":"Tema: especulador. Sua atuação consiste em comprar e vender contratos futuros para ganhar o diferencial de preço, sem interesse real pelo ativo subjacente. A alternativa C é a correta.\n\nA alternativa A descreve o arbitrador, que não assume risco. A B descreve o hedger. A D descreve o investidor de longo prazo, e não o especulador: o especulador não busca carregar o ativo, e sim o diferencial.","id":"10236"},{"n":777,"banco":"lucas","mod":7,"tit":"VII","titn":"Negociação","cap":"36","capn":"Questão 36 (cód. 10237)","stem":"Uma operação ex pit refere – se a:","opts":[["a","Operações realizadas exclusivamente no mercado agrícola."],["b","Transações realizadas com objetivo de especulação de ativos com distorções de preços de mercado."],["c","Qualquer transação executada fora dos meios convencionais, ou seja, fora da plataforma de negociação eletrônica B3, em bases não competitivas."],["d","Operações realizadas no mercado de balcão, apenas."]],"ans":"c","exp":"Tema: operação ex-pit. É qualquer transação executada fora dos meios convencionais de negociação, ou seja, fora da plataforma eletrônica da B3, em bases não competitivas. A alternativa C é a correta.\n\nA alternativa A limita a operação ao agro, o que não é verdadeiro. A B restringe a operação à especulação, o que também não corresponde. A D diz que é só o balcão, o que ignora a parte da definição sobre a ausência de competição.","id":"10237"},{"n":778,"banco":"lucas","mod":7,"tit":"VII","titn":"Negociação","cap":"37","capn":"Questão 37 (cód. 10191)","stem":"“A negociação de ouro pode ser realizada em lote padrão de ouro fino, do qual corresponde a lingotes com teor de pureza de ouro fino para cada 1.000 partes.” Complete a lacuna:","opts":[["a","250"],["b","1.000,00"],["c","999,9"],["d","999"]],"ans":"d","exp":"Tema: lote padrão de ouro fino. A apostila traz teor de pureza de 999,0 partes de ouro para cada 1.000 partes de metal. Por isso a lacuna se completa com 999, alternativa D.\n\nA alternativa A (250) é o peso do lingote-padrão em gramas, e não a pureza. A B (1.000) é o número de partes do metal, e não a pureza. A C (999,9) é um valor de pureza diferente do padrão da B3.","id":"10191"},{"n":779,"banco":"lucas","mod":7,"tit":"VII","titn":"Negociação","cap":"38","capn":"Questão 38 (cód. 10192)","stem":"Contratos futuros são caracterizados pela padronização dada pela regulamentação da bolsa de valores, do qual são estabelecidas todas as características do produto negociado, como por exemplo:","opts":[["a","Qualquer data de vencimento"],["b","Liquidação bruta e data de vencimento"],["c","Cotação e quantidade máxima"],["d","Cotação, tipo de liquidação e data de vencimento"]],"ans":"d","exp":"Tema: padronização dos contratos futuros. Os contratos padronizados têm todas as características definidas pela bolsa, como a cotação, o tipo de liquidação e a data de vencimento. A alternativa D é a correta.\n\nA alternativa A (qualquer data de vencimento) contraria a padronização, porque o vencimento é fixado. A B (liquidação bruta) não é característica padronizada obrigatória. A C (quantidade máxima) também não é característica padronizada típica do contrato.","id":"10192"},{"n":780,"banco":"lucas","mod":7,"tit":"VII","titn":"Negociação","cap":"39","capn":"Questão 39 (cód. 10193)","stem":"Refere – se a obrigação exigida de um lançador de uma put:","opts":[["a","Realize empréstimo ao titular da opção, até uma data prefixada, um lote padrão de um determinado ativo a um preço previamente acordado"],["b","Realize a compra do titular da put, até uma data prefixada, um lote padrão de determinado ativo a um preço previamente acordado"],["c","Realize a venda ao titular da put, até uma data prefixada, um lote padrão de determinado ativo a um preço previamente acordado"],["d","Não há obrigações para o lançador de put, apenas para o titular"]],"ans":"b","exp":"Tema: obrigação do lançador de uma put. O titular da put tem o direito de vender o ativo a um preço fixado até determinada data. Por isso, o lançador tem a obrigação de comprar do titular, se ele exercer. A alternativa B é a correta.\n\nA alternativa A fala em empréstimo, o que não é a natureza da opção. A alternativa C inverte a obrigação, atribuindo ao lançador a venda, que é o direito do titular. A alternativa D nega a obrigação do lançador, o que não é verdadeiro.","id":"10193"},{"n":781,"banco":"lucas","mod":7,"tit":"VII","titn":"Negociação","cap":"40","capn":"Questão 40 (cód. 10194)","stem":"“É de responsabilidade, dentro de suas atribuições, a apuração e punição de infrações dispostas no regulamento de negociação da B3, nas normas que complementam a legislação em vigor, do qual será aplicado, a depender do caso, penalidades previstas em seu estatuto social.” Tal definição refere – se a:","opts":[["a","BSM"],["b","BACEN"],["c","B3"],["d","CVM"]],"ans":"a","exp":"Tema: autorregulação e apuração de infrações. A definição do enunciado é a da BSM, que é a entidade de autorregulação responsável pela apuração e punição de infrações ao regulamento de negociação da B3. A alternativa A é a correta.\n\nA B3 (C) é a bolsa, mas quem apura as infrações é a BSM. O BACEN (B) e a CVM (D) são reguladores, e não aplicam penalidades pelo regulamento da bolsa.","id":"10194"},{"n":782,"banco":"lucas","mod":7,"tit":"VII","titn":"Negociação","cap":"41","capn":"Questão 41 (cód. 10195)","stem":"O procedimento operacional responsável por interromper a negociação de ativos e demais valores mobiliários em momentos atípicos de alta volatilidade no mercado, é nomeado de:","opts":[["a","After hours"],["b","Co location"],["c","STP"],["d","Circuit breaker"]],"ans":"d","exp":"Tema: circuit breaker. É o procedimento operacional que interrompe a negociação de ativos em momentos atípicos de excessiva volatilidade. Por exemplo, se o Ibovespa cai 10%, as negociações são suspensas por 30 minutos. A alternativa D é a correta.\n\nAfter hours (A) é negociação fora do horário regular, co location (B) é a hospedagem da infraestrutura, e STP (C) é a prevenção de operações do mesmo comitente consigo mesmo.","id":"10195"},{"n":783,"banco":"lucas","mod":7,"tit":"VII","titn":"Negociação","cap":"42","capn":"Questão 42 (cód. 10196)","stem":"O participante cadastrado do qual possui suas ordens enviadas ao ambiente de negociação através do registro de ofertas é chamado de:","opts":[["a","Formador de mercado"],["b","Comitente"],["c","PNP"],["d","PN"]],"ans":"b","exp":"Tema: quem envia ordens ao ambiente de negociação. O comitente é o cliente cadastrado, que dá as ordens que são registradas como ofertas pelo intermediário. A alternativa B é a correta.\n\nO formador de mercado (A) é um participante com obrigação de manter ofertas, não quem dá ordens de cliente. O PNP (C) e o PN (D) são os intermediários que registram as ofertas, e não o cliente que as envia.","id":"10196"},{"n":784,"banco":"lucas","mod":7,"tit":"VII","titn":"Negociação","cap":"43","capn":"Questão 43 (cód. 10197)","stem":"”O participante que utiliza sua conta Reservas Bancárias ou Conta de Liquidação para enviar ou receber pagamentos referentes aos processos de liquidação com a câmara”. Tal definição refere – se ao:","opts":[["a","Participante de negociação"],["b","Participante de liquidação"],["c","Membro de compensação"],["d","Banco liquidante"]],"ans":"d","exp":"Tema: participante de liquidação. Ele usa a conta de reservas bancárias ou a conta de liquidação para enviar e receber pagamentos relativos aos processos de liquidação com a câmara. A alternativa B é a correta, pela definição de PL.\n\nA chave indica a alternativa D, \"banco liquidante\". Esse termo não está definido na apostila, e a definição do enunciado descreve o participante de liquidação. Por isso a chave parece divergente do texto. Vale conferir o material original.","id":"10197"},{"n":785,"banco":"lucas","mod":7,"tit":"VII","titn":"Negociação","cap":"44","capn":"Questão 44 (cód. 10198)","stem":"A posição de contraparte da câmara da B3 na central de liquidação, se dá, perante o:","opts":[["a","Comitente"],["b","Participante de liquidação"],["c","Participante de negociação"],["d","Membro de compensação"]],"ans":"d","exp":"Tema: contraparte da câmara na liquidação. A câmara assume posição de contraparte central perante o membro de compensação, que é o responsável pelo pagamento do saldo líquido multilateral e pelos danos decorrentes de falhas das obrigações dos participantes a ele vinculados. A alternativa D é a correta.\n\nComitente (A), PL (B) e PN (C) são participantes vinculados ao MC, mas não são a contraparte da câmara. A responsabilidade perante a câmara é do MC.","id":"10198"},{"n":786,"banco":"lucas","mod":7,"tit":"VII","titn":"Negociação","cap":"45","capn":"Questão 45 (cód. 10199)","stem":"“É caracterizado como ___ o participante que não realizar a liquidação de sua obrigação, na forma estabelecida pela câmara, em decorrência de insuficiência financeira”. Complete a lacuna:","opts":[["a","Devedor operacional"],["b","Concordatário"],["c","Insolvente"],["d","Inadimplente"]],"ans":"d","exp":"Tema: devedor operacional e inadimplente. O devedor operacional não liquida por problema operacional, e o inadimplente não liquida por insuficiência financeira. O enunciado descreve o segundo caso. A alternativa D é a correta.\n\nDevedor operacional (A) é o caso de falha operacional, e não de falta de recursos. Concordatário (B) e insolvente (C) são termos do direito falimentar, que não definem a situação descrita pela câmara.","id":"10199"},{"n":787,"banco":"lucas","mod":7,"tit":"VII","titn":"Negociação","cap":"46","capn":"Questão 46 (cód. 10200)","stem":"Refere – se ao participante que possui autorização de acesso para custódia perante a central depositária da B3:","opts":[["a","Agente de custódia"],["b","Infraestrutura de mercado"],["c","Emissor"],["d","Escriturador"]],"ans":"a","exp":"Tema: participante com autorização de custódia perante a central depositária. É o agente de custódia, o participante que possui autorização para custódia dos ativos na central depositária da B3. A alternativa A é a correta.\n\nA infraestrutura de mercado (B) é a própria B3 e seus sistemas, não um participante. O emissor (C) é quem emite o ativo. O escriturador (D) mantém os registros de titularidade de ações, e não tem a autorização de custódia descrita.","id":"10200"},{"n":788,"banco":"lucas","mod":8,"tit":"VIII","titn":"Compliance","cap":"1","capn":"Questão 1 (cód. 10394)","stem":"Dentro do processo ABR, os clientes devem ser segmentados, minimamente, em:","opts":[["a","Alto e Baixo Risco"],["b","Conservadores e Arrojados"],["c","Médio e Alto Risco"],["d","Alto, Médio e Baixo Risco"]],"ans":"d","exp":"Tema: Abordagem Baseada em Risco (ABR) do PLD/FTP. A ABR obriga o participante a classificar produtos, serviços e clientes em três níveis: alto, médio e baixo risco. A ideia é concentrar esforços de identificação, monitoramento e mitigação nas situações de maior risco. A alternativa D é a correta.\n\nA alternativa A (alto e baixo) deixa de fora o nível intermediário. As alternativas B (conservadores e arrojados) e C (médio e alto) são classificações de perfil de investidor ou faixas incompletas. Vale fixar: a ABR usa sempre as três faixas.","id":"10394"},{"n":789,"banco":"lucas","mod":8,"tit":"VIII","titn":"Compliance","cap":"2","capn":"Questão 2 (cód. 10404)","stem":"São bases legais previstas na LGPD: I. Cumprimento de obrigação legal ou regulatória. II. Para execução de contrato ou procedimentos preliminares do qual o titular seja parte. III. Realização de estudos por ONGs. É correto o que se afirma em:","opts":[["a","I e II"],["b","II e III"],["c","I e III"],["d","Todas"]],"ans":"a","exp":"Tema: bases legais da LGPD para tratamento de dados. O item I está correto: o cumprimento de obrigação legal ou regulatória é base legal. O item II também está correto: a execução de contrato, ou de procedimentos preliminares de que o titular seja parte, é base legal. O item III está errado no ponto de vista da apostila, porque a base é a realização de estudos por órgão de pesquisa, e não por ONG. A alternativa A (I e II) é a correta.\n\nAtenção ao detalhe: a apostila usa a expressão \"órgãos de pesquisa\", com exemplo do IBGE. A questão troca isso por ONG, e por isso o item III não corresponde ao texto.","id":"10404"},{"n":790,"banco":"lucas","mod":8,"tit":"VIII","titn":"Compliance","cap":"3","capn":"Questão 3 (cód. 10403)","stem":"Quando o tratamento de dados pessoais ocorrer com base no consentimento: I. O consentimento deve ser dado por escrito ou por outro meio que demonstre a manifestação de vontade do titular dos dados, se for por meio de cláusula contratual deve ser destacada das demais. II. O Consentimento é dado para finalidades determinadas ou genéricas. III. O Consentimento dado para determinada finalidade não é extensível a outros fins, se houver outra finalidade, novo consentimento deve ser obtido. É correto o que se afirma em:","opts":[["a","I e II"],["b","II e III"],["c","I e III"],["d","Todas"]],"ans":"c","exp":"Tema: consentimento na LGPD. Para ser válido, o consentimento deve ser formalizado de forma clara, por escrito ou por outro meio, e precisa ter finalidade determinada. Não existe autorização genérica nem consentimento extensível. Além disso, o consentimento precisa poder ser revogado.\n\nAnalisando: o item I está correto, porque o consentimento pode ser escrito ou por outro meio, e a cláusula contratual deve ser destacada. O item II está errado, porque o consentimento é dado para finalidades determinadas, e não genéricas. O item III está correto, porque cada nova finalidade exige novo consentimento. A alternativa C (I e III) é a correta.","id":"10403"},{"n":791,"banco":"lucas","mod":8,"tit":"VIII","titn":"Compliance","cap":"4","capn":"Questão 4 (cód. 10402)","stem":"Sobre os direitos do titular de dados pessoais, avalie as afirmativas: I. É direito do titular de dados pessoais, assegurado pela LPGD, a anonimização, bloqueio ou eliminação de dados desnecessários, excessivos ou ilegais. II. Os direitos não são absolutos, o exercício pode ser recusado ou parcialmente atendido se necessário para preservar direitos de terceiro, segredos de negócios entre outras situações, sempre com a devida justificativa.","opts":[["a","Ambas as afirmativas são falsas"],["b","A afirmativa I é verdadeira, enquanto a II é falsa"],["c","A afirmativa I é falsa, enquanto a II é verdadeira"],["d","Ambas as afirmativas são verdadeiras"]],"ans":"d","exp":"Tema: direitos do titular. O item I está correto: a LGPD assegura a anonimização, o bloqueio ou a eliminação de dados desnecessários, excessivos ou tratados em desconformidade. O item II também está correto: os direitos não são absolutos, e podem ser recusados ou atendidos parcialmente quando houver base legal, sempre com justificativa. A alternativa D (ambas verdadeiras) é a correta.\n\nA apostila confirma o ponto central: a instituição deve oferecer meios para o titular exercer seus direitos, mas essa garantia não é absoluta e exige justificativa.","id":"10402"},{"n":792,"banco":"lucas","mod":8,"tit":"VIII","titn":"Compliance","cap":"5","capn":"Questão 5 (cód. 10401)","stem":"Os agentes de tratamento precisam manter registro das operações de tratamento de dados?","opts":[["a","Sim, apenas quando a base legal para o tratamento for o legítimo interesse"],["b","Não existe essa necessidade, pois a ANPD tem controle de todos os tratamentos realizados"],["c","Sim, apenas quando houver um tratamento indevido de dados"],["d","Sim, especialmente quando a base legal para o tratamento for o legítimo interesse"]],"ans":"d","exp":"Tema: registro das operações de tratamento de dados pelos agentes. O material desta edição não traz esse ponto explicitamente nas páginas de teoria do Módulo 8, então a análise depende de conhecimento complementar.\n\nA alternativa B é falsa, porque a ANPD não controla todos os tratamentos. A alternativa A e a D tratam o registro como dependente do legítimo interesse, o que não corresponde à lógica geral do dever de registro, que alcança o tratamento em si. A chave indica a D, mas ela restringe o dever a uma base legal específica, e isso não está confirmado no material disponível. Recomendo conferir o texto da lei antes de considerar a resposta resolvida.","id":"10401"},{"n":793,"banco":"lucas","mod":8,"tit":"VIII","titn":"Compliance","cap":"6","capn":"Questão 6 (cód. 10400)","stem":"O responsável pela comunicação em assuntos de proteção de dados e privacidade é chamado de:","opts":[["a","Compliance Officer"],["b","Head de Comunicação/Marketing"],["c","Encarregado/DPO"],["d","Diretor de RH"]],"ans":"c","exp":"Tema: Encarregado ou DPO (Data Protection Officer). É a figura que serve de canal de comunicação entre a instituição, os titulares de dados e a ANPD, e que implementa as medidas previstas na lei, processa as solicitações dos titulares e orienta funcionários e terceiros. A alternativa C é a correta.\n\nO compliance officer (A) cuida da conformidade em geral, e não é o canal de comunicação com titulares. O head de comunicação (B) trata da imagem e do marketing, e o diretor de RH (D) não tem essa função.","id":"10400"},{"n":794,"banco":"lucas","mod":8,"tit":"VIII","titn":"Compliance","cap":"7","capn":"Questão 7 (cód. 10399)","stem":"Sobre as obrigações dos agentes de tratamento: I. Devem indicar um encarregado pelo tratamento de dados pessoais, também conhecido como Data Protection Officer (DPO), para servir de canal de comunicação com os titulares sobre questões envolvendo privacidade e proteção de dados pessoais e com a ANPD. II. Devem oferecer meios para que os titulares consigam exercer seus direitos previstos na LGPD. III. A ANPD arcará com os prejuízos e danos, por força de falta de segurança adequada ou tratamento indevido do agente, visto que o cliente não pode ficar exposto. É correto o que se afirma em:","opts":[["a","I e II"],["b","II e III"],["c","I e III"],["d","Todas"]],"ans":"a","exp":"Tema: obrigações dos agentes de tratamento. O item I está correto: é obrigatório indicar o encarregado (DPO), que serve de canal com titulares e com a ANPD. O item II está correto: é preciso oferecer meios para que os titulares exerçam seus direitos. O item III está errado, porque quem responde pelos danos decorrentes de falha de segurança ou tratamento indevido é o agente de tratamento, e não a ANPD. A alternativa A (I e II) é a correta.","id":"10399"},{"n":795,"banco":"lucas","mod":8,"tit":"VIII","titn":"Compliance","cap":"8","capn":"Questão 8 (cód. 10398)","stem":"A LGPD se aplica a qualquer operação de tratamento de dados pessoais realizados por pessoa física ou jurídica independente do meio, país de sede ou de localização dos dados, desde que: I. A operação vise oferta ou fornecimento de bens e serviços no Brasil. II. A operação de tratamento ocorra em países que possuam acordos com o Banco Central do Brasil. III. Os dados tenham sido coletados no Brasil, ou sejam o titular estava no Brasil no momento da coleta. É correto o que se afirma em:","opts":[["a","I e II"],["b","II e III"],["c","I e III"],["d","Todas"]],"ans":"c","exp":"Tema: aplicação territorial da LGPD. A lei se aplica ao tratamento de dados feito no Brasil, quando o objetivo é oferecer bens ou serviços no Brasil, ou quando os dados foram coletados no Brasil, isto é, quando o titular estava no país no momento da coleta. Os itens I e III estão corretos.\n\nO item II está errado: a aplicação não depende de acordos com o Banco Central. Essa exigência é específica da contratação de nuvem no exterior, prevista na Resolução CMN 4893, e não é um critério de aplicação da LGPD. A alternativa C (I e III) é a correta.","id":"10398"},{"n":796,"banco":"lucas","mod":8,"tit":"VIII","titn":"Compliance","cap":"9","capn":"Questão 9 (cód. 10397)","stem":"Na linguagem da LGPD, o titular de dados pessoais e o agente de tratamento de dados pessoais são, respectivamente:","opts":[["a","Participante e Investidor"],["b","Investidor e Participante"],["c","Agente de custódia e Participante"],["d","Investidor e Administrador de carteiras de valores mobiliários"]],"ans":"b","exp":"Tema: vocabulário da LGPD aplicado ao mercado financeiro. O titular de dados pessoais é a pessoa a quem os dados se referem, que no mercado de capitais é o investidor. O agente de tratamento é quem trata os dados, como bancos, corretoras e gestores, ou seja, o participante. A alternativa B (investidor e participante) é a correta.\n\nAtenção: a alternativa A inverte os termos, e a D usa o administrador de carteiras como agente de tratamento e o investidor como titular, mas a ordem da pergunta exige a sequência titular e depois agente, e isso só é verdadeiro na B.","id":"10397"},{"n":797,"banco":"lucas","mod":8,"tit":"VIII","titn":"Compliance","cap":"10","capn":"Questão 10 (cód. 10396)","stem":"O que significa a letra “P” na sigla LGPD?","opts":[["a","Protagonismo"],["b","Prevenção"],["c","Proteção"],["d","Pessoais"]],"ans":"c","exp":"Tema: sigla LGPD. A sigla vem de Lei Geral de Proteção de Dados Pessoais. A letra P corresponde a \"Proteção\", que é a palavra central do nome da lei, e não a \"Pessoais\" (que seria a letra final da sigla completa). A lei protege a liberdade, a privacidade e o livre desenvolvimento da personalidade dos titulares. A alternativa C (proteção) é a correta.\n\nA alternativa B (prevenção) é o P de PLD, e não da LGPD. A alternativa A (protagonismo) não faz parte do nome da lei. A alternativa D (pessoais) é o P da palavra \"Pessoais\", mas a pergunta trata da letra P da sigla, cuja primeira palavra é Proteção.","id":"10396"},{"n":798,"banco":"lucas","mod":8,"tit":"VIII","titn":"Compliance","cap":"11","capn":"Questão 11 (cód. 10395)","stem":"Quando um PEP ou uma ONG quiser ser cliente de alguma instituição financeira, deve-se:","opts":[["a","Aceitar estes clientes como qualquer outro cliente PF ou PJ, para que não se caracterize discriminação"],["b","Recusar imediatamente, visto que ambos são clientes que trazem um risco muito alto"],["c","Aceitar ambos, mas comunicar toda e qualquer operação destes clientes ao COAF"],["d","Aceitar ambos, porém devem ter tratamento diferenciado"]],"ans":"d","exp":"Tema: tratamento de PEP e ONG como clientes. A apostila estabelece que PEP e ONG devem ser tratadas de maneira distinta dos demais clientes PF e PJ, e o participante deve definir na política de PLD/FTP as particularidades desse tratamento. Não se trata de recusar, nem de tratar como qualquer cliente. A alternativa D é a correta.\n\nA alternativa A (tratar como qualquer cliente) contraria a exigência de tratamento diferenciado. A B (recusar) não é a regra. A C (aceitar e comunicar toda operação ao COAF) exagera a comunicação, que só se faz quando há suspeita.","id":"10395"},{"n":799,"banco":"lucas","mod":8,"tit":"VIII","titn":"Compliance","cap":"12","capn":"Questão 12 (cód. 10383)","stem":"Se o cliente, por vontade própria, demandar a execução de um investimento inadequado que irá desenquadrar a carteira dele, o participante deve:","opts":[["a","Não executar a operação"],["b","Não executar a operação, alertar o cliente e informar a CVM"],["c","Executar a operação, mas alertar o cliente, antes da primeira aplicação na categoria de valores mobiliários, indicando a causa da divergência e obter a declaração expressa de que o cliente está ciente da inadequação"],["d","Executar a operação normalmente, pois como não foi uma oferta ativa o participante não possui qualquer risco ou responsabilidade"]],"ans":"c","exp":"Tema: suitability e investimento inadequado pedido pelo cliente. Se o cliente, por vontade própria, quiser seguir com um investimento inadequado, o participante não precisa recusar a operação, mas deve alertar o cliente antes da primeira aplicação naquela categoria de valor mobiliário, indicando as causas da divergência. Além disso, precisa obter declaração expressa de que o cliente está ciente da inadequação. A alternativa C é a correta.\n\nA alternativa A (não executar) não é a regra geral. A B (não executar, alertar e informar a CVM) acrescenta uma comunicação que não é exigida. A D (executar sem responsabilidade) está errada, porque o participante tem dever de alertar e registrar a ciência do cliente.","id":"10383"},{"n":800,"banco":"lucas","mod":8,"tit":"VIII","titn":"Compliance","cap":"13","capn":"Questão 13 (cód. 10393)","stem":"São consideradas PEP:","opts":[["a","Apenas políticos municipais, como vereadores, bem como seus familiares até segundo grau e estreito colaboradores."],["b","Pessoas que foram mencionadas em escândalos envolvendo política, nos últimos cinco anos."],["c","Aquele que desempenha ou tenha desempenhado, nos últimos cinco anos, no Brasil ou em países, territórios e dependências estrangeiras, cargos, empregos ou funções públicas relevantes, assim como seus representantes, familiares, até segundo grau e estreitos colaboradores"],["d","Apenas o Presidente da Republica, seus familiares e estreitos colaboradores"]],"ans":"c","exp":"Tema: definição de PEP. Pessoa exposta politicamente é quem desempenha ou tenha desempenhado, nos últimos cinco anos, no Brasil ou no exterior, cargos e funções públicas relevantes, incluindo seus representantes, familiares até segundo grau e estreitos colaboradores. A alternativa C reproduz essa definição, e é a correta.\n\nA alternativa A limita a PEP a políticos municipais, o que é restrito demais. A B fala de pessoas mencionadas em escândalos, o que não é o critério. A D limita a presidente da República, o que também é restrito demais, porque a definição abrange muitos cargos.","id":"10393"},{"n":801,"banco":"lucas","mod":8,"tit":"VIII","titn":"Compliance","cap":"14","capn":"Questão 14 (cód. 10392)","stem":"O diretor responsável pela política de PLD, pode:","opts":[["a","Ser diretor de qualquer outra função dentro do mesmo conglomerado, desde que tenha sua nomeação informada no prazo de 7 dias"],["b","Pode ter outras atividades, desde que não implique em conflito de interesses, principalmente com áreas de negócio e deve ter sua nomeação informada no prazo de 7 dias"],["c","Pode ter outras atividades, desde que não implique em conflito de interesses, principalmente com áreas de negócio e deve ter sua nomeação informada no prazo até 31 de março do ano subsequente"],["d","Pode ser diretor apenas de áreas de negócio, desde que tenha sua nomeação informada no prazo de 7 dias"]],"ans":"b","exp":"Tema: diretor responsável pela política de PLD/FTP. Ele pode ter outras atividades no participante ou no conglomerado, desde que não haja conflito de interesses, especialmente com as áreas de negócio. A nomeação ou substituição deve ser informada à CVM no prazo de 7 dias úteis. A alternativa B é a correta.\n\nA alternativa A aceita o prazo de 7 dias, mas não menciona a restrição de conflito de interesses. A alternativa C traz o prazo de 31 de março, que é o do relatório de efetividade ao BACEN, e não o da nomeação do diretor. A alternativa D restringe o diretor às áreas de negócio, o que contraria a lógica de segregação.","id":"10392"},{"n":802,"banco":"lucas","mod":8,"tit":"VIII","titn":"Compliance","cap":"15","capn":"Questão 15 (cód. 10391)","stem":"O que significa “FT” na sigla PLD/FTP?","opts":[["a","Financiamento de Terrenos"],["b","Financiamento ao Terrorismo"],["c","Financiamento de Proliferação de armas em destruição em massa"],["d","Financiamento à Tanques de Guerra para destruição em massa"]],"ans":"b","exp":"Tema: sigla PLD/FTP. FTP significa Financiamento do Terrorismo e da Proliferação de armas de destruição em massa. A apostila explica que a sigla foi incorporada em 2021, alinhada à diretriz do GAFI. A alternativa B (financiamento ao terrorismo) é a correta, no sentido da sigla de PLD/FT.\n\nA alternativa A (financiamento de terrenos) e a D (financiamento de tanques de guerra) são invenções sem relação com a sigla. A alternativa C (proliferação de armas) é a parte final da sigla, mas a letra F está ligada ao terrorismo.","id":"10391"},{"n":803,"banco":"lucas","mod":8,"tit":"VIII","titn":"Compliance","cap":"16","capn":"Questão 16 (cód. 10390)","stem":"O que é ABR?","opts":[["a","Abordagem Baseada em Risco"],["b","Atividade Baseada em Reatividade do Cliente"],["c","Ação ao Cliente e Investidor Brasileiro"],["d","Abordagem Baseada em Realidade"]],"ans":"a","exp":"Tema: Abordagem Baseada em Risco (ABR). A sigla significa exatamente isso: concentrar esforços em produtos, situações e clientes de maior risco, com identificação, monitoramento, análise, reporte e mitigação dos riscos de LDFT. A alternativa A é a correta.\n\nAs demais alternativas inventam expansões que não existem na norma. A pista é que a abordagem se apoia no risco, e não na reatividade ou na realidade.","id":"10390"},{"n":804,"banco":"lucas","mod":8,"tit":"VIII","titn":"Compliance","cap":"17","capn":"Questão 17 (cód. 10389)","stem":"A periodicidade para atualização cadastral dos clientes ativos, segundo a política de PLD/FTP é de, no máximo:","opts":[["a","2 anos"],["b","3 anos"],["c","5 anos"],["d","10 anos"]],"ans":"c","exp":"Tema: periodicidade de atualização cadastral dos clientes ativos pela política de PLD/FTP. O limite máximo previsto é de cinco anos. A alternativa C é a correta.\n\nAs alternativas A (2 anos) e B (3 anos) são prazos mais curtos que o limite, e a D (10 anos) excede o limite. A apostila indica que o participante deve definir critérios de atualização com limite máximo de cinco anos.","id":"10389"},{"n":805,"banco":"lucas","mod":8,"tit":"VIII","titn":"Compliance","cap":"18","capn":"Questão 18 (cód. 10388)","stem":"Pode ser considerada sério indício de crime de lavagem de dinheiro, e por tanto, devem receber especial atenção no monitoramento de operações: I. Operações que sejam inadequadas ao perfil de investidor do cliente II. Operações realizadas fora do preço de mercado III. Situações em que não seja possível identificar o beneficiário final É correto o que se afirma em:","opts":[["a","I e II"],["b","III, apenas"],["c","II e III"],["d","Todas"]],"ans":"c","exp":"Tema: sinais de alerta de lavagem de dinheiro. O item I (operações inadequadas ao perfil do cliente) é um sinal de alerta, porque sai do comportamento esperado para aquele investidor. O item II (operações fora do preço de mercado) também é um sinal clássico de alerta. O item III (não ser possível identificar o beneficiário final) é diretamente relevante, porque impede saber quem se beneficia da operação. Pela teoria de sinais de alerta, os três itens merecem atenção especial, e a alternativa D seria a mais coerente. O gabarito indica C (II e III), que deixa de fora o item I, o que é uma divergência a conferir com o texto da regulamentação.","id":"10388"},{"n":806,"banco":"lucas","mod":8,"tit":"VIII","titn":"Compliance","cap":"19","capn":"Questão 19 (cód. 10387)","stem":"Sobre os procedimentos em caso de indícios de lavagem de dinheiro e financiamento ao terrorismo. I. Os Participantes devem, mediante análise fundamentada, comunicar a CVM todas as situações e operações detectadas, ou propostas de operações que possam constituir-se em sérios indícios de lavagem de dinheiro e financiamento ao terrorismo. II. Comunicar ao COAF no prazo de 24 (vinte e quatro) horas a contar da conclusão da análise que caracterizou a atipicidade da operação, respectiva proposta, ou mesmo da situação atípica detectada. III. Existe um conteúdo mínimo da comunicação, estipulado pela Resolução CVM nº 50/21 e não deve ser dada ciência de tal ato a qualquer pessoa, inclusive àquela a qual se refira a informação. É correto o que se afirma em:","opts":[["a","I, apenas"],["b","II e III"],["c","I e III"],["d","Todas"]],"ans":"b","exp":"Tema: comunicação de indícios de lavagem de dinheiro. Analisando:\n\nI. Errado. A comunicação deve ser feita ao COAF, e não à CVM.\n\nII. Correto. A comunicação ao COAF deve ser feita em até 24 horas após a conclusão da análise que caracterizou a atipicidade.\n\nIII. Correto. Existe conteúdo mínimo para a comunicação, e ela não pode ser divulgada a ninguém, inclusive ao próprio cliente reportado.\n\nA alternativa B (II e III) é a correta. O item I é a armadilha: o destinatário é o COAF.","id":"10387"},{"n":807,"banco":"lucas","mod":8,"tit":"VIII","titn":"Compliance","cap":"20","capn":"Questão 20 (cód. 10386)","stem":"É correto o que se afirma em: I. Os Participantes devem cumprir, imediatamente e sem aviso prévio aos sancionados, as medidas estabelecidas nas resoluções sancionatórias do Conselho de Segurança das nações Unidas ou as designações de seus comitês de sanções que determinem a indisponibilidade de ativos, de quaisquer valores, de titularidade, direta ou indireta, de pessoas naturais, de pessoas jurídicas ou de entidades, nos termos da Lei nº 13.810, de 2019, sem prejuízo do dever de cumprir determinações judiciais de indisponibilidade também previstas na referida lei. II. A indisponibilidade refere-se à proibição de transferir, converter, trasladar, disponibilizar ativos ou deles dispor, direta ou indiretamente, incidindo inclusive sobre os juros e outros frutos civis e rendimentos decorrentes. III. No caso de não cumprimento imediato da ordem de indisponibilidade, os Participantes devem informar, sem demora, ao Ministério da Justiça e à CVM, a existência de pessoas e ativos sujeitos às determinações de indisponibilidade a que deixaram de dar o imediato cumprimento, justificando as razões para tanto.","opts":[["a","I e II"],["b","II e III"],["c","I e III"],["d","Todas"]],"ans":"d","exp":"Tema: indisponibilidade de ativos por sanções do Conselho de Segurança da ONU e por determinações judiciais, com base na Lei 13.810/2019. Analisando:\n\nI. Correto. Os participantes devem cumprir, imediatamente e sem aviso prévio aos sancionados, as medidas de indisponibilidade.\n\nII. Correto. Indisponibilidade significa proibir transferir, converter, trasladar, disponibilizar ou dispor dos ativos, incluindo juros e frutos civis.\n\nIII. Correto. Se não houver cumprimento imediato, o participante deve informar sem demora ao Ministério da Justiça e à CVM, justificando as razões.\n\nA alternativa D (todas) é a correta.","id":"10386"},{"n":808,"banco":"lucas","mod":8,"tit":"VIII","titn":"Compliance","cap":"21","capn":"Questão 21 (cód. 10385)","stem":"Considera-se cliente ativo aquele que:","opts":[["a","nos últimos 18 (dezoito) meses tenha: efetuado movimentação de sua conta corrente ou posição de custódia, realizado operação de day trade"],["b","nos últimos 18 (dezoito) meses tenha: efetuado movimentação de sua conta corrente ou posição de custódia, realizado operação no mercado de valores mobiliário; ou apresentado saldo e sua posição de custódia"],["c","nos últimos 12 (doze) meses tenha: efetuado movimentação na conta corrente e cartão de crédito"],["d","nos últimos 12 (doze) meses tenha: efetuado movimentação de sua conta corrente ou posição de custódia, realizado operação no mercado de valores mobiliário; ou apresentado saldo em sua posição de custódia"]],"ans":"d","exp":"Tema: definição de cliente ativo para fins de PLD/FTP. Um cliente é considerado ativo quando, nos últimos doze meses, tenha feito movimentação na conta corrente ou na posição de custódia, realizado operação no mercado de valores mobiliários, ou apresentado saldo na posição de custódia. A alternativa D reproduz essa definição com o prazo de doze meses, e é a correta.\n\nAs alternativas A e B usam o prazo de 18 meses, que não é o critério. A alternativa C menciona cartão de crédito, que não entra na definição de cliente ativo do mercado de valores mobiliários.","id":"10385"},{"n":809,"banco":"lucas","mod":8,"tit":"VIII","titn":"Compliance","cap":"22","capn":"Questão 22 (cód. 10384)","stem":"Avalie as afirmativas: I. O Bacen, na Circular 3.978/19, determina que seja elaborado e encaminhado relatório de efetividade da política, controles e procedimentos de prevenção à lavagem de dinheiro II. Um documento contendo os planos de ação destinados a solucionar as deficiências identificadas no relatório de efetividade deve ser elaborado e, enviado como anexo ao relatório de efetividade.","opts":[["a","Ambas as afirmativas são verdadeiras"],["b","A afirmativa I é verdadeira, enquanto a II é falsa"],["c","A afirmativa I é falsa, enquanto a II é verdadeira"],["d","Ambas as afirmativas são falsas"]],"ans":"b","exp":"Tema: relatório de efetividade e plano de ação de PLD/FTP. O item I está correto: a Circular BACEN 3.978 exige o relatório de efetividade da política, dos controles e dos procedimentos de PLD. O item II está errado: o plano de ação para corrigir as deficiências não é anexo ao relatório. Ele tem prazo próprio, até 30 de junho, e é uma entrega separada, enquanto o relatório vence em 31 de março do ano subsequente. A alternativa B é a correta.","id":"10384"},{"n":810,"banco":"lucas","mod":8,"tit":"VIII","titn":"Compliance","cap":"23","capn":"Questão 23 (cód. 10351)","stem":"A documentação relativa a PRSAC:","opts":[["a","Deve ser arquivada por 10 anos"],["b","Deve ser mantida a disposição do Banco Central por, no mínimo, 5 anos"],["c","Deve ser mantida a disposição do Ministério do Meio Ambiente por 5 anos"],["d","Deve ser mantida à disposição do Banco Central por, no mínimo, 10 anos"]],"ans":"b","exp":"Tema: arquivamento da documentação da PRSAC. Toda a documentação relativa ao estabelecimento e às ações da PRSAC deve ser mantida arquivada e à disposição do BACEN por, no mínimo, cinco anos. A alternativa B é a correta.\n\nAs alternativas A e D trazem o prazo de dez anos, que não é o da regra. A alternativa C atribui a guarda ao Ministério do Meio Ambiente, que não é o órgão supervisor da PRSAC.","id":"10351"},{"n":811,"banco":"lucas","mod":8,"tit":"VIII","titn":"Compliance","cap":"24","capn":"Questão 24 (cód. 10352)","stem":"A PRSAC é:","opts":[["a","Uma Política de Responsabilidade específica sobre o meio ambiente"],["b","Uma Política de Responsabilidade Social, Ambiental e Climática"],["c","Uma Política de Responsabilidade da Alta Gestão com todos os colaboradores da organização"],["d","Uma Política de Responsabilidade Sustentável, Alta Administração e COSO"]],"ans":"b","exp":"Tema: o que é a PRSAC. Ela é a Política de Responsabilidade Social, Ambiental e Climática, instituída pela Resolução CMN 4.945/21, que substituiu a antiga política de sustentabilidade. A alternativa B é a correta.\n\nA alternativa A reduz a política ao meio ambiente, deixando de fora o social e o climático. As alternativas C e D misturam conceitos que não fazem parte da sigla.","id":"10352"},{"n":812,"banco":"lucas","mod":8,"tit":"VIII","titn":"Compliance","cap":"25","capn":"Questão 25 (cód. 10353)","stem":"Com relação a conglomerados prudenciais, a PRSAC:","opts":[["a","Deve ser segregada, cada instituição possui a sua"],["b","Deve ser única, ou seja, uma PRSAC para todo conglomerado"],["c","Pode ser única para conglomerado e tratar apenas o que for comum a todas as empresas do grupo"],["d","Pode ser unificada, mas deve considerar aspectos de cada instituição"]],"ans":"d","exp":"Tema: PRSAC em conglomerados. Quando a instituição integra um conglomerado, a PRSAC pode ser unificada, mas deve considerar e descrever as particularidades de cada negócio. A alternativa D é a correta.\n\nA alternativa A exige segregação total, o que não é a regra. A alternativa B exige uma política única sem nenhuma particularidade, o que também não é a regra. A alternativa C limita o conteúdo ao que é comum, deixando de lado as particularidades que a norma exige que sejam descritas.","id":"10353"},{"n":813,"banco":"lucas","mod":8,"tit":"VIII","titn":"Compliance","cap":"26","capn":"Questão 26 (cód. 10354)","stem":"Quem demanda a elaboração da PR- SAC?","opts":[["a","BACEN"],["b","CVM"],["c","BSM"],["d","Ministério do Meio Ambiente"]],"ans":"a","exp":"Tema: quem demanda a PRSAC. A política é regulada pelo BACEN, pela Resolução CMN 4.945/21, e por isso é o BACEN que demanda sua elaboração. A alternativa A é a correta.\n\nA CVM (B) regula outros temas, como a Resolução 59/21 sobre ESG para ofertas de valores mobiliários. A BSM (C) é a entidade de autorregulação e não regula a PRSAC. O Ministério do Meio Ambiente (D) não tem essa atribuição.","id":"10354"},{"n":814,"banco":"lucas","mod":8,"tit":"VIII","titn":"Compliance","cap":"27","capn":"Questão 27 (cód. 10355)","stem":"O que significa a letra “A” na sigla PR- SAC?","opts":[["a","Alta Administração"],["b","Ambiente"],["c","Atmosfera"],["d","Ambiental"]],"ans":"d","exp":"Tema: sigla PRSAC. A letra A significa Ambiental, e a sigla completa é Política de Responsabilidade Social, Ambiental e Climática. A alternativa D é a correta. A letra A não se refere à Alta Administração (A), ao ambiente (B) ou à atmosfera (C): a sigla usa o adjetivo ambiental.","id":"10355"},{"n":815,"banco":"lucas","mod":8,"tit":"VIII","titn":"Compliance","cap":"28","capn":"Questão 28 (cód. 10356)","stem":"A PRSAC deve:","opts":[["a","Ser mantida em sigilo"],["b","Ser divulgada no site do Participante"],["c","Ser mantida em sigilo e apenas disponível ao Banco Central"],["d","Divulgada apenas aos colaboradores e ao diretor responsável"]],"ans":"b","exp":"Tema: divulgação da PRSAC. Ela deve ser uma política pública para todo o mercado, divulgada no site do participante. A alternativa B é a correta.\n\nAs alternativas A e C mantêm a política em sigilo, o que contraria a exigência de publicidade. A alternativa D restringe a divulgação aos colaboradores, o que também não é a regra.","id":"10356"},{"n":816,"banco":"lucas","mod":8,"tit":"VIII","titn":"Compliance","cap":"29","capn":"Questão 29 (cód. 10357)","stem":"Quais tipos de Instituições autorizadas a funcionar pelo Bacen devem estabelecer e implementar a PRSAC:","opts":[["a","Instituições enquadradas no S1 e S2, apenas"],["b","Instituições enquadradas no S1, S3 e S5, apenas"],["c","Todas as Instituições abarcadas pela resolução (S1 a S5)"],["d","Instituições enquadradas no S1 e S5, apenas"]],"ans":"c","exp":"Tema: quem deve implementar a PRSAC. A norma se aplica a todas as instituições financeiras e demais instituições autorizadas a funcionar pelo BACEN que se enquadrem nos segmentos S1 a S5. A alternativa C é a correta, pois abrange todos os segmentos. A segmentação considera o porte e a atividade internacional, pela Resolução CMN 4.553/17.\n\nAs demais alternativas excluem segmentos que a norma inclui.","id":"10357"},{"n":817,"banco":"lucas","mod":8,"tit":"VIII","titn":"Compliance","cap":"30","capn":"Questão 30 (cód. 10358)","stem":"Quem demanda a elaboração da Política de Segurança Cibernética e Política de Segurança da Informação, respectivamente?","opts":[["a","BACEN e CVM"],["b","CVM e BACEN"],["c","BSM e BACEN"],["d","CVM e BACEN"]],"ans":"a","exp":"Tema: quem demanda as políticas de segurança cibernética e de segurança da informação. A Política de Segurança Cibernética é regulada pelo BACEN, pela Resolução CMN 4.893/21. A Política de Segurança da Informação é regulada pela CVM, pela Resolução CVM 35/21. A alternativa A (BACEN e CVM) é a correta, nessa ordem.\n\nAs demais alternativas invertem a ordem ou usam a BSM, que não é a origem das normas.","id":"10358"},{"n":818,"banco":"lucas","mod":8,"tit":"VIII","titn":"Compliance","cap":"31","capn":"Questão 31 (cód. 10359)","stem":"O Participante que contrata serviços de computação em nuvem é responsável pela confiabilidade, pela integridade, pela disponibilidade, pela segurança e pelo sigilo em relação aos serviços contratados, bem como pelo cumprimento da legislação e da regulamentação em vigor e esta contratação deve ser comunicada, em até 10 dias:","opts":[["a","À CVM"],["b","À BSM Supervisão"],["c","Ao COAF"],["d","Ao Banco Central"]],"ans":"d","exp":"Tema: comunicação da contratação de nuvem. O participante que contrata serviços de computação em nuvem continua responsável pela confiabilidade, integridade, disponibilidade, segurança e sigilo dos dados, e deve comunicar a contratação ao Banco Central. A alternativa D é a correta.\n\nA CVM (A) não é o destinatário da comunicação de nuvem. A BSM (B) faz supervisão do mercado, e não recebe essa comunicação. O COAF (C) recebe comunicações de PLD, e não de nuvem.","id":"10359"},{"n":819,"banco":"lucas","mod":8,"tit":"VIII","titn":"Compliance","cap":"32","capn":"Questão 32 (cód. 10360)","stem":"Entre outros itens, o conteúdo mínimo da política de segurança cibernética deve contemplar: I. as medidas, os procedimentos e os controles adotados para reduzir a vulnerabilidade do Participante a incidentes e ataques cibernéticos. II. os controles específicos, incluindo os voltados para a inibição da rastreabilidade da informação, que busquem garantir a segurança das informações sensíveis. III. o registro, a análise da causa e do impacto, bem como o controle dos efeitos de incidentes relevantes para as atividades do Participante, abrangendo, também, informações recebidas de terceiros e prestadores de serviços. É correto o que se afirma em:","opts":[["a","I e III"],["b","II e III"],["c","I e II"],["d","Todos os itens"]],"ans":"a","exp":"Tema: conteúdo mínimo da política de segurança cibernética. Analisando:\n\nI. Correto. A política deve prever medidas, procedimentos e controles para reduzir a vulnerabilidade a incidentes e ataques.\n\nII. Errado. Os controles devem garantir a segurança das informações sensíveis, e não inibir a rastreabilidade. A norma exige justamente rastreabilidade, e não o contrário.\n\nIII. Correto. Deve haver registro, análise de causa e impacto e controle dos efeitos de incidentes relevantes, incluindo informações de terceiros.\n\nA alternativa A (I e III) é a correta.","id":"10360"},{"n":820,"banco":"lucas","mod":8,"tit":"VIII","titn":"Compliance","cap":"33","capn":"Questão 33 (cód. 10361)","stem":"Com relação à contratação de serviços de armazenamento em nuvem:","opts":[["a","O prestador pode ser livremente escolhido"],["b","O prestador deve ser homologado pelo BA- CEN"],["c","O prestador deve estar em lista divulgada anualmente pela BSM"],["d","O prestador deve estar em pais cuja autoridade de supervisão tenha convenio para troca de informações com o BACEN"]],"ans":"d","exp":"Tema: contratação de nuvem no exterior. A regra da Resolução CMN 4.893/21 é que o serviço prestado no exterior só pode ser contratado se as autoridades supervisoras do país do prestador tiverem convênio de troca de informações com o BACEN. A alternativa D é a correta.\n\nA alternativa A (escolha livre) desconsidera a exigência. A alternativa B (homologação pelo BACEN) e a C (lista anual da BSM) não são exigências da norma.","id":"10361"},{"n":821,"banco":"lucas","mod":8,"tit":"VIII","titn":"Compliance","cap":"34","capn":"Questão 34 (cód. 10362)","stem":"A Política do Plano de Ação e de resposta a incidentes e a Política de Segurança cibernética devem:","opts":[["a","Ser aprovados pelo conselho de administração ou, na sua inexistência, pela diretoria da instituição; e ser documentados e revisados, no mínimo, anualmente"],["b","Ser aprovados pela auditoria interna da empresa ou, na sua inexistência, pela diretoria da instituição; e ser documentados e revisados, no mínimo, anualmente"],["c","Ser aprovados pela área de Compliance, na sua inexistência, pela diretoria da instituição; e ser documentados e revisados, no mínimo, a cada 5 anos"],["d","Ser aprovados pelo BACEN e pela diretoria da instituição; e ser documentados e revisados, no mínimo, anualmente"]],"ans":"a","exp":"Tema: aprovação e revisão das políticas de incidentes e de segurança cibernética. Elas devem ser aprovadas pelo conselho de administração ou, na sua inexistência, pela diretoria, e revisadas, no mínimo, anualmente. A alternativa A é a correta.\n\nA alternativa B atribui a aprovação à auditoria interna, o que não é o caso. A alternativa C fala em revisão a cada cinco anos, quando a norma exige anual. A alternativa D atribui a aprovação ao BACEN, que não aprova políticas internas.","id":"10362"},{"n":822,"banco":"lucas","mod":8,"tit":"VIII","titn":"Compliance","cap":"35","capn":"Questão 35 (cód. 10363)","stem":"A política de segurança cibernética deve ser divulgada:","opts":[["a","Mediante linguagem clara, acessível e em nível de detalhamento compatível com as funções desempenhadas"],["b","Mediante linguagem robusta, e em nível de detalhamento compatível com as funções desempenhadas"],["c","Apenas aos funcionários da Instituição"],["d","Apenas ao público, para que possam ter conhecimento do documento na íntegra"]],"ans":"a","exp":"Tema: divulgação da política de segurança cibernética. Ela deve ser divulgada em linguagem clara e acessível, com nível de detalhamento compatível com as funções desempenhadas. A alternativa A é a correta.\n\nA alternativa B usa \"robusta\", que não é o critério de linguagem. A alternativa C restringe a divulgação aos funcionários, e a D limita ao público de forma incompatível com o detalhamento, porque o documento completo não é público.","id":"10363"},{"n":823,"banco":"lucas","mod":8,"tit":"VIII","titn":"Compliance","cap":"36","capn":"Questão 36 (cód. 10364)","stem":"No tocante a Política de Segurança da Informação, devem ser treinados:","opts":[["a","Apenas funcionários"],["b","Diretor responsável e demais funcionários da Instituição"],["c","Equipe de Tecnologia"],["d","Funcionários, prepostos e prestadores de serviços"]],"ans":"d","exp":"Tema: treinamento na política de segurança da informação. Devem ser treinados funcionários, prepostos e prestadores de serviços, porque a política é aplicável a todos eles. A alternativa D é a correta.\n\nAs alternativas A (apenas funcionários) e B (diretor e funcionários) deixam de fora os prepostos e prestadores de serviços. A alternativa C (equipe de tecnologia) restringe o treinamento a uma área, o que não corresponde à norma.","id":"10364"},{"n":824,"banco":"lucas","mod":8,"tit":"VIII","titn":"Compliance","cap":"37","capn":"Questão 37 (cód. 10365)","stem":"O incidente que afete processos críticos de negócios, ou dados ou informações sensíveis e tenha impacto significativo sobre os clientes deve ser considerado como:","opts":[["a","Irrelevante"],["b","Relevante"],["c","Irrelevante, não deixando de registrar a ocorrência para posterior análise de causa e impacto"],["d","Relevante, porém não é necessário registrar a ocorrência para posterior analise de causa e impacto"]],"ans":"b","exp":"Tema: classificação de incidentes. Um incidente que afeta processos críticos de negócio, ou dados ou informações sensíveis, e tem impacto significativo sobre os clientes, é considerado relevante. Ele precisa ser registrado para análise de causa e impacto. A alternativa B é a correta.\n\nAs alternativas A e C classificam o incidente como irrelevante, o que contraria o enunciado. A alternativa D diz que não é necessário registrar um incidente relevante, o que é o oposto da regra.","id":"10365"},{"n":825,"banco":"lucas","mod":8,"tit":"VIII","titn":"Compliance","cap":"38","capn":"Questão 38 (cód. 10366)","stem":"Para analisar casos em que se perceba indícios da prática de churning, são adotados os seguintes indicadores: I. Turnover Ratio, para verificar se o total de despesas incorridas pelo investidor foi demasiado. II. Cost-Equity Ratio, para averiguar se o volume de negócios foi excessivo.","opts":[["a","Ambos os conceitos são falsos"],["b","O conceito I é verdadeiro, enquanto o II é falso"],["c","O conceito I é falso, enquanto o II é verdadeiro"],["d","Ambos os conceitos são verdadeiros"]],"ans":"a","exp":"Tema: indicadores de churning. Os indicadores usados são o Turnover Ratio, que mede o volume de negócios em relação ao patrimônio, e o Cost-Equity Ratio, que mede o total de despesas em relação ao patrimônio. Analisando:\n\nI. Errado. O Turnover Ratio verifica o volume de negócios, e não as despesas.\n\nII. Errado. O Cost-Equity Ratio verifica as despesas, e não o volume de negócios.\n\nOs dois itens inverteram a função de cada indicador. Por isso a alternativa A (ambos falsos) é a correta.","id":"10366"},{"n":826,"banco":"lucas","mod":8,"tit":"VIII","titn":"Compliance","cap":"39","capn":"Questão 39 (cód. 10367)","stem":"São elementos do ciclo de spoofing: I. Oferta 6 vezes maior que o tamanho médio praticado pelo mercado nos 3 pregões que antecedem o negócio realizado resultante do ciclo de spoofing. II. Oferta de tamanho pelo menos 1,8x maior que a soma de todas as outras ofertas constantes no mesmo lado do livro do ativo, até o terceiro nível de preço. III. Oferta que tenha permanecido menos de 10 segundos no livro do ativo. IV. A presença de um dos elementos I, II e III, ou a combinação deles no período de análise configura irregularidade. É correto o que se afirma em:","opts":[["a","II, III e IV"],["b","I, II e III"],["c","I, III e IV"],["d","Todas"]],"ans":"b","exp":"Tema: elementos do ciclo de spoofing. Os itens I, II e III descrevem os filtros de tamanho e de permanência da oferta. Mas, pela teoria, os elementos isolados não configuram irregularidade. É preciso que todos os elementos estejam presentes e que haja recorrência de no mínimo oito eventos no período de análise de 15 dias. O item IV diz que a presença de um elemento isolado, ou sua combinação, configura irregularidade, o que está errado. A alternativa B (I, II e III) é a correta.","id":"10367"},{"n":827,"banco":"lucas","mod":8,"tit":"VIII","titn":"Compliance","cap":"40","capn":"Questão 40 (cód. 10368)","stem":"Prática abusiva de criação artificial de liquidez com o uso de oferta de tamanho fora do padrão do livro de ofertas com o objetivo de influenciar investidores a superar a oferta artificial e gerar negócios do lado oposto do livro:","opts":[["a","Churning"],["b","Spoofing"],["c","Layering"],["d","OMC (Operação de mesmo comitente)"]],"ans":"b","exp":"Tema: spoofing. É a prática de criar liquidez artificial com uma oferta fora do padrão do livro, que não se pretende executar, para pressionar investidores a superá-la e gerar negócios do lado oposto. Depois de atingido o objetivo, a oferta é cancelada. A alternativa B é a correta.\n\nO layering (C) usa várias camadas de ofertas em níveis sucessivos de preço, e não uma única oferta grande. O churning (A) é giro excessivo da carteira, e a OMC (D) é a operação de mesmo comitente.","id":"10368"},{"n":828,"banco":"lucas","mod":8,"tit":"VIII","titn":"Compliance","cap":"41","capn":"Questão 41 (cód. 10369)","stem":"Prática que utiliza ardil ou artifício destinado a induzir ou manter terceiro em erro, com a finalidade de se obter vantagem ilícita de natureza patrimonial para as partes na operação, para o participante ou para terceiros.","opts":[["a","Manipulação de preços"],["b","Prática não equitativa"],["c","Operação Fraudulenta"],["d","Condições artificiais de demanda, oferta ou preço de valores mobiliários"]],"ans":"c","exp":"Tema: operação fraudulenta. É a prática que usa ardil ou artifício para induzir terceiro em erro, com o objetivo de obter vantagem ilícita de natureza patrimonial. A alternativa C é a correta.\n\nA manipulação de preços (A) é o uso de artifícios para elevar, manter ou baixar cotações, e a prática não equitativa (B) é uma conduta que coloca uma parte em desvantagem. A alternativa D é a condição artificial de demanda, oferta ou preço. A pista é o ardil que induz terceiro em erro, característica da fraude.","id":"10369"},{"n":829,"banco":"lucas","mod":8,"tit":"VIII","titn":"Compliance","cap":"42","capn":"Questão 42 (cód. 10370)","stem":"Prática que consiste na utilização de qualquer processo ou artifício destinado, direta ou indiretamente, a elevar, manter ou baixar a cotação de um valor mobiliário, induzindo, terceiros à sua compra e venda.","opts":[["a","Operação fraudulenta"],["b","Manipulação de preços"],["c","Prática não equitativa"],["d","Condições artificiais de demanda, oferta ou preço de valores mobiliários"]],"ans":"b","exp":"Tema: manipulação de preços. É a utilização de processo ou artifício para elevar, manter ou baixar a cotação de um valor mobiliário, induzindo terceiros a comprar ou vender. A alternativa B é a correta.\n\nA operação fraudulenta (A) é o uso de ardil para induzir terceiro em erro. A prática não equitativa (C) é a conduta que coloca uma das partes em desvantagem. As condições artificiais (D) são a criação de demanda, oferta ou preço artificiais, e não a alteração da cotação por processo.","id":"10370"},{"n":830,"banco":"lucas","mod":8,"tit":"VIII","titn":"Compliance","cap":"43","capn":"Questão 43 (cód. 10371)","stem":"Prática abusiva de criação de liquidez artificial no livro de ofertas formando de camadas de ofertas em níveis sucessivos de preço com o objetivo de influenciar investidores a superar a barreira criada pela camada e gerar negócios do lado oposto do livro.","opts":[["a","Layering"],["b","Spoofing"],["c","Churning"],["d","OMC (Operações de Mesmo Comitente)"]],"ans":"a","exp":"Tema: layering. É a prática abusiva de criar liquidez artificial no livro, com camadas sucessivas de ofertas em níveis diferentes de preço, para superar a barreira criada pelas camadas e gerar negócios do lado oposto. A alternativa A é a correta.\n\nO spoofing (B) usa uma única oferta grande, e não camadas. O churning (C) é giro excessivo da carteira. A OMC (D) é a operação de mesmo comitente.","id":"10371"},{"n":831,"banco":"lucas","mod":8,"tit":"VIII","titn":"Compliance","cap":"44","capn":"Questão 44 (cód. 10372)","stem":"OMC intencional:","opts":[["a","É regular, pois é um erro operacional"],["b","É irregular"],["c","É irregular, mas não altera o fluxo das ordens e não prejudica outros investidores"],["d","É regular, porém altera o fluxo das ordens"]],"ans":"b","exp":"Tema: OMC intencional. Operação de mesmo comitente é aquela em que o investidor figura nas duas pontas da operação. Quando é intencional, é irregular, porque não se trata de erro operacional e a operação pode alterar artificialmente o fluxo das ordens. A alternativa B é a correta.\n\nA alternativa A (regular, por ser erro operacional) vale apenas para a OMC não intencional. As alternativas C e D tratam a OMC como regular em algum aspecto, o que não é o caso.","id":"10372"},{"n":832,"banco":"lucas","mod":8,"tit":"VIII","titn":"Compliance","cap":"45","capn":"Questão 45 (cód. 10373)","stem":"Negociação excessiva ou giro em excesso da carteira de um investidor com o único objetivo de gerar maior corretagem, podemos dizer que essa é a definição para:","opts":[["a","Spoofing"],["b","Layering"],["c","Churning"],["d","Front trading"]],"ans":"c","exp":"Tema: churning. É a negociação excessiva ou o giro em excesso da carteira de um investidor, com o único objetivo de gerar corretagem. A alternativa C é a correta.\n\nO spoofing (A) e o layering (B) são práticas de manipulação do livro de ofertas, com criação de liquidez artificial. O front trading (D) é operar à frente de uma ordem de cliente, e não envolve giro de carteira.","id":"10373"},{"n":833,"banco":"lucas","mod":8,"tit":"VIII","titn":"Compliance","cap":"46","capn":"Questão 46 (cód. 10374)","stem":"OMC é:","opts":[["a","Operação de mesmo comitente, mas o investidor figura somente na ponta compradora"],["b","Operação de mesmo comitente, mas o investidor figura somente na ponta vendedora"],["c","Operação de mesmo cliente, mas o investidor figura somente na ponta compradora"],["d","Operação de mesmo comitente, onde o investidor figura nas duas pontas (compradora e vendedora)"]],"ans":"d","exp":"Tema: OMC, operação de mesmo comitente. O investidor figura nas duas pontas da operação, comprador e vendedor, o que pode configurar irregularidade quando intencional. A alternativa D é a correta.\n\nAs alternativas A, B e C limitam a OMC a uma das pontas, o que não corresponde à definição. A alternativa C ainda troca comitente por cliente, o que não é o termo técnico.","id":"10374"},{"n":834,"banco":"lucas","mod":8,"tit":"VIII","titn":"Compliance","cap":"47","capn":"Questão 47 (cód. 10375)","stem":"São classificados como investidores profissionais:","opts":[["a","Clubes de investimento, desde que tenham a carteira gerida por um ou mais cotistas, que sejam investidores qualificados"],["b","Pessoas naturais ou jurídicas que possuam investimentos financeiros em valor superior a R$ 1.000.000,00 (um milhão de reais) e que, adicionalmente, atestem por escrito sua condição de investidor qualificado mediante termo próprio, de acordo com a Resolução CVM nº 30/21"],["c","Agentes autônomos de investimento, administradores de carteira de valores mobiliários, analistas de valores mobiliários e consultores de valores mobiliários autorizados pela CVM, em relação a seus recursos próprios"],["d","Pessoas naturais que tenham sido aprovadas em exames de qualificação técnica ou possuam certificações aprovadas pela CVM como requisitos para o registro de agentes autônomos de investimento, administradores de carteira de valores mobiliários, analistas de valores mobiliários e consultores de valores mobiliários, em relação a seus recursos próprios"]],"ans":"c","exp":"Tema: investidores profissionais. São profissionais as pessoas naturais ou jurídicas com investimentos financeiros superiores a R$ 10 milhões, que atestem essa condição por escrito. Também são profissionais as instituições financeiras, seguradoras, entidades de previdência, fundos de investimento e agentes autorizados pela CVM, em relação a seus recursos próprios. A alternativa C é a correta.\n\nA alternativa A (clubes com carteira gerida por qualificados) descreve os clubes qualificados. A alternativa B (mais de R$ 1 milhão) é o critério do investidor qualificado. A alternativa D (pessoas aprovadas em exames) descreve o profissional pela qualificação técnica, e não por um critério de investimento.","id":"10375"},{"n":835,"banco":"lucas","mod":8,"tit":"VIII","titn":"Compliance","cap":"48","capn":"Questão 48 (cód. 10376)","stem":"Sobre controles internos referentes à Suitability: I. É dever do Participante adotar políticas internas específicas relacionadas à recomendação de produtos complexos, que ressaltem os riscos da estrutura em comparação com a de produtos tradicionais. II. O Participante deve indicar um diretor estatutário responsável pelo cumprimento das normas de suitability estabelecidas na Resolução CVM nº 30/21. III. O diretor estatutário responsável por suitability deve encaminhar aos órgãos de administração do Participante, até o último dia útil do mês de abril, relatório relativo ao ano civil anterior à data de entrega, contendo avaliação do cumprimento das regras, procedimentos e controles internos de verificação de adequação e as recomendações a respeito de eventuais deficiências, com o estabelecimento de cronogramas de saneamento. Está correto o que se afirma em:","opts":[["a","I e II"],["b","II e III"],["c","III, apenas"],["d","Todas"]],"ans":"d","exp":"Tema: controles internos de suitability. Analisando:\n\nI. Correto. O participante deve adotar políticas específicas para produtos complexos, destacando os riscos da estrutura em comparação com produtos tradicionais.\n\nII. Correto. O participante deve indicar um diretor estatutário responsável pelo cumprimento das normas de suitability, pela Resolução CVM 30/21.\n\nIII. Correto. O relatório anual do diretor deve ser entregue até o último dia útil de abril, com avaliação do cumprimento das regras e recomendações sobre deficiências.\n\nA alternativa D (todas) é a correta.","id":"10376"},{"n":836,"banco":"lucas","mod":8,"tit":"VIII","titn":"Compliance","cap":"49","capn":"Questão 49 (cód. 10377)","stem":"É um item a ser analisado para verificar a adequação ao objetivo de investimento do cliente:","opts":[["a","O período em que o cliente deseja manter o investimento"],["b","A necessidade futura de recursos declarada pelo cliente"],["c","Os tipos de produtos, serviços e operações com os quais o cliente tem familiaridade"],["d","O valor e os ativos que compõe o patrimônio do cliente"]],"ans":"a","exp":"Tema: itens de análise para o objetivo de investimento. Ela considera o período em que o cliente deseja manter o investimento, as preferências de risco e as finalidades do investimento. A alternativa A é a correta.\n\nAs demais alternativas pertencem a outros critérios: a necessidade futura de recursos e o patrimônio fazem parte da análise da situação financeira, e a familiaridade com produtos faz parte do conhecimento e da compreensão dos riscos.","id":"10377"},{"n":837,"banco":"lucas","mod":8,"tit":"VIII","titn":"Compliance","cap":"50","capn":"Questão 50 (cód. 10378)","stem":"O Participante está dispensado de verificar a adequação do produto, serviço ou operação no caso de cliente:","opts":[["a","Pessoa física"],["b","Pessoa jurídica de direito público"],["c","Pessoa jurídica"],["d","PEP"]],"ans":"b","exp":"Tema: dispensa do processo de suitability. O participante está dispensado de verificar adequação quando o cliente é pessoa jurídica de direito público, entre outros casos. A alternativa B é a correta.\n\nPessoa física (A) não é dispensada, porque a norma exige avaliação de perfil. A pessoa jurídica em geral (C) também não é dispensada, e a PEP (D) não é categoria de dispensa, porque a PEP tem tratamento de PLD, não de suitability.","id":"10378"},{"n":838,"banco":"lucas","mod":8,"tit":"VIII","titn":"Compliance","cap":"51","capn":"Questão 51 (cód. 10379)","stem":"A pessoa natural com investimento superior a 1 milhão de reais, ao atestar essa condição nos termos exigidos pela CVM, será considerada:","opts":[["a","Investidor varejo"],["b","Investidor varejo"],["c","Investidor qualificado"],["d","Investidor profissional"]],"ans":"c","exp":"Tema: investidor qualificado e profissional. A pessoa natural com investimentos financeiros superiores a R$ 1 milhão que atesta essa condição por escrito é investidora qualificada. O profissional exige mais de R$ 10 milhões. A alternativa C é a correta.\n\nAs alternativas A e B repetem o termo \"varejo\", que é a categoria geral, e não a condição descrita. A alternativa D (profissional) exige o limite de R$ 10 milhões.","id":"10379"},{"n":839,"banco":"lucas","mod":8,"tit":"VIII","titn":"Compliance","cap":"52","capn":"Questão 52 (cód. 10380)","stem":"As informações relativas ao perfil dos investidores, devem ser atualizadas:","opts":[["a","Anualmente"],["b","Em intervalos não superiores a 24 meses"],["c","Somente quando o investidor julgar ser necessário"],["d","Utilizar o mesmo critério e periodicidade previstos na Resolução CVM 50 (PLD/FTP), observando o intervalo máximo de 5 anos"]],"ans":"d","exp":"Tema: atualização do perfil do investidor. A regra da apostila é que as informações cadastrais devem ser atualizadas no máximo a cada cinco anos, pelo mesmo critério e periodicidade da Resolução CVM 50 (PLD/FTP). A alternativa D é a correta.\n\nO intervalo de 24 meses se refere à nova análise e classificação das categorias de valores mobiliários, e não à atualização do perfil do investidor. A alternativa A (anual) é mais exigente do que a norma, e a alternativa C (quando o investidor julgar necessário) deixa a atualização à vontade dele, o que não é a regra.","id":"10380"},{"n":840,"banco":"lucas","mod":8,"tit":"VIII","titn":"Compliance","cap":"53","capn":"Questão 53 (cód. 10381)","stem":"A instituição deve indicar um diretor estatutário responsável pelo cumprimento das normas de suitability estabelecidas na Resolução CVM nº 30/21, sendo que sua nomeação ou a substituição do diretor deve ser informada à CVM :","opts":[["a","No prazo de 5 dias úteis"],["b","No prazo de 7 dias úteis"],["c","No prazo de 8 dias úteis"],["d","No prazo de 10 dias úteis"]],"ans":"b","exp":"Tema: prazo de comunicação ao CVM da nomeação do diretor de suitability. A nomeação ou a substituição do diretor deve ser informada à CVM no prazo de 7 dias úteis. A alternativa B é a correta.\n\nOs demais prazos (5, 8 e 10 dias úteis) não correspondem à regra da apostila.","id":"10381"},{"n":841,"banco":"lucas","mod":8,"tit":"VIII","titn":"Compliance","cap":"54","capn":"Questão 54 (cód. 10382)","stem":"Entre os itens abaixo, assinale: I. For inadequado ao perfil do cliente; II. Não sejam obtidas as informações que permitam a identificação do perfil do cliente; III. As informações relativas ao perfil do cliente não estejam atualizadas. Está correto o que se afirma em:","opts":[["a","Todas"],["b","II e III"],["c","I, apenas"],["d","II, apenas"]],"ans":"a","exp":"Tema: vedações de recomendação de produtos. É proibido recomendar produto ou serviço quando: for inadequado ao perfil do cliente, não sejam obtidas as informações que permitam identificar o perfil, ou as informações do perfil não estejam atualizadas. Os três itens são vedações, e por isso a alternativa A (todas) é a correta.\n\nA questão cobra a leitura completa das três vedações, porque a alternativa B (II e III) deixa de fora a inadequação, e as alternativas C e D deixam de fora pelo menos um dos itens.","id":"10382"}];
var WHY={4: {"b": "Best execution é a obrigação de buscar o melhor resultado possível na execução da ordem do cliente, não o sistema de registro eletrônico de ativos.", "c": "Electronic shares é uma expressão genérica para ações em ambiente eletrônico e não o nome técnico do sistema de transferência e liquidação por registros.", "d": "Uncertificated shares são ações sem certificado físico. O conceito trata da forma do ativo, não do sistema de liquidação."}, 5: {"a": "Book entry é o registro e a transferência escritural de ativos. Não é a regra de execução de ordens nas melhores condições para o cliente.", "c": "Electronic shares descreve ações negociadas ou mantidas eletronicamente, mas não o dever do intermediário de buscar o melhor resultado.", "d": "Uncertificated shares são ações sem certificado físico e não um regime para prevenir conflitos na execução de ordens."}, 6: {"a": "Desmaterialização é a substituição de documentos ou certificados físicos por registros eletrônicos. Não altera as contrapartes do contrato.", "b": "Liquidação diferida indica que a liquidação ocorre em data posterior à negociação. Não transforma a câmara em compradora e vendedora das operações.", "d": "Liquidação bruta processa cada obrigação individualmente, sem compensação líquida. Não é o processo de substituição das contrapartes originais."}, 40: {"b": "Risco de crédito é a possibilidade de a contraparte não cumprir uma obrigação. A questão trata de perda causada pela oscilação de preços.", "c": "Risco de liquidez é a dificuldade de negociar um ativo ou obter recursos sem perda relevante. Não é a variação do valor de mercado.", "d": "Risco operacional decorre de falhas em processos, pessoas, sistemas ou eventos externos, e não da oscilação de preços."}, 41: {"a": "O PNP acessa diretamente a negociação, mas a relação da B3 como contraparte central na liquidação ocorre perante o membro de compensação.", "b": "O PL pode liquidar operações sem exercer necessariamente a função de membro de compensação perante a contraparte central.", "d": "O comitente é o cliente final. A B3 não assume diretamente perante o comitente a posição de contraparte central."}, 42: {"a": "Survivor pays utiliza recursos mutualizados dos participantes adimplentes para cobrir a inadimplência de outro participante.", "c": "Third parties pay sugeriria uso de recursos de terceiros e não é a denominação da salvaguarda vinculada ao próprio inadimplente.", "d": "Modelo integrado descreve a arquitetura de risco e pós-negociação, não a regra de uso exclusivo dos recursos do participante inadimplente."}, 43: {"a": "“Introdutória” não é uma linha reconhecida no modelo das três linhas.", "c": "A segunda linha reúne funções de risco, compliance e controles que monitoram e orientam a gestão operacional.", "d": "A terceira linha corresponde à auditoria interna, que fornece avaliação independente sobre governança, riscos e controles."}, 44: {"a": "A área dona do risco e responsável por operar os controles integra a primeira linha de defesa.", "b": "A auditoria interna desempenha a terceira linha de defesa, com avaliação independente.", "c": "Investigar se um risco já se materializou pode fazer parte de apurações, mas não define a função principal da segunda linha."}, 45: {"b": "Front running é negociar antecipadamente usando conhecimento de ordem relevante de cliente que ainda será executada.", "c": "Insider trading é negociar com informação relevante ainda não divulgada ao mercado.", "d": "Framing não é o termo técnico usado para o giro excessivo da carteira com objetivo de gerar corretagem."}, 64: {"b": "A condição de PEP exige abordagem baseada em risco e diligência reforçada. Tratar exatamente como os demais ignora esse risco adicional.", "c": "Ser PEP não implica recusa automática de cadastro. A instituição deve avaliar e controlar o risco.", "d": "Nem toda operação de PEP é comunicada ao Coaf. A comunicação depende dos critérios de suspeição e das regras aplicáveis."}, 65: {"b": "O período indicado pelo material é de 12 meses, não 18 meses.", "c": "O conceito não se limita à movimentação em conta-corrente; também abrange custódia, operações e existência de saldo.", "d": "Além de usar prazo incorreto, a alternativa restringe indevidamente a atividade a operações de day trade."}, 66: {"b": "Conglomerados devem possuir mecanismos de intercâmbio de informações. A vedação desse intercâmbio prejudicaria a aplicação integrada da política.", "c": "A política deve ser formalizada, aprovada e atualizada. Seu conteúdo não pode ser tratado apenas como documento confidencial sem governança.", "d": "A aprovação cabe à alta administração da instituição, e não previamente ao Bacen, à CVM ou ao Coaf."}, 67: {"a": "O compliance officer atua na conformidade de forma ampla, mas a função específica de canal sobre proteção de dados pertence ao encarregado/DPO.", "b": "Marketing e comunicação não exercem, por definição, as atribuições legais do encarregado de dados.", "d": "A diretoria de RH pode tratar dados pessoais de empregados, mas não é automaticamente o canal institucional previsto para proteção de dados."}, 68: {"a": "O direito de exclusão não é absoluto. Obrigações legais, regulatórias ou outros direitos podem justificar a conservação.", "b": "A empresa deve explicar e fundamentar a impossibilidade de excluir; não basta negar sem justificativa.", "d": "A exclusão é um direito que pode ser solicitado pelo titular, sujeito às hipóteses legais de conservação."}, 69: {"a": "A LGPD prevê diversas bases legais além do consentimento, como obrigação legal, execução de contrato e legítimo interesse.", "b": "O consentimento pode ser revogado pelo titular, observadas as consequências e os tratamentos já realizados de forma legítima.", "d": "No mercado financeiro muitos tratamentos se apoiam em obrigação legal, contrato ou prevenção à fraude, portanto o consentimento não é sempre indispensável."}, 70: {"a": "A divergência de perfil não gera recusa automática. O participante deve alertar o cliente e observar os procedimentos regulatórios.", "b": "Uma ordem desenquadrada do perfil não é, por si só, situação de comunicação ao Coaf ou à CVM.", "c": "Executar sem advertência deixa de informar ao investidor a inadequação identificada pelo suitability."}, 71: {"a": "Investidor de varejo é a categoria geral e não reflete a condição especial obtida com mais de R$ 1 milhão e declaração própria.", "c": "“Investidor institucional” não é a classificação atribuída à pessoa natural apenas pelo valor informado.", "d": "Para investidor profissional, o limite patrimonial aplicável é superior ao de investidor qualificado e segue requisitos próprios."}, 72: {"b": "O objetivo do cliente integra obrigatoriamente a análise de adequação. Ignorá-lo compromete o suitability.", "c": "O objetivo não é o único critério; situação financeira e conhecimento/experiência também devem ser avaliados.", "d": "Não há um único critério universalmente mais importante. A adequação resulta da análise conjunta das informações do cliente."}, 73: {"a": "Spoofing usa ofertas sem intenção real de execução para induzir o mercado. Não é giro excessivo para gerar comissão.", "b": "Layering cria múltiplas camadas de ofertas artificiais para influenciar o livro. Não descreve a negociação excessiva da carteira.", "d": "OMC e front running são práticas distintas: OMC envolve condições artificiais e front running usa conhecimento prévio de ordens. Nenhuma define giro para gerar comissão."}, 74: {"b": "Front running usa informação sobre ordem pendente; layering utiliza várias camadas de ofertas. A descrição aponta especificamente para uma oferta falsa no spoofing.", "c": "Churning é o giro excessivo da carteira para gerar comissões.", "d": "Operação em condições artificiais é categoria mais ampla e não é o nome específico da conduta descrita."}, 75: {"a": "A responsabilização não se limita ao investidor, pois o participante também possui deveres de supervisão e controle.", "b": "A conduta pode partir do investidor, portanto a punição não se restringe ao participante de mercado.", "d": "A alternativa restringe a responsabilização ao diretor do participante; o participante de mercado também pode ser responsabilizado como instituição."}, 76: {"a": "O Bacen disciplina instituições sob sua supervisão, mas o sistema de distribuição de valores mobiliários também está sujeito às regras da CVM.", "b": "A CVM disciplina o mercado de valores mobiliários, mas as instituições financeiras também seguem regras de segurança cibernética do Bacen.", "d": "A ANPD fiscaliza proteção de dados pessoais, mas não é indicada como emissora conjunta dessas regras prudenciais do sistema de distribuição."}, 77: {"a": "Não existe modelo único do Bacen aplicável indistintamente; a política deve ser proporcional às características da instituição.", "b": "A CVM estabelece requisitos, mas não um modelo padrão único para todas as instituições.", "d": "Capital social e perfil de clientes podem ser elementos de contexto, porém a formulação exigida considera porte, perfil e modelo de negócio."}, 78: {"a": "A escolha não é totalmente livre; deve atender aos requisitos regulatórios de contratação e supervisão do serviço.", "b": "O material não exige homologação individual do prestador pelo Bacen.", "d": "Não há, para esse requisito, lista anual de prestadores divulgada pelo Bacen."}, 79: {"b": "A PRSAC não é definida por riscos socioeconômico e operacional; a norma separa as naturezas social, ambiental e climática.", "c": "Risco demográfico não substitui o risco climático previsto na política.", "d": "Riscos socioeconômico e geopolítico não formam o trio regulatório da PRSAC."}, 80: {"a": "A política não precisa ser necessariamente segregada por instituição; pode haver documento unificado no conglomerado.", "b": "Pode existir política única, mas ela não pode ignorar as particularidades de cada instituição.", "c": "Tratar apenas aspectos comuns é insuficiente, pois a política unificada deve contemplar as características específicas de cada integrante."}, 81: {"a": "O prazo apresentado no material é de 5 anos, não 10 anos.", "b": "A documentação deve ficar disponível ao Banco Central, e não ao Ministério do Meio Ambiente.", "d": "O órgão está correto, mas o prazo é de 5 anos, não 10 anos."}};
var WHY2={"1": {"b": "A Lei nº 6.385/1976 criou a CVM e disciplinou o mercado de valores mobiliários; não foi ela que estabeleceu os pilares do SFN.", "c": "A Lei nº 6.404/1976 é a Lei das Sociedades por Ações; trata da organização das companhias, não da estrutura do SFN.", "d": "A Lei nº 4.728/1965 é a Lei do Mercado de Capitais. Os pilares do SFN, com a criação do CMN e do Bacen, vieram da Lei nº 4.595/1964."}, "2": {"a": "O mercado de crédito atende às necessidades de financiamento de pessoas e empresas por meio de instituições financeiras; não é o mercado de controle da liquidez da economia.", "c": "O mercado de capitais financia investimentos de médio e longo prazo das empresas (ações, debêntures etc.), e não o controle da oferta de moeda.", "d": "O mercado de câmbio reúne as operações de compra e venda de moeda estrangeira, e não as operações de controle de moeda e juros de curto prazo."}, "3": {"a": "O Bacen supervisiona as instituições financeiras e executa a política monetária, mas não supervisiona a previdência complementar aberta.", "b": "A CVM regula e fiscaliza o mercado de valores mobiliários; seguros e previdência aberta ficam com a Susep.", "d": "A Previc supervisiona as entidades fechadas de previdência complementar (fundos de pensão), não os planos de previdência aberta."}, "7": {"a": "A câmara de compensação calcula e liquida as obrigações das operações; a guarda dos ativos e a proteção da titularidade cabem à central depositária.", "b": "A central de registro registra ativos e operações, principalmente de balcão, mas a guarda centralizada que protege a propriedade dos ativos é função da central depositária.", "c": "A Câmara de Câmbio liquida operações interbancárias de câmbio; não faz a guarda de ativos."}, "8": {"a": "O membro de compensação responde perante a câmara pela liquidação das operações; não é o canal de acesso direto ao sistema de negociação.", "c": "O participante de liquidação atua na liquidação das operações perante o membro de compensação; não dá acesso direto à negociação.", "d": "Banco de investimento é um tipo de instituição financeira, e não uma categoria de acesso ao sistema de negociação da B3."}, "9": {"a": "A BSM é a entidade que administra o mecanismo, mas não é o nome do mecanismo de ressarcimento.", "c": "PAD é o Processo Administrativo Disciplinar, instaurado pela BSM para apurar infrações e aplicar sanções; não é o mecanismo de ressarcimento de prejuízos.", "d": "RPB3 não é o nome de nenhum mecanismo previsto no guia; o mecanismo correto é o MRP – Mecanismo de Ressarcimento de Prejuízos."}, "10": {"b": "Rendimentos fixos são típicos da renda fixa; a ação não paga remuneração fixa predeterminada ao acionista.", "c": "“Rendimentos variáveis” é uma expressão genérica, não uma forma de remuneração deliberada e paga pela companhia.", "d": "O ganho de capital vem da valorização da ação, realizada pelo investidor na venda; não é um pagamento feito pela empresa."}, "11": {"a": "Ponderar por pesos iguais significa dar o mesmo peso a todas as ações, o que não corresponde ao critério do Ibovespa apresentado no guia.", "b": "O gabarito do guia indica “ponderado por liquidez”. Atenção: na descrição da metodologia, o guia explica que os ativos são ponderados pelo valor de mercado do free float, com limite de participação baseado na liquidez — por isso a capitalização de mercado pura não é a resposta esperada.", "c": "“Pesos diferenciados” é uma expressão genérica que não identifica o critério de ponderação do índice."}, "12": {"a": "O envolvimento da emissora estrangeira caracteriza os programas patrocinados; no BDR Não Patrocinado a iniciativa é apenas da instituição depositária.", "c": "Bolsas estrangeiras não participam dessa decisão; quem solicita o registro à CVM e à B3 é a instituição depositária no Brasil.", "d": "A alternativa fala da origem das empresas e não responde ao ponto da questão: no BDR NP N1 a emissora estrangeira não se envolve."}, "13": {"a": "O contrato futuro de moedas é negociado em bolsa, é padronizado e tem ajustes diários; o enunciado descreve uma operação de balcão.", "c": "O contrato futuro de dólar também é negociado em bolsa, com ajustes diários, e não em balcão com taxa travada até o vencimento.", "d": "O termo de mercadorias tem como objeto commodities, e não a taxa de câmbio entre duas moedas."}, "14": {"a": "Falta o arbitrador, que busca lucro explorando distorções de preço entre mercados ou vencimentos.", "b": "Falta o especulador, que assume risco em busca de lucro com a variação de preços e traz liquidez ao mercado.", "d": "Falta o hedger, que usa derivativos para se proteger do risco de variação de preços."}, "15": {"a": "O cupom limpo usa a taxa de câmbio do próprio dia de início do período; o DDI negocia o cupom sujo, que usa a PTAX do dia útil anterior.", "b": "“Cupom sintético” não é o nome do cupom negociado no contrato futuro de DDI.", "c": "O cupom cambial a termo (limpo) é negociado pelo FRA de cupom (FRC), que combina dois contratos de DDI com posições opostas; o DDI isolado negocia o cupom sujo."}, "16": {"a": "O Selic é o sistema do Bacen para custódia e liquidação de títulos públicos federais (e também o nome da taxa básica de juros); não é o programa de venda direta a pessoas físicas.", "c": "A Cetip foi a depositária e registradora de ativos de balcão que se integrou à B3; não é o programa do Tesouro para pessoas físicas.", "d": "O Puma é a plataforma de negociação da B3 (Puma Trading System), e não o programa de venda de títulos públicos a pessoas físicas."}, "17": {"a": "A última lacuna está errada: quanto maior a duration, maior (e não menor) a exposição ao risco.", "c": "A segunda lacuna está errada: quanto maior a duration, maior (e não menor) o tempo para recuperar o valor investido.", "d": "A segunda e a terceira lacunas estão erradas: tempo de recuperação e exposição ao risco aumentam junto com a duration."}, "18": {"a": "O CRI tem lastro em recebíveis imobiliários, e não em recebíveis do agronegócio.", "b": "O CDB é um título de captação bancária e não tem lastro em recebíveis do agronegócio.", "c": "A LTN é um título público federal prefixado emitido pelo Tesouro Nacional, sem lastro em recebíveis."}, "19": {"a": "A alternativa omite a liquidação em D+2, que também é permitida.", "b": "A alternativa omite a liquidação em D+0 (no mesmo dia), que também é permitida.", "d": "A alternativa restringe a liquidação a D+0, mas as partes também podem escolher D+1 ou D+2."}, "20": {"b": "O Sisbex era o antigo sistema eletrônico de negociação de títulos públicos, substituído pelo Puma Trading System; não é a plataforma de dólar pronto.", "c": "O BovespaFix era o antigo sistema eletrônico de negociação de títulos privados de renda fixa, também substituído pelo Puma Trading System.", "d": "Tradenet não é a plataforma eletrônica da B3 para negociar dólar pronto."}, "21": {"b": "PCAM não é o nome da taxa de referência calculada pelo Bacen a partir das consultas diárias ao mercado.", "c": "A Reuters é uma provedora de informações de mercado, e não a taxa de referência calculada pelo Banco Central.", "d": "“Taxa B3” não designa a taxa média de câmbio; a PTAX é calculada e divulgada pelo Banco Central."}, "22": {"a": "O valor de emissão é o preço pelo qual as cotas são emitidas em um dado momento, e não a fração do patrimônio em si.", "c": "O valor financeiro é o montante em reais aplicado ou resgatado (quantidade × valor da cota).", "d": "A quantidade indica quantas cotas o investidor tem, e não a fração do patrimônio do fundo."}, "23": {"a": "Nos fundos fechados as cotas só são resgatadas ao fim do prazo de duração; antes disso, a saída é pela venda no mercado secundário.", "b": "Fundos exclusivos são definidos pelo público (um único cotista), e não pelo regime de aplicações e resgates.", "d": "“Ativo” se refere à estratégia de gestão (buscar superar um índice de referência), e não ao regime de aplicações e resgates."}, "24": {"a": "O fundo de renda fixa é classificado pela composição da carteira e, em geral, não tem cotas negociadas em bolsa que repliquem um índice.", "b": "O fundo de ações investe principalmente em ações, mas não necessariamente replica um índice nem tem cotas negociadas em bolsa.", "c": "O fundo imobiliário tem cotas negociadas em bolsa, mas investe em ativos imobiliários e não replica um índice."}, "25": {"a": "O valor de emissão é o preço pelo qual as cotas do clube são emitidas, e não a fração do patrimônio.", "c": "O valor financeiro é o montante em reais aplicado ou resgatado, e não a fração do patrimônio do clube.", "d": "A quantidade indica quantas cotas o participante tem, e não a fração do patrimônio do clube."}, "26": {"b": "A CVM regula os clubes de investimento, mas o registro é feito na B3.", "c": "O Bacen não tem atribuição sobre o registro de clubes de investimento.", "d": "A BSM atua na autorregulação e supervisão, mas não é a entidade responsável pelo registro dos clubes."}, "27": {"a": "A distribuição de cotas de clube por meios públicos de comunicação não é permitida; o guia trata essa prática como vedada.", "c": "Não há ressalvas que autorizem esse tipo de distribuição: a vedação abrange imprensa, rádio, TV, páginas abertas na internet e malas diretas.", "d": "A vedação não é parcial nem tem ressalvas; a distribuição por esses meios é simplesmente vedada."}, "28": {"b": "A LIG (Letra Imobiliária Garantida) é um título de renda fixa lastreado em créditos imobiliários, com carteira de ativos em patrimônio separado da emissora (inspirada nos covered bonds); não é a versão brasileira das notas estruturadas.", "c": "Vendor é a empresa que distribui informações de mercado, e não um produto de investimento.", "d": "O CDB é um título de captação bancária, sem a estrutura com derivativos embutidos típica das notas estruturadas."}, "29": {"a": "A União não emite Cepac; o instrumento é municipal e ligado ao planejamento urbano.", "c": "Os estados não emitem Cepac; as operações urbanas consorciadas são municipais.", "d": "As empresas não emitem Cepac; elas podem comprá-los para obter o direito de construir além do limite básico."}, "30": {"a": "Vendor é a empresa que redistribui as informações da bolsa aos usuários finais, e não o serviço da B3 que as gera e envia.", "b": "A gestão de garantias trata do controle dos colaterais depositados pelos participantes, e não da difusão de informações.", "d": "O Cepac é um valor mobiliário municipal ligado a direitos de construção, e não um serviço de informações."}, "31": {"b": "A ordem está invertida: primeiro se calcula o IOF, que é deduzido do rendimento, e depois incide o IR.", "c": "Também há incidência de Imposto de Renda; o prazo curto não isenta do IR.", "d": "Em prazos inferiores a 30 dias também incide o IOF, cobrado antes do IR."}, "32": {"a": "A poupança é isenta, mas o CDB é tributado pela tabela regressiva do IR.", "b": "O CDB é tributado pelo IR, o que torna a alternativa incorreta.", "d": "A LCI é isenta para pessoa física, mas o CDB é tributado pelo IR."}, "33": {"b": "Investidores domiciliados em paraísos fiscais não têm acesso ao regime especial; seguem as mesmas regras aplicáveis aos residentes no Brasil.", "c": "A alternativa inclui indevidamente os domiciliados em paraísos fiscais, que não têm acesso ao regime especial.", "d": "Os residentes seguem o regime geral de tributação; o regime especial vale apenas para não residentes fora de paraísos fiscais."}, "34": {"a": "A corretora é intermediária; a estrutura de contas deve identificar o titular final dos ativos, e não o intermediário.", "b": "O banco custodiante presta o serviço de custódia, mas as contas devem estar em nome do beneficiário final.", "d": "O sistema de custódia é infraestrutura, e não titular dos ativos; as contas ficam em nome do beneficiário final."}, "35": {"b": "A identificação é do investidor (comitente final), e não da corretora que intermedia a operação.", "c": "A identificação deve ocorrer quando a operação é realizada, e não depois, na liquidação.", "d": "A regra exige identificar o investidor na própria operação, e não apenas no momento do registro na conta máster."}, "36": {"a": "A alternativa omite a possibilidade de repasse entre um PNP e um PL.", "b": "A alternativa omite a exigência de vínculo de repasse entre as partes.", "c": "A alternativa omite a possibilidade de repasse entre PNP e PL e a exigência de contrato específico."}, "37": {"a": "“Residentes e domiciliados” deixa de fora os investidores não residentes, que também são abrangidos pelas normas.", "c": "A alternativa deixa de fora os investidores residentes, que também estão sujeitos às normas de cadastro.", "d": "A categoria correta é “residentes e não residentes”; “residentes não domiciliados” não é a classificação usada."}, "38": {"b": "A resolução não restringe o acesso a mercados específicos; ela dá acesso aos mesmos mercados disponíveis ao residente.", "c": "Não há restrição ao mercado de juros; o acesso é aos mesmos mercados do investidor residente.", "d": "Não há restrição ao mercado de ações; o acesso é aos mesmos mercados do investidor residente."}, "39": {"a": "O representante fiscal cuida dos assuntos tributários do investidor perante as autoridades brasileiras; quem faz o registro na CVM é o representante legal.", "c": "O custodiante guarda e controla os ativos e mantém a documentação atualizada, mas não é quem faz o registro na CVM.", "d": "O investidor não residente atua por meio de representante no país; não faz o registro diretamente."}, "46": {"a": "Contradiz o estilo americano, que permite o exercício a qualquer tempo até o vencimento.", "c": "Exercício apenas na data de vencimento caracteriza a opção de estilo europeu.", "d": "D+2 é um prazo de liquidação, e não a regra de exercício da opção americana."}, "47": {"a": "Omite a data de vencimento e o tipo de liquidação; além disso, “quantidade máxima” não está entre as características padronizadas citadas.", "b": "Omite a cotação e restringe a “liquidação bruta”, quando o tipo de liquidação é uma característica definida pela bolsa para cada contrato.", "c": "Nos contratos futuros os vencimentos são padronizados pela bolsa; “qualquer data” é característica de operações a termo ou de balcão."}, "48": {"a": "A opção não envolve empréstimo de ativos; o lançador de put assume a obrigação de comprar.", "c": "Vender ao titular é a obrigação do lançador de uma opção de compra (call), e não de venda.", "d": "O lançador recebe o prêmio e, por isso, assume a obrigação de comprar o ativo se a opção for exercida."}, "49": {"a": "A B3 administra os mercados, mas apurar e punir as infrações do Regulamento de Negociação cabe à BSM, sua autorreguladora.", "c": "A CVM pune no âmbito de sua competência legal, mas o enunciado trata do Regulamento de Negociação da B3 e das penalidades do estatuto e do regulamento processual da BSM.", "d": "O Bacen não é responsável por apurar infrações ao Regulamento de Negociação da B3."}, "50": {"b": "After-hours é um período de negociação após o pregão regular, e não um mecanismo de interrupção.", "c": "Co-location é o serviço de hospedar servidores no data center da bolsa para reduzir latência.", "d": "STP (straight-through processing) é o processamento automático de ponta a ponta, sem intervenção manual."}, "51": {"a": "O PNP tem acesso direto ao ambiente de negociação e transmite ordens; é intermediário, e não o cliente cujas ordens são transmitidas.", "b": "O PN é um intermediário que atua por meio de um PNP; não é o cliente final.", "d": "O formador de mercado é contratado para manter ofertas de compra e venda e dar liquidez; não é o comitente."}, "52": {"a": "O participante de liquidação responde pela liquidação de suas operações e de seus clientes, mas não é ele quem movimenta a conta reservas junto à câmara.", "c": "O participante de negociação negocia em nome dos clientes, mas não movimenta conta reservas bancárias com a câmara.", "d": "O membro de compensação liquida o saldo com a câmara, mas os pagamentos são efetuados pela conta reservas bancárias (ou conta de liquidação) do liquidante."}, "53": {"a": "O comitente é o cliente final; a câmara não assume posição de contraparte central diretamente perante ele.", "b": "O participante de negociação não é contraparte direta da câmara na liquidação.", "c": "O participante de liquidação atua na compensação e liquidação por meio de um membro de compensação; a câmara é contraparte central exclusivamente perante o membro de compensação."}, "54": {"a": "Insolvência é uma situação patrimonial mais ampla (incapacidade de pagar as dívidas em geral), e não o termo usado pela câmara para falha de liquidação.", "b": "A concordata era um instituto da antiga lei de falências, substituído pela recuperação judicial, e não se aplica a esse caso.", "d": "Devedor operacional é a classificação de quem deixa de liquidar por motivo operacional. Quando a falha decorre de insuficiência financeira, como no enunciado, o participante pode ser declarado inadimplente."}, "55": {"b": "Swing trade é a estratégia de manter posições por alguns dias, e não comprar e vender no mesmo dia.", "c": "Front runner é quem pratica front running, conduta ilícita de antecipar-se a ordens de clientes.", "d": "Spot significa mercado à vista, e não a combinação de compra e venda no mesmo dia."}, "56": {"a": "A alternativa omite a modalidade com garantia parcial.", "c": "Restringir a operações sem garantia está errado: também existem as modalidades com garantia e com garantia parcial.", "d": "Restringir a operações com garantia está errado: também existem as modalidades sem garantia e com garantia parcial."}, "57": {"a": "Na modalidade com garantia (total), a câmara atua como contraparte central de ambas as partes e garante a liquidação.", "b": "Na modalidade com garantia parcial, a câmara atua como contraparte central de apenas uma das partes (por exemplo, em swaps); portanto, não se limita a operacionalizar a liquidação.", "c": "“Sem garantia parcial” não é uma modalidade prevista para as operações registradas."}, "58": {"a": "Comunicados divulgam avisos e informações ao mercado, mas a política de tarifação é divulgada por ofício circular.", "c": "Informes ao mercado não são o instrumento usado para divulgar a política de tarifação da B3.", "d": "Os membros de compensação não divulgam a política de tarifação da B3; ela é publicada pela própria B3 por ofício circular."}, "59": {"b": "A política de tarifação trata dos custos e encargos cobrados, e não da continuidade das atividades em caso de desastre.", "c": "“Política de processamento de dados” não é o documento que garante a continuidade das atividades.", "d": "A unidade de contingência externa é um dos recursos previstos, mas o documento citado no guia é a política de continuidade de negócios."}, "60": {"a": "Sistema externo é uma infraestrutura de mercado (sistema de negociação, câmara ou central depositária) autorizada a se conectar à B3, e não o participante com acesso para custódia.", "b": "O emissor é quem emite os ativos, e não quem tem autorização de acesso para custódia.", "c": "O escriturador é contratado pelo emissor para manter os registros dos ativos escriturais, mas não é o participante com autorização de acesso para custódia na central depositária."}, "61": {"a": "“Serviço de Atendimento ao Investidor” não é o nome do serviço oferecido pela central depositária no site.", "c": "“Consulta de Participantes” não é o nome do serviço citado no guia.", "d": "As consultas de posição e movimentação ficam dentro da Área do Investidor; “Extrato Eletrônico” não é o nome do serviço."}, "62": {"a": "A alternativa omite o comitente: as contas são identificadas por agente de custódia e por comitente.", "b": "A alternativa omite o agente de custódia: as contas são identificadas por agente de custódia e por comitente.", "d": "“Conta de ativos” não é critério de identificação; as contas são divididas em carteiras, e não numeradas por ativo."}, "63": {"b": "“Digital” não é o termo técnico usado; o controle dos saldos é feito em forma escritural.", "c": "A guarda centralizada é desmaterializada, por registros eletrônicos, e não física.", "d": "A fungibilidade é uma característica dos ativos custodiados, e não a forma de controle dos saldos."}};Object.keys(WHY2).forEach(function(k){WHY[k]=WHY[k]||{};Object.keys(WHY2[k]).forEach(function(l){WHY[k][l]=WHY2[k][l]})});
var WHY3={"82": {"a": "25% não é o limite legal; a lei exige no mínimo 50% de ações ordinárias.", "b": "Um terço não é o limite da Lei das S.A.; o mínimo de ações ordinárias é 50% do capital.", "d": "Dois terços não é o critério legal; a exigência é de no mínimo 50% de ordinárias."}, "83": {"b": "O free float de 20% (ou regra alternativa) também se aplica ao Nível 1; não é exclusivo do Novo Mercado.", "c": "Manter ações preferenciais é característica do Nível 2; o Novo Mercado só admite ações ordinárias.", "d": "A listagem sem oferta, com até sete anos para o IPO, é característica do Bovespa Mais."}, "84": {"a": "O Novo Mercado é o segmento de mais alto padrão de governança, com capital só em ações ordinárias; não prevê listagem sem oferta.", "b": "O Nível 2 se caracteriza por permitir ações preferenciais com tag along de 100%, e não pela listagem sem oferta.", "c": "O Nível 1 exige práticas de transparência e free float mínimo, mas não prevê listagem sem oferta com prazo para o IPO."}, "85": {"a": "Na subscrição o acionista tem preferência para adquirir novas ações, pagando por elas; não é distribuição gratuita.", "c": "O desdobramento divide as ações existentes, sem aumento de capital nem incorporação de reservas.", "d": "Juros sobre capital próprio são remuneração em dinheiro, e não a entrega de novas ações."}, "86": {"b": "O desdobramento (split) divide cada ação em várias, ou seja, faz o movimento contrário ao descrito.", "c": "A bonificação distribui novas ações gratuitamente, aumentando a quantidade em poder do acionista.", "d": "A subscrição é a aquisição de novas ações em aumento de capital, mediante pagamento."}, "87": {"a": "A ordem a mercado especifica só a quantidade e as características do ativo e é executada assim que recebida, sem limite de preço.", "b": "Na ordem administrada a execução fica a critério do PNP ou do PN, sem preço fixado pelo cliente.", "d": "A ordem casada é vinculada à execução de outra ordem do cliente; o limite de preço não é sua característica definidora."}, "88": {"a": "A ordem stop especifica o preço a partir do qual a ordem deverá ser executada.", "c": "A ordem limitada fixa o preço máximo (compra) ou mínimo (venda) para a execução.", "d": "A ordem casada depende da execução de outra ordem do cliente."}, "89": {"b": "Ofertas on close (MOC/LOC) são direcionadas ao call de fechamento, e não vinculadas a outra ordem.", "c": "A ordem stop é disparada quando o preço do ativo atinge o nível especificado.", "d": "Na ordem administrada a execução fica a critério do intermediário, sem vínculo com outra ordem."}, "90": {"a": "15 minutos não é o prazo previsto; na queda de 10% a interrupção é de 30 minutos.", "c": "A interrupção de 1 hora ocorre quando a queda atinge 15%, após a reabertura.", "d": "A suspensão por prazo definido pela B3 vale para a queda de 20%."}, "91": {"a": "30 minutos é a interrupção correspondente à queda de 10%.", "b": "Não há interrupção de 2 horas na regra do circuit breaker.", "d": "A suspensão por prazo definido pela B3 só se aplica à queda de 20%; não há regra automática até o fim do pregão na queda de 15%."}, "92": {"b": "O doador entrega os ativos; quem deposita garantias é o tomador, que assume a obrigação de devolvê-los.", "c": "O aval de corretora não é o requisito previsto; a exigência é de garantias do tomador depositadas na B3.", "d": "O emissor não participa do empréstimo nem contrata seguro para essas operações."}, "93": {"a": "O doador não perde os proventos: o tomador é obrigado a reembolsá-lo.", "c": "A companhia credita o provento a quem detém o ativo na data-base, que é o tomador.", "d": "A B3 não paga proventos com recursos próprios; a compensação é feita pelo tomador."}, "94": {"a": "O prazo mínimo é de 16 dias corridos, e não de 1 dia; o máximo é de 999 dias.", "c": "Os limites corretos são 16 e 999 dias corridos.", "d": "Os prazos são contados em dias corridos, e o máximo é de 999 dias."}, "95": {"a": "O preço pelo qual o titular pode exercer o direito é o preço de exercício (strike).", "b": "O fluxo é inverso: quem paga o prêmio é o titular, e quem recebe é o lançador.", "d": "O titular paga o prêmio, mas a margem de garantia é exigida de quem assume a obrigação, o lançador."}, "96": {"b": "S < K torna positivo o valor intrínseco da opção de venda (put), e não da call.", "c": "Com S = K o valor intrínseco da call é zero.", "d": "O valor intrínseco da call é zero sempre que S ≤ K."}, "97": {"a": "Negociação em bolsa com vencimentos padronizados é característica das opções listadas, e não das flexíveis.", "c": "Nas opções flexíveis as características são definidas pelas partes; não há imposição de estilo ou forma de liquidação.", "d": "Não há restrição de público a investidores não residentes."}, "98": {"a": "1.000 pontos não é o valor do DI1 no vencimento; o PU é de 100.000 pontos.", "b": "10.000 pontos não corresponde ao PU de vencimento do DI1.", "d": "O PU no vencimento é de 100.000 pontos, e não de 1 milhão."}, "99": {"a": "Os vencimentos não são mensais; ocorrem a cada dois meses.", "c": "Os vencimentos não são trimestrais; são bimestrais.", "d": "Os vencimentos são bimestrais, mas nos meses pares, e não nos ímpares."}, "100": {"b": "No swap não há troca de propriedade de ativos, mas de fluxos financeiros calculados sobre um valor de referência.", "c": "Direito sem obrigação é característica das opções, e não do swap.", "d": "Ajustes diários padronizados em bolsa são próprios dos contratos futuros."}, "101": {"a": "As debêntures simples pagam remuneração e principal, sem possibilidade de troca por ações.", "b": "As conversíveis permitem a troca por ações da própria companhia emissora, e não de outra empresa.", "d": "Incentivadas são debêntures com benefício tributário para financiar infraestrutura; a classificação não trata de troca por ações."}, "102": {"b": "Título bancário com lastro em créditos do agronegócio é a LCA, e não a CPR.", "c": "Certificado de securitizadora com lastro imobiliário é o CRI.", "d": "A CPR é um título privado do agronegócio, e não um título público."}, "103": {"a": "Junho e dezembro não são os meses do come-cotas; o recolhimento ocorre em maio e novembro.", "b": "Março e setembro não são os meses previstos.", "d": "Janeiro e julho não são os meses previstos; o correto é maio e novembro."}, "104": {"b": "R$ 35 mil é o limite de isenção para a venda de outros bens, e não de ações no mercado à vista.", "c": "R$ 10 mil não é o limite previsto; o valor é R$ 20 mil em alienações no mês.", "d": "R$ 50 mil não é o limite previsto para a isenção em ações."}, "105": {"a": "0,005% na fonte e 15% ao mês são as alíquotas das operações comuns, e não do day trade.", "c": "A retenção de 1% está correta, mas a alíquota mensal do day trade é de 20%, e não 15%.", "d": "A alíquota mensal de 20% está correta, mas a retenção na fonte do day trade é de 1%, e não 0,005%."}, "106": {"a": "O conselho tem 12 membros, e a exigência é de pelo menos dois terços independentes, não apenas maioria.", "b": "O número de membros e a proporção de independentes estão incorretos: são 12 membros, com pelo menos dois terços independentes.", "c": "O número de membros está certo, mas a exigência é de pelo menos dois terços independentes, e não de todos."}};Object.keys(WHY3).forEach(function(k){WHY[k]=WHY[k]||{};Object.keys(WHY3[k]).forEach(function(l){WHY[k][l]=WHY3[k][l]})});
var WHY4={"107":{"b":"O Presidente da República e o Presidente da CVM não integram o CMN.","c":"CVM e Susep são órgãos supervisores que seguem as diretrizes do CMN, mas não o compõem.","d":"A B3 é uma infraestrutura de mercado privada e não integra o CMN."},"108":{"a":"US$ 10.000,00 é o tamanho do minicontrato de dólar (WDO), e não do contrato padrão.","b":"US$ 25.000,00 não corresponde a nenhum dos contratos de dólar descritos no guia.","d":"O contrato padrão tem US$ 50.000,00, e não US$ 100.000,00."},"109":{"a":"US$ 1.000,00 não é o tamanho do minicontrato de dólar.","b":"US$ 5.000,00 não é o tamanho do minicontrato de dólar.","c":"US$ 50.000,00 é o tamanho do contrato padrão (DOL), e não do minicontrato."},"110":{"b":"O último dia útil do mês anterior não é a data de vencimento; os contratos vencem no primeiro dia útil do mês de vencimento.","c":"A quarta-feira mais próxima do dia 15 é a regra de vencimento do futuro de Ibovespa, e não do dólar.","d":"Dia 15 não é a regra de vencimento dos contratos de dólar."},"111":{"a":"Os recursos próprios da B3 ficam entre as últimas camadas da cadeia de salvaguardas, e não na primeira.","c":"As contribuições dos membros adimplentes (survivors pay) só são usadas depois de esgotadas as camadas anteriores.","d":"O fundo de liquidação é acionado depois das garantias do comitente e dos intermediários."},"112":{"a":"A CORE é uma metodologia de risco, e não de cálculo de tributos.","b":"Os horários de negociação são definidos pela B3 em seus regulamentos e não têm relação com a CORE.","d":"A classificação em segmentos de listagem depende de regras de governança, e não da metodologia de risco."},"113":{"a":"5 minutos não é a duração mínima prevista para esse leilão.","c":"30 minutos não é a duração mínima prevista para o leilão especial.","d":"1 hora não é a duração mínima do leilão especial; é o tempo de interrupção do circuit breaker na queda de 15%."},"114":{"a":"“Alta” e “baixa” não são as categorias de túneis previstas.","b":"“Abertura” e “fechamento” são fases do pregão, e não tipos de túnel.","c":"“Liquidez” e “volatilidade” não são as categorias de túneis previstas."},"115":{"b":"O período antes da abertura é o pré-abertura (leilão de abertura), e não o after-market.","c":"O after-market acontece no próprio ambiente de bolsa, e não no balcão não organizado.","d":"O after-market é um período de negociação, e não uma janela de liquidação."},"116":{"a":"50% não é o percentual previsto na Lei das S.A.","b":"70% não é o percentual previsto na Lei das S.A.","d":"100% é o tag along exigido em segmentos especiais, como o Novo Mercado, e não o mínimo legal."},"117":{"a":"50% não é o percentual mínimo de distribuição previsto para os FII.","b":"75% não é o percentual mínimo de distribuição previsto para os FII.","c":"90% não é o percentual previsto; o mínimo é de 95% do lucro."},"118":{"a":"50 cotistas não é o número mínimo exigido para a isenção.","c":"500 cotistas não é o número exigido; o mínimo é de 100 cotistas.","d":"1.000 cotistas não é o número exigido; o mínimo é de 100 cotistas."},"119":{"b":"5% não é o limite previsto; o cotista pode ter até 10% das cotas.","c":"20% supera o limite individual de 10%.","d":"30% é o limite para o conjunto dos membros de uma família, e não para o cotista individual."},"120":{"a":"25% não é o percentual mínimo previsto para o FIDC.","b":"Um terço não é o percentual mínimo previsto para o FIDC.","d":"Dois terços não é o percentual previsto; o mínimo é de 50%."},"121":{"a":"O FIDC aplica principalmente em direitos creditórios, e não em participações societárias.","c":"O FII investe em empreendimentos e ativos imobiliários.","d":"O ETF replica um índice de mercado e tem cotas negociadas em bolsa."},"122":{"a":"90 dias é um prazo típico de títulos de curto prazo, e não o mínimo da LF.","b":"1 ano é inferior ao prazo mínimo de dois anos da LF.","c":"5 anos não é o prazo mínimo; a LF pode ter prazo a partir de dois anos."},"123":{"b":"R$ 300.000,00 é o valor mínimo da LF COM cláusula de subordinação.","c":"R$ 1.000,00 é muito inferior ao valor mínimo previsto para a LF.","d":"R$ 150.000,00 não é um dos valores mínimos previstos para a LF."},"124":{"a":"O título com promessa de entrega de produtos rurais é a CPR.","b":"O título de securitizadora com lastro imobiliário é o CRI.","d":"A LCA é um título privado, e não um título público federal."},"125":{"a":"Títulos bancários de longo prazo para crédito imobiliário são instrumentos como a LCI ou a LIG, e não as notas comerciais.","c":"As notas comerciais são títulos privados, e não públicos.","d":"Notas comerciais são títulos de dívida; a conversão em ações é característica das debêntures conversíveis."},"126":{"a":"15% é a menor alíquota da tabela regressiva, mas não se aplica às debêntures incentivadas para pessoa física.","b":"22,5% é a alíquota da tabela regressiva para prazos de até 180 dias.","d":"As debêntures incentivadas têm regime próprio, com alíquota zero para pessoa física, e não seguem a tabela regressiva."},"127":{"a":"22,5% é a alíquota para prazos de até 180 dias.","c":"17,5% é a alíquota para prazos de 361 a 720 dias.","d":"15% é a alíquota para prazos acima de 720 dias."},"128":{"a":"20% vale para prazos de 181 a 360 dias.","c":"15% só vale para prazos acima de 720 dias.","d":"22,5% vale para prazos de até 180 dias."},"129":{"a":"0,38% é a alíquota do IOF em outras operações, como câmbio e crédito, e não a regra regressiva sobre o rendimento.","b":"Não há alíquota fixa mensal de IOF nesses resgates; ela é regressiva conforme os dias.","d":"22,5% a 15% é a faixa da tabela regressiva do Imposto de Renda, e não do IOF."},"130":{"a":"O CMN é o órgão normativo do SFN e fixa a meta de inflação, mas não define a meta da Selic.","c":"O CRSFN julga recursos contra sanções administrativas, sem papel na política de juros.","d":"A CVM regula o mercado de valores mobiliários e não define a política monetária."},"131":{"a":"A LTN é o Tesouro Prefixado (sem cupom), e não o título indexado ao IPCA.","b":"A LFT é o Tesouro Selic, título pós-fixado.","c":"A NTN-F é o Tesouro Prefixado com juros semestrais."},"132":{"a":"Não há prazo de 48 horas contado da operação; o prazo é de 24 horas a partir da conclusão da análise.","c":"5 dias úteis não é o prazo da norma; a comunicação deve ocorrer em até 24 horas após a análise.","d":"30 dias após o mês da operação não é o prazo de comunicação de operações suspeitas ao Coaf."},"133":{"a":"1 ano é inferior ao mínimo exigido; a guarda deve ser de pelo menos 5 anos.","b":"2 anos não atende à exigência da norma, que é de no mínimo 5 anos.","d":"10 anos não é o prazo mínimo previsto; a norma exige pelo menos 5 anos."},"134":{"b":"A Lei nº 12.965/2014 é o Marco Civil da Internet; não criou a ANPD e a LGPD trata de pessoas naturais.","c":"A Lei nº 9.613/1998 é a Lei de Lavagem de Dinheiro, não a LGPD.","d":"A LC nº 105/2001 trata do sigilo bancário; as bases legais de tratamento estão na LGPD."},"135":{"a":"6 meses não é a periodicidade prevista; o limite é de 24 meses.","b":"12 meses não é o intervalo definido na norma; o máximo é de 24 meses.","c":"36 meses excede o limite; a reavaliação deve ocorrer em até 24 meses."},"136":{"a":"A primeira linha é a gestão operacional, que executa os processos e controla os riscos no dia a dia.","b":"A segunda linha reúne controles internos, gestão de riscos e compliance, não a auditoria interna.","d":"A quarta linha corresponde à auditoria externa e aos reguladores."},"137":{"b":"A Resolução CVM nº 30/2021 trata de suitability, não de estrutura de gerenciamento de riscos.","c":"A Resolução CMN nº 4.945/2021 trata da PRSAC (responsabilidade social, ambiental e climática).","d":"A Resolução CVM nº 50/2021 trata de PLD/FTP."},"138":{"a":"O RDE é o Registro Declaratório Eletrônico do Bacen, usado nos capitais de investidores não residentes.","c":"O Sisbacen é o sistema de informações do Banco Central, não o cadastro da B3.","d":"CORE é a metodologia de cálculo de risco da Câmara B3, não um sistema de cadastro."},"139":{"a":"A conta máster não é conta de depósito definitiva; as operações são alocadas depois aos beneficiários finais.","b":"A conta máster não é exclusiva de não residentes nem é aberta pelo representante legal.","d":"A conta máster não é conta de garantia; serve para agrupar ordens para posterior alocação."},"140":{"a":"Os ativos não passam a integrar o patrimônio da B3 em nenhum momento; ficam segregados.","b":"A B3 não pode usar ativos de comitentes para cobrir perdas de outros participantes, pois eles são segregados.","c":"O agente de custódia não é proprietário dos ativos; a titularidade é do comitente."},"141":{"b":"O controle sintético registra apenas a quantidade consolidada, sem datas e custos de aquisição.","c":"Fungível não é uma modalidade de controle de saldos; descreve ativos intercambiáveis entre si.","d":"Consolidado não é o nome da modalidade que registra custos e datas de aquisição."}};Object.keys(WHY4).forEach(function(k){WHY[k]=WHY[k]||{};Object.keys(WHY4[k]).forEach(function(l){WHY[k][l]=WHY4[k][l]})});
var WHY5={"142":{"a":"Está incompleta: o item II também está correto, porque o SFN reúne recursos superavitários para quem precisa deles.","c":"Inclui o item III, que inverte a lógica. Quem articula estratégias são os superavitários em favor dos deficitários, e não o contrário.","d":"Inclui o item III, que está errado, e o item IV, que não é função do SFN. Unificar moedas e equilibrar a balança comercial não fazem parte do conceito de sistema financeiro."},"143":{"a":"Inclui o item II, que está errado: 'Mercado Consumidor' não é um dos mercados do SFN.","b":"Inclui o item II (mercado consumidor) e o item III (mercado concorrente), que não são mercados do SFN.","c":"Inclui o item III, errado, porque 'Mercado Concorrente' não é um dos mercados do SFN. O item V está certo, mas não basta para validar a alternativa."},"144":{"a":"Normatizar a concorrência não é função do Bacen, e não faz parte do papel do Banco Central no mercado monetário.","b":"O Bacen atua no câmbio, mas o controle de câmbio não é a prática que define o mercado monetário, que trata da oferta de moeda e dos juros de curto prazo.","d":"Fiscalizar a previdência é papel da Previc (previdência fechada) e da Susep (previdência aberta), e não do Bacen no mercado monetário."},"145":{"a":"'Mercado fornecedor' não é uma categoria do SFN.","b":"O mercado de capitais negocia títulos e valores mobiliários. Não é nele que se intermedeiam recursos para consumo ou capital de giro.","c":"O mercado de derivativos negocia contratos cujo valor depende de outro ativo. Não é onde se empresta para consumo ou capital de giro."},"146":{"b":"A primeira afirmação é verdadeira: o mercado de câmbio negocia trocas de moeda estrangeira por reais. Marcar F nela torna a sequência errada.","c":"A terceira afirmação é falsa, porque coibir fraudes com valores mobiliários é função da CVM. A quarta é verdadeira, mas a sequência V, F, V, F erra a terceira.","d":"A primeira afirmação é verdadeira, e a terceira é falsa, porque coibir fraudes com valores mobiliários é da CVM. A sequência F, F, V, V erra as duas."},"147":{"a":"O mercado cambial trata de câmbio. Não é onde se capitalizam empresas por meio de títulos e valores mobiliários em bolsa e balcão.","b":"'Mercado de mutualização' não é um mercado do SFN. O balcão existe, mas não define sozinho essas operações.","c":"O mercado interbancário é o empréstimo entre bancos, de curto prazo. Não serve à capitalização de empresas de capital aberto."},"148":{"a":"O Banco Central regula o sistema bancário e o câmbio. A regulação do mercado de capitais não é sua função principal.","c":"O CNSP regula seguros, previdência aberta e capitalização, e não o mercado de capitais.","d":"O COAF combate a lavagem de dinheiro. Não controla, normatiza nem fiscaliza o mercado de capitais."},"149":{"a":"Inclui o item I, que está errado: o preço do derivativo depende das expectativas sobre o comportamento futuro, e não do passado.","c":"Inclui o item IV, que está errado: o ativo subjacente pode ser concreto (ações, moedas, juros) ou abstrato, e não exclusivamente abstrato.","d":"Inclui o item IV, que está errado, e cita um item V que não faz parte desta questão."},"150":{"a":"Inclui o item II, que está errado: o CMN não tem como objetivo estimular o mercado acionário.","b":"Inclui os itens III e IV, que não são funções do CMN. O item III é da CVM, e o item IV não é atribuição do CMN.","d":"Inclui os itens II, III e IV, que não são funções do CMN. Apenas o item I descreve corretamente o CMN."},"151":{"b":"Estabelecer a política cambial é função do CMN e do Bacen, e não da CVM.","c":"Fixar taxas e emolumentos não é competência geral da CVM.","d":"Operar o mercado de balcão é atribuição da B3 e de suas regras, e não da CVM."},"152":{"a":"Prestação de serviço comunitário não é penalidade administrativa prevista para quem descumpre normas do mercado de valores mobiliários.","b":"O CPF não é cancelado como sanção. Ele é um cadastro de pessoa física, e não uma penalidade.","d":"O CNPJ não é bloqueado como sanção. Ele é o cadastro da pessoa jurídica."},"153":{"a":"A Secretaria Política não preside o Conselho Nacional de Previdência Complementar.","c":"O Banco Central não preside o CNPC. A previdência complementar fechada tem outra estrutura de presidência.","d":"O Coaf combate a lavagem de dinheiro e não preside o CNPC."},"154":{"a":"A primeira afirmação é falsa: o CRSFN é órgão de recurso administrativo, e não entidade supervisora.","b":"A segunda afirmação é falsa, porque o CRSFN não é órgão normativo. Além disso, a terceira é verdadeira, e não falsa.","c":"A terceira afirmação é verdadeira, e não falsa. A segunda também é falsa, porque o CRSFN não é normativo."},"155":{"a":"A asserção I é falsa: o CMN é órgão normativo e não tem função fiscalizadora. Por isso não pode ser verdadeira.","b":"A asserção I é falsa, então não pode ser verdadeira. A asserção II também é falsa.","c":"A asserção II é falsa, porque o CMN não fiscaliza. A supervisão é feita pelo Bacen e pela CVM."},"156":{"a":"Bolsa de valores negocia ativos. Ela não conduz a política monetária.","c":"Administradoras de cartão de crédito não têm papel na condução da política monetária.","d":"O CMN fixa diretrizes, mas quem conduz a política monetária no dia a dia é o Bacen, pelo Copom e por seus instrumentos."},"157":{"a":"O Bacen regula bancos e o sistema de pagamentos, não seguros nem previdência aberta.","b":"A CVM regula valores mobiliários, e não seguros.","c":"A Previc supervisiona a previdência fechada (fundos de pensão), e não a previdência aberta, a capitalização e os seguros."},"158":{"b":"Operadoras não desenvolvem atividades dos órgãos normativos. Elas captam, aplicam e intermediam recursos.","c":"Fiscalizar seguradoras e corretoras é papel da Susep e da CVM, e não das instituições operadoras.","d":"Regular crédito e investimento é função dos órgãos normativos e executores, e não das instituições operadoras."},"159":{"a":"Inclui o item I, que está errado: bancos comerciais são regulados e fiscalizados pelo Bacen, e não pela CVM.","b":"Inclui o item III, que está errado: bancos comerciais podem ser públicos ou privados.","c":"Inclui o item III, que está errado. O item IV está certo, mas não basta para validar a alternativa."},"160":{"a":"Cobre só o curto prazo. Os bancos comerciais atuam também no médio prazo.","b":"Cobre só o médio prazo. Falta o curto prazo, que também faz parte da atuação.","c":"O longo prazo é característica dos bancos de investimento e de desenvolvimento, e não dos bancos comerciais."},"161":{"a":"A asserção I não é verdadeira. As caixas econômicas são empresas públicas que atuam, em parte, como bancos comerciais, com depósitos, crédito e serviços.","b":"A asserção I é falsa, então a afirmação de que a II é falsa não basta para validar a opção.","c":"A asserção II é falsa: há vários pontos em comum com os bancos comerciais, como captação de depósitos e serviços bancários."},"162":{"a":"Inclui o item I, que está errado: os cooperados são donos e usuários ao mesmo tempo. Não há separação entre quem usufrui e quem gere.","c":"Inclui o item IV, que está errado: os bancos cooperativos seguem a legislação dos bancos comerciais e dos múltiplos, e não só dos múltiplos.","d":"Inclui o item I (errado) e o item IV (errado)."},"163":{"b":"O item II está errado: o banco de investimento capta por depósito a prazo, e não recebe depósito à vista. O item III também está errado, porque é regulado pelo Bacen, e não pelo CMN.","c":"Inclui o item III, que está errado: a regulação é do Bacen, e não do CMN. O item IV está certo, mas não basta.","d":"Inclui o item II, que está errado, e o item III, que também está errado."},"164":{"a":"Crédito imobiliário não é a carteira obrigatória. A obrigatória é a comercial ou a de investimento.","b":"Carteira de desenvolvimento não é a obrigatória. Ela é típica de bancos públicos.","d":"Não existe carteira de 'crédito financeiro'. A obrigatória é a comercial ou a de investimento."},"165":{"a":"Inclui o item I, que está errado: não existe investimento totalmente seguro, pois todo investimento envolve algum risco.","b":"Inclui o item I, que está errado, então esta combinação não pode ser a correta.","d":"Deixa de fora o item II. A apostila divide os participantes em quem normatiza e quem operacionaliza, então a afirmação II também está correta."},"166":{"a":"Burocráticas e técnicas não são subdivisões do SFN.","c":"Estratégicas não é subdivisão do sistema. As subdivisões são normativas, supervisoras e operacionais.","d":"Executoras e dirigentes não são as subdivisões do SFN. As categorias são normativas, supervisoras e operacionais."},"167":{"a":"O item II está errado: o Bacen não tem a principal competência de regular o SFN, que é do CMN. Além disso, a emissão de papel-moeda é do Bacen, e não do CMN.","c":"Inclui o item II, que está errado.","d":"Inclui o item II, que está errado, e o item I, que está certo, mas não basta."},"168":{"a":"Essa descrição é de bancos comerciais, e não do BNDES.","c":"Capital fixo, capital de giro e depósitos a prazo são operações de bancos comerciais e de investimento, e não o objetivo principal do BNDES.","d":"Compra e venda de moeda estrangeira é operação de câmbio, e não o objetivo do BNDES."},"169":{"b":"A política cambial é função do CMN e do Bacen, e não da CVM.","c":"Fixar limites de emolumentos e comissões não é regra geral da CVM.","d":"Autorizar o funcionamento de instituições financeiras é função do Bacen."},"170":{"a":"Sociedade seguradora é classificação de seguros, e não de previdência fechada.","b":"Investidor não residente é quem tem sede ou domicílio no exterior. Não é a classificação dessa entidade.","c":"Instituição financeira não é a classificação da entidade fechada de previdência. A apostila a trata como investidor profissional."},"171":{"a":"Está correta: negociação e intermediação de valores mobiliários são fiscalizadas pela CVM. Por isso não é a alternativa incorreta.","b":"Está correta: a CVM fiscaliza as companhias abertas, com prioridade às que não lucram ou não pagam o dividendo mínimo.","d":"Está correta: emissão e distribuição de valores mobiliários são fiscalizadas pela CVM."},"172":{"a":"Treinamentos de profissionais não são competência da Susep.","b":"Criar normas de seguro é competência do CNSP. A Susep apenas cumpre essas normas.","c":"A comercialização de apólices é feita pelas seguradoras e corretoras, e não é competência da Susep."},"173":{"b":"Registro na Anbima não é a obrigação prévia descrita nesta questão.","c":"O representante pessoa física ou jurídica não financeira precisa de instituição autorizada pela CVM, mas a obrigação principal descrita é constituir representantes.","d":"Registro no Banco Central não é a obrigação prévia descrita nesta questão."},"174":{"b":"Eurobonds são instrumentos de captação, e não a atribuição de financiamento das financeiras.","c":"Debêntures são instrumentos de captação de empresas, e não a atribuição das financeiras.","d":"Financiar o comércio e a indústria em geral é função mais ampla dos bancos comerciais."},"175":{"a":"Fiscalizar valores mobiliários é atribuição da CVM, e não do Bacen.","c":"A apostila atribui ao Bacen a fiscalização das instituições financeiras, e não a fiscalização do mercado aberto de títulos.","d":"O Bacen é autarquia federal, e não banco privado."},"176":{"a":"A CVM regula o mercado de valores mobiliários e não determina as metas de inflação.","b":"O Bacen implementa a política monetária, mas não define originalmente as metas de inflação.","c":"O Comitê de Política Monetária executa a política, mas não determina originalmente as metas."},"177":{"a":"Essa definição confunde o investidor não residente com quem aplica no exterior, o que não corresponde à definição.","b":"O critério de residência fixa não define o investidor não residente. O critério é a sede ou o domicílio no exterior.","d":"Descreve o investidor residente que aplica no exterior, o oposto do investidor não residente."},"178":{"a":"Distribuição de títulos é função de outras instituições, e não a principal função da corretora.","c":"Aproximar emissoras de títulos e mercadorias não é a função principal da corretora, que aproxima compradores e vendedores.","d":"O pregão em recinto da bolsa não é a função principal da corretora, que aproxima compradores e vendedores."},"179":{"a":"Ser regulada e fiscalizada só pelo Bacen deixa a afirmação incompleta, porque a supervisão é conjunta.","b":"Ser regulada e fiscalizada só pela CVM deixa a afirmação incompleta, porque a supervisão é conjunta.","d":"A corretora é instituição financeira, e não não financeira."},"180":{"a":"A CVM é órgão executor, e não o órgão regulamentar do SFN.","b":"A Previc é órgão executor. Ela supervisiona a previdência fechada, mas não é órgão normativo.","d":"O Bacen é órgão executor, e não órgão de caráter regulamentar."},"181":{"a":"A emissão de títulos públicos é do Tesouro Nacional, e não do Bacen.","c":"A aprovação de orçamentos monetários é do CMN, e não exclusiva do Bacen.","d":"A fixação das diretrizes da política cambial é do CMN, e não do Bacen."},"182":{"a":"A execução da política cambial é do Bacen, e não do CMN.","c":"A fiscalização do mercado de capitais é da CVM, e não do CMN.","d":"A fiscalização do mercado de crédito é do Bacen, e não do CMN."},"183":{"a":"O prazo de guarda previsto na apostila é de cinco anos. Essa é a regra do texto, mas o gabarito oficial indica a alternativa B, o que é uma divergência a conferir.","c":"Não identificar os clientes contraria a exigência de identificação do cliente.","d":"Um prazo máximo de dez anos não corresponde ao mínimo exigido."},"184":{"a":"Inclui o CMN, que é órgão normativo, e não executor.","c":"Inclui o CNSP, que é normativo, e o Coaf, que combate a lavagem de dinheiro e não é executor do SFN.","d":"Inclui o Ministério da Economia e o CNSP, que é normativo. Falta o Bacen, que é executor."},"185":{"a":"O Bacen executa a política monetária e o sistema de pagamentos. Ele não emite títulos da União.","b":"O CMN é órgão normativo, e não emite títulos públicos federais.","c":"A CVM regula o mercado de valores mobiliários. Não emite títulos públicos federais."},"186":{"b":"O Bacen executa a política monetária. Não administra a dívida pública da União.","c":"O CMN é órgão normativo, e não administra a dívida pública.","d":"A CVM regula o mercado de valores mobiliários. Não administra a dívida da União."},"187":{"b":"Um sistema sistemicamente importante deve assumir a posição de contraparte central. Dispensar essa posição contraria a regra.","c":"Dispensar a posição de contraparte central contraria a exigência para sistemas sistemicamente importantes.","d":"Deixar as garantias sem níveis mínimos ou máximos contraria a exigência de mecanismos e salvaguardas."},"188":{"a":"A emissão de papel-moeda é atribuição do Bacen. A apostila indica que a autorização do CMN para isso foi vetada.","b":"Autorizar o funcionamento de instituições financeiras também é atribuição do Bacen. Porém, pelo gabarito, a função correta desta questão é o redesconto.","c":"Coordenar a política monetária é atribuição do CMN. O Bacen formula e executa essa política."},"189":{"a":"A fiscalização das instituições financeiras é do Bacen, e não do CMN.","b":"A autorização para bancos estrangeiros funcionarem no Brasil é do Bacen, e não do CMN.","c":"As operações de redesconto são do Bacen, e não do CMN."},"190":{"a":"Fiscalizar instituições do ramo bancário é do Bacen, e não da CVM.","b":"As diretrizes do mercado de câmbio são do CMN, e não da CVM.","d":"Estimular a caderneta de poupança não é função da CVM. Ela estimula a aplicação em valores mobiliários."},"191":{"a":"O SPB não serve às transferências entre bancos de um mesmo conglomerado. Essa não é a definição do sistema.","b":"DOC para valores acima de R$ 5 mil não é a definição do SPB.","d":"Gerenciar o risco de crédito e custodiar CDBs não definem o SPB."},"192":{"a":"Quem define a meta de inflação é o CMN. O Copom integra o Bacen, mas não define essa meta.","c":"Estimular a poupança é função da CVM, e não do Bacen.","d":"O Bacen fiscaliza as instituições financeiras. Fiscalizar não financeiras que gerem recursos de terceiros não é a função descrita."},"193":{"a":"A Susep é supervisora e executora. Ela cumpre as diretrizes, mas não as define.","c":"O CMN é o órgão normativo do SFN, mas não define as diretrizes de seguros, capitalização e previdência.","d":"A CVM regula o mercado de valores mobiliários, e não seguros."},"194":{"a":"O Copom decide a taxa de juros. Não recebe depósitos compulsórios.","c":"O CMN fixa diretrizes. Não recebe depósitos compulsórios.","d":"A instituição financeira apenas recolhe o valor ao Bacen. Quem recebe é o Bacen."},"195":{"a":"Sociedades de economia mista privadas não são o alvo da fiscalização descrita.","c":"Mercado primário não é tipo de sociedade. É a etapa de emissão de títulos.","d":"Sociedades limitadas não negociam ações em bolsa, e não são o alvo da fiscalização descrita."},"196":{"b":"Instituições financeiras, cooperativas e centrais depositárias são participantes, mas não definem o conjunto do SPB.","c":"Sistemas do governo para tributos não são a definição do SPB.","d":"A liquidação de câmbio é só uma parte dos sistemas. Não é a definição completa."},"197":{"a":"O CNSP cuida de seguros, e não dos fundos de pensão.","c":"O CMN é o órgão normativo máximo, mas não define as diretrizes dos fundos de pensão.","d":"A Previc fiscaliza e supervisiona as entidades de previdência fechada, mas não define as diretrizes."},"198":{"a":"O CNSP é órgão de seguros, e não o órgão máximo do SFN.","b":"O Bacen é órgão executor, e não o órgão máximo.","d":"O Tesouro Nacional administra a dívida pública. Não é o órgão máximo do SFN."},"199":{"a":"O Cetip faz parte do SPB, pelos sistemas de registro, compensação, liquidação e custódia.","c":"O STR (Sistema de Transferência de Reservas) faz parte do SPB.","d":"O Selic (Sistema Especial de Liquidação e Custódia) faz parte do SPB."},"200":{"a":"A CVM regula o mercado de valores mobiliários. Não autoriza cooperativas de crédito.","b":"O CMN é órgão normativo e não concede autorizações individuais.","c":"A Susep regula seguros e não autoriza cooperativas de crédito."},"201":{"b":"Câmbio não é carteira típica do banco múltiplo. A carteira que pode acompanhar a comercial é a de crédito imobiliário.","c":"Câmbio não é carteira do banco múltiplo. Financiamento imobiliário pode ser, mas a alternativa mistura um item que não é carteira.","d":"A carteira de desenvolvimento é típica de bancos públicos, e não de bancos privados."},"202":{"a":"Financeiras são instituições não bancárias. Dizer que são bancárias está errado.","b":"Financeiras não são bancárias. A combinação 'bancárias' está errada.","c":"Financeiras concedem crédito, mas 'capital social' não é a característica principal que a questão pede. A característica é o capital de giro."},"203":{"a":"Inclui apenas o item II. O item III também é atividade da SCTVM, pois ela pode administrar fundos de investimento.","b":"Inclui o item I, que está errado: conceder financiamento imobiliário não é atividade da SCTVM.","d":"Inclui o item I, que não é atividade da SCTVM."},"204":{"a":"Administrar fundos é atribuição de carteira de investimento, que este banco não tem.","b":"Pela carteira comercial, o banco pode captar por depósito à vista. Negar essa possibilidade está errado.","d":"Crédito imobiliário não faz parte dessa combinação de carteiras."},"205":{"b":"Banco comercial não coordena abertura de capital (IPO).","c":"O banco múltiplo só coordena esse tipo de operação se tiver carteira de investimento.","d":"A CVM regula o mercado, mas não coordena a operação de abertura de capital."},"206":{"b":"A SCTVM pode administrar clubes de investimento.","c":"A SCTVM pode administrar fundos de investimento.","d":"A SCTVM pode realizar operações de câmbio."},"207":{"a":"A afirmação é verdadeira, mas incompleta. A alternativa correta traz a função mais específica do BNDES como instrumento do governo.","b":"O BNDES é empresa pública, não sociedade de economia mista com ações negociadas em bolsa.","c":"O principal fomentador do mercado imobiliário não é o BNDES."},"208":{"b":"O banco múltiplo só capta à vista se tiver carteira comercial. Por isso não é a resposta mais direta.","c":"O banco de desenvolvimento não capta por depósito à vista.","d":"As financeiras não captam por depósito à vista."},"209":{"b":"Crédito e financiamento é carteira facultativa, e não obrigatória.","c":"Crédito imobiliário é carteira facultativa, e não obrigatória.","d":"Desenvolvimento é carteira facultativa, e não obrigatória."},"210":{"a":"Crédito de curto prazo e cheque especial são do banco comercial, e não do banco de investimento.","b":"Dólar turismo é operação de câmbio, e não atividade típica do banco de investimento.","c":"Fiscalizar o mercado de distribuição de valores mobiliários é papel da CVM."},"211":{"a":"Crédito imobiliário não é atribuição do banco comercial.","b":"Pelo menos duas carteiras é exigência do banco múltiplo, e não do banco comercial.","c":"Administrar fundos de investimento é atribuição do banco de investimento."},"212":{"a":"30 não é o número mínimo de cooperados exigido.","b":"3 não é o número mínimo de cooperados exigido.","d":"50 não é o número mínimo de cooperados exigido."},"213":{"a":"Deixa de fora o item II, que também pode conceder crédito imobiliário.","c":"Inclui o item III, que está errado: o banco comercial, em regra, não concede crédito imobiliário.","d":"Inclui o item III, que está errado."}};Object.keys(WHY5).forEach(function(k){WHY[k]=WHY[k]||{};Object.keys(WHY5[k]).forEach(function(l){WHY[k][l]=WHY5[k][l]})});
